-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["subzone:sandsorrow-watch"] = {n="Sandmarterwache",s="Die Sandmarterwache ist ein weitläufiger Wüstenaußenposten direkt westlich von Gadgetzan in Tanaris. Die umliegenden Dünen und Ruinen werden von feindseligen Sandfury-Trollen und ihren wiedererweckten Toten überrannt, die auch den östlichen Wachturm mit Blick auf die Ödnis halten.",h="Die Sandmarterwache ist ein weitläufiger Wüstenaußenposten direkt westlich von Gadgetzan in Tanaris.",kw={"gadgetzan","sandtroll","sandfury","sandmarterwache","tanaris"},ang={["profession:Blacksmithing"]="Am von den Sandfury gehaltenen Wachturm arbeitet kein Schmied; Wüstenschmiede versammeln sich stattdessen hinter den Mauern von Gadgetzan, direkt im Osten.",["race:Troll"]="Dunkelspeertrolle werden hier keine Verbundenheit finden: Der feindselige Stamm der Sandfury betrachtet alle Außenseiter als Eindringlinge, die zerschmettert und als schlurfende Leichen wiedererweckt werden müssen."},sec={{t="Ein gefährlicher Posten",b="Direkt westlich des geschäftigen Goblin-Handelszentrums Gadgetzan gelegen, ist die Sandmarterwache ein düsteres Grenzland in der Wüste von Tanaris. Das weite Areal wird vom Stamm der Sandfury beherrscht, der das karge Territorium an der Seite von Legionen schlurfender Trollzombies aggressiv verteidigt. Ein erhöhter Wachturm am östlichen Rand verankert die Stellung und bietet einen befestigten Aussichtspunkt inmitten der vordringenden Wüstenwildnis und der feindseligen einheimischen Stämme."},{t="Grenzaußenposten",b="Selbst der Wachturm am östlichen Rand, in Sichtweite der Mauern von Gadgetzan, wird von den Sandfury gehalten. Von seinen Höhen aus behalten die Sandfury die Goblinstadt misstrauisch im Auge, und Reisende, die Gadgetzan durch das Westtor verlassen, betreten fast direkt ihr Territorium – eine ständige Erinnerung an die explosive Grenzspannung zwischen den opportunistischen Siedlern von Tanaris und den einheimischen Sandtrollen."}},faq={{q="Wo befindet sich die Sandmarterwache?",a="Die Sandmarterwache befindet sich direkt westlich von Gadgetzan in den nördlichen Wüstenebenen von Tanaris. Reisende, die durch Gadgetzans Westtor aufbrechen, stoßen fast unmittelbar auf sie.",al={"lage der sandmarterwache","wo ist sandmarterwache","weg zur sandmarterwache"}},{q="Wer kontrolliert die Sandmarterwache?",a="Die Ruinen, die umliegenden Dünen und der östliche Wachturm sind allesamt von feindseligen Sandfury-Trollen und ihren untoten Dienern besetzt.",al={"wer lebt an der sandmarterwache","fraktion der sandmarterwache","wer kontrolliert die sandmarterwache"}},{q="Warum gibt es an der Sandmarterwache untote Trolle?",a="Der Stamm der Sandfury praktiziert finstere nekromantische Künste sowie Voodoo und erweckt häufig gefallene Krieger der Sandfury als Sandfury-Zombies wieder, um ihr trostloses Territorium und ihre Außenposten in ganz Tanaris zu bewachen.",al={"sandfury zombies","warum trollzombies tanaris","sandmarterwache zombies"}},{q="Welche Gefahren erwarten Abenteurer in den umliegenden Dünen?",a="Das Gebiet wird schwer von Sandfury-Axtwerfern, -Feuerrufern und -Häutern sowie ihren wiedererweckten Trollzombies patrouilliert. Unvorbereitete Reisende, die sich westlich von Gadgetzan vom Hauptweg entfernen, können leicht von umherstreifenden Kriegstrupps der Sandfury überwältigt werden.",al={"sandmarterwache mobs","feinde der sandmarterwache","feindliche trolle sandmarterwache"}}},fp="16,248,18.453.0,16.387.0,34.189.0,30.130.0,48.189.0,61.250.0"}
P.entries["subzone:sardor-isle"] = {n="Insel Sardor",s="Die Insel Sardor ist eine üppig bewachsene Insel vor der Westküste von Feralas, nördlich der gefährlichen Insel des Schreckens. Sie dient als Heimat der Mondfederfeste, der primären militärischen Bastion der Nachtelfen im südlichen Kalimdor. Trotz der starken Präsenz der Schildwachen durchstreifen weiterhin wilde Bestien Teile der Insel, während feindselige Naga aus den Untiefen emporsteigen.",h="Die Insel Sardor ist eine üppig bewachsene Insel vor der Westküste von Feralas, nördlich der gefährlichen...",kw={"mondfederfeste","feralas","die insel des schreckens","naga","insel sardor","schildwachen","shandris mondfeder"},ang={["faction:Alliance"]="Die Insel Sardor ist der wichtigste Machtstützpunkt der Allianz in Feralas und bietet einen sicheren Hafen, Vorräte und Flugmeister innerhalb der Mondfederfeste.",["race:NightElf"]="Unter Generalin Shandris Mondfeder behalten die Schildwachen auf der Insel Sardor die uralten Ruinen und aufkeimenden Naga-Bedrohungen in ganz Feralas genau im Auge."},sec={{t="Bastion der Schildwachen und wilde Küsten",b="Die Insel Sardor liegt jenseits des Wassers vor dem Festland von Feralas und wird von der Mondfederfeste geprägt, einer eindrucksvollen elfischen Garnison unter dem Befehl von Generalin Shandris Mondfeder. Während die Festung selbst schwer befestigt und über regelmäßige Fährüberfahrten mit dem Festland verbunden ist, ist der Rest der Insel alles andere als zahm. Umherstreifende Wolfsrudel beanspruchen die bewaldeten Hänge für sich, während vordringende Naga an den felsigen westlichen und nördlichen Stränden lauern und die Entschlossenheit der Nachtelfenschildwachen unablässig auf die Probe stellen."}},faq={{q="Wo liegt die Insel Sardor?",a="Die Insel Sardor liegt vor der Westküste von Feralas im südlichen Kalimdor, direkt nördlich der Insel des Schreckens. Sie kann mit einem Boot erreicht werden, das von der vergessenen Küste auf dem Festland ablegt.",al={"insel sardor lage","wo liegt sardor","insel sardor finden"}},{q="Was ist die Hauptsiedlung auf der Insel Sardor?",a="Die Insel wird von der Mondfederfeste dominiert, der primären Festung und dem Aufmarschgebiet der Nachtelfen und der Allianz in Feralas, kommandiert von Generalin Shandris Mondfeder.",al={"wer lebt auf der insel sardor","insel sardor stadt","nachtelfenbasis sardor"}},{q="Welche Bedrohungen gibt es auf der Insel außerhalb der Festung?",a="Außerhalb der schützenden Mauern der Mondfederfeste treffen Reisende auf Rudel wilder Wölfe, die durch die Wälder streifen, sowie auf feindselige Naga, die an den Küstenriffen und Stränden lauern.",al={"insel sardor feinde","gefahr auf der insel sardor","monster sardor"}},{q="Wie unterscheidet sich die Insel Sardor von der Insel des Schreckens?",a="Die Insel Sardor liegt im Norden und ist stark von den Nachtelfen der Mondfederfeste besetzt. Die Insel des Schreckens liegt weiter südlich und ist ein weitaus raueres, ungezähmtes Gebiet, in dem es von gefährlichen Chimären und Naga wimmelt.",al={"insel sardor vs die insel des schreckens","unterschied zur insel des schreckens"}}},fp="11,355,32.491.0,29.184.0,43.181.0,60.181.0,51.221.0"}
P.entries["subzone:sargeron"] = {n="Sargeron",s="Sargeron ist die verfallene Ruine einer uralten Stadt der Nachtelfen im nördlichen Desolace. Während der Großen Zerschlagung zerstört, wurden ihre einstigen Tempel der Elune von den Satyrn der Hatefury entweiht und beansprucht, die das Gelände zu Ehren ihres Meisters Sargeras umbenannten.",h="Sargeron ist die verfallene Ruine einer uralten Stadt der Nachtelfen im nördlichen Desolace.",kw={"cup of elune","desolace","elune","hatefury","kaldorei","sargeras","sargeron","satyr"},ang={["class:Priest"]="Priesterinnen des Mondes werden Überreste von Elune's Cathedral und heilige Relikte erkennen, die über die zerbrochenen Steine verstreut liegen und nach Reinigung verlangen.",["race:NightElf"]="Die Ruinen sind ein schmerzhafter Anblick für jeden Kaldorei, da heilige Altäre von Elune offen von dämonischen Satyrn entweiht werden, die die Göttin im Namen von Sargeras verhöhnen."},sec={{t="Ein entweihtes Heiligtum",b="Bevor der Krieg der Ahnen den Kontinent zerriss, war diese Siedlung ein blühendes Zentrum der Verehrung Elunes, das heilige Stätten wie Elune's Temple, Sanctuary und Cathedral beherbergte. Ihr wahrer Name ging in den Tiefen der Geschichte verloren. Als die Welt zerbrach, fiel die Stadt in Trümmer und hinterließ geheiligte Relikte wie Cup of Elune, Elune's Brazier und Elune's Handmaiden. In den Jahrtausenden seither überrannten die verderbten Satyrn der Hatefury die Steine und wandelten die heilige Architektur der Kaldorei in eine Festung um, die den Titanen Sargeras ehrt."}},faq={{q="Wie hieß Sargeron vor der Zerschlagung?",a="Sein ursprünglicher nachtelfischer Name ging im Laufe der Zeit verloren. Der heutige Name, Sargeron, wurde den Ruinen von den Satyrn der Hatefury als Hommage an den gefallenen Titanen Sargeras verliehen.",al={"ursprünglicher name","sargeron ursprünglicher name","wie hieß es früher"}},{q="Wer besetzt Sargeron heute?",a="Die Ruinen werden von den Satyrn der Hatefury besetzt, verderbten dämonischen Wesen, die während des Kriegs der Ahnen entstanden und die uralten Stätten der Nachtelfen aktiv entweihen.",al={"wer lebt hier","sargeron gegner","feinde in sargeron"}},{q="Welche heiligen Stätten befanden sich ursprünglich hier?",a="Die Stadt beherbergte mehrere bedeutende, der Mondgöttin geweihte Stätten, darunter Elune's Temple, Elune's Sanctuary und Elune's Cathedral, die einst verehrte Relikte wie Cup of Elune beherbergten.",al={"elune tempel","heilige stätten","welche gebäude standen hier"}},{q="Warum ist Sargeron für Nachtelfen von Bedeutung?",a="Es dient als düstere Mahnung an den Krieg der Ahnen und die Entweihung heiliger Stätten der Kaldorei durch dämonische Mächte, während alte elfische Artefakte dort von Verlust oder Verderbnis bedroht sind.",al={"nachtelfen lore sargeron","warum ist es den nachtelfen wichtig"}}},fp="8,270,19.549.0,46.166.0,26.156.0,45.192.0,43.186.0"}
P.entries["subzone:satyrnaar"] = {n="Satyrnaar",s="Satyrnaar ist eine uralte, verfallene Nachtelfensiedlung im nordöstlichen Eschental, die vollkommen in die Hände der Satyrn der Bleakheart gefallen ist. Sie liegt knapp abseits der Hauptstraße zwischen dem Splitterholzposten und Azshara und ist die besterhaltene und am leichtesten zugängliche der Satyrfestungen im Wald.",h="Satyrnaar ist eine uralte, verfallene Nachtelfensiedlung im nordöstlichen Eschental, die vollkommen in die...",kw={"eschental","bleakheart","dark strand","forest song","satyr","satyrnaar","seelenstein","splintertree"},ang={["class:Druid"]="Die verheerende Teufelsverderbnis, die von den Bleakheart-Satyrn verbreitet wird, erstickt unaufhörlich den natürlichen Geist von Eschental und verlangt nach rascher Läuterung.",["race:NightElf"]="Das uralte Mauerwerk der Ahnen durch Teufelsverderbnis geschändet und von den verfluchten Überresten der Hochgeborenen bewohnt zu sehen, ist für jeden Nachtelfen, der Eschental durchquert, eine bittere Kränkung."},sec={{t="Eine Höhle voller Teufelsmagie und Schatten",b="Nordöstlich des Splitterholzpostens und südwestlich von Forest Song gelegen, ist Satyrnaar neben Xavian und Nachtflucht eine der drei wichtigsten Satyrsiedlungen in Eschental. Im Gegensatz zu den Ruinen tiefer in der Wildnis ist Satyrnaar verhältnismäßig gut erhalten und weist zwischen zerfallener elfischer Architektur aufgeschlagene Zelte auf. Es dient den Bleakheart-Satyrn als belebtes Lager, was die nahe gelegene Handelsroute für Reisende in Richtung Azshara überaus gefährlich macht. Darüber hinaus schwelen hier finstere Verbindungen: Die Satyrn sind ein Bündnis mit dem schattenhaften Cult of the Dark Strand eingegangen und hüten inmitten der verdorbenen Steine einen ihrer heimtückischen Seelensteine."}},faq={{q="Was ist Satyrnaar?",a="Satyrnaar ist eine verfallene Stätte der Nachtelfen im nordöstlichen Eschental, die von den Bleakheart-Satyrn beansprucht und besetzt wurde. Es dient als eine ihrer wichtigsten Hochburgen in der Region.",al={"satyrnaar übersicht","was ist dieser ort","satyr-lager"}},{q="Wer lebt in Satyrnaar?",a="Die Siedlung wird vom Stamm der Bleakheart-Satyrn beherrscht. Sie haben zwischen den alten Ruinen Zelte errichtet und arbeiten mit dem Cult of the Dark Strand zusammen.",al={"wer ist hier","satyrnaar gegner","bleakheart-satyrn"}},{q="Warum ist Satyrnaar im Vergleich zu anderen Satyrruinen von Bedeutung?",a="Von den drei großen Satyrstätten in Eschental – Satyrnaar, Nachtflucht und Xavian – ist Satyrnaar die besterhaltene und liegt am zentralsten, direkt an der Straße nach Azshara.",al={"satyrnaar vs xavian","warum satyrnaar"}},{q="Welches finstere Artefakt ist in Satyrnaar verborgen?",a="In Satyrnaar befindet sich einer der verdorbenen Seelensteine des Cult of the Dark Strand, eines sterblichen Schattenkults, der mit den Bleakheart-Satyrn verbündet ist.",al={"dark strand seelenstein","satyrnaar kristall","seelenstein"}}},fx={["2ba518f9"]={q="Ist Satyrnaar gefährlich?",a="Satyrnaar ist extrem gefährlich für Reisende, die durch das nordöstliche Eschental ziehen. Es liegt direkt an der Hauptstraße zwischen Splitterholzposten und Azshara und wird von den bösartigen Bleakheart-Satyrn bewohnt, die mit dem Cult of the Dark Strand verbündet sind. Aufgrund seiner zugänglichen, zentralen Lage ist es das am stärksten umkämpfte und am gewaltsamsten verteidigte aller Satyr-Gebiete im Wald. Eindringlinge riskieren, auf Teufelsmagie, Hinterhalte und finstere Schattenrituale zu stoßen, die sich um korrumpierte Seelenedelsteine drehen.",al={"ist satyrnaar sicher","wie gefährlich ist satyrnaar","satyrnaar bedrohung"}}},fp="9,298,23.645.0,18.184.0,23.158.0,59.172.0,46.144.0"}
P.entries["subzone:savage-coast"] = {n="Die ungezähmte Küste",s="Die ungezähmte Küste ist die zerklüftete Westküste des nördlichen Schlingendorntals, die sich von der südlichen Grenze von Westfall hinab in Richtung des Basislagers von Grom'gol erstreckt. Von Flusskrokilisken, Uferbasilisken und feindseligen Trollstämmen heimgesucht, verdient sich dieser Strand seinen brutalen Namen mit jeder Flut.",h="Die ungezähmte Küste ist die zerklüftete Westküste des nördlichen Schlingendorntals, die sich von der...",kw={"basilisk","krokilisk","grom'gol","die ungezähmte küste","schlingendorntal","das finstere riff","westfall"},ang={["class:Hunter"]="Die Strände bieten eine Fülle an Krokilisken und Basilisken zum Aufspüren, Kürschnern und Zähmen entlang der Uferlinie.",["faction:Horde"]="Der nördliche Abschnitt der Küste liegt knapp oberhalb des Basislagers von Grom'gol und dient als Schutzpuffer gegen Wildtiere und aggressive Trollbanden nahe dem großen Meer."},sec={{t="Ein tückischer Strand",b="Von den Klippen an der Grenze zu Westfall südwärts in Richtung des Basislagers von Grom'gol verlaufend, markiert die ungezähmte Küste den gefährlichen westlichen Rand des nördlichen Schlingendorntals. Die sandigen Ufer bieten wenig Gastfreundschaft: Schnappkiefer, Krokilisken und Steinpirscher streifen frei zwischen den Gezeitentümpeln und dem Treibholz umher. Nur ein Stück landeinwärts liegen die Lager territoriumsbewusster Dschungeltrolle, was jeden beiläufigen Strandspaziergang zu einem Kampf ums Überleben macht. Vor der Küste fällt das Wasser in Richtung der versunkenen Gefahren des finsteren Riffs ab, sodass sowohl auf dem Sand als auch unter den Wellen Gefahr lauert."}},faq={{q="Wo liegt die ungezähmte Küste?",a="Die ungezähmte Küste säumt den westlichen Meeresrand des nördlichen Schlingendorntals. Sie beginnt nahe der Grenze zu Westfall im Norden und erstreckt sich südwärts vorbei an den Gewässern nahe dem finsteren Riff bis hinab zum Basislager von Grom'gol.",al={"ungezähmte küste ort","wo ist die ungezähmte küste","ungezähmte küste karte"}},{q="Welche Kreaturen leben an der ungezähmten Küste?",a="Das Ufer wird von gefährlichen Wildtieren überrannt, vor allem von aggressiven Krokilisken und Basilisken, die sich im Sand sonnen. Gleich hinter der Wasserlinie und entlang der nahen Klippen des Dschungels halten feindselige Trollstämme Lager mit Blick auf die Brandung besetzt.",al={"ungezähmte küste mobs","was gibt es an der ungezähmten küste","ungezähmte küste bestien"}},{q="Ist die ungezähmte Küste für Reisende sicher, die von Westfall nach Süden ziehen?",a="Ganz und gar nicht. Auch wenn das Betreten des Schlingendorntals entlang der Küste das dichte Blätterdach umgeht, ist die ungezähmte Küste voller bösartiger amphibischer Raubtiere und einheimischer Trollkrieger, die unvorsichtige Reisende schnell überwältigen.",al={"kann man von westfall ins schlingendorntal laufen","pfad von westfall zur ungezähmten küste"}},{q="Welche Orientierungspunkte liegen nahe der ungezähmten Küste?",a="Direkt vor der Küste liegt das versunkene finstere Riff, während sich weiter südlich entlang der Küstenlinie der befestigte Hordenaußenposten des Basislagers von Grom'gol befindet. Im Norden steigen die Klippen zu den Ackerlanden und der Küste von Westfall an.",al={"sehenswürdigkeiten ungezähmte küste","was liegt nahe der ungezähmten küste"}}},fp="12,282,20.539.0,26.227.0,43.251.0,66.215.0,41.207.0"}
P.entries["subzone:scarab-dais"] = {n="Die Skarabäushöhe",s="Die Skarabäushöhe ist eine uralte erhöhte Plattform nordwestlich des Skarabäuswalls im südlichen Silithus. Sie beherbergt den legendären Skarabäusgong, das Ritualinstrument, das direkt mit den magischen Schutzzaubern verbunden ist, die das Reich der Qiraji in Ahn'Qiraj versiegeln.",h="Die Skarabäushöhe ist eine uralte erhöhte Plattform nordwestlich des Skarabäuswalls im südlichen Silithus.",kw={"ahn'qiraj","jonathan the revelator","die skarabäushöhe","skarabäusgong","der skarabäuswall","sandstürme","silithus"},ang={["race:NightElf"]="Für die Kaldorei ist die Skarabäushöhe eine eindringliche Erinnerung an den tragischen Krieg der Sandstürme vor tausend Jahren, in dem Nachtelfen und Drachenschwärme mit Blut bezahlten, um die Qiraji hinter der Mauer einzuschließen."},sec={{t="Der Gong von Ahn'Qiraj",b="Mit Blick auf den wandelnden Sand vor der kolossalen Barriere des Skarabäuswalls dient die Skarabäushöhe als Mittelpunkt für das Siegel, das vor einem Jahrtausend auf Ahn'Qiraj gelegt wurde. Auf dieser steinernen Erhebung ruht der Skarabäusgong, ein Relikt, das während des Krieges der Sandstürme geschmiedet wurde. Gemäß der uralten Geschichte der Nachtelfen und des bronzenen Drachenschwarms ist das Schlagen dieses Gongs mit dem rekonstruierten Zepter der Sandstürme das einzige Mittel, um die magische Barriere zu zerschlagen und die Tore zu durchbrechen. Bis dieser schicksalhafte Moment eintrifft, verharrt die Plattform in einer unheilvollen Wache über die versiegelten insektoiden Schrecken, die jenseits des Walls schlummern."}},faq={{q="Was ist die Skarabäushöhe?",a="Die Skarabäushöhe ist eine zeremonielle Steinterrasse im südlichen Silithus, gelegen unmittelbar nordwestlich des Skarabäuswalls. Sie wurde errichtet, um den Skarabäusgong zu beherbergen, welcher die magischen Schutzsegen kontrolliert, die Ahn'Qiraj versiegeln.",al={"was ist diese plattform","skarabäushöhe info","gong plattform"}},{q="Was geschieht, wenn jemand den Gong auf der Höhe läutet?",a="Die Legende besagt, dass das Anschlagen des Skarabäusgongs mit dem wiederhergestellten Zepter der Sandstürme die Schutzzauber über dem Skarabäuswall zerschlagen wird, wodurch die Tore von Ahn'Qiraj geöffnet und die darin gefangenen Armeen der Qiraji entfesselt werden.",al={"was bewirkt der gong","skarabäusgong läuten","einen gong schlagen"}},{q="Wer wacht über die Skarabäushöhe?",a="Jonathan the Revelator, ein menschlicher Beobachter des bronzenen Drachenschwarms, bekannt als Hüter des Skarabäusgongs, hält auf der Anhöhe Wache über den Gong und das versiegelte Tor dahinter.",al={"wer ist an der höhe","bronzedrachen an der höhe","jonathan the revelator"}}},fp="11,242,21.618.0,24.207.0,51.220.0,33.174.0"}
P.entries["subzone:scarlet-base-camp"] = {n="Scharlachroter Stützpunkt",s="Der Scharlachrote Stützpunkt ist ein befestigter Außenposten am östlichen Ufer des Mereldarsees in den Östlichen Pestländern, direkt westlich von Tyrs Hand. Seine Barrikaden markieren eine äußere Verteidigungsposition des Scharlachroten Kreuzzugs.",h="Der Scharlachrote Stützpunkt ist ein befestigter Außenposten am östlichen Ufer des Mereldarsees in den...",kw={"östliche pestländer","mereldarsee","scharlachroter stützpunkt","scharlachroter kreuzzug","tyrs hand"},ang={["class:Paladin"]="Das Lager spiegelt die tragische Korruption des Vermächtnisses der Silbernen Hand wider, bei der sich rechtschaffener Eifer zur Verteidigung von Lordaerons heiligem Boden in aggressive Paranoia gegenüber anderen Überlebenden verwandelt hat.",["race:Undead"]="Der Außenposten dient als direkte Erinnerung an die lebenden Eiferer, die die Verlassenen ebenso rücksichtslos aus Lordaeron auslöschen wollen, wie sie die gedankenlose Geißel jagen."},sec={{t="Eine Frontlinie am Mereldarsee",b="Der Scharlachrote Stützpunkt thront am östlichen Ufer des Mereldarsees und ist eine barrikadierte Befestigung direkt westlich von Tyrs Hand. Er markiert eine äußere Position des Scharlachroten Kreuzzugs in der verheerten Landschaft."},{t="Abschirmung der Bastion",b="Tyrs Hand ist eine der Hochburgen des Scharlachroten Kreuzzugs in Lordaeron. Das Lager liegt entlang seiner westlichen Zugangswege, in einer Region, in der der Kreuzzug versucht, das Land von den Untoten zurückzuerobern und Außenstehenden mit Misstrauen begegnet."}},faq={{q="Was ist der Zweck des Scharlachroten Stützpunkts?",a="Das Lager ist eine barrikadierte Befestigung des Scharlachroten Kreuzzugs am östlichen Ufer des Mereldarsees, direkt westlich von Tyrs Hand.",al={"was ist der scharlachrote stützpunkt","warum ist das scharlachrote lager hier","zweck des stützpunkts"}},{q="Wer führt die Truppen an, die in dem Lager stationiert sind?",a="Für das ursprüngliche Classic-Lager ist kein Kommandant bekannt. Es handelt sich um eine Position des Scharlachroten Kreuzzugs in der Nähe von Tyrs Hand.",al={"wer führt den scharlachroten stützpunkt","lagerkommandant","anführer des scharlachroten lagers"}},{q="Sind die Bewohner Reisenden gegenüber feindselig?",a="Der Scharlachrote Kreuzzug ist Außenstehenden beider Fraktionen gegenüber feindselig eingestellt und betrachtet sie als potenzielle Träger der Seuche oder als Agenten der Geißel.",al={"greift mich der scharlachrote stützpunkt an","ist das scharlachrote lager feindselig","sind sie freundlich"}},{q="Wo befindet sich das Lager in Bezug auf den Mereldarsee?",a="Es steht am östlichen Ufer des Mereldarsees, direkt westlich von Tyrs Hand.",al={"scharlachroter stützpunkt see","wo ist das scharlachrote lager","lager bei tyrs hand"}}},fp="17,203,31.197.0,21.221.0,45.117.0,43.107.0,39.138.0,47.67.0"}
P.entries["subzone:scarlet-basilica"] = {n="Die Scharlachrote Basilika",s="Die Scharlachrote Basilika ist eine prächtige Kathedrale im Herzen von Tyrs Hand in den Östlichen Pestländern. Sie dient als hoher Sitz der geistlichen und militärischen Führung des Scharlachroten Kreuzzugs im Osten. Unter der Aufsicht von Crusader Lord Valdelmar stellen ihre Hallen die unnachgiebige Bastion der Eiferer gegen die Geißel dar.",h="Die Scharlachrote Basilika ist eine prächtige Kathedrale im Herzen von Tyrs Hand in den Östlichen Pestländern.",kw={"kathedrale","crusader lord valdelmar","östliche pestländer","die scharlachrote basilika","scharlachroter kreuzzug","tyrs hand"},ang={["class:Paladin"]="Die Basilika steht als verzerrtes Denkmal für eine fehlgeleitete heilige Hingabe, in der ehemalige Ritter der Silbernen Hand ihren Eifer in gnadenlosen Fanatismus verwandelt haben.",["race:Undead"]="Für die Verlassenen stellt die Basilika einen der am stärksten verschanzten Außenposten der Eiferer dar, die ungeachtet des freien Willens aktiv die vollständige Auslöschung aller Untoten anstreben."},sec={{t="Das Herz des östlichen Kreuzzugs",b="Erhaben über der befestigten Enklave von Tyrs Hand thronend, dient die Scharlachrote Basilika als zentrale Kathedrale und Kommandozentrale für die Operationen des Scharlachroten Kreuzzugs in den Östlichen Pestländern. Während das Scharlachrote Kloster weit im Westen in Tirisfal das geistliche Herz des Ordens bildet, verankert diese Basilika ihre verbliebene territoriale Hochburg gegen die verseuchten Schrecken Lordaerons. Streng bewacht von Elite-Kreuzfahrern beherbergt die Kathedrale Crusader Lord Valdelmar, der die örtliche Verteidigung leitet und fanatisch jeden Außenstehenden säubert, der es wagt, sich ihr zu nähern."}},faq={{q="Was ist die Scharlachrote Basilika?",a="Die Scharlachrote Basilika ist die prächtige Kathedrale innerhalb der Festungsstadt Tyrs Hand in den Östlichen Pestländern. Sie dient als primärer Sitz der religiösen und militärischen Führung des Scharlachroten Kreuzzugs in dieser Region.",al={"scharlachrote basilika info","was ist diese kathedrale","tyrs hand kirche"}},{q="Wer befehligt die Streitkräfte in der Basilika?",a="Crusader Lord Valdelmar befehligt die Streitkräfte innerhalb der Scharlachroten Basilika und fungiert als einer der hochrangigen Anführer des Scharlachroten Kreuzzugs, die Tyrs Hand gegen die Geißel und andere vermeintliche Feinde halten.",al={"wer ist in der scharlachroten basilika","valdelmar","scharlachrote basilika boss"}},{q="Wie ist das Verhältnis zum Scharlachroten Kloster?",a="Während das Scharlachrote Kloster in Tirisfal der primäre geistliche Hauptsitz des Ordens ist, fungiert die Scharlachrote Basilika als dessen östliches Gegenstück und bietet ein beherrschendes religiöses und befestigtes Zentrum tief in den Pestländern.",al={"kloster vs basilika","ist das das scharlachrote kloster"}},{q="Sind Reisende in der Basilika willkommen?",a="Nein. Der Scharlachrote Kreuzzug ist einem fremdenfeindlichen Wahnsinn verfallen und glaubt, dass jeder, der nicht ihre scharlachroten Farben trägt, von Untod befallen ist. Sowohl Eindringlinge der Allianz als auch der Horde werden bei Sichtkontakt sofort angegriffen.",al={"kann allianz betreten","ist scharlachrote basilika feindselig","kann ich besuchen"}}},fp="16,315,28.565.0,29.223.0,41.202.0,47.237.0,42.209.0"}
P.entries["subzone:scarlet-monastery"] = {n="Das Scharlachrote Kloster",s="In den nordöstlichen Hügeln von Tirisfal gelegen, war das Scharlachrote Kloster einst ein friedliches Zentrum der Gelehrsamkeit und Andacht für die Kirche des Heiligen Lichts. Nach dem Fall Lordaerons ist es zu einer stark befestigten Zuflucht für den fanatischen Scharlachroten Kreuzzug geworden. Jeder, der sich ohne rote Farben nähert, wird als infizierter Träger der Seuche behandelt und auf der Stelle hingerichtet.",h="In den nordöstlichen Hügeln von Tirisfal gelegen, war das Scharlachrote Kloster einst ein friedliches Zentrum...",kw={"waffenkammer","kathedrale","friedhof","library","mograine","altes kloster","scharlachroter kreuzzug","das scharlachrote kloster","tirisfal","whitemane"},ang={["class:Paladin"]="Der Komplex bildete einst Paladine unter der Silver Hand aus, was seine Wandlung zu einer intoleranten Bastion des Fanatismus zu einem bitteren Anblick für gläubige heilige Streiter macht.",["faction:Horde"]="Das Kloster liegt direkt vor der Haustür der Unterstadt, was seine schwer bewaffneten Kreuzfahrer zu einer aktiven, existenziellen Bedrohung für das Territorium der Verlassenen macht."},sec={{t="Von der Zuflucht zur Festung",b="Vor dem Dritten Krieg war dieser Komplex eine stolze Bastion von Lordaerons Priesterschaft und diente als wichtiges Zentrum für theologische Studien, heilige Archive und die Ausbildung von Paladinen. Als das Königreich Lordaeron an die Geißel fiel, hielten überlebende Verteidiger die Stätte gegen die Untoten. Als sie zum eifernden Scharlachroten Kreuzzug wurden, befestigten sie das Kloster und verwandelten seine friedlichen Bibliotheken, Gärten und die Kathedrale in eine bewaffnete Zitadelle."},{t="Eine Bastion des Fanatismus",b="Aufgeteilt in vier verschiedene Flügel – einen geschändeten Friedhof, eine weitläufige Library, eine Waffenkammer und eine prachtvolle Kathedrale – beherbergt das Kloster nun eine gewaltige Garnison, die von Scharlachrotem Kommandanten Mograine und High Inquisitor Whitemane befehligt wird. Die Kreuzfahrer hier betrachten alle Außenstehenden, ob lebend oder untot, Allianz oder Horde, als Seuchenträger. Während die Verlassenen versuchen, die Garnison zu beseitigen, die ihre unmittelbare Haustür bedroht, betrachtet die Führung der Allianz den gewaltsamen Extremismus des Kreuzzugs zunehmend als gefährliche Perversion des Lichts."}},faq={{q="Warum ist das Scharlachrote Kloster hier?",a="Es wurde ursprünglich während der Herrschaft von Lordaeron als friedliche Zuflucht für Studien erbaut, um heilige Schriften zu beherbergen und Paladine auszubilden. Überlebende Kreuzfahrer nahmen es nach dem Fall des Königreichs ein und befestigten es, damit es als militärischer Aufmarschplatz gegen die Untoten in Tirisfal diente.",al={"was ist das scharlachrote kloster","warum wurde das kloster in tirisfal gebaut","zweck des klosters"}},{q="Warum greift der Scharlachrote Kreuzzug Mitglieder der Allianz an?",a="Der Eifer des Kreuzzugs ist in völlige Paranoia umgeschlagen. Sie glauben, dass jeder, der außerhalb ihrer gesicherten Anlagen gereist ist, ein Träger der Seuche des Untods der Geißel sein könnte, und sie weigern sich, bei Außenstehenden ungeachtet von Volk oder Zugehörigkeit ein Risiko einzugehen.",al={"warum sind die scharlachroten feindlich zur allianz","gehört der scharlachrote kreuzzug zur allianz","warum greifen kreuzfahrer menschen an"}},{q="Wer führt die Streitkräfte im Kloster an?",a="Die Garnison wird von Scharlachrotem Kommandanten Mograine gehalten, der militärische Operationen aus der Kathedrale leitet, und High Inquisitor Whitemane, einer eifrigen Priesterin, die für ihre Hingabe und Wiederbelebungskräfte bekannt ist.",al={"wer ist der boss des scharlachroten klosters","anführer des klosters","wer führt den scharlachroten kreuzzug hier an"}},{q="Was sind die vier Flügel des Komplexes?",a="Der Komplex ist in vier verschiedene Bereiche unterteilt: der Friedhof, überrannt von rastlosen Toten und Folterkammern; die Library, die historische Archive und Folianten bewahrt; die Waffenkammer, in der der Kreuzzug Waffen und Rüstungen herstellt; und die Kathedrale, das geistliche Herz und der Sitz des Kommandanten.",al={"abschnitte des klosters","welche flügel gibt es im scharlachroten kloster","aufbau des klosters"}}},fx={b123b1b5={q="Was ist Das Scharlachrote Kloster?",a="Das in den nordöstlichen Hügeln von Tirisfal gelegene Das Scharlachrote Kloster war einst eine friedliche Kathedrale und ein Zentrum der Gelehrsamkeit für die Priesterschaft von Lordaeron. Nach dem Dritten Krieg und der Verwüstung des Königreichs ergriff The Scarlet Crusade Besitz von dem uralten Heiligtum und verwandelte es in eine schwer befestigte Festung. Seine Hallen, die einst der Erleuchtung und der Ausbildung heiliger Paladine gewidmet waren, hallen nun von fanatischem Eifer wider.",al={"was ist das scharlachrote kloster","hintergrund des scharlachroten klosters","erzähle mir vom scharlachroten kloster"}},["73cac1e2"]={q="Ist Das Scharlachrote Kloster gefährlich?",a="Es ist außergewöhnlich gefährlich. Der Komplex wird von Hunderten schwer bewaffneter, eifernder Kreuzfahrer bewacht, die jeden Außenstehenden als potenziellen Träger der Plage der Untoten betrachten. Ob Ihr zur Horde oder zur Allianz gehört, ihre ständigen Befehle lauten auf gnadenlose Hinrichtung. Selbst jenseits ihrer militärischen Soldaten wird das innere Sanktum von hochrangigen Inquisitoren geschützt, deren heilige Kräfte die Gefallenen wieder ins Gefecht zurückholen können.",al={"ist das scharlachrote kloster gefährlich","wie gefährlich ist das kloster","ist es sicher das kloster zu betreten"}},["5fcbefd1"]={q="Was geschah im Scharlachroten Kloster?",a="Das Kloster war einst eine stolze Bastion der Priesterschaft von Lordaeron, ein Zentrum des Wissens und der Erleuchtung, in dem auch Paladine ausgebildet wurden. Als die Geißel während des Dritten Krieges Lordaeron überrannte, ergriffen überlebende Eiferer des Scharlachroten Kreuzzugs Besitz von dem Komplex und wandelten den friedlichen heiligen Sitz in eine bewaffnete Festung um.",al={"geschichte des scharlachroten klosters","was geschah hier","vergangenheit des klosters"}},a14a0fc8={q="Warum heißt es Das Scharlachrote Kloster?",a="Der Name rührt von seinen Herren her. Als die Geißel Lordaeron überrannte, bemächtigte sich der extremistische Scharlachrote Kreuzzug des Klosters und baute es zu seiner Festung aus, und so trägt es nun den Namen ihres purpurnen Ordens.",al={"warum heisst es das scharlachrote kloster","ursprung des namens scharlachrotes kloster","woher stammt der name"}}},fp="17,382,28.432.0,23.524.0,34.281.0,53.264.0,42.212.0,39.286.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Scarlet Monastery Armory",s="Die Waffenkammer ist der befestigte militärische Flügel des Scharlachroten Klosters, der der Herstellung von Waffen und der Ausbildung von Rekruten für den Scharlachroten Kreuzzug gewidmet ist. Hinter verschlossenen Eisentoren exerzieren Reihen fanatischer Fußsoldaten und Kreuzfahrer unter dem unerbittlichen Befehl von Herod, dem Scharlachroten Champion.",h="Die Waffenkammer ist der befestigte militärische Flügel des Scharlachroten Klosters, der der Herstellung von...",kw={"waffenkammer","crusader's armory","waffenkammer des soldaten","hall of champions","herod","scharlachroter champion","scharlachroter schlüssel","scarlet monastery armory"},ang={["class:Warrior"]="Die Waffenkammer ist das vollendete Übungsgelände für den tödlichen Kampf, auf dem scharlachrote Krieger den tödlichen Einsatz von Haltungen, Entwaffnungen und Herods berühmter Wirbelwindtechnik demonstrieren.",["faction:Horde"]="Da der Scharlachrote Kreuzzug direkt vor den Toren der Unterstadt eine Armee zusammenzieht, ist es für das Überleben der Verlassenen von entscheidender Bedeutung, deren Bewaffnung zu plündern und ihren Champion niederzustrecken."},sec={{t="Die Gießerei des Eifers",b="Einst Teil einer friedlichen Zuflucht für Lordaerons Priesterschaft, wurde das Kloster nach dem Dritten Krieg komplett umgestaltet. Die Waffenkammer dient nun als primäre Schmiede, Waffendepot und Kampfprüfungsstätte des Kreuzzugs. Von den offenen Übungsplätzen bis zu den tiefen Waffenhallen bereiten sich Reihen scharlachroter Fußsoldaten, Beschwörer und Kreuzfahrer unerbittlich darauf vor, die Geißel und jeden anderen zu läutern, den sie als verdorben erachten. Der Flügel bleibt gegenüber dem Grand Vestibule verschlossen und ist nur jenen zugänglich, die den scharlachroten Schlüssel tragen, der in der benachbarten Library zu finden ist."},{t="Die Hall of Champions",b="Im Herzen des Flügels liegt die Hall of Champions, gesäumt von hoch aufragenden Statuen, die legendären Helden der Vergangenheit des Kreuzzugs gewidmet sind. Die Halle wird von Herod beaufsichtigt, einem brutalen Krieger, dessen Wildheit und Wirbelwinde unter den Kreuzfahrern legendär sind. Herod bildet die nächste Generation von Eiferern persönlich aus; wenn er im Kampf hart bedrängt wird, strömen seine verzweifelten Rekruten in die Kammer, um für ihren Champion zu kämpfen und zu sterben."}},faq={{q="Wie gelangt Ihr in das Innere der Waffenkammer?",a="Die Tür zur Waffenkammer im Grand Vestibule ist sicher verschlossen. Um sie zu öffnen, müsst Ihr den Library-Flügel betreten und den scharlachroten Schlüssel aus der Truhe hinter Arkanist Doan im Athenaeum bergen, oder einen Schurken mitbringen, der im Schlossknacken geübt genug ist.",al={"waffenkammer verschlossen","wie man die waffenkammer aufschließt","scharlachroter schlüssel waffenkammer","waffenkammer-tür öffnen"}},{q="Wer führt die Truppen in der Waffenkammer an?",a="Der Flügel wird von Herod befehligt, bekannt als der Scharlachrote Champion. In der Hall of Champions stationiert, drillt er Soldaten und unterzieht neue Rekruten intensiven Kampfprüfungen.",al={"waffenkammer boss","wer leitet die waffenkammer","wer führt die waffenkammer","herod waffenkammer"}},{q="Welchen Zweck erfüllt dieser Flügel für den Scharlachroten Kreuzzug?",a="Er dient als Hauptarsenal und Ausbildungsakademie des Kreuzzugs. Der Komplex beherbergt umfangreiche Waffenschmieden, Rüstkammern für Fußsoldaten und Kreuzfahrer sowie Exerzierplätze im Freien, die genutzt werden, um Soldaten zu stählen, bevor sie nach Tirisfal und in die Pestländer entsandt werden.",al={"warum die waffenkammer existiert","was sie hier tun","zweck der waffenkammer"}},{q="Wessen Statuen werden in der Hall of Champions geehrt?",a="Die Statuen feiern die meistgepriesenen Märtyrer und Helden des Ordens, Champions, deren Andenken die Kreuzfahrer anrufen, während sie neue Rekruten für den Krieg gegen die Untoten drillen.",al={"waffenkammer statuen","hall of champions statuen","statuen in herods raum"}}},fx={["469efc8f"]={q="Was ist die Scarlet Monastery Armory?",a="Die Armory ist ein schwer befestigter Flügel innerhalb des Komplexes Das Scharlachrote Kloster in Tirisfal. Einst der friedlichen Verehrung und dem Studium des Heiligen Lichts unter der Priesterschaft von Lordaeron gewidmet, dient sie nun als Ausbildungskaserne, Waffendepot und Versammlungsplatz für die militanten Eiferer von The Scarlet Crusade.",al={"was ist die armory","hintergrund der armory des scharlachroten klosters","über die armory"}},cd55d42c={q="Was ist mit der Armory geschehen?",a="Während des Dritten Kriegs dezimierte die Geißel Lordaeron, fegte durch die Region und verwandelte das friedliche Zentrum der Gelehrsamkeit in einen verzweifelten Zufluchtsort. Überlebende Geistliche und Soldaten radikalisierten sich zu The Scarlet Crusade, bewaffneten sich und befestigten das Gelände zu einer unnachgiebigen Bastion, die entschlossen ist, jeden auszurotten, bei dem sie den Verdacht haben, die Plage in sich zu tragen.",al={"geschichte der armory","was ist in der armory geschehen","hintergrund der armory"}},edfdc72e={q="Ist die Armory gefährlich?",a="Es ist außergewöhnlich gefährlich. Die Hallen wimmeln von fanatischen Kreuzfahrern, Fußsoldaten und Kampfmagiern, die darauf trainiert sind, auf Sicht zu töten. The Scarlet Crusade betrachtet alle Außenstehenden als potenzielle Träger der Geißel, was bedeutet, dass jeder Eindringling, der die Übungsplätze oder Hallen betritt, disziplinierten, unerbittlichen Soldaten gegenübersteht, die bis zum Tod kämpfen.",al={"wie gefährlich ist die armory","ist die armory sicher","armory bedrohung"}}},fp="24,276,19.544.0,21.418.0,33.236.0,35.179.0,57.256.0,51.169.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Scarlet Monastery Cathedral",s="Die Kathedrale ist das geistliche und militärische Herz des Scharlachroten Klosters und beherbergt das Allerheiligste des Kreuzzugs. Einst eine friedvolle Gebetshalle für Lordaerons Priesterschaft, dient sie heute als Kommandositz für High Inquisitor Whitemane und Scharlachroter Kommandant Mograine, bewacht von den hingebungsvollsten Eiferern des Kreuzzugs.",h="Die Kathedrale ist das geistliche und militärische Herz des Scharlachroten Klosters und beherbergt das...",kw={"kathedrale","chapel gardens","crusader's chapel","high inquisitor","mograine","das scharlachrote kloster","whitemane"},ang={["faction:Alliance"]="Für die Allianz stellt der Kreuzzug eine tragische, verderbte Perversion des Heiligen Lichts und Lordaerons stolzen Erbes dar, was Kommandanten in Süderstade dazu veranlasst, Champions auszusenden, um ihrem Wahnsinn ein Ende zu setzen.",["faction:Horde"]="Gefährlich nahe an Unterstadt gelegen, beherbergt die Kathedrale Eiferer, die sich der völligen Vernichtung der Verlassenen und aller mit ihnen verbündeten Streitkräfte der Horde verschrieben haben."},sec={{t="Sanktum des Eifers",b="Einst ein friedliches Zentrum der Erleuchtung und des Gebets für die Priesterschaft von Lordaeron, verfiel die Kathedrale nach dem Dritten Krieg dem Wahnsinn. Nach dem Fall des Königreichs an die Geißel verwandelten überlebende Eiferer den Komplex in eine Festung unerbittlichen Hasses. Jenseits des gepflegten Kreuzgangs der Chapel Gardens liegt die große Crusader's Chapel, in der sich Priester und Krieger in Hingabe an ihren Kreuzzug versammeln. Sie betrachten alle Außenstehenden – ungeachtet ihres Volkes oder ihrer Fraktion – als Überträger der untoten Seuche, die durch Klinge und heiliges Feuer gereinigt werden müssen."},{t="Die Hochinquisitorin und ihr Kommandant",b="Die in der Kathedrale stationierten Truppen unterstehen direkt Scharlachroter Kommandant Mograine, der die Garnison mit eiserner Disziplin führt. Doch das wahre Herz des Fanatismus dieser Enklave ist High Inquisitor Whitemane. Als formidabler Anwender des Lichts ermöglicht Whitemanes göttliche Hingabe es ihr, gefallene Champions in der Hitze des Gefechts wiederzubeleben. Gemeinsam halten sie und Mograine die innere Kapelle gegen jeden, der es wagt, die Klostertore zu durchbrechen, und beweisen damit, dass der eiserne Griff des Kreuzzugs auf das nördliche Lordaeron tödlich intakt bleibt."}},faq={{q="Wofür wird die Kathedrale genutzt?",a="Sie dient als inneres Reduit und heiliger High Seat des Scharlachroten Kreuzzugs innerhalb des Klosters. Hier halten die obersten Anführer der Organisation Gottesdienste ab und leiten ihre militärischen Feldzüge quer durch Tirisfal.",al={"zweck der kathedrale","warum die kathedrale besuchen","was ist das für ein ort"}},{q="Wer führt den Scharlachroten Kreuzzug hier an?",a="Die Garnison wird von Scharlachroter Kommandant Mograine befehligt, während die geistliche Führung bei High Inquisitor Whitemane liegt, einer formidablen und eifrigen Priesterin.",al={"wer ist hier der boss","bosse der kathedrale","whitemane mograine"}},{q="Warum ist die Tür zur Kathedrale verschlossen?",a="Die schweren Tore zum Kathedralenflügel sind verschlossen, um Eindringlinge daran zu hindern, das innere Sanktum zu stürmen. Der Zutritt erfordert den scharlachroten Schlüssel, der im Library-Flügel des Klosters bewacht wird.",al={"kathedrale verschlossen","wie man die kathedrale öffnet","wo ist der schlüssel"}},{q="Warum greifen die Kreuzfahrer andere lebende Menschen an?",a="Getrieben von paranoidem Wahn durch die Zerstörung Lordaerons durch die Geißel, glaubt der Kreuzzug, dass alle Außenstehenden Träger der Seuche des Untodes sind. Sie verweigern jeglichen Kontakt mit externen Fraktionen und richten jeden hin, der sich ihren Festungen nähert.",al={"warum die allianz angreifen","scharlachroter kreuzzug böse","warum kreuzzug feindselig"}}},fx={["9962382e"]={q="Was ist die Scarlet Monastery Cathedral?",a="Die Cathedral ist der zentrale, krönende Flügel des Komplexes Das Scharlachrote Kloster in Tirisfal. Einst ein verehrtes Heiligtum der Priesterschaft von Lordaeron, das der Gelehrsamkeit und der spirituellen Erleuchtung gewidmet war, dient es nun als Sanctum Sanctorum und Kommandositz für die Eiferer von The Scarlet Crusade.",al={"was ist die cathedral","scharlachrote kathedrale","kathedralenflügel"}},d9fd8161={q="Was ist mit der Scarlet Monastery Cathedral geschehen?",a="Vor dem Dritten Krieg stand dieses friedliche Kloster als stolze Bastion des Heiligen Lichts von Lordaeron, das dem Studium und der Heilung gewidmet war. Als die Geißel durch das Königreich raste, befestigten die überlebenden Verteidiger den heiligen Ort und verwandelten seine ruhigen Hallen und Innenhöfe in eine schwer bewaffnete Festung, die von Paranoia und fanatischem Hass getrieben wird.",al={"geschichte der kathedrale","was ist hier geschehen","vergangenheit des klosters"}},["09ab4f6a"]={q="Ist die Scarlet Monastery Cathedral gefährlich?",a="Es ist bei weitem der gefährlichste Teil des Klosters. Hinter seinem Innenhof liegt eine große Kapelle, vollgestopft mit Elite-Kreuzfahrern, hingebungsvollen Äbten und tödlichen Hexenmeistern. Ihre Verteidiger kämpfen mit eifriger Wut, und Eindringlinge stehen der vereinten Macht von Commander Mograine und der furchterregenden High Inquisitor Whitemane gegenüber.",al={"gefahr in der kathedrale","ist es hier sicher","wie gefährlich ist die kathedrale"}}},fp="27,313,15.561.0,37.517.1,31.224.0,35.160.0,40.190.0,52.243.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {fx={["2ee90fec"]={q="Was ist die Scarlet Monastery Graveyard?",a="Es ist der linke Flügel des Komplexes Das Scharlachrote Kloster im nordöstlichen Tirisfal. Einst als Begräbnisstätte und Krypten für den heiligen Orden von Lordaeron dienend, ist er nun der Verderbnis und Vernachlässigung anheimgefallen, gefüllt mit Gräbern, Mausoleen und den ruhelosen Toten.",al={"was ist die graveyard","graveyard-flügel","scharlachroter friedhof"}},d7efe218={q="Was ist mit der Scarlet Monastery Graveyard geschehen?",a="Ursprünglich ein ruhiger Ruheplatz für geehrte Priester und Champions von Lordaeron, fiel das Gelände unter die Kontrolle von The Scarlet Crusade, als das Kloster gegen die Geißel befestigt wurde. Anstatt friedliche Ruhe zu finden, begannen die hier begrabenen Körper als Untote aufzuerstehen, was dazu führte, dass die Crusade die verfallenen Begräbnisstätten abmauern musste.",al={"geschichte des friedhofs","was ist hier geschehen","ursprung des friedhofs"}},["35b34413"]={q="Wer kontrolliert die Scarlet Monastery Graveyard?",a="Während die Crusade den größeren Klosterkomplex beansprucht, ist der Flügel Graveyard selbst weitgehend den ruhelosen Untoten überlassen. Der gefallene Magier Thalnos, der zu einem blutrünstigen, skelettartigen Zauberwirker korrumpiert wurde, herrscht über die innerste Gruft neben verstreuten Ghulen, Geistern und wandernden Toten.",al={"wer kontrolliert den friedhof","wer hat hier das sagen","friedhofsanführer"}},c4dc5010={q="Warum ist die Scarlet Monastery Graveyard verlassen und zerstört?",a="Die fanatische heilige Macht der Crusade konnte die Plage der Geißel nicht davon abhalten, ihre Toten zu schänden. Unfähig, die auferstehenden Leichen vollständig zu reinigen, zogen sich die lebenden Kreuzfahrer in ihre befestigten Kapellen und Rüstkammern zurück und überließen die Begräbnisstätten, die nun überwuchert und von wiederbelebten Leichen überrannt sind.",al={"warum ist der friedhof zerstört","warum ist er verlassen","warum vernachlässigt"}},["2daa3a11"]={q="Ist die Scarlet Monastery Graveyard gefährlich?",a="Ja. Obwohl weniger organisiert als die militärischen Streitkräfte, die die anderen Klosterflügel besetzen, ist die Graveyard gefüllt mit aggressiven Untoten, bösartigen Geistern und dunklen Zauberwirkern wie Blutmagier Thalnos, die jeden lebenden Eindringling, der die Gräber betritt, gnadenlos angreifen.",al={"ist der friedhof gefährlich","gefahr auf dem friedhof","wie gefährlich ist der friedhof"}},cfbfb429={q="Warum heißt es Scarlet Monastery Graveyard?",a="Es dient als die zugehörige Begräbnisstätte und der Friedhof von Das Scharlachrote Kloster. Es beherbergt uralte Krypten, Mausoleen wie Honor's Tomb und den Forlorn Cloister, wo die heiligen Verteidiger von Lordaeron traditionell zur letzten Ruhe gebettet wurden.",al={"warum heißt es der friedhof","friedhofsname","warum scharlachroter klosterfriedhof"}}}}
P.entries["subzone:scarlet-monastery-library"] = {n="Scarlet Monastery Library",s="Die Bibliothek ist der östliche Flügel des Scharlachroten Klosters in Tirisfal, einst der heiligen Gelehrsamkeit und der Priesterschaft Lordaerons gewidmet. Heute wird sie von Kampfhunden und Fanatikern bewacht und beherbergt uralte Archive sowie seltene Folianten, die von Gelehrten und Magiern beider Fraktionen heiß begehrt sind.",h="Die Bibliothek ist der östliche Flügel des Scharlachroten Klosters in Tirisfal, einst der heiligen...",kw={"arkanist doan","athenäum","kompendium der gefallenen","hundemeister loksey","bibliothek","der scharlachrote schlüssel","das scharlachrote kloster","tirisfal"},ang={["class:Mage"]="Das Athenäum ist eine unverzichtbare Pilgerstätte für ehrgeizige Magier, die alte Rituale der Macht suchen und ihren Mut gegen die zerstörerische Zauberei von Arkanist Doan auf die Probe stellen wollen.",["faction:Alliance"]="Die Bibliothek birgt heilige Aufzeichnungen von Lordaerons gefallenen Helden und Titanengeschichten, welche die Hall of Explorers aus Eisenschmiede unbedingt aus den Händen der Kreuzfahrer zurückholen will."},sec={{t="Archive von Lordaeron",b="Vor dem Dritten Krieg diente das Kloster als Zentrum des Lernens und der Erleuchtung für Lordaerons Priesterschaft. Die östlichen Kreuzgänge beherbergten riesige Archive religiösen Denkens, historischer Aufzeichnungen und arkaner Abhandlungen. Als der Scharlachrote Kreuzzug das Kloster gegen die Geißel befestigte, behielten sie diese Bestände und verwandelten die stillen Hallen in eine bewaffnete Redoute. Heute führen Bestienmeister Fährtenhunde durch die Höfe, während Kampfmagier die Regale patrouillieren und historische Bände wie das Kompendium der Gefallenen sowie uralte Forschungen über die Titanen vor Außenstehenden schützen."},{t="Wächter des Athenäums",b="Um in die Bibliothek einzudringen, muss man an Hundemeister Loksey im Huntsman's Cloister vorbeigelangen, dessen abgerichtete Hunde Eindringlinge aufspüren, die Durchgang in die inneren Kammern suchen. Jenseits der Gallery of Treasures liegt das Athenäum, das von Arkanist Doan überwacht wird. Als gewaltiger Magier, der verheerendes Feuer und schützende Zauberei beherrscht, studiert Doan in Isolation und verteidigt das gehortete Wissen des Kreuzzugs erbittert gegen jeden, der sich in das Herz des Komplexes wagt."}},faq={{q="Wo befindet sich die Bibliothek im Scharlachroten Kloster?",a="Beim Betreten des Grand Vestibule des Komplexes vom Scharlachroten Kloster in Tirisfal gelangt man über das Instanzportal ganz rechts in den Bibliotheksflügel.",al={"bibliothek eingang","welche tür führt zur bibliothek","bibliotheksflügel finden"}},{q="Warum werden Abenteurer in die Bibliothek geschickt?",a="Gelehrte, Priester und Magier von sowohl Allianz als auch Horde suchen nach kostbaren Texten, die in ihren Mauern aufbewahrt werden. Wichtige Ziele sind das Kompendium der Gefallenen, Titanenüberlieferungen, die von Historikern aus Eisenschmiede gesucht werden, sowie uralte magische Schriften für angehende Arkanisten.",al={"warum in die bibliothek gehen","bibliothek quests","was ist in der bibliothek"}},{q="Wer beherrscht den Bibliotheksflügel?",a="Über das innere Heiligtum der Bibliothek, das Athenäum, gebietet Arkanist Doan, ein mächtiger scharlachroter Zauberwirker. Der äußere Hof wird von Hundemeister Loksey und seinen bösartigen Fährtenbestien gesichert.",al={"bibliothek boss","wer leitet die bibliothek","wer führt die bibliothek"}},{q="Was ist der Scharlachrote Schlüssel, der hier gefunden wird?",a="Eine Geldkassette in Arkanist Doans Athenäum enthält Den scharlachroten Schlüssel, der benötigt wird, um die schweren Eisentüren aufzuschließen, die Einlass in die Waffenkammer und den Kathedralenflügel des Klosters gewähren.",al={"doan schlüssel","scharlachroter schlüssel beute","wo ist der scharlachrote schlüssel"}}},fx={["10860e43"]={q="Was ist die Scarlet Monastery Library?",a="Die Library ist der ganz rechts gelegene Flügel des weitläufigen Komplexes von Das Scharlachrote Kloster in Tirisfal. Einst ein ruhiges Zentrum für Studien und klerikale Erleuchtung in Lordaeron, beherbergt sie heute die gesammelte Überlieferung des Scharlachroter Kreuzzug, militärische Schätze und Hundezwinger, unterteilt in das Huntsman's Cloister, die Gallery of Treasures und das Athenaeum.",al={"was ist die bibliothek","scarlet library flügel","klosterbibliothek übersicht"}},["05144c18"]={q="Was ist mit der Scarlet Monastery Library geschehen?",a="Die Library war ursprünglich Teil einer stolzen Bastion der Priesterschaft von Lordaeron, die dem Lernen, dem theologischen Studium und der Erleuchtung gewidmet war. Als die untote Geißel im Dritter Krieg durch das Königreich wütete, befestigten überlebende menschliche Eiferer den gesamten Komplex. Sie wandelten den friedlichen Aufbewahrungsort für Bücher und heiliges Wissen in ein bewaffnetes Bollwerk des fanatischen Scharlachroter Kreuzzug um.",al={"geschichte der scarlet monastery library","bibliothek vergangenheit","was ist hier geschehen"}},a62144f3={q="Ist die Scarlet Monastery Library gefährlich?",a="Sie ist außerordentlich gefährlich. Die Library wird von eifrigen scharlachroten Soldaten, Priestern und Kampfmagiern bewacht, die alle Außenstehenden als Träger der Seuche der Geißel betrachten, die es auf Sicht zu vernichten gilt. Eindringlinge müssen sich durch trainierte Angriffshunde kämpfen, die von Hundemeister Loksey befehligt werden, bevor sie sich der tödlichen Zauberei von Arkanist Doan im inneren Athenaeum stellen.",al={"ist die scarlet monastery library gefährlich","bedrohungen in der bibliothek","wie gefährlich ist die bibliothek"}}},fp="25,282,21.587.0,26.457.0,50.155.0,40.258.0,27.198.0,35.175.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Scarlet Raven Tavern",s="Die Scarlet Raven Tavern ist das soziale Zentrum und die primäre Gaststätte von Dunkelhain und bietet Schutz am Kamin inmitten der Düsternis von Dämmerwald. Unter der Leitung von Schankwart Smitts dient sie als Treffpunkt für bedrängte Einheimische, durchreisende Abenteurer und verängstigte Reisende, die den Schrecken entkommen wollen, die hinter den Stadtgrenzen lauern.",h="Die Scarlet Raven Tavern ist das soziale Zentrum und die primäre Gaststätte von Dunkelhain und bietet Schutz...",kw={"dunkelhain","dämmerwald","schwärzliche krebsküchlein","haggard","jitters","scarlet raven","smitts","schankwart smitts"},ang={["faction:Alliance"]="Für Reisende der Allianz, die die südliche Grenze überqueren, bietet das Scarlet Raven einen der wenigen sicheren Kamine und Rastplätze zwischen dem Wald von Elwynn und dem Gebirgspass der Totenwinde.",["profession:Cooking"]="Die Speisekarte des Gasthauses bietet regionale Delikatessen wie Schwärzliche Krebsküchlein, ein lokales Grundnahrungsmittel, nach dem sich verzweifelte Wanderer wie Bibbers selbst dann sehnen, wenn sie sich auf dem Friedhof verstecken."},sec={{t="Ein düsterer Zufluchtsort",b="Die Scarlet Raven Tavern steht nahe dem Herzen von Dunkelhain und hält ihr Kaminfeuer am Brennen, während ewige Dämmerung den umliegenden Wald erstickt. Vor Jahren war sie ein belebter Zwischenstopp, an dem Marschall Haggard und die Wachen von Sturmwind nach Patrouillen gemeinsam ein Bier tranken. Heute ist das Geschäft mit der Sicherheit der Stadt dahingeschwunden. Schankwart Smitts bedient eine trübsinnige, besorgte Kundschaft, die sich gegen die Kälte und die Angst zusammendrängt. Dennoch bleibt die Taverne ein unverzichtbarer Knotenpunkt für Gerüchte und dient als Ausgangspunkt für Reisende, die Antworten auf die dunklen Phänomene suchen, die die Region verzehren."},{t="Geheimnisse und gestohlene Pints",b="Neben ihrer Funktion als Zufluchtsort beherbergt die Taverne Teile mehrerer sich entfaltender Mysterien. Der zurückgezogen lebende Wanderer Bibbers mietete hier tagelang ein Zimmer, kritzelte nachts fieberhaft in sein Tagebuch, bevor er vor den furchterregenden Dunklen Reitern aus der Stadt floh. Jahrzehntealter Stadtklatsch und bewahrte Gästeverzeichnisse unter ihrem Dach lassen sich auch mit längst vergessenen Gestalten wie Stalvan Dunstmantel in Verbindung bringen, was Smitts' Schankraum zum ersten Ort macht, den neugierige Ermittler bei der Suche nach der Geschichte der ruhelosen Toten von Dämmerwald aufsuchen."}},faq={{q="Wer führt die Scarlet Raven Tavern?",a="Schankwart Smitts ist der Schankwart. Das Gasthaus hat zudem einen Gastwirt und anderes Personal, das die Reisenden in Dunkelhain bedient.",al={"gastwirt von dunkelhain","wer besitzt das scarlet raven","schankwart smitts"}},{q="Warum ist die Atmosphäre der Taverne so düster?",a="Der Fluch, der über Dämmerwald liegt, hat die Handelsrouten unterbrochen und die Einheimischen in Angst und Schrecken versetzt. Da Untote, wilde Worgen und schattenhafte Reiter draußen durch den Wald streifen, besteht das Publikum eher aus verängstigten Stadtbewohnern und verzweifelten Söldnern als aus sorglosen Reisenden.",al={"warum ist das scarlet raven deprimierend","atmosphäre gasthaus dunkelhain"}},{q="Hat Bibbers im Scarlet Raven übernachtet?",a="Bibbers hielt sich im Gasthaus auf und schrieb fieberhaft in sein Tagebuch, bevor er aus der Stadt floh. Seine Gründe werden durch die Untersuchungen in Dämmerwald aufgedeckt.",al={"jitters zimmer","jitters taverne","hat jitters hier gelebt"}},{q="Welche Verbindung hat diese Taverne zur Legende von Stalvan?",a="Alte Stammgäste und vergangene Stadtarchive, die in und um die Taverne aufbewahrt werden, enthalten Hinweise auf Stalvan Dunstmantel, der die Siedlung einst häufig besuchte, bevor er in Tragik und Schande stürzte.",al={"verbindung stalvan gasthaus","stalvan dunstmantel gasthaus dunkelhain"}}},fx={["81b305d7"]={q="Was ist die Scarlet Raven Tavern?",a="Die Scarlet Raven Tavern ist das örtliche Gasthaus von Dunkelhain, das dem bedrängten Volk von Dämmerwald ein Dach, einen warmen Herd und ein kühles Getränk bietet. In einer Region, die von vordringenden Schatten und Schrecken erstickt wird, bleibt sie der wichtigste Treffpunkt für Stadtbewohner, müde Reisende und umherwandernde Abenteurer, die Klatsch austauschen oder sich ausruhen möchten.",al={"was ist die scarlet raven tavern","scarlet raven dunkelhain","gasthaus in dunkelhain"}},["27f7fada"]={q="Ist die Scarlet Raven Tavern gefährlich?",a="Innerhalb ihrer Mauern ist die Scarlet Raven einer der wenigen sicheren Zufluchtsorte in Dämmerwald. Geschützt durch die Nähe der The Night Watch und den Schutz von Dunkelhain hält das Gasthaus die Schrecken des Waldes draußen, auch wenn die Gäste im Inneren beunruhigt und wachsam sind.",al={"ist die scarlet raven gefährlich","ist das gasthaus in dunkelhain sicher","scarlet raven sicher"}}},fp="20,330,12.576.0,24.516.1,34.117.0,41.266.0,38.153.0,63.184.0"}
P.entries["subzone:scarlet-watch-post"] = {fx={["24ad1453"]={q="Was ist der Scharlachroter Wachposten?",a="Der Scharlachroter Wachposten ist ein isolierter Wachturm in den rauen Hügeln im Nordosten von Tirisfal, direkt nördlich von Das Scharlachrote Kloster. Er dient als befestigter Späheraußenposten, der den verwundbaren nördlichen Zugang zur mächtigen Bastion des Kreuzzugs bewachen soll.",al={"was ist der scharlachroter wachposten","scharlachroter wachposten hintergrund","was ist dieser turm"}},["1857b7a1"]={q="Ist der Scharlachroter Wachposten gefährlich?",a="Ja, außerordentlich gefährlich für jeden Außenstehenden. Der Posten ist mit eifrigen scharlachroten Kreuzrittern besetzt, darunter Brüder, Neophyten sowie schwer bewaffnete Vorhut und Leibwächter, die geschworen haben, jeden Eindringling, ob lebendig oder untot, auf Sicht abzuschlachten.",al={"ist der scharlachroter wachposten gefährlich","bedrohung durch scharlachroter wachposten","gefahr am wachposten"}}}}
P.entries["subzone:scholomance"] = {n="Scholomance",s="Tief in den Krypten unter Darrowehr verborgen, ist Scholomance die führende Akademie der Geißel für dunkle Künste und Totenbeschwörung. Hier studieren Sterbliche wie Untote gleichermaßen die Plague of Undeath und Fleischformung unter der sadistischen Anleitung von Dunkelmeister Gandling und dem wachsamen Blick des Lichs Ras Frostwhisper.",h="Tief in den Krypten unter Darrowehr verborgen, ist Scholomance die führende Akademie der Geißel für dunkle...",kw={"barov","darrowehr","kult der verdammten","dunkelmeister gandling","kel'thuzad","totenbeschwörung","ras frostwhisper","scholomance"},ang={["class:Mage"]="Die verdrehten Lehren, die in Scholomance vermittelt werden, stellen die absolute Perversion arkaner Gelehrsamkeit dar, bei der das Erforschen magischer Theorien durch Fäulnis, Schatten und unheilige Schändung ersetzt wurde.",["race:Undead"]="Zauberwirker der Verlassenen blicken mit kalter Vertrautheit und Abscheu auf Scholomance; viele der abscheulichsten Methoden der Geißel zur Versklavung und biologischen Kriegsführung wurden in genau diesen Unterrichtsräumen perfektioniert."},sec={{t="Ein Pakt des Verderbens",b="Vor dem Dritten Krieg war Darrowehr der stolze Sitz von House Barov, einer wohlhabenden aristokratischen Dynastie, die weite Ländereien in ganz Lordaeron besaß, darunter Brill, Tarrens Mühle und Süderstade. Aus Furcht vor dem Verlust ihres Reichtums und ihrer Sterblichkeit erlagen die Barovs den verführerischen Versprechungen von Kel'Thuzad auf ewiges Leben. Sie überschrieben ihre Festung und die uralten Katakomben dem Kult der Verdammten, der es den Adligen prompt damit vergalt, sie abzuschlachten und die weitläufigen Krypten in ein verborgenes nekromantisches Ausbildungsgelände zu verwandeln."},{t="Die Schule der Totenbeschwörung",b="Unter den heimgesuchten Oberflächenruinen von Darrowehr liegt ein florierendes Zentrum des Schaffens der Geißel. In diesen feuchten Hallen wurden frühe Seuchenstämme an den eigenen Dienern der Familie Barov getestet. Heute strömen sterbliche Akolythen hierher, um ihre Meisterschaft über dunkle Magie zu vervollkommnen, beaufsichtigt von Schulleiter Dunkelmeister Gandling und dem eisigen Wächter Ras Frostwhisper, während die rastlosen untoten Überreste der Familie Barov in ewiger Pein verweilen."}},faq={{q="Was ist Scholomance?",a="Scholomance ist eine geheime Akademie der Totenbeschwörung, die vom Kult der Verdammten und der Geißel betrieben wird. Unter der Inselfestung Darrowehr gelegen, dient sie als Ausbildungsstätte für sterbliche Totenbeschwörer, Seuchenforscher und Fleischformer.",al={"was ist dieser ort","scholomance geschichte","scholomance erklären"}},{q="Wem gehören Darrowehr und die Krypten?",a="Die Festung gehörte ursprünglich House Barov, einer der wohlhabendsten Adelsfamilien in Lordaeron. Auf der Suche nach Unsterblichkeit überließen sie Kel'Thuzad ihren Stammsitz, nur um ermordet und als untote Knechte in ihren eigenen Hallen wiedererweckt zu werden.",al={"wem gehörte das","house barov","familie barov"}},{q="Wer leitet die Akademie jetzt?",a="Dunkelmeister Gandling dient als heimtückischer sterblicher Schulleiter der Akademie und überwacht die Ausbildung und die Folterungen. Zudem wird die Stätte im Auftrag der Geißel durch den Lich Ras Frostwhisper schwer bewacht.",al={"wer ist der boss","wer leitet scholomance","schulleiter"}},{q="Welche Schrecken wurden hier entwickelt?",a="Scholomance war eine frühe Brutstätte für den Kult der Verdammten. Während Akolythen in den Hallen ihr Handwerk erlernten, testeten die Kultisten Prototypvarianten der Plague of Undeath an den Hausdienern der Barovs.",al={"was wurde hier hergestellt","experimente in scholomance","scheusale"}}},fp="11,304,14.507.0,24.424.1,20.241.0,36.242.0,25.195.0,33.207.0"}
P.entries["subzone:scholomance-classic"] = {n="Scholomance (Classic)",s="Scholomance ist eine unterirdische Akademie der Nekromantie, die in den Grüften unter Darrowehr in den Westlichen Pestländern verborgen liegt. Von Kel'Thuzad und dem Kult der Verdammten gegründet, dient sie der Geißel als wichtigste Ausbildungsstätte für sterbliche Zauberwirker, die den Tod beherrschen wollen.",h="Scholomance ist eine unterirdische Akademie der Nekromantie, die in den Grüften unter Darrowehr in den...",kw={"barov","darrowehr","kult der verdammten","gandling","nekromantie","ras frostwhisper","scholomance"},ang={["class:Mage"]="Scholomance ist eine groteske Perversion der Gelehrtentraditionen Dalarans und zeigt, was geschieht, wenn das Wissen der Kirin Tor gänzlich der Nekromantie und dem Verfall gewidmet wird.",["class:Paladin"]="Für die Ritter der Silbernen Hand ist die Säuberung der verdorbenen Hallen unter Darrowehr eine dringliche Pflicht, die direkt auf die Wurzeln der sterblichen Führung der Geißel abzielt."},sec={{t="Eine Schule in den Grüften",b="Bevor der Dritte Krieg Lordaeron verwüstete, suchte der abtrünnige Erzmagier Kel'Thuzad nach Rekruten für seinen Kult der Verdammten. In der wohlhabenden Familie Barov, den Herren von Darrowehr, fand er bereitwillige Gönner, die ihre Ländereien und Grüfte gegen das Versprechen von Unsterblichkeit eintauschten. Stattdessen schlachtete der Kult sie ab und erweckte sie als monströse Untote wieder auf. Unter der zerstörten Festung baute der Kult die uralten arathorischen Katakomben zu einer Akademie für die dunklen Künste um. Hier studieren sterbliche Akolythen fernab wachsamer Blicke Seuchenkunde, Seelenbindung und Fleischformung, um jene abscheulichen Magien zu verfeinern, die Lordaeron zerschmetterten."},{t="Lich und Schulleiter",b="Obwohl Kel'Thuzad weitergezogen ist, um die Operationen der Geißel von oben zu leiten, bleibt die Schule voll einsatzbereit. Der ewige Lich Ras Frostwhisper hält im Namen der Geißel Wache über den Komplex, während der sterbliche Nekromant Dunkelmeister Gandling als Schulleiter fungiert und ehrgeizige Zauberer bei entsetzlichen Experimenten unterweist. Jene Schüler, die Schwäche zeigen, werden in die Katakomben geworfen und an Ravenian verfüttert, einen unersättlichen Ghul, der in den unteren Gewölben lauert."}},faq={{q="Was ist Scholomance?",a="Scholomance ist eine geheime Akademie der Nekromantie, die vom Kult der Verdammten betrieben wird. Tief in den Grüften unter der Inselfestung Darrowehr gelegen, bildet sie sterbliche Zauberwirker in den dunklen Künsten der Geißel aus.",al={"was ist dieser ort","scholomance geschichte","scholomance erklärung"}},{q="Wer herrscht jetzt über Scholomance?",a="Der Lich Ras Frostwhisper beaufsichtigt die Festung im Namen der Geißel, doch die sterblichen Angelegenheiten und der Unterricht werden von Dunkelmeister Gandling geleitet, dem skrupellosen Schulleiter.",al={"wer leitet scholomance","wer hat das sagen","scholomance boss"}},{q="Wie gelangte die Geißel an Darrowehr?",a="Die adelige Familie Barov hielt die Festung nach dem Zweiten Krieg. Verführt von Kel'Thuzads Versprechungen ewigen Lebens überschrieben sie ihren Stammsitz und die Grüfte dem Kult der Verdammten. Der Kult erfüllte den Handel, indem er die Barovs abschlachtete und als Untote wiedererweckte.",al={"barov hintergründe","wem gehörte darrowehr","wie der kult scholomance bekam"}},{q="Warum ist die Schule verschlossen?",a="Das massive Eisentor wurde versiegelt, um die Forschungen und Beschwörer der Akademie vor Eindringlingen zu schützen. Um die Tür zu öffnen, wird der Skelettschlüssel benötigt, der durch ein aufwendiges Ritual quer durch die Pestländer geschmiedet wird.",al={"scholomance tür verschlossen","wie man nach scholomance gelangt","skelettschlüssel scholomance"}}},fp="21,270,21.603.0,19.465.0,20.211.0,26.179.0,40.271.0,25.208.0"}
P.entries["subzone:screaming-gully"] = {n="Screaming Gully",s="Screaming Gully ist die erste weitläufige unterirdische Höhle direkt hinter dem Eingang der Höhlen des Wehklagens. In ein unnatürliches Pilzleuchten und seichte Gewässer getaucht, dient sie als äußere Bastion für die verdorbenen Druids of the Fang und ihre mutierten Bestien.",h="Screaming Gully ist die erste weitläufige unterirdische Höhle direkt hinter dem Eingang der Höhlen des...",kw={"brachland","deviate raptor","fanglords","kresh","lady anakondra","screaming gully","die höhlen des wehklagens"},ang={["class:Druid"]="Für cenarische Druiden ist Screaming Gully ein herzzerreißender Anblick ihrer gefallenen Brüder, die den Pfad der Klaue und des Himmels aufgaben, um sich der schlangenartigen Verderbnis hinzugeben."},sec={{t="Schwelle des Alptraums",b="Wenn Ihr die Schwelle der Höhlen des Wehklagens überschreitet, gelangt Ihr direkt in Screaming Gully, eine widerhallende Schlucht, in der der Wind durch unterirdische Felsspalten stöhnt. Weit entfernt vom trockenen Brachland darüber ist die Schlucht überwuchert von feuchtem Bewuchs, feuchtem Dunst und aggressiver Tierwelt, die durch den Emerald Nightmare verzerrt wurde. Fanglord Lady Anakondra überwacht die Kammer, umgeben von Akolythen der Druids of the Fang und bösartigen Deviate Raptors, während uralte Schnappschildkröten wie Kresh die seichten Wasserwege darunter durchstreifen."}},faq={{q="Wo befindet sich Screaming Gully?",a="Screaming Gully ist die erste große Kammer, die Ihr direkt nach Durchschreiten des Portals in den Höhlen des Wehklagens unterhalb des nördlichen Brachlands betretet.",al={"screaming gully standort","wo ist screaming gully","wie man screaming gully findet"}},{q="Warum heißt es Screaming Gully?",a="Die Höhlen des Wehklagens verdanken ihren Namen den heulenden, stöhnenden Geräuschen, die durch unterirdischen Dampf und Winde entstehen, welche durch Felsspalten entweichen – und diese weite Eingangsschlucht fängt den Großteil dieser widerhallenden Schreie ein.",al={"warum screaming gully","screaming gully namensherkunft"}},{q="Wer herrscht über Screaming Gully?",a="Die Kammer wird von Lady Anakondra überwacht, einer der obersten Fanglords, die an der Seite von Naralex der Verderbnis des Emerald Nightmare anheimfiel.",al={"screaming gully boss","wer ist in screaming gully","screaming gully anführer"}},{q="Welche Kreaturen durchstreifen diese Kammer?",a="Die Schlucht wird von Deviate Raptors, verdorbenen Druids of the Fang und umherstreifenden Wasserlebewesen bewohnt, darunter die uralte Schildkröte Kresh, die den überfluteten Boden durchstreift.",al={"screaming gully mobs","feinde in screaming gully"}}},fx={edd75ba3={q="Was ist die Screaming Gully?",a="Die Screaming Gully ist die erste weitläufige unterirdische Kammer, der Ihr direkt hinter dem Eingang von Die Höhlen des Wehklagens begegnet. Gespeist von unterirdischen Strömen, die sich zu seichten Gewässern auf ihrem Boden ansammeln, hallt dieser höhlenartige Riss von unheimlichen natürlichen Geräuschen und dem Zischen korrumpierter Wildtiere wider und dient als Frontlinie des Albtraums, der in den Tiefen Wurzeln schlägt.",al={"was ist die screaming gully","screaming gully übersicht","screaming gully hintergrund"}}},fp="15,265,26.511.0,37.165.0,37.209.0,35.145.0,33.162.0"}
P.entries["subzone:scuttle-coast"] = {fx={d351211f={q="Was ist die Schipperküste?",a="Die Schipperküste ist die felsige östliche Küste von Durotar, die Das große Meer zugewandt ist, südöstlich von Klingenhügel und nördlich von Burg Tiragarde. Es ist ein windgepeitschter Strandabschnitt mit zerklüfteten Untiefen, der berüchtigt für maritime Katastrophen und tückische Gewässer ist.",al={"was ist die schipperküste","schipperküste hintergrund","erzähl mir von der schipperküste"}}}}
P.entries["subzone:sea-of-cinders"] = {n="Das Meer der Asche",s="Das Meer der Asche ist ein Landstrich aus versengtem, windgepeitschtem Terrain im südlichen Teil der Sengenden Schlucht, direkt nördlich des Schwarzfels. Heimgesucht von elementarer Hitze und unbarmherzigen Böen stößt der flache Boden unaufhörlich Asche und Glut aus, was ein erstickendes Ödland schafft, in dem nur sehr wenig überdauern kann.",h="Das Meer der Asche ist ein Landstrich aus versengtem, windgepeitschtem Terrain im südlichen Teil der...",kw={"asche","der schwarzfels","dunkeleisen","glut","ragnaros","das meer der asche","sengende schlucht","ödland"},ang={["profession:Mining"]="Der unbeständige, von Hitze rissige Stein am Rande des Schwarzfels gibt für all jene, die mutig genug sind, inmitten der treibenden Asche zu schürfen, häufig reiche Mineralvorkommen und Dunkeleisenerzadern frei.",["race:Dwarf"]="Für Bronzebeard- und Wildhammerzwerge ist der Gang durch diese brennenden Weiten eine düstere Erinnerung an Thaurissans Torheit und die finsteren Mächte, die das Rotkammgebirge zerschmetterten."},sec={{t="Ein Ödland aus Glut",b="Zwischen den felsigen Klippen der Sengenden Schlucht und der imposanten Masse des Schwarzfels gelegen, verdankt das Meer der Asche seinen Namen dem erstickenden Dunst aus Partikeln und brennendem Schutt, der unablässig über seine Ebenen fegt. Als der Feuerfürst Ragnaros vor Jahrhunderten in die sterbliche Welt beschworen wurde, spaltete der gewaltige Umbruch das Rotkammgebirge und verwandelte die umliegende Landschaft in eine verdorrte Schlackenhalde. Das Meer der Asche gehört zu den kargsten Überresten dieser Katastrophe – eine unbewohnbare Ebene, auf der die Erde selbst sich weigert abzukühlen."},{t="Gefahr unter den Hängen",b="Da es an den nördlichen Zugang zum Schwarzfels grenzt, haben Reisende und Plünderer oft keine andere Wahl, als diese sengenden Weiten zu durchqueren. Die Winde wirbeln hier dichte Wolken blendender Asche auf, die plötzliche Spalten, elementare Schrecken und an die glühende Hitze angepasste Raubtiere verbergen. Zwischen der feindseligen Umgebung und der bedrohlichen Präsenz der Dunkeleisenzwerge, die Anspruch auf diese Region erheben, erfordert jeder Zug durch die Asche Wachsamkeit und ein schnelles Vorankommen."}},faq={{q="Was ist das Meer der Asche?",a="Es ist ein trostloses, aschebedecktes Flachland im Süden der Sengenden Schlucht, direkt an der Nordflanke des Schwarzfels. Es ist von schwelender Erde und umherfliegender Glut überzogen.",al={"was ist das meer der asche","meer der asche geschichte","wo liegt das meer der asche"}},{q="Warum brennt der Boden unaufhörlich?",a="Die Region wurde vor Jahrhunderten völlig verwüstet, als Zauberer-Thane Thaurissan während des Kriegs der drei Hämmer den Feuerfürsten Ragnaros beschwor. Der katastrophale Ausbruch erhitzte die Erde extrem und zerschmetterte die Berge, wodurch Ebenen zurückblieben, die bis zum heutigen Tag schwelen.",al={"warum brennt es","warum gibt es asche","warum raucht der boden"}},{q="Lebt hier jemand?",a="Innerhalb des Meers der Asche existiert keine organisierte Siedlung. Die erstickende Hitze, die schlechte Luft und der Mangel an Wasser machen eine dauerhafte Besiedlung unmöglich, sodass das Gebiet nur von umherstreifenden Bestien, Feuerelementaren und mit dem Schwarzfels verbündeten Patrouillen bevölkert wird.",al={"wer lebt hier","meer der asche bewohner","siedlungen"}},{q="Was macht das Reisen hier so gefährlich?",a="Abgesehen von der feindseligen Fauna und den Dunkeleisenzwergen, die in der Nähe des Berges lauern, ist die Umgebung selbst tödlich. Die Luft ist erfüllt von blendendem Ruß und brennender Asche, und tiefe thermische Klüfte durchziehen das flache Gelände.",al={"ist es sicher","gefahren im meer der asche"}}},fp="14,313,21.560.0,24.462.0,27.182.0,37.270.0,22.272.0,44.212.0"}
P.entries["subzone:sen-jin-village"] = {fx={["8cd2719d"]={q="Was ist Sen'jin?",a="Sen'jin ist eine Küstenfischersiedlung am südlichen Ufer von Durotar, die als wichtigste Zuflucht auf dem Festland für die Dunkelspeer-Trolle dient. Gegründet, nachdem der Stamm der Dunkelspeere von den Echoinseln vertrieben wurde, ist es eine bescheidene Ansammlung von Hütten, Docks und Raptorengehegen, wo Trollflüchtlinge, Hexendoktoren und Späher Wache über ihre verlorene Heimat halten.",al={"was ist sen'jin","sen'jin übersicht","sen'jin hintergrund"}},fb8d4411={q="Was ist in Sen'jin geschehen?",a="Als der Hexendoktor Zalazane den Stamm der Dunkelspeere verriet und mit dunklem Voodoo die Kontrolle über Die Echoinseln übernahm, führte Vol'jin die überlebenden Trolle über das Wasser zur Südküste von Durotar. Dort errichteten sie dieses Dorf als vorübergehendes Heiligtum und militärischen Stützpunkt und benannten es zu Ehren von Vol'jins gefallenem Vater, während sie Pläne schmiedeten, ihre Heimat zurückzuerobern.",al={"sen'jin geschichte","geschichte von sen'jin","wie wurde sen'jin gegründet"}},f928ac6d={q="Wer lebt in Sen'jin?",a="Die Siedlung wird fast ausschließlich von exilierten Dunkelspeertrollen bewohnt. Örtliche Jäger, Schattenjäger, Kräuterkundige und Alchemisten arbeiten in den Hütten und an den Docks, verteidigen die Küste und sammeln Ressourcen, um die umfassenderen Kriegsanstrengungen der Dunkelspeere unter der Führung von Häuptling Vol'jin zu unterstützen.",al={"wer lebt in sen'jin","wer führt sen'jin","anführer von sen'jin"}},["5cc89452"]={q="Ist Sen'jin gefährlich?",a="Das Dorf selbst wird schwer von Sen'jin-Axtwerfern und Schamanen bewacht und bietet Sicherheit innerhalb seiner Grenzen. Jedoch lauert die Gefahr direkt dahinter: Zalazanes gedankenkontrollierte Trolle bewohnen die nahen Die Echoinseln, während die umliegenden Ufer von aggressiven Wildtieren und vordringenden Meereskreaturen geplagt werden.",al={"ist sen'jin sicher","bedrohungen für sen'jin","gefahren in sen'jin"}}}}
P.entries["subzone:sentinel-hill"] = {n="Späherkuppe",s="Die Späherkuppe ist die wichtigste Bastion der Allianz in Westfall und dient als Command Center für die Volksmiliz. Umgeben von überwucherten Feldern, plündernden Gnollen und feindseligen Gesetzlosen ist diese befestigte Anhöhe der einzige sichere Stützpunkt für gesetzestreue Bürger in der Region.",h="Die Späherkuppe ist die wichtigste Bastion der Allianz in Westfall und dient als Command Center für die...",kw={"gryan starkmantel","gryphon roost","die volksmiliz","gnolle der flussufer","späherkuppe","sentinel tower","westfall"},ang={["faction:Alliance"]="Die Späherkuppe ist Euer einziger befestigter Vorposten und Versorgungsknotenpunkt in Westfall, der die Präsenz der Allianz gegen Gesetzlose und Plünderer sichert.",["race:Human"]="Zu sehen, wie die Bauern von Westfall hier gezwungen sind, ihre eigene Miliz aufzustellen, spiegelt die sich vertiefende Krise des Königreichs wider, während der Thron unbesetzt bleibt."},sec={{t="Eine Bastion im Staub",b="Auf einer Anhöhe im Herzen von Westfall gelegen, bildet die Späherkuppe eine überlebenswichtige Zuflucht in einem ansonsten gesetzlosen Gebiet. Sie verfügt über ein kasernenartiges Gasthaus, einen Gryphon Roost, der Reisende mit Sturmwind und darüber hinaus verbindet, eine Schmiede und ein Sägewerk – alles verankert durch den imposanten Sentinel Tower. Während das Umland dem Banditentum und hungrigen Bestien anheimgefallen ist, hält das Lager eine zerbrechliche Verteidigungslinie aufrecht, an der sich Reisende, bedrängte Bauern und Rekruten unter den wachsamen Augen erfahrener Verteidiger neu sammeln können."},{t="Das Herz der Miliz",b="Da die königliche Armee in Sturmwind gebunden ist und keine Soldaten zum Schutz der abgelegenen Gebiete entbehren kann, gründete Gryan Starkmantel direkt auf diesem Hügel die Volksmiliz. Von hier aus organisieren freiwillige Kämpfer Spähtrupps, koordinieren Angriffe gegen die Gnolle der Flussufer und untersuchen das organisierte Banditentum, das Westfalls verlassene Bauernhöfe heimsucht. Die Späherkuppe ist weder eine prächtige Festung noch eine bequeme Zuflucht, sondern ein funktionierendes Frontlager, fest entschlossen, die einstige Kornkammer des Königreichs zurückzuerobern."}},faq={{q="Warum hat Sturmwind keine Soldaten entsandt, um die Späherkuppe zu verteidigen?",a="Da König Varian Wrynn verschwunden ist und die Ressourcen im gesamten Reich knapp sind, hat die Regentschaft von Sturmwind die westlichen Provinzen weitgehend sich selbst überlassen. Einheimische Bürger und Veteranen mussten die Volksmiliz selbst ins Leben rufen, um die Späherkuppe zu halten und zu schützen, was von Westfall noch übrig ist.",al={"warum keine wachen aus sturmwind","wo ist die armee von sturmwind","warum miliz hier"}},{q="Wer hat das Kommando auf der Späherkuppe?",a="Gryan Starkmantel befehligt die Volksmiliz vom Fuße des Sentinel Tower aus. Er koordiniert die örtliche Verteidigung, sammelt Informationen über Bedrohungen in der Umgebung und weist durchreisende Abenteurer an, gegen die Gnolle und Wegelagerer vorzugehen, die die Siedlung bedrängen.",al={"wer leitet die späherkuppe","kommandant späherkuppe","gryan starkmantel"}},{q="Welche Gefahren bedrohen den Hügel akut?",a="Das Lager steht unter ständigem Druck durch aggressive Gnolle der Flussufer, die die westlichen Ebenen durchstreifen, sowie durch die heimtückische, koordinierte Sabotage durch die Bruderschaft der Defias, die sich auf den verlassenen Höfen versteckt hält.",al={"was greift die späherkuppe an","feinde späherkuppe","wer greift an"}},{q="Welche Dienste stehen Reisenden hier zur Verfügung?",a="Die Späherkuppe bietet alle Annehmlichkeiten eines Grenzpostens: einen Greifenmeister mit Verbindungen nach Sturmwind und zu anderen Vorposten der Allianz, einen Gastwirt, einen Briefkasten, Händler für Handwerksbedarf und Reparaturmöglichkeiten rund um die örtliche Schmiede.",al={"späherkuppe angebote","späherkuppe flugpunkt","gibt es hier ein gasthaus"}}},fx={["3c1a5a7a"]={q="Was ist die Späherkuppe?",a="Die Späherkuppe ist der zentrale Außenposten der Allianz in Westfall. Erbaut um einen markanten Wachturm mit Blick auf die Ebenen, dient sie als operatives Hauptquartier für The People's Militia. Umgeben von vordringenden Gesetzlosen und Gnollen bietet die Kuppe müden Reisenden ein seltenes Bollwerk der Sicherheit mit einem Flugmeister, einem Gasthaus, einer Schmiede und lebensnotwendigen Vorräten.",al={"was ist die späherkuppe","über die späherkuppe","späherkuppe westfall"}},fc9f9bfd={q="Ist die Späherkuppe gefährlich?",a="Innerhalb des unmittelbaren Umkreises um den Turm und das Gasthaus halten Euch die Wachen vor Schaden fern. Die umliegenden Hänge und Ebenen sind jedoch außerordentlich gefährlich. Flusspfotengnolle streifen in der Nähe der Straßen umher, schurkische Erntewächter wandern durch nahegelegene Felder und Defias-Banditen patrouillieren aktiv in dem Gebiet direkt außerhalb der Grenzen des Außenpostens.",al={"ist die späherkuppe sicher","gefahr späherkuppe","sicherheit späherkuppe"}}},fp="13,276,21.516.0,20.514.0,59.292.0,34.253.0,40.211.0,47.234.0"}
P.entries["subzone:sentinel-tower"] = {n="Sentinel Tower",s="Der Sentinel Tower krönt den Gipfel der Späherkuppe und dient als wichtigster Aussichtspunkt sowie als Hauptquartier für die Verteidiger in Westfall. Von seinen Höhen aus organisieren Gryan Starkmantel und die Volksmiliz ihre verzweifelte Verteidigung gegen Banditen, Gnolle und den wachsenden Schatten der Bruderschaft der Defias.",h="Der Sentinel Tower krönt den Gipfel der Späherkuppe und dient als wichtigster Aussichtspunkt sowie als...",kw={"defias","gryan starkmantel","volksmiliz","späherkuppe","sentinel tower","wachturm","westfall"},ang={["faction:Alliance"]="Der Sentinel Tower steht für den Mut gewöhnlicher Untertanen der Allianz, die für ihre Heimat kämpfen, während die hohen Herren in Sturmwind die Augen verschließen.",["race:Human"]="Für die Menschen des Königreichs ist der Turm eine schmerzhafte Erinnerung daran, dass die landwirtschaftliche Kornkammer von Sturmwind angesichts einer hausgemachten Rebellion nur noch mit Mühe zusammenhält."},sec={{t="Wacht über den wilden Westen",b="Auf dem Kamm der Späherkuppe errichtet, ist der Sentinel Tower das militärische Herz des unruhigen Westfall. Da Sturmwinds offizielle Armee größtenteils abwesend ist und Hilfe verwehrt, schlossen sich örtliche Freiwillige und Veteranen zusammen, um eine zentrale Redoute zu schaffen. Der Steinturm gewährt den Spähern einen ununterbrochenen Blick über die staubigen Ebenen, von den verlassenen Kürbisfeldern bis zu den nebligen Ufern, und warnt frühzeitig, wenn abtrünnige Straßenräuber oder Gnoll-Plündertrupps umherstreifen."},{t="Hauptquartier der Miliz",b="Der Turm dient Gryan Starkmantel und dem Kern der örtlichen Führung als Kommandoposten. Umgeben von behelfsmäßigen Verteidigungsanlagen, verwundeten Flüchtlingen und müden Soldaten fungiert er sowohl als Verwaltungszentrum als auch als Notunterkunft für Siedler, die von ihrem Land vertrieben wurden. Hier werden Informationen über die Bruderschaft der Defias zusammengetragen, um Freiwillige für geschlossene Schläge gegen das Syndikat zu koordinieren, welches die Provinz ins Verderben gestürzt hat."}},faq={{q="Wer hat das Kommando am Sentinel Tower?",a="Gryan Starkmantel leitet die Operationen vom Turm aus. Als Anführer der Volksmiliz koordiniert er die Verteidigung der vertriebenen Bauern von Westfall und verwaltet die Rekrutierung hilfsbereiter Abenteurer.",al={"sentinel tower anführer","wer führt sentinel tower","wer leitet den turm"}},{q="Warum ist der Turm für Westfall so wichtig?",a="Er ist die einzige befestigte Garnison und der letzte Ausguckposten in den zentralen Ebenen. Weil Sturmwind Westfall weitgehend unverteidigt gelassen hat, dient der Turm als letzte organisierte Bastion der Ordnung und Sicherheit für die Flüchtlinge in der Region.",al={"warum sentinel tower wichtig ist","zweck von sentinel tower"}},{q="Wer hält sich im und um den Turm auf?",a="Ihr werdet dort Milizoffiziere, Wache haltende Späher, Rüstmeister und fliehende Bauernfamilien vorfinden, die ihr verwüstetes Land verlassen haben, um in der Nähe der robusten Steinmauern Schutz zu suchen.",al={"wer ist am sentinel tower","sentinel tower bewohner"}},{q="Welche Bedrohungen werden vom Turm aus beobachtet?",a="Die Späher überwachen die Bewegungen der Flussufergnolle, verirrte Murlocs, die von der Küste landeinwärts kriechen, und vor allem die umherziehenden Wegelagerer und Räuber der Bruderschaft der Defias.",al={"sentinel tower feinde","wovor schützt der turm"}}},fx={["226a51b2"]={q="Was ist der Sentinel Tower?",a="Der Sentinel Tower ist ein markanter Spähturm, der auf der Späherkuppe im Zentrum von Westfall thront. Er wurde als befestigte Festung und Command Center für The People's Militia errichtet und ermöglicht es Gryan Starkmantel und seinen Spähern, die wogenden Ebenen zu überblicken und feindliche Bewegungen in der gesamten Region zu überwachen.",al={"was ist der sentinel tower","sentinel tower westfall","über den sentinel tower"}},["3b2e4075"]={q="Ist der Sentinel Tower gefährlich?",a="Der Turm selbst ist sicher für Reisende der Allianz und dient als schwer bewachtes Nervenzentrum von The People's Militia. Die umliegenden Hügel sind jedoch voller Gefahren und werden ständig von Defias-Banditen, feindseligen Flusspfotengnollen und umherstreifenden mechanischen Erntewächtern bedrängt.",al={"ist der sentinel tower sicher","ist der sentinel tower gefährlich","gefahr sentinel tower"}}},fp="14,299,24.456.0,27.450.0,35.196.0,42.229.0,34.188.0,40.185.0"}
P.entries["subzone:sepulcher"] = {n="Das Grabmal",s="Das Grabmal ist die wichtigste Siedlung und Festung der Verlassenen im Silberwald. Einst ein gewöhnlicher Friedhof und eine Grabkrypta von Lordaeron mit Blick auf die Westküste, dient es der Horde heute als befestigte Zuflucht gegen die regionalen Bedrohungen der Umgebung.",h="Das Grabmal ist die wichtigste Siedlung und Festung der Verlassenen im Silberwald.",kw={"krypta","todeswache","außenposten der verlassenen","friedhof","grabmal","silberwald","grabmal im silberwald"},ang={["faction:Horde"]="Für jeden Reisenden der Horde, der sich von Tirisfal aus nach Süden wagt, bietet das Grabmal auf Meilen hinaus die einzige verlässliche Zuflucht samt Reparaturmöglichkeiten und Flugverbindung.",["race:Undead"]="Das Grabmal ist der Ausgangspunkt für den Kampf der Verlassenen um die Befriedung des Silberwalds und leitet Operationen gegen verbliebene Loyalisten der Geißel, Reste der Kirin Tor und wilde Worgen."},sec={{t="Ein Sanktum im Nebel",b="In den Hügeln über der Küste von Lordaeron gelegen, war das Grabmal ursprünglich ein ruhiger Friedhof samt Krypta an der Weststraße. Im Zuge des Dritten Krieges funktionierten die frisch emanzipierten Verlassenen das uralte Steingewölbe und sein Gelände zu einem unverzichtbaren Außenposten um. Umgeben von feindlichen Kräften auf allen Seiten – den wilden Worgen im Süden, umherstreifenden Überresten der Geißel im Osten und Magiern der Kirin Tor, die von Mühlenbern aus wachen – bietet das Grabmal einen seltenen Zufluchtsort voller Sicherheit, Vorräte und Führung für Reisende, die durch den Silberwald ziehen."}},faq={{q="Was war das Grabmal, bevor die Verlassenen einzogen?",a="Vor dem Dritten Krieg und dem Fall des Königreichs Lordaeron war es schlicht ein Friedhof am Wegesrand mit einer Steinkrypta, auf dem die einheimischen Dorfbewohner ihre Toten begruben.",al={"geschichte des grabmals","was war das grabmal","wer erbaute das grabmal"}},{q="Warum ist das Grabmal für die Verlassenen so wichtig?",a="Es dient als einziger befestigter Stützpunkt der Verlassenen im Silberwald. Von dieser zentralen Position aus können Späher und Kommandanten der Verlassenen vordringende Magier aus Dalaran, verbliebene Nester der Geißel und die sich ausbreitende, bestialische Worgenbedrohung nahe Burg Shadowfang überwachen.",al={"warum ist das grabmal wichtig","verlassene im silberwald","rolle des grabmals"}},{q="Sind Reisende anderer Völker der Horde hier willkommen?",a="Ja. Obwohl der Stützpunkt vollständig von Todeswachen, Händlern und Apothekern der Verlassenen verwaltet und bewohnt wird, fungiert er als offizielle Zuflucht der Horde, die Orcs, Trollen und Tauren auf der Durchreise Rast und Handel bietet.",al={"können orcs zum grabmal","ist das grabmal hordefreundlich","horde beim grabmal"}},{q="Welche Bedrohungen umgeben das Grabmal?",a="Die Siedlung ist von feindlichen Mächten eingekesselt: Streitkräfte der Geißel streifen im Osten umher, die Kirin Tor halten Mühlenbern im Südosten besetzt, und wilde Worgen lauern in den Wäldern im Süden.",al={"bedrohungen für das grabmal","feinde im silberwald","was greift das grabmal an"}}},fx={d7b2f06c={q="Ist das Grabmal gefährlich?",a="Innerhalb seiner Grenzen ist das Grabmal ein sicherer Zufluchtsort, der von Wachen der Verlassenen geschützt wird. Außerhalb seiner Grenzen ist das Gebiet jedoch gefährlich. Feindselige Worgen streifen im Süden umher, die Geißel lauert im Osten und Agenten der Kirin Tor beobachten die Gegend vom Südosten aus, was den Außenposten zu einem isolierten Refugium in feindlichem Gebiet macht.",al={"ist das grabmal sicher","gefahr grabmal"}},["70fd5666"]={q="Was ist Das Grabmal?",a="Das Grabmal ist die primäre Siedlung und Festung der Verlassene im Silberwald. Eingebettet in die Hügel mit Blick auf die westliche Küste von Lordaeron dient es als operatives Zentrum für die Bemühungen der Horde in der gesamten Region und bietet einen sicheren Hafen mit Spähern, Händlern und Ausbildern.",al={"was ist das grabmal","grabmal silberwald"}},["2b930170"]={q="Warum heißt es Das Grabmal?",a="Bevor die Verlassene es als Außenposten befestigten, war der Ort einfach ein Friedhof und eine Krypta entlang der Straße im Silberwald. Ein Grabmal ist eine Grabstätte oder ein Begräbnisgewölbe, und die Verlassene behielten den passenden Namen bei, als sie die uralte Krypta in ihre Militärbasis verwandelten.",al={"warum heißt es grabmal","bedeutung des namens grabmal","warum nennt man es grabmal"}}},fp="9,261,20.549.0,52.153.0,46.254.0,58.231.0,36.178.0"}
P.entries["subzone:sewers"] = {n="Sewers",s="Die Kanalisation ist ein weitläufiges unterirdisches Entwässerungssystem, das einen zweiten direkten Zugang zur Unterstadt bietet. Dieser Verbindungstunnel verläuft unter den Hügeln westlich der Ruinen von Lordaeron und ermöglicht Fledermausführern sowie verstohlenen Reisenden, die unsicheren Aufzüge, die vom Thronsaal nach unten führen, zu umgehen.",h="Die Kanalisation ist ein weitläufiges unterirdisches Entwässerungssystem, das einen zweiten direkten Zugang...",kw={"hintertür","fledermausführer","entwässerung","flugpunkt","lordaeron","kanalisation","tirisfal","unterstadt"},ang={["faction:Alliance"]="Jeder, der töricht oder mutig genug ist, die Hauptstadt der Verlassenen anzugreifen, weiß, dass die Kanalisation den einzigen verdeckten Weg an den stark verteidigten oberirdischen Ruinen vorbei bietet.",["race:Undead"]="Für die Verlassenen sind die Kanäle eine unverzichtbare Lebensader und ein Flugkorridor, der die Unterstadt mit dem Rest von Lordaeron verbunden hält, ohne den Verkehr an den Aufzügen im Innenhof aufzustauen."},sec={{t="Ein Hintereingang in die Katakomben",b="Bevor die Seuche Lordaeron auslöschte, dienten diese steinernen Durchlässe als gewöhnliche Abwasserkanäle der königlichen Hauptstadt. In den Händen der Verlassenen von Sylvanas Windläufer wurden die Abflusstunnel jedoch in die äußere Verteidigung der Unterstadt integriert. Der Durchgang tritt westlich der oberirdischen Ruinen nahe einem umkämpften Wachturm der Scharlachroten in Tirisfal an die Oberfläche und bietet einen ebenen, direkten Zugang nach innen. Die Fledermausführer der Verlassenen nutzen diesen höhlenartigen Tunnel, um Reiter schnell in die unterirdischen Ringe zu fliegen und die langsamen Käfigaufzüge vollständig zu vermeiden. Da dieser Weg die stark befestigten oberirdischen Innenhöfe umgeht, bleibt er eine gefährliche Schwachstelle, die feindliche Infiltratoren ständig auszunutzen versuchen."}},faq={{q="Wohin führt der Kanaltunnel nach außen?",a="Der Tunnel mündet in die sanften Hügel von Tirisfal, direkt westlich der Haupttore der Ruinen von Lordaeron. Er liegt unweit des Wachturms der Scharlachroten mit Blick auf den See.",al={"ausgang unterstadt kanalisation","wohin führen die kanäle","hintereingang kanalisation"}},{q="Warum sollte jemand die Kanalisation anstelle des Haupteingangs benutzen?",a="Der Hauptweg in die Unterstadt erfordert die Nutzung der eisernen Käfigaufzüge von den Palastruinen aus, was langsam sein und während eines Angriffs gefährlich werden kann. Die Kanalisation ist eine direkte, rampenartige Route, die den Fledermaustransport der Verlassenen abwickelt und schnellen Auslass ermöglicht, ohne auf Aufzüge warten zu müssen.",al={"warum kanalisation nutzen","kanalisation vs aufzüge","unterstadt hintertür"}},{q="Ist die Kanalisation sicher vor Angriffen der Allianz?",a="Kaum. Da sie das befestigte Torhaus und den Thronsaal von Lordaeron umgeht, ist die Kanalisation der bevorzugte Durchbruchspunkt für waghalsige Späher und Angriffstrupps der Allianz, die versuchen, sich direkt in die Hauptstadt der Verlassenen zu schleichen.",al={"allianz angriff kanalisation","wird die kanalisation bewacht","unterstadt verteidigung kanalisation"}}},fx={["833a18e0"]={q="Was sind die Abwasserkanäle der Unterstadt?",a="Die Abwasserkanäle dienen als weitläufiges Entwässerungssystem unter den Ruinen von Lordaeron, das in Tirisfal mündet, direkt westlich der Palasttore. Anstatt sich auf die riskanten Palastaufzüge zu verlassen, nutzen viele Reisende der Verlassenen und Fledermausführer diese üblen Tunnel als alternativen Weg direkt in das unterirdische Herz der Unterstadt.",al={"was sind die abwasserkanäle","unterstadt abwasserkanäle","abwasserkanäle unterstadt"}}},fp="6,312,29.696.0,41.190.0,61.273.0,40.221.0"}
P.entries["subzone:shadow-grave"] = {fx={["742f7843"]={q="Ist das Schattengrab gefährlich?",a="Die Krypta selbst bleibt relativ sicher und steht unter der wachsamen Obhut der hier stationierten Betreuer der Verlassenen, die den neu Erweckten beistehen. Doch gleich hinter ihrem steinernen Tor lauern die Gefahren von Tirisfal, wo hirnlos umherstreifende Untote der Geißel, Aasfresser und die allzeit wachsamen Agenten der Scarlet Crusade jeden bedrohen, der sich unvorbereitet zu weit hinauswagt.",al={"ist das schattengrab gefährlich","schattengrab sicher","gibt es feinde im schattengrab"}}}}
P.entries["subzone:shadow-hold"] = {n="Schattenfeste",s="Die Schattenfeste ist ein weitläufiger unterirdischer Komplex, der in der verdorbenen Schlucht von Jaedenar im westlichen Teufelswald verborgen liegt. Einst ein heiliger Grabhügel der Nachtelfen, wurde sie vom Schattenrat eingenommen und geschändet, um als dessen wichtigste Bastion auf Kalimdor zu dienen.",h="Die Schattenfeste ist ein weitläufiger unterirdischer Komplex, der in der verdorbenen Schlucht von Jaedenar...",kw={"arko'narin","banehollow","grabhügel","fel'dan","teufelswald","jaedenar","schattenrat","schattenfeste","trey lightforge"},ang={["class:Warlock"]="In den tiefsten Winkeln der Schattenfeste lagern seltene dämonische Reagenzien wie Xorothianischer Sternenstaub, der nur erlangt werden kann, wenn man sich durch geschickte Infiltration die Gunst von Lord Banehollow verdient.",["race:NightElf"]="Die Feste bietet Nachtelfen einen grauenvollen Anblick – ein uralter Grabhügel, geschändet durch Teufelsschlamm, Gefängniskäfige und dämonische Rituale."},sec={{t="Ein geschändetes Heiligtum",b="Unter der verdorbenen roten Erde von Jaedenar liegt die Schattenfeste, ein gewaltiges unterirdisches Labyrinth, das aus einem uralten Grabhügel der Nachtelfen gehauen wurde. Wo einst schlafende Druiden ruhten, um den Smaragdgrünen Traum zu pflegen, durchstreifen nun finstere Hexenmeister und dämonische Diener gewundene, von Teufelsfeuer erleuchtete Korridore. Auf ihren tiefsten Ebenen befehligt der Kult unter dem Schreckenslord Lord Banehollow, Prinz Xavalis und Schattenlord Fel'dan eine furchterregende Streitmacht, was sie zum obersten Sitz dämonischen Einflusses in der Region macht."},{t="Schrecken in der Tiefe",b="Der Schattenrat nutzt die Höhlen, um seine Verderbnis des Teufelswalds zu koordinieren und grausame Verhöre durchzuführen. Späher der Allianz, darunter die Nachtelfe Arko'narin Starshade und der menschliche Paladin Trey Lightforge, fielen tief im Inneren der Feste in die Hände der Kultisten. Während Arko'narin durch eine rechtzeitige Rettung überlebte, wurde Trey von den Folterern des Kults zu Tode gequält; sein Geist wurde kurzzeitig in Bosheit verdreht, bevor er zur Ruhe gebettet werden konnte. Der Smaragdkreis und einheimische Schamanen arbeiten unablässig daran, die finsteren Barrieren zu durchdringen, die die Feste abschirmen, in der Hoffnung, ihre dämonischen Meister zu bezwingen."}},faq={{q="Was war die Schattenfeste, bevor der Schattenrat sie übernahm?",a="Die Schattenfeste war ursprünglich ein uralter Grabhügel der Nachtelfen, der den schlummernden Druiden geweiht war, die das Land pflegten und mit dem Smaragdgrünen Traum eins waren. Nach dem Dritten Krieg und der dämonischen Verderbnis des Teufelswalds riss der Schattenrat den unterirdischen Komplex an sich und schändete seine heiligen Hallen zu einer Teufelsfestung.",al={"geschichte der schattenfeste","wer erbaute die schattenfeste","was war die schattenfeste ursprünglich"}},{q="Wer herrscht im Inneren der Schattenfeste?",a="Die Festung wird von dem Schreckenslord Lord Banehollow beaufsichtigt, an der Seite mächtiger Leutnants wie dem Satyr Prinz Xavalis und dem Hexenmeister Schattenlord Fel'dan, der die sterblichen Kultisten befehligt.",al={"schattenfeste boss","wer hat die führung der schattenfeste","anführer der schattenfeste"}},{q="Warum sollte ein Abenteurer die Schattenfeste friedlich infiltrieren?",a="Praktizierende der dunklen Künste, die auf der Suche nach mächtigen Beschwörungsreagenzien wie Xorothianischem Sternenstaub sind, betreten die Feste zuweilen getarnt als loyale Kultisten des Schattenrats. Lord Banehollow erlaubt den Handel mit Außenstehenden nur dann, wenn sie ihre Treue beweisen, indem sie Spione und Verräter in seinen Reihen aufspüren.",al={"schattenfeste infiltrieren","schattenrat tarnung schattenfeste","xorothianischer sternenstaub schattenfeste"}},{q="Was geschah mit den Gefangenen in der Feste?",a="Die Nachtelfe Arko'narin Starshade und der Paladin Trey Lightforge wurden gefangen genommen, als sie den Schattenrat auskundschafteten. Trey wurde von der Kultistin Rakaiah zu Tode gefoltert, während Arko'narin von Abenteurern aus ihrem Käfig befreit wurde, die später auch Treys sterbliche Überreste für ein würdiges Begräbnis bargen.",al={"jaedenar gefangene","trey lightforge und arkonarin","schattenfeste käfig"}}},fp="11,252,19.501.0,19.573.1,60.318.0,29.197.0,58.293.1,42.281.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="Schattenklamm",s="Die Schattenklamm ist eine abgelegene Bergsenke, die im südöstlichen Desolace verborgen liegt. Versteckt inmitten zerklüfteter Felsen nahe Magram, dient diese unheimliche Schlucht als verborgener Zufluchtsort für die dämonischen Streitkräfte und sterblichen Eiferer der Burning Blade.",h="Die Schattenklamm ist eine abgelegene Bergsenke, die im südöstlichen Desolace verborgen liegt.",kw={"burning blade","kultisten","dämonen","desolace","teufelsmagie","schattenklamm","magram"},ang={["class:Warlock"]="Die dunklen Beschwörungskreise und die konzentrierte Teufelspräsenz machen diese geheime Schlucht zu einem deutlichen Zeugnis für die Reichweite der dunklen Künste der Burning Blade."},sec={{t="Eine verborgene Enklave der Teufelsmagie",b="Tief in den kargen Gebirgszügen südöstlich von Magram gelegen, bietet die Schattenklamm der Burning Blade einen abgelegenen Aufmarschort fernab der Blicke wandernder Zentaurenstämme. Inmitten seltsamer, übergroßer Pilze und finsterer Rituallager arbeiten Kultisten an der Seite beschworener Dämonen. Hier rufen dunkle Praktizierende Teufelsenergien an und pflegen schwere Ritualketten, wobei sie die natürliche Abgeschiedenheit der Schlucht nutzen, um Verstärkung zusammenzuziehen und einen festen dämonischen Stützpunkt im Ödland von Desolace aufrechtzuerhalten."}},faq={{q="Was ist die Schattenklamm?",a="Die Schattenklamm ist eine verborgene Bergschlucht im südöstlichen Desolace, gleich hinter Magram. Sie dient als verborgenes Lager und Aufmarschort für dämonische Diener und Kultisten im Dienste der Burning Blade.",al={"infos zur schattenklamm","was ist dieser ort","wo ist die schattenklamm"}},{q="Wer hält die Schlucht besetzt?",a="Die Schlucht ist von Kultisten der Burning Blade besetzt, die direkt Seite an Seite mit Dämonen arbeiten. Sie nutzen das geschützte Terrain der Schlucht, um dunkle Rituale zu vollziehen und ihre umfassendere Offensive in der gesamten Region zu unterstützen.",al={"wer lebt hier","schattenklamm mobs","gegner in der schattenklamm"}},{q="Welche Besonderheiten finden sich in der Schlucht?",a="Die Schlucht birgt dunkle Ritualbauten, massive Eisenketten und markante Riesenpilze, die inmitten der von Teufelsmagie verdorbenen Lager in den Bergspalten sprießen.",al={"was befindet sich in der schattenklamm","sehenswürdigkeiten in der schattenklamm"}}},fp="18,243,23.515.0,27.218.0,24.209.0,45.176.0"}
P.entries["subzone:shadowfang-keep"] = {fx={b733cd78={q="Was ist Burg Shadowfang?",a="Burg Shadowfang ist eine heimgesuchte Festung, die hoch auf einer felsigen Klippe im südlichen Silberwald thront und direkt über Lohenscheit in der Nähe des Greymane-Walls aufragt. Ursprünglich der Stammsitz von Baron Silberlein, wurde die Festung während des Dritten Krieges von wilden Worgen überrannt, die heraufbeschworen wurden. Heute steht sie als abgeschiedenes Versteck des wahnsinnigen Erzmagiers Arugal, bewacht von gefräßigen Bestienmenschen, spektralen Verteidigern und verdrehter Zauberei.",al={"was ist burg shadowfang","burg shadowfang lore","burg shadowfang"}},cc8ad05a={q="Was geschah in Burg Shadowfang?",a="Während des Dritten Krieges versuchte Erzmagier Arugal, die Geißel zurückzuschlagen, indem er die Forschungen von Ur nutzte, um außerdimensionale Worgen nach Azeroth zu beschwören. Obwohl die Bestien die Untoten niedermetzelten, wüteten sie bald ungebremst im Silberwald und belagerten die Festung von Baron Silberlein. Die Worgen schlachteten den Baron, seine Familie und seine Garnison ab. Vom Wahnsinn durch Schuld und Entsetzen getrieben, nahm Arugal die Bestien als seine eigenen 'Kinder' an, beanspruchte die gefallene Festung und benannte sie in Shadowfang um.",al={"burg shadowfang geschichte","was geschah mit burg silberlein","fall von shadowfang"}},ee32dcde={q="Warum ist Burg Shadowfang verfallen?",a="Die Festung verfiel, als Arugals randalierende Worgen die Verteidiger belagerten und überwältigten und Baron Silberlein sowie seinen gesamten Haushalt niedermetzelten. Anstatt das adelige Anwesen wiederherzustellen, ließ der wahnsinnige Erzmagier die Hallen in die Dunkelheit verfallen und füllte den Innenhof und die Wehrgänge mit wilden Bestien und den gepeinigten Geistern der erschlagenen Adligen, die während des Massakers ums Leben kamen.",al={"warum ist burg shadowfang verfallen","burg shadowfang zerstört","warum ist sie verlassen"}},["5c468b05"]={q="Ist Burg Shadowfang gefährlich?",a="Burg Shadowfang ist außerordentlich tödlich. Hinter ihren eisernen Toren lauern Rudel wilder Worgen, Arugals kolossaler Wolf Fenrus und blutrünstige Kultisten. Neben den lebenden Bestien suchen die rastlosen, rachsüchtigen Geister von Baron Silberlein und seinen erschlagenen Soldaten die Hallen heim, während Erzmagier Arugal von den Wehrgängen der Burg aus tödliche arkanische Flüche befehligt.",al={"ist shadowfang gefährlich","gefahren in burg shadowfang","wie gefährlich ist shadowfang"}},["26793205"]={q="Warum heißt sie Burg Shadowfang?",a="Ursprünglich als Burg Silberlein nach ihrem herrschenden Adligen bekannt, wurde die Festung von Erzmagier Arugal in Burg Shadowfang umbenannt, nachdem seine beschworenen Worgen sie überrannt hatten. Er verlieh ihr den Namen zu Ehren der wilden, schattenhaften Wolfsbestien, die er als seine geliebten Kinder annahm, sowie der dunklen Rudel, die heute ihre Hallen durchstreifen.",al={"burg shadowfang name","warum heißt sie shadowfang","wie bekam shadowfang seinen namen"}}}}
P.entries["subzone:shadowglen"] = {n="Laubschattental",s="Laubschattental ist ein abgeschiedenes, dämmeriges Tal, eingebettet in die nordöstlichen Äste von Teldrassil. Beherrscht vom großen Grabhügelbaum Aldrassil, dient es als sichere Zuflucht, in der junge Nachtelfen ihre ersten Schritte im Dienst antreten, bevor sie in die weite Welt hinausziehen.",h="Laubschattental ist ein abgeschiedenes, dämmeriges Tal, eingebettet in die nordöstlichen Äste von Teldrassil.",kw={"aldrassil","kaldorei","startgebiet der nachtelfen","laubschattental","schattenweberhöhle","teldrassil"},ang={["faction:Alliance"]="Hoch in den Wipfeln von Teldrassil gelegen und tief hinter bewachten Zugängen verborgen, ist Laubschattental eines der am besten isolierten und verteidigten Rückzugstäler der Allianz.",["race:NightElf"]="Jeder junge Nachtelf beginnt seine aktive Reise hier inmitten der geschützten Wurzeln von Aldrassil, empfängt seine ersten Segnungen und Anweisungen, bevor er sich den Gefahren von Kalimdor stellt."},sec={{t="Eine geschützte Wiege",b="Verborgen im nordöstlichen Kronendach von Teldrassil ist Laubschattental von hohen Kämmen umgeben, die es vor dem Rest der Welt abschirmen. Gebadet in ewige Dämmerung, bildet Aldrassil das Zentrum des Tals – ein gewaltiger Grabhügelbaum, dessen ausgehöhlter Stamm Ältesten, Priesterinnen und Ausbildern junger Nachtelfen zu Beginn ihres Trainings Unterkunft bietet. Der einzige Weg aus dem Tal führt nach Süden durch einen schmalen Bergpass in Richtung Sternenhauch und Dolanaar, was Laubschattental zu einer der am stärksten natürlich befestigten und friedlichsten Zufluchten auf dem Weltenbaum macht."},{t="Kriechende Schatten",b="Trotz seiner ruhigen Abgeschiedenheit ist Laubschattental nicht gänzlich frei von Gefahren. Im äußersten Nordwesten liegt die Schattenweberhöhle, eine finstere Höhle voller giftiger Spinnen, die die ruhige Lichtung unablässig bedrohen. Selbst auf den unberührten Ästen von Teldrassil ist Wachsamkeit geboten, und angehende Verteidiger sind damit betraut, das vordringende Ungeziefer und die ungezähmte Wildtierwelt zurückzudrängen, bevor sie sich in die weiteren Gefilde der darüber hinausgehenden Wipfel wagen."}},faq={{q="Was ist Laubschattental?",a="Laubschattental ist der geschützte Starthein für die Nachtelfen, gelegen in den nordöstlichen Ausläufern von Teldrassil. Es ist eine friedliche, abgeschiedene Zuflucht rund um den majestätischen Baum Aldrassil, in der Neulinge unter Ausbildern trainieren, bevor sie über den Weltenbaum ziehen.",al={"was ist dieser ort","laubschattental geschichte","über laubschattental"}},{q="Was ist der gewaltige Baum im Zentrum des Tals?",a="Der Baum ist Aldrassil, ein Grabhügelbaum, der das Herz von Laubschattental bildet. Sein ausgehöhltes Inneres dient als Verwaltungssitz und Ausbildungszentrum, in dem Nachtelfenneulinge auf Klassenlehrer, Mentoren und Betreuer treffen.",al={"großer baum in laubschattental","aldrassil","laubschattental baum"}},{q="Welche Gefahren gibt es in Laubschattental?",a="Die größte Bedrohung geht vom Nordwesten aus der Schattenweberhöhle aus, einer von Giftsspinnen heimgesuchten Kaverne, aus der die Kreaturen regelmäßig auf die Lichtung kriechen. Junge Verteidiger werden damit beauftragt, die Spinnen zu dezimieren und die unruhige einheimische Tierwelt zu beruhigen.",al={"warum gibt es hier spinnen","laubschattental gefahren","schattenweberhöhle"}},{q="Wie verlässt man Laubschattental?",a="Laubschattental ist bis auf einen einzelnen Pfad im Süden vollständig von Kämmen umgeben. Folgt Ihr diesem engen Bergpass nach Süden, führt er Euch nach Sternenhauch und zur Siedlung Dolanaar.",al={"laubschattental verlassen","wohin führt der pfad","weg aus laubschattental"}}},fx={ceaa8c71={q="Was ist Teldrassil?",a="Teldrassil ist ein riesiger Weltenbaum, der vor der nordwestlichen Küste von Kalimdor gewachsen ist. Sein Name bedeutet in darnassisch \"Krone der Erde\". Er wurde nach dem Dritten Krieg vom Zirkel der Ältesten und mächtigen Druiden erschaffen und dient den Kaldorei als neue Heimat. Seine gigantischen Äste ragen direkt aus dem Meer empor und tragen eine gesamte bewaldete Landmasse und die Hauptstadt Darnassus in ihrem Geäst.",al={"was ist dieser riesige baum","teldrassil weltenbaum","über teldrassil"}},c8ee90fe={q="Wer hat Teldrassil wachsen lassen?",a="Nachdem Malfurion Sturmgrimm verschwand, überzeugte Erz-Druide Fandral Hirschhaupt den Zirkel der Ältesten, einen neuen Weltenbaum zu pflanzen. Mächtige Druiden kanalisierten ihre Magie, um ihn aus dem Meer zu heben, in der Hoffnung, die verlorene Unsterblichkeit der Kaldorei wiederherzustellen. Die Drachenaspekte – insbesondere Nozdormu, der ihnen einst das ewige Leben gewährt hatte – weigerten sich jedoch, die Äste zu segnen, was sein Wachstum fehlerhaft ließ.",al={"wer erschuf teldrassil","wer pflanzte teldrassil","wer erschuf den weltenbaum"}},["8fe22cbd"]={q="Warum leben die Nachtelfen jetzt in einem Baum?",a="Die Verwüstungen des Dritten Krieges beraubten die Nachtelfen ihrer angestammten Unsterblichkeit, als Nordrassil am Hyjal geopfert wurde. In dem Bestreben, ihr ewiges Leben und einen sicheren Zufluchtsort abseits der Bedrohungen des Festlandes zurückzugewinnen, zogen die Kaldorei Teldrassil als ihr Heiligtum auf und errichteten ihre strahlende Hauptstadt Darnassus hoch oben in seinem gewaltigen Geäst.",al={"warum in einem baum leben","warum nachtelfen auf teldrassil","warum auf teldrassil leben"}},["5b09454b"]={q="Wer lebt an der Spitze von Aldrassil?",a="Tenaron Sturmgewalt, der Anführer von Laubschattental, hat sein Zuhause in der Krone von Aldrassil. Hoch oben in den Ästen des großen Baumes überwacht er das Training und die Einweihung angehender Beschützer der Nachtelfen.",al={"spitze von aldrassil","wer ist in aldrassil","tenaron sturmgewalt aldrassil"}},["27b05a0e"]={q="Ist Aldrassil dasselbe wie Teldrassil?",a="Nein. Teldrassil ist der kolossale Weltenbaum, der aus dem Ozean ragt und ein inselgroßes Land aus Wäldern, Bergen und Städten auf seinen oberen Ästen trägt. Aldrassil ist lediglich ein einzelner, massiver uralter Baum, der im Boden von Laubschattental verwurzelt ist und auf Teldrassil selbst steht.",al={"aldrassil vs teldrassil","ist aldrassil teldrassil","unterschied aldrassil teldrassil"}},["0792cbea"]={q="Wer hat hier das Sagen?",a="Tenaron Sturmgewalt überwacht Laubschattental von seinem Gemach auf Aldrassil aus. Er leitet die Verteidigung des Tals, koordiniert lokale Druiden, Wächterinnen und Mentoren, während sie Neuankömmlinge anweisen und gegen die wachsende Verderbnis unter der lokalen Tierwelt vorgehen.",al={"wer führt laubschattental","anführer von laubschattental","das sagen in laubschattental"}},["3fc160d4"]={q="Wer führt die Nachtelfen insgesamt an?",a="Hohepriesterin Tyrande Wisperwind führt die Kaldorei durch die Schwesternschaft der Elune, während Erz-Druide Fandral Hirschhaupt in Abwesenheit von Malfurion Sturmgrimm derzeit den Zirkel des Cenarius leitet. Gemeinsam lenken Priesterschaft und Druiden die Nation der Nachtelfen von ihrer Hauptstadt Darnassus aus.",al={"anführer der nachtelfen","wer regiert die nachtelfen","anführer der kaldorei"}},["003c713a"]={q="Was sind die Webholzspinnen und warum sind sie hier?",a="Die Webholzspinnen sind riesige Arachniden, die sich in der Schattenweberhöhle innerhalb des jungen Weltenbaums eingenistet haben. Während sie sich früher weitgehend zurückhielten, hat ein dunkler Makel auf Teldrassil sie in einen bösartigen Rausch getrieben und sie aus ihren Höhlen getrieben, um jeden anzugreifen, der die nördlichen Gebiete durchstreift.",al={"webholzspinnen teldrassil","warum spinnen in laubschattental","spinnen laubschattental"}},["19b22b7f"]={q="Waren die Webholzspinnen schon immer in dieser Höhle?",a="Ja. Die Schattenweberhöhle im Nordwesten ist das natürliche Zuhause der riesigen Spinnen von Teldrassil. Ihre Feindseligkeit ist jedoch in den letzten Tagen unter der Brutmutter Githyiss die Vile dramatisch angestiegen, was die Höhle zu einer tödlichen Gefahr für unerfahrene Wanderer gemacht hat.",al={"spinnen immer in schattenweberhöhle","geschichte der schattenweberhöhle","waren spinnen schon immer hier"}},b0a66f5b={q="Wer ist Elune?",a="Elune ist die verehrte Mondgöttin der Nachtelfen, die mit Frieden, Sternenlicht und Heilung assoziiert wird. Die Kaldorei verehren sie seit alten Zeiten, und ihre Hohepriesterinnen – angeführt von Tyrande Wisperwind – kanalisieren ihre himmlische Macht, um ihr Volk zu schützen und ihre Feinde zu zerschmettern.",al={"mondgöttin elune","elune nachtelfen","göttin elune"}},["2f0ec344"]={q="Was ist Dolanaar und warum schickt mich jeder dorthin?",a="Dolanaar ist die nächstgelegene größere Siedlung, die sich südwestlich von Laubschattental durch den südlichen Gebirgspass befindet. Sobald eure Mentoren im Tal eure Fähigkeiten geprüft haben, werdet Ihr nach Dolanaar geschickt, um Eure Ausbildung zu vertiefen, Berufe zu erlernen und bei regionalen Krisen in ganz Teldrassil zu helfen.",al={"was ist dolanaar","warum nach dolanaar gehen","dolanaar dorf"}},["94588242"]={q="Warum haben die Nachtelfen ihre Unsterblichkeit verloren?",a="Während des Dritten Krieges marschierte die Brennende Legion auf den Hyjal, um den ursprünglichen Weltenbaum, Nordrassil, zu verzehren. Malfurion Sturmgrimm kanalisierte die Geister des Waldes und die Macht des uralten Baumes, um den Dämonenfürsten Archimonde auszulöschen. Die Opferung Nordrassils zerstörte den Zauber, der von den Drachenaspekten gewährt wurde, und beraubte die Kaldorei ihrer Zeitlosigkeit.",al={"verlust der unsterblichkeit nachtelfen","warum sind nachtelfen sterblich","verlust der nachtelfen-unsterblichkeit"}},b6ffca43={q="Wie bin ich im Laubschattental gelandet?",a="Ihr befindet Euch auf einer abgelegenen Lichtung hoch in den nordöstlichen Ästen von Teldrassil, dem jungen Weltenbaum, der vor der Küste des nördlichen Kalimdor gewachsen ist. Geschützt vor der Außenwelt unter dem großen Baum Aldrassil, dient dieser friedliche Wald als sicherer Zufluchtsort und Trainingsgelände für angehende Kaldorei. Ihr seid hierhergekommen, um dem Ruf Eurer Ältesten zu folgen und Eure Fähigkeiten in friedlicher Abgeschiedenheit zu verfeinern, bevor Ihr auf die größeren Äste der neuen Heimat Eures Volkes tretet.",al={"wie bin ich hierhergekommen","wie bin ich hier angekommen","warum bin ich hier"}},e332bd9f={q="Was soll ich im Laubschattental tun?",a="Eure Aufgabe ist es, den Wächtern und Ältesten von Aldrassil bei den wachsenden Problemen zu helfen, die die Lichtung stören. Eine üble Verderbnis hat vor Kurzem begonnen, die lokale Tierwelt aufzuwühlen, wodurch die einheimischen Webwood-Spinnen und Waldtiere feindselig wurden. Sprecht mit den Ausbildern und Anführern rund um den großen Baum, rottet die Krankheit aus, die in der Schattenweberhöhle schwärt, und stellt das Gleichgewicht des Waldes wieder her, bevor Ihr den Pfad weiter südlich nach Dolanaar nehmt.",al={"was soll ich hier tun","was ist meine bestimmung hier","was mache ich im laubschattental"}},["3011769b"]={q="Warum startet ein neuer Nachtelf hier im Laubschattental?",a="Nach dem Dritten Krieg und der Opferung von Nordrassil siedelten die Nachtelfen über das Meer nach Teldrassil um, um neu zu beginnen. Das Laubschattental ist der geschützteste und abgelegenste Teil der Baumkrone, abgeschirmt hinter bergigen Kämmen und bewacht von erfahrenen Wächterinnen. Da Ihr Eure ersten Schritte in den Künsten des Druidentums, der Kriegskunst oder Elunes Gnade macht, fördert Euer Volk Eure Ausbildung hier in der Sicherheit von Aldrassil, bevor Ihr in die weitere, gefährlichere Welt entlassen werdet.",al={"warum starten nachtelfen hier","warum beginnt mein nachtelf im laubschattental","warum im laubschattental starten"}}},fp="10,269,18.533.0,16.444.0,19.264.0,51.216.0,33.239.0,28.197.0"}
P.entries["subzone:shadowthread-cave"] = {n="Schattenweberhöhle",s="Die Schattenweberhöhle ist eine feuchte Höhle, die in die nordwestlichen Klippen von Laubschattental auf Teldrassil gehauen ist. Ursprünglich von einheimischen Webwood-Spinnen bewohnt, ist die Höhle unter der Herrschaft ihrer Brutgräfin Githyiss the Vile vor Kurzem gefährlich aggressiv geworden.",h="Die Schattenweberhöhle ist eine feuchte Höhle, die in die nordwestlichen Klippen von Laubschattental auf...",kw={"githyiss the vile","laubschattental","schattenweberhöhle","spinnenseide","teldrassil","webwood spinne"},ang={["class:Druid"]="Die ungebremste Aggression der Webwood-Brut in der Schattenweberhöhle ist für Druiden ein beunruhigendes Zeichen dafür, dass die natürliche Harmonie von Teldrassil zutiefst gestört ist.",["race:NightElf"]="Für junge Nachtelfen dient das Säubern der Schattenweberhöhle und das Erschlagen von Githyiss the Vile als eine ihrer allerersten Prüfungen bei der Verteidigung ihrer heiligen Heimat vor dem schleichenden Verderben."},sec={{t="Eine unruhig werdende Brut",b="Verborgen am schattigen Rand von Laubschattental diente die Schattenweberhöhle lange Zeit als natürlicher Bau für Teldrassils Riesenspinnen. In früheren Jahren koexistierten diese Spinnentiere friedlich entlang der noch jungen Äste des Weltenbaums. In jüngster Zeit hat sich ihr Wesen jedoch zu einem heftig territorialen Verhalten gewandelt. Dicke Schichten aus Webwood-Seide verstopfen mittlerweile die steinernen Gänge, und die aggressive Natur der Brut stellt eine unmittelbare Gefahr für junge Kaldorei dar, die ihre ersten Schritte außerhalb von Aldrassil wagen."},{t="Githyiss the Vile",b="Die größte Bedrohung, die tief in den dunkelsten Winkeln der Höhle lauert, ist Githyiss the Vile – eine monströse Brutgräfin, deren Wildheit die der gewöhnlichen Webwood-Kriecher bei Weitem übersteigt. Unerfahrene Schildwachen und Druiden der Nachtelfen werden in die Höhle entsandt, um die Spinnenplage einzudämmen und Githyiss zu erschlagen, damit das Heiligtum von Laubschattental nicht gänzlich von dem Verderben überrannt wird, das die Tierwelt Teldrassils befällt."}},faq={{q="Wo befindet sich die Schattenweberhöhle?",a="Die Schattenweberhöhle liegt im nordwestlichen Winkel von Laubschattental, eingebettet in den felsigen Hang, der das Starttal der Nachtelfen auf Teldrassil begrenzt.",al={"schattenweberhöhle standort","wo ist die schattenweberhöhle","schattenweberhöhle finden"}},{q="Warum sind die Spinnen in der Höhle so aggressiv?",a="Obwohl Spinnen schon immer in der Höhle gehaust haben, treibt eine üble Seuche und ein wachsendes Ungleichgewicht auf ganz Teldrassil die einheimische Tierwelt in den Wahnsinn, was die Webwood-Spinnen außergewöhnlich gewalttätig macht.",al={"warum sind spinnen feindlich","spinnen verderbnis schattenweberhöhle","warum spinnen angreifen"}},{q="Wer ist Githyiss the Vile?",a="Githyiss the Vile ist eine gewaltige, giftige Webwood-Spinnenmatriarchin am tiefsten Punkt der Schattenweberhöhle. Sie ist die Mutter der aggressiven Brut, welche die jungen Kaldorei im Laubschattental bedroht.",al={"githyiss","wer ist githyiss","schattenweberhöhle spinnenboss"}},{q="Was macht die Höhle trotz der Gefahr wertvoll?",a="Die Höhle ist vollgepackt mit Schichten dichter, natürlich gesponnener Webwood-Seide – ein wertvolles und widerstandsfähiges Handwerksmaterial, das von den endlosen Schwärmen von Spinnentieren in ihren dunklen Kammern gewoben wird.",al={"schattenweberseide","spinnenseide laubschattental"}}},fx={["3bee1b1c"]={q="Was ist die Schattenweberhöhle?",a="Die Schattenweberhöhle ist ein unterirdisches Höhlensystem, das sich in die nordwestlichen Abhänge des Laubschattentals auf Teldrassil schmiegt. Traditionell ist es der natürliche Nistplatz der Webwood-Spinnen der Insel und dient als abgelegener Unterschlupf, in dem die Spinnentiere ihre komplizierten Netze weben und ihre Brut abseits der Äste des Weltenbaums aufziehen.",al={"was ist die schattenweberhöhle","schattenweberhöhle hintergrund","schattenweberhöhle"}},aa654c4e={q="Wer lebt in der Schattenweberhöhle?",a="Die Höhle wird fast vollständig von den einheimischen Webwood-Spinnen Teldrassils bewohnt. Im Herzen des Nestes herrscht ihre gewaltige Brutmutter, Githyiss die Gemeine, die die Schwärme von Spinnentieren befehligt, die die Steinwände mit dichten Netzen überziehen.",al={"wer lebt in der schattenweberhöhle","bewohner der schattenweberhöhle","spinnen in der schattenweberhöhle"}}},fp="17,263,24.490.0,17.400.0,35.151.0,46.192.0,25.200.0,48.183.0"}
P.entries["subzone:shalzaru-s-lair"] = {n="Shalzarus Unterschlupf",s="Shalzarus Unterschlupf ist eine weitläufige, überflutete Höhle an der Nordspitze der Insel des Schreckens in Feralas. Sie dient den Naga der Hatecrest als wichtige Festung und beherbergt ihren furchterregenden Meister, Shalzaru. Aus diesen feuchten Tunneln koordinieren die schlangenartigen Invasoren ihre aggressive Präsenz unmittelbar südlich der Mondfederfeste.",h="Shalzarus Unterschlupf ist eine weitläufige, überflutete Höhle an der Nordspitze der Insel des Schreckens in...",kw={"mondfederfeste","feralas","hatecrest","die insel des schreckens","naga höhle","shalzaru","shalzarus unterschlupf"},ang={["faction:Alliance"]="Der Truppenaufmarsch der Hatecrest in dieser Höhle bedroht die Nachschublinien und den Frieden der Mondfederfeste, weshalb die Beseitigung von Shalzaru und seiner Brut für die Schildwachen und ihre Verbündeten höchste Priorität genießt.",["race:NightElf"]="Die abscheuliche Präsenz von Naga, die die uralten Küstenruinen von Feralas entweihen, dient als schmerzhafte Erinnerung an die Zerschlagung und den Abstieg der Hochgeborenen in monströse Verderbnis."},sec={{t="Ein Schlangennest in den Untiefen",b="In die zerklüfteten Klippen am nördlichen Ende der Insel des Schreckens gehauen, teilt sich Shalzarus Unterschlupf in eine gewaltige Haupthöhle und eine kleinere Nebenkammer, die durch überflutete unterirdische Wasserwege miteinander verbunden sind. Das Innere wimmelt von hochgradig alarmierten Schlangenwachen und zauberwirkenden Hexenmeisterinnen der Hatecrest. Tief in den Nischen haust Lord Shalzaru, der schlangenartige Herrscher, der die Hatecrest-Brut über die Insel hinweg befehligt. Die Nähe zur Insel Sardor stellt eine direkte, ständige Bedrohung für die Nachtelfen-Schildwachen dar, die direkt jenseits des Kanals in der Mondfederfeste stationiert sind."}},faq={{q="Wo befindet sich Shalzarus Unterschlupf?",a="Shalzarus Unterschlupf befindet sich am nördlichen Ende der Insel des Schreckens, einer Insel direkt südlich der Insel Sardor und der Mondfederfeste vor der Westküste von Feralas.",al={"wo ist shalzarus unterschlupf","shalzarus unterschlupf ort","shalzarus unterschlupf finden"}},{q="Wer ist Shalzaru?",a="Shalzaru ist ein mächtiger Kriegsherr der Naga und der Anführer des Hatecrest-Stammes, der die Insel des Schreckens bewohnt. Er befehligt seine Streitkräfte aus den Tiefen der überfluteten Höhlen des Unterschlupfs.",al={"wer ist shalzaru","shalzaru lore","boss in shalzarus unterschlupf"}},{q="Welche Kreaturen bewohnen diese Höhle?",a="Die Höhle wimmelt von Naga der Hatecrest, hauptsächlich wachsamen Schlangenwachen der Hatecrest, die die trockenen Pfade sichern, sowie Hexenmeisterinnen der Hatecrest, die über den unterirdischen Gewässern Magie wirken.",al={"welche gegner sind in shalzarus unterschlupf","hatecrest naga höhlenmobs"}},{q="Warum ist dieser Unterschlupf für die einheimischen Nachtelfen wichtig?",a="Da die Insel des Schreckens direkt gegenüber der Mondfederfeste liegt, stellt die konzentrierte Naga-Präsenz in Shalzarus Unterschlupf eine unmittelbare militärische Bedrohung für die Streitkräfte von Shandris Mondfeder und die Sicherheit der Insel Sardor dar.",al={"warum kümmern sich nachtelfen um shalzaru","feathermoon naga bedrohung"}}},fp="15,343,29.575.0,33.177.0,16.176.0,33.185.0,52.245.0"}
P.entries["subzone:shaper-s-terrace"] = {n="Die Terrasse des Formers",s="Hoch oben auf den nördlichen Klippen über Marschalls Zuflucht gelegen, ist die Terrasse des Formers ein mysteriöser Aussichtspunkt, der von antiker Titanenarchitektur geprägt ist. Sie ist zu Ehren von Khaz'goroth dem Former benannt und legt stilles Zeugnis von den urzeitlichen Experimenten ab, die den Krater von Un'Goro formten.",h="Hoch oben auf den nördlichen Klippen über Marschalls Zuflucht gelegen, ist die Terrasse des Formers ein...",kw={"krater","khaz'goroth","marschalls zuflucht","former","die terrasse des formers","titan","un'goro"},ang={["race:Dwarf"]="Für Zwerge, die ihrer Titanenabstammung nachgehen, bietet die Terrasse des Formers einen weiteren faszinierenden Einblick in Khaz'goroths Architektur und die großen Werke der Schöpfer."},sec={{t="Ein Vermächtnis der Titanen",b="Mit Blick auf das üppige, prähistorische Becken des Un'Goro-Kraters beherbergt die Terrasse des Formers monumentale steinerne Bauwerke, die von den Titanen zurückgelassen wurden. Es wird angenommen, dass dieses Hochplateau Khaz'goroth dem Former gewidmet ist und als Denkmal für die himmlischen Architekten steht, die den Krater als lebendiges Laboratorium für das frühe Leben auf Azeroth kultivierten. Von diesen erhöhten Steinen aus beobachteten und lenkten antike Wesen einst die Flora und Fauna unter ihnen. Ihre kalten Steinbögen und massiven metallischen Sockel stehen in krassem, rätselhaftem Kontrast zu der ungezähmten Wildnis, die direkt unter ihnen gedeiht."}},faq={{q="Was ist die Terrasse des Formers?",a="Die Terrasse des Formers ist eine erhöhte Titanenstätte entlang der nördlichen Klippen des Un'Goro-Kraters, direkt über Marschalls Zuflucht. Sie weist steinerne Bauwerke auf, die mit den Titanen verbunden sind, die einst das Land formten.",al={"terrasse des formers","was ist diese terrasse","ungoro terrasse"}},{q="Wer war der 'Former'?",a="Die Terrasse bezieht sich auf Khaz'goroth den Former, einen der titanischen Schöpfer, der in der fernen Vergangenheit dazu beitrug, die Welt Azeroth zu gestalten und zu kultivieren.",al={"wer ist der former","khazgoroth","wer erbaute die terrasse des formers"}}},fp="16,272,22.577.0,29.204.0,21.143.0"}
P.entries["subzone:shatter-scar-vale"] = {n="Shatter Scar-Tal",s="Das Shatter Scar-Tal ist ein verbranntes Becken im zentralen Teufelswald, das direkt nördlich von den Blutgiftfällen liegt. Es markiert den Nullpunkt, an dem während des Dritten Krieges dämonische Höllenbestien im nördlichen Kalimdor einschlugen. Bis heute brennen die Krater von Teufelsfeuer und beherbergen verbliebene Überreste der Brennenden Legion.",h="Das Shatter Scar-Tal ist ein verbranntes Becken im zentralen Teufelswald, das direkt nördlich von den...",kw={"die blutgiftfälle","brennende legion","krater","teufelswald","höllenbestien","shatter scar-tal"},ang={["class:Druid"]="Die schwelenden Narben in diesem Tal sind bleibende offene Wunden auf Kalimdors Geist, die sich weigern zu heilen, solange die Konstrukte der Legion noch brennen.",["class:Warlock"]="Die von Teufelsenergie durchdrungenen Kerne der Höllenbestien, die diese Krater durchstreifen, stellen mächtige Kanäle chaotischer Magie dar, die von der Invasion der Legion zurückgelassen wurden."},sec={{t="Einschlag der Höllenbestien",b="Während des Dritten Krieges ließ die Brennende Legion lebende Belagerungsmaschinen auf das nördliche Kalimdor herabregnen. Das Shatter Scar-Tal trug die Hauptlast dieses Angriffs aus dem Himmel. Dämonische Höllenbestien stürzten aus den Wolken herab, zerrissen das uralte Blätterdach und schlugen tiefe Krater in die Erde. Der gewaltige Aufprall zerschmetterte das Gelände und hinterließ geschwärzte Senken, die bis zum heutigen Tag von unheiligem Feuer schwelen. Obwohl die Legion am Hyjal zerschlagen wurde, haben sich die Höllenbestien und die verbliebenen niederen Dämonen nie wirklich zerstreut und halten eine feste Stellung in der vernarbten Erde."}},faq={{q="Warum ist der Boden voller Krater?",a="Die Krater entstanden während des Dritten Krieges, als die Brennende Legion den Wald mit Höllenbestien bombardierte. Diese kolossalen Konstrukte aus Teufelsgestein stürzten wie Meteore vom Himmel, schlugen auf den Boden auf und hinterließen im gesamten Tal schwelende Einschlagnarben.",al={"krater im teufelswald","warum ist das shatter scar-tal voller krater","was hat die krater verursacht"}},{q="Welche Kreaturen durchstreifen das Shatter Scar-Tal?",a="Das Tal wird noch immer von Konstrukten und Dienern der Brennenden Legion beherrscht. Lebende Höllenbestien bewachen weiterhin die schwelenden Einschlagbecken, zusammen mit anderen umherstreifenden niederen Dämonen, die nach dem Scheitern der Invasion zurückblieben.",al={"welche mobs sind hier","gegner im shatter scar-tal"}},{q="Wo befindet sich das Shatter Scar-Tal?",a="Das Shatter Scar-Tal liegt in den zentralen Bereichen des Teufelswalds, direkt nördlich der Blutgiftfälle an der östlichen Seite des Hauptwegs des Waldes.",al={"lage des shatter scar-tals","wo ist das shatter scar-tal"}}},fp="17,294,23.559.0,37.260.0,38.214.0,35.153.0"}
P.entries["subzone:shattered-strand"] = {n="Der zertrümmerte Strand",s="Der zertrümmerte Strand ist ein wilder, zerklüfteter Küstenstreifen, der den nördlichen Rand der Bucht der Stürme in Azshara säumt. Beherrscht von tosender Brandung und verfallenden uralten Ruinen wimmelt es am Strand von gefährlichen Meeresbestien und aquatischen Stammeskreaturen.",h="Der zertrümmerte Strand ist ein wilder, zerklüfteter Küstenstreifen, der den nördlichen Rand der Bucht der...",kw={"azshara","die bucht der stürme","hydras","makrura","murlocs","meeresriesen","der zertrümmerte strand","der tempel von arkkoran","turm von eldara"},ang={["class:Hunter"]="Der Strand bietet ein ungezähmtes Übungsgelände voller furchterregender Hydras und Küstenbestien, ideal für jene, die mächtige Kreaturen suchen oder die räuberische Fauna der Küste von Kalimdor studieren möchten."},sec={{t="Eine tückische Küstenlinie",b="Entlang des Nordrands der Bucht der Stürme erstreckt sich der zertrümmerte Strand, der alles andere als eine friedliche Küste ist. Die felsigen Strände und Gezeitenseichten sind dicht von aggressiven Wildtieren bevölkert, darunter hoch aufragende Meeresriesen, mehrköpfige Hydras und schnappende Makrura, neben Lagern von Küstenmurlocs. Verfallende elfische Architektur überblickt die Wellen, geprägt von Wahrzeichen wie dem uralten Tempel von Arkkoran und dem einsamen Turm von Eldara. Für Reisende, die Azsharas tückische Klippen durchqueren, bedeutet der Abstieg zu diesem abgelegenen Küstenstreifen die Konfrontation mit einigen der tödlichsten amphibischen Bedrohungen der Region."}},faq={{q="Wo befindet sich der zertrümmerte Strand?",a="Der zertrümmerte Strand bildet die Nordküste der Bucht der Stürme und liegt in den östlichen Weiten von Azshara unterhalb der hoch aufragenden Klippen der Zone.",al={"der zertrümmerte strand lage","wo liegt der zertrümmerte strand","der zertrümmerte strand karte"}},{q="Welche Kreaturen bewohnen den zertrümmerten Strand?",a="Die Küstenlinie wird dicht von bösartigen Hydras, massiven Meeresriesen, gepanzerten Makrura und Ansammlungen feindseliger Murlocs durchstreift, die das Watt patrouillieren.",al={"der zertrümmerte strand mobs","was lebt am zertrümmerten strand","der zertrümmerte strand tiere"}},{q="Welche bemerkenswerten Ruinen sind am Strand zu finden?",a="Die Küste beherbergt uralte Architektur der Hochgeborenen, allen voran den Tempel von Arkkoran und den nahe gelegenen Turm von Eldara, der die Bucht überblickt.",al={"der zertrümmerte strand ruinen","gebäude am zertrümmerten strand","sehenswürdigkeiten zertrümmerter strand"}},{q="Ist der zertrümmerte Strand sicher für beiläufige Erkundungen?",a="Nein. Der Strand ist abgelegen, aufgrund der umgebenden steilen Klippen schwer schnell zu verlassen und dicht besiedelt von räuberischen Wasserbestien und mächtigen Riesen.",al={"ist der zertrümmerte strand gefährlich","der zertrümmerte strand stufe"}}},fp="16,239,23.622.0,38.149.0,44.148.0,48.144.0,52.161.0"}
P.entries["subzone:shifting-mire"] = {n="Der Wabersumpf",s="Der Wabersumpf bildet das gewaltige, schlammige Herz der Sümpfe des Elends und liegt direkt westlich des Tränenteichs. Seinen Namen verdankt er dem seltsamen, unruhigen Schlick unter dem trüben Wasser, der unter dem Einfluss einer unsichtbaren Macht zu treiben und sich zu sammeln scheint.",h="Der Wabersumpf bildet das gewaltige, schlammige Herz der Sümpfe des Elends und liegt direkt westlich des...",kw={"krokilisken","jaguare","verirrte","der wabersumpf","schlick","kummerspinner","sümpfe des elends"},ang={["class:Hunter"]="Das dichte Gestrüpp und das treibende Wasser machen das Spurenlesen tückisch und erfordern von Jägern höchste Wachsamkeit gegenüber verstohlenen Sumpfjaguaren und giftigen Kummerspinnern, die sich im Blattwerk verbergen."},sec={{t="Ein lebendiges Moor",b="Der Wabersumpf erstreckt sich über die zentralen Gefilde des Marschlands und ist eine beunruhigende Weite, in der fester Boden kaum zu finden ist. Der Schlick auf dem Sumpfboden verschiebt und sammelt sich, als würde er von einem lebendigen Willen bewegt, angetrieben von einer seltsamen, allgegenwärtigen Energie, die den Torf durchdringt. Inmitten des treibenden Schlamms streifen räuberische Sumpfjaguare, gewaltige Kummerspinner und hungrige Sägezahnkrokilisken umher, während Gruppen zerschlagener Draenei, bekannt als die Verirrten, die versunkenen Pfade durchstreifen."}},faq={{q="Warum wird er der Wabersumpf genannt?",a="Das Gebiet verdankt seinen Namen dem extrem feinen Schlick, der auf dem Moorboden ruht. Anstatt sich wie normales Sediment abzusetzen, bewirkt eine mysteriöse Energieströmung, dass sich der Schlamm sammelt, treibt und durch die Feuchtgebiete fließt, als wäre er lebendig.",al={"namensursprung wabersumpf","warum wabersumpf","warum bewegt sich der boden"}},{q="Welche Kreaturen leben im Wabersumpf?",a="Der Sumpf wird von gefährlichen Wildtieren heimgesucht, darunter in den Untiefen lauernde Sägezahnkrokilisken, riesige Kummerspinner, die Netze in den Ästen weben, und verstohlene Sumpfjaguare. Zudem wird er von umherstreifenden Verirrten heimgesucht, Draenei, die mutiert und aus ihrer Heimatwelt verbannt wurden.",al={"wabersumpf gegner","was gibt es im wabersumpf"}},{q="Wo befindet sich der Wabersumpf?",a="Er umfasst die zentrale Ausdehnung der Sümpfe des Elends und liegt direkt westlich des gewaltigen Sees, der als der Tränenteich bekannt ist.",al={"wabersumpf lage","wo ist der wabersumpf"}}},fp="13,252,12.460.0,35.237.0,41.269.0,35.139.0"}
P.entries["subzone:shimmer-ridge"] = {n="Schimmergrat",s="Der Schimmergrat ist ein zerklüftetes Hochland im nördlichen Dun Morogh, direkt westlich der Tore von Eisenschmiede. Er wird von feindseligen Frostmähnentrollen besetzt. Die felsigen Höhen bestehen aus zwei Lagern, die durch eine wackelige Brücke verbunden sind, und sind als einziger Fundort für das potente Schimmerkraut bekannt.",h="Der Schimmergrat ist ein zerklüftetes Hochland im nördlichen Dun Morogh, direkt westlich der Tore von...",kw={"dun morogh","frostmähnen","eisenschmiede","bergsteiger","schimmergrat","schimmerkraut","trolle"},ang={["profession:Herbalism"]="Während gewöhnliche Flora im unterkühlten Klima von Dun Morogh nur schwer überlebt, bietet der Schimmergrat einzigartige Bedingungen für das wertvolle Schimmerkraut, das in den Lagern der Frostmähnen gepflegt wird.",["race:Dwarf"]="Im Schatten der Tore von Eisenschmiede gelegen, ist der Schimmergrat eine ärgerliche Erinnerung an die anhaltende Bedrohung durch die Frostmähnen und die gefährliche Quelle für erlesenes Schimmerkraut für legendäres Zwergenbier."},sec={{t="Eine Festung der Frostmähnen",b="Der Schimmergrat liegt an den schroffen Hängen westlich des mächtigen Eingangs von Eisenschmiede und dient dem Stamm der Frostmähnentrolle als aktives Bollwerk. Die Enklave ist in zwei Lager unterteilt, die durch eine Schlucht getrennt und durch einen Holzsteg verbunden sind, und wird von Trollplünderern sowie deren gezähmten Wildschweinen schwer bewacht. Ihre Nähe zur Hauptstraße und der Zwergenhauptstadt stellt für Reisende und Bergpatrouillen eine ständige Belastung dar, da diese stets auf der Hut vor opportunistischen Überfällen aus der Höhe sein müssen."},{t="Der Preis des Schimmerkrauts",b="Neben seiner strategischen Lage ist der Grat für den Anbau von Schimmerkraut berühmt, einer Pflanze, die von den Frostmähnentrollen kultiviert wird. Da es von den lokalen Zwergenbraumeistern für die Herstellung von kräftigen, aromatischen Hochlandbieren geschätzt wird, ist das Kraut andernorts nicht leicht zu finden. Wagemutige Bergsteiger und junge Rekruten riskieren oft Hinterhalte der Frostmähnen und wilde, bezahnte Bestien, nur um frische Körbe der kostbaren Botanik direkt von den Feldern der Trolle zu ernten."}},faq={{q="Wo befindet sich der Schimmergrat?",a="Der Schimmergrat liegt im nördlichen Dun Morogh, direkt westlich der massiven Tore von Eisenschmiede, die in die Zwergenhauptstadt führen.",al={"standort schimmergrat","wo ist der schimmergrat","schimmergrat finden"}},{q="Wer kontrolliert den Schimmergrat?",a="Der Grat wird vom indigenen Stamm der Frostmähnentrolle besetzt, die zwei durch eine Brücke verbundene Lager errichtet haben und die Höhen zusammen mit ihren gezähmten Wildschweinen verteidigen.",al={"wer lebt auf dem schimmergrat","feinde am schimmergrat","trolle am schimmergrat"}},{q="Was ist Schimmerkraut und warum ist es so begehrt?",a="Schimmerkraut ist ein besonderes Bergkraut, das auf den kalten Hängen des Grats gedeiht. Lokale Zwergenbrauer schätzen es überaus als wesentlichen Bestandteil für spezielle, aromatische Rezepte von Hochlandbier.",al={"nutzen von schimmerkraut","was ist schimmerkraut","zweck von schimmerkraut"}},{q="Warum vertreiben die Zwerge die Trolle nicht vollständig?",a="Das Militär von Eisenschmiede ist mit umfassenderer Verteidigung und externen Angelegenheiten beschäftigt, wodurch lokale Bedrohungen wie die Frostmähnenenklaven in Dun Morogh von regionalen Bergsteigern und wandernden Rekruten verwaltet werden müssen.",al={"warum ignoriert eisenschmiede den schimmergrat","eisenschmiede gegen frostmähnen","reaktion der zwerge auf den schimmergrat"}}},fx={aaffe09f={q="Ist der Schimmergrat gefährlich?",a="Ja, für unerfahrene Reisende ist er recht gefährlich. Die Frostmähnentrolle, die auf dem Grat leben, sind gegenüber Außenstehenden äußerst feindselig und bewachen ihre Lager und Schimmerkrautvorkommen energisch. Zwischen aggressiven Trollverteidigern und den wilden Ebern, die sie halten und zähmen, riskiert jeder, der sich ohne Vorsicht auf die Höhen wagt, schnell von den lokalen Kriegerbanden überwältigt zu werden.",al={"ist der schimmergrat sicher","gefahren im schimmergrat","wie gefährlich ist der schimmergrat"}},e59eca35={q="Warum heißt er Schimmergrat?",a="Der Ursprung des Namens ist unbekannt. Der Grat ist für sein Schimmerkraut bekannt, das die Frostmähnentrolle anbauen und zwergische Brauer für ihr Bier suchen.",al={"namensherkunft schimmergrat","warum heißt es schimmergrat","woher kommt der name schimmergrat"}}},fp="13,282,22.510.0,24.439.0,31.140.0,27.168.0,47.205.0,54.202.0"}
P.entries["subzone:shimmering-flats"] = {n="Die schimmernde Ebene",s="Die schimmernde Ebene ist eine weitläufige Salzpfanne an der südöstlichen Spitze von Tausend Nadeln, die an die Wüste von Tanaris grenzt. Einst das Bett eines uralten Sees, ist diese sonnenverbrannte Weite heute berühmt für die Hochgeschwindigkeits-Wettkämpfe der Illusionenrennbahn und eine lebensfeindliche Population von Wüstenbestien.",h="Die schimmernde Ebene ist eine weitläufige Salzpfanne an der südöstlichen Spitze von Tausend Nadeln, die an...",kw={"illusionenrennbahn","pozzik","rustmaul","salzebenen","die schimmernde ebene","silithiden","tanaris","tausend nadeln"},ang={["profession:Engineering"]="Die Salzebenen sind eine Pilgerstätte für Ingenieure, übersät mit Schrott, Treibstoffexperimenten und Hochgeschwindigkeits-Fahrzeugtests, die durch die endlose Rivalität zwischen Goblin- und Gnom-Maschinisten angeheizt werden.",["race:Gnome"]="Draußen auf der Illusionenrennbahn verteidigen Gnom-Piloten und Mechanostreiter mutig den Stolz der Gnom-Technik gegen die unbeständigen, explosiven Entwürfe ihrer Goblin-Rivalen."},sec={{t="Ein Bett aus Salz und Geschwindigkeit",b="Die sich unter der gleißenden südlichen Sonne erstreckende Die schimmernde Ebene ist ein riesiger, ausgetrockneter Seeboden ohne Vegetation, übersät mit den sonnengebleichten Knochen von Schildkröten und sogar dem hölzernen Wrack eines uralten Segelschiffs. Ihre schiere, unebene Oberfläche macht sie zum wichtigsten Testgelände auf Kalimdor für experimentelle Fahrzeuge. In der Mitte der Ebene liegt die Illusionenrennbahn, wo Gnome und Goblin-Bastler ständig darum wetteifern, wessen Raketenautos, Gyrokopter und Motoren die höchsten Geschwindigkeiten erreichen können – was oft in feurigen Unfällen und rauchenden Kratern auf der weißen Kruste endet."},{t="Gefahren des Salzes",b="Jenseits der dröhnenden Motoren der Rennbahn ist das Becken alles andere als friedlich. Gehärtete Basilisken, aggressive Skorpide und kreisende Aasfresser machen Jagd auf alles, was auf der offenen Ebene langsamer wird. Weiter südlich wird der Boden in der Nähe der Rustmaul-Grabungsstätte tückisch. Ursprünglich von Zwergen-Prospektoren ausgehoben, bevor die Horde den Ort umkämpfte, wurde der Steinbruch vollständig aufgegeben, als bei Grabungen unterirdische Tunnel freigelegt wurden, die einen Schwarm bösartiger Silithiden am südlichen Rand der Ebene entfesselten."}},faq={{q="Warum steht ein zerstörtes Schiff mitten in der Wüste?",a="Die schimmernde Ebene war einst ein riesiger Binnensee, der vor langer Zeit austrocknete. Das Wrack, das im nördlichen Teil der Ebene liegt, ist ein Überbleibsel dieses uralten Gewässers, das zurückblieb, als der See zu der riesigen Salzpfanne verdunstete, die Ihr heute seht.",al={"schiff in der schimmernden ebene","boot in der salzebene","wrack in tausend nadeln"}},{q="Warum sind Gnome und Goblins hier zusammen?",a="Die ununterbrochene, flache Salzkruste bietet das perfekte Terrain zum Testen von Raketenautos und hochmodernen mechanischen Apparaturen. Anstatt um Territorium zu kämpfen, gründeten Gnome und Goblins vor Ort die Illusionenrennbahn, um ihre technologische Rivalität anzuheizen, wobei sie unaufhörlich versuchen, sich gegenseitig an Geschwindigkeit, technischem Können und tollkühnem Mut zu übertreffen.",al={"hintergrund der rennbahn","warum sie rennen","gnome und goblins in der salzebene"}},{q="Was geschah mit der Zwergen-Grabungsstätte im Süden?",a="Die Die Rustmaul-Grabungsstätte wurde von Zwergen-Archäologen errichtet, die bald von einem Überfalltrupp der Horde unter der Führung von Moktar Krin angegriffen wurden. Dann stießen die Grabungsarbeiter versehentlich auf einen unterirdischen Silithiden-Bau und setzten Schwärme insektenartiger Schrecken frei, die alle vertrieben und die südliche Ebene überrannten.",al={"hintergrund der rustmaul-grabungsstätte","was geschah mit rustmaul","käfer in der salzebene"}},{q="Wohin führt die Straße durch die schimmernde Ebene?",a="Wenn Ihr den Spuren nach Südosten über die Salzpfanne folgt, gelangt Ihr direkt zum Gebirgspass, der sich zur riesigen Wüste von Tanaris und dem neutralen Hafen von Gadgetzan hin öffnet.",al={"wohin führt die schimmernde ebene","wie kommt man nach tanaris","ausgang nach tanaris"}}},fx={a9a42c0c={q="Was ist die schimmernde Ebene?",a="Die schimmernde Ebene ist ein riesiges, blendend weißes Salzbecken am südöstlichen Ende der Tausend Nadeln, das an die Wüste Tanaris grenzt. Es ist ein vollständig ausgetrocknetes Seebett ohne jede Vegetation, das eine riesige, flache Weite bietet, auf der Erfinder ihre wildesten Kreationen testen und aggressive Wüstenbestien den rissigen Boden durchstreifen.",al={"was ist die schimmernde ebene","hintergrund der schimmernden ebene","über die schimmernde ebene"}},bc39548e={q="Ist die schimmernde Ebene gefährlich?",a="Trotz ihres kargen Aussehens ist die Ebene ziemlich gefährlich. Tödliche einheimische Raubtiere wie Salzbasilisken, Skorpide und Geier durchstreifen das offene Becken, während die unberechenbaren Raketenautos und Testunfälle von Goblins und Gnom-Rennfahrern feurige Trümmer überall hinterlassen. Zudem ist kürzlich im südlichen Teil ein unterirdischer Silithiden-Bau ausgebrochen, der eine uralte zwergische Ausgrabungsstätte überrannt hat.",al={"ist die schimmernde ebene gefährlich","gefahren in der schimmernden ebene","wie gefährlich ist die schimmernde ebene"}},b2b7f543={q="Warum heißt sie die schimmernde Ebene?",a="Der Name stammt von dem blendenden visuellen Effekt der Sonne, die auf das uralte, kristallisierte Salzbecken herabscheint. Das harte grelle Licht, das von der weißen, trockenen Mineralkruste reflektiert wird, erzeugt eine schillernde, flimmernde Fata Morgana am Horizont, die kilometerweit über das ausgetrocknete Becken sichtbar ist.",al={"warum schimmernde ebene","namensherkunft schimmernde ebene","warum heißt es schimmernde ebene"}}},fp="16,303,23.588.0,19.504.0,59.255.0,41.336.0,51.298.0,54.164.0"}
P.entries["subzone:shining-strand"] = {fx={["1e20c8b8"]={q="Was ist der leuchtende Strand?",a="Der leuchtende Strand ist die östliche Küstenlinie vom Silberwald entlang der Gewässer vom Lordameresee. Er erstreckt sich von den Außenbezirken der Ruinen von Lordaeron nach Süden bis hinunter zu den zerklüfteten Hügeln, die den Silberwald vom Alteracgebirge trennen.",al={"was ist der leuchtende strand","hintergrund des leuchtenden strandes","wo ist der strand"}}}}
P.entries["subzone:shrine-of-aessina"] = {n="Der Schrein von Aessina",s="Der Schrein von Aessina ist eine heilige elfische Stätte in den Wäldern des südwestlichen Eschental, geweiht dem uralten Waldgeist der Natur und der wilden Kreaturen. Zwischen Maestras Posten und Astranaar gelegen, steht er als friedvolles Sanktuarium inmitten der wachsenden Grenzkonflikte in der Region.",h="Der Schrein von Aessina ist eine heilige elfische Stätte in den Wäldern des südwestlichen Eschental, geweiht...",kw={"aessina","eschental","astranaar","kaldorei","maestras posten","naturschrein","der schrein von aessina","wilder gott"},ang={["class:Druid"]="Als uraltes Sanktuarium zu Ehren des lebendigen Geistes der wilden Wälder ist der Schrein ein Ort von tiefgreifender Bedeutung für all jene, die sich der Bewahrung des natürlichen Gleichgewichts von Kalimdor verschrieben haben.",["race:NightElf"]="Für die Kaldorei steht der Schrein für Jahrhunderte der Harmonie mit den einheimischen Geistern von Eschental, die nun ständig von vordringenden Kräften von außen bedroht werden."},sec={{t="Ein Sanktuarium der tiefen Wälder",b="Verborgen westlich von Astranaar ehrt der Schrein von Aessina den geheimnisvollen Wilden Gott, der das Herz und den Geist der tiefen Wälder verkörpert. Seit Generationen verehren Nachtelfen und ihre Verwandten des Waldes diesen ruhigen Ort und treten fernab der belebten Hauptwege in Zwiesprache mit der Natur. Da die Horde jedoch nach Eschental vordringt, um Holz zu schlagen und Stützpunkte zu errichten, sieht sich der heilige Boden im gesamten Gebiet einem ungewissen Frieden gegenüber."}},faq={{q="Wer ist Aessina?",a="Aessina ist ein verehrter uralter Naturgeist und Wilder Gott, der mit dem Herzen der unberührten Wälder verbunden ist. Nachtelfen und Waldwesen ehren sie als die lebendige Seele der Natur, die die ungezähmte Wildnis verkörpert.",al={"aessina lore","wer ist aessina","schrein von aessina göttin"}},{q="Wo befindet sich der Schrein von Aessina?",a="Der Schrein liegt im südwestlichen Eschental, südwestlich von Maestras Posten und westlich der Siedlung Astranaar.",al={"schrein von aessina ort","wo ist der schrein von aessina","schrein von aessina finden"}},{q="Warum ist dieser Ort für die Nachtelfen von Bedeutung?",a="Der Schrein dient als uralte heilige Zuflucht, die den Waldgeistern geweiht ist. Stätten wie diese verbinden die Gesellschaft der Nachtelfen und ihre druidischen Traditionen direkt mit der ungezähmten Wildnis von Kalimdor.",al={"bedeutung des schreins von aessina","heilige stätte der nachtelfen"}}},fx={a3085ee2={q="Was ist der Schrein von Aessina?",a="Der Schrein von Aessina ist ein heiliger, uralter Waldzufluchtsort im südwestlichen Eschental, südwestlich von Maestras Posten und westlich von Astranaar gelegen. Dem mysteriösen Waldgeist und Wildgott Aessina gewidmet, steht der Schrein als friedlicher, mystischer Ort inmitten der tiefen Wildnis und spiegelt die uralte Bindung zwischen den Nachtelfen und der lebendigen Seele der Wälder Kalimdors wider.",al={"was ist der schrein von aessina","hintergrund zum schrein von aessina","über den schrein von aessina"}},d41b0789={q="Warum heißt er Schrein von Aessina?",a="Der Schrein hat seinen Namen von Aessina, einem schwer fassbaren Wildgott, der von Nachtelfendruiden und den Bewohnern des Waldes zutiefst verehrt wird. In alten Überlieferungen als schlagendes Herz des tiefen Waldes beschrieben, soll ihre Anwesenheit den dichtesten Wäldern Kalimdors Vitalität und stille Mystik verleihen, was diesen abgelegenen Hain zu einem natürlichen Ort für ihre Verehrung macht.",al={"warum heißt er schrein von aessina","namensherkunft schrein von aessina"}},["5764d345"]={q="Ist der Schrein von Aessina gefährlich?",a="Der Schrein selbst ist eine friedliche, natürliche Lichtung, aber das Eschental als Ganzes ist voller Gefahren. Zwischen der schleichenden Verderbnis, die sich durch Teile des verwunschenen Waldes ausbreitet, und gewaltsamen territorialen Scharmützeln zwischen dem Kriegshymnenclan und den Nachtelfenwächterinnen, ist das Alleinwandern durch die tiefen Wälder immer mit erheblichen Gefahren verbunden.",al={"ist der schrein von aessina gefährlich","gefahr am schrein von aessina","bedrohungen in der nähe des schreins von aessina"}}},fp="17,295,29.432.0,15.208.0,39.121.0,49.188.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="Schrein der schlafenden Flamme",s="Auf dem höchsten Gipfel nordwestlich des Tals der Prüfungen thront der Schrein der schlafenden Flamme, ein abgeschiedener Zufluchtsort, der von den Schamanen der Horde verehrt wird. Geleitet von seinem einsamen Hüter, Telf Joolam, wagen die Initianden den tückischen Aufstieg, um mit dem Element des Feuers in Zwiesprache zu treten und ihre spirituelle Meisterschaft zu beweisen.",h="Auf dem höchsten Gipfel nordwestlich des Tals der Prüfungen thront der Schrein der schlafenden Flamme, ein...",kw={"ruf des feuers","schlafende flamme","durotar","feuertotem","schrein","southfury watershed","telf joolam","das tal der prüfungen"},ang={["class:Shaman"]="Jeder junge Schamane der Orcs und Trolle muss den mühsamen Weg auf diese Klippe auf sich nehmen, um seine spirituelle Verbindung zum Feuer zu entfachen und sich sein Feuertotem zu verdienen.",["faction:Horde"]="Versteckt in den Bergen über Durotar bewahrt dieser isolierte Schrein uralte Elementarrite, die für das spirituelle Herz der neuen Horde von grundlegender Bedeutung sind."},sec={{t="Ein Gipfel der Prüfung und der Flamme",b="Um den Schrein der schlafenden Flamme zu erreichen, muss man einem schmalen, gewundenen Pfad trotzen, der am Südstrom am südwestlichen Rand des Southfury Watershed beginnt. Hoch über den roten Klippen von Durotar bietet der Berggipfel einen weiten Blick über die umliegenden Lande, auch wenn ein einziger Fehltritt am Abgrund den sicheren Tod bedeutet. In dieser stillen Zuflucht wandelt Telf Joolam, ein einsamer Einsiedler, der mit der Beaufsichtigung heiliger Riten betraut ist. Für angehende Schamanen der Orcs und Trolle, die sich dem rituellen Ruf des Feuers stellen, dient das Kohlenbecken des Schreins als Schmelztiegel: Hier müssen sie die schlummernden Kohlen mit der Glut eines bezwungenen Elementars entfachen und so ihre Macht beweisen, mit den zerstörerischen Geistern der Flamme in Kontakt zu treten und sie zu achten."}},faq={{q="Wie erreicht man den Schrein der schlafenden Flamme?",a="Der Pfad beginnt am Südstrom am südwestlichen Rand des Southfury Watershed, direkt nordwestlich des Tals der Prüfungen. Ein schmaler Bergpfad windet sich spiralförmig um den Gipfel und führt geradewegs hinauf zur Spitze.",al={"weg zum schrein der schlafenden flamme","pfad zur schlafenden flamme","berg der schlafenden flamme besteigen"}},{q="Warum ist dieser Schrein für Schamanen so wichtig?",a="Der Schrein ist eine heilige Stätte, an der angehende Schamanen der Horde lernen, das Element des Feuers zu verstehen und zu befehligen. Als Teil ihrer Reise beim Ruf des Feuers müssen Initianden zu diesem Gipfel reisen, um einen rituellen Trank zuzubereiten und das schlummernde Kohlenbecken zu entzünden.",al={"zweck des schreins der schlafenden flamme","warum schamanen hierher reisen","ruf des feuers schrein"}},{q="Wer ist Telf Joolam?",a="Telf Joolam ist ein einsamer Trolleinsiedler, der als Hüter des Schreins fungiert. Er leitet junge Schamanen durch ihre Prüfungen, braut einen Feuertrank, um ihre spirituelle Sicht zu wecken, und stellt ihre Entschlossenheit auf die Probe.",al={"wer ist telf joolam","schlafende flamme nsc","schreinhüter"}},{q="Was geschieht, wenn man das Kohlenbecken entzündet?",a="Schamanen, die die erforderlichen rituellen Bestandteile gesammelt und ein feindseliges Feuerelementar besiegt haben, legen dessen brennende Glut in das Kohlenbecken. Dies dient als Opfergabe, um zu beweisen, dass sie die Stärke und Disziplin besitzen, den unberechenbaren Geist der Flamme zu bändigen.",al={"kohlenbecken der schlafenden flamme","die flamme entzünden","quest schrein-kohlenbecken"}}},fx={b2d73685={q="Ist der Schrein der schlafenden Flamme gefährlich?",a="Der Schrein selbst ist friedlich, doch der Weg dorthin ist tückisch. Der gewundene Pfad, der sich an die Klippen des Berges klammert, ist eng und schwindelerregend; ein einziger Fehltritt kann Euch in den sicheren Tod auf den weit unter Euch liegenden Felsen stürzen lassen. Zudem erfordert das Herbeirufen und Binden des Elementarfeuers auf dem Gipfel absolute Konzentration, um nicht davon verzehrt zu werden.",al={"gefahr schrein der schlafenden flamme","ist der schrein der schlafenden flamme sicher?","ist es hier oben gefährlich?"}},a82c700c={q="Warum heißt er Schrein der schlafenden Flamme?",a="Der Gipfel hat seinen Namen von dem heiligen Becken, das kalt und still ruht, bis ein würdiger Schamane es erweckt. Die Flamme bleibt schlafend – ruhend – und wartet darauf, von einer Glut entfacht zu werden, die im Elementarkampf gewonnen wurde, und erwacht erst zum Leben, wenn sie während der Feuerprüfungen beschworen wird.",al={"warum schlafende flamme","namensherkunft schrein der schlafenden flamme","warum heißt es schrein der schlafenden flamme"}},["9edb20fb"]={q="Was ist der Schrein der schlafenden Flamme?",a="Auf dem höchsten Berggipfel nordwestlich vom Tal der Prüfungen gelegen, ist der Schrein der schlafenden Flamme ein heiliger Ort der Gemeinschaft für Schamanen der Horde. Er ist nur über einen gewundenen, schmalen Pfad über dem Südstrom zu erreichen und ist der Ort, an dem Initianden ihre spirituelle Autorität über das Elementarfeuer beweisen, indem sie sein heiliges Kohlenbecken entzünden.",al={"was ist der schrein der schlafenden flamme","schrein der schlafenden flamme durotar"}},["0def2f7d"]={q="Was ist am Schrein der schlafenden Flamme passiert?",a="Seit Generationen, seit die Horde sich in Durotar niedergelassen hat, sind junge Orc- und Trollschamanen auf diesen windgepeitschten Gipfel gestiegen, um ihre Prüfungen abzulegen. Hier bringen Anwärter gefangene Glut, die sie von besiegten Feuerelementaren gewonnen haben, um das zeremonielle Kohlenbecken des Berges zu entzünden, womit sie ihre Meisterschaft über die urzeitliche Flamme beweisen und sich unter den wachsamen Augen ihres Wächters ihre Feuertotems verdienen.",al={"geschichte des schreins der schlafenden flamme","vergangenheit des schreins der schlafenden flamme","was geschah am schrein der schlafenden flamme"}}},fp="27,297,27.723.0,49.218.0,39.242.0,19.211.0,41.245.0"}
P.entries["subzone:shrine-of-the-fallen-warrior"] = {n="Schrein des gefallenen Kriegers",s="Auf einem abgelegenen Bergkamm westlich des Wegekreuzes liegt der Schrein des gefallenen Kriegers, eine stille Gedenkstätte mit Blick auf die weiten roten Savannen des Brachlands. Gekennzeichnet durch einen Steinsockel mit den Initialen „MK“ und den Leichnam eines gefallenen Orc-Kriegers, wird er von der sanften Gegenwart einer Geistheilerin namens Koiter bewacht.",h="Auf einem abgelegenen Bergkamm westlich des Wegekreuzes liegt der Schrein des gefallenen Kriegers, eine...",kw={"brachland","das wegekreuz","koiter","gedenkstätte","michel koiter","schrein des gefallenen kriegers","twincruiser"},ang={["class:Warrior"]="Krieger aller Völker unternehmen oft eine stille Pilgerreise zu diesem Hügel, um einem gefallenen Waffenbruder Respekt zu zollen, der tapfer kämpfte, bevor er zur Legende wurde.",["faction:Horde"]="Mitten im Kernland des Territoriums der Horde gelegen, fängt diese einsame Ruhestätte die Ehre, die Pflicht und das Opfer ein, die den Kern der schamanischen und kriegerischen Traditionen Kalimdors bilden."},sec={{t="Eine stille Wacht",b="Versteckt hoch auf den Hügeln nordwestlich des Wegekreuzes steht der Schrein des gefallenen Kriegers als ungewöhnlich feierliche Zuflucht inmitten des Staubs und der Gefahren des Brachlands. Um ihn zu finden, müssen Reisende einen gewundenen Kammpfad südwestlich des Gipfels erklimmen, bis sie eine sanfte Anhöhe erreichen. Auf dem Gipfel ruht ein gemeißeltes Steinmonument, in dessen Sockel die Initialen „MK“ eingraviert sind. Davor liegt die gerüstete Gestalt eines ruhenden Orc-Kriegers, Tag und Nacht bewacht von einer namentlich benannten Geistheilerin namens Koiter. Hier gibt es keine Kriegshörner, nur stille Einkehr zu Ehren eines Streiters, der einst die Lande Kalimdors durchstreifte."},{t="Die Bedeutung der Gedenkstätte",b="Innerhalb der Welt steht der Schrein als dauerhafter Tribut an einen verstorbenen Streiter der Horde, dessen Seele in der Obhut der Geister verweilt. Außerhalb der Welt dient das Monument als von Herzen kommender Tribut der Grafiker des Spiels zu Ehren von Michel Koiter, einem geschätzten Illustrator, der während der Entwicklung der Welt verstarb. Der ruhende Krieger ist exakt nach Koiters eigenem Beta-Charakter Twincruiser modelliert und verewigt seine Gegenwart für immer unter dem offenen Himmel Kalimdors."}},faq={{q="Wo befindet sich der Schrein des gefallenen Kriegers?",a="Der Schrein liegt auf einem Hügel westlich des Wegekreuzes im nördlichen Brachland. Reisende können ihn erreichen, indem sie den Fuß eines Kamms südwestlich der Erhebung ausfindig machen und einem gewundenen Pfad hinauf zu der grasbewachsenen Kuppe folgen.",al={"schrein standort","wo ist der schrein","weg zum schrein des gefallenen kriegers"}},{q="Wer ist der Orc, der auf dem Sockel liegt?",a="Im Spiel stellt er einen verehrten gefallenen Krieger dar. In Wirklichkeit ist er direkt Twincruiser nachempfunden, dem Orc-Krieger-Charakter, den der verstorbene Blizzard-Künstler Michel Koiter während der frühen Entwicklung spielte.",al={"wer ist der tote orc","identität des gefallenen kriegers","twincruiser"}},{q="Was bedeutet das in den Stein gemeißelte „MK“?",a="Die runenartigen Initialen „MK“ ehren Michel Koiter, einen Senior Artist, der 2004 während der Entwicklung der Welt verstarb.",al={"initialen mk","wofür steht mk","buchstaben auf dem stein"}},{q="Wer ist die Geistheilerin, die neben dem Schrein steht?",a="Die Geistheilerin trägt den Namen Koiter. Anders als gewöhnliche Geistheiler, die nur Geistern im Tod erscheinen, hält Koiter Wacht und kann von lebenden Wanderern, die den Weg auf den Hügel auf sich nehmen, deutlich gesehen werden.",al={"geistheiler koiter","engel am schrein","wer ist der geist"}},{q="Gibt es Quests, die mit diesem Schrein verbunden sind?",a="Nein. Der Schrein des gefallenen Kriegers ist nicht Teil einer Questreihe oder eines Fraktionskonflikts. Er existiert rein als feierlicher Ort der Besinnung, des Gedenkens und des Tributs.",al={"schrein quest","quest für gefallenen krieger","gibt es hier eine quest"}}},fx={["7e92bc4e"]={q="Was ist der Schrein des gefallenen Kriegers?",a="Der Schrein des gefallenen Kriegers ist ein friedliches, feierliches Denkmal, das hoch oben auf einem Hügel westlich vom Das Wegekreuz thront. Er besteht aus einem verzierten Steinsockel, auf dem die ruhende Gestalt eines geehrten orkischen Kriegers liegt, bewacht von einem Obelisken und einem geisterhaften Wächter. Reisende aus allen Winkeln von Azeroth kommen hierher, um in der Stille ihre Ehrerbietung zu erweisen, fernab der Konflikte, die das Brachland verzehren.",al={"was ist der schrein des gefallenen kriegers","schrein des gefallenen kriegers brachland","denkmal auf hügel brachland"}}},fp="28,327,14.608.0,27.487.0,50.210.0,37.199.0,46.121.0,52.209.0,49.162.0"}
P.entries["subzone:si-7-stormwind-city"] = {fx={["3c33de19"]={q="Ist SI:7 gefährlich?",a="SI:7 stellt keine Bedrohung für loyale Bürger und Verbündete von Sturmwind dar. Hinter den Mauern bildet das verdeckte Geheimdienstnetzwerk des Königreichs seine Agenten aus und koordiniert sie. Doch wer sich ihnen in den Weg stellt oder die Krone bedroht, wird feststellen, dass ihre Meisterschurken, Späher und Attentäter zu den tödlichsten Gegnern in den Östlichen Königreiche zählen.",al={"ist si:7 gefährlich","gefahr bei si:7","ist si:7 sicher"}}}}
P.entries["subzone:silver-stream-mine"] = {n="Silberbachmine",s="Die Silberbachmine ist eine erschöpfte Zwergenmine im nördlichen Loch Modan, eingebettet zwischen der Station Algaz und dem Steinwerkdamm. Einst eine ergiebige Silberader für das Königreich Eisenschmiede, wurde die ausgegrabene Aushöhlung als Nachschubdepot der Miners' League umfunktioniert, bevor sie von Ungeziefer überrannt wurde. Heute hausen Tunnel Rat-Kobolde in den Stollen und horten gestohlene Ausrüstung sowie seltene mineralische Kuriositäten.",h="Die Silberbachmine ist eine erschöpfte Zwergenmine im nördlichen Loch Modan, eingebettet zwischen der Station...",kw={"charged rift gem","kobold","loch modan","miners league","silberbachmine","tunnel rat"},ang={["class:Mage"]="Magierlehrlinge reisen eigens in die gefährlichen, von Kobolden verseuchten Stollen, um Charged Rift Gems zu gewinnen – eine unverzichtbare Zutat für die Herstellung ritueller Gewänder.",["race:Dwarf"]="Für Zwerge ist die Silberbachmine ein ärgerlicher Verlust hart erarbeiteter Infrastruktur, in der nun plumpe Kobolde ein respektables Depot der Miners' League von Eisenschmiede besudeln."},sec={{t="Von der ergiebigen Ader zum Lagerdepot",b="Die Silberbachmine brachte einst reichlich kostbares Erz hervor und trug maßgeblich zu den Silberreserven von Eisenschmiede bei. Mit der Zeit gruben die Zwergenspitzhacken tief genug, um die primären Adern zu erschöpfen, was die weitläufigen Kammern in einen leeren unterirdischen Komplex verwandelte. Anstatt die hart erkämpften Erdarbeiten aufzugeben, wandelte die Miners' League die Schächte in ein sicheres Lagerdepot für Werkzeuge, Minenkisten und regionale Ausrüstung um. Sie dient zudem als einzige bekannte Quelle für seltene Charged Rift Gems, die neugierige Arkanisten auf der Suche nach heiklen Schneiderreagenzien anlocken."},{t="Der Koboldeinfall",b="Das ruhige Depot blieb nicht lange sicher. Aggressive Tunnel Rat-Kobolde, angelockt vom Geruch unbeaufsichtigter Werkzeuge, Kerzenwachs und vergessener unterirdischer Spalten, schwärmten in großer Zahl in die Schächte. Die Verwalter der Miners' League wurden prompt in die Kälte von Loch Modan vertrieben. Nun bewachen die Kobolde die gestohlenen Zwergenkisten mit manischem Eifer, während alte, zertrümmerte Orc-Katapulte und Wagen vergessen vor den hinteren Eingängen verweilen – stumme Zeugen älterer Grenzscharmützel."}},faq={{q="Wofür wurde die Silberbachmine ursprünglich genutzt?",a="Ursprünglich war sie eine ertragreiche Silbermine, die von den Zwergen von Eisenschmiede ausgehoben wurde. Nachdem die Adern versiegten, funktionierte die Miners' League von Eisenschmiede die leerstehenden unterirdischen Hallen zu einem Lagerdepot für Werkzeuge und Grabungsvorräte um.",al={"was ist die silberbachmine","geschichte der silberbachmine","warum wurde silberbach gebaut"}},{q="Wer besetzt derzeit die Mine?",a="Die Mine wurde vollständig von Tunnel Rat-Kobolden überrannt. Sie vertrieben die Zwergenaufseher und bewachen nun die Stollen, horten die verlassenen Vorratskisten der Liga und graben nach verbliebenen Resten.",al={"wer lebt in der silberbachmine","silberbachmine mobs","was ist in der silberbachmine"}},{q="Warum reisen Magier zur Silberbachmine?",a="Die Mine ist die einzige bekannte Quelle für Charged Rift Gems. Diese unbeständigen, magisch reaktiven Steine werden von Arkanisten der Allianz begehrt, um mächtige verzauberte Roben zu weben.",al={"magierquest silberbachmine","charged rift gems","silberbach magierroben"}},{q="Was sind die zerstörten Katapulte hinter der Mine?",a="Hinter der Mine stehen zerbrochene Orc-Wagen und zerstörte Katapulte – verwitterte Überbleibsel früherer Kriegskonflikte, welche die Durchgänge zwischen Loch Modan und den nördlichen Gebirgspässen bedrohten.",al={"orc-wagen hinter silberbach","zerstörte katapulte loch modan mine","horde belagerungsmaschinen loch modan"}}},fx={fbe48c53={q="Was ist die Silberbachmine?",a="Die Silberbachmine ist eine ehemalige Zwergengrabungsstätte in den nördlichen Felsen von Loch Modan, östlich von Station Algaz und südwestlich vom Der Steinwerkdamm gelegen. Einst eine reiche Silberader, die von Zwergen aus Eisenschmiede abgebaut wurde, diente sie später als Versorgungslager für die Minenarbeiterliga, bevor sie in feindliche Hände fiel.",al={"informationen zur silberbachmine","was ist die silberbachmine","über die silberbachmine"}},["6efdd539"]={q="Warum wurde die Silberbachmine aufgegeben?",a="Die Mine wurde ursprünglich als aktive Grabungsstätte stillgelegt, als die Silberadern vor langer Zeit erschöpft waren. Die Minenarbeiterliga nutzte die Tunnel noch eine Zeit lang als gesichertes Vorratslager, doch die Zwergenarbeiter wurden vollständig vertrieben, als aggressive Tunnelrattenkobolde den Ort stürmten, um alle verbliebenen Ressourcen für sich zu beanspruchen.",al={"warum ist die silberbachmine aufgegeben","warum verließen zwerge die silberbachmine","warum wurde silberbach aufgegeben"}},["339be7ce"]={q="Ist die Silberbachmine gefährlich?",a="Ja. Die Mine wurde vollständig von feindseligen Tunnelrattenkobolden überrannt. Diese unterirdischen Plagegeister sind extrem territorial und verzweifelt darauf bedacht, den Inhalt der Mine zu horten, weshalb sie jeden Reisenden oder Bergarbeiter angreifen, der es wagt, sich dem Eingang zu nähern oder sich in die Tiefen vorzuwagen.",al={"ist die silberbachmine gefährlich","bedrohungen in der silberbachmine","monster in der silberbachmine"}}},fp="18,394,31.556.0,20.490.0,52.233.0,32.202.0,42.169.0,46.195.0"}
P.entries["subzone:silverwing-grove"] = {n="Hain der Silberschwingen",s="Versteckt im südlichen Zentrum von Eschental nahe dem Himmelssturzsee dient der Hain der Silberschwingen als Aufmarschgebiet für die Schildwachen der Silberschwingen. Aus dieser befestigten Senke sammeln Nachtelfenkrieger die Streitkräfte der Allianz, um die Holzfäller des Kriegshymnenklans zurückzudrängen, die den Wald verwüsten.",h="Versteckt im südlichen Zentrum von Eschental nahe dem Himmelssturzsee dient der Hain der Silberschwingen als...",kw={"eschental","fallenskysee","schildwache weltensang","hain der silberschwingen","schildwachen der silberschwingen","warsongschlucht"},ang={["faction:Alliance"]="Der Hain ist der primäre Sammelplatz für Champions der Allianz, die sich sammeln und in die blutigen Scharmützel der Kriegshymnenschlucht ziehen wollen.",["race:NightElf"]="Für die Kaldorei verkörpert der Hain der Silberschwingen die unerschütterliche Entschlossenheit, der Schändung der heiligen Bäume durch die Äxte des Kriegshymnenklans Einhalt zu gebieten."},sec={{t="Frontlinie des Waldkriegs",b="Verborgen unter dem smaragdgrünen Blätterdach südwestlich vom Außenposten der Silberschwingen ist der Hain der Silberschwingen ein entscheidender militärischer Bereitstellungsraum für die Schildwachen der Silberschwingen. Weit davon entfernt, ein friedlicher Rückzugsort im Wald zu sein, fungiert er als operatives Herzstück für den erbitterten Territorialkampf der Nachtelfen gegen die Holzfällerarbeiten der Horde in der Kriegshymnenschlucht. Hochrangige Offiziere der Allianz, Nachschub und Kundschafter sammeln sich hier, um Scharmützel zu organisieren und Champions für die Verteidigung des uralten Eschental gegen die orkische Expansion zu mobilisieren."}},faq={{q="Welchem Zweck dient der Hain der Silberschwingen?",a="Der Hain der Silberschwingen dient als Aufmarschbasis für die Schildwachen der Silberschwingen. Hier organisieren das Militär der Nachtelfen und seine Verbündeten der Allianz die Bemühungen, den Abholzungen des Kriegshymnenklans entgegenzutreten und in den anhaltenden Konflikt in der Kriegshymnenschlucht einzugreifen.",al={"warum gibt es den hain der silverwing","was ist der hain der silverwing","zweck des hains der silverwing"}},{q="Wo befindet sich der Hain der Silberschwingen?",a="Er liegt im südlichen Zentrum von Eschental, südwestlich vom Außenposten der Silberschwingen und direkt westlich des Himmelssturzsees.",al={"hain der silverwing standort","wo ist der hain der silverwing","hain der silverwing finden"}},{q="Wer operiert aus dem Hain der Silberschwingen heraus?",a="Der Hain wird von den Schildwachen der Silberschwingen zusammen mit militärischen Befehlshabern der Allianz besetzt, darunter ein Brigadegeneral der Allianz, Logistikhändler und Offiziere wie Schildwache Weltensang, welche die Einsätze gegen die Horde koordinieren.",al={"wer ist im hain der silverwing","hain der silverwing npcs","wer leitet den hain der silverwing"}},{q="Können Hordespieler den Hain der Silberschwingen betreten?",a="Nein. Der Hain ist ein aktiver Militärposten, der von feindseligen Schildwachen und Wachen der Allianz bevölkert wird, die jeden eindringenden Angehörigen der Horde sofort bei Sichtkontakt angreifen.",al={"ist der hain der silverwing feindselig","kann die horde zum hain der silverwing","horde hain der silverwing"}}},fx={["92f0e5de"]={q="Was ist der Hain der Silberschwingen?",a="Der Hain der Silberschwingen ist eine befestigte Nachtelfen-Enklave im südlichen Zentrum von Eschental, die als wichtigster Vorposten der Schildwachen der Silberschwingen dient. Von diesem schattigen Bollwerk aus organisieren die Schildwachen die Allianzstreitkräfte und koordinieren ihren anhaltenden Kampf gegen die Vorhut des Kriegshymnenklans in der benachbarten Kriegshymnenschlucht.",al={"was ist der hain der silberschwingen","hain der silberschwingen lore","über den hain der silberschwingen"}},e4f50e36={q="Ist der Hain der Silberschwingen gefährlich?",a="Für Champions der Allianz ist der Hain ein schwer bewachtes Refugium, das von erfahrenen Schildwachen und Führungsoffizieren beschützt wird. Für Eindringlinge der Horde ist es jedoch tödliches Gebiet. Da es der primäre Bereitstellungsraum für den Konflikt gegen den Kriegshymnenklan ist, schlagen die Verteidiger des Hains jeden Eindringling der Horde sofort nieder.",al={"ist der hain der silberschwingen sicher","gefahr hain der silberschwingen","bedrohungen für den hain der silberschwingen"}}},fp="16,273,28.504.0,40.250.0,34.116.0,37.228.0,41.159.0"}
P.entries["subzone:silverwing-outpost"] = {n="Außenposten der Silberschwingen",s="Der Außenposten der Silberschwingen ist eine befestigte Nachtelfengarnison im südlich-zentralen Eschental, östlich des Falfarren. Befehligt von Duriel Moonfire, dient er als die östlichste Bastion der Allianz gegen die Horde im umkämpften Waldland.",h="Der Außenposten der Silberschwingen ist eine befestigte Nachtelfengarnison im südlich-zentralen Eschental...",kw={"eschental","duriel moonfire","der falfarren","außenposten der silberschwingen","schildwachen der silberschwingen","splintertreeposten","torek"},ang={["faction:Alliance"]="Der Außenposten der Silberschwingen dient als Eure lebenswichtige vorgeschobene Schanze auf der Hordenseite des Flusses und hält die orcische Expansion vom Splitterholzposten aus in Schach.",["faction:Horde"]="Für die Horde ist der Außenposten ein unerträglicher Dorn im Auge des Splitterholzpostens, der Eure Bewegungen und Nachschublinien durch das südliche Eschental direkt behindert."},sec={{t="Östlich des Falfarren",b="Südwestlich des Splitterholzpostens und knapp nördlich der Grenze zum Brachland gelegen, nimmt der Außenposten der Silberschwingen eine naturgemäß gefährliche strategische Position ein. Da er sich auf der Ostseite des Falfarren befindet – einem von der Horde schwer umkämpften und patrouillierten Gebiet –, dient der Außenposten als direkter Schild für die Nachtelfenbesitztümer tiefer im Wald. Duriel Moonfire und ihre Schildwachen der Silberschwingen stehen unter ständiger Belagerung durch die nahegelegenen Orcs, die entschlossen sind, die Streitkräfte der Nachtelfen vollständig aus dem Gebiet zu vertreiben."},{t="Die beständige Front",b="Die Scharmützel rund um den Außenposten der Silberschwingen gehören zu den heftigsten in Eschental. Vom Splitterholzposten ausgehende Kriegstrupps der Orcs, wie etwa die von Torek angeführten Räuber, verüben unerbittliche Hinterhalte auf die Mauern der Garnison. Für die Horde ist die Ausschaltung des Außenpostens unerlässlich, um die Straße zu sichern und Ressourcenoperationen ohne die ständige Bedrohung durch Gegenangriffe der Schildwachen auszuweiten."}},faq={{q="Wo befindet sich der Außenposten der Silberschwingen?",a="Er liegt im südlich-zentralen Eschental, südwestlich des Splitterholzpostens, nördlich der Grenze zum Brachland und auf der Ostseite des Falfarren.",al={"silverwing standort","wo ist silverwing","außenposten der silverwing karte"}},{q="Wer befehligt den Außenposten der Silberschwingen?",a="Der Außenposten wird von Duriel Moonfire befehligt, einer Nachtelfenoffizierin, die die Schildwachen der Silberschwingen anführt, welche die östlichen Weiten des Waldes verteidigen.",al={"silverwing anführer","wer leitet außenposten der silverwing","duriel moonfire"}},{q="Warum greift die Horde diesen Außenposten so aggressiv an?",a="Der Außenposten der Silberschwingen liegt direkt auf der Ostseite des Falfarren nahe dem Splitterholzposten. Seine Präsenz ermöglicht es den Schildwachen, die Nachschublinien der Horde abzuschneiden und die Operationen der Orcs in Eschental direkt zu bedrohen.",al={"warum silverwing angreifen","horde interesse an silverwing","splintertree gegen silverwing"}},{q="Wer sind die Schildwachen der Silberschwingen?",a="Die Schildwachen der Silberschwingen sind ein militanter Orden von Nachtelfenkriegern und Jägerinnen, der sich dem Schutz von Eschental vor Übergriffen verschrieben hat, insbesondere gegen die vordringenden Holzfällerlager und Kriegstrupps der Horde.",al={"was sind silverwings","schildwachen der silverwing lore","silverwing fraktion"}}},fx={["478d573a"]={q="Was ist der Außenposten der Silberschwingen?",a="Der Außenposten der Silberschwingen ist der östlichste Militärstützpunkt der Allianz in Eschental, der errichtet wurde, um die Länder der Nachtelfen gegen die Horde zu verteidigen. Er liegt jenseits vom Der Falfarren südwestlich vom Splitterholzposten und dient als kritische Frontgarnison, an der die Schildwachen der Silberschwingen die Expansion der Horde aus dem Brachland und dem Das Holzfällerlager des Kriegshymnenklans bekämpfen.",al={"was ist der außenposten der silberschwingen","zweck außenposten der silberschwingen","über den außenposten der silberschwingen"}},ad619a65={q="Ist der Außenposten der Silberschwingen gefährlich?",a="Es ist eine aktive Kampfzone. Da der Außenposten isoliert auf der östlichen Seite vom Der Falfarren liegt, ist er unerbittlichen Angriffen von nahegelegenen Orks des Kriegshymnenklans und Überfalltrupps aus dem Splitterholzposten ausgesetzt. Reisende der Allianz finden hinter seinen Mauern Zuflucht und bewaffnete Verteidiger, aber Streitkräfte der Horde werden auf wachsame, feindselige Schildwachen treffen, die sofort das Feuer eröffnen.",al={"ist der außenposten der silberschwingen gefährlich","bedrohungen außenposten der silberschwingen","gefahren am außenposten der silberschwingen"}},b348ef17={q="Warum heißt er Außenposten der Silberschwingen?",a="Die Garnison hat ihren Namen direkt von den Schildwachen der Silberschwingen, der elitären militärischen Einheit der Nachtelfen, die hier stationiert ist, um Eschental zu schützen und die Übergriffe der Horde zur Holzernte zu unterbinden.",al={"warum heißt er außenposten der silberschwingen","namensherkunft außenposten der silberschwingen","bedeutung silberschwinge"}}},fp="18,248,21.501.0,18.384.1,36.150.0,32.142.0,55.217.0,33.213.0"}
P.entries["subzone:sishir-canyon"] = {n="Sishircanyon",s="Der Sishircanyon ist eine zerklüftete Schlucht im Steinkrallengebirge, die sich ostwärts durch die schroffen Höhen schneidet. Dicht umschwärmt von monströsen Tiefenmoosspinnen und erstickt von Spinnweben, dient er als gefährlicher Zugang zu den Ruins of Eldre'thar. Reisende, die sich in seine verworrenen Tiefen wagen, müssen sich gegen giftige Spinnentiere und ihre brütende Matriarchin behaupten.",h="Der Sishircanyon ist eine zerklüftete Schlucht im Steinkrallengebirge, die sich ostwärts durch die schroffen...",kw={"besseleth","tiefenmoos","eldre'thar","sishircanyon","spinnen","steinkrallengebirge","spinnweben"},ang={["class:Hunter"]="Die gefährlichen Netze und giftigen Tiefenmoosspinnen machen den Sishircanyon zu einem anspruchsvollen Prüfungsort für Jäger, die wilde Bestien auf engem Raum in der Schlucht aufspüren und fangen.",["race:NightElf"]="Der überrannte Canyon schneidet den leichten, sicheren Weg zu den angestammten Ruins of Eldre'thar ab, sodass sich die Schildwachen und Gelehrten der Kaldorei durch dichte Spinnennester kämpfen müssen, um ihr Erbe zu erreichen."},sec={{t="Der verwebte Pass",b="Der Sishircanyon zweigt von den Bergstraßen des Steinkrallengebirges ab und ist ein tückischer natürlicher Korridor, der zu den uralten Ruins of Eldre'thar führt. Statt eines ruhigen Bergpfads ist die Schlucht vollkommen von Tiefenmoosspinnen überrannt worden. Ihre klebrigen Seidenteppiche und Gelege von Eiersäcken ersticken den steinigen Boden sowie die Felswände und verwandeln die Schlucht in ein lebendiges Nest. Reisende und Schildwachen, welche die dahinter liegenden Ruinen der Nachtelfen aufsuchen wollen, müssen sich ihren Weg durch Schwärme aggressiver Netzspinner bahnen."},{t="Besseleths Domäne",b="In den tiefsten Winkeln des Canyons lauert Besseleth, die gewaltige und tödliche Matriarchin der Tiefenmoosbrut. Ihr Gift und ihre monströse Größe machen sie zum Schrecken für jeden, der versucht, den Pass zu sichern. Die örtlichen Streitkräfte im Steinkrallengebirge behalten den Canyon wachsam im Auge und warnen Abenteurer davor, dass ein Vorstoß in die verwebten Tiefen nicht nur vereinzelte Spinnen bedeutet, sondern einen Spitzenprädator, der seine Brut erbittert verteidigt."}},faq={{q="Was ist der Sishircanyon?",a="Der Sishircanyon ist eine von Spinnen heimgesuchte Schlucht im Steinkrallengebirge, die sich von den Hauptgebirgspfaden zu den uralten Ruins of Eldre'thar windet.",al={"wo ist der sishircanyon","sishircanyon standort"}},{q="Welche Kreaturen leben im Canyon?",a="Der Canyon wird vollends von räuberischen Tiefenmoosspinnen beansprucht. Die Spinnentiere haben die Schlucht mit dichten Netzen und Eiersäcken überzogen und machen Jagd auf alles, was ihr Revier betritt.",al={"monster im sishircanyon","spinnen in schlucht steinkrallengebirge"}},{q="Wer ist Besseleth?",a="Besseleth ist die furchterregende Spinnenmatriarchin, die tief im Sishircanyon haust. Sie führt die Tiefenmoosbrut an und stellt die größte Gefahr für Reisende dar, die das Gebiet durchqueren.",al={"besseleth standort","riesenspinne sishircanyon"}},{q="Wohin führt der Sishircanyon?",a="Folgt man dem Canyon nach Osten, gelangt man direkt zu den Ruins of Eldre'thar, einer uralten Nachtelfenstätte hoch in den Bergen.",al={"was ist am ende des sishircanyons","pfad durch den sishircanyon"}}},fx={["8c6e4ccd"]={q="Ist der Sishircanyon gefährlich?",a="Der Sishircanyon ist extrem gefährlich für jeden Reisenden, der nicht auf Spinnentiere vorbereitet ist. Die Schlucht ist vollständig von aggressiven Deepmoss-Spinnen überlaufen, die dichte Netze über die Felswände spannen und Gelege bewachen. Wer zu tief vordringt, gerät in den Weg ihrer monströsen Brutmutter, Besseleth.",al={"gefahr sishircanyon","ist der sishircanyon sicher","bedrohungen sishircanyon"}}},fp="13,352,15.507.0,18.412.0,22.148.0,34.180.0,17.178.0,30.134.0"}
P.entries["subzone:skittering-dark"] = {n="Das Huschdunkel",s="Das Huschdunkel ist eine verlassene Mine und eine schattenhafte Waldsenke im westlichen Silberwald. Von aggressiven Riesenspinnen heimgesucht, sind die Höhle und die umliegenden Wälder voller Spinnweben und Gefahren für unvorsichtige Tiere und Reisende.",h="Das Huschdunkel ist eine verlassene Mine und eine schattenhafte Waldsenke im westlichen Silberwald.",kw={"krethis","mine","nördlicher gezeitenstrom","silberwald","das huschdunkel","spinne"},ang={["faction:Horde"]="Reisende der Horde, die sich in den Silberwald wagen, sollten sich vorsehen: Die Spinnen des Huschdunkels lauern unvorsichtiger Beute auf, die aus den umliegenden Wäldern in ihre verwebten Höhlen gerät."},sec={{t="Eine verwebte Senke",b="Eingebettet in die Hügel direkt östlich der Westküste von Nördlicher Gezeitenstrom war Das Huschdunkel einst eine aktive Mine. Heute sind die Schächte vollständig von Spinnweben überwuchert und dienen Riesenspinnen als weitläufiges Nest. Da der schattenhafte Weber Krethis den Außenbereich heimsucht, machen die Spinnen Jagd auf alles, was sich zu nah heranwagt."}},faq={{q="Was ist das Huschdunkel?",a="Es ist eine verlassene Mine im westlichen Silberwald, die vollständig von Riesenspinnen überrannt wurde. Das Höhlennetz und die umliegenden Bäume sind voller klebriger Netze und räuberischer Spinnentiere.",al={"huschdunkel mine","was ist diese mine","spinnenhöhle silberwald"}},{q="Wer führt die Spinnen in der Mine an?",a="Es ist kein einzelner Herrscher der Brut bekannt. Die gefürchtetste unter den Spinnen ist Krethis Shadowspinner, ein seltener und gefährlicher Weber, der in und um die Mine herumstreift.",al={"spinnenboss","huschdunkel boss","matriarchin"}},{q="Wo befindet sich das Huschdunkel?",a="Es liegt eingebettet an den Hügeln im westlichen Silberwald, direkt östlich der als Nördlicher Gezeitenstrom bekannten Küstenlinie.",al={"huschdunkel standort","huschdunkel finden"}}},fx={["958edcba"]={q="Wer lebt im Das Huschdunkel?",a="Die Mine und die umliegende Senke sind von Riesenspinnen überrannt. Sie lauern in dunklen Felsspalten und spinnen dicke Netze über die felsigen Hänge und Tunnel. Eine gefürchtete, seltene Spinne namens Krethis Shadowspinner treibt ebenfalls in und um die Mine herum ihr Unwesen.",al={"wer lebt im das huschdunkel","einwohner das huschdunkel","welche kreaturen leben im das huschdunkel"}},["040a6057"]={q="Ist das Das Huschdunkel gefährlich?",a="Extrem gefährlich. Die aggressiven Spinnen überfallen jeden, der dumm genug ist, sich ihren Nestern zu nähern, und ziehen ahnungslose Beute tief in ihre Netze in den alten Minenschächten.",al={"wie gefährlich ist das das huschdunkel","ist das das huschdunkel gefährlich","gefahr das huschdunkel"}},ecb7b94e={q="Warum ist die Mine im Das Huschdunkel aufgegeben?",a="Die Mine wurde einst betrieben, bevor die Pest und der Krieg Lordaeron verwüsteten, aber welches sterbliche Unternehmen auch immer hier Erz abbaute, brach schon vor langer Zeit zusammen. Da sie während des Untergangs des Königreichs völlig unbeaufsichtigt blieb, boten die unterirdischen Schächte und schattigen Tunnel einen fruchtbaren, abgelegenen Brutplatz für monströse Spinnentiere, was jegliche verbliebene Industrie vollständig vertrieb.",al={"warum ist das das huschdunkel aufgegeben","wer baute im das huschdunkel ab","warum verließen bergleute das das huschdunkel"}},["0b1ef10a"]={q="Warum heißt es Das Huschdunkel?",a="Der Name spiegelt sowohl die düstere Natur des verlassenen Schachts als auch das unaufhörliche Rascheln des Schwarms darin wider. Unter der ewigen Finsternis der schattigen Hügel und Höhlenwände des Silberwalds ist das einzige beständige Geräusch das Zirpen und Huschen von tausenden Spinnenbeinen, die sich durch die Dunkelheit bewegen.",al={"warum heißt es das huschdunkel","ursprung des namens das huschdunkel","wie bekam das huschdunkel seinen namen"}}},fp="15,240,15.324.0,28.197.0,34.159.0,37.117.0"}
P.entries["subzone:skull-rock"] = {n="Die Knochenhöhle",s="Die Knochenhöhle ist eine Höhle in den östlichen Klippen an der Küste von Durotar, direkt östlich von Orgrimmar. Sie dient dem dämonischen Kult der Burning Blade als befestigter Zirkel direkt vor der Nase der Hauptstadt.",h="Die Knochenhöhle ist eine Höhle in den östlichen Klippen an der Küste von Durotar, direkt östlich von...",kw={"burning blade","kultisten","durotar","gazz'uz","orgrimmar","die knochenhöhle"},ang={["class:Warlock"]="Die in der Knochenhöhle praktizierten dunklen Künste zeigen die ungebremste Ausbreitung dämonischen Einflusses, den Thralls Horde auszumerzen und einzudämmen versucht.",["faction:Horde"]="Die Beseitigung der Kultisten aus der Knochenhöhle ist entscheidend, um die Zugänge zur Küste von Durotar zu sichern und Orgrimmar vor einer Unterwanderung von innen heraus zu schützen."},sec={{t="Ein Unterschlupf von Kultisten",b="Verborgen unter den zerklüfteten Felsen im Nordosten Durotars ist Die Knochenhöhle eine der gefährlichsten Hochburgen des Kults der Burning Blade in der Region. Dunkle Kultisten, teufelsanbetende Orcs und Beschwörer versammeln sich tief in den verwinkelten Tunneln, um dämonische Künste zu praktizieren und Verschwörungen gegen die aufkeimende Horde zu spinnen. Die Zelle wird von dem gefährlichen Hexenmeister Gazz'uz angeführt, dessen Machenschaften eine unmittelbare Bedrohung für die nahegelegenen Gates of Orgrimmar und für Reisende entlang der östlichen Küste darstellen."}},faq={{q="Was ist Die Knochenhöhle?",a="Die Knochenhöhle ist ein Höhlensystem im Nordosten Durotars entlang der Küste. Sie ist von Kultisten der Burning Blade besetzt, die ihren natürlichen Schutz nutzen, um Pläne gegen Thralls Horde zu schmieden.",al={"die knochenhöhle","wo ist die knochenhöhle","was ist in der knochenhöhle"}},{q="Wer kontrolliert Die Knochenhöhle?",a="Die Höhle wird vom Kult der Burning Blade heimgesucht, der von der tiefsten Kammer der Höhle aus durch den Orc-Hexenmeister Gazz'uz angeführt wird.",al={"wer leitet die knochenhöhle","wer beherrscht die knochenhöhle","boss der knochenhöhle"}},{q="Warum sorgt sich die Horde um diese Höhle?",a="Ihre Nähe zu Orgrimmar macht sie zu einem ernsten Sicherheitsrisiko. Die Burning Blade versucht aktiv, Thralls neues Reich zu untergraben und die Orcs wieder in die dämonische Knechtschaft zu stürzen.",al={"warum die knochenhöhle säubern","warum ist die knochenhöhle gefährlich"}}},fp="10,195,17.478.0,19.183.0,24.118.0,40.175.0"}
P.entries["subzone:slag-pit"] = {n="Die Schlackengrube",s="Die Schlackengrube ist eine weitläufige unterirdische Bergbauausgrabung, die im Kessel der Sengenden Schlucht liegt. Unter der Aufsicht skrupelloser Zuchtmeister und Sklaventreiber der Dunkeleisenzwerge werden diese feurigen Tunnel im Schatten des Schwarzfels durch Zwangsarbeit vorangetrieben. Eindringlinge müssen sich nicht nur feindseligen Zwergenaufsehern stellen, sondern auch unersättlichen Incendosauriern, die in den unteren Ebenen lauern.",h="Die Schlackengrube ist eine weitläufige unterirdische Bergbauausgrabung, die im Kessel der Sengenden Schlucht...",kw={"der kessel","dunkeleisen","incendosaurier","sengende schlucht","die schlackengrube","sklaventreiber","sklaven","zuchtmeister"},ang={["profession:Mining"]="Die tiefen Schächte der Schlackengrube schneiden geradewegs in den mineralreichen Leib der Sengenden Schlucht und machen sie zu einer ertragreichen – wenn auch außergewöhnlich gefährlichen – Quelle hochwertiger Erze.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede ist der Anblick der Grausamkeit der Dunkeleisen-Sklaventreiber in der Schlackengrube eine bittere Mahnung an die tiefe Spaltung zwischen den Klans."},sec={{t="Unterirdische Fron",b="Tief in die Tiefen des Kessels gegraben, bildet die Schlackengrube den zermürbenden industriellen Motor der Dunkeleisenzwerge in der Sengenden Schlucht. Tag und Nacht werden versklavte Arbeiter unter der Peitsche brutaler Aufseher und Zuchtmeister dazu angetrieben, reiche Erze und Mineralien abzubauen. Die Umgebung ist rau und erstickend, geprägt von sengender Hitze, beißendem Staub und dem Klirren eiserner Spitzhacken. Die Dunkeleisenzwerge halten eine unbarmherzige Disziplin über ihre Ausgrabung aufrecht und wehren jede Einmischung von außen in ihre Nachschublinien zu den Schwarzfelstiefen gewaltsam ab."},{t="Tiefen der Grube",b="Über die Grausamkeit der Sklaventreiber hinaus stellen die Tunnel selbst eine tödliche Gefahr für Arbeiter und Eindringlinge gleichermaßen dar. In den unteren Bereichen der Ausgrabung bricht das Erdreich zu sengenden Höhlen auf, die von Incendosauriern bewohnt werden – wilden, reptilienartigen Bestien, die im feurigen Untergrund heimisch sind. Trotz der ständigen Gefahr, von diesen unterirdischen Raubtieren verschlungen zu werden, treiben die Herrscher der Dunkeleisenzwerge ihre Arbeitskräfte immer tiefer in das Gestein, vollkommen gleichgültig gegenüber den Menschenleben, die dabei verloren gehen."}},faq={{q="Wo befindet sich die Schlackengrube?",a="Die Schlackengrube liegt tief im Kessel, dem gewaltigen Ausgrabungskrater, der das Zentrum der Sengenden Schlucht beherrscht. Ihre Tunnel zweigen direkt unter den oberirdischen Bergbauarbeiten ab.",al={"schlackengrube standort","wo ist die schlackengrube","weg zur schlackengrube"}},{q="Wer kontrolliert die Schlackengrube?",a="Die Mine wird vollständig vom Dunkeleisenklan betrieben. Sklaventreiber und Zuchtmeister der Dunkeleisenzwerge patrouillieren durch die Schächte, setzen eine brutale Disziplin durch und treiben ihre Gefangenen rund um die Uhr zum Graben an.",al={"wer kontrolliert die schlackengrube","schlackengrube fraktion","dunkeleisenzwerge schlackengrube"}},{q="Warum greifen die Sklavenarbeiter Eindringlinge an?",a="Obwohl die versklavten Arbeiter Außenstehenden gegenüber nicht von Natur aus aggressiv sind, sitzt ihre Furcht vor ihren Dunkeleisenmeistern tief. Wird ein Sklaventreiber oder Zuchtmeister in ihrer Nähe angegriffen, eilen die panischen Arbeiter ihrem Aufseher zu Hilfe, um schwerer Bestrafung zu entgehen.",al={"warum greifen sklaven an","feindselige sklaven","sklavenarbeiter aggro"}},{q="Welche Kreaturen leben in der Schlackengrube?",a="Neben den Dunkeleisenzwergen und ihren Sklaven sind die tiefsten Bereiche der Grube von Incendosauriern verseucht – aggressiven Raubtieren mit Flammenschuppen, die durch die unterirdischen Tunnel streifen.",al={"monster in der schlackengrube","incendosaurier","schlackengrube bestien"}}},fp="8,370,17.539.0,17.505.0,30.181.0,26.185.0,42.256.0,36.197.0"}
P.entries["subzone:slaughter-hollow"] = {n="Schlächtergrotte",s="Schlächtergrotte ist ein abgelegener Ogerhügel, der in den verschneiten Höhen des Alteracgebirges verborgen liegt. Unter der Kontrolle des brutalen Crushridge-Klans dient er eher als raues Lager denn als belebte Siedlung. Reisende haben selten einen Grund, das Gebiet zu betreten, es sei denn, sie jagen Oger oder erkunden die gefrorenen Gebirgspässe.",h="Schlächtergrotte ist ein abgelegener Ogerhügel, der in den verschneiten Höhen des Alteracgebirges verborgen...",kw={"alterac","crushridge","hillsbrad","ogerhügel","rizz loosebolt","schlächtergrotte"},ang={["race:Gnome"]="Die bedauerliche Gefangennahme von Rizz Loosebolt durch die Crushridge dient als deutliche Warnung an Tüftler und Späher, die unvorbereitet durch die Pässe von Alterac ziehen."},sec={{t="Ein Ogerbau",b="Hoch in den Gipfeln an der Grenze zwischen Hillsbrad und Alterac verborgen, dient Schlächtergrotte als Lager für die örtlichen Crushridge-Oger. Wie viele über das Hochland verstreute Ogerhügel ist der Ort von behelfsmäßigen Lagerfeuern, weggeworfenen Knochen und primitiven Unterkünften übersät. Während andere Ogerhöhlen in den Bergen häufigen Konflikten um Territorien oder gestohlene Vorräte ausgesetzt sind, bleibt Schlächtergrotte weitgehend ruhig und wird von größeren militärischen Feldzügen umgangen."},{t="Gefangene und Reisende",b="Aufgrund seiner Abgeschiedenheit dient der Hügel gelegentlich als Aufbewahrungsort für unglückliche Gefangene, die entlang der Bergpfade verschleppt wurden. Unter Reisenden erzählt man sich von einem unglückseligen Gnom namens Rizz Loosebolt, der hier in einem primitiven Käfig eingesperrt ist und versucht, mit jedem Vorbeikommenden zu feilschen. Solch bedauernswerte Gefangene ergehen sich selten gut angesichts des Appetits des Crushridge-Klans."}},faq={{q="Was ist Schlächtergrotte?",a="Schlächtergrotte ist ein Ogerlager im Alteracgebirge, das vom Crushridge-Klan bewohnt wird. Es zeichnet sich durch primitive Hügelbehausungen und Feuerstellen aus, die typisch für Ogersiedlungen im Hochland sind.",al={"schlächtergrotte lore","was ist dieser ort","schlächtergrotte hillsbrad"}},{q="Wer lebt in Schlächtergrotte?",a="Die Senke wird ausschließlich von Crushridge-Ogern bewohnt – demselben Klan, der auch die nahe gelegenen Ruinen von Alterac und verschiedene umliegende Außenposten beherrscht.",al={"wer ist hier","schlächtergrotte mobs","wer kontrolliert schlächtergrotte"}},{q="Gibt es hier Quests?",a="Keine formellen Quests schicken Abenteurer direkt nach Schlächtergrotte. Es ist größtenteils ein abgelegener Bau, den man bei der Erkundung des bergigen Geländes entdeckt.",al={"schlächtergrotte quests","quests in schlächtergrotte","warum hierher kommen"}},{q="Wer war der Gnom, der hier eingesperrt war?",a="Ein Gnom namens Rizz Loosebolt wird in einem Käfig im Inneren der Senke gefangen gehalten und bietet jedem, der ihn findet, Waren an.",al={"rizz loosebolt","gnom im käfig","schlächtergrotte händler"}}},fx={["446b3423"]={q="Ist die Schlächtergrotte gefährlich?",a="Ja, die Schlächtergrotte ist außerordentlich gefährlich. Tief in den verschneiten Pässen des Alteracgebirges dient diese Grotte als Ogerhügel, der vor feindseligen Ogern der Crushridge wimmelt. Wer unvorbereitet in ihr Lager wandert, zieht schnell den Zorn mehrerer schwerfälliger Bestien auf sich.",al={"ist die schlächtergrotte sicher","gefahr in der schlächtergrotte","wie gefährlich ist die schlächtergrotte"}}},fp="16,307,14.439.0,22.381.0,25.183.0,30.145.0,26.151.0,29.112.0"}
P.entries["subzone:slaughtered-lamb"] = {n="Slaughtered Lamb",s="Versteckt im Magierviertel von Sturmwind scheint das Slaughtered Lamb nicht mehr als eine ruhige, verrufene Taverne zu sein. Unter seinen Dielen verbergen jedoch weitläufige Katakomben das Sanktum und die Übungsplätze der ungesetzlichen Hexenmeister der Allianz.",h="Versteckt im Magierviertel von Sturmwind scheint das Slaughtered Lamb nicht mehr als eine ruhige, verrufene...",kw={"katakomben","jarel moor","das magierviertel","slaughtered lamb","sturmwind","hexenmeister","wischock","zardeth"},ang={["class:Warlock"]="Die Katakomben darunter sind Eure primäre Zuflucht in Sturmwind und bieten Klassenlehrer, Rituale zur Dämonenbindung und Aufgaben, die für das Meistern der dunklen Künste unerlässlich sind.",["faction:Alliance"]="Während die Allianz für das Licht und die Ordnung eintritt, offenbart das Slaughtered Lamb die unausgesprochene Bereitschaft des Königreichs, dunkle Magie in seinem Schatten zu dulden."},sec={{t="Eine dünne Tarnung",b="Oberflächlich betrachtet bietet das Slaughtered Lamb kaum mehr als finstere Ecken und spärliche Gäste, bedient von Wirt Jarel Moor, der beiläufige Besucher warnt, sich von den Schatten fernzuhalten. Diese Warnung ist wörtlich gemeint. Der Abstieg durch die hinteren Gänge offenbart einen unterirdischen Komplex aus Grüften und Beschwörungskreisen, in dem menschliche Hexenmeister und herübergekommene Praktizierende aus Khaz Modan offen Teufelsarkana studieren – geschützt vor den missbilligenden Blicken der Kirche des Heiligen Lichts und der Kirin Tor."},{t="Die Zechschuld des Adligen",b="Der Betrieb eines Teufelszirkels im Herzen der Hauptstadt bringt ständige Gefahr mit sich. Als Lord Baurles K. Wischock die im Keller lauernden Hexenmeister entdeckte, drohte er damit, das Haus der Adligen zu mobilisieren und beim Thron eine umfassende Untersuchung zu beantragen. In Wahrheit versuchte der Aristokrat lediglich, sich vor einer ruinösen Zechschuld zu drücken. Bevor seine Aufregung echte Aufmerksamkeit erregen konnte, fädelte Zardeth der Schwarzen Klaue ein, dass Wischock ein tödliches Gebräu trank, was den Einmischer dauerhaft zum Schweigen brachte und die Geheimnisse der Zuflucht wahrte."}},faq={{q="Was geht unter dem Slaughtered Lamb wirklich vor sich?",a="Die Katakomben unter der Taverne dienen als verborgenes Sanktum für Sturmwinds Hexenmeister. Praktizierende der Dämonologie und Shadow Magic versammeln sich dort, um Lehrlinge zu unterweisen, Beschwörungen durchzuführen und Teufelskünste auszuüben, die auf den Straßen darüber verboten sind.",al={"was ist unter dem slaughtered lamb","slaughtered lamb keller","wer ist im slaughtered lamb"}},{q="Weiß die Stadtwache von Sturmwind von den Hexenmeistern?",a="Die Taverne operiert unter einem heiklen Schleier plausibler Abstreitbarkeit. Teufelsmagie wird von der Kirche des Heiligen Lichts und der Magierakademie mit tiefem Misstrauen betrachtet, was den Zirkel dazu zwingt, im Verborgenen zu agieren und jeden aggressiv mundtot zu machen, der droht, sie vor den königlichen Autoritäten zu entlarven.",al={"wissen wachen von hexenmeistern","warum werden hexenmeister nicht verhaftet","ist das slaughtered lamb illegal"}},{q="Wer war Lord Wischock und was geschah mit ihm?",a="Lord Baurles K. Wischock ist ein Adliger und Stammgast der Taverne, der die darunter verborgenen Hexenmeister entdeckte. Er sorgte für Aufsehen im Haus der Adligen und setzte sich für eine umfassende Untersuchung ein, in der Hoffnung, den König zur Schließung des Etablissements zu bewegen.",al={"baurles wischock","lord wischocks schicksal","wer ist wischock"}},{q="Warum kommen Gnom-Hexenmeister hierher?",a="Nach dem Fall von Gnomeregan zogen die Hexenmeistermeister der Stadt nach Eisenschmiede, wo Magni sie aufmerksam überwacht. Lago Blackwrench schickt Novizen zur Ausbildung zu Gakin dem Dunkelbinder ins Slaughtered Lamb.",al={"gnom hexenmeister sturmwind","khaz modan hexenmeister"}}},fx={["28eb4e6b"]={q="Was ist das Slaughtered Lamb?",a="Oberflächlich betrachtet ist das Slaughtered Lamb eine ruhige, heruntergekommene Taverne im Magierviertel von Sturmwind. Über der Erde wirkt sie fast vernachlässigt, mit einem leeren Schankraum, der nur von seinem Barkeeper Jarel Moor betreut wird. Unter ihren Dielen erstreckt sich jedoch ein weitläufiges Netzwerk aus unterirdischen Krypten und Katakomben. Diese dunklen Tiefen dienen als geheimes Sanktuarium für die praktizierenden Hexenmeister Sturmwinds und schützen ihre verbotenen Teufelsrituale und Beschwörungen vor den missbilligenden Blicken der Stadtwache und des Hauses der Adligen.",al={"was ist slaughtered lamb","slaughtered lamb taverne","the slaughtered lamb"}},f1944543={q="Was ist im Slaughtered Lamb geschehen?",a="Der geheime Keller der Taverne wurde fast enttarnt, als Lord Baurles K. Wischock die Hexenmeister entdeckte, die sich darunter verbargen. Er sorgte für Aufsehen im Haus der Adligen und setzte sich für eine vollständige Untersuchung ein, in der Hoffnung, den König dazu zu bewegen, die Einrichtung schließen zu lassen.",al={"slaughtered lamb geschichte","was geschah im slaughtered lamb","slaughtered lamb hintergrund"}},["531ea530"]={q="Wer betreibt das Slaughtered Lamb?",a="Der obere Schankraum wird von Jarel Moor geführt, einem Barkeeper, der neugierige Gäste leise davor warnt, sich von den dunklen Ecken fernzuhalten. Unter der Erde ist die schattige Enklave von geheimnisvollen Hexenmeister-Mentoren und Beschwörern bevölkert, darunter Gestalten wie Zardeth der Schwarzen Klaue. Sie unterweisen menschliche Lehrlinge sowie Gnom-Transferierte und halten sich bedeckt, damit Geschäfte und dunkle Zauberei ungestört fortgesetzt werden können.",al={"wer betreibt slaughtered lamb","slaughtered lamb barkeeper","wer ist im slaughtered lamb"}},ecc63b24={q="Ist das Slaughtered Lamb gefährlich?",a="Die Hexenmeister, die sich hier verbergen, hüten ihre Geheimnisse eifersüchtig vor jedem, der droht, ihre unterirdischen Zirkel zu enthüllen.",al={"ist slaughtered lamb gefährlich","slaughtered lamb gefahr","ist es sicher im slaughtered lamb"}}},fp="16,244,15.486.0,15.511.1,49.240.0,54.287.0,47.236.1,32.209.0"}
P.entries["subzone:slithering-scar"] = {n="Die wuchernde Narbe",s="Die wuchernde Narbe ist ein weitläufiger Silithidenbau, der die südlichen Klippen des Un'Goro-Kraters dominiert. Als Heimat des aggressiven Gorishischwarms stellen ihre ausgegrabenen Tunnel und organischen Türme ein gefährliches insektoides Vordringen in das urzeitliche Becken dar.",h="Die wuchernde Narbe ist ein weitläufiger Silithidenbau, der die südlichen Klippen des Un'Goro-Kraters...",kw={"gelegemutter zavas","koloss","gorishi","bau","silithiden","die wuchernde narbe","ungoro"},ang={["class:Druid"]="Die aggressive Ausbreitung des Gorishibaus bedroht die empfindliche, ungezähmte Vitalität des Kraters und erfordert Wachsamkeit gegenüber dem unnatürlichen Befall."},sec={{t="Der Gorishibau",b="In die rote Erde und das Gestein des südlichen Un'Goro gegraben, bildet die wuchernde Narbe einen fremdartigen Eingriff in die üppige prähistorische Landschaft. Der Bau wird von den Gorishi-Silithiden kontrolliert, einer organisierten Insektoidenart, die die Klippen mit feuchten Höhlen und Eikammern durchlöchert hat. In diesen unterirdischen Bauen ziehen Arbeiter und Tunnler riesige Gelege von Eiern und Larven neben hoch aufragenden Wespenbruten auf. Noch beunruhigender ist, dass die Kolonie heranwachsende Silithidenkolosse heranzieht – monströse Giganten, die sich einen unangefochtenen Pfad durch das Ökosystem des Kraters bahnen sollen. Seltsame Kristallformationen, die im Bau eingebettet liegen, pulsieren in unnatürlicher Resonanz und dienen als Brennpunkte für den finsteren, koordinierten Willen der Kolonie."},{t="Eine fehlende Schutzwehr",b="Gelehrte und Forscher, die den Rand von Un'Goro durchqueren, bemerken oft eine beunruhigende Anomalie bezüglich des Standorts des Baus. Während uralte Kristallpylonen an den nördlichen, östlichen und westlichen Grenzen des Beckens Wache halten, besitzen die südlichen Ausläufer keine solche Säule. Genau in dieser ungeschützten Lücke haben sich die Gorishi aus den benachbarten Wüsten nach innen gegraben. Ob die Silithiden gezielt eine vergessene südliche Schutzwehr untergraben haben oder schlichtweg dort eindrangen, wo die ursprünglichen Schutzwehren des Kraters am schwächsten waren, bleibt für diejenigen, die ihre rasante Ausbreitung beobachten, ein beunruhigendes Rätsel."}},faq={{q="Was ist die wuchernde Narbe?",a="Es ist ein Silithidenbaukomplex, der in die südlichen Klippenwände des Un'Goro-Kraters gehauen wurde und vom Gorishischwarm bewohnt wird.",al={"was ist dieser ort","die wuchernde narbe übersicht","ungoro insektenbau"}},{q="Was tun die Silithiden hier?",a="Der Gorishischwarm gräbt riesige unterirdische Tunnel, hütet Brutkammern voller Larven und Eier und zieht gewaltige Silithidenkolosse heran, um die Vorherrschaft über den Krater zu erlangen.",al={"warum sind hier insekten","silithiden ziel ungoro","gorishi ziel"}},{q="Warum gibt es im Süden keinen Pylon wie in den anderen Regionen?",a="Während die nördlichen, östlichen und westlichen Ränder von Un'Goro durch uralte Kristallpylonen markiert sind, gibt es an der südlichen Klippe keinen. Die wuchernde Narbe entstand genau dort, wo diese schützende Grenze fehlt.",al={"fehlender südlicher pylon","warum kein südpylon","wo ist der südpylon"}},{q="Welche gefährlichen Kreaturen bewohnen den Bau?",a="Neben Legionen von Arbeitern, Schindern und Stechern wird die Narbe von sich entwickelnden Kolossen und berüchtigt wilden Brutmüttern wie Gelegemutter Zavas durchstreift.",al={"bau bosse","bemerkenswerte insekten","gelegemutter zavas"}}},fp="15,247,16.730.0,14.602.0,28.117.0,33.181.0,58.205.0,42.159.0"}
P.entries["subzone:sludge-fen"] = {n="Das Schlickermoor",s="Das Schlickermoor ist ein giftiges industrielles Ölfeld, das von der Venture Company im nordöstlichen Brachland betrieben wird. Einst ein unberührter, kristallblauer See, verwandelte sich das Feuchtgebiet in einen öligen Morast, nachdem die Goblins Bohrplattformen und Maschinerie errichteten. Der Betrieb wird von Supervisor Lugwizzle beaufsichtigt und zieht ständige Wirtschaftsspionage sowie Sabotage durch Rivalen in Ratschet an.",h="Das Schlickermoor ist ein giftiges industrielles Ölfeld, das von der Venture Company im nordöstlichen...",kw={"bohrinsel","schredder","das schlickermoor","sputtervalve","supervisor lugwizzle","brachland","venture company","wizzlecrank"},ang={["class:Druid"]="Das Schlickermoor steht als abscheuliches Zeugnis unnatürlicher Ausbeutung. Druiden der Horde reisen während der Prüfung des Seelöwen in seine öligen Tiefen, um den Halben Anhänger der Wasser-Beweglichkeit zu bergen.",["profession:Engineering"]="Die Venture Company betreibt hier hochentwickelte Schredder und Maschinen, was den Ort zu einem unwiderstehlichen Ziel für Baupläne, Spezialkomponenten und aus Ratschet organisierten Wirtschaftsspionage-Diebstahl macht."},sec={{t="Industrielle Verwüstung",b="Vor der Ankunft der Venture Company war das Schlickermoor ein unberührtes Becken aus kristallklarem Wasser, gespeist von natürlichen Quellen im kargen Brachland. Getrieben vom unnachgiebigen Streben nach Profit errichtete die Venture Company über dem Becken eine ausgedehnte Ölbohranlage, die das Feuchtgebiet in ein schlammiges Reservoir verwandelte, das von schwerem Industrieabfall bedeckt ist. Unter der Aufsicht von Supervisor Lugwizzle pumpen Goblinbohrer, Ingenieure und Vorarbeiter rund um die Uhr Rohöl, ungeachtet der Umweltzerstörung. Das Wasser ist mittlerweile dick von Abflüssen und giftigen Nebenprodukten, sodass das einheimische Wasserleben unter dem Schmierfilm erstickt."},{t="Unternehmensrivalität und Spionage",b="Die Maschinerie und die Schredder-Innovationen des Moors haben es zu einem Hauptziel für Industriediebstahl gemacht. Im nahegelegenen Ratschet stand der Ingenieur Stotterspritter von der Tinkers' Union unter starkem Druck, mit der modernen Holzfäller- und Ausgrabungstechnologie der Venture Company mitzuhalten. Anstatt eigene Entwürfe zu erfinden, entsandte Stotterspritter einen Agenten namens Wizzlecrank, um direkt aus dem Schlickermoor einen Schredder der Venture Company zu entwenden. Da Wizzlecrank die Maschine törichterweise kaperte, ohne sich den Zündschlüssel zu sichern, werden oft angeheuerte Söldner in den Morast gelockt, um Lugwizzle den Schlüssel abzunehmen und die gestohlene Kriegsmaschine durch ein Spießrutenlaufen wütender Arbeiter der Venture Company zu eskortieren."}},faq={{q="Wie sah das Schlickermoor aus, bevor die Venture Company eintraf?",a="Das Schlickermoor war ursprünglich ein Becken aus reinem, kristallblauem Wasser. Die Venture Company ruinierte die natürliche Oase, als sie eine Bohrinsel samt Raffineriebetrieb direkt darüber errichtete und das umliegende Feuchtgebiet in Rohöl und chemischem Abfall ertränkte.",al={"das schlickermoor vergangenheit","war das schlickermoor immer verschmutzt","das schlickermoor geschichte"}},{q="Wer leitet die Operation im Schlickermoor?",a="Das Ölfeld wird im Auftrag der Venture Company von Supervisor Lugwizzle geleitet. Er beaufsichtigt die Arbeitskräfte aus Vorarbeitern, Bohrern und Ingenieuren an der Seite von Untergebenen wie Overseer Glibby und Foreman Grills.",al={"das schlickermoor boss","wer leitet das schlickermoor","supervisor lugwizzle"}},{q="Warum steht mitten im Moor ein gekaperter Schredder?",a="Der Goblin Wizzlecrank wurde von Stotterspritter aus Ratschet geschickt, um die überlegene Schredder-Konstruktion der Venture Company zu stehlen. Er sprang jedoch ins Cockpit, ohne sich zuvor den Zündschlüssel zu beschaffen, was ihn umringt von feindseligen Arbeitern der Venture Company stranden ließ.",al={"wizzlecrank schredder","goblin im schredder schlickermoor","warum steckt schredder fest"}},{q="Warum tauchen Druiden in diese verschmutzten Gewässer?",a="Druiden der Horde, die die Prüfung des Seelöwen absolvieren, werden auf den Grund des verseuchten Tümpels geleitet, um den Halben Anhänger der Wasser-Beweglichkeit aus einer versunkenen Schließkassette zu bergen, was ihre Ausdauer gegen die üble Umgebung auf die Probe stellt.",al={"druidenquest schlickermoor","halber anhänger der wasser-beweglichkeit","prüfung der wassergestalt"}}},fx={["35534ec0"]={q="Was ist Das Schlickermoor?",a="Das Schlickermoor ist ein Ölbohrfeld, das von der Venture Company im nordöstlichen Brachland betrieben wird. Das Gelände, das von einer direkt aus dem Schlamm errichteten industriellen Bohrplattform dominiert wird, dient als Zentrum für die Ressourcengewinnung und das Testen von Maschinen und ist von giftigen Abwässern, mahlenden Schreddern und Firmenpersonal umgeben.",al={"was ist das schlickermoor","erzähl mir vom schlickermoor","übersicht über das schlickermoor"}},["537e9a89"]={q="Ist Das Schlickermoor gefährlich?",a="Ja. Die Venture Company beschäftigt aggressive Aufseher, Vorarbeiter und Ingenieure, die ihre Operationen aktiv mit Schreddern und schwerem Gerät bewachen und jeden Eindringling sofort angreifen. Zudem sind die Gewässer selbst von giftigen Industrieabfällen und unnatürlichen Schlammanomalien, die durch die Verschmutzung entstanden sind, durchsetzt.",al={"ist das schlickermoor gefährlich","gefahren im schlickermoor","bedrohungen im schlickermoor"}},["8087f29c"]={q="Warum heißt es Das Schlickermoor?",a="Der Ort erhielt seinen Namen aufgrund der schieren Menge an giftigen Abwässern und Industrieabfällen, die durch die Bohrarbeiten der Venture Company dort abgeladen wurden. Was einst ein unberührter natürlicher Tümpel war, wurde gründlich zu einem schmutzigen, ölverschmierten Sumpf aus schwarzem Schlamm verkommen gelassen.",al={"warum heißt es das schlickermoor","bedeutung des namens schlickermoor","wie bekam das schlickermoor seinen namen"}}},fp="10,379,22.621.0,31.676.1,60.247.0,37.207.0,65.258.0,46.226.0"}
P.entries["subzone:solliden-farmstead"] = {fx={cf3d4bd1={q="Was ist Sollidens Bauernhof?",a="Sollidens Bauernhof ist eine aktive Kürbisfarm im westlichen Tirisfal, versteckt direkt nördlich von Todesend. Bemerkenswerterweise ist dies einer der wenigen Orte im nördlichen Lordaeron, an denen es lebenden einheimischen Menschen gelungen ist, die Seuche des Untods völlig unversehrt zu überleben, indem sie sich unter dem Schatten des nahe gelegenen Scharlachroten Kreuzzugs hartnäckig an ihren Boden klammerten.",al={"was ist sollidens bauernhof","sollidens bauernhof","erzähl mir von sollidens bauernhof"}},["7c9ed8e2"]={q="Ist Sollidens Bauernhof gefährlich?",a="Ja, wenn Ihr Euch zu sehr nähert. Die überlebenden Bauern sind durch das Überleben inmitten von Schrecken zutiefst paranoid und aggressiv geworden. Anstatt Fremde willkommen zu heißen, greifen sie sowohl Horde- als auch Allianzreisende sofort an. Darüber hinaus liegt die Farm in unmittelbarer Nähe zu den Verteidigungsanlagen des Scharlachroten Kreuzzugs an einem nahe gelegenen Außenposten, was die Umgebung tückisch macht.",al={"ist sollidens bauernhof gefährlich","sind die bauern von solliden gefährlich","bedrohung durch sollidens bauernhof"}}}}
P.entries["subzone:sorrow-hill"] = {n="Trauerhügel",s="Trauerhügel ist ein weitläufiger Friedhof südlich von Andorhal in den Westlichen Pestländern. Einst die letzte Ruhestätte für einfaches Volk, Soldaten und Adlige gleichermaßen, wurde er durch nahegelegene Seuchenkessel in eine wuchernde Zuflucht rastloser Untoter verwandelt.",h="Trauerhügel ist ein weitläufiger Friedhof südlich von Andorhal in den Westlichen Pestländern.",kw={"friedhof andorhal","dargal","joseph redpath","skelettschinder","trauerhügel","uthers grabmal","westliche pestländer"},ang={["class:Paladin"]="Trauerhügel ist ein Ort tiefster Trauer und Verehrung für Paladine, die hierherkommen, um an Uthers Grabmal Tribut zu zollen, während sie die Untoten zurückdrängen, die den Boden um ihren Mentor entweihen.",["faction:Alliance"]="Direkt an der Straße vom Zugwindlager gelegen, stellt der Friedhof sowohl einen strategischen Kontrollpunkt in Richtung Andorhal als auch die geheiligte Ruhestätte der gefallenen Verteidiger Lordaerons dar."},sec={{t="Eine Bürde aus Gräbern",b="Vor dem Dritten Krieg diente Trauerhügel als wichtigste Begräbnisstätte für die Stadt Andorhal und die umliegenden Ortschaften. Als die Geißel die Seuche des Untods entfesselte, konnten die Totengräber mit den Verstorbenen nicht mehr Schritt halten. Gepflegte Grüfte wurden bald von flachen, notdürftig markierten Erdgruben umgeben. Schließlich gaben verängstigte Überlebende traditionelle Bestattungen gänzlich auf und griffen stattdessen dazu, die Leichen ihrer Liebsten auf einem Massenscheiterhaufen im Süden zu verbrennen, aus Furcht, sie könnten auferstehen. Bevor die Stadt vollends fiel, bestatteten die Reste der Bevölkerung Lord Uther der Lichtbringer auf der Anhöhe des Friedhofs, was dem Hügel seinen tragischen Namen verlieh."},{t="Die auferstandenen Toten",b="Die fauligen Seuchenkessel der Geißel in der gesamten Region haben Trauerhügel längst verderbt. Die beigesetzten Soldaten und Bürger wandern nun als Skelettschinder und gefräßige Ghule zwischen den nebelverhangenen Grabsteinen umher, während Skelettmagier und ein örtlicher Kommandant der Geißel in den südöstlichen Grüften hausen. Da der Friedhof direkt an der Straße zwischen dem Zugwindlager und Andorhal liegt, ordnen sowohl die Allianz als auch die Argentumdämmerung regelmäßig Patrouillen an, um die Reihen der Untoten hier auszudünnen und einen lebenswichtigen Stützpunkt in der Region zu sichern."}},faq={{q="Warum wurde dieser Friedhof Trauerhügel genannt?",a="Er erhielt diesen Namen während des Falls von Lordaeron, als die überlebende Bevölkerung von Andorhal katastrophale Verluste durch die Geißel erlitt. Ihr letzter gemeinsamer Akt vor der Flucht war es, ihren gefallenen Champion, Lord Uther der Lichtbringer, in einem prächtigen Grabmal auf der Hügelkuppe zur Ruhe zu betten.",al={"trauerhügel bedeutung name","warum heißt es trauerhügel"}},{q="Warum gibt es hier so viele flache Gräber?",a="Als die Seuche des Untods Andorhal heimsuchte, häuften sich die Todesfälle so schnell, dass den Bürgern keine Zeit blieb, ordentliche Gräber anzulegen. Sie hoben hastige, kaum gekennzeichnete Gruben aus, bis der Ansturm so überwältigend wurde, dass sie Begräbnisse zugunsten von Massenverbrennungen gänzlich aufgaben.",al={"flache gräber trauerhügel","warum gräber schlecht markiert"}},{q="Wer ist auf Trauerhügel begraben?",a="Neben Tausenden gefallenen Soldaten und Bürgern von Andorhal beherbergt der Friedhof das große Grabmal von Uther der Lichtbringer. Zudem befindet sich hier die Ruhestätte des Kanoniers Dargal sowie ein Denkmal zu Ehren von Joseph Redpath, dessen Leichnam vernichtet wurde.",al={"berühmte gräber trauerhügel","bekannte personen hier begraben"}},{q="Welche Bedrohung geht heute von Trauerhügel aus?",a="Verderbt durch die Seuchenkessel des Lichkönigs sind die Toten des Friedhofs als Skelettschinder, sabbernde Ghule und Skelettmagier auferstanden. Angeführt von einem Kommandanten der Geißel, der in der südöstlichen Gruft residiert, bedrohen diese Untoten den südlichen Zugang nach Andorhal.",al={"geißel bei trauerhügel","wer kontrolliert trauerhügel"}}},fp="11,257,18.667.0,20.521.0,41.275.0,42.265.0,29.248.0,40.260.0"}
P.entries["subzone:sorrowmurk"] = {n="Sorgendunkel",s="Das Sorgendunkel ist die tückische Sumpflandschaft, die direkt östlich des Tränenteichs in den Sümpfen des Elends liegt. Es wird seit Langem von patrouillierenden grünen Drachenwesen beherrscht, die den Zugang zum Versunkenen Tempel bewachen, und bleibt eine der gefährlichsten Regionen in den östlichen Marschlanden.",h="Das Sorgendunkel ist die tückische Sumpflandschaft, die direkt östlich des Tränenteichs in den Sümpfen des...",kw={"atal'hakkar","drachenbrut","grüner drachenschwarm","grüner drache","tränenteich","sorgendunkel","sümpfe des elends"},ang={["class:Druid"]="Die traurige Verderbnis, die die Wächter des Smaragdgrünen Traums in diesen Feuchtgebieten berührt, macht die grünen Drachenwesen hier zu einem tragischen Anblick für jeden Diener der Natur."},sec={{t="Ein gefährlicher Grenzbereich",b="Das Sorgendunkel erstreckt sich entlang des östlichen Randes des Tränenteichs und ist ein dichtes, trübes Moor, das an das Verbotene Meer grenzt. Seit Jahren wimmeln die Gewässer und verworrenen Äste vor grausamen grünen Drachenbruten und riesigen Drachen, Überreste des Geleges, das entsandt wurde, um über den versunkenen Tempel von Atal'Hakkar zu wachen. Ihre Anwesenheit sorgt dafür, dass nur erfahrene Reisende es wagen, durch seine durchnässten Weiten zu wandern."}},faq={{q="Wo befindet sich das Sorgendunkel?",a="Das Sorgendunkel liegt im östlichsten Teil der Sümpfe des Elends, direkt hinter dem Tränenteich und den versunkenen Ruinen des Tempels von Atal'Hakkar, und grenzt an die Küste.",al={"sorgendunkel standort","wo ist sorgendunkel","sorgendunkel karte"}},{q="Welche Kreaturen bewohnen das Sorgendunkel?",a="Die Region ist berüchtigt für grüne Drachenwesen, darunter aggressive Drachenbrut und große Drachen, die das Sumpfgebiet um die Gewässer des Tempels erbittert patrouillieren.",al={"sorgendunkel gegner","was lebt in sorgendunkel","sorgendunkel feinde"}},{q="Warum gibt es grüne Drachen im Sorgendunkel?",a="Der Grüne Drachenschwarm wurde von Ysera beauftragt, über den Tränenteich zu wachen und sicherzustellen, dass das Böse, das im Tempel von Atal'Hakkar versunken ist, eingedämmt bleibt.",al={"warum drachen hier","grüner drachenschwarm sümpfe des elends","tempeldrachen"}}},fp="10,272,17.411.0,32.173.0,38.151.0,46.159.0"}
P.entries["subzone:south-gate-outpost"] = {n="Südtoraußenposten",s="Der Südtoraußenposten ist ein befestigter Bergposten der Zwerge am Südtorpass zwischen Dun Morogh und Loch Modan. Seine Gebirgsjäger sichern die verschneite Südstraße und bewachen den stetigen Strom an Reisenden zwischen den eisigen Höhen von Eisenschmiede und dem gemäßigten Tal des Lochs.",h="Der Südtoraußenposten ist ein befestigter Bergposten der Zwerge am Südtorpass zwischen Dun Morogh und Loch...",kw={"dun morogh","zwerg","straße nach eisenschmiede","loch modan","gebirgsjäger","südtoraußenposten","südtorpass","thelsamar"},ang={["faction:Alliance"]="Der Außenposten dient als verlässlicher militärischer Schutzpunkt an einer der wichtigsten inneren Nachschublinien von Khaz Modan und hält die Verbindung zwischen der Hauptstadt und den östlichen Siedlungen offen.",["race:Dwarf"]="Für Zwerge, die das Coldridgetal und Dun Morogh zum ersten Mal verlassen, ist der Südtoraußenposten der letzte frostige Orientierungspunkt, bevor sie in die lebendigen, sonnenbeschienenen Lande von Loch Modan hinabsteigen."},sec={{t="Wächter der Südstraße",b="Auf halber Strecke durch den Gebirgseinschnitt des Südtorpasses gelegen, markiert der Südtoraußenposten die Grenze zwischen den verschneiten Hängen von Dun Morogh und dem grünen Becken von Loch Modan. Hier stationierte Gebirgsjäger aus Eisenschmiede haben die Aufgabe, die felsigen Serpentinen zu patrouillieren und gefährliche Wildtiere von der Hauptstraße fernzuhalten. Verglichen mit ihren bedrängten Verwandten oben am Nordtoraußenposten haben die hiesigen Verteidiger ihren Straßenabschnitt weitgehend gesichert, sodass Reisende, Pilger und Handelskarren auf dem Weg nach Thelsamar in relativer Sicherheit reisen können."}},faq={{q="Welchem Zweck dient der Südtoraußenposten?",a="Er dient als befestigter Grenzkontrollpunkt und Garnison entlang des Südtorpasses. Die hier stationierten Gebirgsjäger halten die verschneite Durchgangsstraße zwischen Dun Morogh und Loch Modan frei von Bergbestien und feindseligen Eindringlingen.",al={"warum steht der südtoraußenposten hier","zweck des südtoraußenpostens","was ist der südtoraußenposten"}},{q="Warum ist es hier so viel ruhiger als am Nordtoraußenposten?",a="Die Garnison am Südtoraußenposten hat die aggressive Tierwelt direkt an der Straße erfolgreich dezimiert. Der Nordtoraußenposten hingegen hat mit heftigeren Übergriffen und unwegsamerem Berggelände zu kämpfen, weshalb der südliche Pass vergleichsweise ruhig ist.",al={"unterschied zwischen nordtor und südtor","ist das südtor sicher","südtor vs nordtor"}},{q="Wohin führt die Straße durch den Südtoraußenposten?",a="Richtung Westen führt der Pass bergauf in das verschneite Hochland von Dun Morogh nach Eisenschmiede. In östlicher Richtung bergab gelangt Ihr direkt in das gemäßigte Tal von Loch Modan, wobei die Straße geradewegs zur Siedlung Thelsamar führt.",al={"wohin führt diese straße","ziel der südtorstraße","weg durch den südtorpass"}}},fx={["3c6e6693"]={q="Was ist der Südtoraußenposten?",a="Der Südtoraußenposten ist eine befestigte Zwergen-Bergstation, die am Südtorpass im östlichen Dun Morogh liegt. Er befindet sich direkt an dem verschneiten Hochpass, der Dun Morogh mit dem weiteren Tal verbindet, und empfängt Reisende und Kuriere, die nach Osten in Richtung Thelsamar unterwegs sind.",al={"was ist der südtoraußenposten","infos zum südtoraußenposten","außenposten am südtorpass"}},["790564b9"]={q="Wer lebt im Südtoraußenposten oder betreibt ihn?",a="Bergsteiger der Eisenschmiede bemannen diese entlegene Grenzstation. Sie halten Wache über Reisende, die den Pass durchqueren, verwalten Vorräte und koordinieren sich eng mit lokalen Patrouillen, um einen sicheren Transit durch die Gebirgskorridore zwischen Dun Morogh und Loch Modan zu gewährleisten.",al={"wer kontrolliert den südtoraußenposten","wer leitet den südtoraußenposten","wer lebt im südtoraußenposten"}},["94f233ba"]={q="Ist der Südtoraußenposten gefährlich?",a="Der Außenposten selbst ist recht sicher. Die stationierten Bergsteiger haben die meisten der eindringenden Gebirgstiere entlang des Passes fleißig beseitigt und diese Station vor den gewaltsamen Angriffen der Kreaturen und dem harten Druck bewahrt, denen der Nordtoraußenposten ausgesetzt ist.",al={"ist das südtor sicher","ist der südtoraußenposten gefährlich","gefahr südtoraußenposten"}},["09ad7c8c"]={q="Warum heißt er Südtoraußenposten?",a="Er hat seinen Namen vom Südtorpass, der südlichen Berglücke, die durch das Felsgestein zwischen Dun Morogh und Loch Modan geschlagen wurde, im Gegensatz zu dem nördlichen Übergang, der vom Nordtoraußenposten verteidigt wird.",al={"warum heißt er südtoraußenposten","ursprung des namens südtoraußenposten","warum südtor"}}},fp="18,291,29.544.0,42.228.0,57.255.0,52.251.0"}
P.entries["subzone:south-gate-pass"] = {n="Südtorpass",s="Der Südtorpass ist die wichtigste Bergdurchgangsstraße, die die verschneiten Höhen von Dun Morogh mit dem Talkessel von Loch Modan verbindet. Flankiert von Zwergentunneln und Wachposten dient er als direkteste Route zwischen Eisenschmiede und der Siedlung Thelsamar.",h="Der Südtorpass ist die wichtigste Bergdurchgangsstraße, die die verschneiten Höhen von Dun Morogh mit dem...",kw={"dun morogh","loch modan","gebirgsjäger","südtoraußenposten","südtorpass","thelsamar","tunnel"},ang={["faction:Alliance"]="Der Pass dient als lebenswichtige innere Verkehrsader, die Eisenschmiede mit den östlichen Gebieten der Allianz verbindet und von den Gebirgsjägern des Königs instand gehalten und gesichert wird.",["race:Dwarf"]="Für Zwerge, die Dun Morogh verlassen, ist der Südtorpass die Schwelle, an der die eisige Bergluft den offenen Tälern und Steinbrüchen von Loch Modan weicht."},sec={{t="Die Straße nach Osten",b="Geradewegs durch das Khaz Modan-Gebirge gehauen, verbindet der Südtorpass die hohen Berge von Dun Morogh mit dem hügeligen Tal von Loch Modan im Osten. Reisende, die die kalten Hänge hinter sich lassen, treten durch steinerne Torbögen in das wärmere Kernland der Zwerge ein. Da der Pfad direkt nach Thelsamar führt, herrscht hier ein stetiger Strom von Gebirgsjägern, Kurieren und frisch ausgebildeten Abenteurern, die aus der Hauptstadt aufbrechen."},{t="Eine bewachte Schwelle",b="Der Pass wird durch den Südtoraußenposten gegen wilde Bestien und herumstreifende Troggs befestigt, wo Zwergengebirgsjäger ständige Wache halten. Obwohl er im Allgemeinen sicherer ist als die ungezähmte Wildnis tiefer im Tal, wird Reisenden geraten, auf der Straße zu bleiben, da feindselige Wildtiere und umherziehende Bedrohungen häufig die Zugänge auskundschaften."}},faq={{q="Wohin führt der Südtorpass?",a="Wenn Ihr nach Westen durch die Tunnel geht, gelangt Ihr in das verschneite Hochland von Dun Morogh auf der Straße nach Eisenschmiede. Wenn Ihr nach Osten reist, führt der Weg hinab in das Becken von Loch Modan, direkt auf die Siedlung Thelsamar zu.",al={"wohin führt der südtorpass","südtorpass ziel","südtor straße"}},{q="Ist der Südtorpass sicher zu bereisen?",a="Die Straße selbst ist dank der am Südtoraußenposten stationierten Zwergenwachen relativ sicher, doch Bären, Spinnen und vordringende Troggs bewohnen die umliegenden Klippen und Hänge außerhalb der Tunnelöffnung.",al={"ist der südtorpass gefährlich","südtorpass bedrohungen"}},{q="Warum wird dieser Pass mehr genutzt als der Nordtorpass?",a="Der Südtorpass bietet die direkteste und bequemste Überlandverbindung zwischen Dun Morogh und Thelsamar, was ihn zur bevorzugten Route für den lokalen Handel, Versorgungskarawanen und Reisende macht, die ins zentrale Loch Modan unterwegs sind.",al={"südtor gegen nordtor","warum südtor nutzen"}}},fx={ae3b1570={q="Was ist der Südtorpass?",a="Der Südtorpass ist ein lebenswichtiger Gebirgspass, der sich durch das Felsgestein zwischen dem verschneiten Dun Morogh im Westen und den Tälern von Loch Modan im Osten schlängelt. Da er direkt in der Nähe der Stadt Thelsamar herauskommt, dient er als Hauptroute für Bergsteiger, Kuriere und Reisende, die zwischen der Heimat der Eisenschmiede und dem Loch unterwegs sind.",al={"infos zum südtorpass","was ist der südtorpass","hintergrundinformationen südtorpass"}},d7b0d8f2={q="Wer bewacht den Südtorpass?",a="Der Pass wird von den Bergsteigern der Eisenschmiede bewacht und instand gehalten, die im Südtoraußenposten stationiert sind. Diese Zwergenwachen halten Ausschau nach dem Verkehr, der durch die Tunnel fährt, und stellen sicher, dass die Handelsroute gegen die wilden Bestien und feindseligen Bedrohungen, die in den umliegenden Hügeln lauern, offen bleibt.",al={"wer kontrolliert den südtorpass","wachen am südtorpass","südtoraußenposten"}},["487bb631"]={q="Warum heißt er Südtorpass?",a="Der Pass erhielt seinen Namen aufgrund seiner Lage relativ zum Bergrücken, der Dun Morogh und Loch Modan trennt. Er bildet das südliche Tor durch die Bergkette, gespiegelt im Norden durch den Nordtorpass.",al={"bedeutung des namens südtorpass","warum südtorpass","warum südtor"}}},fp="15,259,13.416.0,19.325.0,32.214.0,34.211.0,48.220.0"}
P.entries["subzone:south-seas"] = {fx={["89d72661"]={q="Was ist in der Geschichte von Die südlichen Meere geschehen?",a="Vor zehntausend Jahren war ganz Azeroth ein einziger Kontinent, bevor die Große Teilung die Landmasse zerschlug. Als der Brunnen der Ewigkeit während des Krieges der Ahnen implodierte, strömte der Ozean herbei, um den Riss zu füllen, riss Kontinente auseinander und erschuf den Mahlstrom sowie die umliegenden Meere. Die Inseln, die über Die südlichen Meere verstreut sind, sind Überreste jener alten Welt.",al={"geschichte die südlichen meere","wie entstanden die südlichen meere","ursprung die südlichen meere"}},["68566e28"]={q="Ist das Reisen durch Die südlichen Meere gefährlich?",a="Diese Gewässer sind berüchtigt dafür, tückisch zu sein. Jenseits von unberechenbarem Wetter und gefährlichen Riffen wimmelt es in Die südlichen Meere von aggressiven Raubtieren, darunter riesige Tintenfische und monströse, fleischfressende Blutflügelfledermäuse, die auf tropischen Inseln nisten. Noch schlimmer ist, dass halsabschneiderische Piratenkartelle wie die Blutsegelbukaniere die Schifffahrtswege durchstreifen und Jagd auf Handelsschiffe und wagemutige Reisende machen.",al={"sind die südlichen meere gefährlich","gefahren in den südlichen meeren","bedrohungen in den südlichen meeren"}},["7fe84177"]={q="Warum nennt man sie Die südlichen Meere?",a="Die Region hat ihren Namen einfach von ihrer Geografie als südlicher Teil von Das große Meer, der die Gewässer südlich des zentralen Mahlstroms abdeckt und an die südlichen Küsten beider Hauptkontinente grenzt.",al={"warum der name die südlichen meere","wie erhielten die südlichen meere ihren namen"}}}}
P.entries["subzone:south-tide-s-run"] = {n="Südlicher Gezeitenstrom",s="Südlicher Gezeitenstrom ist die einsame südwestliche Küstenlinie von Silberwald, die sich entlang der kalten Gewässer des großen Meeres erstreckt. Diese feuchten Sandstrände und die Brandung flankieren das bewaldete Landesinnere und bilden das südliche Gegenstück zu Nördlicher Gezeitenstrom.",h="Südlicher Gezeitenstrom ist die einsame südwestliche Küstenlinie von Silberwald, die sich entlang der kalten...",kw={"großes meer","silberwald küste","silberwald","südlicher gezeitenstrom","south tides run"},ang={["race:Undead"]="Die wilde südwestliche Küste liegt weit vom Schutz des Grabmals entfernt, was sie zu einem einsamen Grenzland macht, das von den Verlassenen nur selten betreten wird."},sec={{t="Das Westufer",b="Südlicher Gezeitenstrom erstreckt sich entlang des südwestlichen Randes von Silberwald und bildet eine trostlose Grenze zwischen den Wäldern und dem großen Meer. Im Gegensatz zu den geschützten östlichen Straßen, die hinab zum Greymane-Wall führen, fängt dieses offene Ufer die volle Wucht der westlichen Gezeiten ab und dient als karge Küstenwildnis, die von den Siedlungen im Landesinneren weitgehend unberührt geblieben ist."}},faq={{q="Wo befindet sich Südlicher Gezeitenstrom?",a="Südlicher Gezeitenstrom erstreckt sich entlang der südwestlichen Küstenlinie von Silberwald und grenzt an die weiten Weiten des großen Meeres.",al={"wo ist south tides run","south tides run standort","south tide run karte"}},{q="Wie unterscheidet sich Südlicher Gezeitenstrom von Nördlicher Gezeitenstrom?",a="Beide sind lange Strandabschnitte, die Silberwalds westliche Küstenlinie bilden, doch Südlicher Gezeitenstrom umfasst den südlichen Teil der Küste, während sich Nördlicher Gezeitenstrom entlang des Nordwestens nahe der Grenze zu Tirisfal erstreckt.",al={"north tides run vs south tides run","unterschied zwischen den tide runs"}},{q="Gibt es Siedlungen entlang von Südlicher Gezeitenstrom?",a="Direkt am Strand gibt es keine größeren Städte oder Außenposten. Die meisten Aktivitäten der Verlassenen konzentrieren sich landeinwärts nahe den Hauptverkehrswegen, sodass der Küstenstreifen isoliert bleibt.",al={"städte in south tides run","wer lebt in south tides run"}}},fx={c53efa4c={q="Was ist der Südliche Gezeitenstrom?",a="Der Südliche Gezeitenstrom ist der südwestliche Küstenabschnitt des Silberwalds, der entlang der Gewässer des großen Meers verläuft. Zusammen mit dem Nördlichen Gezeitenstrom im Norden bildet er die westliche Küstenlinie der Region.",al={"was ist der südliche gezeitenstrom","infos zum südlichen gezeitenstrom","südlicher gezeitenstrom"}},d867ddea={q="Warum heißt er Südlicher Gezeitenstrom?",a="Er hat seinen Namen von seiner Lage entlang der Küste des Silberwalds und dient als südliches Gegenstück zum Nördlichen Gezeitenstrom am Rande des großen Meers.",al={"warum südlicher gezeitenstrom","bedeutung des namens südlicher gezeitenstrom","name südlicher gezeitenstrom"}}},fp="16,238,17.353.0,34.119.0,55.234.0,49.159.0"}
P.entries["subzone:southern-gold-road"] = {n="Südliche Goldstraße",s="Die Südliche Goldstraße ist die lebenswichtige Wüstendurchgangsstraße, die sich durch die südliche Hälfte des Brachlands zieht und die zentralen Ebenen mit dem großen Aufzug verbindet. Sie dient als unverzichtbare Ader für den regionalen Handel und führt Karawanen, Nachschub sowie Reisende zwischen fernen Winkeln Kalimdors entlang.",h="Die Südliche Goldstraße ist die lebenswichtige Wüstendurchgangsstraße, die sich durch die südliche Hälfte des...",kw={"brachland","karawanen","goldstraße","der große aufzug","südliche goldstraße","tausend nadeln"},ang={["faction:Horde"]="Die Straße dient als Rückgrat der Nachschublinien der Horde zwischen der zentralen Kreuzung des Brachlands und den südlichen Außenposten nahe Tausend Nadeln."},sec={{t="Schlagader des Südens",b="Die Südliche Goldstraße beginnt offiziell an der Steinbrücke, die die nördliche und südliche Hälfte des Brachlands teilt, und verläuft geradewegs nach Süden, bis sie auf den großen Aufzug trifft, der hinab nach Tausend Nadeln führt. Wie der nördliche Abschnitt, der schlicht Goldstraße genannt wird, verdankt diese staubige Hauptstraße ihren Namen dem endlosen Strom lukrativer Händlerkarawanen, die über ihre gesamte Länge ziehen. Trotz ständiger Überfälle einheimischer Stacheleberstämme und in der Savanne lauernder Raubtiere bleibt sie einer der am stärksten frequentierten Fernwege des Kontinents, auf dem Waren zwischen abgelegenen Außenposten und geschäftigen Häfen transportiert werden."},{t="Ein Kreuzungspunkt ferner Länder",b="Die Straße wird von weit mehr als nur dem lokalen Verkehr der Horde genutzt. Abenteurer und abgehärtete Händler, die von so weit her wie Gadgetzan in den südlichen Wüsten von Tanaris, Auberdine an den nebligen Ufern der Dunkelküste und den heiligen Hainen von Nachthafen in Mondlichtung anreisen oder dorthin aufbrechen, beschreiten diese sonnenverbrannte Weite. Für Reisende, die zu Fuß das Landesinnere von Kalimdor durchqueren, ist das Überleben des Weges entlang der Südlichen Goldstraße eine zermürbende Reifeprüfung."}},faq={{q="Wo beginnt und endet die Südliche Goldstraße?",a="Die Straße beginnt offiziell an der Brücke, die die nördliche und südliche Hälfte des Brachlands teilt, und führt südwärts, bis sie am großen Aufzug den Rand von Tausend Nadeln erreicht.",al={"pfad südliche goldstraße","route südliche goldstraße","wo liegt südliche goldstraße"}},{q="Warum wird sie Goldstraße genannt?",a="Die Durchgangsstraße ist nach den wertvollen Handelskarawanen benannt, die regelmäßig auf ihr reisen und kostbare Waren, Erz und Münzen durch das Herz von Kalimdor befördern.",al={"warum goldstraße genannt","ursprung name goldstraße","bedeutung goldstraße"}},{q="Was ist der Unterschied zwischen der Goldstraße und der Südlichen Goldstraße?",a="Die Trennlinie ist die Brücke, die den zentralen Einschnitt des Brachlands überquert. Nördlich dieses Punktes ist der Weg schlicht als Goldstraße bekannt, während der nach Süden zum großen Aufzug führende Abschnitt als Südliche Goldstraße bezeichnet wird.",al={"goldstraße vs südliche goldstraße","zwei goldstraßen"}},{q="Wer reist auf diesem Straßenabschnitt?",a="Neben lokalen Boten und Patrouillen der Horde nutzen Händler und Forscher die Route, um zwischen weit entfernten Gebieten zu reisen, und verbinden so Orte wie Gadgetzan im fernen Süden mit der Dunkelküste und Mondlichtung im hohen Norden.",al={"wer nutzt südliche goldstraße","karawanen südliche goldstraße"}}},fp="18,301,19.606.0,29.443.0,48.191.0,31.158.0,72.228.0,39.226.0"}
P.entries["subzone:southern-savage-coast"] = {n="Südliche ungezähmte Küste",s="Die Südliche ungezähmte Küste umfasst den langen Streifen aus Stränden und Gezeitengewässern, der das südwestliche Schlingendorntal säumt. Flankiert von den tückischen Tiefen der südlichen Meere, beheimaten diese Ufer umherstreifende Wildtiere, feindselige Naga und die allgegenwärtige Bedrohung durch Küstenräuber.",h="Die Südliche ungezähmte Küste umfasst den langen Streifen aus Stränden und Gezeitengewässern, der das...",kw={"beutebucht","janeirospitze","die ungezähmte küste","die südlichen meere","südliche ungezähmte küste","schlingendorntal","das finstere riff"},ang={["class:Hunter"]="Die weitläufigen Strände bieten ideales Jagdgebiet für amphibisches Wild, Küstenkatzen und Basilisken, mit freiem Sichtfeld, das dem klaustrophobischen Dickicht im Landesinneren weit vorzuziehen ist."},sec={{t="Eine tückische Küstenlinie",b="Entlang des westlichen Randes des südlichen Dschungels markiert die Südliche ungezähmte Küste den Übergang des Festlands in die warmen Strömungen der südlichen Meere. Getrennt von der nördlichen ungezähmten Küste durch die versunkenen Ruinen und Gefahren des finsteren Riffs, führt diese Küstenlinie an Buchten nahe der Arena der Gurubashi und dem Nek'maniquellbrunnen vorbei, bevor sie hinter Beutebucht und der Janeirospitze ausläuft. Während die Strände im Vergleich zum erdrückenden Dschungeldickicht offenes Gelände bieten, müssen Reisende sich gegen aggressive reptilienartige Raubtiere, jagende Naga in den Untiefen und vorbeiziehende Korsaren zur Wehr setzen, die den Strand nach leichter Beute absuchen."}},faq={{q="Wo beginnt und endet die Südliche ungezähmte Küste?",a="Sie umfasst die südwestliche Küstenlinie des Schlingendorntals, beginnt unterhalb des finsteren Riffs und erstreckt sich südwärts entlang der Küste an Beutebucht und der Janeirospitze vorbei, wo sie in die wilden Ufer übergeht.",al={"ort der südlichen ungezähmten küste","wo liegt die südliche ungezähmte küste","grenzen der ungezähmten küste"}},{q="Wie unterscheidet sie sich von der nördlichen ungezähmten Küste?",a="Die beiden Küstenabschnitte sind durch das finstere Riff getrennt. Die nördliche ungezähmte Küste erstreckt sich entlang der Gewässer des Großen Meeres im nördlichen Schlingendorntal, während die Südliche ungezähmte Küste am unteren Kap liegt und an die südlichen Meere grenzt.",al={"unterschied zwischen ungezähmter und südlicher küste","warum zwei ungezähmte küsten","grenze finsteres riff"}},{q="Welche Gefahren erwarten Reisende entlang des Strandes?",a="Die offenen Sandstrände sind dicht bevölkert von boshaften Basilisken, schnappenden Krokolisken, feindseligen Naga, die aus den Untiefen kriechen, sowie Patrouillen revierbezogener Piraten.",al={"ist die südliche ungezähmte küste gefährlich","mobs an der südlichen ungezähmten küste","gefahren entlang der küste"}},{q="Kontrolliert Beutebucht diese Küstenlinie?",a="Nein. Die Blackwater Raiders und das Steamwheedle-Kartell kontrollieren strikt nur den Hafen von Beutebucht und dessen unmittelbare Zugänge. Die wilden Strände im Norden und Süden bleiben gesetzloses, ungezähmtes Gebiet.",al={"gehört der strand zu beutebucht","kontrolle des steamwheedle-kartells über die küste","goblingebiet"}}},fp="21,281,23.616.0,51.203.0,51.226.0,50.167.0,38.205.0"}
P.entries["subzone:southfury-river"] = {n="Der Südstrom",s="Der Südstrom ist eine der markantesten Wasserstraßen im zentralen Kalimdor und bahnt sich von den Höhen des Hyjal aus einen reißenden und breiten Weg nach Süden. Er bildet die natürliche Grenze, die Azshara von Eschental sowie Durotar vom Brachland trennt, bevor er nahe Ratschet in das große Meer stürzt.",h="Der Südstrom ist eine der markantesten Wasserstraßen im zentralen Kalimdor und bahnt sich von den Höhen des...",kw={"eschental","azshara","brachland","durotar","hyjal","orgrimmar","ratschet","der südstrom"},ang={["faction:Horde"]="Der Südstrom fungiert als westliche Verteidigungslinie von Durotar und als natürliche Verbindungslinie zwischen der Hauptstadt und dem Herzen des Brachlands."},sec={{t="Eine wichtige natürliche Grenze",b="Seinen Ursprung hoch im Hyjal nehmend, stürzt der Südstrom über gewaltige Kaskaden hinab, bevor er durch das zentrale Kalimdor fließt. Seine tosenden Gewässer dienen als klare geografische Trennlinie, welche die heiligen Wälder von Eschental vom uralten Azshara scheidet und die trockenen Hügel von Durotar von der Savanne des Brachlands trennt. Nur wenige strategische Brücken wagen es, seine reißende Strömung zu überqueren – allen voran das schwere Bauwerk, das die hinteren Gates of Orgrimmar bewacht, sowie der Übergang, der Durotar mit dem Brachland verbindet. Schließlich mündet der Fluss nordöstlich des neutralen Hafens Ratschet über einen Wasserfall in das große Meer."},{t="Strategische Bedeutung",b="Für die Horde ist der Südstrom sowohl ein Schild als auch eine lebenswichtige natürliche Verkehrsader. Er schützt die westlichen Zugänge nach Durotar und Orgrimmar vor direkten Bodenangriffen und spendet zugleich frisches Bergwasser durch eine ansonsten sengende, sonnenverbrannte Landschaft. Direkt nördlich des westlichen Übergangs nach Orgrimmar liegt eine einzigartige geografische Wegkreuzung, an der vier bedeutende Gebiete aufeinandertreffen: Eschental, Azshara, Durotar und das Brachland. Die Kontrolle über diese aufgewühlte Wasserstraße sichert die Nachschublinien zwischen Orgrimmar und den umliegenden Siedlungen der Horde."}},faq={{q="Wo entspringt der Südstrom und wo endet er?",a="Der Südstrom entspringt in den alpinen Gefilden des Hyjal und stürzt über dramatische Wasserfälle ins Flachland hinab. Er fließt südwärts zwischen Eschental, Azshara, Durotar und dem Brachland hindurch, bevor er nordöstlich von Ratschet über einen Wasserfall in das große Meer mündet.",al={"quelle des südstroms","wohin fließt der südstrom","mündung des südstroms"}},{q="An welche Zonen grenzt der Fluss?",a="Der Fluss trennt Eschental von Azshara im Norden und das Brachland von Durotar im Süden. Bemerkenswerterweise gibt es einen Punkt nördlich der westlichen Brücke von Orgrimmar, an dem alle vier Gebiete an den Ufern des Flusses zusammentreffen.",al={"welche zonen liegen am südstrom","südstrom grenze"}},{q="Wo können Reisende den Südstrom überqueren?",a="Es gibt drei Hauptbrücken über den Südstrom: eine, die Azshara mit Eschental verbindet, eine, die zu den hinteren Gates of Orgrimmar führt, und eine bedeutende Brücke, die Durotar mit dem Brachland verbindet.",al={"südstrom brücken","wie man den südstrom überquert","brücken über den südstrom"}},{q="Warum ist der Fluss für Orgrimmar von Bedeutung?",a="Der Fluss bildet eine gewaltige natürliche Barriere, die die Westflanke von Orgrimmar und Durotar verteidigt. Zudem ist sein frisches Gebirgswasser eine unschätzbare Lebensader in einer ansonsten trockenen und kargen Region.",al={"südstrom orgrimmar","warum der südstrom für die horde wichtig ist"}}},fx={dbc3f3f2={q="Was ist Der Südstrom?",a="Der Südstrom ist das bekannteste Gewässer im zentralen Kalimdor. Er fließt von den Höhen des Hyjal nach Süden, und seine schnellen, breiten Wasser bilden natürliche Grenzen zwischen den Wäldern von Eschental und den Ruinen von Azshara, bevor er nach unten schneidet, um Durotar vom Brachland zu trennen. Er mündet schließlich durch einen kaskadierenden Wasserfall nordöstlich des Goblinhafens Ratschet in das große Meer.",al={"was ist der südstrom","übersicht zum südstrom","hintergrundinformationen südstrom"}},["4c95fcc0"]={q="Ist Der Südstrom gefährlich?",a="Der Fluss selbst ist ein reißender Strom mit gefährlichen, stürzenden Wasserfällen, wo er vom Hyjal herabfällt und ins Meer mündet. Jenseits der tückischen Strömung ist das Land auf beiden Seiten voller Konflikte und umherstreifender Bestien, was jede unbegleitete Überquerung weitaus riskanter macht, als sich an die befestigten Brücken zu halten.",al={"ist der südstrom gefährlich","bedrohungen am südstrom","gefahren am südstrom"}}},fp="15,301,22.606.0,20.552.0,45.251.0,34.213.0,46.196.0,40.208.0"}
P.entries["subzone:southmoon-ruins"] = {n="Südmondruinen",s="Die Südmondruinen sind uralte steinerne Überreste im Süden von Tanaris, direkt nördlich des Tals der Behüter. Das zerfallende Mauerwerk, das seit Langem von den brutalen Dunemaul-Ogern beansprucht wird, bewahrt Relikte der uralten Trollzivilisation, die einst die Wüste beherrschte, bevor der Sand sie verschlang.",h="Die Südmondruinen sind uralte steinerne Überreste im Süden von Tanaris, direkt nördlich des Tals der Behüter.",kw={"dunemaul","ruinen","southmoon","südmondruinen","tanaris","tal der behüter"},ang={["race:Dwarf"]="Zwergische Reisende, die das südliche Tanaris durchqueren, finden in Southmoon kaum mehr als verwittertes trollisches Mauerwerk und die Dunemaul-Oger, die darin lagern.",["race:Troll"]="Für die Dunkelspeere sind diese zerbrochenen Säulen ein ernüchternder Blick auf den verfallenen Glanz ihrer fernen Trollvettern, der unter der Wüstensonne ins Elend herabgesunken ist."},sec={{t="Steine im Treibsand",b="Aus den glühenden Weiten des südlichen Tanaris emporragend, stehen die Südmondruinen als verwittertes Zeugnis der alten Trollreiche da, die einst die südlichen Gefilde von Kalimdor beherrschten. Wie die nahe gelegenen Ruinen Eastmoon und Noonshade haben ihre Steinsäulen und Altäre Jahrtausenden von Wind und abrasivem Sand getrotzt. Die Stätte diente den Dunemaul-Ogern oft als verwahrlostes Lager; sie hegen kaum Ehrfurcht vor der Handwerkskunst der Vergangenheit und nutzen die uralten Bauwerke rein als Unterschlupf und Revier."},{t="Geheimnisse unter den Trümmern",b="Die architektonischen Überreste sind unverkennbar trollisch, doch ist nur wenig über das Volk überliefert, das die Steine von Southmoon aufrichtete, oder darüber, warum sie die Stätte verließen. Was immer sie zurückließen, liegt unter dem Flugsand begraben, und die Oger, die zwischen den Säulen hausen, scheren sich nicht darum."}},faq={{q="Wer erbaute ursprünglich die Südmondruinen?",a="Die Südmondruinen sind uralte Trollruinen – verwitterte Überreste der Trollzivilisation, die einst die südlichen Gebiete der heutigen Wüste von Tanaris beherrschte.",al={"wer baute southmoon","southmoon geschichte","sind das trollruinen"}},{q="Wer bewohnt die Ruinen derzeit?",a="Die Ruinen werden traditionell von den Dunemaul-Ogern bewohnt, die nach Tanaris wanderten, verschiedene verfallene uralte Außenposten als Lager beanspruchten und andere Aasfresser vertrieben.",al={"wer lebt hier","southmoon mobs","dunemaul bei southmoon"}},{q="Wo befinden sich die Südmondruinen?",a="Sie liegen in der südlichen Hälfte von Tanaris, nordwestlich des Tals der Behüter und südlich der zentralen Wüstenöde.",al={"southmoon standort","wo sind die southmoon-ruinen","wie man southmoon findet"}}},fp="15,295,28.499.0,26.276.0,41.160.0,33.195.0,38.130.0"}
P.entries["subzone:southpoint-tower"] = {n="Southpoint-Turm",s="Der Southpoint-Turm ist ein verfallener Spähturm von Lordaeron an der westlichen Grenze des Vorgebirges des Hügellands, der die Straße zum Silberwald überblickt. Einst ein Wachposten der Menschen, wird die zertrümmerte Struktur nun von Spähern der Verlassenen genutzt, die die Bewegungen der Allianz in der Region überwachen.",h="Der Southpoint-Turm ist ein verfallener Spähturm von Lordaeron an der westlichen Grenze des Vorgebirges des...",kw={"todespirscherin lesch","die felder von hillsbrad","vorgebirge des hügellands","spähturm","silberwald","southpoint-turm"},ang={["faction:Alliance"]="Der verfallene Turm beherbergt eine feindliche Spionin, die die Straße zum Silberwald beobachtet, was ihn zu einem natürlichen Ziel für Späher macht, die Hillsbrads menschliche Siedlungen beschützen.",["race:Undead"]="Der Turm bietet den Verlassenen einen unverzichtbaren Aufklärungsposten nahe der Grenze zum Silberwald, um menschliche Truppenbewegungen aus Hillsbrad heraus zu überwachen."},sec={{t="Ein verfallener Wächter",b="Direkt südlich der Hauptstraße gelegen, die den Silberwald und das Vorgebirge des Hügellands verbindet, wurde der Southpoint-Turm ursprünglich vom Königreich Lordaeron erbaut, um den Verkehr zwischen dem östlichen Ackerland und den westlichen Wäldern zu bewachen. Nach dem Dritten Krieg und der Zerstörung des Königreichs durch die Geißel verfiel das Mauerwerk. Heute steht er dachlos und zerbröckelnd da, ein isoliertes Relikt menschlicher Herrschaft in einem zersplitterten Gebiet."},{t="Ein wachsames Auge auf die Hügel",b="Trotz seines eingestürzten Zustands bleibt der Aussichtspunkt taktisch wertvoll. Die Verlassenen unterhalten hier einen Außenposten und stationieren Agenten wie Todespirscherin Lesch, um lokale Allianzpatrouillen, die nahegelegenen menschlichen Siedlungen der Felder von Hillsbrad und Reisende auf der Hauptstraße auszuspionieren. Aufgrund seiner einsamen Lage unmittelbar nahe feindlichem Gebiet wird der Turm häufig zum Schauplatz von Scharmützeln."}},faq={{q="Wo befindet sich der Southpoint-Turm?",a="Der Southpoint-Turm liegt am westlichen Rand des Vorgebirges des Hügellands, direkt südlich der Straße, die in den Silberwald führt, und knapp westlich der Felder von Hillsbrad.",al={"southpoint-turm standort","wo ist der southpoint-turm","southpoint-turm finden"}},{q="Wer kontrolliert den Southpoint-Turm derzeit?",a="Der Turm wird von den Verlassenen kontrolliert. Eine Agentin namens Todespirscherin Lesch ist in seinen verfallenen Mauern stationiert, um die Straße zu beobachten und nahegelegene Allianztruppen zu überwachen.",al={"wer ist beim southpoint-turm","wem gehört der southpoint-turm","southpoint-turm fraktion"}},{q="Warum liegt der Turm in Trümmern?",a="Der Turm wurde während des Falls von Lordaeron schwer beschädigt und aufgegeben, als die Geißel die Region verwüstete. Er wurde nie repariert, sodass nur noch zerbrochene Steinmauern übrig sind.",al={"warum ist der southpoint-turm zerstört","wer hat den southpoint-turm zerstört"}},{q="Warum greifen Allianzspieler diesen Außenposten an?",a="Der Posten beherbergt eine einzelne Späherin der Verlassenen, die menschliches Territorium beobachtet. Seine isolierte Lage nahe der Grenze macht ihn zu einem leichten und verlockenden Ziel für Reisende der Allianz, die zwischen Süderstade und den westlichen Straßen unterwegs sind.",al={"warum todespirscherin lesh töten","allianz greift southpoint-turm an"}}},fx={f07dd792={q="Wer lebt im Southpoint-Turm oder verwaltet ihn?",a="Der Turm ist keine dauerhafte Siedlung, beherbergt aber derzeit Todespirscherin Lesch, eine Agentin der Verlassenen. Sie versteckt sich im zertrümmerten Mauerwerk und nutzt die Höhe, um die Bewegungen der Allianz zwischen Süderstade und den westlichen Grenzen auszuspionieren.",al={"wer ist am southpoint-turm","bewohner des southpoint-turms","wer lebt im southpoint-turm"}},["0d7406b8"]={q="Ist der Southpoint-Turm gefährlich?",a="Er kann je nach Eurer Zugehörigkeit tückisch sein. Todespirscherin Lesch schlägt jeden Allianzreisenden nieder, der den Weg zum Silberwald nimmt, während Allianzspäher und Abenteurer häufig ihren isolierten Posten angreifen, um die Informationen der Verlassenen zu stören.",al={"ist der southpoint-turm gefährlich","wie gefährlich ist der southpoint-turm","gefahren am southpoint-turm"}},dd4aae73={q="Was ist der Southpoint-Turm?",a="Der Southpoint-Turm ist ein verfallender menschlicher Wachturm am westlichen Rand des Vorgebirges des Hügellands, der die Straße überblickt, die in den Silberwald führt. Einst eine stehende Befestigung für menschliche Verteidiger, liegt er heute weitgehend zerstört und ungeschützt da und dient als taktischer vorgeschobener Überwachungsposten.",al={"was ist der southpoint-turm","zweck des southpoint-turms","über den southpoint-turm"}}},fp="16,286,17.431.0,17.407.0,34.162.0,40.173.0,26.163.0,44.214.0"}
P.entries["subzone:southridge-beach"] = {n="Südklippenufer",s="Das Südklippenufer erstreckt sich entlang der südlichen Küsten der Bucht der Stürme im zentralen Azshara. Einst ein prachtvoller Bezirk der uralten Kaldorei-Stadt Eldarath, sind die zerbrochenen Ruinen heute von feindseligen Naga, Murlocs und riesigen Meeresriesen überlaufen.",h="Das Südklippenufer erstreckt sich entlang der südlichen Küsten der Bucht der Stürme im zentralen Azshara.",kw={"azshara","die bucht der stürme","eldarath","makrura","murloc","naga","meeresriese","südklippenufer"},ang={["race:NightElf"]="Die ruinierte Architektur am Südklippenufer dient als schmerzhafte Erinnerung an die Blütezeit und den tragischen Untergang der antiken Hochgeborenen-Zivilisation vor dem Großen Auseinanderbrechen."},sec={{t="Eine ertrunkene Küstenlinie",b="Das Südklippenufer bildet die südliche Grenze der stürmischen Bucht der Stürme. Vor Tausenden von Jahren war diese Küste Teil der großartigen Hochgeborenen-Stadt Eldarath, doch das Große Auseinanderbrechen spaltete das Land und riss den Großteil ihrer Paläste unter die Gezeiten. Heute säumen zerfallende Marmorsäulen und verwitterte Steinpavillons den Sand. Anstatt von Gelehrten und adligen Höflingen wird der Strand nun von aggressiven Naga der Spitelash, umherstreifenden Makrura, bösartigen Hydren und plündernden Murlocstämmen umkämpft. Sogar massive Meeresriesen wandern gelegentlich aus den Tiefen ans Ufer."}},faq={{q="Wo befindet sich das Südklippenufer?",a="Das Südklippenufer liegt im zentralen Azshara und säumt den südlichen Rand der Bucht der Stürme direkt unterhalb der Klippen des Festlands.",al={"lage südklippenufer","wo liegt südklippenufer","azshara südklippenufer"}},{q="Welche Ruinen sind entlang des Strandes verstreut?",a="Die Steinsäulen und Bögen entlang des Sandes sind die äußeren Überreste von Eldarath, einer einst großen Stadt der Hochgeborenen-Nachtelfen, die vor zehntausend Jahren während des Großen Auseinanderbrechens zerstört und überflutet wurde.",al={"ruinen südklippenufer","eldarath ruinen strand","was sind das für ruinen"}},{q="Welche Kreaturen leben am Südklippenufer?",a="Die Küstenlinie ist stark von Naga besetzt, neben primitiven Murlocs, gepanzerten Makrura, gefährlichen Hydren und gelegentlich umherstreifenden Meeresriesen.",al={"gegner am südklippenufer","feinde südklippenufer","was lebt hier"}},{q="Warum sind hier so viele Naga?",a="Die Naga sind aus den Tiefen des Ozeans hervorgebrochen, um die Ruinen ihrer ehemaligen Zivilisation in ganz Azshara zurückzuerobern, und haben eine feste militärische Präsenz entlang der Strände der Bucht der Stürme errichtet.",al={"warum naga am strand","naga südklippenufer","azshara naga"}}},fp="16,244,19.560.0,34.128.0,41.199.0,40.148.0,32.186.0"}
P.entries["subzone:southshore"] = {fx={f6e4321c={q="Was ist Süderstade?",a="Süderstade ist eine geschäftige Hafenstadt an der Südküste des Vorgebirges des Hügellands. Sie dient als eines der letzten verbliebenen Bollwerke der menschlichen Zivilisation und der Autorität der Allianz in Lordaeron, nachdem die Geißel die Hauptstadt zerstört hat. Obwohl sie von feindlichen Fraktionen umgeben ist, verfügt sie über einen funktionierenden Hafen, eine zivile Führung und eine standhafte Garnison.",al={"was ist süderstade","stadt süderstade","über süderstade"}},["856a6b32"]={q="Ist Süderstade gefährlich?",a="Für die Allianz bietet Süderstade einen gut bewachten Zufluchtsort, aber das Umland ist voller Gefahren. Scharmützel mit den Verlassenen aus Tarrens Mühle finden häufig im Vorgebirge statt, während Murlocs und Naga von der Küste den Hafen bedrohen. Außerdem lauern Schurken des Syndikats, Oger der Crushridge und verbliebene Untote direkt außerhalb der Stadtgrenzen.",al={"wie gefährlich ist süderstade","ist süderstade sicher","bedrohungen in süderstade"}}}}
P.entries["subzone:southshore-town-hall"] = {n="Rathaus von Süderstade",s="Das Rathaus von Süderstade dient als Verwaltungssitz der Südküste des Vorgebirges des Hügellands und ist eines der letzten funktionierenden Zentren der zivilen Autorität Lordaerons. Von hier aus koordiniert Magistrat Henry Maleb die örtliche Verteidigung und regiert die überlebende Bevölkerung der Stadt. Die Halle ist ein wichtiger Knotenpunkt für die Allianz, während sie darum kämpft, im von der Seuche heimgesuchten Norden Fuß zu fassen.",h="Das Rathaus von Süderstade dient als Verwaltungssitz der Südküste des Vorgebirges des Hügellands und ist...",kw={"henry maleb","hillsbrad","kundric zanden","lordaeron","magistrat","süderstade","rathaus"},ang={["faction:Alliance"]="Für Champions der Allianz, die im Norden eintreffen, ist das Rathaus von Süderstade der wichtigste bürgerliche Außenposten, der regionale Autorität und entscheidende Missionen gegen nahe Bedrohungen bietet.",["race:Human"]="Menschliche Reisende betrachten das Rathaus als ergreifende Erinnerung an Lordaerons verlorenen Ruhm, wo ein funktionierender Magistrat noch immer die Banner eines zerschlagenen Königreichs hochhält."},sec={{t="Eine Bastion ziviler Herrschaft",b="Während ein Großteil von Lordaeron unter der Verderbnis der Geißel und der Expansion der Verlassenen in Trümmern liegt, bewahrt das Rathaus von Süderstade den Anschein einer intakten menschlichen Regierung. Magistrat Henry Maleb leitet von seinem Büro hier aus die täglichen Amtsgeschäfte und arbeitet Seite an Seite mit Beamten wie Kundric Zanden, um Ressourcen zu sichern und die bürgerliche Ordnung aufrechtzuerhalten. In einer Region, die von aggressiven Untoten, Schurken des Syndikats und den erbitterten Grenzscharmützeln von Hillsbrad umgeben ist, fungiert das Rathaus als das Nervenzentrum, das das Überleben der Stadt gegen ständige Bedrohungen steuert."}},faq={{q="Wer leitet die Stadt vom Rathaus von Süderstade aus?",a="Magistrat Henry Maleb fungiert als wichtigster ziviler Anführer in Süderstade und führt die Amtsgeschäfte aus dem Rathaus heraus, wobei er die Verteidigung und Verwaltung der überlebenden Menschensiedlung leitet.",al={"wer hat hier das sagen","bürgermeister von süderstade","wer leitet süderstade"}},{q="Welche strategische Bedeutung hat das Rathaus von Süderstade?",a="Sie stellt einen der letzten Sitze der rechtmäßigen zivilen Führung Lordaerons im Norden dar. Mitglieder der Allianz wenden sich an das Rathaus, um Weisungen, Kopfgelder und Koordination gegen die vordringenden Verlassenen und Syndikatsbanditen zu erhalten.",al={"warum ist das rathaus wichtig","bedeutung von süderstade"}},{q="Wer arbeitet sonst noch im Rathaus?",a="Neben Magistrat Henry Maleb sind Beamte wie Kundric Zanden im Rathaus stationiert, um bei der Verwaltung der örtlichen Angelegenheiten zu helfen und den Betrieb der Stadt zu unterstützen.",al={"wer ist im rathaus von süderstade","kundric zanden","rathaus npcs"}},{q="Wie hält das Rathaus die Verbindung zur übrigen Allianz aufrecht?",a="Obwohl Süderstade historisch Teil des Königreichs Lordaeron ist, verlassen sich die Stadt und ihre Führung nun stark auf die Allianz und erhalten Verstärkung sowie Nachschub, um diese isolierte Küstenbastion gegen die umliegenden feindlichen Streitkräfte zu verteidigen.",al={"gehört süderstade zur allianz","verbindungen zu sturmwind"}}},fx={ccaa2d22={q="Was ist das Rathaus von Süderstade?",a="Dieses solide Steingebäude bildet das administrative Herz von Süderstade und ist ein wichtiges Zentrum der Regierung für die überlebenden Reste von Lordaeron. Innerhalb seiner Mauern koordinieren lokale zivile Führungspersönlichkeiten die Verteidigung der Siedlung, wahren die zivile Ordnung und verwalten die täglichen Bedürfnisse eines Zufluchtsortes, der von feindlichen Kräften umgeben ist.",al={"rathaus von süderstade","was ist das rathaus von süderstade","welches gebäude ist das in süderstade"}},eda35516={q="Was geschah im Rathaus von Süderstade?",a="Nach dem Fall von Lordaeron an die Geißel während des Dritten Krieges wurde Süderstade zu einem der letzten großen Zufluchtsorte für die Überlebenden des Königreichs. Das Rathaus wurde als Hauptsitz der zivilen Autorität etabliert, wo Magistrat Henry Maleb und seine Ratsmitglieder die monumentale Aufgabe übernahmen, die rechtmäßige menschliche Gesellschaft an der Südküste zu bewahren.",al={"geschichte des rathauses von süderstade","was passierte hier im rathaus"}},["49b6de22"]={q="Ist das Rathaus von Süderstade gefährlich?",a="Für Champions der Allianz ist das Rathaus ein sicherer und befestigter Zufluchtsort, der von wachsamen Stadtwachen bewacht wird. Für Mitglieder der Horde ist das Betreten des Gebäudes jedoch gefährlich; die Stadtbeamten und die nahegelegenen Wachposten greifen sofort jeden Eindringling an, der die Grenzen der Stadt verletzt.",al={"ist das rathaus von süderstade sicher","ist es gefährlich im rathaus von süderstade"}}},fp="20,389,23.520.0,49.201.0,57.228.0,36.174.0,61.231.0"}
P.entries["subzone:southwind-village"] = {n="Südwindposten",s="Der Südwindposten ist die von Geistern heimgesuchte Ruine eines Nachtelfen-Außenpostens im Sand von Silithus. Während des Krieges der Sandstürme von den Qiraji ausgelöscht, sind seine Straßen nun von den ruhelosen Geistern gefallener Verteidiger und umherstreifenden Silithiden gebunden.",h="Der Südwindposten ist die von Geistern heimgesuchte Ruine eines Nachtelfen-Außenpostens im Sand von Silithus.",kw={"fandral hirschhaupt","qiraji","rajaxx","shade of ambermoon","silithus","südwindposten","valstann staghelm","krieg der sandstürme"},ang={["class:Druid"]="Die verfallenen hainartigen Bauten und die gequälten Geister uralter Druiden, die im Südwindposten verweilen, dienen als düstere Mahnung an den Verlust der Natur gegen die insektoiden Horden.",["race:NightElf"]="Für Nachtelfen stellt der Südwindposten eine der schmerzhaftesten Niederlagen ihrer Geschichte dar, und die gepeinigten Gespenster, die durch das zerbrochene Mauerwerk wandeln, sind andere Kaldorei, die auf Frieden warten."},sec={{t="Eine Tragödie im Sand",b="Der Südwindposten diente vor tausend Jahren während des uralten Krieges der Sandstürme einst als wichtige Nachtelfenfeste. Als die Legionen der Qiraji den Verteidigungsring durchbrachen, führte Valstann Staghelm – Sohn von Erzdruide Fandral Hirschhaupt – ein Kontingent an, um das Dorf zu halten. Die Verteidigung endete in einer völligen Katastrophe: Die Nachtelfen-Verteidiger wurden überwältigt und niedergemetzelt, und Valstann selbst wurde von General Rajaxx in die Gefangenschaft verschleppt. Das Dorf wurde völlig zerstört, und seine einstigen Gebäude blieben zerborsten unter der Sonne zurück."},{t="Die gequälten Toten",b="Ein Jahrtausend nach seinem Fall bleibt der Südwindposten eine offene Wunde in der Wüste. Das Trauma des Angriffs war so überwältigend, dass die Geister der getöteten Nachtelfen-Schildwachen und -Druiden nicht weiterziehen konnten. Durch das Grauen ihrer letzten Momente in den Wahnsinn getrieben, streifen diese ruhelosen Phantome – angeführt von Shade of Ambermoon – endlos an den verfallenen Steinmauern umher und greifen jeden Eindringling an, während räuberische Silithiden die umliegenden Dünen umschwärmen."}},faq={{q="Was geschah mit dem Südwindposten?",a="Der Südwindposten wurde vor tausend Jahren während des Krieges der Sandstürme zerstört. Die unersättliche Qiraji-Armee überrannte die Nachtelfengarnison, schlachtete ihre Verteidiger gnadenlos ab und machte den Außenposten dem Erdboden gleich.",al={"warum ist südwindposten ruiniert","südwindposten lore","was zerstörte südwindposten"}},{q="Wer war Valstann Staghelm?",a="Valstann Staghelm war der geliebte Sohn von Erzdruide Fandral Hirschhaupt. Er führte die verzweifelte Verteidigung des Südwindpostens gegen die einfallenden Insektoiden an, doch seine Truppen wurden dezimiert und er selbst wurde vom Qiraji-Kommandanten, General Rajaxx, gefangen genommen.",al={"valstann staghelm südwindposten","fandral hirschhaupt sohn","wer verteidigte südwindposten"}},{q="Warum gibt es hier Nachtelfengeister?",a="Das plötzliche und brutale Gemetzel an den Verteidigern bannte ihre Seelen in die Ruinen. Die Geister der getöteten Druiden und Schildwachen sind in einer ewigen Schleife ihres letzten, schrecklichen Kampfes gefangen, überwacht von der verweilenden Shade of Ambermoon.",al={"südwindposten geister","warum gibt es geister im südwindposten","shade of ambermoon"}},{q="Haben die Insekten etwas mit der Zerstörung des Dorfes zu tun?",a="Ja. Die Silithiden, die um die Ruinen schwärmen, sind Teil der größeren insektoiden Plage, die mit den Qiraji verbunden ist – genau jener Streitmacht, die vor Jahrhunderten in Silithus einfiel und den Außenposten zerstörte.",al={"silithiden südwindposten","haben insekten verbindung zu südwindposten"}}},fp="17,249,22.540.0,18.438.0,35.214.0,26.242.0,36.239.0,51.183.0"}
P.entries["subzone:spirit-rise"] = {n="Die Anhöhe der Geister",s="Die Anhöhe der Geister ist der nordwestliche Tafelberg von Donnerfels und dient als wichtigstes Heiligtum der Taurenhauptstadt für spirituelle und schamanische Studien. Sie wird von spirituellen Führern wie dem Skychaser-Stamm beaufsichtigt und beherbergt oben heilige Ausbildungshallen, während sie nach unten hin in die höhlenartigen Teiche der Visionen führt.",h="Die Anhöhe der Geister ist der nordwestliche Tafelberg von Donnerfels und dient als wichtigstes Heiligtum der...",kw={"halle der geister","mulgore","die teiche der visionen","schamane","skychaser","die anhöhe der geister","donnerfels"},ang={["class:Shaman"]="Für Schamanen der Horde dient Die Anhöhe der Geister als unverzichtbarer Versammlungsort, um Ausbilder zu konsultieren, elementare Riten durchzuführen und mit Ahnengeistern zu kommunizieren.",["race:Tauren"]="Die Anhöhe verkörpert die tiefen spirituellen Wurzeln Eures Volkes und bietet neben den mystischen Gewässern der Teiche der Visionen Trost abseits weltlicher Pflichten."},sec={{t="Ein Heiligtum der Geister",b="Hoch oben auf den Klippen gelegen, die die Ebenen von Mulgore überblicken, ist Die Anhöhe der Geister der Gemeinschaft mit den Elementen und den Ahnengeistern gewidmet. Sie ist durch Seilbrücken mit dem zentralen Tafelberg verbunden und beherbergt die Halle der Geister und den Pavillon der geistigen Heilung, wo sich junge und erfahrene Schamanen versammeln, um ihre Verbindung zu Erde, Luft, Feuer und Wasser zu vertiefen. Der Skychaser-Stamm ist auf der Anhöhe stark vertreten und führt Suchende durch alte Traditionen."},{t="Höhlen und Übergänge",b="Unter den luftigen Hütten und den Totemschreinen unter freiem Himmel befindet sich ein Eingang, der tief in den Tafelberg führt: die dampfenden Teiche der Visionen, eine heilige unterirdische Höhle, in der Seher in geisterberührte Gewässer blicken."}},faq={{q="Wofür ist Die Anhöhe der Geister bekannt?",a="Die Anhöhe der Geister ist das spirituelle Herz von Donnerfels und hauptsächlich der schamanischen Praxis, der Heilung und der Gemeinschaft mit Naturgeistern und Ahnen gewidmet. Sie dient außerdem als Eingang zu den Teichen der Visionen.",al={"was ist die anhöhe der geister","zweck der anhöhe der geister","warum die anhöhe der geister besuchen"}},{q="Welcher Taurenstamm leitet die Aktivitäten auf der Anhöhe der Geister?",a="Der Skychaser-Stamm übt hier großen Einfluss aus und fördert die spirituellen Traditionen, Wahrsagungsrituale und schamanischen Ausbildungen, die die Anhöhe prägen.",al={"wer leitet die anhöhe der geister","stamm auf der anhöhe der geister","skychaser-stamm"}},{q="Was kann man unter der Anhöhe der Geister finden?",a="Ein Abstieg durch die Anhöhe führt in die Teiche der Visionen, eine feuchte unterirdische Höhle voller dampfender Gewässer, in der Seher und spirituelle Praktizierende meditieren und nach Visionen suchen.",al={"höhle der anhöhe der geister","unter der anhöhe der geister","eingang zu den teichen der visionen"}}},fx={a67a2478={q="Was ist Die Anhöhe der Geister?",a="Die Anhöhe der Geister ist eine der erhöhten Mesas, aus denen Donnerfels besteht, gelegen nordwestlich der zentralen Anhöhe. Sie dient als spirituelles Herz der Stadt, das hauptsächlich schamanistischen Studien, der Geisterkommunion und der Führung durch die Ahnen gewidmet ist. Die Anhöhe ist durch Seilbrücken mit dem Rest der Stadt verbunden, beherbergt die Halle der Geister und liegt über der unterirdischen Kaverne, die als Die Teiche der Visionen bekannt ist.",al={"was ist die anhöhe der geister","infos über die anhöhe der geister","anhöhe der geister donnerfels"}},["6e710860"]={q="Ist Die Anhöhe der Geister gefährlich?",a="Überhaupt nicht. Die Anhöhe der Geister ist ein Zufluchtsort innerhalb der souveränen Hauptstadt der Tauren. Ihr werdet hier eher Schamanen, spirituelle Heiler und reisende Besucher finden als feindliche Bestien oder Invasoren. Die einzige wirkliche Gefahr ist der tiefe Fall von den Klippen, falls Ihr in der Nähe des Randes der Mesa oder ihrer Hängebrücken den Halt verlieren solltet.",al={"ist die anhöhe der geister sicher","gefahr anhöhe der geister","feinde auf der anhöhe der geister"}}},fp="11,286,26.464.0,19.201.0,30.207.0,51.151.0,39.181.0"}
P.entries["subzone:spirit-rock"] = {n="Geisterfelsen",s="Der Geisterfelsen ist eine heilige Klippe, die sich in den schroffen Felsen über dem Tal der Prüfungen in Durotar erhebt. Er ist über einen gewundenen Pfad namens Verborgener Pfad erreichbar und dient als abgelegene heilige Stätte, an der Initianden direkt mit den Elementarkräften des Landes kommunizieren.",h="Der Geisterfelsen ist eine heilige Klippe, die sich in den schroffen Felsen über dem Tal der Prüfungen in...",kw={"ruf der erde","durotar","erdgeister","verborgener pfad","sapta","schamane","geisterfelsen","das tal der prüfungen"},ang={["class:Shaman"]="Der Geisterfelsen ist ein wichtiger Übergangsritus für junge Schamanen der Orcs und Trolle, die den Verborgenen Pfad hinaufsteigen, um die Erdsapta zu trinken und ihr erstes Band mit den Geistern von Stein und Boden zu knüpfen."},sec={{t="Ein Refugium der Elemente",b="Mit Blick auf den roten Canyon, in dem junge Krieger und Späher der Horde ihre Ausbildung beginnen, steht der Geisterfelsen als Altar der Zwiesprache. Isoliert vom Lärm des Tals der Prüfungen nähert man sich ihm nur über den Verborgenen Pfad, der sich den felsigen Bergrücken hinaufwindet. Angehende Schamanen pilgern zu diesem einsamen Felsvorsprung, um die traditionelle Sapta zu trinken und den Schleier der physischen Welt zu durchdringen, um das Grollen und Flüstern der Erde selbst zu vernehmen."}},faq={{q="Wofür wird der Geisterfelsen genutzt?",a="Der Geisterfelsen ist eine heilige Stätte, die vor allem von Schamanenanwärtern der Horde genutzt wird. Durch den Verzehr eines speziellen Tranks, der als Erdsapta bekannt ist, erlangen die Novizen am Felsen die spirituelle Sicht, die erforderlich ist, um direkt mit den Geistern der Erde zu kommunizieren.",al={"zweck des geisterfelsens","was am geisterfelsen geschieht","nutzen des geisterfelsens"}},{q="Wie erreicht man den Geisterfelsen?",a="Der Geisterfelsen liegt hoch in den Klippen über dem Tal der Prüfungen im südwestlichen Durotar. Er ist über den Verborgenen Pfad zugänglich, einen schmalen, unmarkierten Pfad, der sich vom Talboden hinauf in die zerklüfteten Hügel schlängelt.",al={"weg zum geisterfelsen","pfad zum geisterfelsen","geisterfelsen ort"}},{q="Was ist eine Sapta?",a="Eine Sapta ist ein zeremonielles Elementargebräu, das von Schamanenausbildern zubereitet wird. Das Trinken verändert die Wahrnehmung des Suchenden und ermöglicht es ihm, elementare Manifestationen wahrzunehmen, die für gewöhnliche Sinne unsichtbar bleiben.",al={"erdsapta","was ist sapta","sapta getränk"}}},fx={["5b9df982"]={q="Was ist der Geisterfelsen?",a="Der Geisterfelsen ist ein abgelegener Zufluchtsort hoch oben in den felsigen Klippen mit Blick auf Das Tal der Prüfungen in Durotar. Man erreicht ihn über einen gewundenen, versteckten Pfad durch die Hügel und er dient als heiliger Versammlungsort, an dem aufstrebende Schamanen die Gemeinschaft mit den Geistern der Welt suchen.",al={"was ist der geisterfelsen","geisterfelsen durotar","über den geisterfelsen"}},["383a79b2"]={q="Ist der Geisterfelsen gefährlich?",a="Der Felsen selbst ist ein Ort feierlicher spiritueller Reflexion und keine Höhle für Monster. Der Pfad, der hinauf in die zerklüfteten Felsen führt, grenzt jedoch an die raue Wildnis von Durotar, und die direkte Kommunikation mit Elementargeistern birgt ihre eigenen Prüfungen für die Unvorbereiteten.",al={"geisterfelsen gefahr","ist der geisterfelsen sicher","feinde am geisterfelsen"}},["57276d06"]={q="Warum heißt es Geisterfelsen?",a="Er erhielt seinen Namen, weil er ein geweihter, natürlicher Brennpunkt ist, an dem der Schleier zwischen dem physischen Reich und den Elementargeistern dünn ist. Hier trinken Schamanen speziell zubereitete Saptas, um die Geister der Erde wahrzunehmen und mit ihnen zu sprechen.",al={"warum geisterfelsen","ursprung des namens geisterfelsen"}}},fp="11,255,27.445.0,29.236.0,29.217.0,16.204.0"}
P.entries["subzone:splintertree-post"] = {n="Splitterholzposten",s="Der Splitterholzposten ist die primäre Festung der Horde im östlichen Eschental, nordwestlich des Dämonenhügels gelegen. Gegründet von Grommash Hellscream und dem Kriegshymnenklan während des Dritten Krieges, dient er als schwer befestigtes Bollwerk gegen die Nachtelfen und als Aufmarschgebiet für die territoriale Expansion.",h="Der Splitterholzposten ist die primäre Festung der Horde im östlichen Eschental, nordwestlich des...",kw={"eschental","astranaar","dämonenhügel","grommash hellscream","splintertreeposten","vhulgra","warsong-clan"},ang={["faction:Horde"]="Der Splitterholzposten ist das unverzichtbare zentrale Basislager für Abenteurer, die durch Eschental ziehen, und bietet Reparaturen, Rast sowie entscheidende Flugrouten durch ganz Kalimdor.",["race:NightElf"]="Für die Nachtelfen ist diese Festung eine bittere Narbe auf Eschental, gegründet von jenem Kriegshäuptling, der Cenarius niederstreckte, und aufrechterhalten von Eindringlingen, die ihre uralten Bäume niedermetzeln."},sec={{t="Eine Grenzfestung",b="Direkt aus den uralten Wäldern geschlagen, dient der Splitterholzposten als wichtigster militärischer und logistischer Knotenpunkt der Horde im gesamten östlichen Eschental. Ursprünglich von Grommash Hellscream und dem Kriegshymnenklan gegründet, als die Orcs während des Dritten Krieges zum ersten Mal in den Wald vordrangen, bleibt er eine schwer bewaffnete Enklave, die hauptsächlich von Spähern und Kriegern der Orcs und Tauren verteidigt wird. Ausgestattet mit einem Flugmeister, einem Gasthaus und stetigen Nachschublinien nach Orgrimmar festigt er die umkämpfte Präsenz der Horde unter dem Blätterdach."},{t="Die ständige Gefahr der Vergeltung",b="Der Splitterholzposten befindet sich in ständiger Bereitschaft. Die Nachtelfen haben Grommashs Taten während des Krieges weder vergessen noch vergeben, noch dulden sie das anhaltende Holzfällen der Orcs und ihre Überfälle auf Astranaar. Infolgedessen sieht sich die Siedlung ständigen Vergeltungsschlägen und Guerillaangriffen der Schildwachen aus dem umliegenden Gehölz gegenüber, die die Wachen der Garnison zu jeder Stunde auf die Probe stellen."}},faq={{q="Wer gründete den Splitterholzposten?",a="Er wurde von Grommash Hellscream und dem Kriegshymnenklan gegründet, als die Orcs während des Dritten Krieges erstmals nach Eschental vorstießen, um Holz zu sammeln und einen Stützpunkt zu errichten.",al={"wer baute splintertree","splintertree gründer","grom splintertree"}},{q="Warum greifen die Nachtelfen diesen Stützpunkt häufig an?",a="Die Nachtelfen betrachten den Splintertreeposten als unrechtmäßigen, entweihenden Eingriff in das Land ihrer Ahnen. Die Feindseligkeit aus Grommashs brutalen Feldzügen im Dritten Krieg besteht fort, weiter angefacht durch die anhaltenden Holzfällarbeiten der Horde und Scharmützel gegen die nahe gelegene Nachtelfenfeste Astranaar.",al={"warum greifen elfen an","splintertree schildwachen angriffe","nachtelfen überfälle splintertree"}},{q="Welche Annehmlichkeiten und Reisemöglichkeiten gibt es hier?",a="Der Splitterholzposten bietet ein Gasthaus, einen Stallmeister, einen Briefkasten, Rüstungsreparaturen und einen Windreiter-Flugmeister mit Flugrouten nach Orgrimmar, zum Wegekreuz und zu anderen Vorposten der Horde in ganz Kalimdor.",al={"splintertree flugroute","splintertree dienste","splintertree gasthaus"}},{q="Wer bildet derzeit die Garnison am Splintertreeposten?",a="Die Siedlung wird hauptsächlich von Orcs und Tauren bewohnt, die als erfahrene Späher, Wachposten und Offiziere an vorderster Front damit beauftragt sind, das Grenzland zu halten.",al={"splintertree wachen","wer lebt im splintertreeposten","splintertree völker"}}},fx={["1c750cca"]={q="Was ist der Splitterholzposten?",a="Der Splitterholzposten ist eine befestigte Festung der Horde im östlichen Eschental, nur nordwestlich vom Dämonenhügel. Er wurde hauptsächlich als Militärbasis und Bereitstellungsraum gegründet und verankert die Präsenz der Horde entlang der Waldstraße. Innerhalb seiner Palisaden aus Holz versammeln sich Späher, Krieger und Nachschubverwalter, um den territorialen Stützpunkt der Horde zu verstärken, und bieten müden Reisenden einen lebenswichtigen Zufluchtsort für Wärme, Reparaturen und Wind-Rider-Transport inmitten eines feindlichen und umkämpften Waldgebiets.",al={"was ist der splitterholzposten","zweck des splitterholzpostens","lager splitterholzposten"}},["1352f983"]={q="Was ist die Geschichte des Splitterholzpostens?",a="Der Splitterholzposten wurde ursprünglich während des Dritten Krieges von Grommash Hellscream und dem Kriegshymnenklan aus der Wildnis geschlagen, als die Orcs zum ersten Mal in das Eschental vordrangen, um das massive Holz zu ernten. In den Jahren nach dem Konflikt entwickelte sich das Lager von einem rauen Kriegslager zu einem permanenten Außenposten der Horde, der ständig in erbitterte Scharmützel gegen Nachtelfen-Verteidiger verwickelt war, die über die orkischen Einfälle in ihre heiligen Wälder wütend waren.",al={"geschichte des splitterholzpostens","vergangenheit des splitterholzpostens","was geschah am splitterholzposten"}},e71555e8={q="Ist der Splitterholzposten gefährlich?",a="Für Champions der Horde bietet der Posten einen sicheren Zufluchtsort hinter stabilen hölzernen Barrikaden. Der umliegende Wald ist jedoch tückisch. Nachtelfen-Wächter starten als Reaktion auf nahegelegene Scharmützel häufig tödliche Vergeltungsangriffe auf den Außenposten, während korrumpierte wilde Bestien und dämonische Überreste, die in der Nähe des Dämonenhügels lauern, eine allgegenwärtige Gefahr direkt hinter den Mauern des Postens darstellen.",al={"ist der splitterholzposten sicher","gefahr splitterholzposten","bedrohungen für den splitterholzposten"}}},fp="17,296,21.505.0,34.402.0,30.168.0,51.264.0,53.198.0,52.156.0"}
P.entries["subzone:splithoof-crag"] = {fx={fc440e32={q="Was ist die Spalthufklippe?",a="Die Spalthufklippe ist eine befestigte Siedlung, die in die nördlichen Felswände der Tausend Nadeln gehauen wurde, östlich des Düsterwolkengipfels gelegen. Sie dient als wichtiger Stützpunkt für die lokalen Zentauren des Galak-Klans und umfasst gruppierte Lager entlang des Canyonbodens und eine innere Kaverne, die als Spalthufhöhle bekannt ist.",al={"was ist das für ein ort","infos zur spalthufklippe","über die spalthufklippe"}},["76cca678"]={q="Ist die Spalthufklippe gefährlich?",a="Sie ist für Außenstehende extrem gefährlich. Die Galak-Zentauren sind äußerst aggressiv, territorial und greifen Eindringlinge sofort an. Außerdem ist das innere Heiligtum der Siedlung, die Spalthufhöhle, stark verteidigt, um ihre heiligen Relikte zu schützen.",al={"ist es hier sicher","gefahr spalthufklippe","bedrohungen spalthufklippe"}}}}
P.entries["subzone:splithoof-hold"] = {n="Spalthufhöhle",s="Die Spalthufhöhle ist eine tiefe Höhlenfestung, die in das Gestein der Spalthufklippe in Tausend Nadeln gehauen wurde. Gehalten vom Zentaurenstamm der Galak, dient die Höhle als befestigter Bau und beherbergt den Ancient Brazier, eine Stätte mit einer ewig brennenden heiligen Flamme.",h="Die Spalthufhöhle ist eine tiefe Höhlenfestung, die in das Gestein der Spalthufklippe in Tausend Nadeln...",kw={"ancient brazier","galak-zentauren","die heilige flamme","spalthufklippe","spalthufhöhle","tausend nadeln"},ang={["class:Shaman"]="Die Existenz einer ewigen Flamme, die tief in einer dunklen Steinhöhle brennt, zieht die Aufmerksamkeit jedes Spiritualisten auf sich, der mit den ursprünglichen Mysterien des Elementarfeuers im Einklang steht.",["race:Tauren"]="Die Zentauren der Galak bleiben geschworene Blutsfeinde der Tauren, weshalb jede Festung, die sie in Tausend Nadeln unterhalten, eine unmittelbare Bedrohung für den Frieden am Freiwindposten darstellt."},sec={{t="Eine Zentaurenbastion",b="Verborgen im Inneren der Spalthufklippe dient die Spalthufhöhle als befestigte Redoute für die Zentauren der Galak. Anders als der windgepeitschte Talboden bietet diese geschlossene Höhle ihnen Schutz, gut verteidigbare Engpässe und einen sicheren Zufluchtsort vor rivalisierenden Stämmen und Reisenden, die die Nadeln durchqueren."},{t="Die heilige Flamme",b="Tief in den schattigen Nischen der Feste liegt ein uraltes Kohlenbecken, das die heilige Flamme hütet. Dieses mystische Feuer brennt unaufhörlich und dient den Zentauren als Mittelpunkt von Macht und ritueller Verehrung sowie spirituellen Wanderern in der Schlucht als Gegenstand tiefer Neugier."}},faq={{q="Wo befindet sich die Spalthufhöhle?",a="Die Spalthufhöhle befindet sich in den Klippen und Wällen der Spalthufklippe entlang der nördlichen Steilhänge von Tausend Nadeln. Man betritt sie durch eine Höhlenöffnung, die inmitten der Hauptsiedlung der Zentauren liegt.",al={"spalthufhöhle standort","wo ist die spalthufhöhle","spalthufhöhle finden"}},{q="Wer kontrolliert die Spalthufhöhle?",a="Die Höhle wird vom Zentaurenstamm der Galak gehalten, der sie aggressiv gegen Eindringlinge, Übergriffe von Bestien und die nahegelegenen Tauren vom Freiwindposten verteidigt.",al={"wer lebt in der spalthufhöhle","spalthufhöhle mobs","wem gehört die spalthufhöhle"}},{q="Was befindet sich in der Feste?",a="Neben den feindseligen Zentaurenverteidigern der Galak beherbergt die Höhle den Ancient Brazier – ein Artefakt, das die heilige Flamme in den Tiefen des Felsens ewig brennen lässt.",al={"was ist in der spalthufhöhle","ancient brazier standort","die heilige flamme spalthuf"}}},fx={["9edfe937"]={q="Was ist die Spalthufhöhle?",a="Die Spalthufhöhle ist eine Kavernenfestung, die in den Fels der Spalthufklippe in den Tausend Nadeln gehauen wurde. Der wilde Zentaurenstamm der Galak nahm die natürliche Höhle in Besitz und baute sie zu einem befestigten Stützpunkt innerhalb des Canyons aus, in dem ihre heiligen Relikte und das Klanfeuer geschützt aufbewahrt werden.",al={"was ist die spalthufhöhle","wissen über die spalthufhöhle","über die spalthufhöhle"}},["8bfe11a3"]={q="Ist die Spalthufhöhle gefährlich?",a="Die Spalthufhöhle ist für Außenstehende extrem gefährlich. Sie dient als wichtige Zuflucht für die aggressiven Galak-Zentauren, die ihre Höhle, ihre Kriegertrupps und die ewige Heilige Flamme, die in ihren Tiefen aufbewahrt wird, erbittert vor allen Eindringlingen schützen.",al={"ist die spalthufhöhle gefährlich","gefahr spalthufhöhle","bedrohung spalthufhöhle"}}},fp="14,255,17.285.0,16.278.0,32.203.0,28.156.0,24.174.0"}
P.entries["subzone:stagalbog"] = {n="Stagalsumpf",s="Der Stagalsumpf ist ein dichter, wasserreicher Marschstrich, der sich über die südlichen Ausläufer der Sümpfe des Elends erstreckt. Er grenzt an das südliche Gebirge direkt unterhalb des Tränenteichs und bleibt eine ungezähmte Wildnis.",h="Der Stagalsumpf ist ein dichter, wasserreicher Marschstrich, der sich über die südlichen Ausläufer der Sümpfe...",kw={"sumpf","tränenteich","stagalsumpf","stagalboghöhle","sümpfe des elends"},ang={["class:Hunter"]="Die ruhigen Streifen zwischen dem Sumpfwasser und den Felsklippen machen den Stagalsumpf zu einem erstklassigen Jagdrevier für einheimische Sumpfbestien.",["profession:Herbalism"]="Die feuchten, sonnenarmen Wurzeln des Stagalsumpf bieten erstklassige Wachstumsbedingungen für Sumpfflora, die abseits ausgetretener Pfade gedeiht."},sec={{t="Das südliche Sumpfgebiet",b="Unter dem Schatten der südlichen Felsen erstreckt sich der Stagalsumpf, typisch für die Sümpfe des Elends: stehendes Gewässer, herabhängendes Schilf und verworrene Vegetation. Er liegt unmittelbar südlich der versunkenen Ruinen vom Tempel von Atal'Hakkar, gefangen zwischen dem verseuchten See und der felsigen Grenze der Region. Abgesehen von wilden Tieren hat die Zivilisation hier keinen Fuß gefasst."},{t="Schatten des Tempels",b="Da er an den Tränenteich grenzt, fängt der Stagalsumpf häufig die Schatten oder Verderbnisse ein, die aus dem Versunkener Tempel sickern."}},faq={{q="Wo befindet sich der Stagalsumpf?",a="Der Stagalsumpf liegt im südlichen Teil der Sümpfe des Elends, direkt südlich des Tränenteichs und entlang der Basis des südlichen Gebirges.",al={"standort stagalsumpf","wo ist stagalsumpf","wie findet man stagalsumpf"}},{q="Welche Bedrohungen kann man im Sumpf antreffen?",a="Der Sumpf wird von einheimischen Sumpfbestien und räuberischen Kreaturen bewohnt.",al={"kreaturen im stagalsumpf","monster im stagalsumpf"}}},fp="9,206,17.378.0,20.131.0,31.174.0,44.72.0"}
P.entries["subzone:staghelm-point"] = {n="Staghelms Stätte",s="Staghelms Stätte ist ein uralter Wachturm der Nachtelfen, der auf einem zerklüfteten Gipfel im nordöstlichen Silithus thront. Mit Blick auf die vordringenden Dünen und die nahe gelegenen Kavernen des Schattenhammers steht der Turm als Mahnwache gegen die uralten Bedrohungen, die die Wüste heimsuchen.",h="Staghelms Stätte ist ein uralter Wachturm der Nachtelfen, der auf einem zerklüfteten Gipfel im nordöstlichen...",kw={"bronzedrache","fandral hirschhaupt","ralo'shan","silithus","staghelms stätte","kavernen des schattenhammers","wachturm"},ang={["class:Druid"]="Der Turm trägt den Namen Staghelm und bietet einen nachdenklichen Ausblick über die verderbte, aride Wildnis, die dem Gleichgewicht der Natur trotzt.",["race:NightElf"]="Staghelms Stätte beschwört die feierliche Geschichte des Krieges der Sandstürme herauf und steht als deutliche Mahnung an die schweren Opfer der Kaldorei, die Schrecken unter Silithus zurückzuhalten."},sec={{t="Eine stille Wacht über den Sanden",b="Hoch über den ariden Ebenen des nordöstlichen Silithus gelegen, wird Staghelms Stätte von einem einsamen Nachtelfenturm gekrönt. Der Außenposten dient als einsamer Wächter, der über das Ödland und die finsteren Kultisten wacht, die in nahe gelegenen Höhlen wie den Kavernen des Schattenhammers lauern. Bewacht von Ralo'shan the Eternal Watcher und begleitet von einem Bronzedrachen, der über ihm seine Kreise zieht, trägt der Turm den stolzen und tragischen Namen der Staghelm-Blutlinie – eine Erinnerung an die immensen Opfer, die die Kaldorei während des uralten Krieges der Sandstürme erbrachten."}},faq={{q="Wer lebt bei Staghelms Stätte?",a="Der einsame Turm wird von Ralo'shan the Eternal Watcher bewacht, während ein majestätischer Bronzedrache aus der Brut Nozdormus eine ständige Patrouille am Himmel darüber fliegt.",al={"wer ist bei staghelms stätte","staghelms stätte nscs","raloshan"}},{q="Welche Bedrohungen liegen in der Nähe?",a="Den sich vom Gipfel herabwindenden Pfad hinab liegen die Kavernen des Schattenhammers, eine Höhle und ein umliegendes Lager, in dem es von fanatischen Mitgliedern des Schattenhammer-Kults wimmelt.",al={"staghelms stätte gefahr","feinde in der nähe","kavernen des schattenhammers"}}},fp="14,257,30.531.0,28.165.0,24.154.0"}
P.entries["subzone:stagnant-oasis"] = {n="Die brackige Oase",s="Die brackige Oase ist eines der kostbaren Gewässer, das im trockenen Herzen des Brachlands eingebettet ist und zwischen der Goldstraße und der Händlerküste liegt. Umgeben von üppigen Palmen und umkämpft von Kolkar-Zentauren, bieten seine trüben Wasser und die umliegenden Ufer einzigartiger lokaler Tierwelt, einschließlich Schnappschildkröten und umherstreifender Kodos, Lebensraum.",h="Die brackige Oase ist eines der kostbaren Gewässer, das im trockenen Herzen des Brachlands eingebettet ist...",kw={"brachland","zentauren","deviatfisch","goldstraße","kodo","kolkar","schnappkiefer","die brackige oase"},ang={["faction:Horde"]="Für Kuriere und Späher der Horde, die das Gebiet zwischen dem Wegekreuz und Taurajo durchqueren, stellen die Zentaurenlager an der Oase eine ständige Bedrohung für den Versorgungsverkehr auf der Goldstraße dar.",["profession:Cooking"]="Die Gewässer von der brackigen Oase liefern seltenen Deviatfisch, die wesentliche Zutat für das Zubereiten von Schmackhaften Deviatfischen."},sec={{t="Ein trüber Zufluchtsort in der Dürre",b="Versteckt östlich der Goldstraße und landeinwärts von der Händlerküste bietet die brackige Oase einen lebenswichtigen Fleck Grün inmitten des staubigen Buschlands des Brachlands. Wie seine benachbarten Gewässer unterstützt der Tümpel dichtes Blattwerk und aggressive Schnappkieferschildkröten, während geschwächte Kodos des Brachlands oft von den riesigen Herden des Felds der Riesen hierher abirren. Reisende müssen jedoch vorsichtig sein: Kolkar-Zentauren unterhalten Lager entlang der Ufer und verteidigen erbittert die Wasserrechte gegen jeden, der in ihr Gebiet wandert."},{t="Seltsame Gewässer",b="Trotz seines stagnierenden Aussehens wimmelt der Tümpel von ungewöhnlichem aquatischem Leben, einschließlich seltsamer mutierter Varianten wie Deviatfisch. Gelehrte und Schamanen werfen ein wachsames Auge auf die Oasen des Brachlandes und untersuchen die eigentümlichen Kräfte, die sich auf die lokalen Quellen und die Tierwelt, die daraus trinkt, auswirken."}},faq={{q="Wo befindet sich die brackige Oase?",a="Die brackige Oase liegt im zentral-südlichen Abschnitt des Brachlands, östlich der Goldstraße und westlich der Klippen, die die Händlerküste säumen.",al={"standort von der brackigen oase","wo befindet sich die brackige oase","wie findet man die brackige oase"}},{q="Wer kontrolliert die brackige Oase?",a="Nomadische Kolkar-Zentauren haben Lager um den Rand des Tümpels errichtet. Neben den Zentauren durchstreifen gefährliche Bestien wie Oasenschnappkiefer und einsame, wandernde Kodos das umliegende Grün.",al={"wer lebt bei der brackigen oase","zentauren in der brackigen oase","feinde in der brackigen oase"}},{q="Warum sind die Kodos hier leichter zu jagen?",a="Im Gegensatz zu den riesigen, koordinierten Herden, die weiter südlich im Feld der Riesen anzutreffen sind, sind die Kodos in der Nähe von der brackigen Oase einzelgängerisch und oft geschwächt oder verirrt, was sie zu deutlich leichterer Beute für Jäger und Reisende macht.",al={"verirrte kodos im brachland","kodos in der brackigen oase","kodos im brachland jagen"}},{q="Welche Art von Fisch kann in dem Tümpel gefangen werden?",a="Angler können Deviatfisch aus dem trüben Tümpel ziehen, ein eigenartiger Fang, der zu kulinarischen Köstlichkeiten verarbeitet werden kann, die in ganz Kalimdor geschätzt werden.",al={"angeln in der brackigen oase","deviatfisch in der brackigen oase","fischen in der brackigen oase"}},{q="Hat Thrall diese Oase während des Langen Marsches besucht?",a="Keine Aufzeichnung besagt dies mit Sicherheit. Die brackige Oase könnte eines der drei Wasserlöcher gewesen sein, die Thrall und die neu angekommene Horde sicherten, während sie an der Seite von Cairne Bluthuf durch das Brachland marschierten.",al={"thrall und die brackige oase","oase langer marsch","oase in warcraft 3"}}},fx={["9f5a622c"]={q="Was ist Die brackige Oase?",a="Die brackige Oase ist eine der üppigen Wasserstellen, die das trockene Weideland von Brachland durchziehen, gelegen zwischen der Goldstraße und Die Händlerküste. Gefüllt mit Süßwasserbecken, hoch aufragenden Palmen und einheimischem Grün dient sie als wichtiger Zufluchtsort für die Tierwelt inmitten der umliegenden Savanne, auch wenn sie ihre eigenen lauernden Gefahren birgt.",al={"was ist die brackige oase","info die brackige oase","über die brackige oase"}},f4d964bf={q="Ist Die brackige Oase gefährlich?",a="Ja, Reisende müssen vorsichtig sein. Wilde Kolkar-Zentauren unterhalten Lager entlang ihres Umfangs und beanspruchen das wertvolle Wasser gewaltsam für sich. Neben den feindseligen Plünderern streifen aggressive Oasis-Schnappkiefer durch die schlammigen Ufer und stellen eine tödliche Gefahr für unachtsame Wanderer dar, die Erholung von der brennenden Sonne suchen.",al={"ist die brackige oase sicher","die brackige oase gefahr","bedrohungen die brackige oase"}}},fp="14,329,28.530.0,14.291.0,36.151.0,32.208.0,38.221.0,44.135.0,50.197.0"}
P.entries["subzone:starbreeze-village"] = {n="Sternenhauch",s="Sternenhauch ist eine verlassene Nachtelfensiedlung östlich von Dolanaar in Teldrassil. Einst ein beschauliches Waldweildorf, fiel es vor Kurzem an die dem Wahnsinn verfallenen Furbolgs des Gnarlpine-Stammes. Die zerstörte Siedlung steht nun als unübersehbares Mahnmal für die wachsende Verderbnis, die in die Wurzeln des Weltenbaums einsickert.",h="Sternenhauch ist eine verlassene Nachtelfensiedlung östlich von Dolanaar in Teldrassil.",kw={"dolanaar","ferocitas","furbolg","gnarlpine","starbreeze","teldrassil","uruson","dorf"},ang={["class:Druid"]="Der Wahnsinn, der die Gnarlpine-Furbolgs verzehrt, und die Schändung von Sternenhauch fordern die Pflicht des Zirkels des Cenarius heraus, das Gleichgewicht der Tierwelt Teldrassils wiederherzustellen.",["race:NightElf"]="Zu sehen, wie eine Elfensiedlung so nah an Dolanaar in Ruinen verfällt, ist eine schmerzhafte Erinnerung an Teldrassils prekären Zustand und die Verderbnis, die am Weltenbaum nagt."},sec={{t="Ein gefallener Weiler",b="Südöstlich von Laubschattental und nur ein Stück die Straße hinab von Dolanaar gelegen, beherbergte Sternenhauch einst friedliche Nachtelfenfamilien unter den Ästen von Teldrassil. Heute liegt das Dorf in Trümmern, seine hölzernen Bauten überrannt von aggressiven Gnarlpine-Furbolgs. Von einer finsteren Verderbnis, die die Äste des Weltenbaums heimsucht, in den Wahnsinn getrieben, vertrieben die Tiermenschen die elfischen Bewohner und verteidigen das ruinierte Land nun mit aller Härte."},{t="Die Bedrohung durch Ferocitas",b="Die Anwesenheit der Gnarlpine im Dorf ist nicht bloß ein gewöhnlicher Revierüberfall. Am Rande der Siedlung lauert Ferocitas der Traumfresser, eine rätselhafte, verdorbene Kreatur, deren Gegenwart darauf hindeutet, dass finstere, üble Magie die Furbolgs aktiv in den Wahnsinn treibt. Zusammen mit riesigen Bestien wie Uruson, die die Pfade durchstreifen, machen diese Eindringlinge Starbreeze zu einer akuten Gefahr für Reisende im Osten von Teldrassil."}},faq={{q="Warum ist Sternenhauch verlassen?",a="Das Dorf wurde überrannt, als die Gnarlpine-Furbolgs einer um sich greifenden Verderbnis in Teldrassil zum Opfer fielen. Von Wahnsinn und Gewalt getrieben, griffen die Furbolgs die Nachtelfenbewohner an und zwangen sie zur Flucht und zur Aufgabe ihrer Heime.",al={"was geschah mit starbreeze","warum ist starbreeze zerstört","starbreeze verlassen"}},{q="Wer lebt jetzt in Sternenhauch?",a="Feindselige Gnarlpine-Furbolgs besetzen nun das Dorf. Zu den herausragenden Gestalten unter ihnen zählen die umherstreifende Patrouille Uruson und die verdorbene Gestalt, die als Ferocitas der Traumfresser bekannt ist.",al={"wer ist in starbreeze","starbreeze mobs","wer hat starbreeze eingenommen"}},{q="Wo liegt Sternenhauch?",a="Sternenhauch liegt im Osten von Teldrassil, südöstlich von Laubschattental und östlich von Dolanaar.",al={"wo liegt starbreeze","starbreeze kartenposition","starbreeze finden"}},{q="Wer ist Ferocitas der Traumfresser?",a="Ferocitas ist eine gefährliche, verdorbene Kreatur am Rande von Sternenhauch, die mit den dunklen Mächten in Verbindung steht, welche den hiesigen Gnarlpine-Stamm in Rage versetzen.",al={"ferocitas lore","wer ist ferocitas","ferocitas starbreeze"}}},fx={["3682bebf"]={q="Was ist Sternenhauch?",a="Sternenhauch ist eine ehemalige Siedlung der Nachtelfen in den Zweigen von Teldrassil, östlich von Dolanaar und südöstlich von Laubschattental gelegen. Einst eine friedliche Enklave, bestehend aus kleinen elfischen Wohnstätten, liegt sie heute in Ruinen und mahnt an die Verderbnis, die sich derzeit über den Weltenbaum ausbreitet.",al={"was ist sternenhauch","übersicht sternenhauch","sternenhauch geschichte"}},["71f9207c"]={q="Was ist mit Sternenhauch geschehen?",a="Vor nicht allzu langer Zeit war Sternenhauch eine ruhige Gemeinschaft der Nachtelfen. Doch eine schleichende Verderbnis ergriff den örtlichen Gnarlpine-Furbolgstamm und trieb sie in einen wilden, gewalttätigen Rausch. Überwältigt von dem plötzlichen Angriff wurden die Kaldorei-Bewohner vertrieben oder niedergemetzelt, und die Furbolgs übernahmen die vollständige Kontrolle über die Siedlung.",al={"historie von sternenhauch","was passierte in sternenhauch","wie fiel sternenhauch"}},["678e5f4f"]={q="Ist Sternenhauch gefährlich?",a="Ja, es ist sehr gefährlich, sie unvorbereitet zu betreten. Die Ruinen wimmeln von feindseligen, verdorbenen Gnarlpine-Furbolgs, die jeden Außenstehenden bei Sichtkontakt angreifen. Der wuchtige Furbolg Uruson patrouilliert die Wege des Dorfes, während der Gnarlpine-Anführer Ferocitas the Dream Eater an den Außenbezirken der Siedlung lauert.",al={"ist sternenhauch sicher","gefahr in sternenhauch","gefahren von sternenhauch"}}},fp="18,322,15.444.0,23.426.1,36.225.0,36.174.0,36.104.0,33.169.0"}
P.entries["subzone:starfall-village"] = {n="Starfall",s="Starfall ist ein friedlicher Zufluchtsort der Nachtelfen, eingebettet entlang der verschneiten Straße von Winterquell. Als einziger Außenposten der Allianz im gefrorenen Tal bietet er Reisenden, die der beißenden nördlichen Kälte trotzen, Schutz und Vorräte. Er wacht außerdem über den nahegelegenen Grabhöhleneingang.",h="Starfall ist ein friedlicher Zufluchtsort der Nachtelfen, eingebettet entlang der verschneiten Straße von...",kw={"allianz","nachtelf","starfall","winterquell"},ang={["faction:Alliance"]="Als einzige Allianz-Siedlung in Winterquell bietet Starfall in einer ansonsten tückischen und abgelegenen Hochlandwildnis wichtige Erholung, Handelswaren und Wegbeschreibungen.",["race:NightElf"]="Für die Nachtelfen ist Starfall ein wichtiger nördlicher Außenposten, der neben einer ruhigen, unbewohnten Grabhöhle steht."},sec={{t="Ein Zufluchtsort der Allianz im Schnee",b="Nordwestlich des Goblin-Handelspostens Ewige Warte und südlich des Frostsäblerfelsen gelegen, stellt Starfall das einzige Bollwerk der Allianz-Zivilisation in Winterquell dar. Die Siedlung besteht aus traditionellen Blockhütten der Nachtelfen und dient als Zufluchtsort für Reisende, indem sie inmitten der rauen Bergwelt wichtige Vorräte und eine warme Feuerstelle bietet. Trotz seines friedlichen Erscheinungsbildes bleibt das Dorf stets wachsam, da es an eine ruhige, unbewohnte Grabhöhle angrenzt."}},faq={{q="Was ist Starfall?",a="Starfall ist eine Enklave der Nachtelfen in Winterquell. Sie fungiert als wichtigster Zufluchtsort und Versorgungslager für die Allianz im Tal und bietet Unterkunft, Handel und Orientierung für Späher, die in Richtung Frostsäblerfelsen reisen oder die nahegelegenen Grabhöhlen untersuchen.",al={"starfall","stadt starfall","was ist das für ein ort"}},{q="Können Spieler der Horde die Einrichtungen in Starfall nutzen?",a="Nein. Starfall ist strikt auf die Nachtelfen und die Allianz ausgerichtet. Reisende der Horde, die zu nah kommen, werden von den örtlichen Verteidigern feindselig empfangen.",al={"ist starfall freundlich zur horde","kann die horde starfall nutzen","starfall horde"}},{q="Was hat es mit der Grabhöhle neben dem Dorf auf sich?",a="Die Höhle direkt hinter dem Dorf ist eine leere Grabhöhle. Solche Zufluchtsorte beherbergen traditionell Druiden, während ihre Geister im Smaragdgrünen Traum wandeln, doch hier schlafen derzeit keine Druiden.",al={"grabhöhle starfall","höhle neben starfall"}},{q="Wo liegt Starfall?",a="Das Dorf liegt an der schneebedeckten Hauptstraße durch Winterquell, nordwestlich der Goblin-Siedlung Ewige Warte und südlich des Frostsäblerfelsen.",al={"standort von starfall","wie komme ich nach starfall","wo ist starfall"}}},fp="16,277,30.476.0,25.269.0,56.168.0,43.185.0,34.157.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="Stahlrosts Depot",s="Stahlrosts Depot ist eine geschäftige Ingenieurswerkstatt und Reparaturstation direkt östlich von Kharanos in Dun Morogh. Unter der Aufsicht von Beldin Stahlrost und einer Gruppe von Handwerkern dient es als Knotenpunkt an vorderster Front für die Fahrzeugwartung, Tüftler-Nachschublieferungen und Bergungsarbeiten.",h="Stahlrosts Depot ist eine geschäftige Ingenieurswerkstatt und Reparaturstation direkt östlich von Kharanos in...",kw={"belbi steelgrill","dun morogh","ingenieurskunst","kharanos","steelgrill","stahlrosts depot","werkstatt"},ang={["profession:Engineering"]="Das Depot ist ein Freiluftlabor, umgeben von Dampfmaschinen und Tüftlerbedarf, was es zu einem natürlichen Rastplatz für angehende Ingenieure macht, die durch Dun Morogh reisen.",["race:Gnome"]="In enger Zusammenarbeit mit ihren zwergischen Gastgebern nutzen verbannte Gnomentüftler oft die Schmiedefeuer und Ersatzteile des Depots, um ihre geborgenen Apparaturen am Laufen zu halten."},sec={{t="Eine Bastion aus Dampf und Stahl",b="Eingebettet direkt an der verschneiten Straße östlich von Kharanos ertönt in Stahlrosts Depot das Klappern von Metall, das Zischen von Dampfventilen und das Summen experimenteller Motoren. Zwergenbergleute und exzentrische Gnomeningenieure versammeln sich hier inmitten schwerer Maschinen, mechanisierter Schreitpanzer und Vorräten an Roherzen, die aus nahe gelegenen Steinbrüchen herangeschafft wurden. Während Dun Morogh mit unablässigen Angriffen von Troggs und Engpässen bei mechanischen Vorräten zu kämpfen hat, halten Beldin Stahlrost und seine Mannschaft die Maschinen der Allianz in Schuss und bilden so eine unverzichtbare Anlaufstelle für Reisende, die in der bitteren Kälte Ersatzteile oder technischen Rat suchen."}},faq={{q="Was ist Stahlrosts Depot?",a="Stahlrosts Depot ist eine Ingenieurswerkstatt und ein Außenposten in Dun Morogh, der etwas weiter die Straße hinunter östlich von Kharanos liegt. Es richtet sich an Bergleute, Tüftler und Feldtechniker, die schwere Maschinen warten.",al={"steelgrills depot","was ist dieser ort","steelgrills"}},{q="Wer leitet das Depot?",a="Das Depot wird von der Steelgrill-Familie verwaltet, insbesondere von Beldin Stahlrost, zusammen mit anderen zwergischen und gnomischen Handwerkern, die die umliegenden Maschinen warten und die Bergbauarbeiten beaufsichtigen.",al={"wer leitet steelgrills","wer betreibt steelgrills depot","belbi steelgrill"}},{q="Welche Dienste sind hier verfügbar?",a="Das Depot beherbergt Handwerkshändler, Reparaturdienste und Ausbilder für Handwerker, die ihre Ingenieurs- und Sammelfertigkeiten im Feld verfeinern möchten.",al={"lehrer in steelgrills","was kann ich hier tun","dienste in steelgrills depot"}}},fx={["01d49f70"]={q="Ist Stahlrosts Depot gefährlich?",a="Nicht direkt. Stahlrosts Depot ist ein sicheres Arbeitslager und Handelsstützpunkt der Zwerge, das sicher an der verschneiten Straße östlich von Kharanos liegt. Während die umliegenden Felsen und Hügel vor wilden Tieren, umherstreifenden Troggs und lästigen Leprognomen, die nach dem Fall von Gnomeregan fliehen, nur so wimmeln, bleibt das Depot selbst fest in den Händen der Allianz, bewacht von herzhaften Bergleuten, Handwerkern und den Bergsteigern aus der Umgebung.",al={"ist stahlrosts depot gefährlich","gefahr stahlrosts depot","ist es sicher in stahlrosts depot"}},["14c76990"]={q="Warum heißt es Stahlrosts Depot?",a="Der Außenposten hat seinen Namen von Beldin Stahlrost, dem leitenden Ingenieur und Unternehmer, der hier die Aufsicht führt. Beldin und seine Mitstreiter errichteten dieses Lager am Wegesrand, um zwergische und gnomische mechanische Wunderwerke, Belagerungsmaschinen und Bergbauausrüstung direkt vor der geschäftigen Siedlung Kharanos zu warten, zusammenzubauen und zu testen.",al={"warum stahlrosts depot","wer ist stahlrost","ursprung des namens stahlrost"}}},fp="18,272,28.601.0,27.200.0,19.189.0,33.150.0"}
P.entries["subzone:stendel-s-pond"] = {n="Stendels Tümpel",s="Stendels Tümpel ist ein kleines, möglicherweise verdorbenes Gewässer südwestlich der Späherkuppe in Westfall. Umgeben von herumstreifenden Gnollen und gekennzeichnet durch nahegelegene Gräber, bleibt er trotz seiner unheimlichen Gefahren einer der wenigen frischen Angelplätze in der ausgedörrten Landschaft.",h="Stendels Tümpel ist ein kleines, möglicherweise verdorbenes Gewässer südwestlich der Späherkuppe in Westfall.",kw={"gnolle","gräber","tümpel","weiskarpfen","späherkuppe","stendel","westfall"},ang={["faction:Alliance"]="In der Nähe der Späherkuppe gelegen, bleibt der Tümpel aufgrund von Gnoll-Lagern eine unkontrollierte Bedrohung an der südlichen Grenze der Volksmiliz.",["profession:Cooking"]="Der aus diesen trüben Gewässern gefangene Weiskarpfen wird von Köchen für ihre Fischgerichte geschätzt."},sec={{t="Eine gefährliche Wasserstelle",b="Versteckt südwestlich der Späherkuppe bietet Stendels Tümpel eine ruhige Pause von Westfalls staubigen Ebenen, auch wenn die Gefahr nie weit entfernt ist. Gnolle durchstreifen die schlammigen Ufer, während verstreute Skelette und ein paar einsame Gräber darauf hindeuten, dass entweder die Gewässer oder die Bestien um sie herum für unvorsichtige Reisende tödlich sind. Angler riskieren dennoch die beschwerliche Reise wegen der Schwärme von Weiskarpfen."}},faq={{q="Wo befindet sich Stendels Tümpel?",a="Er liegt südwestlich der Späherkuppe im zentralen Westfall, direkt abseits der staubigen Pfade, die in die südlichen Gefilde führen.",al={"lage von stendels tümpel","wo ist stendels tümpel","stendels tümpel finden"}},{q="Welche Kreaturen lauern um den Tümpel herum?",a="Das schlammige Ufer des Tümpels wird von territorialen Riverpaw-Gnollen durchstreift, die jeden Wanderer angreifen, der sich dem Wasser nähert.",al={"wer lebt hier","monster an stendels tümpel","gnolle an stendels tümpel"}},{q="Warum befinden sich Skelette und Gräber am Ufer?",a="Die Skelette und zwei unbeschriftete Gräber weisen auf die tödlichen Gefahren der Gegend hin. Ob Reisende den Gnollen zum Opfer fielen oder durch fauliges Tümpelwasser vergiftet wurden, bleibt ein unheilvolles Geheimnis.",al={"wessen gräber sind das","warum skelette","grab am tümpel"}}},fx={a33fcb3a={q="Was ist Stendels Tümpel?",a="Stendels Tümpel ist ein kleines, ruhiges Gewässer, das südwestlich der Späherkuppe in den zentralen Ebenen von Westfall liegt. Obwohl er aus der Ferne friedlich wirkt, erzählen die Ufer des Tümpels eine düstere Geschichte von Not in dieser staubigen Region.",al={"was ist stendels tümpel","übersicht stendels tümpel","über stendels tümpel"}},["9e1e18fd"]={q="Ist Stendels Tümpel gefährlich?",a="Ja, er ist alles andere als sicher für allein reisende Abenteurer. Aggressive Gnolle streifen am Wasser entlang und machen jede Annäherung gefährlich. Zudem deuten die Skelettreste und einsamen Gräber entlang des Ufers darauf hin, dass entweder die lokale Tierwelt tödlich ist oder das abgestandene Wasser selbst ungenießbar sein könnte.",al={"ist stendels tümpel sicher","gefahren bei stendels tümpel","wie gefährlich ist stendels tümpel"}}},fp="14,267,25.355.0,32.117.0,36.116.0,48.177.0"}
P.entries["subzone:stillwater-pond"] = {n="Stillwater-Tümpel",s="Der Stillwater-Tümpel ist ein ruhiges, stehendes Gewässer direkt westlich von Brill in Tirisfal. Einst ein beliebter Picknick- und Badeort für die lebenden Kinder von Lordaeron, ist er zu einem trüben Becken verfallen, das von Skelettfischen bewohnt und von gefährlichen Aasfressern durchstreift wird.",h="Der Stillwater-Tümpel ist ein ruhiges, stehendes Gewässer direkt westlich von Brill in Tirisfal.",kw={"bayne","blendwassersee","brill","schattenhund","skelettfisch","stillwater-tümpel","tirisfal"},ang={["class:Hunter"]="Die verseuchte Tierwelt rund um den Tümpel, darunter wilde Schattenhunde wie Bayne, macht das Gebiet zu einem gefährlichen Jagdrevier für Späher, die am Rande von Brill patrouillieren.",["race:Undead"]="Für Verlassene, die noch Erinnerungen an ihr Leben in Lordaeron haben, steht der Stillwater-Tümpel als düstere Mahnung an verlorene Kindheitstage, an denen sie an seinen einst klaren Ufern picknickten und schwammen."},sec={{t="Ein zerstörter Zufluchtsort",b="Vor dem Dritten Krieg und den Verheerungen durch die Seuche des Untods diente der Stillwater-Tümpel als friedlicher Rückzugsort für das Volk von Tirisfal. Familien aus den umliegenden Weilern versammelten sich an seinen grasbewachsenen Ufern zu nachmittäglichen Picknicks, und Kinder, die noch zu jung waren, um den tückischen Tiefen des Blendwassersees zu trotzen, lernten in seinen seichten Gewässern das Schwimmen. Heute ist das idyllische Wasser leblos und grau geworden. Die Lebenden sind längst verschwunden; geblieben sind nur noch Skelettfische, die unter der Oberfläche dahinflitzen, und umherirrende Untote, die durch die umliegenden Wälder streifen."},{t="Lauerer im Nebel",b="Obwohl der Stillwater-Tümpel im Vergleich zu den belagerten Straßen und umkämpften Bauernhöfen von Tirisfal ruhig wirkt, birgt er seine ganz eigenen Gefahren. Das trübe Wasser dient nur noch den verseuchten Bestien der Lichtungen als Tränke – allen voran einem wilden Schattenhund namens Bayne, der am Ufer umherstreift. Reisende, die auf ihrem Weg nach Brill die westlichen Wiesen durchqueren, müssen vorsichtig sein, da räuberische Bestien und ziellose Zombies oft am Wasserrand verweilen."}},faq={{q="Wie war der Stillwater-Tümpel vor der Seuche?",a="In den Tagen des menschlichen Lordaeron war der Stillwater-Tümpel ein malerischer und beliebter Ort für Ausflüge und Picknicks. Da er seicht und ruhiger als der weitläufige Blendwassersee war, brachten Familien häufig kleine Kinder hierher, damit sie gefahrlos schwimmen konnten.",al={"stillwater-tümpel geschichte","wofür wurde der stillwater-tümpel genutzt","tirisfal badeort"}},{q="Lebt heute noch etwas in dem Wasser?",a="Normales Wasserleben hat die Verderbnis von Tirisfal nicht überstanden. Das Einzige, was noch unter der grauen Oberfläche schwimmt, sind die wiederbelebten, skelettierten Überreste von Fischen, die durch den Einfluss der Geißel zurückgelassen wurden.",al={"stillwater-tümpel fische","was lebt im stillwater-tümpel","stillwater kreaturen"}},{q="Welche gefährlichen Kreaturen streifen nahe dem Tümpel umher?",a="Abgesehen von geistlosen Untoten, die durch die Lichtungen wandern, ist die berüchtigtste Bedrohung am Ufer Bayne – ein ungewöhnlich mächtiger und aggressiver Schattenhund, der unvorsichtige Reisende reißt.",al={"stillwater-tümpel monster","wer ist bayne","schattenhund bei brill"}},{q="Wo befindet sich der Stillwater-Tümpel?",a="Der Stillwater-Tümpel liegt im zentralen Tirisfal, direkt westlich der Stadt Brill und südwestlich des größeren Blendwassersees.",al={"wo liegt der stillwater-tümpel","stillwater-tümpel standort","stillwater-tümpel finden"}}},fx={fa6e3aa4={q="Was ist Stillwater-Tümpel?",a="Stillwater-Tümpel ist ein ruhiger, im Schatten liegender See, der direkt westlich der Stadt Brill liegt. Einst ein geschätzter Freizeitort für die lebenden Familien von Lordaeron, liegt er nun kalt, grau und still da und spiegelt die düstere Einöde wider, die den Rest von Tirisfal bedeckt.",al={"was ist stillwater-tümpel","stillwater-tümpel geschichte","erzähl mir von stillwater-tümpel"}},["7a8eb54a"]={q="Warum ist Stillwater-Tümpel verfallen und verlassen?",a="Der Tümpel verfiel während des Dritten Krieges zusammen mit dem Rest des Königreichs, als die Geißel die Plage des Untodes über Tirisfal brachte. Die verheerende Fäulnis, die über Lordaeron hinwegzog, löschte das sterbliche Leben an seinen Ufern aus und verwandelte angenehme Picknickplätze in eine trostlose Wildnis, in der wilde Tiere und die wandernden Toten ihr Unwesen treiben.",al={"warum ist stillwater-tümpel verlassen","was zerstörte stillwater-tümpel","warum ist stillwater-tümpel tot"}}},fp="15,272,16.533.0,20.437.0,48.231.0,42.196.0,46.178.0,33.129.0"}
P.entries["subzone:stone-cairn-lake"] = {fx={a25fa3d9={q="Was ist Der Steinhügelsee?",a="Der Steinhügelsee ist ein ringförmiges Gewässer im nordöstlichen Wald von Elwynn. In seiner Mitte liegt eine Insel mit Heldenwache, einem feierlichen Denkmal zu Ehren derjenigen, die während des Ersten Krieges umkamen. Einst ein ruhiges Ziel für Reisende und Trauernde, ist die Gegend seitdem verwildert und gefährlich geworden.",al={"was ist der steinhügelsee","info der steinhügelsee","erzähl mir von der steinhügelsee"}},["9a875c99"]={q="Ist Der Steinhügelsee gefährlich?",a="Ja, er stellt eine erhebliche Gefahr für umherstreifende Reisende dar. Schurkenmagier haben die Insel in der Mitte des Sees besetzt und verteidigen ihr Lager aggressiv mit arkaner Magie. Darüber hinaus haben feindselige Murlocs die Untiefen überrannt und Siedlungen entlang der südlichen Ufer errichtet, von wo aus sie jeden angreifen, der sich nähert.",al={"ist der steinhügelsee sicher","bedrohungen der steinhügelsee","gefahr der steinhügelsee"}},["92ff0cce"]={q="Warum wurde Der Steinhügelsee als Pilgerstätte aufgegeben?",a="Der Steinhügelsee war einst ein friedliches Pilgerziel für Bürger, die die gefallenen Soldaten des Ersten Krieges ehrten. Die Wachen von Sturmwind konnten die Sicherheit jedoch angesichts zunehmender Unruhen nicht gewährleisten, was es schurkenhaften Zauberwirkern ermöglichte, die Denkmalinsel zu besetzen und bösartigen Murlocs, die Ufer für sich zu beanspruchen.",al={"warum ist der steinhügelsee verlassen","warum ist der steinhügelsee ruiniert","pilgerstätte steinhügelsee"}}}}
P.entries["subzone:stonebull-lake"] = {n="Stonebullsee",s="Der Stonebullsee ist ein ruhiges, hufeisenförmiges Gewässer, das das Dorf der Bluthufe im Herzen von Mulgore umschließt. Gespeist vom unberührten, natürlichen Abfluss der Ebenen, bietet er lebenswichtiges Süßwasser, reichlich Fisch und friedliche Ufer für die jungen Tauren, die unter der Führung von Cairne Bluthuf das Erwachsenwerden durchleben.",h="Der Stonebullsee ist ein ruhiges, hufeisenförmiges Gewässer, das das Dorf der Bluthufe im Herzen von Mulgore...",kw={"bloodhoof","angeln","see","mulgore","stonebullsee","donnerfels"},ang={["race:Tauren"]="Für die Tauren, die in ganz Mulgore ihre Heimat errichten, spendet der Stonebullsee sanften Lebensunterhalt und erinnert an die Gaben der Erdenmutter nahe ihrer Hauptstadt."},sec={{t="Gewässer der Ebene",b="Indem er das Dorf der Bluthufe von drei Seiten umschließt, prägt der Stonebullsee die Geografie des zentralen Mulgore. Eine Holzbrücke überspannt den schmalsten Abschnitt des Sees und führt den Hauptfeldweg zwischen der Siedlung und der großen Mesa von Donnerfels im Norden entlang. Seine ruhigen Gewässer sind reich an einheimischen Fischen, was seine Ufer zu einem beliebten Rastplatz für ruhende Jäger, müde Reisende und angehende Angler macht, die ihr Handwerk unter dem weiten, offenen Himmel erlernen."}},faq={{q="Wo befindet sich der Stonebullsee?",a="Der Stonebullsee befindet sich im zentralen Mulgore. Er bildet ein Hufeisen um das Dorf der Bluthufe und flankiert die Siedlung von drei Seiten.",al={"stonebullsee lage","wo liegt der stonebullsee","mulgore see"}},{q="Wofür wird die Brücke über den See genutzt?",a="Die Brücke überquert den schmalsten Teil des Stonebullsees, um die Hauptstraße zu tragen, die das Dorf der Bluthufe direkt mit Donnerfels im Norden verbindet.",al={"stonebull brücke","brücke nahe bloodhoof","straße über stonebullsee"}},{q="Warum ist der Stonebullsee für die Tauren wichtig?",a="Der See ist eine unverzichtbare Süßwasserquelle und ein wichtiger Angelplatz für die Bewohner des Dorfes der Bluthufe. Er bietet außerdem einen ruhigen Ort der Besinnung und Zusammenkunft für junge Taurenkrieger, die im zentralen Mulgore trainieren.",al={"warum ist der stonebullsee wichtig","bedeutung des stonebullsees"}}},fx={b1753406={q="Was ist Stonebullsee?",a="Stonebullsee ist ein breites, hufeisenförmiges Gewässer, das das Dorf der Bluthufe im Zentrum von Mulgore umschließt. Seine kühlen, frischen Wasser sind auf den Ebenen für ihre Fülle an Fischen bekannt und bieten sowohl eine grundlegende Nahrungsquelle als auch einen ruhigen Zufluchtsort, an dem die Tauren oft stille Stunden damit verbringen, ihre Angeln vom Ufer aus auszuwerfen. Eine stabile Holzbrücke überspannt die engste Stelle und führt Reisende entlang der Hauptstraße zwischen dem Dorf der Bluthufe und den Klippen im Norden.",al={"stonebullsee mulgore","was ist stonebullsee","über stonebullsee"}},["641ee038"]={q="Ist Stonebullsee gefährlich?",a="Der See selbst ist im Allgemeinen friedlich und durch die Nähe des Dorfes der Bluthufe sowie die in der Nähe patrouillierenden Tauren-Krieger geschützt. Während Raubtiere und umherstreifende Bestien die weiteren Ebenen von Mulgore durchstreifen, bleibt das Wasser des Stonebullsees einer der sichersten Orte zum Angeln und Sammeln in der Region, frei von lauernden aquatischen Schrecken oder feindseligen Siedlungen an seinen unmittelbaren Ufern.",al={"ist stonebullsee gefährlich","bedrohungen am stonebullsee","gefahr stonebullsee"}}},fp="14,298,19.448.0,32.132.0,44.147.0,46.222.0"}
P.entries["subzone:stonefield-farm"] = {n="Hof der Steinfelds",s="Der Hof der Steinfelds ist ein bewirtschaftetes Gehöft im südlichen Wald von Elwynn. Er ist die Heimat der Familie Steinfeld, die seit langem in einer erbitterten Fehde mit ihren Nachbarn, den Maclures, liegt.",h="Der Hof der Steinfelds ist ein bewirtschaftetes Gehöft im südlichen Wald von Elwynn.",kw={"wald von elwynn","oma steinfeld","maclure","stonefield","hof der steinfelds","tommy joe"},ang={["race:Human"]="Für Menschen, die aus Nordhain aufbrechen, bieten die Streitigkeiten zwischen den Steinfelds und Maclures einen heiteren Einblick in das ländliche Leben des Königreichs jenseits der Bedrohung durch Banditen und Gnolle."},sec={{t="Ein verbittertes Gehöft",b="Eingebettet in das hügelige Grün südlich von Goldhain erzeugt der Hof der Steinfelds Feldfrüchte für das Reich, während er gleichzeitig einen heftigen, jahrzehntelangen Groll gegen die nahegelegenen Weinberge der Maclures hegt. Das böse Blut zwischen den Haushalten führt zu kleinlichen Zankereien, gegenseitigen Diebstahlsvorwürfen und ständigen Spannungen. Doch hinter den feindseligen Streitigkeiten hat sich der junge Tommy Joe Steinfeld heimlich in Maybell Maclure verliebt – eine stille Romanze, die entweder die Kluft zwischen den Familien überbrücken oder weitere Empörung entfachen könnte."}},faq={{q="Was hat es mit der Fehde zwischen den Steinfelds und den Maclures auf sich?",a="Die Familien Steinfeld und Maclure pflegen im südlichen Wald von Elwynn eine langjährige, hartnäckige Rivalität. Sie beschuldigen einander ständig des Hausfriedensbruchs, des einfachen Diebstahls und allgemeiner Vergehen und weigern sich, selbst bei einfachen nachbarschaftlichen Angelegenheiten zusammenzuarbeiten.",al={"fehde stonefield maclure","warum kämpfen die stonefields","stonefield rivalen"}},{q="Wer lebt auf dem Hof der Steinfelds?",a="Das Gehöft wird von der Familie Steinfeld bewirtschaftet, darunter Oma Steinfeld, Mutter Steinfeld und der junge Tommy Joe Steinfeld.",al={"stonefield npcs","wer ist auf dem hof der stonefields"}},{q="Was ist das Geheimnis von Tommy Joe Steinfeld?",a="Trotz der erbitterten Feindseligkeit zwischen den beiden Haushalten ist Tommy Joe Steinfeld heimlich in Maybell Maclure verliebt. Die beiden Liebenden sind auf wohlwollende Reisende angewiesen, um Botschaften und Geschenke hin und her zu überbringen, ohne dass ihre Familien etwas davon bemerken.",al={"geheimnis von tommy joe","tommy joe romanze","stonefield liebe"}}},fx={["60255a1c"]={q="Was ist Hof der Steinfelds?",a="Hof der Steinfelds ist ein ruhiges Gehöft im südlichen Wald von Elwynn, das von der Familie Steinfeld bewirtschaftet und gepflegt wird. Obwohl es wie ein gewöhnlicher Bauernhof aussieht, der Feldfrüchte für die Region produziert, ist er im ganzen Tal für seine lange, bittere Rivalität mit dem benachbarten Gehöft, den Weinberge der Maclures, bekannt. Besucher finden sich oft inmitten häuslicher Streitigkeiten, Zänkereien um Erbstücke und den geheimen romantischen Bestrebungen der jüngeren Generation wieder.",al={"was ist hof der stonefields","stonefield farm elwynn","über hof der stonefields"}},["45c8f9cb"]={q="Ist Hof der Steinfelds gefährlich?",a="Das Gehöft selbst ist im Allgemeinen sicher und wird von der Familie instand gehalten, aber die umliegenden Felder sind eine andere Sache. Wie in weiten Teilen des südlichen Wald von Elwynn streifen wilde Tiere durch die Außenbezirke, und örtliche Banditen sowie eindringende Schädlinge bedrohen häufig das Vieh und die Ernte. Reisende sollten ihre Waffen bereithalten, wenn sie sich in die Weiden wagen oder hinunter zu den nahe gelegenen Flussufern und Obstgärten wandern.",al={"ist hof der stonefields gefährlich","bedrohungen bei hof der stonefields","feinde hof der stonefields"}}},fp="15,190,18.517.0,58.248.0,29.124.0,38.239.0"}
P.entries["subzone:stonefire-tavern"] = {n="Stonefire Tavern",s="Die Stonefire Tavern ist das Haupthaus für Reisende innerhalb der Bergstadt Eisenschmiede. Im belebten Viertel The Commons, direkt nördlich der Stadttore gelegen, bietet sie einen warmen Herd, kräftiges Zwergenbier und einen Rastplatz für Abenteurer, die aus ganz Khaz Modan eintreffen.",h="Die Stonefire Tavern ist das Haupthaus für Reisende innerhalb der Bergstadt Eisenschmiede.",kw={"the commons","zwergengasthaus","gwenna firebrew","gastwirt feuerbräu","eisenschmiede","khaz modan","stonefire tavern"},ang={["faction:Alliance"]="Als das den Vordertoren von Eisenschmiede am nächsten gelegene große Gasthaus dient die Stonefire Tavern Allianz-Reisenden, die die Zwergenhauptstadt besuchen, oft als zentraler Ausgangspunkt.",["race:Dwarf"]="Für Zwerge, die von Expeditionen aus ganz Khaz Modan zurückkehren, ist die Stonefire Tavern der erste Ort in der Hauptstadt, um sich ein kühles Pint Firebrew-Bier zu gönnen und den neuesten Klatsch zu erfahren."},sec={{t="Das Herz der Commons",b="Direkt nördlich der Festungstore in The Commons gelegen, dient die Stonefire Tavern als wichtigstes Gasthaus in Eisenschmiede. Geführt von Gastwirt Feuerbräu und seiner Tochter Gwenna bietet die Schänke müden Reisenden deftige Mahlzeiten, lokale Brauerzeugnisse und Unterkünfte unter dem Berg. Ob auf der Suche nach Schutz vor den harschen Bergschneen von Dun Morogh oder um Geschichten und Vorräte auszutauschen, bevor es tiefer in die Stadt geht – Reisende aus allen Winkeln der Allianz versammeln sich regelmäßig um den prasselnden Kamin."}},faq={{q="Wo befindet sich die Stonefire Tavern?",a="Die Taverne befindet sich im Viertel The Commons von Eisenschmiede, nur einen kurzen Fußweg nördlich der Hauptstadttore.",al={"stonefire tavern standort","eisenschmiede gasthaus lage","wo ist stonefire"}},{q="Wer betreibt die Stonefire Tavern?",a="Die Taverne wird von Gastwirt Feuerbräu mit Unterstützung seiner Tochter, Gwenna Firebrew, geführt.",al={"wer leitet stonefire tavern","stonefire gastwirt","firebrew gasthaus"}},{q="Können Reisende hier ihren Ruhestein binden?",a="Ja. Gastwirt Feuerbräu heißt Allianz-Reisende willkommen, die die Stonefire Tavern zu ihrem Heimatort in Eisenschmiede machen möchten.",al={"ruhestein eisenschmiede","eisenschmiede heimatgasthaus","ruhestein stonefire"}},{q="Welche Annehmlichkeiten befinden sich in der Nähe?",a="Direkt vor dem Eingang der Taverne befindet sich ein städtischer Briefkasten, und das umliegende Viertel The Commons ist voll von Banken, Händlern und Handwerkswaren.",al={"stonefire dienste","briefkasten nahe stonefire"}}},fx={a8df8501={q="Was ist Stonefire Tavern?",a="Die Stonefire Tavern dient als einer der wichtigsten Treffpunkte und Gasthäuser innerhalb von Eisenschmiede. Sie liegt im geschäftigen Stadtviertel der Unterstadt, direkt nördlich der Stadttore, und bietet ein warmes Kaminfeuer, starkes Zwergenbier und einen einladenden Ort zum Ausruhen für müde Reisende, Soldaten und Besucher, die in der Bergkapitale ankommen.",al={"was ist stonefire tavern","stonefire tavern eisenschmiede","eisenforge stonefire gasthaus"}},["3314a531"]={q="Ist Stonefire Tavern gefährlich?",a="Nicht im Geringsten. Die Stonefire Tavern ist ein sicherer, freundlicher Zufluchtsort, der tief im befestigten Herzen von Eisenschmiede liegt. Bewacht von der Zwergenwache und umgeben von anderen Allianz-Gästen, ist die einzige wirkliche Gefahr, der Ihr dort begegnen könntet, ein Krug zu viel von dem starken Gebräu der Firebrews.",al={"ist stonefire tavern sicher","gefahr stonefire tavern","bedrohungen stonefire tavern"}}},fp="16,284,20.513.0,38.120.0,34.97.0,43.122.0,26.136.0"}
P.entries["subzone:stonemaul-ruins"] = {n="Die Stonemaul Ruinen",s="Die Stonemaul Ruinen sind die zerstörten Überreste von Stonemaul Village, einst die stolze Siedlung der Stonemaul-Oger auf Kalimdor. Nachdem sie vom Schwarzen Drachenschwarm vertrieben worden waren, floh der Clan nach Norden und überließ seine einstige Heimat den marodierenden Firemane-Drachkin.",h="Die Stonemaul Ruinen sind die zerstörten Überreste von Stonemaul Village, einst die stolze Siedlung der...",kw={"brackenwall","das drachendüster","firemane","kor'gall","mok'morokk","stonemaul","die stonemaul ruinen","stonemaul village"},ang={["faction:Horde"]="Die Stonemaul-Oger sind treue Verbündete, die an der Seite von Thralls Horde gegen Kul Tiras Blut vergossen haben. Ihnen dabei zu helfen, gegen den Schwarzen Drachenschwarm zurückzuschlagen, ehrt diesen Pakt."},sec={{t="Aufstieg und Fall der Clanheimat",b="Nach ihrer Migration nach Kalimdor gründeten die Stonemaul-Oger ihre Siedlung inmitten der trüben Sümpfe der Düstermarschen. Das Dorf erlangte Berühmtheit, als der Bestienmeister Rexxar den tödlichen Prüfungen des Clans trotzte, ihren brutalen Häuptling Kor'gall erschlug und die Oger sammelte, um die aufkeimende Horde gegen die Streitkräfte von Admiral Proudmoore zu verteidigen. Nach dem Krieg übertrug Rexxar dem Oger Mok'Morokk das Kommando. Unter Mok'Morokks selbstsüchtiger Herrschaft verfiel das Dorf und wurde schließlich vom Schwarzen Drachenschwarm überrannt und zerstört. Die überlebenden Oger flohen nach Norden, um Brackenwall zu errichten, während Onyxias Brut die Ruinen vollständig in Besitz nahm."},{t="Der Kampf um die Rückeroberung",b="Heute liegen die Ruinen tief im Drachendüster und wimmeln von Firemane-Drachkin, die sich um die nahe gelegenen Nistplätze der Brut kümmern. Während Oberanführer Mok'Morokk feige wurde und sich damit begnügte, in Brackenwall vor sich hinzuleben, weigern sich ältere und stolzere Clanmitglieder wie Tharg und Draz'Zilb, ihre Heimat aufzugeben. Von Brackenwall aus drängen sie die Champions der Horde dazu, die besetzenden Drachkin zu vernichten und die Eier des Drachenschwarms zu zerschlagen, in der Hoffnung, dass die Stonemaul eines Tages zurückmarschieren und ihr angestammtes Dorf zurückfordern können."}},faq={{q="Wer lebte früher in den Stonemaul Ruinen?",a="Der Stonemaul-Clan der Oger errichtete und bewohnte die Siedlung, die damals als Stonemaul Village bekannt war, nach ihrer Ankunft auf Kalimdor.",al={"wer lebte hier","stonemaul ruinen geschichte","wer erbaute stonemaul village"}},{q="Warum wurde das Dorf aufgegeben?",a="Onyxias Schwarzer Drachenschwarm griff die Siedlung an und vertrieb die Oger, wodurch das Dorf zu einem Nistausposten für Firemane-Drachkin wurde.",al={"warum ist stonemaul zerstört","was geschah mit stonemaul village","wer griff stonemaul an"}},{q="Wohin gingen die überlebenden Oger?",a="Die Überlebenden zogen sich unter Oberanführer Mok'Morokk nach Norden in die Düstermarschen zurück und errichteten Brackenwall als ihre provisorische Festung.",al={"wo sind die oger jetzt","stonemaul oger aufenthaltsort"}},{q="Welche Verbindung hatte Rexxar zu diesem Ort?",a="Rexxar kam hierher, um die Oger gegen Kul Tiras zu gewinnen. Er bestand ihre Prüfung, erschlug ihren tyrannischen Kriegsherrn Kor'gall im Kampf und diente kurzzeitig als Häuptling, bevor er die Führung an Mok'Morokk übergab.",al={"rexxar stonemaul","rexxar ogerhäuptling"}},{q="Planen die Oger, die Ruinen zurückzuerobern?",a="Ja. Während Mok'Morokk Angst hatte zu handeln, rekrutieren andere Anführer der Stonemaul wie Tharg und Draz'Zilb aktiv Abenteurer der Horde, um die Firemane-Drachkin auszudünnen und die Rückeroberung ihrer Heimat vorzubereiten.",al={"kehren die oger zurück","rückeroberung von stonemaul"}}},fp="15,257,30.654.0,28.522.0,36.124.0,30.146.0,33.144.0,43.201.0,38.196.0"}
P.entries["subzone:stonesplinter-valley"] = {n="Splittersteintal",s="Das Splittersteintal ist ein zerklüftetes Gebirgstal im südwestlichen Loch Modan, das von feindseligen Troggs überrannt wurde. Einst eine unberührte alpine Mulde, hat es sich unter dem brutalen Befehl des Trogg-Häuptlings Grawmug in ein befestigtes Lager verwandelt.",h="Das Splittersteintal ist ein zerklüftetes Gebirgstal im südwestlichen Loch Modan, das von feindseligen Troggs...",kw={"grawmug","loch modan","splitterstein","splittersteintal","thelsamar","troggs"},ang={["faction:Alliance"]="Die Säuberung des Splittersteintals sichert lebenswichtige Versorgungswege, die durch Loch Modan verlaufen und verwundbar geworden sind, da die Streitkräfte von Eisenschmiede über das gesamte Reich verteilt sind.",["race:Dwarf"]="Die Trogg-Plage hier ist ein Hohn für die Sicherheit von Loch Modan, und die Gebirgsjäger von Thelsamar verlassen sich auf standhafte Zwergenverwandte, um Grawmugs vordringende Schläger zu beseitigen."},sec={{t="Eine schnatternde Festung",b="Versteckt zwischen den schroffen Hängen des südwestlichen Loch Modan war das Splittersteintal einst eine ruhige alpine Mulde. Diese Gelassenheit endete, als Wellen unterirdischer Troggs sich quer durch Khaz Modan ihren Weg an die Oberfläche bahnten. Der Stamm der Splittersteine beanspruchte das Tal für sich und verwandelte die felsigen Engpässe rasch in primitive Befestigungen, grub Höhlen, errichtete Barrikaden und jagte alles, was sich zu nahe heranwagte. Ihre schiere Zahl macht das Tal zu einer offenen Wunde an den Straßen durch das südliche Loch Modan, was die Gebirgsjäger aus Thelsamar dazu zwingt, abenteuerlustige Söldner anzuheuern, die bereit sind, ihre Reihen zu lichten und ihren hünenhaften Kriegsherrn Grawmug zu beseitigen."}},faq={{q="Wo liegt das Splittersteintal?",a="Es liegt eingebettet in den Bergen in der südwestlichen Ecke von Loch Modan, direkt südlich der Hauptstraße, die am Grautatzengrat vorbeiführt.",al={"lage splittersteintal","wo liegt das splittersteintal","troggtal loch modan"}},{q="Wer beherrscht das Splittersteintal?",a="Das Lager wird von einem brutalen Trogg-Häuptling namens Grawmug beherrscht, der aus dem tiefsten Winkel des Tals die Überfälle des Stammes auf einheimische Reisende und Patrouillen lenkt.",al={"wer führt die splittersteintroggs an","grawmug","troggboss loch modan"}},{q="Warum sind die Troggs hier in Loch Modan?",a="Troggs wurden tief unter der Erde bei Ausgrabungen der Zwerge an anderen Orten in Khaz Modan freigelegt. Getrieben von sinnloser Aggression wanderten einzelne Kriegstrupps an die Oberfläche, und der Stamm der Splittersteine wählte dieses abgelegene Gebirgstal als seinen primären Aufmarschort.",al={"warum gibt es troggs in loch modan","woher kamen die troggs","trogg-ursprung loch modan"}},{q="Warum liegt den Zwergen daran, das Tal zu säubern?",a="Das Tal liegt gefährlich nahe an Zwergensiedlungen, Minen und Gebirgsstraßen. Eine verschanzte Armee von Splittersteintroggs sich selbst zu überlassen, bedroht die Sicherheit von Reisenden, die durch das südliche Loch Modan ziehen, und strapaziert die ohnehin überforderten Patrouillen der Gebirgsjäger.",al={"warum splittersteintroggs bekämpfen","thelsamar troggproblem"}}},fx={c84babb8={q="Was ist das Splittersteintal?",a="Das Splittersteintal ist ein zerklüftetes Bergtal, das in den südwestlichen Teil von Loch Modan eingeschnitten ist. Einst eine unberührte alpine Landschaft, wurde es vollständig von einem riesigen Clan feindseliger Troggs überrannt, die die Mulden und Gebirgspässe als ihre eigene Festung beansprucht haben.",al={"übersicht splittersteintal","was ist das splittersteintal","über das splittersteintal"}},["30aeaf73"]={q="Was ist mit dem Splittersteintal geschehen?",a="Was einst eine unberührte und friedliche Ecke des Gebirgsbeckens von Loch Modan war, verwandelte sich in einen Bau für die Troggs. Nachdem sie sich in ganz Khaz Modan ausgegraben hatten, flutete der Splittersteinclan in großer Zahl in das Tal, verwüstete die Wildnis und vertrieb jeden, der es wagte, sich zu nähern.",al={"geschichte splittersteintal","was geschah mit dem tal","trogg-befall splittersteintal"}},["39c06fe2"]={q="Ist das Splittersteintal gefährlich?",a="Es ist äußerst gefährlich. Feindselige Splittersteintroggs wimmeln in dichter Zahl durch das Gelände und bewachen ihr Territorium erbittert gegen Außenstehende. Tief im Herzen des Tals lauert ihr gefürchteter Häuptling, Grawmug, was jeden Vorstoß tief in das Tal zu einem tödlichen Unterfangen macht.",al={"wie gefährlich ist das splittersteintal","bedrohung splittersteintal","ist das splittersteintal sicher"}},["27e6d962"]={q="Warum heißt es Splittersteintal?",a="Das Tal hat seinen Namen direkt von dem Splittersteintroggstamm, der es heimsucht und kontrolliert. Ihre befestigte Präsenz hat die Gegend in den Augen der umliegenden Zwergenverteidiger völlig neu definiert.",al={"namensherkunft splittersteintal","warum splittersteintal","ursprung des namens splitterstein"}}},fp="20,234,23.646.0,38.136.0,31.171.0,38.260.0,50.267.0"}
P.entries["subzone:stonetalon-peak"] = {n="Der Steinkrallengipfel",s="Der Steinkrallengipfel ist ein uraltes Refugium der Nachtelfen, eingebettet in ein fruchtbares alpines Tal am nordwestlichen Rand des Steinkrallengebirges. Es ist den Kaldorei heilig, wird von einheimischen Druiden gepflegt und dient als wichtigste Bastion der Allianz in diesen schroffen Höhen.",h="Der Steinkrallengipfel ist ein uraltes Refugium der Nachtelfen, eingebettet in ein fruchtbares alpines Tal am...",kw={"jaina","kaldorei","nachtelf","orakel","schildwachen","steinkrallen","der steinkrallengipfel","talon den","thrall"},ang={["class:Druid"]="Das Refugium ist tief mit der Geschichte des Cenarius und der heiligen Talon Den verwoben, was es zu einer unverzichtbaren Pilger- und Verteidigungsstätte für die Wächter der Natur macht.",["faction:Alliance"]="Der Steinkrallengipfel ist Euer einziger befestigter Stützpunkt in den westlichen Bergen und bietet lebenswichtige Erholung, Flugrouten und Quest-Unterstützung inmitten feindlichen Gebiets."},sec={{t="Ein heiliges Bergtal",b="Hoch über dem trockenen Staub der unteren Hänge gelegen, öffnet sich der Steinkrallengipfel zu einem üppigen, nebelverhangenen Zufluchtsort. Das Tal gilt seit Langem als heilig und ist von uralter Magie durchdrungen; es birgt Ruinen, die Jahrtausende zurückreichen, als die Region vor der Großen Zerschlagung Tempel zu Ehren von Königin Azshara beherbergte. In der modernen Ära haben Schildwachen und Druiden der Kaldorei hier wieder eine friedvolle Obhut geschaffen und einen beschaulichen Rückzugsort samt einer Grabhöhle und einem lebenswichtigen Flugplatz der Allianz errichtet."},{t="Kreuzweg des Schicksals",b="Neben seinen idyllischen Wäldern und uralten Ruinen birgt der Steinkrallengipfel historische Bedeutung aus dem Dritten Krieg. Geleitet von den Visionen des Medivh erklommen sowohl Jaina Prachtmeers menschliche Expedition als auch Thralls Horde diese gefährlichen Höhen auf der Suche nach dem schwer fassbaren Orakel, das in den tiefen Höhlen des Berges hauste. Diese schicksalhafte Begegnung zwang Todfeinde dazu, die Klingen ruhen zu lassen, und schuf das Fundament für den fragilen Pakt, der sich am Hyjal der Brennenden Legion entgegenstellte. Heute steht der Gipfel weiterhin fest unter der Wacht der Schildwachen, auch wenn Vorstöße der Horde im Flachland die Verteidiger in Alarmbereitschaft halten."}},faq={{q="Warum ist der Steinkrallengipfel im Vergleich zum Rest des Gebirges so grün?",a="Der Steinkrallengipfel liegt in einem geschützten Hochtal, das von uralter Magie erfüllt ist. Die hingebungsvolle Pflege durch die Nachtelfen und die Druiden des nahegelegenen Talon Den hat einen blühenden, bewaldeten Zufluchtsort bewahrt, dessen Vegetation in starkem Kontrast zu den verkohlten, gezackten Klippen darunter steht.",al={"warum ist der steinkrallengipfel grün","warum wald am steinkrallengipfel","steinkrallengipfel wetter"}},{q="Was geschah hier während des Dritten Krieges?",a="Geleitet von den prophetischen Warnungen des Propheten Medivh reisten sowohl Jaina Prachtmeer als auch Thrall zum Steinkrallengipfel, um das Orakel in den Höhlen des Berges zu finden. Ihre Zusammenkunft tief im Inneren des Gesteins führte dazu, dass sie einen historischen Waffenstillstand schlossen, der Menschen und Orcs im Kampf gegen die Brennende Legion vereinte.",al={"was geschah am steinkrallengipfel warcraft 3","jaina und thrall steinkrallen","das orakel steinkrallen"}},{q="Wer beherrscht derzeit den Steinkrallengipfel?",a="Der Gipfel ist ein Außenposten der Allianz, beschützt und unterhalten von Schildwachen und Druiden der Nachtelfen. Er dient als primärer sicherer Hafen, Quest-Knotenpunkt und Flugmeister-Verbindung für Allianz-Abenteurer, die im Steinkrallengebirge unterwegs sind.",al={"ist der steinkrallengipfel allianz oder horde","wer lebt am steinkrallengipfel","steinkrallengipfel fraktion"}},{q="Welche uralten Ruinen befinden sich hier?",a="Die verfallenen Säulen und Marmorbauwerke, die über das gesamte Tal verstreut sind, sind Überreste des uralten Nachtelfenreichs und dienten einst als Tempelanlagen, die Königin Azshara vor ihrem Abstieg in den Wahnsinn und der Großen Zerschlagung geweiht waren.",al={"steinkrallengipfel ruinen","alter tempel steinkrallen","azshara tempel steinkrallengipfel"}}},fx={["755df306"]={q="Was ist der Steinkrallengipfel?",a="Der Steinkrallengipfel ist ein grünes Bergtal und eine Siedlung der Nachtelfen, eingebettet am weit entfernten nordwestlichen Ende des Steinkrallengebirges. Heilig für die lokalen Kulturen und von alter Magie durchdrungen, steht dieses üppige Heiligtum in krassem Gegensatz zu den kargen Klippen unterhalb. Es dient als lebenswichtige nördliche Bastion für die Nachtelfen und ihre Verbündeten der Allianz im zentralen Kalimdor.",al={"was ist der steinkrallengipfel","übersicht steinkrallengipfel","über den steinkrallengipfel"}},d4bc90d5={q="Ist der Steinkrallengipfel gefährlich?",a="Während der Hain selbst ein befestigter Zufluchtsort für die Allianz ist, bergen die umliegenden Gipfel ernste Gefahren. Aggressive Harpyien nisten in den Felsen, feindselige Holzfäller der Venture Company verwüsten die nahegelegenen Wälder und die Horde bestreitet die Gebirgspässe. Reisende, die zum Gipfel aufsteigen, müssen ständig wachsam gegenüber Hinterhalten auf den schmalen Pfaden bleiben.",al={"ist der steinkrallengipfel sicher","bedrohungen im steinkrallengipfel","gefahren steinkrallengipfel"}}},fp="15,269,22.491.0,21.593.0,70.293.0,40.291.0,39.233.0,36.239.0"}
P.entries["subzone:stonewatch"] = {fx={["5eefcf97"]={q="Was ist Steinwacht?",a="Steinwacht ist eine befestigte militärische Bastion im zentralen Rotkammgebirge, die hoch über den kaskadierenden Steinwachtfällen errichtet wurde. Erbaut von den Menschen aus Seenhain, um als wichtige Verteidigungsbastion gegen die aus der Brennenden Steppe strömenden Orc-Invasionen zu dienen, besteht sie sowohl aus der beeindruckenden Burg Steinwacht als auch aus einem bepanzerten Wachturm, der die umliegenden Täler überblickt.",al={"was ist steinwacht","übersicht burg steinwacht","erzähl mir von steinwacht"}},ae6d9597={q="Ist Steinwacht gefährlich?",a="Steinwacht ist eine der gefährlichsten Regionen im Rotkammgebirge. Schwer befestigt und wimmelnd von disziplinierten Schwarzfelsorc-Invasoren, dient es als zentraler Bereitstellungsraum für ihre Überfälle auf das umliegende Tal. Eindringlinge werden auf kampferprobte Grunzer, Wachen und Hexenmeister treffen, die dem Kriegsherrn Gath'Ilzogg loyal ergeben sind, was jeden Angriff zu einem tödlichen Unterfangen macht.",al={"wie gefährlich ist steinwacht","bedrohung steinwacht","ist steinwacht sicher"}}}}
P.entries["subzone:stonewatch-falls"] = {n="Steinwachtfälle",s="Die Steinwachtfälle sind ein malerischer Wasserfall mit einem tiefen Gebirgsbecken in den östlichen Ausläufern des Rotkammgebirges, gespeist vom Abfluss des Immerruhsees. Unterhalb der aufragenden Höhen von Steinwacht stürzen sie den Berghang hinab, und ihre abgelegenen Gewässer werden von einem feindseligen Murlocstamm beansprucht.",h="Die Steinwachtfälle sind ein malerischer Wasserfall mit einem tiefen Gebirgsbecken in den östlichen...",kw={"der immerruhsee","murlocs","rotkammgebirge","steinwacht","steinwachtfälle","wasserfall"},ang={["faction:Alliance"]="Die Murlocsiedlung an den Steinwachtfällen stellt eine weitere gefährliche Ansammlung von Monstern dar, die Reisende im ohnehin gebeutelten Osten des Rotkammgebirges heimsucht."},sec={{t="Ein gefährliches Gebirgsbecken",b="Die Steinwachtfälle entspringen dem östlichen Fluss des Immerruhsees und stürzen über das zerklüftete Gelände unterhalb der Schwarzfelsork-Festung Steinwacht herab. Das herabstürzende Wasser hat ein tiefes Becken an den Berghang geschwemmt. Trotz seiner natürlichen Schönheit verweilen Reisende selten, um die Aussicht zu bewundern; eine bösartige Murlocbande treibt in dem Becken ihr Unwesen, baut primitive Schilfhütten und lauert jedem auf, der unvorsichtig genug ist, das Ufer zu betreten."}},faq={{q="Woher stammt das Wasser der Steinwachtfälle?",a="Die Wasserfälle werden von dem Fluss gespeist, der an der Ostseite des Immerruhsees abfließt und den Hang hinab in ein abgeschiedenes Gebirgsbecken unterhalb der Klippen von Steinwacht stürzt.",al={"wo beginnen die steinwachtfälle","wasserquelle der fälle","flussquelle steinwacht"}},{q="Welche Kreaturen leben an den Steinwachtfällen?",a="Ein einheimischer Murlocstamm bevölkert die Ufer der Wasserfälle. Sie ernähren sich von Fischen aus dem tiefen Gebirgsbecken und errichten provisorische Unterstände und Hütten am Ufer.",al={"was gibt es an den steinwachtfällen","murlocs an den steinwachtfällen","mobs nahe der fälle"}},{q="Stehen die Steinwachtfälle mit Burg Steinwacht in Verbindung?",a="Die Fälle liegen am Fuße des Hügels direkt unterhalb von Steinwacht und seiner zerstörten Burg. Während Schwarzfelsorks die befestigten Höhen oben beherrschen, dominieren die Murlocs das Wasserbecken darunter.",al={"verbindung der fälle zur burg","liegt burg steinwacht nahe den fällen","steinwacht beziehung"}}},fx={ffdc928b={q="Was sind die Steinwachtfälle?",a="Die Steinwachtfälle sind ein malerischer Wasserfall am Ende des östlichen Flusses vom Der Immerruhsee. Das kaskadierende Wasser stürzt direkt unter der Burg Steinwacht die Hügel hinunter und sammelt sich in einem tiefen, abgelegenen Bergsee, der in den felsigen östlichen Höhen des Rotkammgebirges liegt.",al={"lore steinwachtfälle","was ist dieser ort","wo sind die steinwachtfälle"}},["763cc7e3"]={q="Sind die Steinwachtfälle gefährlich?",a="Ja, Reisende sollten vorsichtig sein. Ein feindseliger Murlocstamm hat das Becken und seine Ufer befallen und primitive Hütten am Ufer errichtet. Zwischen diesen territorialen Strandkriechern und dem Schatten der Schwarzfelsorcs, die die Burg Steinwacht oberhalb besetzen, sind die Gewässer weit entfernt von friedlich.",al={"gefahr steinwachtfälle","ist es hier sicher","bedrohungen an den steinwachtfällen"}},["7a8101a7"]={q="Warum heißen sie Steinwachtfälle?",a="Der Wasserfall hat seinen Namen direkt von der Burg Steinwacht, der beeindruckenden Festung, die auf den Höhen direkt darüber thront. Die Gewässer stürzen direkt den Abhang unterhalb der Festung hinunter.",al={"namensherkunft steinwachtfälle","warum heißen sie steinwachtfälle"}}},fp="16,292,25.441.0,53.165.0,44.178.0,49.190.0"}
P.entries["subzone:stonewatch-keep"] = {n="Burg Steinwacht",s="Burg Steinwacht ist eine befestigte steinerne Festung, die sich im östlichen Rotkammgebirge erhebt und einst vom Königreich Sturmwind erbaut und bemannt wurde. Sie ist an ein einfallendes Heer von Schwarzfelsorcs gefallen und dient als vorgeschobene Operationsbasis, von der aus deren Kriegsfürsten Seenhain terrorisieren.",h="Burg Steinwacht ist eine befestigte steinerne Festung, die sich im östlichen Rotkammgebirge erhebt und einst...",kw={"blackrockklan","gath'ilzogg","keeshan","seenhain","morganth","rotkammgebirge","burg steinwacht","tharil'zun"},ang={["faction:Alliance"]="Burg Steinwacht ist eine schmerzhafte Erinnerung an Sturmwinds überdehnte Grenzen; ihre Zinnen zu säubern ist unerlässlich, um die verwundbaren Stadtbewohner von Seenhain zu schützen.",["race:Human"]="Menschliche Verteidiger vergossen Blut bei der Verteidigung dieser Mauern, und die Befreiung der Burg hilft dabei, die gefallenen Soldaten und die vom Schwarzfelsklan genommenen Gefangenen zu rächen."},sec={{t="Eine gefallene Bastion",b="Burg Steinwacht verteidigte ursprünglich die östlichen Bergkämme und schützte die Siedler von Seenhain vor feindlichen Überfällen. Dieser Frieden zerbrach, als der abtrünnige Hexenmeister Morganth ein Bündnis mit dem Schwarzfelsklan schloss. Gestärkt durch dunkle Magie stürmten die Orcs die Festung mit grausamer Wildheit, überwältigten die menschlichen Verteidiger und nahmen die Burg für sich ein. Obwohl Morganth seine Verbündeten später verließ, um den nahegelegenen Turm von Ilgalar zu errichten und die einheimischen Gnolle zu unterwerfen, festigten die Schwarzfelsinvasoren erfolgreich ihren Griff um Steinwacht und verwandelten eine einstige Bastion der Allianz in einen befestigten Aufmarschort für ihren Angriff auf das Tal."},{t="Der Sitz des Kriegsfürsten",b="Heute wird die Burg von einer schweren Garnison von Schwarzfelskriegern besetzt und vom furchterregenden Orc-Kriegsfürsten Gath'Ilzogg sowie seinem brutalen Leutnant Tharil'zun befehligt. Von den steinernen Zinnen aus koordinieren diese Anführer Raubzüge durch das Rotkammgebirge und nehmen Gefangene wie Sturmwinds Corporal Keeshan. Da das Militär des Königreichs überdehnt ist und kein ganzes Regiment zur Befreiung der Festung entsenden kann, sahen sich Magistrat Solomon und Marschall Marris gezwungen, Söldner-Streiter anzuheuern, um die Festung zu infiltrieren und die Führung des Schwarzfels hinzurichten, bevor Seenhain völlig überrannt wird."}},faq={{q="Wem gehört Burg Steinwacht zurzeit?",a="Die Burg wird derzeit vom Schwarzfelsklan besetzt, der vor Ort von Kriegsfürst Gath'Ilzogg und seinem Leutnant Tharil'zun angeführt wird. Bevor sie eingenommen wurde, war sie eine Festung der Allianz, die die Stadt Seenhain verteidigte.",al={"wer kontrolliert burg steinwacht","wer lebt in burg steinwacht","gegner in burg steinwacht"}},{q="Wie haben die Schwarzfelsorcs die Burg eingenommen?",a="Der Schwarzfelsklan verbündete sich mit dem abtrünnigen menschlichen Hexenmeister Morganth. Gestärkt durch Morganths dunkle Zauberei begannen die Orcs einen wilden Angriff, der die in Steinwacht stationierten menschlichen Verteidiger überwältigte.",al={"wie orcs steinwacht eroberten","fall von burg steinwacht","warum fiel steinwacht"}},{q="Warum erobert die Armee von Sturmwind Burg Steinwacht nicht zurück?",a="Die Armee von Sturmwind hat das Rotkammgebirge aufgrund interner Politik und Truppenmangels im gesamten Königreich weitgehend vernachlässigt. Infolgedessen müssen sich die Stadtführer von Seenhain auf unabhängige Abenteurer verlassen, um der Bedrohung Herr zu werden.",al={"warum keine armee von sturmwind","wo sind die wachen","armeehilfe seenhain"}},{q="Welche Verbindung hat Morganth zu dieser Festung?",a="Morganth half dem Schwarzfelsklan bei der Eroberung von Burg Steinwacht, verriet ihn jedoch kurz nach dem Sieg. Er zog weiter, um seinen eigenen Unterschlupf, den Turm von Ilgalar, zu errichten, und nutzte bezauberte Shadowhide-Gnolle statt Orcs, um seine Befehle auszuführen.",al={"morganth steinwacht","ist morganth in burg steinwacht"}}},fx={["2fd36daf"]={q="Was ist Burg Steinwacht?",a="Burg Steinwacht ist eine massive steinerne Festung, die das nordöstliche Rotkammgebirge überblickt. Ursprünglich von den Menschen aus Seenhain erbaut und besetzt, um die Gebirgspässe zu bewachen, verankerte sie einst die östlichen Verteidigungsanlagen des Königreichs. Heute steht sie als befestigte Bastion der eindringenden Schwarzfelsorcs, die sie durch dunkle Zauberei und brutale Gewalt eroberten.",al={"was ist steinwacht","übersicht burg steinwacht","was ist dieser ort"}},["9c4dac94"]={q="Ist Burg Steinwacht gefährlich?",a="Sie ist eine der gefährlichsten Bastionen im Rotkammgebirge. Schwer befestigt und wimmelnd von disziplinierten Schwarzfelsorcs, wird die Burg vom Kriegsherrn Gath'Ilzogg und seinem vertrauten Leutnant, Tharil'zun, beaufsichtigt. Alleine in ihre Innenhöfe zu wandern ist tödlich; sie einzunehmen erfordert erfahrene Abenteurer, die bereit für einen unerbittlichen, brutalen Kampf sind.",al={"wie gefährlich ist steinwacht","ist burg steinwacht sicher","gefahr durch burg steinwacht"}}},fp="15,277,16.665.0,18.585.0,35.214.0,44.202.0,54.219.0,47.240.0"}
P.entries["subzone:stonewatch-tower"] = {fx={["7b29287c"]={q="Ist der Turm der Steinwacht gefährlich?",a="Extrem gefährlich. Der Turm ist schwer von dem Schwarzfelsklan besetzt und dient als befestigter vorgeschobener Wachtposten direkt im Schatten der Burg Steinwacht. Jeder Reisende, der sich ohne schwere Verstärkung nähert, wird schnell feststellen, dass er von erfahrenen orcischen Kriegern auf Befehl von Gath'Ilzogg umschwärmt wird.",al={"gefahr turm der steinwacht","wie gefährlich ist der turm der steinwacht","ist der turm der steinwacht sicher"}}}}
P.entries["subzone:stonewrought-dam"] = {n="Der Steinwerkdamm",s="Der Steinwerkdamm ist ein kolossales Meisterwerk der Zwergeningenieurskunst am nördlichen Rand von Loch Modan. Er staut die Wasser des Lochs auf, wodurch der gewaltige Hochlandsee entstand, während die darunterliegenden Sumpfland zu bewohnbaren Sümpfen entwässert wurden.",h="Der Steinwerkdamm ist ein kolossales Meisterwerk der Zwergeningenieurskunst am nördlichen Rand von Loch Modan.",kw={"dunkeleisen","franclorn forgewright","hinderweir","loch modan","der steinwerkdamm","der loch","sumpfland"},ang={["profession:Engineering"]="Für Ingenieure jeder Art ist der Damm ein Meisterwerk hydraulischer Kontrolle und tragender Stonewrought-Mechanik, das selbst den großen Bauwerken unter Eisenschmiede in nichts nachsteht.",["race:Dwarf"]="Der Damm steht als Monument uralter zwergischer Maurerkunst und architektonischen Scharfsinns, wenngleich sein Dunkeleisen-Erbe unter den Historikern von Eisenschmiede ein heikler und umstrittener Punkt bleibt."},sec={{t="Ein Wunderwerk zwergischer Handwerkskunst",b="Über die Schlucht östlich von Dun Algaz gespannt, gilt der Steinwerkdamm weithin als einer der größten baulichen Triumphe der Zwergenzivilisation. Entworfen vom meisterhaften Dunkeleiseningenieur Franclorn Forgewright, wurde das Bauwerk mithilfe seiner bahnbrechenden Stonewrought-Technik errichtet. Durch das Aufstauen der Gewässer des Gebirgsbeckens verdoppelte der Damm die Oberfläche des Lochs und senkte gleichzeitig stetig den Wasserstand im Norden, wodurch das sumpfige Becken der Sumpfland aus einem einst vollständig überfluteten Tal hervorgehen konnte."},{t="Sabotage und Verteidigung",b="Obwohl er unter der Leitung eines Dunkeleisenarchitekten erbaut wurde, dient der Damm heute Eisenschmiede – und ist zu einem vorrangigen Ziel für Saboteure der Dunkeleisenzwerge geworden, die von den südlichen Bergen aus operieren. Jüngste Angriffe und Infiltrationsversuche haben Eisenschmiede dazu gezwungen, hier eine Garnison unter Chefingenieur Hinderweir VII. zu stationieren. Wachen und Ingenieure patrouillieren Tag und Nacht auf dem Mauerwerk, wohl wissend, dass jeder Bruch den Loch katastrophal entleeren und eine verheerende Flut über die darunterliegenden Sumpfland entfesseln würde."}},faq={{q="Wer hat den Steinwerkdamm erbaut?",a="Er wurde vom berühmten Dunkeleisenarchitekten Franclorn Forgewright entworfen und überwacht, der die Stonewrought-Bautechnik erfand. Obwohl er von einem Dunkeleisenmeister erbaut wurde, dient er heute dem Königreich der Bronzebeards.",al={"wer erbaute den stonewroughtdamm","schöpfer des damms","damm architekt"}},{q="Was passiert, wenn der Damm bricht?",a="Ein Einsturz wäre katastrophal. Der Loch würde rasch ablaufen und Loch Modan als leeren Schlammkrater zurücklassen, während die verdrängten Wassermassen als unkontrollierbare, verheerende Flutwelle in die Sumpfland hinabstürzen würden.",al={"wenn der damm bricht","was passiert wenn der damm bricht","damm zerstört"}},{q="Warum greifen die Dunkeleisenzwerge ihn an?",a="Der Dunkeleisenklan versucht, die lebenswichtige Infrastruktur von Eisenschmiede zu treffen und die Region zu destabilisieren. Die Zerstörung des Damms würde die Nachschublinien lahmlegen, die nördlichen Feuchtgebiete ertränken und dem Stolz der Bronzebeards einen bitteren Schlag versetzen.",al={"warum damm angreifen","dunkeleisen dammangriff"}},{q="Wer leitet derzeit die Verteidigung des Damms?",a="Chefingenieur Hinderweir VII. leitet den täglichen Betrieb und die Verteidigungsanlagen des Damms und stimmt sich mit den Truppen von Eisenschmiede ab, um Saboteure aufzuspüren.",al={"wer leitet den damm","damm ingenieur"}}},fx={["721eb9b8"]={q="Was ist der Steinwerkdamm?",a="Der Steinwerkdamm ist ein kolossales zwergisches Wunderwerk, das am nördlichen Rand von Loch Modan positioniert ist, gleich östlich des Dun Algaz-Passes. Er hält das riesige Loch zurück, vergrößert es dramatisch und reguliert gleichzeitig die Wasserwege, die in das Sumpfland unterhalb hinabfließen. Als eines der größten architektonischen Wunder der Welt bekannt, steht er als bleibendes Monument antiker zwergischer Ingenieurskunst.",al={"was ist der steinwerkdamm","über den steinwerkdamm","lore steinwerkdamm"}},b3d97da7={q="Was ist die Geschichte des Steinwerkdamms?",a="Der Damm wurde von Franclorn Forgewright konzipiert und beaufsichtigt, einem brillanten Dunkeleisenzwergen-Architekten, der bahnbrechende Bautechniken entwickelte, bevor sein Clan in den Schatten fiel. Sein großartiger Entwurf verdoppelte das Volumen von Loch Modan und half dabei, das sumpfige Becken des Sumpflands trockenzulegen. Obwohl er vor langer Zeit in einer Zeit der Einheit erbaut wurde, ist er kürzlich zu einer Front in einem erbitterten Konflikt geworden, da Saboteure der Dunkeleisenzwerge versuchen, ihn zu zerstören.",al={"geschichte steinwerkdamm","geschichte des damms","was geschah am steinwerkdamm"}},a124034a={q="Ist der Steinwerkdamm gefährlich?",a="Das Bauwerk selbst ist solide und stabil, aber die Gegend wimmelt vor Gefahr. Dunkeleisenzwergen-Infiltratoren und Saboteure schleichen um seine Flanken und Tunnel herum, bewaffnet mit Sprengstoff und dunkler Magie in der Hoffnung, die Mauern zu durchbrechen. Die Streitkräfte der Allianz und Wachen von Eisenschmiede sind weit verstreut, um ständige Sabotageversuche abzuwehren, was Reisen um den Rand herum für unvorbereitete Wanderer gefährlich macht.",al={"steinwerkdamm gefährlich","ist der damm sicher","bedrohungen am steinwerkdamm"}},e9d9cbd5={q="Warum heißt es Steinwerkdamm?",a="Der Damm hat seinen Namen von der „steinwerk“-Baumethode, einer fortschrittlichen Technik der zwergischen Mauerwerkskunst und Architektur, die von seinem Chefbaumeister, Franclorn Forgewright, erfunden wurde. Die Präzision und Widerstandsfähigkeit dieses Stils ermöglichte es der massiven Mauer, über Generationen hinweg enormem Wasserdruck standzuhalten.",al={"warum heißt es steinwerkdamm","namensbedeutung steinwerkdamm","ursprung des namens steinwerk"}}},fp="16,239,25.518.0,20.490.0,31.218.0,31.209.0,39.225.0,48.162.0"}
P.entries["subzone:stonewrought-pass"] = {n="Steinwerkpass",s="Der Steinwerkpass ist ein unterirdischer Tunnel, der direkt durch die südlichen Berge von Loch Modan in die verheerte Weite der Sengenden Schlucht geschlagen wurde. Meisterhaft konstruiert vom berühmten Architekten Franclorn Forgewright, verbindet dieser Durchgang das Tal der Könige direkt mit dem Staubfeuertal. Schwere Eisentore sichern beide Enden, um die friedlichen Länder der Zwerge vor den vulkanischen Schrecken des Südens zu schützen.",h="Der Steinwerkpass ist ein unterirdischer Tunnel, der direkt durch die südlichen Berge von Loch Modan in die...",kw={"staubfeuertal","franclorn forgewright","loch modan","pebblebitty","sengende schlucht","stonewroughtpass","tal der könige"},ang={["faction:Alliance"]="Dieser von den zwergischen Gebirgsjägern bewachte, verschlossene Durchgang schützt die verwundbaren Siedlungen in Loch Modan vor den vulkanischen Bedrohungen, die in der Sengenden Schlucht schwelen.",["race:Dwarf"]="Der Tunnel steht als Zeugnis für die ingenieurtechnische Brillanz von Franclorn Forgewright, wenngleich er nun an das düstere, eroberte Gebiet Eurer abtrünnigen Dunkeleisen-Verwandten grenzt."},sec={{t="Ein Torweg, in Stein gehauen",b="Aus dem Grundgestein geschlagen vom legendären Baumeister Franclorn Forgewright – der auch für den gewaltigen Steinwerkdamm berühmt ist –, dient der Steinwerkpass als direkter Korridor zwischen der idyllischen Schönheit von Loch Modan und den versengten Einöden der Sengenden Schlucht. Er tritt in Loch Modan nahe dem kolossalen Tal der Könige hervor und schneidet geradewegs durch den Gebirgszug hinunter in das Staubfeuertal. Da die Sengende Schlucht von Dunkeleisenzwergen und feurigen Bestien wimmelt, halten die Gebirgsjäger von Eisenschmiede den Durchgang hinter schweren Toren fest verschlossen, um zu verhindern, dass die Gefahr nach Norden überschwappt."}},faq={{q="Wohin führt der Steinwerkpass?",a="Der Pass schneidet direkt durch die Gebirgskette und verbindet das Tal der Könige am südlichen Rand von Loch Modan mit dem Staubfeuertal in den nördlichen Ausläufern der Sengenden Schlucht.",al={"wohin führt der stonewroughtpass","tunnelverbindung","sengende schlucht nach loch modan"}},{q="Wer hat diesen Tunnel entworfen?",a="Er wurde vom zwergischen Baumeister Franclorn Forgewright entworfen, dem legendären Handwerker, der in ganz Khaz Modan für den Entwurf des Steinwerkdamms und anderer monumentaler Steinbauwerke gefeiert wird.",al={"wer erbaute den stonewroughtpass","architekt des passes","franclorn forgewright tunnel"}},{q="Warum sind die Tore verschlossen?",a="Die Tore sind auf beiden Seiten schwer verriegelt, um die feurigen Monster und feindseligen Dunkeleisenzwerge der Sengenden Schlucht daran zu hindern, in die bewohnten Länder von Loch Modan einzufallen. Gebirgsjägerin Pebblebitty bewacht den Eingang in Loch Modan und verlangt eine Genehmigung, bevor sie Durchlass gewährt.",al={"verschlossenes tor","warum ist der pass verschlossen","wie man das tor öffnet"}}},fp="17,396,25.591.0,38.181.0,25.190.0,25.272.0"}
P.entries["subzone:stormwind-city"] = {n="Sturmwind",s="Sturmwind ist die majestätische Hauptstadt des Königreichs Sturmwind und das militärische sowie politische Herz der Allianz. Nach seiner Zerstörung im Ersten Krieg aus der Asche wiederaufgebaut, steht es nach dem Fall der nördlichen Königreiche als größte verbliebene Bastion menschlicher Macht auf Azeroth da.",h="Sturmwind ist die majestätische Hauptstadt des Königreichs Sturmwind und das militärische sowie politische...",kw={"allianz","anduin","bolvar","elwynn","erster krieg","steinmetze","sturmwind","wrynn"},ang={["faction:Alliance"]="Sturmwind ist der wichtigste militärische, maritime und spirituelle Sammelpunkt für die Allianz in den südlichen Östlichen Königreichen und heißt Zwerge, Gnome sowie Gesandte der Nachtelfen gleichermaßen willkommen.",["race:Human"]="Für Menschen auf ganz Azeroth stehen die weißen Mauern von Sturmwind für Beständigkeit, Überleben und den fortdauernden Ruhm der Menschheit nach dem vollkommenen Verlust der nördlichen Königreiche."},sec={{t="Ein wiederaufgebautes Leuchtfeuer",b="Vor über einem Jahrtausend von nach Süden wandernden Nachkommen der Arathi gegründet, florierte Sturmwind als lebendige Küstenhauptstadt, umgeben von steinernen Wehrmauern und angetrieben von reißenden Flussmühlen. Diese Erhabenheit endete im Ersten Krieg, als die Orcische Horde die Stadt belagerte, ihre Verteidigung durchbrach und sie dem Erdboden gleichmachte, was Sir Anduin Lothar dazu zwang, die überlebenden Flüchtlinge über das große Meer nach Lordaeron zu führen. Nach dem Sieg der Allianz im Zweiten Krieg übernahm die Stonemasons' Guild die monumentale Aufgabe, die Hauptstadt als jene glänzende Festung aus weißem Stein, Kanalnetzen und hoch aufragenden Türmen wiederaufzubauen, die heute nördlich vom Wald von Elwynn steht."},{t="Das Herz der Allianz",b="Da Lordaeron von der Geißel zerschlagen und Dalaran während des Dritten Krieges schwer verwüstet wurde, dient Sturmwind als primäre Zuflucht und Festung der Menschheit. Seine breiten Alleen und Wehrmauern werden von der disziplinierten Stadtwache von Sturmwind patrouilliert, während die Türme der Kathedrale des Lichts den Glauben und die Hingabe in den südlichen Königreichen leiten. Doch unter den geordneten Vierteln und feierlichen Toren brodelt stiller politischer Aufruhr: König Varian Wrynn ist auf mysteriöse Weise verschwunden und hinterließ seinen jungen Sohn Anduin auf dem Thron unter der Regentschaft von Hochlord Bolvar Fordragon und dem geflüsterten Rat der königlichen Beraterin Lady Katrana Prestor."}},faq={{q="Warum wurde Sturmwind nach dem Ersten Krieg wiederaufgebaut?",a="Sturmwind wurde während des Ersten Krieges von der Orcischen Horde geplündert und niedergebrannt. Nachdem die Große Allianz von Lordaeron die Orcs im Zweiten Krieg besiegt hatte, forderten menschliche Flüchtlinge ihr angestammtes Königreich zurück. Der königliche Hof beauftragte die Stonemasons' Guild damit, auf den ursprünglichen Ruinen eine neue, noch prachtvollere Festungsstadt zu errichten.",al={"wer baute sturmwind wieder auf","wiederaufbau von sturmwind","warum sieht sturmwind neu aus"}},{q="Wer regiert Sturmwind derzeit?",a="Nominell sitzt der Knabenkönig Anduin Wrynn nach dem plötzlichen und ungeklärten Verschwinden seines Vaters, König Varian Wrynn, auf dem Thron. Aufgrund von Anduins Jugend liegt die eigentliche Regierungsgewalt bei Hochlord Bolvar Fordragon, der als Regent und Kommandant der Verteidigung des Königreichs fungiert.",al={"wer ist könig von sturmwind","wer regiert sturmwind","aktueller herrscher von sturmwind"}},{q="Warum ist Sturmwind die menschliche Haupthauptstadt anstelle von Lordaeron?",a="Während des Dritten Krieges wurde das nördliche Königreich Lordaeron durch die Seuche der Untoten und die Geißel von innen heraus völlig dezimiert. Da Lordaeron zerstört und andere nördliche Reiche der Menschen verwüstet sind, bleibt Sturmwind das wohlhabendste, intakteste und bevölkerungsreichste Menschenkönigreich, das auf Azeroth noch fortbesteht.",al={"was geschah mit lordaeron","warum nicht lordaeron als hauptstadt","ist sturmwind die letzte stadt"}},{q="Welche Streitkräfte beschützen die Stadt?",a="Der Frieden in den Stadtbezirken und auf den Zinnen wird von der Stadtwache von Sturmwind gewahrt. Die weitergehende territoriale Verteidigung und der königliche Schutz obliegen den Rittern des Königreichs, den stationierten Soldaten von Burg Sturmwind und den Paladinen, die der Church of the Light angehören.",al={"wer bewacht sturmwind","armee von sturmwind","stadtwachen"}}},fx={["209accb7"]={q="Was ist Sturmwind?",a="Sturmwind ist die Hauptstadt des Königreichs Sturmwind und die größte verbliebene menschliche Bastion auf Azeroth. Nördlich des Waldes von Elwynn entlang der Westküste gelegen, steht sie als das schlagende Herz der Allianz. Hinter ihren hoch aufragenden weißen Steinmauern und tiefen Canals liegen blühende Händlerviertel, der Sitz der Krone und die Kathedrale des Lichts, ein Leuchtfeuer des Glaubens für alle, die das Heilige Licht verehren.",al={"was ist sturmwind","übersicht sturmwind","über sturmwind"}},["38604972"]={q="Was geschah in Sturmwind?",a="Gegründet vor über einem Jahrtausend von Nachfahren der Arathi, überstand Sturmwind Gnollkriege und Trollangriffe, bevor es im Ersten Krieg völlig verwüstet wurde. Die Orcische Horde belagerte die Hauptstadt, durchbrach ihre Verteidigung und machte sie dem Erdboden gleich, was die Überlebenden dazu zwang, nach Norden über das Meer zu fliehen. Nachdem die Allianz im Zweiten Krieg triumphierte, baute die Steinmetzgilde die Stadt mühsam wieder zu der majestätischen Festung auf, die dort heute steht.",al={"geschichte sturmwind","was geschah mit sturmwind","fall von sturmwind"}}},fp="14,298,16.651.0,21.636.0,46.327.0,35.292.0,61.301.0,38.284.0"}
P.entries["subzone:stormwind-gate"] = {n="Tor von Sturmwind",s="Das Tor von Sturmwind ist der monumentale, befestigte Eingang, der den Wald von Elwynn mit Sturmwind verbindet. Von königlichen Schildwachen unablässig bewacht, bildet diese Schwelle die wichtigste Grenze zwischen den friedvollen Wäldern und dem erhabenen Tal der Helden.",h="Das Tor von Sturmwind ist der monumentale, befestigte Eingang, der den Wald von Elwynn mit Sturmwind...",kw={"wald von elwynn","goldhain","stormwind city guard","tor von sturmwind","das tal der helden"},ang={["faction:Alliance"]="Das Tor verkörpert die Sicherheit und Beständigkeit der Großen Allianz und gewährt reisenden Soldaten sowie jungen Abenteurern den ersten Blick auf ihre Pracht.",["race:Human"]="Für das Volk von Sturmwind bedeutet die Rückkehr durch diese Steinbögen die Heimkehr in die Sicherheit nach langen Reisen durch Elwynn und darüber hinaus."},sec={{t="Die Schwelle des Königreichs",b="Über der südlichen Straße des Walds von Elwynn aufragend, dient das Tor von Sturmwind sowohl als Verteidigungsbollwerk als auch als zeremonieller Eingang zur Hauptstadt. Schildwachen der Stadtwache von Sturmwind halten am steinernen Portal ununterbrochen Wache und sichern die Zugänge aus dem Wald, während regelmäßige Patrouillen zwischen dem äußeren Bogen und dem Tal der Helden marschieren. Trotz anhaltender Unruhen in ganz Elwynn stehen die gewaltigen Tore aus Eisen und Stein weit offen, um Reisende, Händler und heimkehrende Verteidiger im Herzen der Allianz willkommen zu heißen."}},faq={{q="Wohin führt das Tor von Sturmwind?",a="Durchschreitet Ihr das Tor aus dem Wald von Elwynn, gelangt Ihr direkt in das Tal der Helden, den prachtvollen Eingang nach Sturmwind, der von aufragenden Monumenten des Zweiten Krieges gesäumt ist.",al={"wohin führt tor von sturmwind","was liegt hinter dem tor","sturmwind eingang"}},{q="Warum steht das Tor offen, wenn der Wald von Elwynn gefährlich ist?",a="Sturmwind lebt von offenem Handel und regem Reiseverkehr aus Goldhain und dem gesamten Gebiet der Allianz. Obwohl Banditentum und Aktivitäten der Defias die umliegenden Wälder plagen, hält die Stadt die Passage lieber mit wachsamen Wachen besetzt, anstatt ihre eigenen Bürger und den Handel auszusperren.",al={"warum sind die tore offen","ist tor von sturmwind geschlossen","warum offen"}},{q="Wer bewacht die Tore?",a="Der Eingangsbereich wird von der Stadtwache von Sturmwind bemannt. Zwei Schildwachen halten unmittelbar davor im Wald von Elwynn Wache, zwei weitere sichern den inneren Durchgang, und bewaffnete Fußsoldaten patrouillieren auf der Brücke, die durch das Tal der Helden führt.",al={"tor von sturmwind wachen","wer verteidigt das tor"}},{q="Werden am Tor besondere Ereignisse abgehalten?",a="Ja. Auf dem freien Gelände rund um das Tor von Sturmwind finden häufig große stadtweite Feiertage und saisonale Versammlungen der Allianz statt, da es als offener Sammelplatz außerhalb der überfüllten Viertel dient.",al={"feiertage am tor von sturmwind","ereignisse am tor"}}},fx={c23a16f5={q="Ist das Tor von Sturmwind gefährlich?",a="Nicht für Mitglieder der Allianz. Das Tor wird schwer bewacht, da die Stadtwache von Sturmwind beide Seiten der Schwelle sowie das angrenzende Das Tal der Helden patrouilliert. Feindliche Infiltratoren oder Reisende der Horde werden es jedoch für nahezu unmöglich halten, es zu durchbrechen, da die stationierten Wachen jeden erklärten Feind der Krone beim Anblick sofort angreifen.",al={"ist das tor sicher","gefahr am tor von sturmwind","ist das tor von sturmwind sicher"}}},fp="14,246,28.536.0,35.176.0,56.267.0,21.226.0,42.193.0"}
P.entries["subzone:stormwind-keep"] = {n="Burg Sturmwind",s="Burg Sturmwind thront hoch über der Hauptstadt als steinerne Festung und Machtsitz des Königreichs Sturmwind. Nach seiner Zerstörung im Ersten Krieg wiederaufgebaut, beherbergt es derzeit den königlichen Hof des jungen Knabenkönigs Anduin Wrynn und seines Regenten, Hochlord Bolvar Fordragon.",h="Burg Sturmwind thront hoch über der Hauptstadt als steinerne Festung und Machtsitz des Königreichs Sturmwind.",kw={"anduin wrynn","bolvar fordragon","burg sturmwind","katrana prestor","royal library","thronsaal","war room"},ang={["faction:Alliance"]="Die Festung ist das Herzstück des östlichen Militärkommandos der Allianz, von wo aus Bolvar Fordragon und die Marschälle die Verteidigung gegen aufkeimende Bedrohungen in ganz Elwynn, Westfall und darüber hinaus koordinieren.",["race:Human"]="Aus der Asche der Verwüstung des Ersten Krieges auferstanden, steht die Festung als Zeugnis für die Widerstandskraft und den Stolz des Volkes von Sturmwind."},sec={{t="Die wiederaufgebaute Zitadelle",b="Auf einem Plateau gelegen, das die gesamte Stadt überblickt, dient Burg Sturmwind sowohl als Palast als auch als militärische Bastion. Die ursprüngliche Festung wurde von der Alten Horde dem Erdboden gleichgemacht, als König Llane gegen Ende des Ersten Krieges ermordet wurde. Nachdem die Allianz das Königreich zurückerobert hatte, wurde die rekonstruierte Festung auf den alten Fundamenten neu errichtet und beherbergt heute nicht nur den großen Thronsaal und den War Room, sondern auch friedliche Gartenhöfe und die weitläufige Royal Library."},{t="Ein gespaltener Hofstaat",b="Hinter den Bannern und dem polierten Stein der Festung verbirgt sich ein brüchiger Friede. Da König Varian Wrynn auf dem Weg zu einem diplomatischen Gipfeltreffen in Theramore auf mysteriöse Weise verschwunden ist, liegt die Regentschaft in den Händen des zehnjährigen Königs Anduin Wrynn. Die tatsächliche Herrschaft obliegt Hochlord Bolvar Fordragon und der adeligen Lady Katrana Prestor. Während Bolvar die Verteidigung und militärische Angelegenheiten leitet, wird die Hofpolitik durch aristokratische Machtkämpfe gelähmt, was die abgelegenen Gebiete schutzlos und die Krone zutiefst abgelenkt zurücklässt."}},faq={{q="Wer regiert derzeit in Burg Sturmwind?",a="König Anduin Wrynn sitzt zwar formell auf dem Thron, doch da er erst zehn Jahre alt ist, regiert Hochlord Bolvar Fordragon als Regent an der Seite von Lady Katrana Prestor als königlicher Beraterin.",al={"wer hat das sagen","wer führt sturmwind an","wer ist der könig"}},{q="Was geschah mit König Varian Wrynn?",a="König Varian verschwand unter mysteriösen Umständen, als er über das Meer zu einer Friedenskonferenz in Theramore reiste. Sein plötzliches Verschwinden hinterließ einen verwaisten Thron, was Bolvar und den Hofstaat dazu zwang, den jungen Anduin zu krönen, um politische Stabilität zu wahren.",al={"wo ist varian","varian verschwunden","was geschah mit dem könig"}},{q="Wurde die Festung im Ersten Krieg zerstört?",a="Ja. Nach der Ermordung von König Llane Wrynn durch Garona überrannte die Alte Horde die Stadt und machte die Festung dem Erdboden gleich. Die heutige Festung wurde auf den alten Fundamenten neu errichtet, nachdem die Allianz im Zweiten Krieg siegreich geblieben war.",al={"haben die orcs die festung zerstört","zerstörung der festung erster krieg"}},{q="Welche bedeutenden Flügel können innerhalb der Festung betreten werden?",a="Der Komplex umfasst den Hauptthronsaal, den direkt dahinter liegenden War Room, die Petitioner's Chamber für vorsprechende Bittsteller, einen offenen Gartenhof, die Royal Gallery und die Royal Library.",al={"räume der festung","was befindet sich in der festung","flügel von burg sturmwind"}}},fx={["3e1bbfc4"]={q="Was ist Burg Sturmwind?",a="Burg Sturmwind ist die majestätische Festung und der Machtsitz des menschlichen Königreichs Sturmwind. Die Festung überblickt die gesamte Stadt und dient sowohl als königlicher Palast als auch als Herz der Regierung des Reiches. Innerhalb ihrer befestigten Steinmauern findet Ihr den königlichen Hof, den Thronsaal, Audienzkammern für Bittsteller, die Royal Library und friedliche Innengärten, neben Kasernen für die persönliche Elitegarde der Burg.",al={"was ist burg sturmwind","zweck von burg sturmwind","über burg sturmwind"}},a781e02c={q="Ist Burg Sturmwind gefährlich?",a="Für loyale Untertanen und Verbündete der Allianz ist Burg Sturmwind eines der sichersten Refugien der Welt. Schwer garnisoniert von königlichen Elitegarden und Beschützern der Krone, wacht sie wachsam gegen Bedrohungen von außen. Doch unter der Oberfläche des friedlichen Hoflebens liegen subtile politische Intrigen, bei denen adlige Fraktionen und königliche Berater um Einfluss auf den jungen König ringen, während das Königreich mit wachsenden Unruhen im gesamten Reich zu kämpfen hat.",al={"ist burg sturmwind gefährlich","ist burg sturmwind sicher","ist die burg feindselig"}}},fp="14,269,19.466.0,15.482.1,38.178.0,35.249.0,40.232.0,48.194.0"}
P.entries["subzone:stormwind-stockade"] = {fx={e9dc0ba3={q="Was ist das Stormwind Stockade?",a="Das Verlies ist ein hochgesicherter unterirdischer Gefängniskomplex, der unter den Canals von Sturmwind in den Fels gehauen wurde. Unter der Leitung von Aufseher Thelwasser wurde es errichtet, um die gefährlichsten Kriminellen des Königreichs unterzubringen, darunter Mörder, politische Aufständische, Defias-Banditen und feindliche Ausländer, die auf ihr Urteil warten.",al={"was ist das verlies","informationen zum stormwind stockade"}},d734f0f2={q="Was ist im Stormwind Stockade geschehen?",a="Ein gewaltsamer, von Gefangenen angeführter Aufstand brach innerhalb des Komplexes aus, orchestriert von dem gefangenen Defias-Drahtzieher Bazil Thredd. Die randalierenden Insassen überwältigten ihre Kerkermeister, drängten die Wachen vollständig aus den Zellentrakten und übernahmen die Kontrolle über die Einrichtung. Die Stadtwache hält die Krise nun geheim, während sie Mercenaries rekrutiert, um das Gefängnis zurückzuerobern.",al={"was geschah im verlies","geschichte des verlieses","warum gibt es einen aufstand im verlies"}},["10925a1c"]={q="Ist das Stormwind Stockade gefährlich?",a="Es ist derzeit extrem gefährlich. Die Insassen bewegen sich ohne Aufsicht frei in den Hallen, bewaffnet und organisiert unter der Führung der Defias, zusammen mit Halsabschneidern, Schwarzfelsorcs und Dunkeleisenzwergen-Infiltratoren. Jeder, der das Gefängnis betritt, muss sich seinen Weg durch gesetzlose, feindselige Korridore kämpfen, in denen die Wachen keinerlei Kontrolle mehr haben.",al={"wie gefährlich ist das verlies","ist das verlies gefährlich","gefahr im verlies"}}}}
P.entries["subzone:stormwind-stockade-classic"] = {n="Das Verlies",s="Das Verlies von Sturmwind ist ein befestigtes unterirdisches Gefängnis unter dem Kanalviertel von Sturmwind. Ursprünglich erbaut, um Kleinkriminelle, gewalttätige Söldner und politische Aufrührer festzuhalten, ist es vor Kurzem nach einer gewaltsamen Insassenrevolte im Chaos versunken.",h="Das Verlies von Sturmwind ist ein befestigtes unterirdisches Gefängnis unter dem Kanalviertel von Sturmwind.",kw={"bazil thredd","defias","dextren ward","kam tiefenzorn","gefängnis","das verlies","verlies von sturmwind","targorr der schreckliche","aufstand","aufseher thelwasser"},ang={["faction:Alliance"]="Der Aufstand direkt unter den Straßen der Hauptstadt ist eine bittere Demütigung für die Regierung von Hochlord Bolvar Fordragon und zeigt, wie verwundbar Sturmwind von innen heraus ist, während der König abwesend bleibt.",["race:Human"]="Für die Menschen der umliegenden Städte beweist das Versagen des Verlieses, dass dem Adelshaus der bürokratische Papierkram in der Hauptstadt weitaus wichtiger ist als der Schutz der Grenzsiedlungen vor Mördern."},sec={{t="Ein Gefängnis in Aufruhr",b="Verborgen an den Kanälen zwischen der Altstadt und dem Magierviertel dient das Verlies als wichtigste Strafanstalt des Königreichs Sturmwind. Unter der Leitung von Aufseher Thelwasser beherbergt der unterirdische Komplex eine Ansammlung der gefährlichsten Übeltäter des Reiches: Halsabschneider der Bruderschaft der Defias, einen marodierenden Schwarzfelsorc, einen Oger und sogar einen infiltrierenden Dunkeleisenzwerg. Kürzlich überwältigte ein koordinierter Gefängnisaufstand, eingefädelt von dem gerissenen Schwerverbrecher Bazil Thredd, die Garnison, vertrieb die überlebenden Wachen und überließ den Verurteilten die vollständige Kontrolle über die inneren Hallen."},{t="Bürokratie und Vergeltung",b="Die Katastrophe im Verlies offenbart tiefe Risse in Sturmwinds Verwaltung. Mehrere berüchtigte Insassen, wie der Schwarzfelsschrecken Targorr der Schreckliche und der Leichen verkaufende Grabräuber Dextren Ward, waren längst zum Tode verurteilt, wurden jedoch durch endlose, von einflussreichen Adligen erwirkte Hinrichtungsaufschübe am Leben gehalten. Frustriert über die aristokratische Verzögerungstaktik haben benachbarte Siedlungen wie Seenhain und Dunkelhain zusammen mit der Zwergengarnison in Dun Modr die königlichen Instanzen völlig umgangen und unabhängige Abenteurer angeworben, um inmitten des Chaos hineinzumarschieren und die wichtigsten Rädelsführer hinzurichten."}},faq={{q="Wo befindet sich das Verlies?",a="Der Eingang zum Verlies liegt innerhalb von Sturmwind am nördlichen Kanalufer und verbindet den Durchgang zwischen der Altstadt sowie dem Kathedralen- und dem Magierbezirk.",al={"eingang zum verlies","weg zum verlies","verlies standort"}},{q="Wer leitet das Gefängnis derzeit?",a="Obwohl Aufseher Thelwasser der offizielle Vorsteher ist, wurde er während des Aufstands vertrieben. Die Anlage befindet sich derzeit de facto unter der Kontrolle des Gefangenen, der den Aufstand angezettelt hat: Bazil Thredd, zusammen mit verbündeten Defias-Randalierern.",al={"wer leitet das verlies","verlies boss","bazil thredd"}},{q="Warum sind Orcs und Dunkeleisenzwerge in Sturmwind eingesperrt?",a="Sturmwind hält hier hochrangige Kriegsgefangene und Saboteure fest. Targorr der Schreckliche ist ein gefangengenommener Räuber der Schwarzfelsorcs aus den nahegelegenen Bergen, während Kam Tiefenzorn ein feindseliger Dunkeleisenzwerg ist, der wegen Subversion gegen die Allianz inhaftiert wurde.",al={"warum sind orcs im verlies","kam tiefenzorn","targorr der schreckliche"}},{q="Warum wurden verurteilte Mörder am Leben gelassen, anstatt hingerichtet zu werden?",a="Bürokratie und politische Einmischung hochrangiger Adliger aus Sturmwind verzögerten die Hinrichtungen von Verurteilten wie Dextren Ward und Targorr immer wieder, was in den Außengebieten wie dem Rotkammgebirge und dem Dämmerwald für Empörung sorgte.",al={"warum wurden sie nicht hingerichtet","adlige von sturmwind","dextren ward hinrichtung"}}},fx={d4f3da71={q="Was ist Das Verlies von Sturmwind?",a="Das Verlies ist ein schwer bewachter Hochsicherheitsgefängniskomplex unter dem Kanalviertel von Sturmwind. Unter der Autorität von Aufseher Thelwasser sollte es die schlimmsten Straftäter des Reiches wegsperren – von kleinen Straßendieben und Grabräubern bis hin zu politischen Aufständischen, Verschwörern der Defias und skrupellosen Mördern.",al={"was ist das verlies","verlies sturmwind","erkläre das verlies"}},["5c482541"]={q="Was ist im Verlies von Sturmwind geschehen?",a="Kürzlich brach ein gewalttätiger Gefangenenaufstand im Inneren der Zellen aus, angeführt von dem gerissenen Drahtzieher Bazil Thredd. Die randalierenden Insassen überwältigten die Wachen, ermordeten Aufseher und drängten Aufseher Thelwasser hinaus in die Canals. Da die Stadtwache ausgesperrt wurde, übernahmen die Sträflinge die vollständige Kontrolle über den Komplex und verwandelten die unterirdischen Hallen in einen befestigten Zufluchtsort für Halsabschneider und Verschwörer.",al={"was ist hier passiert","geschichte des aufstands im verlies","geschichte des verlieses"}},b72eefeb={q="Ist Das Verlies von Sturmwind gefährlich?",a="Es ist außerordentlich gefährlich. Die engen Steinkorridore wimmeln von befreiten Mördern, Mercenaries der Defias, grausamen Schwarzfelsorks und Eindringlingen der Dunkeleisenzwerge. Zusammengepfercht auf engstem Raum fallen die Insassen jeden gewaltsam an, der das Verlies betritt, und die Gefahr, dass sich feindliche Verstärkungen in die Canals der Stadt ausbreiten, bleibt eine ständige Bedrohung für die Sicherheit von Sturmwind.",al={"wie gefährlich ist das verlies","ist das verlies sicher","gefahr im verlies"}}},fp="28,265,18.586.0,27.590.1,30.162.0,36.231.0,64.239.0,60.218.0"}
P.entries["subzone:stoutlager-inn"] = {n="Gasthof Zum Starkbier-Lager",s="Der Gasthof Zum Starkbier-Lager ist das lebendige Herz von Thelsamar und ein wichtiger Zufluchtsort für Reisende in Loch Modan. Eingebettet unter den sanften Hügeln des Lochs bietet er warme Herde, starkes Zwergenbier und einen geschäftigen Treffpunkt für Abenteurer und Einheimische gleichermaßen.",h="Der Gasthof Zum Starkbier-Lager ist das lebendige Herz von Thelsamar und ein wichtiger Zufluchtsort für...",kw={"zwerg","ruhestein","gastwirt","loch modan","gasthof zum starkbier-lager","taverne","thelsamar"},ang={["faction:Alliance"]="Der Gasthof dient als entscheidender Sammelpunkt und sicherer Hafen für Abenteurer der Allianz, die nach Norden in Richtung Sumpfland ziehen oder in den unruhigen Tälern rund um den Loch patrouillieren.",["race:Dwarf"]="Für die Zwerge der Bronzebeards verkörpert der Gasthof Zum Starkbier-Lager die vertraute Wärme der Heimat, bekannt für echte Gastfreundschaft, frisches Bier und verlässliche Gesellschaft fernab von Eisenschmiede."},sec={{t="Ein einladender Herd in den Hügeln",b="Direkt in der Siedlung Thelsamar gelegen, dient der Gasthof Zum Starkbier-Lager als Zentrum des Gemeinschaftslebens im westlichen Loch Modan. Bergleute, Gebirgsjäger und Reisende, die zwischen Dun Morogh und dem Sumpfland unterwegs sind, kehren hier ein, um Gerüchte auszutauschen, eine Unterkunft zu finden und kräftige Schlucke Zwergengebräu zu teilen. Während die Wildnis jenseits von Thelsamar durch die Aktivitäten von Troggs und Kobolden zunehmend feindseliger wird, bieten die dicken Steinmauern und prasselnden Feuer des Starkbier-Lagers einen verlässlichen Zufluchtsort."}},faq={{q="Welche Dienste werden im Gasthof Zum Starkbier-Lager angeboten?",a="Der Gasthof bietet traditionelle Tavernen-Annehmlichkeiten, darunter einen Gastwirt zum Binden von Ruhesteinen, Betten für müde Reisende und örtliche Händler, die Vorräte und Getränke zur Stärkung auf Reisen durch Loch Modan anbieten.",al={"gasthaus-dienstleistungen","was gibt es im gasthaus","gastwirt von thelsamar"}},{q="Wo befindet sich der Gasthof Zum Starkbier-Lager?",a="Er wurde direkt im Zentrum von Thelsamar erbaut, der wichtigsten Stadt der Allianz im westlichen Loch Modan entlang der Hauptstraße.",al={"lage des gasthauses","wo ist das starkbier-lager","gasthof zum starkbier-lager finden"}},{q="Warum ist der Gasthof für Thelsamar so wichtig?",a="Neben der Bereitstellung von Verpflegung und Unterkunft fungiert der Gasthof Zum Starkbier-Lager als Dorfplatz und Nachrichtenzentrum. Hier schreiben einheimische Gebirgsjäger Kopfgelder aus und Reisende planen Ausflüge in die umliegenden Hügel.",al={"warum es beliebt ist","lore zur taverne in thelsamar"}}},fx={["621b2370"]={q="Was ist der Gasthof Zum Starkbier-Lager?",a="Der Gasthof Zum Starkbier-Lager ist das schlagende Herz von Thelsamar und eine der belebtesten Versammlungshallen im gesamten Loch Modan. Er dient als warme, einladende Zuflucht für müde Reisende, die von den Bergstraßen kommen, und bietet starkes Zwergenbier, warmes Essen und weiche Betten am Herd. Örtliche Bergsteiger, Bergleute und besuchende Abenteurer versammeln sich regelmäßig unter den schweren Holzbalken, um Gerüchte auszutauschen, Ausflüge in die umliegenden Hügel zu planen und gute Gesellschaft fernab der Wildnis zu genießen.",al={"was ist der gasthof zum starkbier-lager","lore gasthof zum starkbier-lager","gasthof in thelsamar"}},["7e615305"]={q="Ist der Gasthof Zum Starkbier-Lager gefährlich?",a="Keineswegs. Der Gasthof Zum Starkbier-Lager ist ein sicheres Refugium inmitten von Thelsamar, das fest von örtlichen Zwergenwachen und vorbeiziehenden Bergsteigern geschützt wird. Während Troggs, Kobolde und feindselige Tierwelt die Ufer und Grate von Loch Modan durchstreifen, bleibt der Gasthof selbst ein friedlicher Zufluchtsort, an dem Ihr Euch ausruhen, zu Atem kommen und Euren Geist an den Herd binden könnt, ohne Angst vor einem Angriff haben zu müssen.",al={"ist der gasthof zum starkbier-lager sicher","gefahr im gasthof zum starkbier-lager","bedrohungen im gasthof in thelsamar"}}},fp="14,255,31.482.0,50.207.0,36.126.0,41.193.0"}
P.entries["subzone:strahnbrad"] = {n="Strahnbrad",s="Strahnbrad ist eine verfallene Menschensiedlung in den nordöstlichen Höhen des Alteracgebirges, nahe der Grenze zu den Westlichen Pestländern. Einst berühmt als Schauplatz der frühen Verteidigung von Prinz Arthas Menethil gegen Überfälle der Schwarzfelsorcs, ist die Stadt seither dem Verfall anheimgefallen und dient dem kriminellen Syndikat als befestigte Hochburg.",h="Strahnbrad ist eine verfallene Menschensiedlung in den nordöstlichen Höhen des Alteracgebirges, nahe der...",kw={"alterac","arthas","blackrock","gol'dir","krusk","lordaeron","strahnbrad","syndikat"},ang={["class:Paladin"]="Über das Kopfsteinpflaster von Strahnbrad zu gehen, ruft die frühen, unbefleckten Tage von Prinz Arthas Menethil und Uther der Lichtbringer in Erinnerung – ein bitteres Mahnmal dafür, wie tief Lordaerons Helden gefallen sind.",["faction:Horde"]="Die Versklavung des Orcs Gol'dir durch das Syndikat macht Strahnbrad zu einem dringlichen Ziel für Streiter der Horde, die gegen menschliche Banditen vorgehen und ihren Artgenossen retten wollen."},sec={{t="Eine Stadt voller Tragödien",b="Ursprünglich ein Besitz des Königreichs Alterac, bevor sie nach dem Zweiten Krieg Lordaeron einverleibt wurde, begann Strahnbrads Unglück am Vorabend des Dritten Krieges. Orcs des Schwarzfelsklans überfielen die Siedlung, um Menschenopfer für die Brennende Legion zu erbeuten, woraufhin Prinz Arthas Menethil und die Ritter der Silbernen Hand zu ihrer Verteidigung ausritten. Obwohl Arthas die Angreifer vertrieb und ihren Sklavenmeister erschlug, zahlte die Stadt einen hohen Blutzoll. Als Lordaeron kurz darauf unter der Geißel zerbrach, wurde Strahnbrad den Elementen überlassen."},{t="Der Griff des Syndikats",b="Heute ist Strahnbrad zu einem entscheidenden Operationszentrum für das Syndikat geworden, jener Organisation vertriebener Alterac-Adliger und Gesetzloser, die planen, ihr gefallenes Reich zurückzufordern. Von menschlichen Schurken und Banditen patrouilliert, dienen das verlassene Rathaus und die Schmiede nun als Verstecke und Aufmarschgebiete. Das Syndikat nutzt die Ruinenstadt zur Lagerung von Vorräten und zur Zwangsarbeit gefangener Sklaven, darunter unglückselige Gefangene wie der Orc Gol'dir, den Späher der Horde aus Tarrens Mühle aktiv zu befreien versuchen."}},faq={{q="Warum ist Strahnbrad historisch von Bedeutung?",a="Strahnbrad war für Prinz Arthas Menethil der Schauplatz des Eröffnungsgefechts des Dritten Krieges. Von Uther der Lichtbringer entsandt, um die Siedlung vor wütenden Schwarzfelsorcs zu schützen, hielt Arthas hier seine erste gefeierte Verteidigung ab, rettete Stadtbewohner und schlug die Orc-Angreifer nieder.",al={"warum ist strahnbrad wichtig","arthas strahnbrad","strahnbrad geschichte"}},{q="Wer kontrolliert Strahnbrad heute?",a="Das Syndikat beherrscht Strahnbrad. Diese menschlichen Banditen, loyal zu den gefallenen Adelsgeschlechtern von Alterac, haben das verfallene Rathaus und die Schmiede befestigt, um sie als primäres Aufmarschgebiet für ihre Ambitionen in den Bergen zu nutzen.",al={"wer besitzt strahnbrad","strahnbrad mobs","wer lebt in strahnbrad"}},{q="Zu welchem Königreich gehörte Strahnbrad ursprünglich?",a="Strahnbrad war vor dem Ersten Krieg ursprünglich Teil des Königreichs Alterac. Nachdem Alterac die Allianz während des Zweiten Krieges verraten hatte, wurde die Stadt in das Herrschaftsgebiet des Königreichs Lordaeron eingegliedert.",al={"ist strahnbrad alterac oder lordaeron","strahnbrad königreich"}},{q="Warum kümmert sich die Horde um diese Stadt?",a="Das Syndikat hat einen Orc namens Gol'dir gefangen genommen und ihn in den Ruinen von Strahnbrad zu brutaler Sklavenarbeit gezwungen. Agenten der Horde aus Tarrens Mühle, angeführt von Krusk, schicken Abenteurer hierher, um die Verteidigung des Syndikats zu durchbrechen und Gol'dir zu befreien.",al={"horde-quests in strahnbrad","krusk strahnbrad","gol'dir strahnbrad"}}},fx={["8ef7b8bc"]={q="Was ist Strahnbrad?",a="Strahnbrad ist eine zerstörte Siedlung in den nordöstlichen Ausläufern des Alteracgebirges, nahe dem Pass zu den Westliche Pestländer. Ursprünglich eine menschliche Stadt, die vom Königreich Alterac an Lordaeron überging, steht sie heute verlassen da; ihre Straßen sind frei von unschuldigem Leben und werden von gefährlichen Gesetzlosen besetzt.",al={"was ist dieser ort","übersicht strahnbrad","erzähl mir von strahnbrad"}},e385b772={q="Warum ist Strahnbrad zerstört und verlassen?",a="Strahnbrad erlitt kurz vor dem Dritter Krieg eine brutale Verwüstung, als abtrünnige Schwarzfelsorcs die Siedlung überfielen, um Opfer für die Brennende Legion zu fangen. Obwohl Prinz Arthas Menethil eintraf, um die Plünderer zu vertreiben, kamen viele Stadtbewohner ums Leben. Nach dem Fall von Lordaeron an die Geißel zerstreute sich die überlebende Bevölkerung oder starb, was die verlassenen Bauwerke dazu verdammt, von Banditen eingenommen zu werden.",al={"warum ist strahnbrad zerstört","wer zerstörte strahnbrad","warum ist strahnbrad eine geisterstadt"}},["37fa5a7f"]={q="Ist ein Besuch in Strahnbrad gefährlich?",a="Ja, Strahnbrad ist sehr gefährlich. Die verlassene Stadt dient als aktive Festung für das Syndikat, ein rücksichtsloses kriminelles Netzwerk aus ehemaligem Adel aus Alterac und Briganten. Sie greifen Eindringlinge sofort an und sind sogar dafür bekannt, Gefangene für Zwangsarbeit zu nehmen, was das Gebiet für jeden einzelnen Reisenden, der durch die Berge zieht, gefährlich macht.",al={"ist strahnbrad sicher","strahnbrad feindselig","gefahren in strahnbrad"}}},fp="10,344,17.552.0,20.482.0,41.275.0,28.226.0,50.207.0,40.243.0"}
P.entries["subzone:stratholme-classic"] = {n="Stratholme (Classic)",s="Stratholme, einst das stolzeste Juwel des nördlichen Lordaeron und die Geburtsstätte der Silbernen Hand, ist heute eine brennende Ruine, die der Geißel als regionale Hauptstadt dient. Gespalten zwischen dem fanatischen Scharlachroten Kreuzzug und Baron Rivendares untoten Legionen, bleibt die verfluchte Stadt in einem endlosen, gewaltsamen Krieg gefangen.",h="Stratholme, einst das stolzeste Juwel des nördlichen Lordaeron und die Geburtsstätte der Silbernen Hand, ist...",kw={"arthas","dathrohan","plaguelands","säuberung","rivendare","silberne hand","schlachthaus","stratholme"},ang={["class:Paladin"]="Die Entweihung von Stratholme trifft Paladine zutiefst; sie ist sowohl die heilige Geburtsstätte der Silbernen Hand als auch der Friedhof, auf dem Arthas Uthers Führung zerschlug.",["faction:Alliance"]="Für die Allianz stellt Stratholme den katastrophalen Fall von Lordaeron dar und erinnert Soldaten sowie Überlebende an den schrecklichen Preis des Dritten Krieges."},sec={{t="Die verfluchte Hauptstadt",b="Vor dem Dritten Krieg war Stratholme das nördliche Kraftzentrum von Lordaeron und die heilige Geburtsstätte der Ritter der Silbernen Hand. Ihr Schicksal wurde besiegelt, als Prinz Arthas die Stadt säuberte und seine eigenen Untertanen abschlachtete, nachdem infiziertes Getreide die Seuche hinter ihre Mauern gebracht hatte. Schwelend und zerstört zurückgelassen, wurde Stratholme von der Geißel beansprucht. Heute dient die Stadt unter der übergeordneten Autorität des Leichnams Kel'Thuzad und dem Feldbefehl von Baron Rivendare als Hauptstützpunkt der untoten Macht in den Plaguelands."},{t="Eine geteilte Kriegsfront",b="Stratholme ist zwischen zwei bösartigen Fraktionen aufgeteilt, die in stetigem Blutvergießen verharren. Im Westen hat der fanatische Scharlachrote Kreuzzug den Crusaders' Square und die Scarlet Bastion befestigt, angeführt von Grand Crusader Saidan Dathrohan. Im Osten liegen die Schlachthäuser und Nekropolen der Geißel, verteidigt von hoch aufragenden Zikkurats und dem Todesritter Baron Rivendare. Jeder, der die Stadt betritt, muss sich durch dieses zermürbende Kreuzfeuer schlagen, umgeben von brennenden Mietskasernen und rastlosen Geistern."}},faq={{q="Warum brennt Stratholme immer noch?",a="Prinz Arthas steckte die Stadt während seiner berüchtigten Säuberung im Dritten Krieg in Brand, um die Ausbreitung der Seuche des Untodes aufzuhalten. Die Feuer sind nie wirklich erloschen, genährt durch dunkle Magie, Nekromantie und den endlosen Häuserkampf zwischen der Geißel und dem Scharlachroten Kreuzzug.",al={"warum brennt stratholme","wer hat stratholme verbrannt","stratholme brennt"}},{q="Wer kontrolliert Stratholme derzeit?",a="Die Kontrolle ist geteilt. Grand Crusader Dathrohan befehligt ein überlebendes Kontingent des Scharlachroten Kreuzzugs, das in der westlichen Bastion verschanzt ist, während der Todesritter Baron Rivendare die östlichen Ruinen für die Geißel unter Kel'Thuzad regiert.",al={"wer herrscht über stratholme","wer hat die macht in stratholme","stratholme anführer"}},{q="Welche historische Bedeutung hat die Stadt für Paladine?",a="Stratholme war die Geburtsstätte des Ordens der Silbernen Hand, wo Archbishop Alonsus Faol einst Uther der Lichtbringer und die ersten Paladine weihte. Ihr Untergang markiert die tiefste Tragödie in der Geschichte des Ordens.",al={"silberne hand stratholme","paladingeschichte stratholme"}},{q="Wie betritt man die von der Geißel kontrollierte Seite der Stadt?",a="Während sich Abenteurer vom Haupttor aus den gesamten Weg freikämpfen können, lässt sich das östliche Geißelviertel auch direkt über den Service Entrance erreichen. Das Betreten durch dieses Hintertor erfordert einen Schlüssel, den Magistrate Barthilas bei sich trägt, wenngleich geübte Schurken, mächtige Dietrich-Schmiedeschlüssel oder Goblinschlägstoff es ebenfalls aufbrechen können.",al={"hintertürschlüssel","service entrance stratholme","wie man zur untotenseite gelangt"}}},fp="20,296,18.522.0,18.475.0,32.278.0,34.232.0,60.223.0,57.327.0"}
P.entries["subzone:stratholme-main-gate"] = {n="Stratholme Main Gate",s="Das Stratholme Main Gate steht als erhabener, brennender Eingang zu Lordaerons nördlicher Metropole in den nordwestlichen Östlichen Pestländern. Es gewährt direkten Zugang durch die verfallenen Avenuen der Stadt in Richtung King's Square und zu den dortigen Befestigungen der Kreuzfahrer.",h="Das Stratholme Main Gate steht als erhabener, brennender Eingang zu Lordaerons nördlicher Metropole in den...",kw={"arthas","östliche pestländer","vordereingang","king's square","main gate","scarlet bastion","geißel","stratholme"},ang={["class:Paladin"]="Vor diesen Toren zu stehen, erfüllt Paladine mit immenser Trauer; hier zerbrach die Silberne Hand, als Arthas den Orden an jenem Tag auflöste, an dem er Stratholme säuberte.",["race:Human"]="Der Haupttorbogen war einst die erhabene Schwelle zu Lordaerons zweitgrößter Hauptstadt, die nun zu einer ascheerstickten Nekropole verkommen ist."},sec={{t="Tor zu einem gefallenen Juwel",b="Stratholme war einst der Stolz des nördlichen Lordaeron, berühmt als Geburtsort des Ordens der Silbernen Hand. Heute markieren seine kolossalen gewölbten Haupttore die Schwelle zu einem endlosen Albtraum. Hier wandte sich Prinz Arthas während des Dritten Krieges gegen seinen Mentor, Uther der Lichtbringer, und säuberte seine eigenen Bürger, bevor die Seuche des Untods sie heimsuchen konnte. Seitdem brennt die Stadt unaufhörlich und wurde zur wichtigsten Festung der Geißel in der Region."},{t="Der scharlachrote Vorstoß",b="Der Weg durch das Haupttor führt geradewegs in die Ruinen von King's Square und Market Row, weiter in Richtung des befestigten Viertels, das als Scarlet Bastion bekannt ist. Eiferer des Scharlachroten Kreuzzugs drangen durch diesen Eingang vor, um die Stadt zurückzuerobern und die Toten zu läutern, wobei sie sich ein Lager in den Trümmern schlugen. Allerdings sehen sich die Kreuzfahrer von überwältigenden untoten Monstrositäten umzingelt und führen einen Zermürbungskrieg, den sie gegen die dunklen Mächte, die Stratholmes Verteidigung lenken, nicht gewinnen können."}},faq={{q="Wohin führt dieses Tor?",a="Das Haupttor ist das erhabene vordere Portal nach Stratholme und öffnet sich direkt zu King's Square und Market Row. Es dient als Hauptroute in Richtung der Scarlet Bastion, dem vom Scharlachroten Kreuzzug umkämpften Viertel.",al={"wohin führt das strat main gate","was ist das stratholme main gate","vordereingang strat"}},{q="Warum brennt die Stadt hinter diesen Toren noch immer?",a="Während des Dritten Krieges säuberte Prinz Arthas die Stadt und steckte sie in Brand, um die Ausbreitung der Seuche des Untods aufzuhalten. Dunkle nekromantische Magie, unheilige Feuer und die zügellose Verderbnis der Geißel halten die zerstörte Stadt seither ohne Unterlass in Schutt und Asche.",al={"warum brennt stratholme","wer hat stratholme verbrannt","feuer in stratholme"}},{q="Was ist der Unterschied zwischen diesem Tor und dem Service Entrance?",a="Beide Eingänge führen in dieselbe riesige zerstörte Stadt, jedoch von entgegengesetzten Seiten. Das Main Gate führt in die Nähe der von den Lebenden und dem Kreuzzug gehaltenen Viertel der Stadt, während der Service Entrance zu den östlichen Straßen führt, die direkt unter der Herrschaft der Schlachthäuser der Geißel und Baron Rivendare stehen.",al={"main gate vs service entrance","welcher strat-eingang","strat-tore"}},{q="Wer kontrolliert das Gebiet unmittelbar hinter dem Main Gate?",a="Die ersten Straßen hinter dem Torbogen werden von schlurfenden Zombies, Ghulen, skelettierten Schrecken und umherwandernden Schemen heimgesucht, während der Scharlachrote Kreuzzug weiter in den Avenuen eine umkämpfte Bastion hält.",al={"wer ist im main gate","welche mobs sind vor strat"}}},fp="20,259,25.472.0,20.494.0,26.214.0,49.258.0,66.289.0,55.203.0"}
P.entries["subzone:stratholme-service-entrance"] = {n="Stratholme Service Entrance",s="Der Stratholme Service Entrance ist ein befestigtes Hintertor am Ostwalltor in den nördlichen Östlichen Pestländern. Er gewährt einen direkten, verdeckten Zugang in das von der Geißel kontrollierte östliche Viertel der brennenden Stadt und umgeht die großen Fronttore.",h="Der Stratholme Service Entrance ist ein befestigtes Hintertor am Ostwalltor in den nördlichen Östlichen...",kw={"hintertür","baron rivendare","östliche pestländer","ostwalltor","elders square","geißel","eingang für dienstboten","stratholme"},ang={["class:Paladin"]="Für Ritter des Lichts führt diese Schwelle direkt in den geschändeten nekromantischen Apparat der Geißel und bietet einen direkten Weg, um Rivendare zu läutern und die gefallene Ehre der heiligen Stadt zurückzufordern.",["class:Rogue"]="Das Diensttor verkörpert die klassische taktische Infiltration und ermöglicht es Abenteurern, befestigte Kampflinien zu umgehen und unbemerkt in die Versorgungsgänge der Stadt zu schlüpfen."},sec={{t="Eine durchbrochene Bastion",b="Während das monumentale Haupttor von Stratholme (Stratholme Main Gate) sich zum King's Square öffnet und einen Weg zur Scarlet Bastion bietet, durchbricht der Stratholme Service Entrance die östliche Befestigung der Stadt am Ostwalltor. Heute führt er direkt in das verdorbene Herz der Metropole: den Elders' Square und die verheerten Pfade, die zu Baron Rivendares Schlachthöfen führen."},{t="Die Redoute der Geißel",b="Der Vorstoß durch das Dienstportal bietet einen kürzeren Weg zu den östlichen Bezirken der Geißel. In den umliegenden Gassen wimmelt es von Gargoyles, Gruftbestien und Kultisten, die die Schreckenszikkurate bewachen. Für die Argentumdämmerung und wagemutige Abenteurer, die den herrschenden Todesritter direkt angreifen wollen, dient dieses verborgene Eisentor als primärer Ausgangspunkt für gezielte Schläge gegen die Befehlshaber des Lichkönigs."}},faq={{q="Wo befindet sich der Stratholme Service Entrance?",a="Der Eingang befindet sich am Ostwalltor entlang der nördlichen Berge der Östlichen Pestländer, östlich der Hauptruinen von Stratholme. Er liegt eingebettet in einem steinernen Torbogen entlang der befestigten Mauer.",al={"eingang für dienstboten standort","wo ist das hintertor","strat seiteneingang karte","wie findet man die strat hintertür"}},{q="Wie unterscheidet sich dieser Eingang vom Stratholme Main Gate?",a="Das Stratholme Main Gate öffnet sich zum King's Square und bietet einen Weg durch die Stadt zur Scarlet Bastion. Der Stratholme Service Entrance öffnet sich nahe dem Elders' Square und ermöglicht einen kürzeren Weg zu den von Untoten gehaltenen östlichen Bezirken und dem Slaughter Square.",al={"hintertür gegen vordertür","eingang für dienstboten unterschied","welcher strat eingang"}},{q="Warum wird er Service Entrance genannt?",a="Es handelt sich um einen hinteren Eingang am Ostwalltor, der den vorderen Zugang zur Stadt umgeht. Seine ursprüngliche städtische Nutzung ist nicht näher angegeben.",al={"warum eingang für dienstboten","lore zum eingang für dienstboten"}},{q="Wer kontrolliert diesen Teil der Stadt?",a="Der Bezirk jenseits des Tores wird fest von der Geißel gehalten, beaufsichtigt von Baron Rivendare und seinen Akolythen, welche die Zikkurate instand halten, die ihre dunkle Magie auf dem Elders' Square verankern.",al={"wer kontrolliert das hintertor","eingang für dienstboten bosse","anführer der untoten-seite"}}},fp="27,253,18.359.0,19.413.0,49.202.0,60.236.0,38.124.0,35.182.0"}
P.entries["subzone:stromgarde-keep"] = {n="Burg Stromgarde",s="Burg Stromgarde ist die gebeutelte, geteilte Hauptstadt des gefallenen Menschenkönigreichs Stromgarde im Arathihochland. Einst als Strom die stolze Wiege der menschlichen Zivilisation, ist die Festung heute zwischen feindseligen Schurken des Syndikats, einfallenden Ogern der Felsfäuste und einem verzweifelten Rest königlicher Verteidiger unter Prinz Galen Trollbane aufgeteilt.",h="Burg Stromgarde ist die gebeutelte, geteilte Hauptstadt des gefallenen Menschenkönigreichs Stromgarde im...",kw={"arathi","arathor","felsfäuste","galen","strom","stromgarde","burg stromgarde","syndikat","thoradin","trollbane"},ang={["faction:Alliance"]="Stromgarde war während des Zweiten Krieges ein Gründungsmitglied der Allianz von Lordaeron. Seine bedrängten Verteidiger verkörpern eine der letzten treuen Hochburgen im Norden, die verzweifelt kämpfen, um der völligen Vernichtung zu entgehen.",["race:Human"]="Stromgarde war das uralte Herz Eures gesamten Volkes, wo sich die ersten Menschenstämme unter Thoradin zusammenschlossen und von den Hochelfen die arkanen Künste erlernten. Mit anzusehen, wie es von Kriminellen und Ogern überrannt wird, ist ein bitterer Anblick."},sec={{t="Die Wiege der Menschheit",b="Lange bevor sie ihren heutigen Namen trug, wurde diese Festung vor fast drei Jahrtausenden als Strom gegründet, die erste Hauptstadt des vereinten Menschenreiches von Arathor unter König Thoradin. Sie diente als Ausgangspunkt für den Sieg der Menschheit gegen die Waldtrolle und war die Geburtsstätte der menschlichen Zauberei, an der hochelfische Magi die ersten hundert menschlichen Zauberwirker unterwiesen. Im Laufe der Jahrhunderte, als jüngere Schwesterkönigreiche wie Dalaran, Lordaeron und Sturmwind aufstiegen und florierten, schwand der Einfluss von Strom. Von der eigensinnigen Trollbane-Dynastie, die zurückblieb, in Stromgarde umbenannt, blieb sie während des gesamten Zweiten Krieges eine stolze Kriegerbastion und bildete den Rückhalt der Allianz von Lordaeron gegen die Horde der Orcs."},{t="Eine zerschlagene Bastion",b="Nach den Verheerungen des Dritten Krieges brach Stromgarde schließlich unter immer neuen Katastrophen und Verrat zusammen. Heute liegt die majestätische Steinstadt in drei kriegführende Sektoren zerbrochen da. Die aristokratischen Verräter des Syndikats halten den prächtigen inneren Bergfried besetzt, während barbarische Oger der Felsfäuste das einstige Heiligtum des Magiertraktes überrannt haben. Im verbleibenden Viertel eingeschlossen, führen Prinz Galen Trollbane und die angeschlagenen Truppen Stromgardes einen zermürbenden, blutigen Krieg an mehreren Fronten, nur um zu verhindern, dass ihre angestammte Heimat vollends in Vergessenheit gerät."}},faq={{q="Wer kontrolliert Burg Stromgarde derzeit?",a="Die Ruinenstadt ist in drei heftig umkämpfte Zonen unterteilt. Das verräterische Syndikat kontrolliert den zentralen inneren Bergfried, einfallende Oger des Felsfaustclans besetzen das zerstörte Magiertraktviertel, und Prinz Galen Trollbane führt aus dem verbleibenden Viertel die überlebenden Reste von Stromgardes Streitkräften an.",al={"wer lebt in stromgarde","wem gehört burg stromgarde","wer ist in stromgarde"}},{q="Was war das Imperium von Arathor?",a="Das Imperium von Arathor war die allererste vereinte Nation der Menschen, vor fast dreitausend Jahren von König Thoradin gegründet. Seine Hauptstadt war Strom, gelegen genau auf dem Grund, auf dem heute Burg Stromgarde steht.",al={"was ist strom","erstes menschenreich","arathor imperium"}},{q="Warum liegt die Stadt in Trümmern?",a="Stromgarde stand während des Zweiten Krieges als mächtige Bastion da, doch nach den chaotischen Nachwehen des Dritten Krieges blieb das Königreich verwundbar und isoliert zurück. Eine Mischung aus innerem Verrat, opportunistischen Angriffen des kriminellen Syndikats und Überfällen der Felsfaust-Oger zerschlug die Verteidigung der Stadt.",al={"warum ist stromgarde zerstört","was geschah mit stromgarde"}},{q="Wer ist Galen Trollbane?",a="Prinz Galen Trollbane ist der königliche Nachkomme und Befehlshaber von Stromgardes überlebenden Truppen. Aus seiner umkämpften Redoute innerhalb der Burg leitet er die verzweifelte Verteidigung sowohl gegen das Syndikat als auch gegen die Oger.",al={"prinz trollbane","wer ist prinz galen"}}},fp="15,342,18.693.0,19.547.0,39.293.0,31.208.0,25.300.0,23.208.0"}
P.entries["subzone:sun-rock-retreat"] = {n="Sonnenfels",s="Sonnenfels ist ein verborgener Zufluchtsort der Horde, der hoch in den zentralen Gipfeln des Steinkrallengebirges südlich des Mirkfallonsees liegt. Vorherrschend von Streitkräften der Tauren und Orcs bevölkert, dient es der Horde als primärer Aufmarschplatz und Versorgungsposten in der Region. Über seinen strategischen Nutzen hinaus ruht die Siedlung auf heiligem Boden, der von den Tauren seit langem wegen seiner tiefen spirituellen Resonanz verehrt wird.",h="Sonnenfels ist ein verborgener Zufluchtsort der Horde, der hoch in den zentralen Gipfeln des...",kw={"an'she","mirkfallonsee","steinkrallengebirge","sonnenfels","tauren","venture company"},ang={["faction:Horde"]="Als zentraler Aufmarschort der Horde im Steinkrallengebirge bietet Sonnenfels einen lebenswichtigen Nachschubposten und Flugknotenpunkt inmitten umkämpfter Gipfel.",["race:Tauren"]="Sonnenfels ist für die Shu'halo mehr als nur ein Außenposten; es ist von An'she gesegneter, heiliger Boden, auf dem Schamanen seit Jahrhunderten im Reich der Geister wandeln."},sec={{t="Ein heiliger Zufluchtsort in den Gipfeln",b="In einem Bergkessel südlich des Mirkfallonsees verborgen, besitzt Sonnenfels für die Tauren seit langem eine spirituelle Bedeutung. Einer uralten Überlieferung zufolge küsste An'she, die Sonne, genau jenen Berggipfel, auf dem das Dorf steht. Generationen vor der Ankunft der Horde reisten Schamanen und Pilger der Tauren hierher, um Rituale durchzuführen, die den Schleier der Sterblichen überbrückten, und schöpften Kraft aus der starken Verbindung des Landes zur Geisterwelt."},{t="Grenzaußenposten",b="Heute dient Sonnenfels als Hauptstützpunkt der Horde im gesamten Steinkrallengebirge. Orcs und Tauren arbeiten Seite an Seite, um einen sicheren Stützpunkt gegen feindselige Harpyienbruten, einheimische Nachtelfenschildwachen und die industrielle Plünderung durch die Venture Company zu errichten. Als zentraler Knotenpunkt, der Handels- und Flugrouten zwischen Donnerfels, dem Wegekreuz und den Grenzen von Eschental verbindet, bietet der Rückzugsort jenen Schutz, Vorräte und spirituelle Führung, die den schroffen Felsen trotzen."}},faq={{q="Was ist Sonnenfels?",a="Sonnenfels ist der primäre Außenposten der Horde im Steinkrallengebirge. Hauptsächlich von Tauren und Orcs bewohnt, fungiert es als friedlicher Zufluchtsort, Handelsstation und Kommandoposten für die Recken der Horde, die in der Region im Einsatz sind.",al={"was ist sonnenfels","sonnenfels info","wer leitet sonnenfels"}},{q="Warum ist dieser Ort den Tauren heilig?",a="Der Legende der Tauren nach berührte An'she, die Sonne, den Berg, auf dem Sonnenfels heute steht. Das Land besitzt eine beständige Verbindung zur Geisterwelt und ist daher eine uralte Pilgerstätte für Visionssuchen und die Zwiesprache mit den Ahnen.",al={"warum ist sonnenfels heilig","anshe steinkrallen","tauren sonnenfels lore"}},{q="Welchen Bedrohungen sieht sich Sonnenfels ausgesetzt?",a="Sonnenfels muss sich gegen aggressive, revierbezogene Harpyien, feindselige Nachtelfen, die die heiligen Wälder bewachen, und die zerstörerischen Bergbau- sowie Abholzungsaktivitäten der Venture Company behaupten, welche die Natur verwüsten.",al={"sonnenfels bedrohungen","wer greift sonnenfels an","feinde im steinkrallengebirge"}},{q="Wohin verbindet der örtliche Flugmeister?",a="Sonnenfels bietet einen Windreiterdienst, der Reisende direkt mit den wichtigsten Orten im zentralen Kalimdor verbindet, darunter Das Wegekreuz im Brachland und die Hauptstadt der Tauren, Donnerfels.",al={"flugpunkte sonnenfels","flug nach sonnenfels","flugmeister sonnenfels"}}},fx={ea57691e={q="Was geschah in der Vergangenheit in Sonnenfels?",a="Über Generationen hinweg diente Sonnenfels als heiliges Ziel für Tauren-Pilger. Wegen der tiefen und dauerhaften Verbindung des Landes zum Geisterreich kamen Reisende von überall her auf den Ebenen, um feierliche Rituale abzuhalten, die es ihnen erlaubten, in die Welt der Geister hinüberzugehen. In jüngerer Zeit errichtete die Horde hier eine dauerhafte Präsenz und machte den abgelegenen Zufluchtsort zu einer aktiven Basis, die sich dem Schutz der Berge vor Umweltzerstörung widmet.",al={"geschichte von sonnenfels","vergangenheit von sonnenfels","historie von sonnenfels"}},["399aba06"]={q="Wer lebt in Sonnenfels?",a="Sonnenfels wird von einem engagierten Kontingent der Streitkräfte der Horde bevölkert, vorwiegend Tauren und Orcs. Neben den spirituellen Schamanen und Druiden, die den geheiligten Boden ehren, arbeiten Krieger und Arbeiter zusammen, um die Narben zu heilen, die von rücksichtslosen Ausbeutern wie der Venture Company in die Gipfel des Steinkrallengebirge geschlagen wurden.",al={"wer lebt in sonnenfels","bewohner von sonnenfels","wer leitet sonnenfels"}},["7401fa7d"]={q="Ist Sonnenfels gefährlich?",a="Der Zufluchtsort selbst ist ein sicherer Hafen, der von wachsamen Verteidigern der Horde bewacht wird und Reisenden und Pilgern Sicherheit bietet. Die Wildnis, die ihn umgibt, ist jedoch gefährlich. Aggressive Bestien, territoriale Harpyien und die zerstörerischen Mercenaries der Venture Company befallen die nahegelegenen Klippen und Schluchten, was bedeutet, dass Ihr wachsam bleiben solltet, sobald Ihr die Grenzen des Lagers verlasst.",al={"ist sonnenfels sicher","wie gefährlich ist sonnenfels","gefahr in sonnenfels"}},f56a5eae={q="Warum heißt es Sonnenfels?",a="Die Siedlung bezieht ihren Namen aus der alten Mythologie der Tauren. Ihren Legenden zufolge beugte sich An'she – die Sonne im Glauben der Tauren – einst herab und küsste persönlich den Berggipfel, an dem das Dorf heute liegt, segnete den Stein und erfüllte das Gebiet mit göttlicher Wärme und spiritueller Kraft.",al={"warum heißt es sonnenfels","namensherkunft sonnenfels","bedeutung von sonnenfels"}}},fp="16,391,27.428.0,16.496.0,25.221.0,39.234.0,35.212.0,43.192.0"}
P.entries["subzone:sundown-marsh"] = {fx={d0103c3e={q="Sind die Sonnenwendmarschen gefährlich?",a="Die Sonnenwendmarschen sind tückisch für jeden Reisenden, der nicht auf die Wildnis vorbereitet ist. Aggressive Krokolisken lauern im Wasser, Raptoren und umherstreifende Gnolle durchstreifen die Schlammbänke und gefährliche Schlammwesen und Sumpfbestien wandern durch den Morast, was jede Reise abseits der ausgetretenen Pfade gefährlich macht.",al={"wie gefährlich sind die sonnenwendmarschen","bedrohungen in den sonnenwendmarschen","sind die sonnenwendmarschen sicher"}}}}
P.entries["subzone:sunnyglade"] = {n="Sonnengrund",s="Sonnengrund war während des Ersten Krieges einst eine wohlhabende, blühende Menschensiedlung, die zum Königreich Sturmwind gehörte. Verwüstet und schließlich aufgegeben, als die Frontlinien zusammenbrachen, schmachtet die zerstörte Siedlung nun unter dem finsteren Einfluss des Schattenhammerkultes.",h="Sonnengrund war während des Ersten Krieges einst eine wohlhabende, blühende Menschensiedlung, die zum...",kw={"erster krieg","magierturm","alte horde","flusslande","sturmwind","sonnengrund","schattenhammer"},ang={["class:Mage"]="Der einsame Magierturm von Sonnengrund ist eine unheimliche Erinnerung an frühe menschliche Zauberkunst – einst von der Alten Horde einzig verschont, um das arkane Wissen der Menschen zu sezieren.",["race:Human"]="Die überwucherten Steine von Sonnengrund dienen als düsteres Denkmal für die äußeren Siedlungen, die aufgegeben wurden, als Sturmwind sich während des Ersten Krieges zum Rückzug gezwungen sah."},sec={{t="Fall einer goldenen Stadt",b="Bevor der Erste Krieg das südliche Azeroth zerriss, wurde Sonnengrund für seinen Reichtum und seinen behaglichen Wohlstand gerühmt. Dieser Friede wurde gewaltsam zerstört, als die Alte Horde einfiel. Plündernde Orc-Trupps griffen die Stadt an und versklavten die überlebenden Bewohner, wobei sie nur einen einsamen Magierturm intakt ließen, um die arkanen Künste der menschlichen Beschwörer zu studieren. Obwohl Streitkräfte aus Sturmwind einen Versuch unternahmen, die gefangenen Bauern zu retten und die Siedlung wiederaufzubauen, wurden die umliegenden Flusslande unaufhaltsam von der vorrückenden Horde verschlungen. Da Sturmwinds Befehlshaber die äußere Provinz für verloren hielten, zogen sie ihre Ressourcen schließlich zur Verteidigung der Heimat ab und überließen Sonnengrund dem Verfall."},{t="Eine verheerte Zuflucht",b="Heute liegt Sonnengrund weit jenseits der sicheren Grenzen von Sturmwinds wiedererrichtetem Reich. Während der ikonische steinerne Magierturm den Ersten Krieg und die darauf folgenden Jahre der Verlassenheit bemerkenswert gut überstanden hat, ist die friedliche Ortschaft um ihn herum verschwunden. Stattdessen wurden die abgelegenen Ruinen von Eiferern des Schattenhammerkultes besetzt, die das einst blühende Tal für ihre eigenen finsteren Pläne nutzen."}},faq={{q="Was geschah mit Sonnengrund?",a="Sonnengrund wurde während des Ersten Krieges von der Alten Horde angegriffen und geplündert. Obwohl es menschlichen Streitkräften gelang, gefangene Bauern zu befreien, und sie einen Wiederaufbau versuchten, gab Sturmwind die Region der Flusslande letztlich auf, um sich auf die Verteidigung seiner Kerngebiete zu konzentrieren.",al={"was ist sonnengrund","geschichte von sonnengrund","warum ist sonnengrund zerstört"}},{q="Wer beherrscht Sonnengrund heute?",a="Die Ruinen von Sonnengrund werden derzeit vom Schattenhammerkult besetzt, der inmitten der zerfallenen Häuser und des uralten Magierturms sein Lager aufgeschlagen hat.",al={"wer lebt in sonnengrund","sonnengrund feinde","sonnengrund schattenhammer"}},{q="Warum ließen die Orcs den Magierturm während des Ersten Krieges stehen?",a="Als die Alte Horde Sonnengrund plünderte, verschonte sie den arkanen Turm der Stadt ganz bewusst, damit ihre Hexenmeister und Befehlshaber die menschliche Magie studieren und ihre Geheimnisse lüften konnten.",al={"orc magierturm sonnengrund","lore zum sonnengrund turm"}},{q="Warum hat Sturmwind die Stadt nach dem Krieg nicht zurückgefordert?",a="Als sich der Erste Krieg zuspitzte, stufte die Führung von Sturmwind die Flusslande als verlorenes Gebiet ein und richtete den gesamten militärischen Schwerpunkt auf die zentrale Verteidigung des Königreichs, wodurch Sonnengrund zurückgelassen wurde.",al={"warum aufgegeben","sturmwind sonnengrund"}}},fp="10,277,21.665.0,17.396.0,28.256.0,28.151.0,68.168.0,52.193.0"}
P.entries["subzone:swamplight-manor"] = {n="Swamplight-Anwesen",s="Das Swamplight-Anwesen ist eine ironisch benannte, baufällige Holzbaracke tief im Hexenhügel in den Düstermarschen. Es dient als das exzentrische Heim und die Küche von 'Swamp Eye' Jarl, einem isolierten Einsiedler, der im gesamten Moor für seine sonderbaren kulinarischen Vorlieben bekannt ist. Trotz seiner bescheidenen, unheimlichen Abgeschiedenheit birgt der umliegende Garten Intrigen, die sowohl die Aufmerksamkeit von Theramore als auch von Brackenwall erregen.",h="Das Swamplight-Anwesen ist eine ironisch benannte, baufällige Holzbaracke tief im Hexenhügel in den...",kw={"brackenwall","düstermarschen","garran vimes","verlorener bericht","swamp eye jarl","swamplight-anwesen","hexenhügel"},ang={["faction:Alliance"]="Kundschafter aus Theramore, die von Captain Garran Vimes entsandt wurden, haben ein wachsames Auge auf die Gerüchte rund um das Anwesen, insbesondere in Bezug auf vermisste Späher und abgefangene Hordenkorrespondenz.",["profession:Cooking"]="Für Feinschmecker, die den Marschen trotzen, stellt Jarl den exzentrischen Höhepunkt der Nahrungssuche im Sumpf dar, der regionale Mahlzeiten aus Kreaturen zubereitet, die die meisten Köche kaum anzurühren wagen würden."},sec={{t="Die Zuflucht eines Einsiedlers im Moor",b="Entgegen dem, was sein hochtrabender Name vermuten lässt, ist das Swamplight-Anwesen weit von einem herrschaftlichen Anwesen entfernt. Es ist lediglich eine windschiefe, verwitterte Hütte, eingebettet in die heimgesuchten Feuchtgebiete des Hexenhügels. Sein einziger Bewohner, der sonderbare Einsiedler 'Swamp Eye' Jarl, führt ein einsames Dasein, umgeben von Nebel, Moder und ruhelosen Marschgeistern. Jarl verbringt seine Tage damit, ungewöhnliche regionale Delikatessen aus der heimischen Tierwelt zuzubereiten, und heuert häufig umherziehende Abenteurer an, um bizarre Zutaten wie Marschfroschschenkel und Kreaturenaugen für sein merkwürdiges Handwerk zu beschaffen."},{t="Geheimnisse im Garten",b="Während Reisende meist auf der Suche nach exzentrischer Kochkunst oder Schutz vor den Geistern des Hexenhügels über das Anwesen stolpern, verbergen die Ländereien einen weitaus finstereren Grenzkonflikt. Unter einem losen Erdhaufen in Jarls behelfsmäßigem Garten liegt der weggeworfene Bericht eines Orcspions, mitsamt einem abgetrennten Kopf ganz in der Nähe. Sowohl die Wachen Theramores unter Captain Garran Vimes als auch die Streitkräfte der Horde in Brackenwall haben großes Interesse daran, diese Dokumente zu bergen, was das überwucherte Fleckchen Erde des Einsiedlers zu einem unerwarteten Brennpunkt im regionalen kalten Krieg macht."}},faq={{q="Warum wird eine winzige Hütte 'Anwesen' genannt?",a="Der Name ist reine Ironie. Das Gebäude ist kaum mehr als eine feuchte, heruntergekommene Holzhütte, die von ihrem einsiedlerischen Bewohner 'Swamp Eye' Jarl mit einer Prise Exzentrik benannt wurde, um einen Kontrast zur trostlosen Düsterkeit des Hexenhügels zu bilden.",al={"swamplight-anwesen namensursprung","warum anwesen","ist swamplight ein echtes anwesen"}},{q="Wer lebt im Swamplight-Anwesen?",a="'Swamp Eye' Jarl lebt hier allein. Er ist ein berüchtigter, halb verrückter Einsiedler und Koch, der beschlossen hat, isoliert im heimgesuchten Moor zu hausen, und vorbeiziehende Reisende anheuert, um ihn mit sonderbaren Kochzutaten zu versorgen und ihm bei den örtlichen Geistern zu helfen.",al={"wer ist swamp eye jarl","swamplight-anwesen bewohner","wer lebt hier"}},{q="Was liegt draußen im Garten begraben?",a="In einem Haufen aufgewühlter Erde in Jarls Garten liegt der verlorene Spionagebericht eines Orcs verborgen, zusammen mit einem abgetrennten Kopf. Sowohl die Behörden der Allianz in Theramore als auch die Kundschafter der Horde aus Brackenwall sind bestrebt, sich diese Informationen zu sichern.",al={"swamplight-anwesen erdhaufen","lose erde swamplight","orc spionagebericht"}},{q="Können sowohl Spieler der Allianz als auch der Horde Jarl besuchen?",a="Ja. Jarl lebt so weit abseits der Zivilisation, dass er Neutralität wahrt und gern Hilfe annimmt oder Rezepte mit Reisenden der Allianz wie auch der Horde tauscht.",al={"ist jarl neutral","kann horde mit swamp eye jarl sprechen","swamplight fraktion"}}},fp="16,407,30.551.0,21.545.1,37.222.0,30.238.0,37.238.1,47.159.0"}
P.entries["subzone:swarming-pillar"] = {n="Die Schwarmsäule",s="Die Schwarmsäule ist eine hoch aufragende Felsformation im Herzen von Silithus, die von den Silithiden vollkommen befallen und umgeformt wurde. Die Nadel liegt direkt südlich von Burg Cenarius und verdankt ihren Namen den unerbittlichen Wolken geflügelter Insektoiden, die um ihre Spitzen und unterirdischen Eingänge schwirren.",h="Die Schwarmsäule ist eine hoch aufragende Felsformation im Herzen von Silithus, die von den Silithiden...",kw={"burg cenarius","bau","insekten","silithiden","silithus","nadel","die schwarmsäule"},ang={["class:Druid"]="Da der Bau an der Schwarmsäule so nahe an Burg Cenarius liegt, stellt er einen unmittelbaren Frevel an der natürlichen Ordnung und eine ständige Gefahr für die Wacht des Zirkels des Cenarius dar."},sec={{t="Eine Nadel aus Chitin und Sand",b="Die Schwarmsäule erhebt sich jäh aus den Wanderdünen im Zentrum von Silithus und dient als düsteres Denkmal für die ungebremste Ausbreitung der Silithiden. Was einst als natürliche Felsformation begann, wurde von den harzigen Sekreten und Bauten des insektoiden Schwarms ausgehöhlt und verkrustet. Direkt südlich von Burg Cenarius bringt sie unaufhörlich Gelege geflügelter Arbeiter und Soldaten hervor, deren dunkle Schwärme die trockene Wüstenluft erfüllen und Reisende mahnen, Abstand zu halten."},{t="Das Herz des Baus",b="Obwohl sie an der Oberfläche gewaltig und einschüchternd wirkt, ist die Schwarmsäule lediglich der sichtbare Ausläufer eines riesigen unterirdischen Netzwerks. Unter ihrem steinernen Äußeren verbergen sich tiefe Tunnel und höhlenartige Brutkammern, die einen der größten Bauten der Region verankern. Der Zirkel des Cenarius betrachtet die Felsnadel mit großer Sorge, da ihre aktiven Bruten die druidischen Unternehmungen direkt bedrohen und die furchterregende Koordination hinter der Bedrohung durch die Insektoiden erahnen lassen."}},faq={{q="Was ist die Schwarmsäule?",a="Die Schwarmsäule ist eine gewaltige Felsformation im Zentrum von Silithus, die von Silithiden eingenommen und in einen aktiven Bau verwandelt wurde. Sie zeichnet sich durch den endlosen Schwarm fliegender Insektoiden aus, der ihre Spitze umkreist.",al={"die schwarmsäule","was ist diese säule","silithidennadel silithus"}},{q="Wo befindet sich die Schwarmsäule?",a="Ihr findet sie im Zentrum der Wüste, nur ein kurzes Stück direkt südlich von Burg Cenarius.",al={"wo ist die schwarmsäule","schwarmsäule standort"}},{q="Warum fliegen so viele Insekten um sie herum?",a="Die Felsformation beherbergt einen der Hauptbauten in Silithus und dient als riesige Brutstätte sowie als Knotenpunkt für geflügelte Silithiden, die den Sand der umliegenden Wüste patrouillieren.",al={"warum schwärmen sie","fliegende insekten silithus säule","fliegende silithiden"}},{q="Ist die Schwarmsäule mit den Bauten unter dem Sand verbunden?",a="Ja. Die sichtbare Felsnadel ist lediglich der oberste Ausläufer einer ausgedehnten unterirdischen Kolonie, die tief in das Grundgestein und den Sand unter Silithus gegraben wurde.",al={"bautunnel","unterirdische silithidensäule"}}},fp="15,288,26.462.0,17.444.0,28.213.0,37.99.0,44.172.0,63.146.0"}
P.entries["subzone:tabetha-s-farm"] = {n="Tabetha's Farm",s="Tief in den trübsten Weiten des Morasts liegt Tabetha's Farm, ein abgelegenes Gehöft, das sich um eine kleine Holzhütte, einen bescheidenen Garten und einen privaten Steg gruppiert. Trotz der tückischen Sumpfumgebung dient diese Zuflucht der Einsiedlermagierin Tabetha als verborgener Rückzugsort.",h="Tief in den trübsten Weiten des Morasts liegt Tabetha's Farm, ein abgelegenes Gehöft, das sich um eine kleine...",kw={"dustwallow","düstermarschen","morast","tabetha","tabetha's farm","tabethas hütte"},ang={["class:Mage"]="Eure Lehrer in den Hauptstädten schätzen Tabethas esoterisches Wissen sehr und schicken erfahrene Zauberwirker zu ihrer Farm, um flüchtige Manawogen und uralte Relikte der Macht zu untersuchen.",["class:Warlock"]="Obwohl sie als ruhige Sumpfeinsiedlerin lebt, ist Tabetha eine der wenigen Zauberwirkerinnen, die Euch dabei helfen können, die mächtigen Energien zu läutern, die an die Orb of Orahil gebunden sind."},sec={{t="Die Zuflucht einer Einsiedlerin",b="Versteckt in den westlichen Feuchtgebieten der Düstermarschen trotzt Tabetha's Farm ihrer unbarmherzigen Umgebung. Das Gehöft, das aus einer verwitterten Hütte, kleinen Gemüsebeeten und einem Steg zur Erkundung der trüben Wasserwege des Sumpfes besteht, bietet eine ruhige Zuflucht fernab der politischen Rivalitäten zwischen Theramore und Brackenwall. Hier lebt die zurückgezogene Menschenzauberin Tabetha in nahezu vollständiger Isolation und widmet sich esoterischen Studien über arkan- und teufelsmagische Kräfte, ohne jede Einmischung aus Dalaran oder seitens der örtlichen Behörden."},{t="Ein Wegpunkt arkaner Macht",b="Trotz ihrer abgelegenen Lage zieht die Farm Anwender der magischen Künste aus ganz Kalimdor und den Östlichen Königreichen an. Magier, die die Beherrschung roher arkaner Wogen anstreben, und Hexenmeister, die Hilfe bei der Läuterung flüchtiger Artefakte wie der Orb of Orahil suchen, werden direkt vor Tabethas Haustür gewiesen."}},faq={{q="Wer lebt auf Tabetha's Farm?",a="Die Farm ist das Zuhause der exzentrischen Magierin Tabetha, die den kleinen Garten, den Steg und das Gehöft inmitten der gefährlichen Sumpfkreaturen des Morasts versorgt.",al={"wer ist tabetha","wer lebt hier","bewohner von tabetha's farm"}},{q="Warum reisen Magier den weiten Weg zu dieser Farm?",a="Magierlehrer auf der ganzen Welt schicken vielversprechende Schüler zu Tabetha, um ihr arkanes Wissen zu vertiefen. Sie besitzt profunde Kenntnisse über flüchtige Manawogen, uralte Relikte und urzeitliche Mächte, die an gewöhnlichen städtischen Akademien selten gelehrt werden.",al={"warum besuchen magier tabetha","magierquest dustwallow","magier klassenquest tabetha"}},{q="Warum sollten Hexenmeister hierherkommen?",a="Hexenmeister ersuchen Tabethas Sachverstand bei Exorzismen und Elementarenergien, wenn es darum geht, gefährliche Artefakte zu reinigen und zu bändigen – vor allem bei den Ritualen, die zur Läuterung der Orb of Orahil erforderlich sind.",al={"tabetha hexenmeisterquest","orb of orahil reinigen","hexenmeister tabetha"}},{q="Ist Tabetha's Farm mit der Horde oder der Allianz verbündet?",a="Tabetha nimmt eine neutrale Haltung ein und bietet Reisenden ihre Weisheit ungeachtet ihrer politischen Zugehörigkeit an. Ihre Farm bleibt sowohl von Jaina Prachtmeers Theramore als auch von den Streitkräften der Horde in Brackenwall unabhängig.",al={"ist tabetha allianz","ist tabetha horde","ist tabetha neutral"}}},fp="14,275,20.507.0,26.286.0,28.148.0,45.240.0,29.196.0,56.221.0"}
P.entries["subzone:tahonda-ruins"] = {n="Ruinen von Tahonda",s="Die Ruinen von Tahonda sind die sonnengebleichten Überreste einer uralten Taurensiedlung, die vom Salz und Sand der schimmernden Ebene verschlungen wurde. Nur wenig ist über die Dorfbewohner bekannt, die einst hier lebten, und gefährliche Saltstone-Basilisken lauern nun zwischen den verfallenden Zeltstangen und dem zerfetzten Leder.",h="Die Ruinen von Tahonda sind die sonnengebleichten Überreste einer uralten Taurensiedlung, die vom Salz und...",kw={"saltstone-basilisken","die schimmernde ebene","tahonda","ruinen von tahonda","taurendorf","tausend nadeln"},ang={["race:Tauren"]="Eine vergessene Taurensiedlung zu finden, die unter dem Salz von Tausend Nadeln versinkt, ist eine ergreifende Mahnung an die Gefahren, denen Eure nomadischen Vorfahren ausgesetzt waren, als sie durch Kalimdor zogen."},sec={{t="Unter dem Salz versunken",b="In den südlichen Weiten der schimmernden Ebene nahe dem Pass nach Tanaris gelegen, erheben sich die Ruinen von Tahonda als düsteres Monument einer verlassenen Vergangenheit der Tauren. Das Dorf fiel vor langer Zeit, und seine verwitterten Bauten wurden nach und nach von wandernden weißen Salzkrusten begraben. Während manche vermuten, dass die einheimischen Saltstone-Basilisken die Bewohner vertrieben haben, deuten seltsame Spuren an den überlebenden Strukturen auf anderes hin. Zwei deutliche Gruppen von je drei parallelen Rissen zerfetzen das Leder einer verfallenen Hütte – ein Hinweis darauf, dass das Dorf durch die Krallen mächtiger Raubtiere oder feindlicher Angreifer ein gewaltsames Ende fand, ehe die Wüste die verbleibenden Reste für sich beanspruchte."}},faq={{q="Was waren die Ruinen von Tahonda ursprünglich?",a="Tahonda war einst ein Dorf der Tauren, erbaut auf der trockenen Weite der schimmernden Ebene. Im Laufe der Zeit verfiel das Dorf zu einer Ruine und wurde allmählich von treibendem Sand und Salzkrusten verschluckt.",al={"was sind die ruinen von tahonda","wer erbaute tahonda","ruinen von tahonda geschichte"}},{q="Warum wurde das Dorf verlassen?",a="Keine schriftliche Überlieferung bewahrt das genaue Schicksal des Dorfes. Die Ruinen werden derzeit von bösartigen Saltstone-Basilisken heimgesucht, die die Siedler vertrieben haben könnten. Tiefe Risse mit drei Klauenspuren, die sich über die verbleibenden Lederhütten ziehen, deuten jedoch auf einen plötzlichen, gewaltsamen Angriff hin.",al={"warum ist tahonda zerstört","was zerstörte tahonda","was geschah mit tahonda"}},{q="Welche Kreaturen leben heute in den Ruinen?",a="Die Überreste des Dorfes sind vollkommen von feindseligen Saltstone-Basilisken befallen, die sich zwischen den verrottenden Holzstangen und zerfetzten Fellunterkünften sonnen.",al={"tahonda mobs","was gibt es in den ruinen von tahonda","tahonda bestien"}}},fx={["601f2090"]={q="Was geschah mit den Ruinen von Tahonda?",a="Es gibt nur sehr wenige Aufzeichnungen über die Vergangenheit von Tahonda. Es war einst eine alte Tauren-Siedlung, die schließlich zerfiel und allmählich von den wandernden Sanden der Die schimmernde Ebene begraben wurde. Während die eindringenden Saltstone-Basilisken die Dorfbewohner vielleicht vertrieben haben, deuten Krallenspuren, die über die verwitterten Lederbehausungen gerissen wurden, darauf hin, dass die Siedlung ein gewaltsames Ende durch wilde Bestien oder feindliche Plünderer fand, bevor sie im Laufe der Zeit verloren ging.",al={"geschichte der ruinen von tahonda","was geschah in den ruinen von tahonda"}},d43cf6cc={q="Sind die Ruinen von Tahonda gefährlich?",a="Ja. Die versunkenen Überreste des Dorfes sind zu einer Brutstätte für aggressive Saltstone-Basilisken geworden. Durch die halb vergrabenen Lederzelte und eingestürzten Pfähle zu wandern, setzt Euch diesen steinstarrenden Raubtieren aus, die die trostlose Ecke der Salzwüste für unvorsichtige Reisende, die Richtung Tanaris ziehen, gefährlich machen.",al={"sind die ruinen von tahonda gefährlich","bedrohungen in den ruinen von tahonda","gefahren in den ruinen von tahonda"}}},fp="13,290,23.605.0,39.186.0,30.272.0,37.163.0"}
P.entries["subzone:tainted-scar"] = {n="Die Faulende Narbe",s="Die Faulende Narbe ist eine von Dämonen heimgesuchte Schlucht im Südwesten der Verwüsteten Lande, durchdrungen von übler Teufelsmagie aus dem nahegelegenen Dunklen Portal. Sie dient derzeit als wichtigste Zuflucht für die Überreste der Brennenden Legion auf Azeroth, befehligt von der Verdammniswache Lord Kazzak.",h="Die Faulende Narbe ist eine von Dämonen heimgesuchte Schlucht im Südwesten der Verwüsteten Lande...",kw={"verwüstete lande","brennende legion","daio the decrepit","eredruin","kazzak","lord kazzak","razelikh","die faulende narbe"},ang={["class:Warlock"]="Die Faulende Narbe ist von großem Interesse für erfahrene Hexenmeister, die Daio the Decrepit an seinem dämonischen Altar aufsuchen, um zu lernen, wie man feurige Höllenbestien versklavt und befehligt.",["faction:Alliance"]="Kommandanten der Allianz überwachen die Schlucht genau, aus Furcht, Lord Kazzaks verschanzte Dämonenarmee könnte nach Norden in die Sümpfe des Elends oder in das Territorium von Sturmwind vordringen."},sec={{t="Eine Bastion der Legion",b="Einst ein üppiges Feuchtgebiet, das zum uralten Black Morass gehörte, wurde dieser trostlose Graben durch chaotische Teufelsenergien, die aus dem Dunklen Portal drangen, völlig seines Lebens beraubt und nahm die Farbe getrockneten Blutes an. Nach Archimondes Niederlage am Hyjal während des Dritten Krieges sammelten sich die überlebenden Streitkräfte der Brennenden Legion im Süden. Der kolossale Ered'ruin Lord Kazzak beanspruchte die Faulende Narbe als seine Festung, postierte Elitedämonen auf ihren geschwärzten Anhöhen und entsandte schreckliche Leutnants wie Razelikh the Defiler, um die Herrschaft über die verödeten roten Böden zu sichern."},{t="Unheilige Bewohner",b="Während die meisten Sterblichen die Narbe unter Androhung eines qualvollen Todes meiden, empfinden Praktizierende der dunklen Künste ihre gesättigten Teufelsenergien als unwiderstehlich. Ein exzentrischer menschlicher Hexenmeister namens Daio the Decrepit hat sich an einem zerstörten dämonischen Altar mit Blick auf die Schrecken niedergelassen; er nutzt die umherstreifenden Unholde, um finstere Rituale durchzuführen und angehenden Hexenmeistern beizubringen, wie man furchterregende Höllenbestien beschwört und bindet."}},faq={{q="Was ist die Faulende Narbe?",a="Es ist eine Schlucht im Südwesten der Verwüsteten Lande, die durch dämonische Magie aus dem Dunklen Portal schwer verdorben wurde. Einst Teil des Black Morass, verkümmerte das Land zu einem kargen, blutroten Ödland, das fast ausschließlich von hochrangigen Dämonen der Brennenden Legion bevölkert wird.",al={"was ist die faulende narbe","faulende narbe lore","warum ist der boden hier rot"}},{q="Wer beherrscht die Faulende Narbe?",a="Lord Kazzak, ein hoch aufragender Verdammniswachen-Kommandant der Brennenden Legion, befehligt die hier versammelten Dämonen. Nach der Niederlage der Legion im Dritten Krieg sammelte er die überlebenden Unholde im Süden, um einen tödlichen Stützpunkt auf Azeroth aufrechtzuerhalten.",al={"wer führt die dämonen hier an","faulende narbe boss","lord kazzak faulende narbe"}},{q="Warum lebt hier ein alter Mensch unter den Dämonen?",a="Dieser Einsiedler ist Daio the Decrepit, ein betagter Hexenmeister, der der Narbe getrotzt hat, um ihre mächtigen Teufels-Ley-Energien zu nutzen. Statt vor den Dämonen zu fliehen, führt er an einem hiesigen Altar finstere Rituale durch und unterweist erfahrene Hexenmeister, die die Beschwörung von Höllenbestien meistern wollen.",al={"wer ist daio","daio the decrepit","einsiedler in der faulenden narbe"}},{q="Ist die Faulende Narbe mit dem Dunklen Portal verbunden?",a="Ja. Als das Dunkle Portal erstmals die Grenze zwischen den Welten durchbrach, strömten chaotische Netherenergien in die umliegenden Sümpfe. Die Faulende Narbe absorbierte gewaltige Mengen dieses magischen Niederschlags, was das Terrain dauerhaft in eine unwirtliche, dämonische Zuflucht verwandelte.",al={"faulende narbe verbindung zum dunklen portal","warum ist es verdorben"}}},fp="12,280,23.561.0,18.385.0,25.273.0,27.232.0,49.263.0,49.266.0"}
P.entries["subzone:talonbranch-glade"] = {n="Nachtlaublichtung",s="Die Nachtlaublichtung ist eine ruhige Nachtelfen-Schanze, eingebettet in die verheerten Hügel des nördlichen Teufelswalds. Direkt südlich der Holzschlundfeste gelegen, bietet sie einen seltenen Zufluchtsort mit unberührtem Mondlicht, Schutz und Hippogryphentransit inmitten einer ansonsten verderbten Wildnis.",h="Die Nachtlaublichtung ist eine ruhige Nachtelfen-Schanze, eingebettet in die verheerten Hügel des nördlichen...",kw={"teufelswald","flugpunkt","lichtung","mondbrunnen","schildwachen","nachtlaublichtung","holzschlund"},ang={["faction:Alliance"]="Die Nachtlaublichtung ist Euer nördlichster Stützpunkt im Teufelswald und bietet lebenswichtige Flugverbindungen, Reparaturen und Zuflucht nahe der Holzschlundfeste.",["race:NightElf"]="Der unberührte Mondbrunnen der Lichtung dient als Zeugnis für Elunes fortwährende Gnade inmitten der schweren dämonischen Verderbnis, die den uralten Wald erstickt."},sec={{t="Ein Leuchtfeuer im Verderben",b="Auf einer Anhöhe nahe dem Tunnel zur Holzschlundfeste gelegen, dient die Nachtlaublichtung als nördlichste Bastion der Allianz im Teufelswald. Um eine geschützte Nachtelfenhütte und einen funktionierenden Mondbrunnen herum errichtet, bietet der Außenposten eine entscheidende Zuflucht vor der dämonischen Verderbnis, die den umliegenden Wald verschlungen hat. Kundschafter der Allianz, Schildwachen und durchreisende Abenteurer nutzen die Lichtung, um sich auszuruhen, zu erholen und ihre Ausflüge tiefer in die verseuchten Wälder oder weiter nach Winterquell und Mondlichtung zu planen."},{t="Ein Kreuzungspunkt des Nordens",b="Neben ihren natürlichen und spirituellen Verteidigungsanlagen fungiert die Nachtlaublichtung als unverzichtbarer Logistikknotenpunkt. Die hier stationierten Hippogryphen verbinden Reisende mit Auberdine an der Dunkelküste und Ewige Warte in den verschneiten Weiten jenseits der Holzschlundfeste. Sie bleibt ein einsamer, wachsamer Wachposten, der die Stellung gegen die vordringenden Schatten des Schattenrats und wilde Bestienrudel hält, die durch die verdorbenen Täler streifen."}},faq={{q="Was ist die Nachtlaublichtung?",a="Sie ist ein Lager der Allianz im nördlichen Teufelswald, das Schildwachen, Druiden und Reisenden, die den verderbten Wald durchqueren, als Zufluchtsort, Rastplatz und Flugknotenpunkt dient.",al={"nachtlaublichtung","zweck der nachtlaublichtung","was ist dieser ort"}},{q="Wohin fliegt der hiesige Flugmeister?",a="Der Hippogryphenmeister an der Nachtlaublichtung verbindet Reisende direkt mit mehreren Außenposten der Allianz und neutralen Stützpunkten, darunter Auberdine, Ewige Warte und Mondlichtung.",al={"flugrouten nachtlaublichtung","flugpunkte","wohin kann ich fliegen"}},{q="Ist das Wasser im Mondbrunnen trinkbar?",a="Ja. Im Gegensatz zu den verseuchten Tümpeln und verdorbenen Quellen im gesamten Teufelswald bleibt der Mondbrunnen an der Nachtlaublichtung von Elune gesegnet und von dämonischem Schmutz unberührt.",al={"mondbrunnen nachtlaublichtung","ist das wasser sauber","mondbrunnen verderbt"}},{q="Wie nah liegt dieser Ort an der Holzschlundfeste?",a="Die Nachtlaublichtung liegt direkt südlich des Eingangs zur Holzschlundfeste und ist damit die letzte Raststätte vor der Durchquerung der Furbolgtunnel nach Winterquell oder Mondlichtung.",al={"wo ist die holzschlundfeste","weg nach winterquell"}}},fp="17,255,22.502.0,25.395.0,26.165.0,41.142.0,43.170.0,36.176.0"}
P.entries["subzone:talondeep-path"] = {n="Der Steinkrallenpfad",s="Der Steinkrallenpfad ist ein gewundener unterirdischer Tunnel, der sich durch den Gebirgskamm zwischen Eschental und dem Steinkrallengebirge bohrt. Frei von feindseligen Kreaturen oder Reisenden dient er als ruhiger, natürlicher unterirdischer Durchgang, der den Mystralsee mit der Scherwindklippe verbindet.",h="Der Steinkrallenpfad ist ein gewundener unterirdischer Tunnel, der sich durch den Gebirgskamm zwischen...",kw={"eschental","höhle","mystralsee","steinkrallengebirge","steinkrallen","der steinkrallenpfad","tunnel","die scherwindklippe"},ang={["profession:Mining"]="Die gewundenen Felsnischen der Höhle schneiden direkt durch das tiefe Steinfundament der Bergkette und machen sie zu einem natürlichen Orientierungspunkt bei Reisen zwischen dem mineralienreichen Eschental und das Steinkrallengebirge."},sec={{t="Ein ruhiger Gebirgspass",b="Verborgen unter dem zerklüfteten Gebirgskamm, der Eschental und das Steinkrallengebirge trennt, liegt der Steinkrallenpfad, eine ruhige unterirdische Route. Die Passage verbindet die Wälder unmittelbar westlich des Mystralsees direkt mit den nordwestlichen Ausläufern der Scherwindklippe. Im Gegensatz zu den gefährlichen Pfaden an der Oberfläche, auf denen Raubtiere und kriegerische Fraktionen lauern, bleibt das Innere des Tunnels unheimlich ruhig und frei von feindseligen Bestien oder Lagern, wenn auch durchzogen von gewundenen Seitennischen, Felsspalten und natürlichen Einbuchtungen im Stein. Über der Erde zeugen noch schwache Überreste einer uralten Überlandstraße davon, dass Reisende einst die hohen Gipfel erklommen, ehe diese geschützte Höhle zum bevorzugten Weg durch das Gestein wurde."}},faq={{q="Wohin führt der Steinkrallenpfad?",a="Der Tunnel verbindet das südwestliche Eschental mit dem nordöstlichen Steinkrallengebirge. Sein nördlicher Eingang liegt unmittelbar westlich des Mystralsees, während seine südliche Mündung in die nordwestliche Seite der Scherwindklippe mündet.",al={"wohin führt der steinkrallenpfad","steinkrallenpfad verbindungen","steinkrallentunnel ausgänge"}},{q="Gibt es Monster oder Feinde im Inneren des Tunnels?",a="Nein. Das Innere der Höhle ist außergewöhnlich friedlich und völlig frei von feindseligen Monstern, Bestien oder befreundeten NSC, was sie zu einem sicheren Durchgang für Reisende macht, die die Gebirgsscheide überqueren.",al={"ist der steinkrallenpfad sicher","steinkrallenpfad mobs","steinkrallenpfad bedrohungen"}},{q="Was sind die Ruinen über der Höhle?",a="Überreste einer überwucherten Überlandstraße verlaufen entlang des Gebirgskamms direkt über der Höhle. Sie deuten darauf hin, dass eine ältere, tückische Überlandroute über die Klippen existierte, bevor der Durchgang durch das ausgehöhlte Innere genutzt wurde.",al={"straße über dem steinkrallenpfad","überlandpfad steinkrallengebirge"}},{q="Ist der Steinkrallenpfad ein Tunnel der Allianz oder der Horde?",a="Keine der beiden Fraktionen hält den Tunnel. Er ist vollkommen unbefestigte und neutrale Wildnis, die Reisenden jeglicher Zugehörigkeit einen sicheren Fußweg zwischen dem umkämpften Wald und dem Gebirge ermöglicht.",al={"wer kontrolliert den steinkrallenpfad","steinkrallenpfad fraktion"}}},fx={["3cd0cb65"]={q="Was ist der Steinkrallenpfad?",a="Der Steinkrallenpfad ist ein gewundener unterirdischer Tunnel, der direkt durch die Gipfel gehauen wurde und eine entscheidende Abkürzung zwischen den üppigen Wäldern des Eschental und den rauen Höhen des Steinkrallengebirge bietet. Von Westen des Mystralsee im Eschental kommend, tauchen Reisende nahe der nordwestlichen Ausläufer der Die Scherwindklippe im Steinkrallengebirge wieder auf. Im Inneren verzweigt sich die Höhle in neugierige Nischen und Sackgassen, bleibt aber einer der ruhigsten Gebirgspässe in Kalimdor.",al={"was ist der steinkrallenpfad","tunnel steinkrallenpfad","über den steinkrallenpfad"}}},fp="14,267,21.684.0,35.211.0,48.194.0,36.211.0,46.198.0"}
P.entries["subzone:tarren-mill"] = {n="Tarrens Mühle",s="Tarrens Mühle ist ein bedrängter Außenposten der Verlassenen, der im nördlichen Vorgebirge des Hügellands unterhalb des Alteracgebirges liegt. Einst ein friedliches Bauerndorf der Menschen, dient der Ort heute als wichtigste Bastion der Horde in Hillsbrad und befindet sich in ständigem Konflikt mit der Allianzstadt Süderstade im Süden.",h="Tarrens Mühle ist ein bedrängter Außenposten der Verlassenen, der im nördlichen Vorgebirge des Hügellands...",kw={"alterac","verlassene","hillsbrad","vorgebirge des hügellands","lordaeron","süderstade","syndikat","tarrens mühle"},ang={["faction:Horde"]="Tarrens Mühle ist Euer einziger großer Zufluchtsort im Vorgebirge des Hügellands und bietet einen Fledermausführer, Vorräte und lebenswichtige militärische Unterstützung gegen die vordringenden Allianztruppen aus Süderstade.",["race:Undead"]="Die Einnahme von Tarrens Mühle erweitert die südlichen Grenzen von Königin Sylvanas und verwandelt ein einst stolzes Bauerndorf Lordaerons in eine strategische Festung gegen die Lebenden."},sec={{t="Vom Korn zum Grab",b="Vor dem Dritten Krieg war Tarrens Mühle eine florierende landwirtschaftliche Siedlung, die dem Königreich Lordaeron die Treue hielt. Während des Zweiten Krieges erlangte der Ort Bekanntheit, als Truppen der Allianz gefangene hochelfische Bogenschützen aus nahegelegenen Orc-Lagern befreiten und so Quel'Thalas' volle Unterstützung für die Allianz von Lordaeron sicherten. Heute sind die ursprünglichen lebenden Bewohner der Stadt jedoch verschwunden und wurden durch die Verlassenen ersetzt. Die Architektur des Ortes ist verwittert und verfallen, die Felder sind kahl und die alte Mühle steht still, während die neuen untoten Bewohner die Siedlung gegen ständige Bedrohungen durch Gebirgsbestien, Gesetzlose des Syndikats und Plänkler der Allianz befestigen."},{t="Die Frontlinie von Hillsbrad",b="Tarrens Mühle fungiert als unverzichtbare vorderste Operationsbasis der Horde in der Region. In direktem Gegensatz zum Allianzhaufen Süderstade gelegen, hat sich die Straße zwischen den beiden Siedlungen zu einem offenen Kriegsgebiet entwickelt. Reisende der Horde nutzen Tarrens Mühle, um gegen die menschlichen Bauern und Soldaten vorzugehen, die Hillsbrad besetzen, Angriffe auf zwergische Ausgräber in Dun Garok zu koordinieren und die tückischen Straßen zu sichern, die in die verschneiten Klippen des Alteracgebirges hinaufführen."}},faq={{q="Wer kontrolliert Tarrens Mühle zurzeit?",a="Tarrens Mühle wird vollständig von den Verlassenen kontrolliert und dient als primärer Quest-Knotenpunkt und Außenposten der Horde im Vorgebirge des Hügellands.",al={"wer besitzt tarrens mühle","ist tarrens mühle horde oder allianz","tarrens mühle fraktion"}},{q="Warum bekämpfen sich Tarrens Mühle und Süderstade?",a="Tarrens Mühle verkörpert die südliche Reichweite der Verlassenen und der Horde in Lordaeron, während Süderstade die letzte große Festung der Allianz in der Region darstellt. Ihre unmittelbare Nähe macht fortwährende Territorialkriege unvermeidlich, da beide Fraktionen um die Kontrolle über die fruchtbaren Böden und strategischen Straßen von Hillsbrad ringen.",al={"süderstade gegen tarrens mühle","warum gegen süderstade kämpfen","hillsbrad krieg"}},{q="Wie war Tarrens Mühle vor der Seuche?",a="Es war eine friedliche menschliche Siedlung für Landwirtschaft und Müllerei im Königreich Lordaeron. Während des Zweiten Krieges befreiten Soldaten der Allianz in der Nähe des Ortes gefangene hochelfische Bogenschützen und sicherten so den Militärpakt von Quel'Thalas mit der Allianz von Lordaeron.",al={"geschichte von tarrens mühle","wer lebte früher hier","tarrens mühle lore"}},{q="Welche Bedrohungen gibt es um Tarrens Mühle herum neben der Allianz?",a="Abseits der Streitkräfte von Süderstade muss Tarrens Mühle sich mit den einheimischen Banditen des Syndikats, Hochlandyetis und Ogern, die von den Gipfeln Alteracs herabsteigen, sowie mit wilden Gebirgsbestien auseinandersetzen, die das Vorgebirge durchstreifen.",al={"feinde von tarrens mühle","lokale gefahren hillsbrad"}}},fx={["51e1ff94"]={q="Was ist Tarrens Mühle?",a="Tarrens Mühle ist ein nördlicher Außenposten und eine Siedlung im Vorgebirge des Hügellands, gelegen direkt unterhalb des Alteracgebirges. Einst eine bescheidene Bauerngemeinde des Königreichs Lordaeron, dient es heute als primäre Bastion der Verlassenen und als Horde-Stützpunkt in der Region und steht als direktes Gegengewicht zur Allianz in Süderstade.",al={"übersicht tarrens mühle","was ist das für eine stadt","über tarrens mühle"}},["7a0e9758"]={q="Was geschah in der Vergangenheit in Tarrens Mühle?",a="Während des Zweiten Krieges überfielen Streitkräfte der Horde Bogenschützen aus Silbermond in der Nähe der Stadt, was König Terenas dazu veranlasste, Allianz-Truppen hierher zu befehlen, um die Gefangenen zu retten und das Bündnis der Elfen mit Lordaeron zu festigen. Nachdem der Dritte Krieg das Königreich verwüstet hatte, ging seine menschliche Bevölkerung verloren und die Verlassenen beanspruchten die verwitterte Siedlung als ihren eigenen Stützpunkt.",al={"geschichte von tarrens mühle","vergangenheit von tarrens mühle","tarrens mühle im zweiten krieg"}},["3dc25634"]={q="Warum ist Tarrens Mühle in solch einem heruntergekommenen Zustand?",a="Die Stadt litt unter der Verwüstung durch den Dritten Krieg, anschließenden Angriffen der Geißel und dem Verlust ihrer ursprünglichen menschlichen Bevölkerung. Die Verlassenen, die sie jetzt besetzen, betrachten Tarrens Mühle in erster Linie als strategischen militärischen Stützpunkt und nicht als komfortables Zuhause, was dazu führt, dass ihre alten Gebäude, die Kirche und die verdorrten Obstgärten in einem Zustand vernachlässigten Verfalls sind.",al={"warum ist tarrens mühle ruiniert","warum sieht tarrens mühle kaputt aus","tarrens mühle verfallen"}},["4eb188ad"]={q="Ist Tarrens Mühle gefährlich?",a="Tarrens Mühle ist außergewöhnlich gefährlich. Gelegen an der volatilen Frontlinie des Hillsbrad, sieht es sich unerbittlichen Scharmützeln und Gegenangriffen von Allianz-Soldaten und Champions aus Süderstade gegenüber. Jenseits der Allianz lauern Syndikat-Gesetzlose in nahegelegenen Ruinen, Berg-Yetis streifen durch die nördlichen Hänge und wilde Crushridge-Oger bedrohen ständig die Außenbezirke.",al={"ist es sicher in tarrens mühle","gefahr in tarrens mühle","bedrohungsstufe tarrens mühle"}}},fp="11,317,19.631.0,23.462.0,35.138.0,44.306.0,44.250.0,59.201.0"}
P.entries["subzone:temple-gardens"] = {n="Die Tempelgärten",s="Die Tempelgärten bilden das ruhige, von Wasser durchzogene Herz von Darnassus und umgeben kleine Inseln direkt nördlich vom Tempel des Mondes. Geschmückt mit Brücken und unberührter Flora beherbergt das Viertel die Stadtbank und das mystische Baumportal, das an den Fuß von Teldrassil führt.",h="Die Tempelgärten bilden das ruhige, von Wasser durchzogene Herz von Darnassus und umgeben kleine Inseln...",kw={"bank","darnassus","portal","rut'theran","teldrassil","die tempelgärten","tempel des mondes"},ang={["faction:Alliance"]="Jeder Besucher, der an den Docks anlegt, muss durch das Portal von Rut'theran in diese ruhigen Gewässer treten, um den Rest der Stadt zu erreichen.",["race:NightElf"]="Die Gärten verkörpern die harmonische Verbindung von Wildnis und bürgerlicher Architektur, die die darnassische Kultur prägt, und bieten Raum für Besinnung inmitten des alltäglichen Verwaltungslebens."},sec={{t="Das Herz der Elfenhauptstadt",b="Über die Gewässer im Zentrum von Darnassus hinweg dienen die Tempelgärten als Kreuzungspunkt der Nachtelfenhauptstadt. Holzbrücken verbinden die gestalteten Inseln mit der Enklave des Cenarius im Norden, den belebten Terrassen im Osten und dem erhabenen Heiligtum des Tempels des Mondes im Süden. Die Nachtelfen pflegen das fließende Wasser und die üppige Vegetation des Viertels sorgsam und schaffen so eine friedvolle Atmosphäre, die Reisenden wie Priesterinnen gleichermaßen Rast bietet."},{t="Tor nach Teldrassil",b="Neben dem zentralen Gewölbe und der Bank der Stadt auf ihrer Hauptinsel besitzen die Tempelgärten eine entscheidende Bedeutung für Reisende, die den Weltenbaum betreten oder verlassen. Am westlichen Ufer der Gärten steht ein gewaltiges, rosa leuchtendes Baumportal. Dieser magische Torbogen ermöglicht einen augenblicklichen Durchgang hinab durch die Äste nach Rut'theran am Fuße von Teldrassil und verbindet die abgelegene Baumkrone mit den Docks an der Küste und den Flugrouten."}},faq={{q="Was ist das rosa leuchtende Portal in den Gärten?",a="Das leuchtende Baumportal am westlichen Rand der Gärten ist die wichtigste Verkehrsverbindung zwischen der Krone von Teldrassil und seinem Fuß. Wer hindurchtritt, wird augenblicklich nach Rut'theran befördert, wo Schiffe und Hippogryphen die Nachtelfen mit der Dunkelküste und der weiteren Welt verbinden.",al={"baumportal darnassus","rosa baumportal","teleporter darnassus"}},{q="Wo befindet sich die Bank von Darnassus?",a="Die Hauptbank der Stadt liegt direkt in den Tempelgärten und befindet sich in einem offenen Pavillon der Elfen auf der größten zentralen Insel des Viertels.",al={"darnassus bank standort","wo ist die bank","bankier darnassus"}},{q="Warum heißen sie Tempelgärten?",a="Das Viertel verdankt seinen Namen dem prächtigen Tempel des Mondes, der direkt südlich an die Gärten angrenzt.",al={"tempelgärten namensherkunft","warum tempelgärten"}},{q="Welche Viertel sind mit den Tempelgärten verbunden?",a="Über das Wasser hinweg führen Brücken von den Gärten in fast jedes Viertel: die Enklave des Cenarius im Norden, die Terrassen der Handwerker, Krieger und Händler im Osten und der Tempel des Mondes im Süden.",al={"wohin führen die tempelgärten","brücken von den tempelgärten"}}},fx={["15ee89a5"]={q="Was sind Die Tempelgärten?",a="Die Tempelgärten bilden das grüne, ruhige Herz von Darnassus. Dieser malerische Bezirk, der sich über einen zentralen See erstreckt, bietet üppige Inselchen, geschwungene Holzbrücken und gepflegte Flora, die durch die Naturmagie der Nachtelfen erhalten wird. Das Gebiet beherbergt die Stadtbank auf seiner zentralen Insel und dient als natürliche Kreuzung, die die umliegenden Terrassen der Hauptstadt mit dem Tempel des Mondes verbindet.",al={"die tempelgärten darnassus","was sind die tempelgärten","lore der tempelgärten"}},a5d2a9ad={q="Was geschah in Die Tempelgärten?",a="Die Gärten wurden nach dem Dritten Krieg zusammen mit dem Rest von Darnassus angelegt und geformt, wobei sie auf den Ästen von Teldrassil erschaffen wurden, um einen Ort der Schönheit und friedlichen Kontemplation zu bieten. Pfleger der Nachtelfen leiteten sorgfältig die Gewässer und kultivierten zarte Flora, um ein ruhiges Heiligtum zu schaffen, das Priester, Anführer und Besucher zur Reflexion nutzen.",al={"geschichte der tempelgärten","was geschah in den tempelgärten"}},["6a127887"]={q="Sind Die Tempelgärten gefährlich?",a="Überhaupt nicht. Die Gärten liegen sicher im Inneren von Darnassus, bewacht von Wächterinnen und geschützt durch die Verteidigungsanlagen der Hauptstadt. Es ist einer der friedlichsten und am stärksten frequentierten Bezirke der Stadt, völlig frei von wilden Bestien oder feindlichen Bedrohungen.",al={"sind die tempelgärten sicher","gefahr in den tempelgärten","sind die tempelgärten gefährlich"}}},fp="14,273,26.462.0,21.431.0,47.289.0,36.136.0,39.141.0,46.219.0"}
P.entries["subzone:temple-of-arkkoran"] = {n="Der Tempel von Arkkoran",s="Der Tempel von Arkkoran ist eine uralte Ruine der Nachtelfen, die auf den nordöstlichen Klippen von Azshara über dem zertrümmerten Strand ruht. Ursprünglich zu Ehren von Elune erbaut, wurde das verfallene Bauwerk seither von dem hoch aufragenden Meerriesen Arkkoroc und seinen aquatischen Knechten beansprucht.",h="Der Tempel von Arkkoran ist eine uralte Ruine der Nachtelfen, die auf den nordöstlichen Klippen von Azshara...",kw={"arkkoroc","azshara","elune","makrura","murloc","meerriese","der zertrümmerte strand","der tempel von arkkoran"},ang={["class:Priest"]="Obwohl uralte Symbole von Elune zwischen den verwitterten Steinen verweilen, ist in diesen meerumpeitschten Ruinen keine göttliche Zwiesprache mehr geblieben.",["race:NightElf"]="Ein heiliges Haus von Elune zu sehen, das zu einem Nistplatz für Makrura und Meerriesen verkommen ist, ist eine bittere Erinnerung an den Glanz, der vor zehntausend Jahren verloren ging."},sec={{t="Eine geweihte Ruine, vom Meer beansprucht",b="Wie viele der erhabenen Ruinen an Azsharas Küste war der Tempel von Arkkoran einst ein der Mondgöttin Elune geweihtes Heiligtum, bevor die Zerschlagung das uralte Reich der Nachtelfen erschütterte. Heute sind seine verwitterten Marmorstufen und zerbrochenen Kolonnaden von Monstrositäten der Gezeiten überrannt. Der Meerriese Arkkoroc herrscht über die höchste Ebene des Tempels, umgeben von loyalen Makrura und bösartigen Murlocs, die die umliegende Küste gewaltsam gegen jeden landbewohnenden Eindringling verteidigen."}},faq={{q="Wozu wurde der Tempel von Arkkoran ursprünglich erbaut?",a="Lange bevor er unter seinem heutigen Namen bekannt wurde, war das Bauwerk ein Tempel der Nachtelfen, der der Verehrung von Elune geweiht war. Während der Großen Zerschlagung verfiel er zusammen mit dem Rest der umliegenden Küstenzivilisation zu Ruinen.",al={"geschichte des tempels von arkkoran","wer baute den tempel von arkkoran","was ist dieser tempel"}},{q="Wer ist Arkkoroc?",a="Arkkoroc ist ein mächtiger Meerriese, der diesen ehemaligen Tempel der Nachtelfen zu seiner Heimat gemacht hat. Er residiert auf der höchsten Plattform der Ruinen und beherrscht das umliegende Ufer sowie die Küstenbestien, die es bewohnen.",al={"wer ist arkkoroc","meerriese arkkoroc","wer herrscht über arkkoran"}},{q="Welche Kreaturen bewachen das Tempelgelände?",a="Der Tempel und seine umliegenden Terrassen werden von aggressiven Makrura und Murlocs patrouilliert, darunter Klackerer, Kneifer und Schlicksucher von Arkkoran. An den umliegenden Stränden des zertrümmerten Strandes sind zudem Hydren und andere Meerriesen beheimatet.",al={"tempel von arkkoran mobs","was lebt im tempel von arkkoran","feinde im tempel von arkkoran"}}},fp="18,270,37.478.0,53.228.0,16.208.0,40.238.0"}
P.entries["subzone:temple-of-atal-hakkar"] = {n="Der Tempel von Atal'Hakkar",s="Der Tempel von Atal'Hakkar, weithin bekannt als der Versunkene Tempel, ist eine überflutete Festung, die von verbannten Trollpriestern zu Ehren des Blutgottes Hakkar erbaut wurde. Vor Jahrhunderten vom grünen Drachenschwarm unter den Sümpfen versenkt, dienen seine ertrunkenen Hallen noch immer als Schauplatz für verbotene Rituale und finstere Verderbnis.",h="Der Tempel von Atal'Hakkar, weithin bekannt als der Versunkene Tempel, ist eine überflutete Festung, die von...",kw={"atal'ai","atal'hakkar","eranikus","hakkar","jammal'an","tränenteich","versunkener tempel","sümpfe des elends","ysera"},ang={["class:Druid"]="Die Verderbnis von Yseras grünen Drachenwächtern in den Tiefen des Tempels trifft das Herz des Smaragdgrünen Traums und verlangt nach einer raschen Untersuchung.",["race:Troll"]="Für die Dunkelspeere sind die Ruinen eine düstere Mahnung an den blutgetränkten Wahnsinn, der das uralte Gurubashireich zugrunde richtete, und an die ewige Gefahr durch Hakkar den Seelenschinder."},sec={{t="Der Zorn des grünen Schwarms",b="Vor über einem Jahrtausend zerriss ein verheerender Bürgerkrieg das Gurubashireich, als die Priesterschaft der Atal'ai versuchte, Hakkar den Seelenschinder zu beschwören. Nach Norden verbannt, errichteten die überlebenden Fanatiker einen gewaltigen Steintempel in den Sümpfen des Elends, um ihr dunkles Werk zu vollenden. Als der Drachenaspekt Ysera von ihrem Vorhaben erfuhr, schmetterte sie die Ziggurat tief in den Morast und überflutete ihre Kammern unter dem Tränenteich. Grüne Drachenwächter wurden zurückgelassen, um die ertrunkenen Ruinen zu bewachen und sicherzustellen, dass Hakkars Rückkehr für immer vereitelt blieb."},{t="Ein Schlummer wird zum Albtraum",b="Statt den Kult zu begraben, bot das Versinken des Tempels den Atal'ai die nötige Abgeschiedenheit, um ihre grausamen Opfer ungehindert fortzuführen. Im Laufe der Jahrhunderte begann die Verderbnis, die Wächter von innen heraus zu zerfressen; die Drachenschildwachen verfallen dem Wahnsinn, während die Atal'ai, geleitet von Jammal'an dem Propheten, den Weg für Hakkars Avatar bereiten. Nun wachen sowohl die Horde als auch die Allianz mit bangem Blick über die versunkene Ziggurat, während finstere Gerüchte aus den Tiefen des Sumpfes dringen."}},faq={{q="Warum steht der Tempel unter Wasser?",a="Ysera, der Aspekt des grünen Drachenschwarms, zerschmetterte den Tempel eigenhändig unter den Wassern des Sumpfes, um die Atal'ai-Trolle daran zu hindern, den Blutgott Hakkar nach Azeroth zu beschwören.",al={"warum versunkener tempel","wer versenkte den tempel","wie ist er versunken"}},{q="Wer sind die Atal'ai?",a="Die Atal'ai sind eine fanatische Sekte von Trollpriestern, die aus dem südlichen Gurubashireich verbannt wurden, weil sie Blutmagie praktizierten und versuchten, Hakkar den Seelenschinder in die physische Welt zu rufen.",al={"atal'ai geschichte","wer baute den versunkenen tempel","atal'ai-priester"}},{q="Warum gibt es hier grüne Drachen?",a="Ysera beauftragte eine Schar grüner Drachen damit, über die versunkenen Ruinen zu wachen und Eindringlinge fernzuhalten, damit Hakkar niemals beschworen werden konnte. Tragischerweise sind viele dieser Wächter dem Wahnsinn und dunkler Verderbnis anheimgefallen.",al={"warum drachen im sumpf","grüner drachenschwarm versunkener tempel"}},{q="Wie gelangt man in das Innere des Tempels?",a="Ihr müsst vom Tränenteich aus in die überfluteten Ruinen schwimmen, die versunkenen Durchgänge der Broken Hall durchqueren und über steinerne Korridore wie die Hall of Masks emporsteigen.",al={"versunkenen tempel betreten","eingang versunkener tempel","zugang zu atal'hakkar"}}},fp="21,301,25.529.0,26.462.0,29.183.0,20.188.0,33.223.0,33.178.0"}
P.entries["subzone:temple-of-the-moon"] = {n="Tempel des Mondes",s="Der Tempel des Mondes steht in Darnassus als das spirituelle Herz des Nachtelfenvolkes und der Regierungssitz auf Teldrassil. Unter dem Vorsitz von Hohepriesterin Tyrande Wisperwind dient das Heiligtum als Hauptquartier der Schwesternschaft von Elune. Seine hoch aufragenden Marmorstufen beherbergen einen heiligen Mondbrunnen, dessen gesegnete Wasser Heilung und Gemeinschaft mit der Mondgöttin spenden.",h="Der Tempel des Mondes steht in Darnassus als das spirituelle Herz des Nachtelfenvolkes und der Regierungssitz...",kw={"darnassus","haidene","mondbrunnen","schwesternschaft von elune","teldrassil","tempel von elune","tempel des mondes","tyrande wisperwind"},ang={["class:Priest"]="Für Priester der Allianz – insbesondere der Nachtelfen – stellt der Tempel den höchsten Quell von Elunes göttlichem Mandat und die Heimat ihrer ranghöchsten Ausbilder dar.",["race:NightElf"]="Der Tempel steht als kultureller, spiritueller und bürgerlicher Kern des modernen Lebens der Kaldorei und vereint die Schwesternschaft von Elune und die Führung von Teldrassil unter einem Dach."},sec={{t="Zuflucht der Mondgöttin",b="Kurz nach dem Dritten Krieg errichtet, als sich die Nachtelfen auf Teldrassil niederließen, gehört der Tempel des Mondes zu den größten Steinstrukturen, die von modernen Kaldorei erbaut wurden. Ein Großteil seines Marmors wurde auf dem Festland von Kalimdor abgebaut und auf magische Weise über das Meer transportiert. Im Zentrum seines Inneren liegt ein weitläufiger Mondbrunnen, der von der Statue von Haidene bewacht wird und dessen geweihte Wasser eine stille Macht ausstrahlen. Neben seiner Funktion als Gebetsstätte und Ort stiller Einkehr für Pilger dient der Tempel als politischer Scheitelpunkt von Darnassus, in dem Hohepriesterin Tyrande Wisperwind residiert, während sie ihr Volk durch den Anbeginn eines ungewissen neuen Zeitalters führt."},{t="Die Bastion der Schwesternschaft",b="Auf den ruhigen Terrassen des Tempels führen die Priesterinnen der Schwesternschaft von Elune den Willen der Göttin sowohl spirituell als auch taktisch aus. Von hier aus werden Abgesandte und entsandte Schwestern über ganz Nordkalimdor ausgesandt, um Bedrohungen zu untersuchen oder örtlichen Schildwachen beizustehen, wie etwa Priesterin Gwennyth Bly'Leggondes Erkundungen entlang der Küste der Dunkelküste. Novizinnen wie auch erfahrene Priesterinnen versammeln sich unter der sternenbesetzten Gewölbedecke, um sich im göttlichen Zauberwirken zu üben, die Verwundeten zu versorgen und Das Sanktum vor Verderbnis von außen zu schützen."}},faq={{q="Wer leitet den Tempel des Mondes?",a="Hohepriesterin Tyrande Wisperwind führt den Vorsitz im Tempel. Als Anführerin der Schwesternschaft von Elune und De-facto-Oberhaupt der Kaldorei-Regierung hält sie auf den oberen Rängen Hof und leitet sowohl die spirituellen als auch die militärischen Angelegenheiten von Darnassus.",al={"anführer tempel des mondes","wer ist im tempel","tyrande aufenthaltsort"}},{q="Wie wurde der Tempel auf Teldrassil erbaut?",a="Während Teldrassil aus Zweigen über dem Ozean erwuchs, ist der Tempel selbst eines der wenigen großen Steinbauwerke in Darnassus. Sein Marmor und Mauerwerk wurden auf dem Festland von Kalimdor abgebaut und durch magischen Transport auf den Gipfel des Weltenbaums gebracht.",al={"wie wurde der tempel des mondes erbaut","steintempel darnassus ursprung"}},{q="Was ist das Becken im Zentrum des Tempels?",a="Das zentrale Becken ist ein heiliger Mondbrunnen, über den die Statue von Haidene wacht. Seine Wasser sind zutiefst geweiht und werden als direkter Segen von Elune verehrt, der von der Schwesternschaft für Reinigungsrituale, Meditation und mächtige Wiederherstellungsmagie genutzt wird.",al={"tempel mondbrunnen","wasser im tempel des mondes"}},{q="Welche Dienste finden Spieler hier?",a="Der Tempel fungiert als primärer Knotenpunkt für die Priesterausbildung in Darnassus. Abenteurer kommen auch hierher, um Hohepriesterin Tyrande Wisperwind Bericht zu erstatten und Weisungen oder Aufträge der Schwesternschaft von Elune zu empfangen.",al={"was ist im tempel der elune","tempel lehrer darnassus"}}},fx={["18c3233a"]={q="Was ist der Tempel des Mondes?",a="Der Tempel des Mondes ist das große Heiligtum von Elune und das spirituelle Herz der Nachtelfen. Als eines der größten Steingebäude auf Teldrassil dient er als heilige Wohnstätte für die Schwesternschaft von Elune und als de facto Regierungssitz für Darnassus, in dem die Hohepriesterin Tyrande Wisperwind residiert.",al={"tempel des mondes darnassus","was ist dieser tempel","tempel der elune darnassus"}},fde18cfb={q="Was geschah im Tempel des Mondes?",a="Erbaut zusammen mit Darnassus im Gefolge des Dritten Krieges, wurde der Tempel aus Stein errichtet, der magisch vom Festland herübergebracht wurde. Seit seiner Erschaffung dient er als Kommandozentrale, von wo aus die Hohepriesterin Tyrande Wisperwind und die Schwesternschaft von Elune die Angelegenheiten und die spirituelle Führung der Kaldorei beaufsichtigen.",al={"geschichte des tempels des mondes","was geschah hier","geschichte des tempels der elune"}},["7506a07b"]={q="Ist der Tempel des Mondes gefährlich?",a="Überhaupt nicht für Verbündete der Nachtelfen. Er ist eines der sichersten, ruhigsten Heiligtümer auf ganz Teldrassil, bewacht von erfahrenen Priesterinnen, Wächterinnen und der Hohepriesterin selbst. Jeder jedoch, der es wagt, Feindseligkeit oder Verderbnis in Elunes Heiligtum zu bringen, wird schnelle und tödliche Vergeltung erfahren.",al={"ist der tempel des mondes gefährlich","ist es hier sicher","gefahr im tempel der elune"}},["7361c49d"]={q="Warum heißt es Tempel des Mondes?",a="Das Heiligtum ist Elune gewidmet, der verehrten Mondgöttin der Kaldorei. Die Nachtelfen sehen sie als die Mutter ihres Volkes und die Quelle des heiligen Lichts und benennen ihre prächtigsten Hallen und Heiligtümer zu Ehren ihrer leuchtenden Präsenz.",al={"warum tempel des mondes","ursprung des tempelnamens","warum heißt er tempel des mondes"}}},fp="18,378,29.664.0,24.544.0,33.245.0,39.261.0,45.247.0,36.220.0"}
P.entries["subzone:terrace-of-repose"] = {n="Terrasse der Erholung",s="Die Terrasse der Erholung ist ein makelloser Hofgarten direkt vor dem Eingang zum Scharlachroten Kloster in Tirisfal. Vom Scharlachroten Kreuzzug instand gehalten, ist sie einer der wenigen Orte im nördlichen Lordaeron, die von der Seuche des Untods völlig unberührt geblieben sind – samt grünen Hecken und sauberem Wasser.",h="Die Terrasse der Erholung ist ein makelloser Hofgarten direkt vor dem Eingang zum Scharlachroten Kloster in...",kw={"brunnen","hecken","seuche des untods","scharlachroter kreuzzug","das scharlachrote kloster","terrasse der erholung","tirisfal","unberührt"},ang={["class:Paladin"]="Lebende Flora und unberührtes Wasser in Tirisfal zu sehen, ist ein eindrucksvolles Zeugnis für das Heilungspotenzial des Landes, selbst wenn es derzeit von unnachgiebigen Fanatikern gepflegt wird.",["race:Undead"]="Für die Verlassenen ist das makellose Grün der Terrasse eine deutliche und bittere Erinnerung an die Welt der Lebenden, die sie verstößt – gepflegt von Todfeinden, deren einziger Wunsch es ist, Lordaeron von ihrer Art zu reinigen."},sec={{t="Eine Oase in der Pest",b="Direkt nördlich des prächtigen Eingangs in das Scharlachrote Kloster gelegen, bietet die Terrasse der Erholung einen surrealen Kontrast zu den verrottenden Wäldern von Tirisfal. Während der Rest von Lordaeron unter grauem Nebel, verdorbenem Boden und fauligen Mooren erstickt, verfügt diese Terrasse über grüne, sauber gestutzte Hecken und einen funktionierenden Brunnen, der von frischem, unberührtem Wasser gespeist wird. Für die Eiferer des Scharlachroten Kreuzzugs dient der Garten als greifbarer Beweis ihrer göttlichen Rechtschaffenheit und Reinheit – eine heilige Bastion, die demonstriert, dass heilige Hingabe das Verderben der Geißel abwehren kann."}},faq={{q="Warum sind Gras und Wasser hier sauber, während Tirisfal tot ist?",a="Die Terrasse der Erholung ist der Reichweite der Seuche des Untods entgangen. Durch ständige Wachsamkeit und womöglich ihre unerschütterliche Hingabe an das Heilige Licht hat der Scharlachrote Kreuzzug den Boden bewahrt, gedeihende Hecken gepflanzt und eine klare, frische Wasserquelle erhalten, die völlig frei von der umgebenden Verwesung ist.",al={"warum ist es hier grün","sauberes wasser scharlachrotes kloster","terrasse der erholung unberührt"}},{q="Wo genau befindet sich die Terrasse der Erholung?",a="Sie liegt unmittelbar vor dem Eingangsbereich des Komplexes vom Scharlachroten Kloster, in den nordöstlichen Hügeln von Tirisfal.",al={"wo ist terrasse der erholung","terrasse der erholung standort","kloster garteneingang"}},{q="Wofür nutzen die Kreuzfahrer die Terrasse?",a="Sie dient nicht nur als Zugang zu ihrem befestigten Kloster, sondern bietet auch einen ruhigen Zufluchtsort unberührter Erde, an dem Kreuzfahrer rasten, nachdenken und einen idealisierten Einblick in das Königreich Lordaeron erhaschen können, wie es vor dem Dritten Krieg bestand.",al={"scharlachroter kreuzzug gartennutzung","zweck der terrasse der erholung"}}},fx={f618a338={q="Was ist die Terrasse der Erholung?",a="Die Terrasse der Erholung ist ein ruhiger Innenhof, der sich direkt nördlich des Haupteingangs des Scharlachroten Klosters befindet. Unter strenger Bewachung durch The Scarlet Crusade zeichnet sie sich als einer der wenigen makellosen Orte aus, die im nördlichen Lordaeron verblieben sind, mit gepflegten grünen Hecken und frischem, fließendem Wasser, das von der Fäulnis der Geißel unberührt geblieben ist.",al={"was ist die terrasse der erholung","terrasse der erholung scharlachrotes kloster","über die terrasse der erholung"}},["310f02b5"]={q="Wer kontrolliert die Terrasse der Erholung?",a="The Scarlet Crusade unterhält und kontrolliert die Terrasse. Direkt vor ihrer weitläufigen Klosterfestung gelegen, dient das Gebiet als Rückzugsort im Freien und als verteidigbarer Garten, der von Kreuzfahrer-Wachen und Klerikern gepflegt wird, die entschlossen sind, eine Ecke von Lordaeron so zu bewahren, wie sie vor dem Fall existierte.",al={"wer lebt auf der terrasse der erholung","wer kontrolliert die terrasse der erholung","fraktion auf der terrasse der erholung"}},["538b338a"]={q="Ist die Terrasse der Erholung gefährlich?",a="Sie ist extrem gefährlich für jeden außerhalb von The Scarlet Crusade. Die Terrasse wird stark von fanatischen Kreuzfahrern patrouilliert, die jeden Eindringling auf Sicht angreifen, egal ob Ihr Verlassene, Horde oder ungebundene Reisende seid, die sich zu nah an die Klostertore wagen.",al={"ist die terrasse der erholung gefährlich","bedrohungen auf der terrasse der erholung","kann ich die terrasse der erholung besuchen"}}},fp="17,314,22.565.0,60.300.0,47.135.0,42.239.0"}
P.entries["subzone:terror-run"] = {n="Terrorflucht",s="Die Terrorflucht ist ein gefährlicher Landstrich in den südwestlichen Ausläufern des Un'Goro-Kraters, direkt westlich der insektoiden Bauten der wuchernden Narbe. Getreu ihrem furchterregenden Namen wird dieses Gebiet von raubtierhaften Bestien durchstreift, von gewaltigen Teufelssauriern über gefräßige Diemetradons bis hin zu herabstoßenden Pterrordaxen.",h="Die Terrorflucht ist ein gefährlicher Landstrich in den südwestlichen Ausläufern des Un'Goro-Kraters, direkt...",kw={"teufelssaurier","diemetradon","marshal expedition","pterrordax","roter machtkristall","die wuchernde narbe","terrorflucht","un'goro"},ang={["class:Hunter"]="Die weiten Ebenen der Terrorflucht sind ein tödlicher Prüfstein und beherbergen einige der wildesten Bestien in ganz Kalimdor – von flinken Raptoren und wilden Pterrordaxen bis hin zu emporragenden Teufelssauriern."},sec={{t="Eine Jagd auf offenem Feld",b="Über die südwestliche Ebene des Un'Goro-Kraters erstreckt sich die Terrorflucht und macht ihrem unheilvollen Ruf alle Ehre. Wilde Pterrordaxe kreisen durch die feuchte Luft empor, während massive Diemetradons, Stegodons und Teufelssaurier als Spitzenprädatoren das niedrige Dickicht am Boden durchstreifen. Das Territorium liegt direkt im Schatten des gebirgigen Kraterrands, unangenehm nah an den zirpenden, fremdartigen Hügeln der wuchernden Narbe eingekeilt. Am östlichen Rand der Ebene liegen die verfallenen Überreste eines Lagers von Williden Marschalls Expedition – eine ernüchternde Mahnung an jene Forscher, die unvorbereitet überrascht wurden, als die urzeitlichen Raubtiere des Kraters zuschlugen."},{t="Rote Kristalle und uralte Raubtiere",b="Über die bloße Konzentration hungriger Fauna hinaus zieht die Terrorflucht Naturforscher wie auch Abenteurer wegen einer geologischen Seltenheit an: Sie ist der Hauptort im Krater, an dem eigentümliche Rote Machtkristalle aus dem fruchtbaren Boden ragen. Die purpurnen Formationen summen vor urzeitlicher Energie, ähnlich den blauen, grünen und gelben Kristallen, die man anderswo im Becken findet. Lange genug zu überleben, um sie zu sammeln, bedeutet jedoch, sich mit den uneingeschränkten Herrschern der Ebenen anzulegen – darunter nistende Teufelssaurier, die im tiefen Süden keinerlei Eindringlinge dulden."}},faq={{q="Warum heißt dieses Gebiet Terrorflucht?",a="Der Name spiegelt die tödliche Konzentration von Spitzenprädatoren wider, die diesen offenen Korridor durchstreifen. Angesichts riesiger Teufelssaurier, territorialer Diemetradons und wachsamer Pterrordaxe, die über den Köpfen kreisen, muss jeder, der die Ebene zu Fuß durchquert, damit rechnen, um sein Leben rennen zu müssen.",al={"terrorflucht namensbedeutung","warum terrorflucht","wer benannte terrorflucht"}},{q="Was kann man hier neben gefährlichen Bestien noch finden?",a="Die Terrorflucht ist die einzige Region im Krater von Un'Goro, in der Rote Machtkristalle aus der Erde geborgen werden können. Zudem könnt Ihr an ihrem östlichen Rand ein verlassenes Forschungslager finden, das von Williden Marschalls Expedition während ihrer gefährlichen Erkundung des Kraters zurückgelassen wurde.",al={"was gibt es in der terrorflucht","terrorflucht kristalle","terrorflucht ressourcen"}},{q="Was hat es mit dem verlassenen Lager am östlichen Rand auf sich?",a="Das verlassene Lager gehörte Mitgliedern von Williden Marschalls Expedition. Die Wissenschaftler und Forscher sahen sich gezwungen, ihre Forschungsausrüstung im Stich zu lassen und zu fliehen, als die einheimische Tierwelt ihre Stellung überrannte.",al={"marshals lager terrorflucht","verlassenes forschungslager","verlorenes expeditionslager"}},{q="Wo liegt die Terrorflucht im Verhältnis zu anderen Orientierungspunkten?",a="Sie erstreckt sich über den südwestlichen Krater von Un'Goro, unmittelbar westlich der von Silithiden verseuchten Bauten namens Die wuchernde Narbe und südlich des zentralen Vulkans, Feuersäulengrat.",al={"terrorflucht lage","wo liegt terrorflucht"}}},fp="10,310,18.617.0,34.534.0,35.276.0,48.257.0,47.214.0,57.172.0"}
P.entries["subzone:terror-wing-path"] = {n="Schreckenspfad",s="Der Schreckenspfad ist ein felsiger Canyon, der sich durch die östlichen Ausläufer der Brennenden Steppe schlängelt. Er wird von Welpen und Drachkin des Schwarzen Drachenschwarms heimgesucht und dient als gefährlicher Zugang in den entlegenen nordöstlichen Winkel der Steppe.",h="Der Schreckenspfad ist ein felsiger Canyon, der sich durch die östlichen Ausläufer der Brennenden Steppe...",kw={"schwarzer drachenschwarm","brennende steppe","drachkin","rotkammpass","schreckenspfad","welpen"},ang={["class:Hunter"]="Das steile Gelände und die fliegenden Welpen machen den Schreckenspfad zu einem Prüffeld für Scharfschützen, die drakonische Bestien zwischen Rauch und Canyonwinden aufspüren."},sec={{t="Ein Nistplatz der Drachkin",b="In die schroffen, aschebedeckten Ausläufer der östlichen Brennenden Steppe geschnitten, verdankt der Schreckenspfad seinen Namen den fliegenden Raubtieren und Lindwürmern, die ihn für sich beanspruchen. Bruten des Schwarzen Drachenschwarms durchstreifen diese Hohlwege, bewachen erbittert ihre Gelege und jagen alles, was töricht genug ist, in ihren Schatten zu treten. Asche und Ruß bedecken die Steinpfade und machen jeden Marsch unter den Canyonwänden zu einem tückischen Wagnis."},{t="Eine gefährliche Passage",b="Schwarze Drachen patrouillieren entlang des Tals, und manchmal sieht man den seltenen Magmagiganten Volchan hindurchwandern. Nur die kampferprobtesten Abenteurer wagen die Reise, und selten allein, doch ist er der einzige Weg zur verborgenen Höhle von Schlitterfels im äußersten nordöstlichen Winkel der Steppe."}},faq={{q="Welche Kreaturen leben im Schreckenspfad?",a="Der Pfad wird von Welpen, Brütlingen und größeren Drachkin des Schwarzen Drachenschwarms heimgesucht. Sie patrouillieren angriffslustig an den Hängen und jagen Beute am Boden im gesamten östlichen Pass.",al={"schreckenspfad mobs","was ist hier","drachkin schreckenspfad"}},{q="Wohin führt der Schreckenspfad?",a="Er schlängelt sich durch den östlichen Teil der Brennenden Steppe in den abgelegenen nordöstlichen Winkel der Region, wo dahinter die Höhle von Schlitterfels verborgen liegt.",al={"wohin führt der schreckenspfad","schreckenspfad route","schreckenspfad weg"}},{q="Warum ist der Schwarze Drachenschwarm in diesem Canyon aktiv?",a="Der Schwarze Drachenschwarm hält die Brennende Steppe unter dem Schwarzfels fest im Griff. Der Schreckenspfad bietet Nistplätze, Jagdgründe und eine östliche Verteidigungslinie, die die Flanken des Berges schützt.",al={"warum sind drachen hier","schwarzer drachenschwarm schreckenspfad","präsenz des drachenschwarms"}}},fp="16,239,17.411.0,18.300.0,40.173.0,33.156.0,52.214.0"}
P.entries["subzone:thalassian-base-camp"] = {n="Thalassischer Stützpunkt",s="Versteckt auf einem hohen Grat im nördlichen Azshara dient der Thalassische Stützpunkt als Ausgangspunkt für eine Expedition von Blutelfen, die uralte arkanische Relikte ausgraben. Obwohl sie ursprünglich durch eine Vereinbarung mit der Horde finanziert wurde, brach die Führung des Lagers schnell ihr Wort, sobald die Grabungen begannen. Nun deuten dunklere Beschwörungspraktiken inmitten ihrer roten Pavillons und zerkleinerten magischen Artefakte auf ihre wahren Ziele hin.",h="Versteckt auf einem hohen Grat im nördlichen Azshara dient der Thalassische Stützpunkt als Ausgangspunkt für...",kw={"azshara","verraten","glitzernder staub","hawkhelm","magister hawkhelm","magus rimtori","rimtori","thalassischer stützpunkt","ursolan"},ang={["class:Mage"]="Die einzigartige Veredelung von Artefakten zu Glitzerndem Staub durch die Blutelfen bietet einen seltenen, wenn auch gefährlichen Einblick in thalassische Techniken, die selbst Erzmagier Xylem interessieren.",["faction:Horde"]="Die Horde nimmt gebrochene Eide nicht auf die leichte Schulter; Magus Rimtori nahm Euer Gold und gab nur Verrat zurück, was dieses Lager zu einem Ziel für Vergeltung macht."},sec={{t="Ein gebrochenes Abkommen",b="Die Blutelfenexpedition östlich von Ursolan sollte Reisenden aus Orgrimmar eigentlich nicht feindselig gesinnt sein. Ihre Anführerin, Magus Rimtori, handelte einen formellen Pakt mit der Horde aus: Im Austausch für Nachschublinien, Finanzierung und bewaffnetes Geleit durch die tückische Wildnis von Azshara sollten ihre Forscher alle magischen Reichtümer teilen, die sie freilegten. Doch kaum war der Stützpunkt befestigt und die ersten Relikte aus den elfischen Ruinen geborgen, brach Rimtori ihr Wort vollständig und vertrieb die Abgesandten der Horde. Während Rimtori mit einem bewaffneten Gefolge tiefer gelegene Gebiete durchkämmt, wacht Magister Hawkhelm über den Grat und verteidigt das Lager gegen Vergeltungsmaßnahmen."},{t="Staub und Dämonologie",b="Die Blutelfen kamen nicht nur her, um die Geschichte zu katalogisieren. Sie besitzen eine ungewöhnliche Technik, um geborgene magische Kuriositäten zu Glitzerndem Staub zu zermalmen – ein veredeltes Pulver, das sich deutlich von gewöhnlichen Verzauberungsrückständen unterscheidet und bereits die Neugier von Erzmagier Xylem geweckt hat. Noch beunruhigender ist, dass weiter oben auf den Graten des Lagers ein Foliant der Beschwörung der Kaldorei liegt. Weit entfernt von einer akademischen Studie über Relikte der Hochgeborenen offenbart der Foliant eine finstere Bereitschaft, den Schleier zu durchdringen und dämonische Wesen direkt in die Ruinen von Azshara zu beschwören."}},faq={{q="Warum sind hier in Azshara Blutelfen?",a="Sie sind Teil einer arkanen Ausgrabung unter der Führung von Magus Rimtori. Sie reisten durch Kalimdor, um die Ruinen des uralten Kalimdor nach mächtigen magischen Artefakten zu durchforsten, auf der Suche nach Macht, die sie nach der Zerstörung des Sonnenbrunnens ernten und absaugen können.",al={"warum gibt es blutelfen in azshara","thalassischer stützpunkt zweck","wer lebt hier"}},{q="Warum steht die Horde diesem Lager feindselig gegenüber?",a="Magus Rimtori nahm Münzen und Ressourcen der Horde unter dem Versprechen an, die Entdeckungen der Expedition zu teilen. Sobald ihre Truppen im nördlichen Azshara sicher Fuß gefasst hatten, brach sie die Vereinbarung, verweigerte jeglichen Tribut und ließ die Horde auf Rache sinnen.",al={"warum greift die horde den thalassischen stützpunkt an","magus rimtori verrat","verraten quest lore"}},{q="Wer leitet den Thalassischen Stützpunkt?",a="Die oberste Leiterin der Expedition ist Magus Rimtori, auch wenn sie oft in Begleitung persönlicher Leibwächter durch Azshara zieht. In ihrer Abwesenheit obliegt die alltägliche Führung des Lagers Magister Hawkhelm.",al={"wer hat das sagen","lagerboss","magister hawkhelm"}},{q="Was ist Glitzernder Staub?",a="Es handelt sich um einen arkanen Rückstand, der durch die spezielle Methode der Blutelfen beim Zermalmen verzauberter Relikte entsteht. Anders als der herkömmliche Staub, der beim traditionellen Entzaubern gewonnen wird, haben seine einzigartigen Eigenschaften das rege Interesse des exzentrischen Erzmagiers Xylem geweckt.",al={"magischer staub xylem","glitzernder staub lore","warum magische gegenstände zermalmen"}},{q="Was ist der Foliant der Beschwörung der Kaldorei auf dem Grat?",a="Dieser uralte Foliant thront auf einem Grat über dem Lager und kann genutzt werden, um Dämonen in die Gegend zu rufen. Seine Anwesenheit enthüllt, dass sich Rimtoris Expedition mit weitaus finstereren Dingen befasst als der einfachen historischen Bergung.",al={"buch auf dem hügel","kaldorei foliant","dämonenbuch azshara"}}},fp="20,415,18.654.0,19.532.1,36.238.0,38.249.0,35.211.0,24.271.0,52.221.0"}
P.entries["subzone:thandol-span"] = {n="Thandol-Übergang",s="Der Thandol-Übergang ist ein Paar kolossaler Zwergensteinbrücken, die das Sumpfland von Khaz Modan mit dem Arathihochland im südlichen Lordaeron verbinden. Lange Zeit als Wunder der Ingenieurskunst und lebenswichtige Verkehrsader zwischen den nördlichen und südlichen Königreichen gefeiert, befindet er sich nach einem Sabotageakt von Dunkeleiseneindringlingen gegenwärtig in einem Zustand der Zerstörung.",h="Der Thandol-Übergang ist ein Paar kolossaler Zwergensteinbrücken, die das Sumpfland von Khaz Modan mit dem...",kw={"arathihochland","balgaras","dunkeleisen","dun modr","eisenschmiede","kam tiefenzorn","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Der Übergang ist die einzige direkte Überlandverbindung, die Khaz Modan mit den bedrängten nördlichen Außenposten von Lordaeron vereint, was seine Verteidigung für die Kriegsanstrengungen unverzichtbar macht.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede stellt der Übergang sowohl ein Meisterwerk ihrer Steinmetze dar als auch ein schmerzhaftes Schlachtfeld, auf dem ihnen verwandte Dunkeleisenzwerge die Zerstörung direkt vor die Haustür brachten."},sec={{t="Eine durchtrennte Lebensader",b="Nach dem Krieg der drei Hämmer erbaut, um Eisenschmiede mit dem Wildhammerklan des Nistgipfel zu verbinden, gehört der Thandol-Übergang zu den großartigsten Steinmetzleistungen der Zwergengeschichte. In der Lage, ganze marschierende Armeen zu tragen, diente er während des gesamten Zweiten Krieges als entscheidender Landkorridor zwischen Lordaeron und Khaz Modan und trug insbesondere Sir Anduin Lothars Gegenoffensive nach Süden. Heute ist der Übergang schwer gezeichnet. Dunkeleisensaboteure unter der Führung von Balgaras the Foul und Kam Tiefenzorn starteten einen verheerenden Angriff vom nahe gelegenen Dun Modr aus, zerstörten eine der Brücken vollständig mit Sprengstoff und drohten, den Überlandverkehr zwischen den verbündeten Reichen gänzlich zu unterbrechen."},{t="Der Kampf um die Überquerung",b="Die verbliebene Brücke ist weiterhin umkämpft und schwer bewacht. Gebirgsjäger aus Eisenschmiede kämpfen verzweifelt darum, die verbleibende Fahrbahn zu sichern und Pioniere der Dunkeleisenzwerge abzuwehren, wobei sie schmerzhafte Verluste erleiden. Der Verlust der Brücke würde den nördlichen Handel und militärische Verlegungen fast vollständig von Seewegen abhängig machen und die im Arathihochland stationierten Streitkräfte der Allianz von unmittelbarer Verstärkung abschneiden."}},faq={{q="Was ist der Thandol-Übergang?",a="Er ist eine gewaltige doppelbogige Steinbrücke der Zwerge, die die tiefe Schlucht zwischen dem Sumpfland im nördlichen Khaz Modan und dem Arathihochland im südlichen Lordaeron überspannt.",al={"thandol-übergang übersicht","was ist diese brücke","thandol-brücke"}},{q="Warum ist eine der Brücken zerstört?",a="Dunkeleisenzwerge starteten einen Angriff vom eroberten Außenposten Dun Modr aus und setzten hochexplosiven Sprengstoff ein, um einen der beiden Bögen zu sprengen und so die Nachschublinien der Allianz zu kappen.",al={"wer hat die brücke gesprengt","thandol-übergang zerstört","warum ist der thandol-übergang kaputt"}},{q="Warum wurde der Thandol-Übergang ursprünglich erbaut?",a="Die Zwerge von Eisenschmiede erbauten den Übergang nach dem Krieg der drei Hämmer, um Handel, Diplomatie und dauerhafte Bande mit ihren Wildhammer-Vettern zu pflegen, die jenseits der Schlucht im Norden lebten.",al={"wer baute den thandol-übergang","geschichte des thandol-übergangs","warum wurde er gebaut"}},{q="Überquerten im Zweiten Krieg Armeen diesen Ort?",a="Ja. Obwohl die Alte Horde die Brücken umging, indem sie das Meer überquerte, um in Lordaeron einzufallen, führte Sir Anduin Lothar später die Gegenoffensive der Allianz über den Übergang, um die Orcs zurück nach Khaz Modan zu drängen.",al={"thandol-übergang zweiter krieg","orcs am thandol-übergang","lothar thandol-übergang"}}},fx={a33b8b45={q="Ist der Thandol-Übergang gefährlich?",a="Ja, das Reisen über den Übergang ist gefährlich. Dunkeleisensaboteure sind kürzlich in die Schlucht eingedrungen und haben Sprengstoff gezündet, wodurch einer der beiden Zwillingsbögen vollständig durchtrennt wurde und der verbleibende Teil des Übergangs anfällig ist. Feindliche Dunkeleisenzwerge halten sich in der Nähe im nördlichen Sumpfland und um Dun Modr auf und planen aktiv weitere Angriffe auf Reisende und Verteidiger aus Eisenschmiede, die die Stellung halten.",al={"ist der thandol-übergang sicher","gefahr am thandol-übergang","bedrohungen am thandol-übergang"}}},fp="12,349,18.687.0,26.422.0,25.167.0,33.175.0,42.182.0,44.204.0"}
P.entries["subzone:the-den"] = {fx={e0991dfb={q="Was ist The Den?",a="The Den ist die höhlenartige Operationsbasis im Tal der Prüfungen, gelegen in der südwestlichen Ecke von Durotar. Er dient als primäres Sammellager für junge Orc-Novizen, die sich als würdig für die Horde erweisen wollen. Drinnen lehren Ausbilder die Grundlagen verschiedener Künste, Händler verkaufen wichtige Vorräte und lokale Anführer verteilen Prüfungen, um ankommende Rekruten zu testen, bevor sie sich in die weitere Welt hinauswagen.",al={"was ist the den","the den durotar","über the den"}},ac46dd9b={q="Ist The Den gefährlich?",a="The Den selbst ist stark bewacht und für Mitglieder der Horde recht sicher, geschützt durch Den-Grunzer und erfahrene Aufseher. Die wirklichen Gefahren lauern draußen, wo Bestien und Stacheleber durch das Tal der Prüfungen streifen.",al={"ist the den gefährlich","ist es sicher in the den","bedrohungen in the den"}}}}
P.entries["subzone:the-loch"] = {n="Der Loch",s="Der Loch ist der gewaltige Süßwassersee, der das Tal von Loch Modan beherrscht. Zurückgehalten durch den monumentalen Steinwerkdamm, ist er das größte Gewässer auf Khaz Modan und die Lebensader der umliegenden Zwergensiedlungen.",h="Der Loch ist der gewaltige Süßwassersee, der das Tal von Loch Modan beherrscht.",kw={"khaz modan","see","loch modan","der steinwerkdamm","der loch","thelsamar","dreschadon","sumpfland"},ang={["faction:Alliance"]="Die ruhigen Gewässer des Lochs bieten lebenswichtiges Süßwasser und Handelsrouten zwischen dem zentralen Tal von Eisenschmiede und den umliegenden Außenposten.",["race:Dwarf"]="Der Loch ist ein Aushängeschild des Stolzes von Eisenschmiede und zeigt, wie zwergische Steinmetzkunst und der Steinwerkdamm die Natur zähmen können, um Siedlungen wie Thelsamar zu versorgen."},sec={{t="Das Herz des Tals",b="Im Zentrum von Loch Modan gelegen, zählt der Loch zu den größten Binnenseen der bekannten Welt, der nur vom Lordameresee und dem Darrowmeresee im Norden übertroffen wird. Seine Gewässer ernähren die einheimischen Fischer und bieten eine friedliche Kulisse für die Stadt Thelsamar sowie die nahe gelegenen Jagdhütten. Unter seiner ruhigen Oberfläche lauern jedoch aggressive Dreschadon und Süßwasserbestien, die das Durchschwimmen zu einem gefährlichen Wagnis machen."},{t="Die Barriere von Stonewrought",b="Der Loch existiert in seinem heutigen, ruhigen Zustand dank meisterhafter zwergischer Ingenieurskunst. Im Norden erhebt sich der massive Steinwerkdamm, ein architektonisches Wunderwerk, das über der Bergschlucht errichtet wurde, um zu verhindern, dass der See in das darunterliegende Sumpfland abfließt. Die Instandhaltung dieses kolossalen Bauwerks ist unerlässlich, um das Ökosystem des Tals zu bewahren und die Sicherheit von Khaz Modan zu gewährleisten."}},faq={{q="Was ist der Loch?",a="Der Loch ist der gewaltige Bergsee, der das Zentrum des Tals von Loch Modan in Khaz Modan ausfüllt. Er ist eines der größten Süßwassergewässer der Welt und prägt die Geografie sowie den Lebensunterhalt der dortigen Zwerge.",al={"der loch geschichte","was ist der loch see","loch modan see"}},{q="Warum läuft der See nicht aus?",a="Der See wird im Norden durch den Steinwerkdamm aufgestaut, ein hoch aufragendes zwergisches Bauwerk. Der Damm hält zahllose Gallonen Wasser zurück, die andernfalls durch den Gebirgspass in das tiefer gelegene Sumpfland strömen würden.",al={"warum fließt der loch nicht ab","was staut den loch","stonewroughtdamm zweck"}},{q="Ist es sicher, im Loch zu schwimmen?",a="Nicht gänzlich. Während die Küsten und Stege von einheimischen Fischern gesäumt sind, beherbergen die tieferen Gewässer räuberische Dreschadon und schnappende Bestien, die unvorsichtige Reisende, die sich zu weit vom Ufer entfernen, oft angreifen.",al={"loch ungeheuer","im loch schwimmen","kreaturen im loch"}},{q="Wie groß ist der Loch im Vergleich zu anderen Seen?",a="Er ist das größte Gewässer auf dem Kontinent Khaz Modan und der drittgrößte bekannte See in den Östlichen Königreichen, nur übertroffen vom Lordameresee und dem Darrowmeresee in Lordaeron.",al={"größter see","der loch größenvergleich","wie groß ist der loch"}}},fp="8,227,19.414.0,24.373.0,17.221.0,28.225.0,31.194.0,46.181.0"}
P.entries["subzone:thelgen-rock"] = {n="Thelgenfelsen",s="Der Thelgenfelsen ist ein weitläufiges Höhlensystem, das in die südliche Bergwand des Sumpflands geschlagen ist. Von giftigen Spinnen verseucht, ist er dafür berüchtigt, seltene Adern des flüchtigen Pyrophorerzes zu beherbergen.",h="Der Thelgenfelsen ist ein weitläufiges Höhlensystem, das in die südliche Bergwand des Sumpflands geschlagen...",kw={"höhle","pyrophorerz","spinnenhöhle","spinnen","thelgenfelsen","sumpfland"},ang={["profession:Mining"]="Die tiefen Tunnel des Thelgenfelsens beherbergen seltene Vorkommen von Pyrophorerz und locken Schürfer in die Gefahr unter dem Berg."},sec={{t="Eine netzverhangene Höhle",b="Eingebettet in die südlichen Berge, die das Sumpfland von Loch Modan trennen, ist der Thelgenfelsen ein tiefes unterirdisches Höhlennetzwerk, das von aggressiven Spinnentieren überrannt wird. Die Gänge sind dicht mit Netzen verhangen und wimmeln von giftigen Spinnen, was das Betreten der Höhlen für Reisende extrem gefährlich macht. Trotz des Befalls trotzen Bergleute und Abenteurer seinen Tiefen wegen der wertvollen Vorkommen an Pyrophorerz, die in den felsigen Tunneln eingebettet liegen."}},faq={{q="Was macht den Thelgenfelsen gefährlich?",a="Die Höhlen des Thelgenfelsens sind dicht von großen, giftigen Spinnen bewohnt. Reisende, die sich in die gewundenen Tunnel wagen, können sich inmitten der Netze leicht in die Enge getrieben und von giftigen Bissen überwältigt wiederfinden.",al={"thelgenfelsen gefahren","warum ist der thelgenfelsen gefährlich","spinnen im thelgenfelsen"}},{q="Warum kommen Schürfer und Bergleute hierher?",a="Das Höhlensystem birgt reiche Adern von Pyrophorerz, einem feurigen und flüchtigen Mineral, das von zwergischen Schürfern und Ingenieuren begehrt wird. Trotz des Spinnenbefalls wagen sich kühne Bergleute hinein, um Proben aus den Höhlenwänden zu gewinnen.",al={"warum den thelgenfelsen besuchen","erz im thelgenfelsen","pyrophorerz"}},{q="Wo befindet sich der Thelgenfelsen?",a="Der Thelgenfelsen liegt entlang des südlichen Gebirgszuges des Sumpflands, südlich der Hauptstraße, die den Hafen von Menethil mit dem Gebirgspass Dun Algaz verbindet.",al={"thelgenfelsen lage","wo liegt der thelgenfelsen"}}},fx={["10e18c06"]={q="Was ist der Thelgenfelsen?",a="Der Thelgenfelsen ist ein weitläufiges Höhlensystem, das tief in die südlichen Berge des Sumpflandes gegraben wurde. Er ist unter Bergleuten weithin bekannt für seine reichen Vorkommen an Pyrophorerz, doch das Abbauen von irgendetwas erfordert hier, den giftigen Spinnenschwärmen zu trotzen, die jeden Schatten und Tunnel im Inneren für sich beansprucht haben.",al={"was ist der thelgenfelsen","was ist der ort thelgenfelsen","thelgenfelsen höhle"}},ba9bab1c={q="Ist der Thelgenfelsen gefährlich?",a="Ja, er ist extrem gefährlich. Die Höhlen sind von aggressiven, giftigen Spinnen befallen, die jede Schürfexpedition zu einem tödlichen Unterfangen machen. Entdecker und Bergleute, die nach den seltenen Mineraladern suchen, müssen ständig die dunklen Höhlen im Auge behalten, um nicht von Gift und Spinnweben überwältigt zu werden.",al={"wie gefährlich ist der thelgenfelsen","gefahr im thelgenfelsen","ist der thelgenfelsen sicher"}}},fp="12,197,19.443.0,34.212.0,40.227.0,30.153.0"}
P.entries["subzone:thelsamar"] = {n="Thelsamar",s="Thelsamar ist die wichtigste Zwergensiedlung in Loch Modan, eingebettet auf den westlichen Klippen mit Blick auf den großen See. Gelegen an der Hauptstraße zwischen Dun Morogh und dem Sumpfland, dient es als geschäftiger Knotenpunkt für Handel, Gastfreundschaft und zivile Verteidigung gegen Übergriffe der umliegenden Troggs und Oger.",h="Thelsamar ist die wichtigste Zwergensiedlung in Loch Modan, eingebettet auf den westlichen Klippen mit Blick...",kw={"blutwürste","grautatze","loch modan","gebirgsjäger","splitterstein","gasthof zum starkbier-lager","thelsamar"},ang={["profession:Cooking"]="Kulinarische Reisende machen oft im Gasthof Zum Starkbier-Lager Halt, um das regionale Rezept für herzhafte Blutwürste aus dem Fleisch einheimischer Bären, Spinnen und Eber zu erlernen.",["race:Dwarf"]="Für Zwerge, die das kalte Dun Morogh verlassen, ist Thelsamar der erste Vorgeschmack auf wärmere Tiefebenen, der mit großartigem Bier, robusten Steinherden und aktivem Dienst für die Gebirgsjägergarde aufwartet."},sec={{t="Herz von Loch Modan",b="Thelsamar dient als zentrale Bastion des zivilen Zwergenlebens im Tal. Erbaut in traditioneller Khaz Modan-Stein- und Holzarchitektur, bietet es den lebhaften Gasthof Zum Starkbier-Lager, einen eigenen Gryphon Roost, Handwerksstationen und verschiedene Versorgungshändler. Da es direkt an der Durchgangsstraße liegt, die den Südtorpass nach Dun Morogh mit dem Algaz-Pass in Richtung Sumpfland verbindet, kommen fast alle Reisenden durch die Region an seinen warmen Herdfeuern und robusten Dächern vorbei."},{t="Ärger an der Grenze",b="Trotz seiner behaglichen Annehmlichkeiten schwebt Thelsamar in ständiger Gefahr. Im Süden bedrohen Troggs, die aus dem Splittersteintal strömen, das Umland der Stadt, während Bären und Raubtiere den Grautatzengrat heimsuchen. Da die regulären Streitkräfte von Eisenschmiede im gesamten Reich überfordert sind, verlassen sich der örtliche Magistrat und die Gebirgsjäger stark auf reisende Abenteurer und Mercenaries, um die Handelsstraßen zu patrouillieren und vordringende Feinde zurückzuschlagen."}},faq={{q="Welche Dienste sind in Thelsamar verfügbar?",a="Thelsamar bietet eine vollständige Palette an Grenzannehmlichkeiten, darunter den Gasthof Zum Starkbier-Lager für Unterkunft und Erfrischung, einen Flugmeister mit Verbindungen durch ganz Zentral-Khaz Modan, Händler und eine Schmiede im Freien. Es beherbergt auch mehrere Berufs- und Kampflehrer, um aufstrebenden Abenteurern zu helfen.",al={"thelsamar händler","was gibt es in thelsamar","lehrer in thelsamar"}},{q="Wohin führt die Straße durch Thelsamar?",a="Die von Nord nach Süd verlaufende Straße westlich der Stadt schließt im Süden durch den Tunnel an Dun Morogh an und führt geradewegs nach Eisenschmiede. Folgt man ihr nach Norden, führt sie Reisende durch das Algaz-Tor hinunter in das feuchte Sumpfland.",al={"thelsamar straße","wohin führt der weg","reisen ab thelsamar"}},{q="Warum heuert die Stadt so viele Söldner an?",a="Die örtlichen Gebirgsjäger sind von mehreren aufkommenden Bedrohungen überwältigt. Aggressive Splitterstein-Troggs haben die südlichen Ausgrabungsstätten überrannt, wilde Bestien streifen an den Rändern der Siedlung umher und organisierte Oger beginnen vorzudringen, was die Stadtführung dazu zwingt, Kopfgelder für unabhängige Kämpfer auszuloben.",al={"warum gibt es quests in thelsamar","wer greift thelsamar an"}},{q="Was ist die berühmte lokale Spezialität hier?",a="Die Stadt ist unter Jägern und Reisenden für Thelsamar Blood Sausages bekannt, ein herzhaftes Zwergengericht, das von Vidra Ofenglut im Gasthof Zum Starkbier-Lager aus den Innereien und dem Fleisch einheimischer Wildtiere zubereitet wird.",al={"thelsamar essen","blutwürste loch modan"}}},fx={["19f21b39"]={q="Was ist Thelsamar?",a="Thelsamar ist die wichtigste Siedlung der Zwerge in Loch Modan und liegt eingebettet auf den westlichen Klippen mit Blick auf den See. Die Stadt liegt direkt an der wichtigen Nord-Süd-Straße, die Dun Morogh mit dem Sumpfland verbindet, und dient als zentraler Knotenpunkt für Reisende in den Bergen, Händler und die Gebirgswächter-Patrouillen, die das Tal verteidigen.",al={"stadt thelsamar","was ist diese stadt","erzählt mir etwas über thelsamar"}},a244cff7={q="Wer lebt in Thelsamar oder verwaltet es?",a="Thelsamar wird von Bronzebart-Zwergen bewohnt und untersteht der zivilen Autorität von Magistrat Bluntnose, der lokale Angelegenheiten regelt und Hilfe von außen anfordert, um mit den umliegenden Bedrohungen fertigzuwerden. Die Stadt wird aktiv von zwergischen Gebirgswächtern und Wachen geschützt, die dem militärischen Kommando von Eisenschmiede unterstellt sind.",al={"wer führt thelsamar an","wer leitet thelsamar","thelsamar anführer"}},c5fc67c9={q="Ist Thelsamar gefährlich?",a="Die Stadt selbst ist sicher und wird von Gebirgswächtern gut bewacht, doch die umliegende Wildnis birgt ernsthafte Gefahren. Trogg-Einfälle aus dem Splittersteintal bedrohen nahegelegene Farmen, im Süden streifen Bären umher und Oger aus der Festung Mo'grosh drängen vor, was die Stadt dazu zwingt, sich auf reisende Abenteurer zu verlassen, um den Umkreis zu sichern.",al={"ist thelsamar sicher","bedrohungen für thelsamar","gefahr thelsamar"}}},fp="9,303,19.471.0,23.430.0,41.290.0,43.220.0,43.293.0,40.198.0"}
P.entries["subzone:thistlefur-hold"] = {fx={["36b0fa4f"]={q="Wer lebt in Thistlefur Hold?",a="Die höhlenartige Festung beherbergt die Hauptbevölkerung des Furbolgstamms der Thistlefur. Während sie einst harmonisch inmitten der uralten Wälder des Eschentals lebten, bewachen diese verdorbenen Furbolgs nun erbittert ihre unterirdischen Bauten gegen alle Eindringlinge und zeigen sich feindselig gegenüber Nachtelfen, Reisenden der Horde und allen anderen, die ihre Schwelle überschreiten.",al={"wer lebt in thistlefur hold","bewohner von thistlefur hold","wer ist in thistlefur hold"}}}}
P.entries["subzone:thistlefur-village"] = {n="Lager der Distelfelle",s="Das Lager der Distelfelle ist eine weitläufige Siedlung, die nördlich von Astranaar im westlich-zentralen Eschental im Wald verborgen liegt. Es dient dem Furbolgstamm der Thistlefur als Hauptwohnsitz, der einer finsteren Verderbnis anheimgefallen ist und jeden Außenstehenden gewaltsam angreift, der sich seinen Höhlen nähert.",h="Das Lager der Distelfelle ist eine weitläufige Siedlung, die nördlich von Astranaar im westlich-zentralen...",kw={"eschental","astranaar","verderbnis","dal bloodclaw","furbolg","rorgish jowl","thistlefur","dorf"},ang={["class:Druid"]="Der gefallene Zustand des Stammes der Thistlefur dient als düstere Mahnung an das anhaltende Verderben, das die Geister und die Tierwelt von Eschental heimsucht, und verlangt nach wachsamer Läuterung durch den Zirkel des Cenarius.",["race:NightElf"]="Jahrhundertelang lebten die Nachtelfen in Eintracht mit den einheimischen Furbolgstämmen zusammen. Zu sehen, wie die Thistlefur so nahe bei Astranaar gewaltsamer Verderbnis anheimfallen, ist für die Schildwachen sowohl eine Herzensqual als auch eine ernste Sicherheitskrise."},sec={{t="Ein verdorbener Bau",b="Direkt nördlich der Nachtelfenzuflucht Astranaar gelegen, war das Lager der Distelfelle einst Teil der friedlichen Waldgemeinschaften von Eschental. Doch die bösartige Verderbnis, die in die uralten Wälder eingesickert ist, hat den Stamm der Thistlefur vollkommen ergriffen. Nun völlig dem Wahnsinn verfallen und überaus feindselig, bewachen die Furbolgs erbittert die Pfade, die sich durch ihre Siedlung schlängeln. Der Clan untersteht zwei außergewöhnlich wilden Häuptlingen, Dal Bloodclaw und Rorgish Jowl, deren unnachgiebige Aggression eine ständige Bedrohung für Reisende und nahegelegene Siedlungen darstellt."}},faq={{q="Wo befindet sich das Lager der Distelfelle?",a="Das Lager der Distelfelle liegt in den westlich-zentralen Gefilden von Eschental, tief eingebettet in die bewaldeten Hügel direkt nördlich der Nachtelfenstadt Astranaar.",al={"lager der distelfelle ort","wo ist distelfelle","karte distelfelle"}},{q="Warum greifen die Furbolgs hier Reisende an?",a="Die Furbolgs der Thistlefur wurden von der finsteren Verderbnis erfasst, die sich in den Wäldern von Eschental ausbreitet. Durch diese finsteren Einflüsse in den Wahnsinn getrieben, betrachten sie alle Außenstehenden als unmittelbare Feinde und greifen jeden an, der sich ihrem Territorium nähert.",al={"warum sind distelfelle feindselig","verdorbene furbolgs distelfelle","warum angriff"}},{q="Wer führt die Furbolgs der Thistlefur an?",a="Der Stamm wird von zwei besonders wilden und brutalen Kriegshäuptlingen namens Dal Bloodclaw und Rorgish Jowl angeführt, die eine grausame Vorherrschaft über das Dorf und die umliegenden Höhlen ausüben.",al={"distelfelle boss","distelfelle anführer","wer führt distelfelle"}},{q="Stellt das Lager der Distelfelle eine Gefahr für Astranaar dar?",a="Ja. Da das Lager der Distelfelle unmittelbar nördlich von Astranaar liegt, macht das aggressive und unberechenbare Wesen der verdorbenen Furbolgs sie zu einer ständigen Gefahr für Späher der Nachtelfen, Nachschublinien und Schildwachen, die entlang der zentralen Straßen stationiert sind.",al={"bedrohung durch distelfelle für astranaar","gefahr für astranaar"}}},fx={["840d1e44"]={q="Was ist das Lager der Distelfelle?",a="Das Lager der Distelfelle ist eine Furbolg-Siedlung im westlichen Zentrum des Eschentals, direkt nördlich von Astranaar. Es dient als primäres Zuhause und Festung für den Stamm der Thistlefur, eine Gruppe von Furbolgs, die der dunklen Verderbnis zum Opfer gefallen ist, die sich durch den Wald ausbreitet.",al={"infos zum lager der distelfelle","was ist thistlefur","lore zum lager der distelfelle"}},["7a812bcb"]={q="Ist das Lager der Distelfelle gefährlich?",a="Das Lager der Distelfelle ist für jeden Reisenden außergewöhnlich gefährlich. Vom Wahnsinn durch die Verderbnis getrieben, sind die ansässigen Furbolgs extrem territorial und greifen jeden, der in die Nähe ihrer Grenzen wandert, gewaltsam an. Das Lager wird von furchterregenden Kriegern und Schamanen unter dem rücksichtslosen Kommando von Dal Bloodclaw und Rorgish Jowl gut verteidigt.",al={"wie gefährlich ist das lager der distelfelle","ist thistlefur sicher","gefahr lager der distelfelle"}},fc97bd16={q="Wer lebt im Lager der Distelfelle?",a="Das Lager wird ausschließlich vom Furbolgstamm der Thistlefur bewohnt. Einst friedliche Waldbewohner, leben diese verdorbenen Furbolgs nun unter der brutalen Führung zweier wilder Häuptlingsgestalten, Dal Bloodclaw und Rorgish Jowl, die ihre Verteidigung und ihre Überfälle organisieren.",al={"wer lebt im lager der distelfelle","thistlefur bewohner","wer lebt bei den thistlefur"}}},fp="18,279,15.565.0,36.158.0,46.239.0,34.180.0,51.243.0"}
P.entries["subzone:thistlefuzz-arcanery"] = {n="Thistlefuzz Arcanery",s="Thistlefuzz Arcanery ist eine bedeutende Werkstatt und Akademie der magischen Künste östlich der Großen Schmiede in Eisenschmiede. Sie wird vor allem von Gnomen betrieben und dient als wichtigster Zufluchtsort der Hauptstadt für Verzauberer und Gelehrte, die Magie in Metall und Pergament einweben möchten. Ihre geschäftigen Hallen summen von arkaner Energie direkt neben den tosenden Feuern der Zwergenindustrie.",h="Thistlefuzz Arcanery ist eine bedeutende Werkstatt und Akademie der magischen Künste östlich der Großen...",kw={"arkan","verzauberer","verzauberkunst","gnom","die große schmiede","eisenschmiede","thistlefuzz arcanery"},ang={["class:Mage"]="Besuchende Magier finden hier vertraute Reagenzien, ruhige Ecken für theoretische Studien und gleichgesinnte Zauberwirker inmitten der ansonsten kriegerischen, waffenfokussierten Hallen der Zwergenhauptstadt.",["race:Gnome"]="Für in Eisenschmiede lebende Gnome ist Thistlefuzz Arcanery eine willkommene Erinnerung an ihre Liebe zu arkaner Theorie, technischer Forschung und feinfühligen Experimenten inmitten einer Stadt, die von schwerem Zwergeneisen dominiert wird."},sec={{t="Arkane Handwerkskunst im Berg",b="Direkt östlich der donnernden Großen Schmiede gelegen, bietet Thistlefuzz Arcanery einen deutlichen Kontrast zu den klirrenden Ambossen der Zwergenschmiede. Auf ihren zwei Ebenen versammeln sich Gelehrte, Praktizierende und Lehrlinge, um die feinsinnigen Disziplinen der Verzauberkunst und des magischen Studiums zu meistern. Während die Zwerge von Eisenschmiede es vorziehen, Stahl durch Muskelkraft und Feuer umzuformen, demonstrieren die Gnome der Arcanery, wie rohe arkane Energie direkt in Waffen, Rüstungen und kuriose Werkzeuge gebunden werden kann. Sie ist ein unverzichtbarer Zufluchtsort für Zauberwirker, die sich durch die Bergfeste bewegen."}},faq={{q="Wo befindet sich Thistlefuzz Arcanery?",a="Thistlefuzz Arcanery liegt am östlichen Ring der Großen Schmiede im Zentrum von Eisenschmiede und ist leicht an den arkanen Apparaturen sowie den Verzauberkunst-Bedarfsgütern zu erkennen, die um ihre Türen ausgestellt sind.",al={"arcanery standort","wo ist thistlefuzz","eisenschmiede verzauberkunstladen"}},{q="Welche Dienste werden in der Arcanery angeboten?",a="Das Geschäft richtet sich an Ausübende magischer Handwerke. Verzauberkunstlehrer, Händler für Zauberhandwerk und Gelehrte versammeln sich hier, um Lehrlinge auszubilden, mit seltenen Reagenzien zu handeln und Experimente abseits des physischen Rußes der Schmieden durchzuführen.",al={"was gibt es in thistlefuzz arcanery","lehrer in thistlefuzz"}},{q="Warum befindet sich eine arkane Werkstatt so nah an der Großen Schmiede?",a="Die Platzierung einer Verzauberungswerkstatt direkt neben der Großen Schmiede ist überaus praktisch. Frisch geschmiedete Klingen, Rüstungsplatten und mechanische Komponenten aus den Händen der Zwergenschmiede können sofort nach Osten gebracht werden, um mit schützenden Verzauberungen und elementarer Macht erfüllt zu werden.",al={"warum nahe der schmiede","arcanery die große schmiede verbindung"}}},fx={b65c06f3={q="Was ist die Thistlefuzz Arcanery?",a="Die Thistlefuzz Arcanery ist eine arkanistische Werkstatt und ein Geschäft, das direkt östlich der Großen Schmiede im Herzen von Eisenschmiede liegt. Während in der umliegenden Stadt das Klopfen von Ambossen und flüssigem Eisen widerhallt, richtet sich diese ruhige Einrichtung an Praktizierende der mystischen Künste und bietet Ausbildung sowie Vorräte für angehende Verzauberer.",al={"thistlefuzz arcanery","was ist die thistlefuzz arcanery","arcanery in eisenschmiede"}},ddf479e1={q="Ist die Thistlefuzz Arcanery gefährlich?",a="Keineswegs, vorausgesetzt, Ihr seid in Eisenschmiede willkommen. Die Arcanery ist ein friedlicher Handwerksladen, der von den Stadtwachen und den Behörden von Eisenschmiede geschützt wird. Solange Ihr der Allianz nicht feindselig gegenübersteht, könnt Ihr ohne Angst vor Schaden in den Regalen stöbern und Euch mit den dort Praktizierenden unterhalten.",al={"ist die thistlefuzz gefährlich","gefahr thistlefuzz arcanery"}}},fp="20,374,28.565.0,38.185.0,46.231.0,63.264.0"}
P.entries["subzone:thistleshrub-valley"] = {n="Disteltal",s="Versteckt in den südwestlichen Ausläufern von Tanaris liegt das Disteltal, eine bizarre Oase stacheligen Pflanzenlebens inmitten endloser Dünen. Die Schlucht ist bekannt für ihren sonderbaren Hain aus riesigen Kakteen und feindseligen, belebten Distelsträuchern, die jeden angreifen, der ihr dornenüberwuchertes Territorium betritt.",h="Versteckt in den südwestlichen Ausläufern von Tanaris liegt das Disteltal, eine bizarre Oase stacheligen...",kw={"kakteen","kaktus","wüste","tanaris","distelbusch","dornen","uldum","tal"},ang={["class:Druid"]="Druiden dürften die bösartig belebten Distelsträucher faszinierend finden und darüber nachsinnen, welche urzeitlichen oder elementaren Kräfte sie in einer ansonsten trostlosen Wüste gedeihen lassen.",["profession:Herbalism"]="Das Tal ist für Kräuterkundige auf der Durchreise durch Tanaris eine Anomalie, da es inmitten dichter Haine dornigen Gestrüpps eine eigentümliche und widerstandsfähige Wüstenflora beherbergt."},sec={{t="Ein Hain aus Dornen",b="Während der Großteil von Tanaris ein trockenes Ödland bar jeglicher Vegetation ist, strotzt das Disteltal auf merkwürdige Weise vor Leben. Riesige blühende Kakteen ragen über den Boden der Schlucht empor und bilden einen scharfen Kontrast zum umgebenden Sandmeer. Doch dies ist kein friedlicher Zufluchtsort. Das Tal hat seinen Namen von den feindseligen, lebendigen Pflanzenkreaturen, die im Dickicht lauern. Diese Distelsträucher schlagen mit rasiermesserscharfen Dornen nach jedem Reisenden, der sich ihnen nähert, was den Weg für jene gefährlich macht, die versuchen, an den Klippen vorbei in Richtung der geheimnisvollen südlichen Tore vorzudringen."},{t="Schildwachen der Wüste",b="Die Anwesenheit einer solchen belebten Flora in einem derart trockenen Klima hat Wanderer und Wüstenüberlebenskünstler schon lange vor Rätsel gestellt. Ob nun durch vergessene Elementarenergien erweckt oder durch hartnäckige Anpassung an das raue Klima von Tanaris: Die Distelsträucher verteidigen ihr Territorium äußerst gewaltsam. Reisende, die die Schlucht durchqueren, müssen nicht nur mit diesen um sich schlagenden Dickichten aus Dornen und Wurzeln kämpfen, sondern auch mit Wüstenraubtieren und Giftschlangen, die zwischen den hoch aufragenden Kakteen nisten."}},faq={{q="Wo befindet sich das Disteltal?",a="Das Disteltal liegt eingebettet in der südwestlichen Ecke von Tanaris, eingezwängt am südlichen Gebirgszug nahe den geheimnisvollen, versiegelten Toren von Uldum.",al={"disteltal standort","wo liegt das disteltal","disteltal finden"}},{q="Warum gibt es in diesem Teil von Tanaris so viel Pflanzenleben?",a="Im Gegensatz zum Rest der kargen Wüste beherbergt das Tal ein Mikroklima, das von hoch aufragenden Kakteen und belebter Pflanzenwelt dominiert wird. Wie diese ungewöhnlichen Distelsträucher im trockenen Wüstensand derart aggressiv gedeihen können, bleibt ein anhaltendes Rätsel der südlichen Dünen.",al={"warum riesenkaktus hier","warum wachsen hier pflanzen"}},{q="Welche Kreaturen leben im Disteltal?",a="Das Tal wird von feindseligen, wandelnden Distelkreaturen, aggressiven Wüstenblüten und verschiedenen Giftschlangen heimgesucht, die sich unter der dornigen Vegetation verbergen.",al={"disteltal mobs","monster im disteltal"}},{q="Was ist das gewaltige Steinbauwerk nahe dem Tal?",a="Direkt hinter dem Tal befindet sich ein gewaltiges, versiegeltes Titanenbauwerk, das oft als das Portal nach Uldum bezeichnet wird und für Wüstenwanderer verschlossen und rätselhaft bleibt.",al={"tore nahe disteltal","titanentor tanaris"}}},fp="19,294,17.559.0,23.453.0,37.153.0,56.254.0,43.162.0,52.160.0"}
P.entries["subzone:thondroril-river"] = {n="Thondroril",s="Der Thondroril ist eine entscheidende natürliche Grenze, welche die Westlichen und Östlichen Pestländer voneinander trennt. Seinen Ursprung hat er in den Bergen des nördlichen Lordaeron nahe dem Schreckenstunnel, von wo aus seine verseuchten Wasser südwärts in den Darrowmeresee fließen. Einst ein lebendiger Handels- und Reisewasserweg des gefallenen Königreichs, wird er nun von monströsen Bestien der Geißel und der bescheidenen Zuflucht eines legendären Eremiten gesäumt.",h="Der Thondroril ist eine entscheidende natürliche Grenze, welche die Westlichen und Östlichen Pestländer...",kw={"darrowmeresee","östliche pestländer","lordaeron","schreckenstunnel","thondroril","tirion fordring","westliche pestländer"},ang={["class:Paladin"]="Das Ostufer des Thondroril bietet Tirion Fordring Zuflucht, einem Gründungsmitglied der Silbernen Hand, dessen Vermächtnis trotz seiner Verbannung fortbesteht.",["profession:Herbalism"]="Das feuchte, faulende Flussbett nährt an seinen trüben Ufern widerstandsfähige, von der Seuche berührte Flora wie Sonnengras, Arthas' Tränen und Pestblüte."},sec={{t="Ein vom Ruin gezeichneter Fluss",b="Vor dem Fall von Lordaeron diente der Thondroril als bedeutender Wasserweg, der nördliche Besitztümer in Richtung Stratholme mit dem Darrowmeresee im Süden verband. Heute markiert der Fluss die gefährliche Trennlinie zwischen den Westlichen und Östlichen Pestländern. Die Gewässer tragen die Verderbnis der Seuche in sich und an seinen Ufern wimmelt es von riesigen Maden, Pestfledermäusen, kranken Bären und räuberischen Schnappkiefern, die das einst malerische Flussbett in eine tödliche Furt für Reisende verwandeln."},{t="Wächter am Ufer",b="Obwohl die Wildnis entlang des Thondroril rau und erbarmungslos ist, fehlt es ihr nicht gänzlich an Hoffnung. Am östlichen Ufer, eingebettet in ein unscheinbares, überwuchertes Gehöft, lebt der verbannte Paladin Tirion Fordring. Vor Jahren seiner Titel beraubt und in den Untergrund gezwungen, blickt der einstige Lord aus der Ferne auf den verfaulenden Fluss und den Ruin seiner Heimat und stellt den Mut sowie das Gewissen jener Abenteurer auf die Probe, die abgehärtet genug sind, die verseuchte Grenze zu überqueren."}},faq={{q="Wo beginnt und endet der Thondroril?",a="Der Fluss entspringt in den Höhen des nördlichen Lordaeron nahe dem Eingang zum Schreckenstunnel und fließt dann südwärts durch die Pestländer, bis er direkt in den Darrowmeresee mündet. Hinter dem See setzt sich der Wasserweg nach Süden als Darrowmere River fort.",al={"thondroril verlauf","wohin fließt der thondroril","quelle des thondroril"}},{q="Welche gefährlichen Kreaturen leben an den Flussufern?",a="Die Seuche hat die einheimische Tierwelt zu tödlichen Monstrositäten mutieren lassen. Reisende treffen regelmäßig auf verschlingende Maden, kranke Pestbären, riesige Vampirfledermäuse, Gruftspinnen und Flussschnappkiefer, die an beiden Ufern lauern.",al={"monster am fluss","thondroril gegner","flussgefahren"}},{q="Wer ist der alte Mann, der am Ostufer lebt?",a="Die einsame Gestalt im verfallenen Bauernhaus am Ostufer ist Tirion Fordring, einer der ursprünglichen Ritter der Silbernen Hand. Jahre vor dem Dritten Krieg aus der Allianz verbannt, lebt er in stiller Abgeschiedenheit und beobachtet die Geißel.",al={"wer ist am fluss","alter eremit thondroril","thondroril questgeber"}},{q="Warum teilt der Fluss die beiden Pestländer?",a="Der Thondroril hat eine breite natürliche Schlucht durch das Zentrum Lordaerons gegraben. Als das Königreich unter der Herrschaft der Geißel zusammenbrach, begannen Kartografen und Überlebende, den Fluss als klare Grenze zwischen den Westlichen und Östlichen Pestländern zu betrachten.",al={"grenze westliche östliche pestländer","pestländer grenze"}}},fp="16,386,19.461.0,20.446.1,46.248.0,51.217.0,47.240.0,46.241.0"}
P.entries["subzone:thoradin-s-wall"] = {n="Thoradinswall",s="Thoradinswall ist ein monumentaler, zerfallender Steinwall, der das Arathihochland vom Vorgebirge des Hügellands trennt. Vor Jahrtausenden von König Thoradin zu Beginn des Reichs von Arathor in Auftrag gegeben, wurde er errichtet, um die frühe Menschheit vor den erbitterten Überfällen der Amani-Trolle zu schützen.",h="Thoradinswall ist ein monumentaler, zerfallender Steinwall, der das Arathihochland vom Vorgebirge des...",kw={"amani","arathi","arathor","hillsbrad","strom","thoradin","thoradinswall","wall"},ang={["race:Human"]="Vor dem Wall zu stehen ist eine ehrfürchtige Begegnung mit der menschlichen Antike und zeugt vom beständigen Mauerwerk König Thoradins, der einst die verstreuten Menschenstämme vereinte.",["race:Troll"]="Die verfallenen Befestigungen sind eine eindringliche Erinnerung an die uralten Territorialkriege, in denen die Menschheit die Herrschaft der Waldtrolle erfolgreich aufhielt."},sec={{t="Ein Bollwerk des alten Arathor",b="Vor fast dreitausend Jahren errichtet, markiert Thoradinswall die westliche Grenze des alten Strom, dem Herzen des ersten vereinten Menschenreiches. König Thoradin erkannte, dass die jungen Siedlungen der Menschheit den räuberischen Überfällen der Waldtrolle der Amani schutzlos ausgeliefert waren. Durch die Errichtung dieser gewaltigen Steinbarriere quer durch den Talkorridor sicherte Arathor sein Kernland und schuf eine verteidigungsfähige Bastion, von der aus die Menschheit überleben und schließlich die Vorherrschaft der Trolle im Norden anfechten konnte."},{t="Jahrhunderte des Verfalls",b="Heute befindet sich die uralte Barriere in einem Zustand schweren Verfalls. Gewaltige Breschen klaffen im steinernen Wall, dessen Zinnen durch Tausende Jahre der Witterung, der Kriegsführung und der Verlassenheit abgetragen wurden. Nach der Zersplitterung Arathors in rivalisierende Königreiche und dem schließlichen Fall des benachbarten Lordaeron an die Geißel pflegt kein zentrales Reich mehr das Mauerwerk. Nun schlüpfen Reisende und umherstreifende Banditen ungehindert durch seine zerbrochenen Torbögen, während sie zwischen Hillsbrad und dem ungezähmten Arathihochland reisen."}},faq={{q="Wer erbaute Thoradinswall?",a="Er wurde von König Thoradin in Auftrag gegeben, dem Gründer und Kriegsherrn, der vor fast drei Jahrtausenden die Stämme der Menschheit vereinte, um das Reich von Arathor zu gründen.",al={"wer erbaute thoradinswall","erbauer von thoradinswall","thoradinswall ursprung"}},{q="Warum wurde der Wall überhaupt erbaut?",a="König Thoradin ordnete seinen Bau an, um die frühe Hauptstadt der Menschheit, Strom, und ihre jungen Siedlungen vor den erbitterten Angriffen des benachbarten Trollreichs der Amani zu verteidigen.",al={"zweck von thoradinswall","warum der wall erbaut wurde","wozu diente thoradinswall"}},{q="Warum ist der Wall heute so verfallen?",a="Der Wall hat Tausende Jahre natürlicher Verwitterung, Konflikte und Vernachlässigung erlitten. Nachdem das Reich von Arathor in unabhängige Menschennationen zersplittert war, verlor die gewaltige Grenzbefestigung ihre strategische Priorität und wurde dem Verfall überlassen.",al={"warum ist thoradinswall zerstört","wer zerstörte thoradinswall","warum zerstört"}},{q="Welche Regionen trennt Thoradinswall?",a="Der Wall bildet die natürliche Landgrenze, die das üppige Vorgebirge des Hügellands im Westen vom zerklüfteten Arathihochland im Osten trennt.",al={"wo ist thoradinswall","was trennt die mauer","grenze von thoradinswall"}}},fx={b3263746={q="Was ist Thoradinswall?",a="Thoradinswall ist ein uralter, gewaltiger steinerner Wall, der die Grenze zwischen dem Arathihochland und dem Vorgebirge des Hügellands überspannt. Vor Jahrtausenden auf dem Höhepunkt des Imperiums von Arathor errichtet, diente er als das große defensive Bollwerk der Menschheit, um das Kernland um Strom vor den heftigen Einfällen der Amani-Trolle zu schützen. Obwohl heute stark verwittert und beschädigt, ragen seine hoch aufragenden Bögen und bröckelnden Steine immer noch über der Handelsstraße empor.",al={"was ist thoradinswall","infos zu thoradinswall","über thoradinswall"}},a3fa6dab={q="Was ist an Thoradinswall passiert?",a="Über Generationen hinweg hielt der Wall unzähligen Überfällen der Waldtrolle von Zul'Aman stand und verteidigte die Wiege der Menschheit. Im Laufe der darauffolgenden Jahrhunderte führten Vernachlässigung, Kriege und der bloße Lauf der Zeit dazu, dass seine Verteidigungsanlagen zu den heute stehenden Ruinen verfielen.",al={"geschichte von thoradinswall","schlachten an thoradinswall","was ist hier passiert"}},bb7d6206={q="Warum heißt es Thoradinswall?",a="Der Wall ist zu Ehren von Hochkönig Thoradin benannt, dem legendären Kriegsherrn, der als Erster die kriegführenden Menschenstämme zum ruhmreichen Imperium von Arathor vereinte. Kurz nach der Gründung seines Imperiums und seiner großen Hauptstadt Strom befahl Thoradin den Bau dieser riesigen Befestigungsanlage, um das Überleben der Menschheit gegen feindselige Bedrohungen aus der Wildnis zu sichern, womit er sicherstellte, dass sein Name für immer in den Stein der Grenze eingemeißelt blieb.",al={"warum heißt es thoradinswall","nach wem ist thoradinswall benannt","name thoradinswall"}}},fp="15,288,28.497.0,18.490.0,26.154.0,42.172.0,37.241.0,43.140.0"}
P.entries["subzone:thorn-hill"] = {n="Dornenhügel",s="Dornenhügel ist eine befestigte Enklave der Stachelmähnen-Stacheleber, die auf den hohen Bergrücken östlich vom Wegekreuz im Brachland liegt. Die Siedlung dient als vorgeschobene Basis für Stacheleber-Kriegstrupps, die die Versorgungswege der Horde zwischen Durotar und der inneren Savanne überfallen.",h="Dornenhügel ist eine befestigte Enklave der Stachelmähnen-Stacheleber, die auf den hohen Bergrücken östlich...",kw={"brachland","das wegekreuz","stacheleber","stachelmähne","rasierschnauze","dornenhügel"},ang={["faction:Horde"]="Die Sicherung der Straße zwischen dem Wegekreuz und Durotar ist für die junge Horde von entscheidender Bedeutung, was die aggressiven Plünderer in Dornenhügel zu einem dringenden Ziel für neue Krieger macht."},sec={{t="Ein Dorn im Fleisch der Horde",b="Auf der Nordseite der schroffen Hügel zwischen Durotar und dem Wegekreuz gelegen, bietet Dornenhügel einen wachsamen Ausblick auf die wichtigsten Handelskorridore des Brachlands. Die Siedlung ist die Heimat einer gefährlichen Ansammlung des Stammes der Stachelmähnen, darunter Jäger, abgerichtete Wölfe und geomantische Erdenformer. Angeleitet von Mystikern wie dem Ältesten Mystiker Rasierschnauze haben die Stacheleber hier ihre Angriffe auf vorbeiziehende Versorgungskarawanen der Horde intensiviert. Da dieses Berglager so nah an lebenswichtigen Transitrouten liegt, betrachten die Wachen im Wegekreuz Dornenhügel als eine der unmittelbarsten militärischen Bedrohungen in der zentralen Savanne."}},faq={{q="Was ist Dornenhügel?",a="Dornenhügel ist ein bedeutendes Lager der Stachelmähnen-Stacheleber, das an den Berghängen im nördlichen Brachland liegt, direkt zwischen dem Wegekreuz und der Grenze zu Durotar.",al={"standort dornenhügel","wo liegt dornenhügel","was ist dieses lager"}},{q="Wer führt die Stacheleber in Dornenhügel an?",a="Die prominenteste Figur unter den Stachelebern hier ist der Älteste Mystiker Rasierschnauze, ein Stachelmähnen-Mystiker, der die Kriegstrupps des Stammes leitet.",al={"boss in dornenhügel","wer regiert dornenhügel"}},{q="Warum kämpft die Horde hier gegen die Stacheleber?",a="Die in Dornenhügel ansässigen Stachelmähnen-Kriegstrupps überfallen regelmäßig die Versorgungskarawanen der Horde, die den Weg über die Grenze von Durotar zum Wegekreuz zurücklegen, was die lokalen Behörden der Horde dazu zwingt, Krieger zur Säuberung der Bergrücken auszusenden.",al={"warum dornenhügel angreifen","überfälle auf hordekarawanen","stacheleber im wegekreuz"}},{q="Welche Arten von Feinden leben in Dornenhügel?",a="Das Lager wird von Stachelmähnen-Geomanten, Jägern, abgerichteten Wölfen und wilden Berserkern verteidigt.",al={"gegner in dornenhügel","stacheleberarten in dornenhügel"}}},fx={e0126d7b={q="Ist Dornenhügel gefährlich?",a="Dornenhügel stellt eine ernsthafte Bedrohung für jeden dar, der zwischen Durotar und dem Wegekreuz reist. Die Siedlung am Berghang wird schwer von feindseligen Stachelmähnen-Geomanten, Jägern und abgerichteten Wölfen verteidigt, angeleitet von Mystikern wie dem Ältesten Mystiker Razorsnout. Da diese Stachelhauer aktiv vorbeiziehende Karawanen der Horde überfallen, müssen sich unvorsichtige Reisende bei Betreten ihres befestigten Gebiets auf sofortige Angriffe gefasst machen.",al={"ist dornenhügel gefährlich","gefahren in dornenhügel","wie gefährlich ist dornenhügel"}}},fp="10,259,27.622.0,19.169.0,37.129.0,44.217.0,41.102.0"}
P.entries["subzone:three-corners"] = {n="Drei Ecken",s="Drei Ecken ist eine wichtige Kreuzung, die knapp hinter der westlichen Grenze des Rotkammgebirges liegt. Mit ihren Abzweigungen zu den drei Nachbarorten Goldhain, Seenhain und Dunkelhain markiert sie die Grenze zwischen dem Herzen des Königreichs und der gefährlichen Wildnis des Rotkamms. Ein Wachturm der Stadtwache von Sturmwind überragt die Kreuzung und hält die Stellung gegen vordringende Gnollrudel.",h="Drei Ecken ist eine wichtige Kreuzung, die knapp hinter der westlichen Grenze des Rotkammgebirges liegt.",kw={"kreuzung","dunkelhain","gnolle","goldhain","seenhain","rotkammgebirge","drei ecken","turmwache"},ang={["faction:Alliance"]="Für Reisende der Allianz, welche die relative Sicherheit des Walds von Elwynn verlassen, ist Drei Ecken der erste befestigte Außenposten und eine deutliche Mahnung daran, dass Sturmwinds Einfluss auf seine Grenzlande nur noch schwach ist.",["race:Human"]="Der Wachturm verbindet die südlichen Kernlande der Menschen und dient als kritischer Knotenpunkt für Kuriere und den Handel zwischen Elwynn, dem Dämmerwald und dem Rotkammgebirge."},sec={{t="Eine Kreuzung dreier Haine",b="Am westlichen Rand des Rotkammgebirges gelegen, verbindet Drei Ecken drei wichtige Siedlungen der Allianz: Goldhain im Wald von Elwynn im Westen, Seenhain im Nordosten und Dunkelhain im Dämmerwald im Süden. Aufgrund dieses strategischen Knotepunkts errichtete Sturmwind die Turmwache im Zentrum der Kreuzung. Örtliche Wachen und Späher besetzen den Posten und versuchen, die Verkehrsstraßen frei von den aggressiven Gnollen des Rotkamms zu halten, die ständig Reisende und Versorgungswagen zwischen den Regionen bedrohen."}},faq={{q="Warum heißt dieser Ort Drei Ecken?",a="Die Kreuzung teilt sich in drei verschiedene Straßen, die zu den drei Hainen des südlichen Sturmwind führen: Goldhain im Wald von Elwynn, Seenhain im Rotkammgebirge und Dunkelhain im Dämmerwald.",al={"drei ecken bedeutung des namens","warum drei ecken","geschichte von drei ecken"}},{q="Wer bewacht den Turm bei Drei Ecken?",a="Der als Turmwache bekannte Außenposten wird von Mitgliedern der Stadtwache von Sturmwind bemannt. Sie dienen als Frühwarnposten und Verteidigungskastell gegen Gnolle, die sich von den Gipfeln des Rotkammgebirges in Richtung der Grenze von Elwynn vorwagen.",al={"wer kontrolliert drei ecken","wachen der turmwache","wer ist im turm"}},{q="Welche Bedrohungen lauern um Drei Ecken herum?",a="Gnolle aus den umliegenden Hügeln lauern ununterbrochen auf den Straßen und überfallen Reisende und Kuriere. Die hier stationierten Wachen bitten regelmäßig vorbeiziehende Abenteurer darum, die Gnollrudel auszudünnen und die Straßen passierbar zu halten.",al={"drei ecken monster","gefahren bei drei ecken","drei ecken gnolle"}}},fx={["36588b3d"]={q="Was ist Drei Ecken?",a="Drei Ecken ist ein lebenswichtiger Knotenpunkt direkt innerhalb der südwestlichen Grenze des Rotkammgebirges. Von dieser zentralen Kreuzung zweigen drei Hauptstraßen zu den drei großen regionalen Siedlungen ab: Goldhain im Wald von Elwynn, Seenhain hier im Rotkammgebirge und Dunkelhain unten im Dämmerwald. Das Zentrum dieser wichtigen Kreuzung wird von der Turmwache bewacht, einem befestigten Spähposten, der von der Wache von Sturmwind besetzt ist.",al={"was ist dieser ort","wo ist drei ecken","übersicht drei ecken"}},["4545d69d"]={q="Ist Drei Ecken gefährlich?",a="Während die Kreuzung selbst durch die bei der Turmwache stationierten Wachen von Sturmwind geschützt ist, wimmelt es in den unmittelbar umliegenden Hügeln und Pfaden vor Gefahren. Örtliche Gnollrudel durchstreifen unaufhörlich das Gebüsch und überfallen unvorsichtige Reisende entlang der Straßen. Jedem, der dort durchreist, wird dringend empfohlen, in der Nähe des Wachturms der Garnison zu bleiben, anstatt allein in das wilde Unterholz zu wandern.",al={"ist drei ecken sicher","gefahr in drei ecken","bedrohungen in drei ecken"}}},fp="13,386,28.513.0,39.182.0,38.217.0,45.216.0"}
P.entries["subzone:thunder-axe-fortress"] = {n="Festung Donneraxt",s="Die Festung Donneraxt ist eine befestigte Anlage im nordwestlichen Desolace, die als Hochburg für den dämonischen Burning Blade-Kult dient. In ihren steinernen Kasernen, Wachtürmen und verdunkelten Höhlen führen Kultisten dunkle Rituale durch, um dämonische Wesenheiten zu beschwören und gestohlene Artefakte der Macht aufzubewahren. Der Kult bleibt eine aktive Bedrohung für jeden, der die öden Einöden durchquert.",h="Die Festung Donneraxt ist eine befestigte Anlage im nordwestlichen Desolace, die als Hochburg für den...",kw={"burning blade","desolace","hand von iruxos","kohor","szepter des lichts","festung donneraxt","tyranis malem"},ang={["class:Warlock"]="Die Experimente der Burning Blade in der Festung zeigen die rücksichtslosen Grenzen der Dämonologie, von der Bindung niederer Scheusale bis hin zum Erzwingen von Ebenenrissen für größere Wesenheiten.",["faction:Alliance"]="Die Untersuchung der Festung Donneraxt steht im Einklang mit den Bemühungen der Argentumdämmerung, gefährliche Artefakte wie das Szepter des Lichts zu sichern, bevor Teufelskultisten sie gegen den Kontinent richten können."},sec={{t="Eine Bastion der Burning Blade",b="Die im nordwestlichen Desolace gelegene Festung Donneraxt dient als schwer bewachte Redoute für die Burning Blade. Bestehend aus steinernen Kasernen, defensiven Wachtürmen und tiefen Höhlen, ermöglicht sie dem Kult, einen befestigten Stützpunkt fernab der Blicke der großen Städte von Kalimdor aufrechtzuerhalten. Hier sammeln die Kultisten Teufelsenergien, beschwören niedere Dämonen und schmieden Pläne, um weit gefährlichere Wesenheiten in die Welt zu bringen."},{t="Gestohlene Relikte und dunkle Beschwörungen",b="Der Kult lagert in der Festung die Hand von Iruxos, ein Relikt, das mit den Dämonenportalen von Mannorocs Koven verbunden ist. Ein Seher der Burning Blade studiert außerdem das gestohlene Szepter des Lichts auf einem der Wachtürme. Azore Aldamort bittet Reisende darum, das Szepter zurückzuholen, das Gerüchten zufolge den Naga gestohlen wurde."}},faq={{q="Wer kontrolliert die Festung Donneraxt?",a="Die Festung wird vom Burning Blade-Kult gehalten, einer Organisation, die sich der dämonischen Macht und den Überresten des Schattenrats verschrieben hat. Vor Ort werden die Festung und ihre Operationen von Hexenmeistern wie Tyranis Malem überwacht.",al={"wer leitet die festung thunder axe","wer ist in der festung thunder axe","boss der festung thunder axe"}},{q="Was ist das Szepter des Lichts?",a="Das Szepter des Lichts ist ein uraltes Artefakt, dem nachgesagt wird, dass es ganze Städte unter dem Meer versenken kann. Azore Aldamort bittet Reisende darum, es einem Seher der Burning Blade abzunehmen, der es auf einem der Wachtürme der Festung studiert.",al={"szepter des lichts","gestohlenes naga artefakt"}},{q="Wie ist diese Festung mit Mannorocs Koven verbunden?",a="Die Kultisten in der Festung Donneraxt bewahren ein Artefakt auf, das als die Hand von Iruxos bekannt ist. Dieses Relikt war direkt mit den Dämonenportalen verbunden, die in Mannorocs Koven im südlichen Desolace aktiv sind, und verknüpft so ihre dämonischen Bemühungen im gesamten Gebiet.",al={"verbindung zu mannorocs koven","hand von iruxos"}}},fp="20,359,30.415.0,33.304.1,34.223.0,29.221.1,49.232.0"}
P.entries["subzone:thunder-bluff"] = {n="Donnerfels",s="Donnerfels ist die hochgelegene Hauptstadt der Tauren, die sich Hunderte von Fuß über die wogenden Ebenen von Mulgore erhebt. Nach dem Dritten Krieg von Cairne Bluthuf gegründet, dient sie als vereinte Zuflucht und kulturelles Herz für ein Volk, das über Generationen hinweg als Nomaden umherzog.",h="Donnerfels ist die hochgelegene Hauptstadt der Tauren, die sich Hunderte von Fuß über die wogenden Ebenen von...",kw={"cairne bluthuf","erdenmutter","grimmtotem","hochebenen","mulgore","die teiche der visionen","tauren","donnerfels"},ang={["faction:Horde"]="Donnerfels bietet der Horde eine unverzichtbare Bastion im südlichen Kalimdor und ruht als beständiger Anker der Weisheit und Ressourcen an der Seite des orkischen Orgrimmar.",["race:Tauren"]="Für die Tauren stellt Donnerfels nach Generationen des Umherwanderns ihre erste wahre feste Heimat dar, die ihre heiligen Totems, Geisterhütten und größten Häuptlinge beherbergt."},sec={{t="Eine Zuflucht auf den Hochebenen",b="Über unzählige Generationen hinweg lebten die Tauren als nomadische Wanderer im zentralen Kalimdor, ständig bedrängt von brutalen Kriegstrupps der Zentauren. Diese Ära der Flucht endete während des Dritten Krieges, als Cairne Bluthuf ein Ehrenbündnis mit Kriegshäuptling Thrall und der neuen Horde schmiedete. Gemeinsam schlugen sie die Bedrohung durch die Zentauren zurück und beanspruchten das fruchtbare Grasland von Mulgore. Cairne versammelte die verstreuten Stämme und errichtete Donnerfels auf einer Reihe weitläufiger, natürlicher Felshochebenen. Heute ist die Stadt durch schwindelerregende Seilbrücken verbunden und über ausgeklügelte hölzerne Aufzüge zugänglich, was sowohl absolute Verteidigung als auch ein geschäftiges Zentrum für Handel und spirituelle Zusammenkünfte bietet."},{t="Einheit und aufziehende Nebel",b="Während Donnerfels als Leuchtfeuer der Harmonie dasteht, beherbergen seine hoch aufragenden Höhen verschiedene Gruppierungen. Die meisten Stämme verehren die Weisheit von Cairne Bluthuf, doch unter Traditionalisten wie Magatha Grimmtotem und ihrer Sippe auf der Anhöhe der Ältesten schwelt stiller Unmut. Tief unter der Oberfläche der Stadt liegen die unterirdischen Teiche der Visionen, wo Geistwandler und Schamanen den Willen der Ahnen ergründen. Trotz unterschwelliger Stammesrivalitäten bleibt Donnerfels die wahre spirituelle Säule der Horde auf Kalimdor und heißt aus dem Brachland zurückkehrende Jäger, reisende Handwerker und Druiden willkommen, die mit der Erdenmutter Zwiesprache halten."}},faq={{q="Wie gelangen Reisende hinauf nach Donnerfels?",a="Reisende erreichen die Stadt über gewaltige, aus Holz und Flaschenzügen konstruierte Aufzüge an den südwestlichen und nordöstlichen Klippen oder per Flug direkt zum Windreiterhorst der Stadt auf der zentralen Hochebene.",al={"donnerfels aufzug","wie man nach tb kommt","donnerfels betreten"}},{q="Warum bauten die Tauren ihre Stadt auf Klippen?",a="Nachdem sie jahrhundertelang unerbittliche Zentaurenüberfälle auf offenem Feld ertragen mussten, wählte Cairne Bluthuf die emporragenden Felshochebenen, um seinem Nomadenvolk eine uneinnehmbare Zuflucht mit Blick auf die heiligen Weidegründe von Mulgore zu bieten.",al={"warum hochebenen","warum auf hohen klippen gebaut","donnerfels verteidigung"}},{q="Wer herrscht über Donnerfels?",a="Oberhäuptling Cairne Bluthuf führt Donnerfels an. Er vereinte die verstreuten Stämme, sicherte den Frieden von Mulgore und herrscht mit dem Rat der Stammesführer und Ältesten der Anhöhen.",al={"anführer von donnerfels","wer ist der häuptling","cairne donnerfels"}},{q="Sind alle Taurenstämme Cairne treu ergeben?",a="Während die überwiegende Mehrheit Cairnes Weisheit verehrt, hegen einige Gruppen – allen voran der von der Ältestengreisin Magatha angeführte Grimmtotemstamm – Zweifel am Bündnis mit der Horde und suchen ihren eigenen Weg für das Volk der Tauren.",al={"grimmtotem donnerfels","stämme von donnerfels","politische rivalen der tauren"}}},fx={f3581e0f={q="Was ist Donnerfels?",a="Donnerfels ist die Hauptstadt der Tauren, die sich auf einem Netzwerk von hoch aufragenden, windgepeitschten Plateaus im nördlichen Mulgore befindet. Verbunden durch Seilbrücken und riesige Aufzüge, dient die Stadt als geschäftiges Zufluchtsort voller Langhäuser, Zelte und Geisterhütten. Sie repräsentiert die erste dauerhafte Heimat, die die Tauren nach Jahrhunderten nomadischer Wanderschaft beansprucht haben.",al={"was ist donnerfels","erzählt mir von donnerfels","lore von donnerfels"}},d7d48e60={q="Wie wurde Donnerfels gegründet?",a="Über Generationen hinweg lebten die Tauren als nomadische Stämme, die ständig von marodierenden Zentauren gejagt wurden. Während des Dritten Kriegs verbündete sich Häuptling Cairne Bluthuf mit Thrall und der Neuen Horde. Gemeinsam vertrieben sie die Zentauren und sicherten sich die üppigen Ebenen von Mulgore. Auf diesen hoch aufragenden Plateaus gründete Cairne die Stadt als sicheren Zufluchtsort, um die verstreuten Taurenstämme zu vereinen.",al={"geschichte von donnerfels","wer gründete donnerfels","ursprung von donnerfels"}},["4fba0646"]={q="Ist Donnerfels gefährlich?",a="Die Stadt selbst ist ein gut verteidigter Zufluchtsort für die Horde, obwohl ihre steilen Klippen eine tödliche Gefahr darstellen, falls Ihr nahe der Kanten einen falschen Schritt macht. Jenseits der physischen Abgründe halten sich im Stillen interne politische Spannungen unter der Oberfläche des Friedens, da einige rivalisierende Fraktionen, wie der Stamm der Grimmtotems, unruhige Teilnehmer an Cairnes vereinter Nation bleiben.",al={"ist donnerfels sicher","gefahr in donnerfels","bedrohungen in donnerfels"}}},fp="13,279,23.664.0,25.602.0,41.205.0,46.220.0,24.188.0,38.215.0"}
P.entries["subzone:thunder-falls"] = {n="Donnerfälle",s="Die Donnerfälle sind eine abgeschiedene Bergschlucht, die in den nordwestlichen Höhen des Waldes von Elwynn versteckt liegt. Eingebettet zwischen steilen Klippen und gespeist von rauschenden Kaskaden, beherbergt sie eine stille Hütte am Flussufer, die in die Hände örtlicher Banditen gefallen ist.",h="Die Donnerfälle sind eine abgeschiedene Bergschlucht, die in den nordwestlichen Höhen des Waldes von Elwynn...",kw={"banditen","hütte","wald von elwynn","spiegelsee","donnerfälle","wasserfall"},sec={{t="Eine verborgene Bergmulde",b="Versteckt in den zerklüfteten Graten über dem Spiegelsee, sind die Donnerfälle eine ungewöhnliche geologische Kluft. Die Schlucht wurde von einem reißenden Gebirgsbach geformt, der über eine unzugängliche nördliche Kaskade eintritt und an beiden Seiten in dramatischen Wasserfällen abfällt. Eine Seite stürzt hinab in den Spiegelsee, während der flussabwärts verlaufende Lauf nach Westen in Richtung der rauen Grenzen von Westfall fließt. Trotz des tosenden Wassers befinden sich eine kleine Hütte, ein Anlegesteg und eine Feldschmiede am Ufer, auch wenn Gesetzlose nun die friedliche Lichtung für sich beanspruchen."}},faq={{q="Wie erreicht Ihr die Donnerfälle?",a="Ihr könnt die Donnerfälle erreichen, indem Ihr Euch zur Nordseite des Spiegelsees im Wald von Elwynn begebt. Ein steiler, schmaler Pfad schlängelt sich an der rechten Seite des Wasserfalls vom Spiegelsee hinauf in die Hügel und führt direkt in die abgeschiedene Schlucht.",al={"anreise zu den donnerfällen","standort der donnerfälle","wo liegen die donnerfälle"}},{q="Wer wohnt in der Hütte an den Donnerfällen?",a="Die abgelegene Hütte scheint einst einem einsamen Fischer oder Grenzgänger gehört zu haben, komplett mit Anlegesteg, Ruderboot und einem Amboss im Freien. Heute jedoch dient sie als abgelegenes Versteck für Banditen, die in der Wildnis vom Wald von Elwynn operieren.",al={"wer ist in der hütte","haus an den donnerfällen","hüttenbanditen"}},{q="Wohin fließt der Fluss an den Donnerfällen?",a="Der Bach fließt durch die schmale Berglücke von einer oberen Bergkaskade herab. Flussabwärts windet er sich an der Hütte vorbei und stürzt über einen weiteren steilen Fall hinab, der nahe der östlichen Grenze von Westfall mündet.",al={"wohin fließt das wasser","fluss an den donnerfällen"}}},fx={["1050bd39"]={q="Was sind die Donnerfälle?",a="Die Donnerfälle sind eine abgeschiedene Bergschlucht, die in den nordwestlichen Höhen des Waldes von Elwynn versteckt liegt. Gespeist von einem unzugänglichen Wasserfall, der von den hohen nördlichen Klippen herabstürzt, gräbt sich der Fluss durch eine enge Schlucht zwischen zwei Wasserfällen und ergießt sich auf der einen Seite in Richtung Mirror Lake und stürzt auf der anderen westwärts in Richtung der Grenze von Westfall. Es ist ein ruhiger, verborgener Zufluchtsort mit einem einsamen Landhaus, einem kleinen Steg und kaltem Bergwasser.",al={"was sind die donnerfälle","geschichte der donnerfälle","erzähle mir von den donnerfällen"}},db2700a0={q="Sind die Donnerfälle gefährlich?",a="Trotz der idyllischen Lage müsst Ihr vorsichtig sein. Gesetzlose und mit der Defias-Bruderschaft verbündete Banditen haben ihr Lager um das einsame Haus aufgeschlagen und nutzen die versteckte, gut zu verteidigende Lage oberhalb der Wasserfälle aus. Neben feindseligen Wegelagerern erfordert das Navigieren an den steilen Klippen und tosenden Wasserfällen Vorsicht, da ein falscher Schritt Euch in die Stromschnellen unterhalb stürzen lassen kann.",al={"sind die donnerfälle sicher","banditen bei den donnerfällen","bedrohungen bei den donnerfällen"}}},fp="13,246,24.529.0,31.232.0,42.247.0,43.207.0"}
P.entries["subzone:thunder-ridge"] = {n="Donnergrat",s="Der Donnergrat ist ein zerklüfteter Canyon im westlichen Durotar, gelegen knapp südwestlich von Orgrimmar an den Ufern des Südstroms. Einst ein üppiger Hain uralter Bäume, der von Herden von Donnerechsen bewohnt wurde, erlitt der Canyon durch Holzfällerarbeiten der Menschen und dunkle Zauberei schwere Entwaldung. Heute stellen die aufgewühlten Bestien und verbliebenen Kultisten eine ständige Bedrohung für nahegelegene Siedlungen dar.",h="Der Donnergrat ist ein zerklüfteter Canyon im westlichen Durotar, gelegen knapp südwestlich von Orgrimmar an...",kw={"burning blade","durotar","fizzle dunkelklaue","orgnil narbenseele","rexxar","der südstrom","donnerechsen","donnergrat","uzzek"},ang={["class:Warrior"]="Kriegerlehrer wie Uzzek schicken ihre Schützlinge in den Donnergrat, um ihr defensives Können gegen die schiere körperliche Wucht und die Blitzeinschläge der wilden Donnerechsen auf die Probe zu stellen.",["faction:Horde"]="Eingebettet direkt vor den westlichen Klippen von Orgrimmar muss der Grat frei von Agenten der Burning Blade wie Fizzle Darkclaw gehalten werden, um dämonische Zersetzung vor den Toren der Hauptstadt zu verhindern."},sec={{t="Eine gezeichnete Zuflucht",b="Vor nicht allzu langer Zeit war der Donnergrat eine seltene grüne Oase im trockenen Durotar, getragen von uralten Bäumen. Sein friedliches Gleichgewicht zerbrach kurz nach dem Dritten Krieg, als menschliche Eindringlinge aus Kul Tiras begannen, sein Holz zu fällen, was die einheimischen Donnerechsen in Raserei versetzte. Später vollendete von der Burning Blade gewirkte Teufelsmagie die Zerstörung, indem sie das Blätterdach vernichtete und eine karge, ungeschützte Schlucht hinterließ, in der nun wütende, blitze-speiende Bestien ungezähmt umherstreifen."},{t="Kultisten und Kraftproben",b="Die Bewohner von Orgrimmar haben ein wachsames Auge auf den Grat. Die Burning Blade unterhält hier unter dem Hexenmeister Fizzle Darkclaw eine Gruppe von Kultisten, die dämonische Magie nutzen, um weiteres Chaos in ganz Durotar zu säen. Veteranen der Horde wie Orgnil Narbenseele beauftragen Späher mit der Jagd nach der Geheimorganisation, während Kriegerausbilder wie Uzzek angehende Kämpfer in die schroffen Felsen schicken, um ihre Widerstandskraft gegen die Enraged Thunder Lizards auf die Probe zu stellen."}},faq={{q="Was geschah mit den Bäumen im Donnergrat?",a="Der Donnergrat war einst ein dichter Wald, erlitt jedoch zwei Wellen der Zerstörung. Zuerst fällten Holzfällerkolonnen der Streitkräfte von Kul Tiras kurz nach der Gründung von Durotar rücksichtslos sein uraltes Holz. Später nutzte die Brennende Klinge dunkle, dämonische Magie, um die überlebenden Haine dem Erdboden gleichzumachen und den Wald vollständig auszulöschen.",al={"warum ist der donnergrat karg","donnergrat wald","entwaldung donnergrat"}},{q="Warum sind die Donnerechsen hier so aggressiv?",a="Die Donnerechsen lebten friedlich zwischen den uralten Bäumen des Grates, bis Übergriffe von außen ihren Lebensraum ruinierten. Der Lärm und die Zerstörung des menschlichen Holzabbaus, kombiniert mit der anhaltenden Teufelsverderbnis durch die Kultisten der Burning Blade, trieben die Herden in einen aufgewühlten Wahnsinn, der sie jeden angreifen lässt, der sich in den Canyon wagt.",al={"wütende echsen donnergrat","donnerechsen durotar"}},{q="Wer ist Fizzle Darkclaw?",a="Fizzle Darkclaw ist ein Anführer innerhalb des Kults der Burning Blade, der ein Lager im Donnergrat errichtete. Von diesem Stützpunkt aus leiten er und seine Anhänger finstere Rituale, um die Region zu destabilisieren, was Anführer der Horde wie Orgnil Narbenseele dazu veranlasste, ein Kopfgeld auf ihn auszusetzen.",al={"fizzle dunkelklaue geschichte","wer ist dunkelklaue","burning blade donnergrat"}},{q="Kämpfte Rexxar im Donnergrat?",a="Ja. Kurz nach der Gründung von Durotar reiste der Champion der Horde, Rexxar, hierher, um Schimmerkraut für den Schamanen Drek'Thar zu sammeln. Während er sich im Canyon aufhielt, entdeckte Rexxar das Holzfällerlager der Menschen, das die Echsen in Raserei versetzte, was ihn dazu zwang, die rasenden Bestien auszudünnen und ihre Eier zu bergen, damit Drek'Thar sie untersuchen konnte.",al={"rexxar donnergrat","drek'thar donnergrat"}}},fx={d8d2e909={q="Was ist der Donnergrat?",a="Der Donnergrat ist eine tiefe, entwaldete Schlucht im nordwestlichen Durotar, die sich südwestlich von Orgrimmar befindet. Einst ein blühender alter Wald, diente er als traditioneller Zufluchtsort für riesige Herden von Donner-Echsen. Heute ist das üppige Blätterdach verschwunden und durch kahle Klippen, umherstreifende Bestien und vordringende dunkle Kultisten ersetzt.",al={"was ist der donnergrat","donnergrat in durotar","wo ist der donnergrat"}},["675c5d12"]={q="Was geschah am Donnergrat?",a="Kurz nach der Gründung von Durotar errichteten Menschen aus Kul Tiras hier einen illegalen Holzfällerbetrieb, fällten die alten Bäume und erzürnten die Donner-Echsen, bis Rexxar und Drek'Thar eingriffen. Später zerstörte die dämonische Verderbnis, die vom Kult der Burning Blade ausgeübt wurde, die verbliebenen Bäume, verwüstete das Tal und versetzte die einheimischen Bestien in einen gewalttätigen Rausch.",al={"geschichte des donnergrats","was geschah am donnergrat"}},ea9b6430={q="Wer lebt im Donnergrat?",a="Im Donnergrat gibt es keine friedliche Siedlung. Abgesehen von Herden aufgeregter Donner-Echsen und Blitzhäutern hat ein Zirkel von Kultisten der Burning Blade, angeführt von dem Hexenmeister Fizzle Darkclaw, ein Lager in der Schlucht aufgeschlagen und nutzt dunkle Magie, um Chaos in ganz Durotar zu verbreiten.",al={"wer lebt im donnergrat","bewohner des donnergrats","fraktionen im donnergrat"}},e9504f5d={q="Ist der Donnergrat gefährlich?",a="Ja. Die einheimischen Donner-Echsen sind von Natur aus territorial, und die jüngsten dunklen Einmischungen haben sie in einen unberechenbaren, feindseligen Zorn versetzt, der Eindringlinge mit Blitzen schocken kann. Zudem werden die Kultisten der Burning Blade, die in der Schlucht lauern, jeden, der ihre Ritualstätten untersucht, sofort niederstrecken.",al={"wie gefährlich ist der donnergrat","gefahren im donnergrat","ist der donnergrat sicher"}}},fp="13,391,19.466.0,30.418.1,44.317.0,47.331.0,23.279.0,34.309.0"}
P.entries["subzone:thunderbrew-distillery"] = {n="Brauerei Donnerbräu",s="Die Brauerei Donnerbräu dient als belebte Taverne und zentraler Treffpunkt von Kharanos in Dun Morogh. Sie ist weit über die Grenzen für ihre starken Biere bekannt und fungiert sowohl als aktive Brauerei als auch als wichtige Raststätte für Reisende, die die verschneiten Gebirgspässe durchqueren. Im Inneren finden Gäste warme Kamine, kühles Bier und eine große Auswahl an Klassenlehrern sowie ortsansässigen Handwerkern.",h="Die Brauerei Donnerbräu dient als belebte Taverne und zentraler Treffpunkt von Kharanos in Dun Morogh.",kw={"dun morogh","zwergenbier","gastwirt belm","kharanos","ragnar donnerbräu","brauerei donnerbräu"},ang={["profession:Cooking"]="Die Küche in der Brauerei bietet Ausbildung in Kochkunst und Vorräte an, was sie zu einer wichtigen Anlaufstelle für Köche macht, die lernen möchten, wie man herzhafte Verpflegung für die Berge zubereitet.",["race:Dwarf"]="Für Zwerge, die das Coldridgetal verlassen, ist die Brauerei ein beliebtes Zuhause, das vertrautes Bier, einen Sitzplatz an einem lodernden Kamin und bewährte Mentoren in Eisen und Glauben bietet."},sec={{t="Das warme Heim von Kharanos",b="Die mitten in Kharanos gelegene Brauerei Donnerbräu ist das Herz des öffentlichen Lebens im südlichen Dun Morogh. Die Brauerei wurde vom Clan der Thunderbrew gegründet – etabliert durch Arkilus Thunderbrew und fortgeführt von seiner Verwandtschaft – und ist in ganz Khaz Modan für die Herstellung kräftiger, wärmender Biere berühmt, die dazu dienen, die beißende Kälte des Gebirges abzuwehren. Sie fungiert als örtliches Gasthaus, das vor Ort von Gastwirt Belm geleitet wird, und bietet müden Bergsteigern ein prasselndes Feuer, herzhafte Kost und Betten, um den Schneestürmen draußen zu entkommen."},{t="Ein Kreuzungspunkt für Wissen und Handwerk",b="Neben dem Ausschank renommierter Biere dient die Brauerei auch als wichtiger Knotenpunkt für angehende Abenteurer. Da Kharanos die erste größere Siedlung ist, die Reisende nach dem Verlassen vom Coldridgetal erreichen, beherbergt die Taverne der Thunderbrew vielfältige Ausbilder. Mentoren für Kampfkünste, heilige Riten, arkanes Studium und Schurkenhandwerk versammeln sich unter ihren stabilen Holzbalken zusammen mit Lehrmeistern für Kochkunst und Erste Hilfe, was eine lärmende Trinkhalle in einen unverzichtbaren Vorbereitungsposten verwandelt."}},faq={{q="Wer besitzt und betreibt die Brauerei Donnerbräu?",a="Das Etablissement gehört der Familie Thunderbrew und wurde von Arkilus Thunderbrew gegründet. Sein Sohn Ragnar Donnerbräu kümmert sich aktiv um die Brautraditionen der Familie, während Gastwirt Belm sich um die Gastfreundschaft und die Zimmer für Reisende kümmert, die sich in Kharanos ausruhen.",al={"besitzer der brauerei","wer leitet thunderbrew","familie thunderbrew"}},{q="Welche Dienste sind in der Brauerei verfügbar?",a="Die Brauerei dient als das primäre Gasthaus von Kharanos. Im Inneren können Reisende ihren Ruhestein bei Gastwirt Belm binden, Getränke und Vorräte von Händlern erwerben und Unterweisung bei Lehrern für Krieger, Paladine, Priester, Magier, Schurken, Kochkunst und Erste Hilfe suchen.",al={"was gibt es in der brauerei donnerbräu","lehrer in der brauerei","gasthausdienste in kharanos"}},{q="Warum ist die Brauerei so berühmt?",a="Die Brauerei ist in den gesamten Östlichen Königreichen für die Herstellung außergewöhnlich starker Zwergenbiere berühmt, insbesondere Thunderbrew Ale. Ihre Biere sind dafür bekannt, Reisende gegen die harschen, eisigen Temperaturen der Gipfel von Dun Morogh zu stählen.",al={"warum ist thunderbrew ale berühmt","ruf von thunderbrew ale"}}},fx={["1fa2ba89"]={q="Was ist die Brauerei Donnerbräu?",a="Die Brauerei Donnerbräu ist eine geschäftige Zwergenschänke und ein Gasthaus im Herzen von Kharanos. Neben warmen Betten, Ruhesteinen und deftigen Getränken dient sie als wichtigster Treffpunkt der Gemeinde, an dem sich Bergsteiger, Handwerker, Klassenlehrer und Reisende ausruhen und Neuigkeiten aus ganz Dun Morogh austauschen.",al={"was ist die brauerei donnerbräu","schänke donnerbräu","brauerei in kharanos"}},["6c9338b8"]={q="Was ist die Geschichte der Brauerei Donnerbräu?",a="Die von dem Zwergenbrauer Arkilus Thunderbrew gegründete Brauerei besteht seit Generationen als eine der besten Brauereien in Dun Morogh. Heute wird sie unter seinem Sohn Ragnar immer noch als Familienbetrieb geführt und braut weiterhin ihre berühmten Ales.",al={"geschichte der brauerei","geschichte der brauerei donnerbräu","wer gründete die brauerei donnerbräu"}},ec3a2fd6={q="Ist die Brauerei Donnerbräu gefährlich?",a="Ganz und gar nicht. Die Brauerei ist ein sicherer Zufluchtsort für Reisende und Verteidiger der Allianz, der von Bergsteigern und Stadtwachen gut vor den Troggs, Frosttrollen und hungrigen Bestien geschützt wird, die in den verschneiten Hügeln außerhalb von Kharanos umherstreifen.",al={"ist die brauerei donnerbräu gefährlich","ist die brauerei sicher","ist es hier sicher"}},["1194a384"]={q="Warum heißt es Brauerei Donnerbräu?",a="Die Brauerei hat ihren Namen von der Familie Thunderbrew, die das Geschäft über Generationen hinweg gründete und aufrechterhielt, sowie von den kräftigen Zwergen-Ales, die sie in ihren Kellern brauen.",al={"warum heißt die brauerei donnerbräu","ursprung des namens donnerbräu","name der brauerei donnerbräu"}}},fp="22,378,27.500.0,35.495.0,49.249.0,50.270.0,32.244.0"}
P.entries["subzone:thunderhorn-water-well"] = {n="Brunnen der Donnerhörner",s="Der Brunnen der Donnerhörner ist eine lebenswichtige Wasserquelle in den wogenden Ebenen des zentralen Mulgore entlang des Pfades zwischen dem Dorf der Bluthufe und Donnerfels. Wie alle Brunnen im gesamten Tal spendet er den Stämmen und den durch das Grasland streifenden Herden unverzichtbare Nahrung. Dieses Wasser rein und geschützt zu halten, ist entscheidend für den Erhalt des Lebens in der Heimat der Tauren.",h="Der Brunnen der Donnerhörner ist eine lebenswichtige Wasserquelle in den wogenden Ebenen des zentralen...",kw={"bloodhoof","mulgore","donnerfels","thunderhorn","venture company","wasser","brunnen"},ang={["class:Shaman"]="Schamanen verehren die reinen Wasserquellen von Mulgore zutiefst und betrachten den Schutz der Wassergeister und unterirdischen Ströme als heilige Pflicht.",["race:Tauren"]="Für die Tauren sind Brunnen wie der von Thunderhorn lebenswichtige Lebensadern, die von der Erdenmutter geschenkt wurden und ständige Wachsamkeit gegenüber fremden Verschmutzern und habgierigen Eindringlingen erfordern."},sec={{t="Eine lebensspendende Quelle",b="Inmitten des weitläufigen Graslands des zentralen Mulgore gelegen, greift der Brunnen der Donnerhörner direkt auf die reinen Grundwasserleiter zu, die das Tal speisen. Für die nomadischen Tauren und ihre neu gegründeten Dörfer stehen diese Gemeinschaftsbrunnen für Leben, Nahrung und den Segen der Erdenmutter. Da Wasser in den sonnenüberfluteten Ebenen kostbar ist, bedeutet die Kontrolle über die Brunnen die Kontrolle über das Land selbst. Eindringlinge wie die Venture Company haben wiederholt ein Auge auf diese Quellen geworfen und versucht, sie für die industrielle Ausbeutung nutzbar zu machen und das empfindliche Gleichgewicht zu stören, um dessen Erhalt die Stämme kämpfen."}},faq={{q="Wo befindet sich der Brunnen der Donnerhörner?",a="Der Brunnen befindet sich im zentralen Mulgore entlang der Nord-Süd-Straße, die zwischen dem Dorf der Bluthufe und den Klippen von Donnerfels verläuft.",al={"lage des wasserbrunnens von thunderhorn","wo ist der brunnen von thunderhorn","wasserbrunnen von thunderhorn karte"}},{q="Warum ist dieser Wasserbrunnen für die Tauren wichtig?",a="Die Wasserbrunnen von Mulgore speisen sich aus den unberührten unterirdischen Wassern des Tals und versorgen die Herden, Pilger und Siedlungen. Für die Tauren ist Wasser ein heiliges Geschenk der Erdenmutter, das vor äußerem Verderben und Habgier bewahrt werden muss.",al={"warum der brunnen von thunderhorn wichtig ist","bedeutung der tauren-wasserbrunnen","warum die brunnen beschützen"}},{q="Wer hat den Brunnen bedroht?",a="Goblins der Venture Company versuchten, die Kontrolle über den Brunnen zu übernehmen, um die Wasserversorgung des Tals für ihre nahegelegenen Bergbau- und Holzfällerunternehmungen zu monopolisieren, doch die einheimischen Tauren schlugen zurück, um ihn zurückzuerobern und zu reinigen.",al={"wer hat den brunnen angegriffen","venture company brunnen","feinde am brunnen von thunderhorn"}}},fx={["4280b7a1"]={q="Was ist der Brunnen der Donnerhörner?",a="Der Brunnen der Donnerhörner ist eine wichtige Wasserquelle der Tauren inmitten der sanften Graslandschaften von Mulgore. An der nördlichen Straße gelegen, die das Dorf der Bluthufe mit den Klippen von Donnerfels verbindet, bietet der Brunnen frisches Wasser, das für die Versorgung der lokalen Stämme und der Reisenden, die die Ebenen durchqueren, unerlässlich ist.",al={"was ist der brunnen der donnerhörner","infos zum brunnen der donnerhörner","über den brunnen der donnerhörner"}},["254832a1"]={q="Was geschah am Brunnen der Donnerhörner?",a="Um die knappen Wasservorräte der Ebene zu kontrollieren, besetzte die opportunistische Venture Company den Brunnen mit ihren bewaffneten Arbeitern. Die Tauren erkannten die schwere Bedrohung für ihre Heimat und schlossen sich zusammen, um die Eindringlinge zu vertreiben und das reine Wasser für ihr Volk zurückzugewinnen.",al={"geschichte des brunnens der donnerhörner","was geschah am brunnen der donnerhörner","venture company am brunnen der donnerhörner"}},b5bd5549={q="Ist der Brunnen der Donnerhörner gefährlich?",a="Obwohl der Brunnen den Tauren gehört, werden die umliegenden Graslandschaften von räuberischer Tierwelt und eindringenden Mitarbeitern der Venture Company frequentiert, die das Land ausbeuten wollen. Reisende, die den Weg zwischen dem Dorf der Bluthufe und Donnerfels gehen, sollten wachsam bleiben.",al={"ist der brunnen der donnerhörner gefährlich","bedrohungen am brunnen der donnerhörner","ist der brunnen der donnerhörner sicher"}}},fp="22,373,20.585.0,44.142.0,47.252.0,28.210.1"}
P.entries["subzone:tidefury-cove"] = {n="Tidefury-Bucht",s="Die Tidefury-Bucht ist ein tückischer Wasserabschnitt mit felsigen Untiefen an der südöstlichen Küste der Düstermarschen, südlich der Insel Theramore. Berüchtigt für ihre gefährlichen Riffe und Schiffswracks, dient sie als abgelegener Zufluchtsort für umherstreifende Makrura und einsame Angler.",h="Die Tidefury-Bucht ist ein tückischer Wasserabschnitt mit felsigen Untiefen an der südöstlichen Küste der...",kw={"bucht","dustwallow","makrura","pagle","proudmoore","riffe","schiffswrack","theramore","tidefury"},ang={["faction:Horde"]="Für die Horde war dieser Küstenstreifen der Ausgangspunkt für die finale Gegenoffensive, die Großadmiral Proudmoores nautische Aggression brach und das Überleben der jungen Nation sicherte.",["profession:Cooking"]="Die ertragreichen seichten Küstengewässer und die Nähe zum Meisterangler Nat Pagle machen diesen Abschnitt von Dustwallow zu einem erstklassigen Ziel für Fischer auf der Suche nach kostbaren Fängen."},sec={{t="Ein Friedhof aus Schiffen und Riffen",b="Am hinteren Ende der Dustwallow Bay zwischen der Insel Theramore und dem Drachensumpf gelegen, stellt die Tidefury-Bucht eine berüchtigte nautische Gefahr für vorbeifahrende Seefahrer dar. Zerklüftete Riffe und wechselnde Untiefen haben im Laufe der Jahre zahlreiche Schiffe gefordert und verrottende hölzerne Rümpfe halb versunken in der Gezeitenzone zurückgelassen. Heute werden die Schiffsruinen von opportunistischen Makrura überrannt, was die Bucht in einen gefährlichen, isolierten Küstenstreifen verwandelt, der meist nur von hartgesottenen Plünderern oder stillen Einsiedlern aufgesucht wird, die Abstand zu Theramores belebten Docks suchen."},{t="Der historische Brückenkopf",b="Während der Invasion von Durotar wurden die Ufer der Tidefury-Bucht zu einem entscheidenden strategischen Schlachtfeld. Admiral Daelin Prachtmeers Expedition der Kul Tiraner befestigte die Küste mit einer imposanten Küstenfestung und Wachtürmen, um die Zugänge nach Theramore zu kontrollieren. Um Proudmoores Griff zu brechen, mobilisierte Thrall die vereinte Macht der jungen Horde – vereinte Orcs, Dunkelspeere und Tauren an der Seite von Rexxar und den Ogern der Stonemaul –, um die Küste zu stürmen und den Brückenkopf der Kul Tiraner zu zerschlagen, bevor sie direkt auf die Inselfestung vorrückten."}},faq={{q="Wo befindet sich die Tidefury-Bucht?",a="Die Tidefury-Bucht liegt am südöstlichen Rand der Düstermarschen, direkt südlich der Insel Theramore und grenzt am südlichen Ende der Dustwallow Bay an die Küste des Drachensumpfs.",al={"tidefury-bucht lage","wo liegt tidefury-bucht","tidefury-bucht karte"}},{q="Warum gibt es Schiffswracks in der Tidefury-Bucht?",a="Die Bucht ist voll von seichten Sandbänken und versteckten Felsenriffen, die die Schifffahrt extrem gefährlich machen. Schiffe, die zu nahe an die Küste geraten, laufen häufig auf Grund, wo Wellen und Aasfresser sie schnell zu zerschellten Rümpfen reduzieren.",al={"tidefury schiffswracks","zerstörte schiffe tidefury","gesunkene schiffe dustwallow bay"}},{q="Wer lebt heute in der Tidefury-Bucht?",a="Abgesehen von aggressiven Makrura an der Küste ist der bemerkenswerteste Bewohner der Bucht der berühmte Angler Nat Pagle, der auf einer der äußeren Inseln ein Lager namens Nat's Landing unterhält.",al={"wer ist in der tidefury-bucht","tidefury-bucht bewohner","nat pagle standort"}},{q="Welche Schlacht fand hier in der Vergangenheit statt?",a="Während Admiral Daelin Prachtmeers Feldzug gegen die neue Horde errichteten die Streitkräfte der Kul Tiraner hier eine schwer befestigte Küstenbastion. Thralls Horde stürmte und zerstörte die Basis mit Unterstützung von Verbündeten der Tauren und Oger, um den Weg zur Insel Theramore freizumachen.",al={"schlacht um die tidefury-bucht","warcraft 3 tidefury","invasion von durotar tidefury"}}},fp="13,267,30.529.0,21.548.0,31.167.0,42.233.0,33.183.0,40.256.0"}
P.entries["subzone:tidus-stair"] = {n="Die Tidusstaffel",s="Die Tidusstaffel ist eine natürliche Felsformation aus breiten, gestuften Steinterrassen über der Händlerküste südöstlich von Ratschet. Geschützt am Großen Meer gelegen, dient sie zwei Taurenschamanen als ruhiger Rückzugsort, um mit den Gezeiten und Wassergeistern Zwiesprache zu halten.",h="Die Tidusstaffel ist eine natürliche Felsformation aus breiten, gestuften Steinterrassen über der...",kw={"brachland","islen wasserdeuter","mahren himmelsdeuter","die händlerküste","ratschet","die tidusstaffel","wassertotem"},ang={["class:Shaman"]="Jeder Schamane der Horde wandert während seiner Prüfungen zur Bindung des Wassertotems irgendwann diese Küstenstufen hinab, um Islen Wasserdeuter aufzusuchen.",["race:Tauren"]="Die ruhige Gegenwart von Islen Wasserdeuter und Mahren Himmelsdeuter zeigt, wie Taurenseher selbst weit außerhalb der Grenzen von Mulgore eine spirituelle Wacht halten."},sec={{t="Stufen zum Meer",b="Die Tidusstaffel, die südöstlich von Ratschet zur Brandung hinabführt, ähnelt einer monumentalen Reihe verwitterter Steinstufen, die direkt in die Küstenklippen geschlagen wurden. Während das umliegende Brachland trocken, staubig und anfällig für Scharmützel ist, wird dieser ruhige Abschnitt mit Blick auf die Händlerküste vom Rauschen der brechenden Wellen beherrscht. Auf den Terrassen steht eine bescheidene Hütte, in der die Tauren Islen Wasserdeuter und Mahren Himmelsdeuter leben. Weit entfernt von den geschäftigen Handelsdocks der Goblins verbringen die beiden ihre Tage mit Fischen, beobachten den Horizont und suchen nach Erkenntnissen der Wassergeister an der Küste."}},faq={{q="Wo befindet sich die Tidusstaffel?",a="Die Tidusstaffel liegt an der Ostküste des Brachlands, direkt südöstlich des Goblinhafens Ratschet. Sie überblickt die Gewässer der Händlerküste.",al={"lage der tidusstaffel","wo ist die tidusstaffel","weg zur tidusstaffel"}},{q="Wer lebt an der Tidusstaffel?",a="Zwei Tauren haben hier ihr Zuhause: Islen Wasserdeuter und Mahren Himmelsdeuter. Sie leben in einer einfachen Hütte am Meer auf den Terrassen und verbringen ihre Zeit mit Angeln und der Zwiesprache mit der Natur.",al={"wer ist an der tidusstaffel","npcs an der tidusstaffel","wer lebt hier"}},{q="Warum ist die Tidusstaffel für Schamanen von Bedeutung?",a="Schamanen der Horde, die das Element des Wassers meistern wollen, werden quer durch Kalimdor geführt, um Islen Wasserdeuter an der Tidusstaffel aufzusuchen. Hier, am offenen Ozean, lernen die Initianden, mit den Gezeiten zu kommunizieren und reine Gewässer aufzuspüren, um ihr Wassertotem an sich zu binden.",al={"schamane tidusstaffel","wassertotem tidusstaffel","warum schamanen hierher kommen"}},{q="Gehört die Tidusstaffel zur Horde oder ist sie neutral?",a="Die dort ansässigen Tauren sind der Horde treu ergeben und leiten Hordenschamanen an, obwohl die abgelegenen Terrassen außerhalb aller formellen militärischen Grenzen liegen.",al={"ist die tidusstaffel horde","fraktion tidusstaffel"}}},fx={["95879c45"]={q="Was ist die Tidusstaffel?",a="Die Tidusstaffel ist eine beeindruckende natürliche geologische Formation an der Händlerküste, südöstlich von Ratschet. Mehrere breite Felsenterrassen erstrecken sich wie eine riesige steinerne Treppe hinunter zum großen Meer. Auf diesen Terrassen befindet sich friedlich ein einfacher Küstenunterstand mit Blick auf die Wellen, der einen ruhigen Zufluchtsort an der ansonsten belebten und trockenen Küste des Brachlands bildet.",al={"was ist die tidusstaffel","überblick über die tidusstaffel","geschichte der tidusstaffel"}},["4cc68021"]={q="Ist die Tidusstaffel gefährlich?",a="Die Treppe selbst ist ein ruhiger Zufluchtsort, geschützt vor den unmittelbaren Gefahren der offenen Ebenen. Die umliegende Händlerküste wird jedoch oft von der Küstenfauna und gefährlichen Piraten aus den nahegelegenen Verstecken des Südmeers durchstreift, daher sollten Reisende wachsam bleiben, während sie den Weg nach Süden entlang der Küste zurücklegen.",al={"ist die tidusstaffel sicher","gefahr an der tidusstaffel","bedrohungen an der tidusstaffel"}}},fp="11,254,16.579.0,29.153.0,25.174.0,42.242.0,49.135.0"}
P.entries["subzone:timbermaw-hold"] = {n="Holzschlundfeste",s="Die Holzschlundfeste ist ein befestigtes unterirdisches Tunnelnetzwerk, das den Teufelswald, Mondlichtung und Winterquell miteinander verbindet. Sie dient den Furbolgs der Holzschlund als Feste, einem der letzten Stämme, die der dämonischen Verderbnis widerstehen, die das nördliche Kalimdor heimsucht.",h="Die Holzschlundfeste ist ein befestigtes unterirdisches Tunnelnetzwerk, das den Teufelswald, Mondlichtung und...",kw={"teufelswald","furbolg","mondlichtung","holzschlund","holzschlundfeste","tunnel","winterquell"},ang={["class:Druid"]="Die Feste dient als entscheidende Bergpassage zwischen Eurem heiligen Refugium in Mondlichtung und der verwundeten Wildnis des Teufelswalds, wo die Geister der Furbolgs verzweifelt nach Reinigung verlangen.",["class:Shaman"]="Die Holzschlund haben ihre unverdorbene spirituelle Tradition und ihre Heilungsrituale tapfer aufrechterhalten, ungeachtet der Teufelsverderbnis, die direkt vor ihren Höhlentoren schwelt."},sec={{t="Ein Zufluchtsort inmitten des Verfalls",b="Tief in die Bergwurzeln zwischen dem Teufelswald, Mondlichtung und Winterquell gehauen, ragt die Holzschlundfeste als verzweifelt bewachte Bastion auf. Während benachbarte Furbolgstämme während des Dritten Krieges der üblen Verderbnis der Brennenden Legion anheimfielen, überstand der Stamm der Holzschlund den Albtraum in diesen steinernen Korridoren. Obwohl sie unter der Erde in Sicherheit waren, mussten sie mitansehen, wie ihre geliebten Wälder zu verdorbenen Zerrbildern verkamen. Äußerst beschützerisch und zutiefst misstrauisch gegenüber Außenstehenden bewachen die Furbolgs jeden Tunneleingang mit grimmiger Entschlossenheit und erwarten von jedem, der aus den infizierten Wäldern herbeiströmt, nur Gewalt."},{t="Kreuzweg des Nordens",b="Über ihre Rolle als Zufluchtsort für den Stamm hinaus ist die Holzschlundfeste die einzige direkte Bergstraße, die das verdorbene Tiefland des Teufelswalds, das heilige Refugium von Mondlichtung und die gefrorenen Weiten von Winterquell verbindet. Außenstehende, die sie durchqueren möchten, ohne von den Stammesposten in Stücke gerissen zu werden, müssen ihren guten Willen unter Beweis stellen. Diejenigen, die ihren Widerstand gegen die verdorbenen Furbolg-Clans der Region zeigen, finden in den Holzschlund standhafte Verbündete, die bereit sind, ihr uraltes schamanisches Wissen und ihre Lederverarbeitungstraditionen zu teilen."}},faq={{q="Warum greifen die Furbolgs in der Holzschlundfeste Besucher an?",a="Der Stamm der Holzschlund hegt von Natur aus Misstrauen gegenüber Außenstehenden, nachdem er mitansehen musste, wie seine benachbarte Verwandtschaft der Verderbnis der Brennenden Legion erlag. Aus Furcht davor, dass Fremde sie mit wilden, dämonischen Furbolgs verwechseln – oder die Verderbnis in ihr Zuhause tragen –, greifen sie jeden an, der sich ihren Tunneln nähert, bis ein Außenstehender seine friedlichen Absichten beweist.",al={"warum sind holzschlund feindlich","holzschlund greift mich an","holzschlund freundlich werden"}},{q="Welche Zonen verbindet die Holzschlundfeste?",a="Die Haupthöhle verzweigt sich in drei Hauptausgänge: den nördlichen Teufelswald im Südwesten, die friedvolle Zuflucht Mondlichtung im Norden und die frostigen Täler von Winterquell im Osten. Ein verbarrikadiertes Tor befindet sich zudem im nördlichen Azshara.",al={"holzschlundfeste tunnel ziele","wohin führt die holzschlundfeste","holzschlund ausgänge"}},{q="Wie überstanden die Holzschlund die Verderbnis der Legion?",a="Während die Wälder des Teufelswalds unter der dämonischen Teufelsenergie verdorrten, suchte der Stamm der Holzschlund tief in seinen Berghöhlen Zuflucht. Indem sie sich auf dem Höhepunkt der dämonischen Invasion in der Feste einschlossen, gelang es ihnen, ihren Verstand und ihre heiligen schamanischen Bräuche zu bewahren, während benachbarte Clans dem Wahnsinn anheimfielen.",al={"warum sind holzschlund unverdorben","holzschlund nicht verdorben"}},{q="Was ist die versiegelte Holztür im Inneren der Feste?",a="Tiefer in den Tunneln befindet sich eine runde Holzbarriere, die eine Seitenhöhle versperrt. Ihr genauer Zweck ist ungewiss, wenngleich Reisende mutmaßen, dass sie ältere Tunnelkomplexe abriegelt, die in Richtung der Tiefen des Baus oder anderer alter unterirdischer Kammern unter dem Hyjal führen.",al={"versperrte tür in der holzschlundfeste","holzschlundfeste verschlossenes tor"}}},fp="14,250,24.597.0,23.517.0,54.342.0,40.232.0,49.316.0,47.257.0"}
P.entries["subzone:timbermaw-post"] = {n="Holzschlundposten",s="Der Holzschlundposten ist ein kleines Furbolglager in der verschneiten Weite von Winterquell, eingebettet zwischen den Frostfeuerquellen und dem Kel'Therilsee. Obwohl er den Namen des nicht verderbten Stammes der Holzschlund trägt, ist das Lager unter die aggressive Kontrolle der verderbten Winterfallfurbolgs gefallen.",h="Der Holzschlundposten ist ein kleines Furbolglager in der verschneiten Weite von Winterquell, eingebettet...",kw={"die frostfeuerquellen","furbolg","kel'therilsee","holzschlund","holzschlundposten","winterfall","winterquell"},ang={["class:Druid"]="Für Druiden, die die Furbolgs als uralte Hüter der Natur verehren, ist der Anblick des Lagers, das von den wahnsinnigen Winterfallfurbolgs besetzt ist, ein deutlicher Beweis für den bleibenden Makel der Brennenden Legion."},sec={{t="Ein verdrängter Außenposten",b="Der Holzschlundposten liegt südöstlich, jenseits der Straße von den Frostfeuerquellen und westlich des zugefrorenen Kel'Therilsees, und steht als bittere Erinnerung an den internen Konflikt der Furbolgs in Winterquell. Trotz seines Namens Holzschlund werden Reisende, die sich dem Lager nähern, nicht freundlich empfangen. Der Außenposten wird von dem feindseligen Winterfallstamm kontrolliert, der durch dämonische Verderbnis in den Wahnsinn und die Gewalt getrieben wurde. Das Lager ist nun von wilden Winterfallfurbolgs überlaufen und dient als aggressiver Stützpunkt, der an die zentrale Straße grenzt."}},faq={{q="Warum heißt es Holzschlundposten, wenn dort Winterfallfurbolgs leben?",a="Trotz seines Namens wird das Lager vom verderbten Winterfallstamm kontrolliert. Seine Gründungsgeschichte ist nicht bekannt.",al={"warum holzschlundposten","wem gehört der holzschlundposten","furbolgs im holzschlundposten"}},{q="Wo befindet sich der Holzschlundposten?",a="Er liegt im zentralen Winterquell, südöstlich jenseits der Hauptstraße von den Frostfeuerquellen und direkt westlich des Kel'Therilsees.",al={"standort holzschlundposten","wo ist der holzschlundposten","karte holzschlundposten"}},{q="Sind die Furbolgs im Holzschlundposten feindselig?",a="Ja. Selbst wenn Ihr Euch einen friedlichen Ruf beim eigentlichen Stamm der Holzschlund verdient habt, gehören die Furbolgs, die diesen Posten bewohnen, zum feindseligen Winterfallstamm und werden Eindringlinge sofort angreifen.",al={"sind furbolgs hier feindselig","holzschlundposten freundlich","kann ich mit dem holzschlundposten sprechen"}}},fp="14,295,19.525.0,65.110.0,32.137.0,43.188.0"}
P.entries["subzone:tinker-town"] = {n="Tüftlerstadt",s="Die Tüftlerstadt ist das geschäftige Gnomviertel, das eingebettet in der unterirdischen Zwergenstadt Eisenschmiede liegt. Der Bezirk wurde eingerichtet, um Flüchtlingen nach dem tragischen Fall von Gnomeregan Obdach zu bieten, und dient als Sitz der Exilregierung von Hochtüftler Gelbin Mekkadrill sowie als Hauptbahnhof der Tiefenbahn.",h="Die Tüftlerstadt ist das geschäftige Gnomviertel, das eingebettet in der unterirdischen Zwergenstadt...",kw={"die tiefenbahn","ingenieurskunst","gnomeregan","eisenschmiede","mekkadrill","tüftlerstadt"},ang={["profession:Engineering"]="Für Ingenieure ist die Tüftlerstadt ein essenzieller Halt in Eisenschmiede, der neben der Tiefenbahn auch spezialisierte Ausbilder, Gadget-Händler und Bauteile bietet.",["race:Gnome"]="Die Tüftlerstadt ist das Herz Eures im Exil lebenden Volkes. Hier, umgeben von klappernden Prototypen und anderen Überlebenden, leitet Hochtüftler Mekkadrill die laufenden Bemühungen zur Rückeroberung von Gnomeregan."},sec={{t="Ein Zuhause im Exil",b="Als unterirdische Troggs die hochtechnologische Stadt Gnomeregan überrannten, öffneten die Zwergenwirte von Eisenschmiede ihre Tore für die Überlebenden. Um den plötzlichen Zustrom an Flüchtlingen unterzubringen, wurde ein höhlenartiger Bezirk – der zuvor Wohnort von Zwergen war und den Eingang zur Tiefenbahn beherbergte – für sie zur Verfügung gestellt. Unter dem wachsamen Auge von Hochtüftler Gelbin Mekkadrill und seinem Rat wurde die Tüftlerstadt schnell zu einem energiegeladenen Zentrum aus surrenden Zahnrädern, experimenteller Alchemie und Gadgets. Obwohl sie beengte Gäste in einer Stadt aus Stein sind, haben die Gnome ein Abbild ihrer Zivilisation um eine massive kugelförmige Apparatur herum wiederaufgebaut, fest entschlossen, ihre unterirdische Heimat zurückzuerobern."},{t="U-Bahn und Geheimnisse",b="Abgesehen davon, dass die Tüftlerstadt die gnomische Führung beherbergt, ist sie einer der strategisch wichtigsten Verkehrsknotenpunkte auf dem Kontinent. Der Bezirk beherbergt den Eingang der Tiefenbahn in Eisenschmiede, ein technisches Wunderwerk, das die Zwergenhauptstadt schnell mit Sturmwind verbindet."}},faq={{q="Warum leben Gnome in Eisenschmiede statt in ihrer eigenen Stadt?",a="Gnomeregan fiel einer plötzlichen, verheerenden Invasion primitiver Troggs zum Opfer. Anstatt die Allianz während des Dritten Krieges zu belasten, kämpften die Gnome allein und waren letztendlich gezwungen zu evakuieren. König Magni Bronzebart bot Eisenschmiede als Zufluchtsort an und erlaubte Hochtüftler Mekkadrill, diesen Bezirk als ihre temporäre Hauptstadt im Exil zu etablieren.",al={"warum sind gnome hier","warum leben gnome in eisenschmiede","gnom-flüchtlinge eisenschmiede"}},{q="Was macht der Eingang zur Tiefenbahn hier?",a="Die Tiefenbahn wurde als technisches Gemeinschaftswunder zwischen Gnomen und Zwergen erbaut, um Eisenschmiede direkt mit Sturmwind zu verbinden. Der Endbahnhof der Tiefenbahn in Eisenschmiede mündet direkt in die Tüftlerstadt und bietet Hochgeschwindigkeitsverkehr zwischen den beiden Hauptstädten der Allianz.",al={"wohin fährt die tiefenbahn","tiefenbahn in der tüftlerstadt","tüftlerstadt portal"}}},fx={d4e07867={q="Was ist die Tüftlerstadt?",a="Die Tüftlerstadt ist das Gnomviertel von Eisenschmiede, das um den großen Eingang zur Tiefenbahn herum angelegt wurde. Nach dem Fall von Gnomeregan hießen die Zwerge von Eisenschmiede ihre vertriebenen Verbündeten im Berg willkommen und gewährten ihnen diesen Bezirk, um ihre Gemeinschaft, ihre Werkstätten und ihre Ingenieurslabore wieder aufzubauen.",al={"was ist die tüftlerstadt","infos zur tüftlerstadt","gnomviertel in eisenschmiede"}},["37905e65"]={q="Wer regiert die Tüftlerstadt?",a="Die Tüftlerstadt dient als Sitz der Exilregierung der Gnome, die von Großtüftler Gelbin Mekkadrill und seinem Rat aus leitenden Beratern geführt wird. Unter seiner Führung wimmelt es in dem Bezirk von vertriebenen Gnomen, Meisteringenieuren, Alchemisten und Erfindern, die versuchen, eine neue Zukunft zu schmieden.",al={"wer leitet die tüftlerstadt","anführer der tüftlerstadt","wer ist verantwortlich für die tüftlerstadt"}},["70a740c2"]={q="Ist die Tüftlerstadt gefährlich?",a="Die Tüftlerstadt ist völlig sicher vor äußeren Feinden, da sie tief im befestigten Herzen von Eisenschmiede liegt. Da jedoch flüchtige alchemistische Gebräue, surrende Zahnräder und experimentelle Sprengstoffe in die überfüllten Werkstätten gepackt sind, sind kleinere mechanische Missgeschicke und feurige Unfälle nie ganz auszuschließen.",al={"ist die tüftlerstadt sicher","bedrohungen in der tüftlerstadt"}},["3f3e824e"]={q="Warum heißt es Tüftlerstadt?",a="Der Bezirk hat seinen Namen von der Leidenschaft der Gnome für das Tüfteln, Erfinden und mechanische Basteln sowie von dem Titel ihres gewählten Anführers, Großtüftler Gelbin Mekkadrill. Er dient als geschäftiges Zentrum für Tüftler, Ingenieure und Erfinder, die innerhalb der Zwergenhauptstadt arbeiten.",al={"warum heißt es tüftlerstadt","namensursprung der tüftlerstadt","herkunft des namens tüftlerstadt"}}},fp="11,310,15.671.0,18.264.0,61.345.0,45.264.0"}
P.entries["subzone:tinkers-court"] = {fx={d2a5bbc9={q="Was ist der Tinkers' Court?",a="Der Tinkers' Court ist das tiefste administrative Herz von Gnomeregan. In friedlichen Zeiten diente er als die große Kammer, in der der gewählte Großtüftler und der regierende Rat zusammenkamen, um das Volk der Gnome zu leiten, über technische Wunderwerke zu debattieren und das bürgerliche Leben zu beaufsichtigen. Heute steht er als befestigtes inneres Sanktum da, das von Verrätern beansprucht wird.",al={"was ist der tinkers' court","tinkers' court in gnomeregan","über den tinkers' court"}},["66d32e28"]={q="Was geschah während des Falls von Gnomeregan mit dem Tinkers' Court?",a="Als die Invasion der Troggs zuschlug, regierten Hochtüftler Gelbin Mekkadrill und seine Berater von dieser Halle aus. Nach dem katastrophalen Rat von Mekgineer Thermaplugg, Strahlung in der ganzen Stadt freizusetzen, um die Bestien zu beseitigen, wurde der Hof von giftigem Fallout überwältigt. Mekkadrill und die Überlebenden mussten fliehen und überließen die Kammer dem wahnsinnigen Verräter.",al={"was geschah im tinkers court","geschichte des tinkers court","fall des tinkers court"}},fddc0bd4={q="Warum wurde der Tinkers' Court aufgegeben und zerstört?",a="Der Hof wurde während der katastrophalen Verstrahlung von Gnomeregan aufgegeben. Die tödlichen radioaktiven Dämpfe, die die unteren Ebenen einhüllten, machten ein normales Leben für Gnom unmöglich, mutierten die Zurückgebliebenen zu wahnsinnigen Gnomlepra-Opfern und verwandelten den großen Regierungssitz in eine verschmutzte, mechanische Festung.",al={"warum ist der tinkers court zerstört","tinkers court aufgegeben","warum zerstört"}},["19b28a1e"]={q="Wie gefährlich ist der Tinkers' Court?",a="Es ist die am stärksten befestigte und gefährlichste Kammer in der gesamten zerstörten Stadt. Mekgineer Thermaplugg hat sich mit tödlichen Roboterwächtern, laufenden Mechanostridern und fanatischen Gnomlepra-Opfern umgeben. Wer sie betritt, muss zermalmende Maschinen, giftige Strahlen und die tödlichsten Kampferfindungen des wahnsinnigen Tüftlers überstehen.",al={"ist der tinkers court gefährlich","gefahren im tinkers court","wie gefährlich ist der tinkers court"}},a5ad6256={q="Warum heißt er Tinkers' Court?",a="Die Gesellschaft der Gnom wird nicht von Erbmonarchen geführt, sondern von gewählten visionären Erfindern, den Hochtüftlern, die an der Seite einer Versammlung aus Meisterhandwerkern und Gelehrten regieren. Die Kammer erhielt ihren Namen von diesem Gremium und diente als buchstäblicher Hof, an dem sich die Tüftler versammelten, um ihr Volk zu führen.",al={"warum heißt es tinkers court","bedeutung des namens tinkers court","warum der name tinkers court"}}}}
P.entries["subzone:tiragarde-keep"] = {n="Burg Tiragarde",s="Burg Tiragarde ist eine befestigte menschliche Festung an Durotars Schipperküste, südlich von Klingenhügel. Die ursprüngliche Festung wurde während der Invasion von Großadmiral Daelin Prachtmeer erbaut und ist auch heute noch von feindseligen Kul Tiraner Marinesoldaten unter Leutnant Benedict besetzt. Sie fungiert als trotziger, ständiger Dorn im Auge der Horde direkt auf deren eigenem Territorium.",h="Burg Tiragarde ist eine befestigte menschliche Festung an Durotars Schipperküste, südlich von Klingenhügel.",kw={"daelin prachtmeer","durotar","kul tiras","leutnant benedict","klingenhügel","schipperküste","burg tiragarde"},ang={["faction:Horde"]="Burg Tiragarde ist ein unverhohlener Invasionsstützpunkt der Allianz direkt vor der Haustür von Durotar; das Stürmen ihrer Zinnen und das Ausschalten von Leutnant Benedict ist eine Feuertaufe für junge Soldaten im Dienst von Klingenhügel.",["race:Human"]="Die Garnison verkörpert das unbeugsame, rachsüchtige Erbe von Kul Tiras und Admiral Proudmoore, die unter Missachtung der Diplomatie von Jaina Prachtmeer einen hartnäckigen Guerillakrieg führen."},sec={{t="Proudmoores Bastion",b="Errichtet während des Feldzugs von Großadmiral Daelin Prachtmeer zur Vernichtung von Thralls neu gegründetem Reich, bot Burg Tiragarde der Flotte von Kul Tiras einen befestigten Brückenkopf an den roten Gestaden von Durotar. Obwohl die Horde die Belagerung schließlich brach und Proudmoore auf der Insel Theramore tötete, wurde die Burg nie vollständig aufgegeben. Nachschubtruppen unter Leutnant Benedict eroberten die zerschlagenen Steinmauern zurück und befolgten die bestehenden Befehle des verstorbenen Admirals, einen unerbittlichen Krieg gegen die Orcs zu führen, während sie den von Lady Jaina Prachtmeer ausgehandelten Frieden gänzlich ablehnten."},{t="Ein Dorn in Durotars Flanke",b="Heute stehen die schimmernden weißen Zinnen der Burg in hartem Kontrast zu den purpurroten Klippen von Durotar. Gut ausgebildete Seeleute und Marinesoldaten aus Kul Tiras patrouillieren auf den Wehrgängen und starten Überfälle auf Nachschublinien nahe Klingenhügel. Für die Horde ist Burg Tiragarde ein anhaltendes Sicherheitsrisiko und ein lebendiges Bewährungsfeld. Befehlshaber der Orcs und Trolle beauftragen ständig junge Krieger damit, die Festung anzugreifen und Benedicts Soldaten niederzustrecken, um die Garnison in Schach zu halten, bevor die Menschen eine tiefere Offensive ins Landesinnere starten können."}},faq={{q="Warum gibt es Menschen in Durotar?",a="Diese Menschen sind Seeleute und Marinesoldaten aus Kul Tiras, die während der Invasion nach dem Dritten Krieg mit Großadmiral Daelin Prachtmeer eintrafen. Sie lehnen einen Frieden mit der Horde ab und halten diese Garnison aufrecht, um die Orcs zu bedrängen.",al={"warum ist die allianz hier","wer sind die menschen in tiragarde","menschliche soldaten durotar"}},{q="Gehören diese Menschen zu Jainas Truppen in Theramore?",a="Nein. Während Jaina Prachtmeer über die Insel Theramore herrscht und einen brüchigen Waffenstillstand mit Thrall aufrechterhält, folgen diese Soldaten den Befehlen ihres verstorbenen Vaters, Großadmiral Daelin Prachtmeer. Sie betrachten jeden Frieden mit Orcs als inakzeptablen Verrat.",al={"ist tiragarde theramore","sind sie leute von jaina prachtmeer","soldaten aus theramore hier"}},{q="Wer befehligt Burg Tiragarde?",a="Die Festung wird von Leutnant Benedict befehligt, einem Kul Tiraner Offizier, der nach den postumen Invasionsbefehlen von Admiral Proudmoore handelt, um die Küste zu sichern und die Horde anzugreifen.",al={"boss in tiragarde","wer führt burg tiragarde","leutnant benedict"}},{q="Warum hat die Horde sie nicht einfach ausgelöscht?",a="Die Burg ist befestigt und von disziplinierten, gut bewaffneten Truppen der Kul Tiraner besetzt. Während die Verteidiger von Klingenhügel häufig Scharmützel mit der Garnison austragen und sie als Bewährungsprobe für neue Rekruten nutzen, würde eine groß angelegte Belagerung schwere Verluste fordern und lebenswichtige Ressourcen von der Sicherung des Rests von Durotar abziehen.",al={"warum tiragarde nicht zerstören","warum steht die burg noch"}}},fx={["975f81a6"]={q="Was ist Burg Tiragarde?",a="Burg Tiragarde ist eine Küstenbefestigung der Allianz an der Schipperküste im südöstlichen Durotar. Sie wurde aus blassem Stein erbaut, der einen starken Kontrast zu den umliegenden roten Schluchten bildet, und dient als befestigter Brückenkopf für die der Horde feindlich gesinnten Streitkräfte der Menschen. Selbst in ihrem ramponierten Zustand bietet die Burg den Soldaten von Kul Tiras eine befestigte Basis, um nahegelegene Siedlungen wie Klingenhügel zu schikanieren.",al={"was ist burg tiragarde","was ist diese burg","erzählt mir von burg tiragarde"}},["6c9a5200"]={q="Was ist in Burg Tiragarde geschehen?",a="Großadmiral Daelin Prachtmeer errichtete die Burg hastig während seiner Invasion von Durotar, um Krieg gegen die junge Horde zu führen. Die Horde schlug zurück, griff die Festung an und zerschlug sie, bis sie fiel. Obwohl Prachtmeer später getötet wurde, wurden Reserveeinheiten unter Leutnant Benedict entsandt, um die zerstörte Burg zurückzuerobern und den Feldzug des gefallenen Admirals fortzusetzen.",al={"geschichte von burg tiragarde","was ist hier geschehen","schlacht um burg tiragarde"}},["79c67834"]={q="Warum ist Burg Tiragarde eine Ruine?",a="Die Festung liegt in Trümmern, weil die Horde sie während der anfänglichen Invasion von Großadmiral Daelin Prachtmeer in Durotar gestürmt und zerschlagen hat. Obwohl Leutnant Benedict und seine Verstärkung aus Kul Tiras den Ort erfolgreich wiederbesetzten, halten sie ihn eher als eine zerfallende, notdürftig geflickte Festung denn als ein makelloses Schloss, das ständig unter Belagerung und dem Druck nahegelegener orkischer Außenposten steht.",al={"warum ist burg tiragarde zerstört","warum ist die burg beschädigt","wer zerstörte burg tiragarde"}},["246e91e1"]={q="Ist Burg Tiragarde gefährlich?",a="Ja, sehr gefährlich für Mitglieder der Horde. Die Burg wird von gut ausgebildeten Kul Tiraner Marines und Seeleuten besetzt, die tiefen Hass auf Orcs hegen und Reisende entlang der Küste angreifen. Sie starten Raubzüge in Richtung Klingenhügel und verteidigen ihre Wälle erbittert gegen jeden Krieger der Horde, der ausgesandt wird, um sie zu vertreiben.",al={"ist burg tiragarde sicher","gefahr in burg tiragarde","sind die menschen in burg tiragarde gefährlich"}}},fp="14,360,20.550.0,26.519.0,32.220.0,53.232.0,28.177.0,43.324.0"}
P.entries["subzone:tkashi-ruins"] = {n="Ruinen von Tkashi",s="Die Ruinen von Tkashi sind uralte Steinüberreste südwestlich von Nesingwarys Expedition im nördlichen Schlingendorntal. Von feindseligen Bloodscalptrollen überrannt, bleibt der Ort eine Hochburg des Stammes.",h="Die Ruinen von Tkashi sind uralte Steinüberreste südwestlich von Nesingwarys Expedition im nördlichen...",kw={"bloodscalp","nesingwary","schlingendorntal","tkashi","ruinen von tkashi","trollruinen"},ang={["race:Troll"]="Für die Dunkelspeer sind Orte wie Tkashi düstere Erinnerungen an die uralten Stammesruinen, die von ihrer feindseligen Gurubashiverwandtschaft hinterlassen wurden und nun erbittert von den wilden Bloodscalp-Nachzüglern verteidigt werden."},sec={{t="Steine der Bloodscalp",b="Südwestlich von Hemet Nesingwary Jr.s Jagdlager gelegen, markiert das zerfallende Steinmauerwerk der Ruinen von Tkashi die uralte Domäne der Dschungeltrolle des Schlingendorntals. Heute ist das Lager stark von dem Bloodscalpstamm besetzt, der das Gebiet aggressiv verteidigt und zwischen den Ranken und verfallenem Stein seine schamanistischen Rituale abhält. Während Hemet Nesingwary Jr. in seinen Jagderinnerungen notierte, die Ruinen problemlos durchquert zu haben, empfinden moderne Reisende die Trolle als weit weniger zuvorkommend, da sie wertvolle Stammesrelikte bewachen, die im Schutt vergraben liegen."}},faq={{q="Wer lebt in den Ruinen von Tkashi?",a="Die Ruinen sind vom Bloodscalpstamm besetzt, einer feindseligen Fraktion von Dschungeltrollen, die den zerfallenden Komplex aggressiv gegen Außenstehende und rivalisierende Stämme verteidigt.",al={"wer ist hier","gegner in den ruinen von tkashi","trolle bei tkashi"}},{q="Wo befinden sich die Ruinen von Tkashi?",a="Sie liegen im nördlichen Schlingendorntal, direkt südwestlich des Flussübergangs in der Nähe von Nesingwarys Expedition.",al={"standort von tkashi","wo ist tkashi","ruinen von tkashi finden"}},{q="Was wird über Tkashi in Hemet Nesingwary Jr.s Schriften erwähnt?",a="In Kapitel drei seiner Memoiren, Die Grünen Hügel des Schlingendorntals (speziell auf Seite 21), hält Nesingwary fest, dass er und seine Jagdgesellschaft die Ruinen von Tkashi während ihrer frühen Tage im Dschungel ohne Zwischenfälle durchqueren konnten.",al={"nesingwary tkashi","grüne hügel tkashi"}}},fp="12,203,24.548.0,30.167.0,35.107.0,62.230.0"}
P.entries["subzone:tor-kren-farm"] = {n="Tor'krens Hof",s="Tor'krens Hof ist eine ruhige, ums Überleben kämpfende Schweinefarm im nordwestlichen Durotar, nahe dem Donnergrat und dem Südstrom. Misha Tor'kren kümmert sich um das Gehöft, während sie ängstlich auf Neuigkeiten von ihrem Sohn Kron wartet, der von einem Jagdausflug nicht zurückgekehrt ist.",h="Tor'krens Hof ist eine ruhige, ums Überleben kämpfende Schweinefarm im nordwestlichen Durotar, nahe dem...",kw={"durotar","kron","misha tor'kren","schweinehof","der südstrom","donnergrat","tor'krens hof"},ang={["class:Hunter"]="Mishas Warnungen vor den Krokilisken des Südstroms erinnern junge Jäger daran, wie gefährlich die Flussufer von Durotar sein können.",["faction:Horde"]="Die stille Tragödie auf Tor'krens Hof offenbart die alltäglichen Opfer, die einfache Siedler der Horde erbringen, während sie bestrebt sind, Durotars wilde Grenze zu zähmen."},sec={{t="Ein einsames Gehöft",b="Seinen Lebensunterhalt auf dem trockenen, unerbittlichen roten Boden von Durotar zu bestreiten, ist niemals einfach, doch Tor'krens Hof hatte es schwerer als die meisten. Südöstlich des Donnergrats gelegen, konzentriert sich das Gehöft auf die Schweinezucht in einem rauen Klima, in dem Futter und Wasser knapp sind. Im Gegensatz zu den geschäftigen Handelsposten oder schwer verteidigten Kasernen der Horde liegt der Hof abgelegen und ruhig und erwirtschaftet im Schatten der nahen Klippen nur karge Erträge."},{t="Die Sorge einer Mutter",b="Misha Tor'krens Sohn Kron zog vor einigen Tagen nach Westen, um entlang des Südstroms Krokilisken zu jagen, und ist nicht zurückgekehrt. Sie hatte ihn vor den bösartigen Raubtieren gewarnt, doch er ging im Zorn fort. Nun bittet sie vorbeikommende Abenteurer, nach ihm zu suchen oder ein Zeichen seines Schicksals zurückzubringen, da sie das Schlimmste befürchtet, aber ohne Gewissheit über das Geschehene nicht zu trauern beginnen kann."},{t="Der Verlust einer Mutter",b="Als ein Abenteurer Krons Amulett von den Krokilisken des Flusses zurückbringt, erkennt Misha es wieder und sagt, sie wisse nun, dass ihr Sohn tot sei. Da sie sein Schicksal nun kennt, kann sie endlich zu trauern beginnen."}},faq={{q="Wo befindet sich Tor'krens Hof?",a="Tor'krens Hof liegt im nordwestlichen Durotar, südöstlich des als Donnergrat bekannten Canyons, östlich des Südstroms.",al={"tor'krens hof lage","wo ist tor'krens hof","tor'krens hof finden"}},{q="Wer lebt auf Tor'krens Hof?",a="Misha Tor'kren betreibt die Schweinefarm. Ihr Sohn Kron wird vermisst, nachdem er aufgebrochen war, um entlang des Südstroms zu jagen.",al={"wer leitet tor'krens hof","tor'krens hof nscs","wer ist misha tor'kren"}},{q="Was geschah mit Mishas Sohn?",a="Kron ging vor Tagen auf die Jagd nach Krokilisken entlang des Südstroms und ist nicht zurückgekehrt. Misha bittet Reisende, ihn zu finden oder ein Zeichen seines Schicksals zurückzubringen.",al={"mishas sohn","kron tor'krens tod","wer ist kron"}},{q="Was produziert Tor'krens Hof?",a="Er wird als Schweinefarm betrieben, auch wenn raues Gelände und Abgeschiedenheit seine Erträge weitaus magerer halten als die anderer Viehzuchtbetriebe in Durotar.",al={"tor'krens hof betrieb","was für ein hof ist tor'krens hof","tor'krens schweine"}}},fx={["13fe9b16"]={q="Was ist Tor'krens Hof?",a="Tor'krens Hof ist ein bescheidenes Gehöft im nordwestlichen Durotar, versteckt zwischen dem Donnergrat und dem Südstrom. Es dient als Schweinefarm, hat jedoch Mühe, den Erfolg und Gewinn anderer Siedlungen in der Region zu erzielen. Unter der harten Wüstensonne gelegen, steht es für die ruhige, harte Arbeit alltäglicher Orcs, die versuchen, sich an der unbarmherzigen Grenze von Durotar einen Lebensunterhalt zu verdienen.",al={"was ist torkrens hof","wissen über torkrens hof","über torkrens hof"}},["11f4c018"]={q="Ist Tor'krens Hof gefährlich?",a="Das Gehöft selbst bietet relative Sicherheit, aber die Umgebung ist voller Gefahren. Es liegt in der Nähe des Südstroms und seines Einzugsgebiets, Gewässer, die von bösartigen Krokilisken befallen sind, die in der Vergangenheit bereits Leben gefordert haben. Zudem beherbergt das raue Gelände in der Nähe aggressive Wildtiere, was bedeutet, dass Reisende und Arbeiter immer wachsam sein müssen, wenn sie sich über die unmittelbare Grenze des Gehöfts hinauswagen.",al={"ist torkrens hof sicher","gefahren bei torkrens hof","gefahr bei torkrens hof"}},["65c8d3ec"]={q="Warum heißt es Tor'krens Hof?",a="Die Farm hat ihren Namen von der Familie Tor'kren, die sie erbaut hat und bewirtschaftet. Misha Tor'kren ließ sich auf dem Land nieder, um zusammen mit ihrem Sohn Kron Schweine zu züchten, und verlieh der kleinen, beständigen Farm ihren Familiennamen.",al={"warum heißt es torkrens hof","ursprung des namens torkrens hof","wer ist torkren"}}},fp="13,240,18.429.0,16.352.0,15.183.1,31.128.0,27.113.0,29.152.0,32.135.0"}
P.entries["subzone:tower-of-althalaxx"] = {n="Turm von Althalaxx",s="Der Turm von Althalaxx ist eine uralte Turmspitze der Hochgeborenen an der Küste der nördlichen Dunkelküste. Einst ein abgeschiedener Rückzugsort für den Zauberer Athrikus Narassin vor der Großen Zerschlagung, wird er heute von dämonischen Kultisten und Hexenmeistern heimgesucht, die finstere Künste praktizieren.",h="Der Turm von Althalaxx ist eine uralte Turmspitze der Hochgeborenen an der Küste der nördlichen Dunkelküste.",kw={"althalaxx","ameth'aran","athrikus narassin","bashal'aran","dunkler strand","dunkelküste","hochgeborene","satyr","schattenrat"},ang={["class:Warlock"]="Die finsteren Riten, die vom Kult des Dunklen Strandes durchgeführt werden, bezeugen den weitreichenden Einfluss und die anhaltende Präsenz des Schattenrats in Kalimdor.",["race:NightElf"]="Der Turm stellt eine düstere Mahnung an die Verderbnis der Hochgeborenen und den dämonischen Wahn dar, der auf dem Land der Ahnen verweilt und ein rasches Eingreifen von Darnassus erfordert."},sec={{t="Ein Rückzugsort der Hochgeborenen",b="Vor zehntausend Jahren siedelte Königin Azshara begünstigte Diener der Hochgeborenen in den Küstenstädten Ameth'Aran und Bashal'Aran an und übertrug dem mächtigen Zauberer Athrikus Narassin die Autorität über sie. Da er der bürgerlichen Verwaltung überdrüssig wurde, beschloss Athrikus, sich im nahe gelegenen Turm von Althalaxx zu isolieren. Als die Große Zerschlagung das alte Kalimdor zerriss, überdauerte der Turm an der trostlosen Küste der Dunkelküste als stille Ruine vergessener Elfenmagie."},{t="Der Dunkle Strand",b="In der heutigen Ära regt sich in dem Turm bösartige Zauberei. Hexenmeister, finstere Kultisten, die sich Kult des Dunklen Strandes nennen, und mit ihnen verbündete Satyrn haben sich unter der Führung von Athrikus Narassin selbst in der Ruine versammelt. Ihre Riten kanalisieren dämonische Magie und quälen die verweilenden Geister der uralten Toten, um unheilvollen Plänen zu dienen, die direkt mit dem dämonischen Schattenrat verknüpft sind."}},faq={{q="Was ist der Turm von Althalaxx?",a="Er ist ein uralter Magierturm der Elfen, der während der Herrschaft von Königin Azshara an der nördlichen Dunkelküste erbaut wurde und nun von dunklen Zauberern und Kultisten besetzt ist.",al={"turm von althalaxx","was ist althalaxx"}},{q="Wer hat den Turm ursprünglich erbaut und bewohnt?",a="Athrikus Narassin, ein mächtiger Zauberer der Hochgeborenen, der von Königin Azshara eingesetzt wurde, um die nahe gelegenen Siedlungen Ameth'Aran und Bashal'Aran zu überwachen, zog sich hierhin zurück, als er seiner Pflichten überdrüssig wurde.",al={"wer lebte hier","athrikus narassin","wer baute den turm"}},{q="Wer sind die Kultisten, die den Turm jetzt besetzen?",a="Sie gehören zum Kult des Dunklen Strandes, einer Sekte aus Hexenmeistern, Kultisten und Satyrn, die in dem zerstörten Turm finstere Riten abhalten.",al={"wer sind die kultisten","kult des dunklen strandes","althalaxx feinde"}},{q="Warum gibt es hier Geister und gequälte Seelen?",a="Die Kultisten führen finstere Rituale und Seelenbindungsmagie durch, wodurch sie die seit Langem toten Elfengeister der alten Dunkelküste für ihre Zauber qualvollen Martern unterziehen.",al={"warum gibt es geister","gequälte geister althalaxx"}}},fx={["1aaea03f"]={q="Ist der Turm von Althalaxx gefährlich?",a="Der Turm ist extrem gefährlich. Er wimmelt von fanatischen Hexenmeistern und Kultisten des Kults des Dunklen Strangs, die unter der Leitung des Schattenrats dämonischen Meistern dienen. Zusätzlich zu diesen dunklen Zauberern und ihren Satyr-Verbündeten wird das Gelände von gequälten Geistern und Gespenstern heimgesucht, die durch üble Zauberei gebunden sind.",al={"ist der turm von althalaxx sicher","gefahr am turm von althalaxx","gefahren am turm von althalaxx"}}},fp="18,265,19.473.0,15.397.1,31.141.0,44.189.0,45.131.0,47.156.0"}
P.entries["subzone:tower-of-arathor"] = {n="Der Turm von Arathor",s="Der Turm von Arathor ist ein verfallener Zaubererturm im ehemaligen Magierbezirk im südwestlichen Teil von Burg Stromgarde. Einst die Werkstatt von Archmage Trelane, wurde er während des Falls der Stadt überrannt und ist derzeit von Ogern der Boulderfist besetzt.",h="Der Turm von Arathor ist ein verfallener Zaubererturm im ehemaligen Magierbezirk im südwestlichen Teil von...",kw={"arathi","boulderfist","malin","ruul onestone","skuerto","stromgarde","der turm von arathor","trelane"},ang={["class:Mage"]="Der Turm dient als ernüchternde Erinnerung an das Schicksal von Stromgardes arkaner Enklave und zeigt zugleich Archmage Trelanes geschickte Beherrschung defensiver Elementarkonstrukte.",["faction:Alliance"]="Burg Stromgarde ist umkämpftes Gebiet; wenn Ihr den Agenten von Erzmagier Malin helft, Trelanes verlorene Artefakte zu bergen, verwehrt Ihr dem vordringenden Clan der Boulderfist mächtige magische Relikte."},sec={{t="Eine überrannte Bastion",b="Erbaut im Herzen des Magierbezirks von Burg Stromgarde und benannt nach dem alten Reich von Arathor, diente diese Spitze lange den Zauberern des Reiches. Sein bemerkenswertester Bewohner, Archmage Trelane, entwarf ein magisches Verteidigungsgitter, das auf verzauberte Edelsteine abgestimmt war, um das Sanktum zu schützen. Als jedoch das Syndikat und der Ogerclan der Boulderfist Stromgarde nach dem Dritten Krieg angriffen, zerfiel das Königreich. Trotz Trelanes verzweifelten Versuchen, den Turm mithilfe seiner arkanen Schutzschilde zu halten, überwältigte ihn die schiere rohe Gewalt der Oger. Gezwungen, um sein Leben aus der Stadt zu fliehen, ließ der Erzmagier seine wertvollsten arkanen Artefakte zurück und überließ die Spitze den Händen des Boulderfist-Grobians Ruul Onestone und seinen Anhängern."},{t="Die Rückholung der verlorenen Relikte",b="Selbst im Exil weigerte sich Trelane, sein Lebenswerk aufzugeben. Mit der Hilfe seines ehemaligen Schülers, Erzmagier Malin von den Kirin Tor, wurde eine Expedition aufgestellt, um sein Phylakterium, seine Kugel und seinen Glutachat aus den Ruinen zu bergen. Von der Zuflucht aus operierend, entdeckten Malins Agenten, dass die Oger die Steine geplündert hatten, die erforderlich waren, um die automatisierten Verteidigungsanlagen des Turms zu steuern. Durch die Herstellung eines verzauberten Ersatzachats und dessen Platzierung auf den Sockeln, die den Eingang des Turms säumen, konnten beschworene Wasserelementare erweckt werden, um die Ogerbesetzer zu vertreiben und wagemutigen Abenteurern die Bergung der Erbstücke des Erzmagiers zu ermöglichen."}},faq={{q="Was ist der Turm von Arathor?",a="Es ist ein Magierturm in den südwestlichen Ruinen von Burg Stromgarde. Zu Ehren des alten Menschenreichs Arathor benannt, diente er den Magiern des Königreichs als Studienzentrum, bis er an einfallende Oger fiel.",al={"der turm von arathor","stromgarde magierturm","arathi turm"}},{q="Wer lebt jetzt in dem Turm?",a="Der Turm und das umliegende Magierturmvierteil sind von Ogern der Boulderfist besetzt. Im Inneren der Turmspitze haust der Ogermagier Ruul Onestone zusammen mit seinen Wachen, die die von seinem ehemaligen Meister zurückgelassenen Relikte aufgespürt haben und bewachen.",al={"wer ist im turm von arathor","turm von arathor mobs","turm von arathor boss"}},{q="Wer war Archmage Trelane?",a="Archmage Trelane war ein bedeutender Zauberer von Stromgarde, der im Turm lebte und forschte. Er schuf dessen durch Edelsteine angetriebene Schutzsysteme und floh ins Exil, nachdem er das Sanktum nicht gegen den Angriff der Boulderfist verteidigen konnte.",al={"archmage trelane","wer besaß den turm","trelane"}},{q="Wie funktionieren die Verteidigungsanlagen des Turms?",a="Trelane stimmte den Turm so ab, dass er aktiviert wird, wenn ein verzauberter Achat an die Sockel gelegt wird, die seinen Eingang flankieren. Nach der Aktivierung beschwört die arkane Matrix feindselige Wasserelementare, die alle Eindringlinge am Eingang bekämpfen.",al={"turmverteidigung aktivieren","trelanes verteidigung","turmsockel"}}},fp="16,262,17.725.0,26.615.1,29.215.0,27.230.0,25.226.0,33.232.0"}
P.entries["subzone:tower-of-azora"] = {n="Turm von Azora",s="Der Turm von Azora ist ein schlanker Magierturm, der sich im östlichen Wald von Elwynn nördlich von Brackwells Kürbisbeet erhebt. Unter der Leitung des menschlichen Erzmagiers Theocritus dient die Enklave als gelehrter Außenposten, der in einer stillen magischen Fehde mit einem feindseligen Turm im benachbarten Rotkammgebirge gefangen ist.",h="Der Turm von Azora ist ein schlanker Magierturm, der sich im östlichen Wald von Elwynn nördlich von...",kw={"azora","elwynn","verzauberkunst","ilgalar","morganth","hellsicht","turmspitze","theocritus"},ang={["class:Mage"]="Für Magier, die jenseits von Sturmwind reisen, bietet der Turm einen abgelegenen Zufluchtsort zum Lernen, arkane Lehrer und einen Logenplatz bei den gefährlichen Künsten der Fernwahrsagerei.",["race:Gnome"]="Einen arkanen Turm in den Ländern der Menschen zu sehen, der unter Erzmagier Theocritus von Gnomen bemannt wird, ist ein stolzer Beweis für die Meisterschaft Eures Volkes über die mystischen Künste."},sec={{t="Ein Turm arkaner Wachsamkeit",b="An der östlichen Straße in Richtung des Rotkammgebirges gelegen, ist der Turm von Azora ein arkanes Refugium, dessen Belegschaft fast ausschließlich aus gnomischen Zauberwirkern besteht. Unter der Leitung von Erzmagier Theocritus erforschen diese Gelehrten sonderbare Kuriositäten und bieten wandernden Zauberwirkern magische Unterweisung. Die wilde magische Aura rund um die Turmspitze verdirbt gelegentlich die Tierwelt der Umgebung, sodass sich die gnomischen Bediensteten mit verzauberten Haushaltsgegenständen und mutierten Insekten herumschlagen müssen, die durch die Tür kriechen."},{t="Die Fehde mit Ilgalar",b="Hinter seiner ruhigen, gelehrten Fassade befindet sich der Turm in einem andauernden Krieg aus Hellsicht und Sabotage. Im Osten, auf den schroffen Klippen des Rotkammgebirges, thront die finstere Festung Der Turm von Ilgalar, beherrscht von dem abtrünnigen Hexenmeister Morganth. Theocritus und Morganth spionieren einander unaufhörlich mit arkanen Mitteln aus und heuern wagemutige Abenteurer an, um Hellsicht-Relikte wie das Eye of Azora zu platzieren, die Schutzschilde von Ilgalar zu durchdringen und Morganths finstere Machenschaften zu überwachen."}},faq={{q="Wer beherrscht den Turm von Azora?",a="Dem Turm steht Erzmagier Theocritus vor, ein vollendeter menschlicher Magier. Er leitet die Bediensteten im Inneren der Turmspitze und koordiniert ihre magische Verteidigung gegen rivalisierende Zauberer.",al={"wer leitet den turm von azora","wer hat hier das sagen","turm von azora boss"}},{q="Warum sind hier so viele Gnome?",a="Die Bediensteten von Azora sind überwiegend gnomische Forscher und Akolythen, die Erzmagier Theocritus bei seinen Studien, arkanen Experimenten und der Instandhaltung gegen magische Missgeschicke zur Seite stehen.",al={"warum gnom im elwynn turm","diener von azora"}},{q="Gegen wen kämpft der Turm?",a="Der Turm befindet sich in einer magischen Rivalität mit dem Turm von Ilgalar im Rotkammgebirge, der Heimat des bösen Zauberers Morganth. Beide Türme bespitzeln einander mit Hellsicht-Artefakten und streiten um ihren Einfluss.",al={"azora feind","turmfehde","wen spioniert azora aus"}},{q="Was ist das Eye of Azora im obersten Stockwerk?",a="Das Eye of Azora ist ein verzauberter Hellsicht-Fokus, der auf einem Tisch im oberen Sanktum ruht. Durch Berührung kann ein Betrachter über magische Distanzen hinweg die Umgebung des Turms von Ilgalar überwachen.",al={"kugel im obersten stockwerk","eye of azora","kristallkugel azora"}}},fx={e823b8a2={q="Was ist der Turm von Azora?",a="Der Turm von Azora ist ein bekannter Magierturm im zentralen Wald von Elwynn, östlich von Goldhain. Unter der Leitung von Theocritus, dem Erzmagier von Azora, dient er als magisches Refugium und Studienort für arkane Praktiker, der hauptsächlich mit gnomischen Dienern und Verzauberern besetzt ist.",al={"turm von azora","was ist dieser turm","über den turm von azora"}},["7c8bc76d"]={q="Ist der Turm von Azora gefährlich?",a="Der Turm ist ein sicherer Zufluchtsort für Reisende der Allianz und bietet Schutz und Ausbildung in der Verzauberkunst. Die starke magische Aura, die von der Spitze ausgeht, hat jedoch dazu geführt, dass alltägliche Gegenstände und Wildtiere, die dem Turm zu nahe kommen, verformt werden, was die Diener im Inneren dazu zwingt, sich mit bizarren Kuriositäten wie belebten Eimern und mutierten Schmetterlingen auseinanderzusetzen.",al={"ist der turm von azora gefährlich","gefahr am turm von azora","gefahren am turm von azora"}}},fp="14,299,27.497.0,21.444.1,29.185.0,34.181.0,34.218.0,42.200.0"}
P.entries["subzone:tower-of-eldara"] = {n="Turm von Eldara",s="Der Turm von Eldara ist eine uralte, versiegelte Turmspitze der Nachtelfen, die auf dem weit im Nordosten gelegenen Vorgebirge über der Bucht der Stürme in Azshara thront. Obwohl er längst verlassen ist, hat seine robuste Steinarchitektur die Zerschlagung überstanden und ragt stumm über Küsten auf, die von aggressiven Küstenbestien durchstreift werden.",h="Der Turm von Eldara ist eine uralte, versiegelte Turmspitze der Nachtelfen, die auf dem weit im Nordosten...",kw={"azshara","die bucht der stürme","eldara","hochgeborene","kaldorei","ruinen","turm von eldara"},ang={["class:Mage"]="Wie viele Bauwerke der Hochgeborenen in ganz Azshara summte der versiegelte Turm wahrscheinlich einst von arkanen Studien, bevor er vor sterblicher Einmischung verschlossen wurde.",["race:NightElf"]="Der Turm von Eldara ist eine ergreifende Mahnung an das glorreiche Reich, das Eure Vorfahren beherrschten, bevor Königin Azshara und die Hochgeborenen die alte Welt zerschlugen."},sec={{t="Ein Relikt des alten Azshara",b="Auf einer abgelegenen Klippe nordöstlich der Bucht der Stürme thront der Turm von Eldara als einsames Zeugnis des gewaltigen Kaldorei-Reichs, das einst diese Küstenlinie beherrschte. Wie ein Großteil der ruinierten Architektur Azsharas geriet er nach der Großen Zerschlagung vor Tausenden von Jahren in Vergessenheit. Heute bleibt der Eingang fest verschlossen und vor der Außenwelt verriegelt, ohne einen Hinweis darauf zu geben, welche Relikte oder Kammern im Inneren versiegelt liegen. Die umliegenden Ufer sind voller Gefahren und werden unaufhörlich von streunenden Murlocs, klauenschlagenden Makrura und räuberischen Hydren heimgesucht, die alle außer den wagemutigsten Reisenden fernhalten."}},faq={{q="Was ist der Turm von Eldara?",a="Er ist ein uralter Nachtelfenturm am nordöstlichen Klippenrand von Azshara, der die Bucht der Stürme überblickt. Er wurde vor der Großen Zerschlagung als Teil des weitläufigen Kaldorei-Reichs erbaut, das einst die Region umspannte.",al={"turm von eldara geschichte","was ist dieser turm","turm von eldara"}},{q="Kann man den Turm von Eldara betreten?",a="Nein. Der Turm ist verschlossen und vor Eindringlingen fest versiegelt. Welche Kammern oder Gewölbe auch immer im Inneren intakt geblieben sind, bleiben heutigen Forschern verwehrt.",al={"kann ich in den turm von eldara hineingehen","wie öffnet man den turm von eldara","ist der turm offen"}},{q="Welche Gefahren lauern um den Turm herum?",a="Die felsigen Klippen und die nahen Sandstrände rund um das Vorgebirge werden dicht von feindseligen Murlocs, gepanzerten Makrura und Küstenhydren patrouilliert.",al={"mobs nahe turm von eldara","feinde um eldara","kreaturen der bucht der stürme"}},{q="Wo genau befindet sich der Turm?",a="Ihr findet ihn an der äußersten östlichen Landspitze, die in das Große Meer hineinragt, direkt nordöstlich über die Gewässer der Bucht der Stürme in Azshara.",al={"turm von eldara standort","wo ist der turm von eldara","wie findet man eldara"}}},fp="15,292,26.615.0,28.229.0,34.147.0,37.147.0,35.140.0"}
P.entries["subzone:tower-of-ilgalar"] = {n="Der Turm von Ilgalar",s="Der Turm von Ilgalar ist eine isolierte Turmspitze, die hoch oben in den Felsen des östlichen Rotkammgebirges thront. Einst ein Rückzugsort für Zauberer, ist er im Schatten versunken als das Versteck von Morganth, einem verbannten Hexer aus Sturmwind, der nun die wilden Gnolle der Region befehligt und dunkle Magie praktiziert.",h="Der Turm von Ilgalar ist eine isolierte Turmspitze, die hoch oben in den Felsen des östlichen Rotkammgebirges...",kw={"azora","dunkelhunde","ilgalar","seenhain","morganth","rotkammgebirge","schattenfell","theocritus","der turm von ilgalar"},ang={["class:Mage"]="Der Turm dient als deutliche Warnung davor, was geschieht, wenn arkane Studien in verbotene dunkle Magie abdriften, und zieht den wachsamen Blick von Kirin Tor-Veteranen wie Theocritus auf sich.",["class:Warlock"]="Morganths Abhängigkeit von beschworenen Dunkelhunden und schattenhaften Flüchen spiegelt dämonische Künste wider, was seinen Rückzugsort in den Bergen zu einem faszinierenden Beispiel abtrünniger Zauberkunst außerhalb der städtischen Zirkel macht."},sec={{t="Ein Bollwerk dunkler Hexerei",b="Der über dem östlichen Rotkammgebirge aufragende Turm von Ilgalar dient als persönliches Heiligtum von Morganth. Aus dem Magierviertel von Sturmwind verstoßen, weil er sich mit verbotener Magie befasste, zog sich der abtrünnige Hexer in diese schroffen Höhen zurück, um ohne kaiserliche Einmischung tiefer in die dunklen Künste einzutauchen. Statt in Einsamkeit zu leben, übernahm Morganth die Herrschaft über den örtlichen Gnollclan der Schattenfell und setzte sie als wilde Wachen rund um die Basis der Turmspitze ein. Im Inneren wimmelt der Turm von beschworenen dämonischen Spürhunden und knistert vor schattenhafter Macht, was eine ständige, bedrohliche Gefahr für die bedrängte Stadt Seenhain unterhalb darstellt."},{t="Die Rivalität mit Azora",b="Gelehrte ziehen oft Parallelen zwischen dem Turm von Ilgalar und dem Turm von Azora im Wald von Elwynn. Während die wahre Identität von Ilgalar im Dunkeln bleibt, stehen die beiden Türme in stiller, magischer Opposition zueinander. In Elwynn behält der Erzmagier Theocritus Ilgalar durch verzauberte Spähvorrichtungen wie das Auge von Azora genau im Blick, überwacht Morganths finstere Experimente und plant, den Renegaten zu neutralisieren, bevor sich seine Verderbnis weiter durch das Königreich ausbreitet."}},faq={{q="Wer lebt im Turm von Ilgalar?",a="Der Turm wird von Morganth gehalten, einem abtrünnigen menschlichen Hexer, der aus der Stadt Sturmwind verbannt wurde, weil er verbotene dunkle Magie praktizierte. Er herrscht nun über den Turm, zusammen mit beschworenen dämonischen Dunkelhunden, und befehligt die örtlichen Schattenfellgnolle.",al={"wer ist im turm von ilgalar","boss im turm von ilgalar","wer kontrolliert den turm"}},{q="Warum floh Morganth ins Rotkammgebirge?",a="Morganth wurde aus dem Magierviertel in Sturmwind verstoßen, nachdem er sich den dunklen Künsten zugewandt hatte. Er zog sich in die abgelegenen Felsen des Rotkammgebirges zurück, um seine verbotenen Experimente fernab der wachsamen Augen der Behörden des Reiches und der Kirin Tor durchzuführen.",al={"warum ist morganth hier","hintergrundgeschichte von morganth","warum wurde morganth verbannt"}},{q="Was ist die Verbindung zwischen diesem Turm und dem Turm von Azora?",a="Beide Türme sind bedeutende magische Spitzen im südlichen Sturmwind, die in ihrer Bestimmung gespiegelt zu sein scheinen. Vom Turm von Azora im Wald von Elwynn aus späht der Magier Theocritus mithilfe des Auges von Azora aktiv auf das obere Heiligtum von Ilgalar, um Morganths dunkle Rituale zu überwachen.",al={"verbindung zum turm von azora","ilgalar und azora","auge von azora rotkammgebirge"}},{q="Warum bewachen Gnolle den Turm?",a="Morganth nutzte seinen magischen Einfluss, um den örtlichen Gnollclan der Schattenfell zu unterwerfen. Sie fungieren als äußere Wachen und Muskelkraft, die Eindringlinge, Späher und die Miliz von Seenhain davon abhalten, die Klippen zu seinem Heiligtum zu erklimmen.",al={"warum sind gnolle hier","schattenfellgnolle turm","gnolle um den turm"}}},fx={d387a688={q="Was ist der Turm von Ilgalar?",a="Der Turm von Ilgalar ist ein geheimnisvoller Magierturm, der hoch in den östlichen Höhen des Rotkammgebirges thront. Er wurde hoch über dem Immerruhsee errichtet und ähnelt dem Turm von Azora im Wald von Elwynn, doch ist er zu einer Bastion verbotener Zauberei geworden und nicht zu einem Ort rechtmäßiger arkaner Studien.",al={"was ist der turm von ilgalar","hintergrundgeschichte turm von ilgalar","magierturm rotkammgebirge"}},["30aed8f6"]={q="Ist der Turm von Ilgalar gefährlich?",a="Er ist außerordentlich gefährlich. Der Turm ist von feindseligen Schattenkammgnollen umringt, die dem Zauberer im Inneren gehorchen, während Schattenhundvertraute das Gelände patrouillieren. Wer die Wendeltreppe hinaufsteigt, steht Morganth persönlich gegenüber, einem verbannten Hexenmeister, der verheerende dunkle Magie beherrscht.",al={"ist der turm von ilgalar gefährlich","gefahren im turm von ilgalar","wie gefährlich ist der turm von ilgalar"}}},fp="16,285,25.620.0,22.485.0,34.231.0,34.239.0,65.273.0,40.217.0"}
P.entries["subzone:trade-district"] = {n="Der Handelsdistrikt",s="Der Handelsdistrikt ist das geschäftige kommerzielle Herz von Sturmwind, das direkt hinter den Haupttoren und dem Tal der Helden liegt. Er dient Abenteurern wie Bürgern gleichermaßen als zentraler Knotenpunkt und beherbergt die Hauptbank der Stadt, das Auktionshaus, das Gildenamt und verschiedenste Händlerläden.",h="Der Handelsdistrikt ist das geschäftige kommerzielle Herz von Sturmwind, das direkt hinter den Haupttoren und...",kw={"auktionshaus","basar","counting house","gilded rose","gryphon roost","sturmwind","der handelsdistrikt","visitor center"},ang={["faction:Alliance"]="Für die Champions der Allianz ist der Handelsdistrikt der Inbegriff eines Zentrums für Bankgeschäfte, das Handeln im Auktionshaus, das Organisieren von Gilden und Flüge über die Östlichen Königreiche."},sec={{t="Die Das Wegekreuz des Handels",b="Wer die steinernen Bögen aus dem Tal der Helden durchschreitet, gelangt unmittelbar in den Handelsdistrikt. Dieser lebendige, offene Platz fungiert als Sturmwinds wichtigster Marktplatz und logistisches Zentrum. In seiner Mitte steht das Auktionshaus, in dessen Nähe sich das Stormwind Counting House, die Hauptbank der Stadt, sowie das beliebte Gasthaus The Gilded Rose befinden. Das Viertel schlägt direkt die Brücke zwischen der militärischen Enklave von der Altstadt, dem friedvollen Kathedralenplatz und den arkanen Straßen des Magierviertels, wodurch sichergestellt wird, dass Münzen, Rohstoffe und Abenteurerbedarf rasch durch das Reich zirkulieren."},{t="Basare und Gildenhallen",b="Entlang der gepflasterten Straßen und angrenzenden Kanäle lässt sich jedes lebensnotwendige Gut erwerben. Waffenschmiede bei Weller's Arsenal und Lionheart Armory liefern Klingen und Kettenrüstungen, Bogner bieten bei The Empty Quiver Bögen an, und handwerkliche Stände führen von frischen Blumen bis hin zu edlen gereiften Tropfen der Gallina Winery einfach alles. Direkt hinter den Toren koordiniert das Stormwind Visitor's Center neu registrierte Satzungen und Wappenrockentwürfe für organisierte Abenteurergilden, während eine erhöhte Rampe auf der Ostseite zum Gryphon Roost hinaufführt und das Handelsleben der Hauptstadt mit den restlichen Gebieten der Allianz verbindet."}},faq={{q="Wo befindet sich der Handelsdistrikt?",a="Der Handelsdistrikt liegt direkt hinter den Haupteingangstoren der Stadt und dem Tal der Helden. Er schließt im Nordwesten direkt an den Kathedralenplatz an, im Osten an die Altstadt und im Südwesten über die Kanäle hinweg an das Magierviertel.",al={"der handelsdistrikt standort","wo ist der handelsdistrikt","weg zum handelsdistrikt"}},{q="Wo finde ich die Bank und das Gasthaus?",a="Das Stormwind Counting House (die Hauptbank der Stadt) und das Gasthaus The Gilded Rose befinden sich am südwestlichen Rand des Handelsdistrikts, direkt an der Hauptverkehrsader gelegen.",al={"der handelsdistrikt bank","gilded rose standort","sturmwind bank der handelsdistrikt"}},{q="Wo kann man in Sturmwind eine Gilde registrieren oder einen Wappenrock entwerfen?",a="Das Stormwind Visitor's Center, das zu Eurer Linken liegt, sobald Ihr den Handelsdistrikt durch die Stadttore betretet, beherbergt den Gildenmeister und die Dienste zur Wappenrockgestaltung.",al={"gildenmeister sturmwind","gildenfürsprecher","gilde gründen"}},{q="Wo kann man vom Handelsdistrikt aus einen Greifenflug nehmen?",a="Eine steinerne Rampe auf der Ostseite des Handelsdistrikts führt direkt hinauf zum Gryphon Roost, wo der Flugmeister Greifen über das gesamte Königreich und darüber hinaus aussendet.",al={"flugmeister sturmwind","gryphon roost sturmwind","wo ist der flugmeister"}}},fx={["747b4250"]={q="Was ist Der Handelsdistrikt?",a="Der Handelsdistrikt ist das geschäftige kommerzielle Herz von Sturmwind, das sich unmittelbar hinter den Haupttoren nach dem Tal der Helden befindet. Er dient als primäres Zentrum für Handel, Bankwesen und Reisen im Königreich. Reisende kommen hierher, um Waren zu tauschen, Proviant in geschäftigen Läden zu kaufen, Post zu versenden und das Zählhaus von Sturmwind zu besuchen. Er beherbergt auch den primären Gryphon Roost der Stadt, der Flugrouten durch die Östlichen Königreiche anbietet.",al={"übersicht über den handelsdistrikt","was ist das für ein ort","handelsdistrikt von sturmwind"}},d6628855={q="Warum heißt er Der Handelsdistrikt?",a="Der Distrikt hat seinen Namen von seiner Rolle als Sturmwind Hauptmarkt, der manchmal auch als Basarviertel bezeichnet wird. Kaufleute, Ladenbesitzer und reisende Händler versammeln sich hier, um fast jede Art von Waren zu verkaufen – von Rüstungen, Waffen und arkanen Reagenzien bis hin zu frischem Käse, Blumen und feinem Wein. Da er sich auf den Handel konzentriert, beherbergt er sowohl die Banktresore der Stadt als auch ihre geschäftigen Handelshäuser.",al={"warum handelsdistrikt","ursprung des namens handelsdistrikt","basarviertel"}},["7971c440"]={q="Ist Der Handelsdistrikt gefährlich?",a="Unter normalen Umständen ist Der Handelsdistrikt außergewöhnlich sicher. Er wird ständig von Wachen von Sturmwind patrouilliert und befindet sich direkt hinter den großen Toren, sodass er vor äußeren Bedrohungen geschützt ist. Während Diebe oder politische Spannungen im Schatten der Hauptstadt lauern könnten, können ehrliche Leute und reisende Abenteurer in Frieden handeln, Bankgeschäfte erledigen und ihre Besorgungen machen, ohne Angst vor den Gefahren der Wildnis haben zu müssen.",al={"ist der handelsdistrikt sicher","ist der handelsdistrikt gefährlich","gibt es gefahren im handelsdistrikt"}}},fp="14,293,26.599.0,23.612.0,36.228.0,38.188.0,60.170.0,58.169.0"}
P.entries["subzone:trade-quarter"] = {n="Handwerksviertel",s="Das Handwerksviertel bildet den zentralen Kern von Unterstadt und liegt direkt unter den Aufzügen von den Ruinen von Lordaeron. Es dient als schlagendes wirtschaftliches Herz der Verlassenen und beherbergt ihre primären Tresorgewölbe, das Auktionshaus und wichtige bürgerliche Dienste. Von diesem konzentrischen Knotenpunkt aus zweigen gewölbte Korridore in die umliegenden Viertel ab.",h="Das Handwerksviertel bildet den zentralen Kern von Unterstadt und liegt direkt unter den Aufzügen von den...",kw={"auktionshaus","bank","fledermausführer","särge","gasthaus","jeremiah payson","handwerksviertel","unterstadt"},ang={["faction:Horde"]="Für Abgesandte der Orcs, Tauren oder Trolle, die in Tirisfal eintreffen, dient das Handwerksviertel als das fremdartige, schattenhafte Marktzentrum ihrer nördlichen Verbündeten.",["race:Undead"]="Das Handwerksviertel verkörpert die rasche Wiedererlangung einer zivilisierten Ordnung durch die Verlassenen, die unterirdische Verliese in einen florierenden Markt verwandelt haben, der der Finanzierung ihres Überlebens dient."},sec={{t="Herz der Krypten",b="Wer von der zerstörten Oberfläche von Lordaeron hinabsteigt, tritt aus den Aufzügen in die hallenden Steinweiten des Handwerksviertels. Aufgeteilt in einen terrassierten, kreisförmigen Grundriss, beherbergt seine zentrale Plattform die Stadtkasse und die Zentralbank, umrahmt von Brücken, die giftige Abwasserkanäle überspannen. Auf den umliegenden Terrassen herrscht reges Treiben von Händlern, Gildennamen-Registrierern und Auktionatoren, die in der unheimlichen Düsternis feilschen. Selbst einfache Unterkünfte spiegeln den Pragmatismus der Verlassenen wider: Das hiesige Gasthaus bietet ungefütterte Holzsärge statt weicher Betten. Von diesem zentralen Knotenpunkt aus führen Steinbögen nach außen in die spezialisierten Viertel der Stadt, was ihn zum unvermeidlichen Kreuzungspunkt für jedes Geschäft innerhalb der Hauptstadt macht."}},faq={{q="Wo befindet sich das Handwerksviertel?",a="Das Handwerksviertel nimmt den toten Mittelpunkt von Unterstadt ein. Wenn Ihr die Hauptstadt über die Aufzüge an der Oberfläche unter den Ruinen von Lordaeron betretet, tretet Ihr unmittelbar auf den oberen Ring des Viertels.",al={"handwerksviertel standort","handwerksviertel finden","wo ist handwerksviertel"}},{q="Welche Dienste gibt es im Handwerksviertel?",a="Das Viertel beherbergt die zentrale Bank von Unterstadt, ein Auktionshaus am äußeren Ring, das Hauptgasthaus, einen Fledermausführer für Flugreisen, Gildennamen-Registrierer und verschiedene Handwerkslehrer, darunter den Kochlehrer der Stadt.",al={"handwerksviertel dienste","was gibt es im handwerksviertel","unterstadt bank standort"}},{q="Warum gibt es Särge im Gasthaus?",a="Die Physiologie der Verlassenen verlangt keinen echten Schlaf, und viele behalten Gewohnheiten bei, die ihrem untoten Zustand entsprechen. Das Gasthaus stellt einfache, ungefütterte Holzsärge statt herkömmlicher Betten bereit – eine alltägliche Bequemlichkeit für die Toten, für lebende Besucher jedoch zutiefst beunruhigend.",al={"unterstadt gasthaus särge","warum särge im gasthaus","unterstadt betten"}},{q="Wer ist der Händler, der unter den Brücken lauert?",a="Jeremiah Payson verdient seinen Lebensunterhalt unter einer der zentralen Brücken, die zur Bank führen. Während die regulären Händler oben Waffen und Handwerkswaren feilbieten, verkauft Payson lebende Haustierkakerlaken an neugierige Passanten.",al={"jeremiah payson","kakerlakenhändler unterstadt","wer verkauft kakerlaken"}}},fx={d7706923={q="Was ist das Handwerksviertel?",a="Das Handwerksviertel dient als zentraler Knotenpunkt und pulsierendes Herz der Unterstadt. Diese abgestufte kreisförmige Kammer liegt direkt hinter den Aufzügen, die von den Ruinen der Hauptstadt oben herabführen, und ist über gewundene Kanäle direkt mit allen anderen Vierteln verbunden. Es fungiert als das geschäftige Handelszentrum des Reiches und beherbergt das große Bankgewölbe, Gemischtwarenhändler, Gildenangebote und die wichtigsten Versammlungsorte der Stadt.",al={"was ist das handwerksviertel","handwerksviertel unterstadt","zentrum der unterstadt"}},b95b8a75={q="Was geschah bei der Erschaffung des Handwerksviertels?",a="Ursprünglich unter dem Königspalast und der Hauptstadt von Lordaeron ausgehoben, beherbergten diese unterirdischen Hallen einst Kerker, Krypten und Abwasserkanäle. Nach dem Fall von Lordaeron an die Geißel und Prinz Arthas führte Fürstin Sylvanas Windläufer die Verlassenen bei der Rückeroberung des Gebiets an. Sie erweiterten und gestalteten die zentralen unterirdischen Kammern zu einem befestigten Stadtzentrum um, um Handel zu treiben und ihr neues souveränes Reich zu verwalten.",al={"geschichte des handwerksviertels","wie entstand das handwerksviertel","historie des handwerksviertels"}},["5eb4f186"]={q="Ist das Handwerksviertel gefährlich?",a="Für Mitglieder der Horde und Verbündete der Dunklen Fürstin ist das Handwerksviertel einer der sichersten Orte im Reich, der schwer von turmhohen Monstrositäten und königlichen Wachen bewacht wird. Es ist jedoch absolut tödlich für Mitglieder der Allianz oder ungebetene Eindringlinge, die sofort bei ihrer Ankunft aus den Ruinen oben auf der Stelle getötet werden.",al={"ist das handwerksviertel sicher","ist das handwerksviertel gefährlich","bedrohungen handwerksviertel"}},["49015933"]={q="Warum heißt es Handwerksviertel?",a="Es verdankt seinen Namen seiner Funktion als wichtigstes Handelsviertel der Hauptstadt der Verlassenen. Das zentrale Gewölbe beherbergt die Stadtkasse und die Bank, während die umliegenden Ringe und Ebenen Händlerstände, Auktionshäuser, Handwerksbedarf und Gildenvermittler beherbergen, die alle wichtigen Geschäftstransaktionen im gesamten Königreich ermöglichen.",al={"warum heißt es handwerksviertel","name handwerksviertel","warum handwerksviertel"}}},fp="13,354,19.694.0,35.206.0,45.214.0,33.269.0,46.212.0"}
P.entries["subzone:tradesmen-s-terrace"] = {n="Die Terrasse der Händler",s="Die Terrasse der Händler ist das geschäftige kommerzielle Herz von Darnassus, gelegen entlang der südlichen Flanke der Stadt. Sie vereint Handwerker, Händler und das örtliche Auktionshaus unter der geschwungenen Holzarchitektur der Nachtelfenhauptstadt. Die Terrasse dient als primäre Handelsverbindung zwischen Kunsthandwerkern und Abenteurern, die durch Teldrassil und darüber hinaus reisen.",h="Die Terrasse der Händler ist das geschäftige kommerzielle Herz von Darnassus, gelegen entlang der südlichen...",kw={"auktionshaus","darnassus","kaldorei","kaufleute","läden","teldrassil","die terrasse der händler","händler"},ang={["faction:Alliance"]="Die Terrasse bietet Reisenden der Allianz, die über Rut'theran ankommen, Zugang zu Banken, Auktionatoren und wichtigem Handwerksbedarf, bevor sie tiefer nach Kalimdor aufbrechen.",["race:NightElf"]="Für die Nachtelfen ist die Terrasse der Händler ein seltener Ort dichter städtischer Geschäftigkeit, angepasst, um das friedliche Blätterdach von Darnassus ohne die störende Industrie anderer Völker zu bewahren."},sec={{t="Der Handelsknotenpunkt von Darnassus",b="Die Terrasse der Händler erstreckt sich über den südlichen Teil von Darnassus und beherbergt das kaufmännische Leben der Hauptstadt. Während ein Großteil der Stadt stiller Einkehr, Zufluchtsorten in der Wildnis und spirituellen Pflichten gewidmet ist, versammelt diese Terrasse Ladenbesitzer, Handwerker und Kaufleute, die sowohl den einheimischen Kaldorei als auch Reisenden aus der gesamten Allianz dienen. Sie beherbergt das zentrale Auktionshaus von Darnassus, Gemischtwarenhändler und Handwerksbedarfsgeschäfte, was sie zum unverzichtbaren Ausgangspunkt für Reisen in die Wildnis macht. Breite Fußwege verbinden sie nach Norden direkt mit der Terrasse der Krieger und nach Westen mit den ruhigen Gewässern der Tempelgärten und dem erhabenen Tempel des Mondes."},{t="Handwerker und Händler",b="Das Handwerk der Kaldorei legt Wert auf Harmonie mit der Natur, und die Geschäfte hier spiegeln dieses feine Gleichgewicht wider. Selbst inmitten des alltäglichen Handels kommt die Terrasse ohne die tosenden Schmelzöfen oder den Smog aus, die man in Werkstätten der Zwerge oder Menschen findet, und setzt stattdessen auf ruhigen Stein, ausgewähltes Holz und gewobene Waren. Für reisende Abenteurer, die Handelsverträge, Reparaturen oder aus den dichten Ästen von Teldrassil gesammelte Materialien suchen, stellt die Terrasse das wichtigste Geschäftszentrum im nördlichen Kalimdor dar."}},faq={{q="Was ist die Terrasse der Händler?",a="Die Terrasse der Händler ist das südliche Marktviertel von Darnassus. Sie dient als Handelszentrum der Nachtelfenhauptstadt und beherbergt die meisten Händler, Handwerker und das zentrale Auktionshaus der Stadt.",al={"was ist dieser ort","terrasse der händler info","terrasse der händler darnassus"}},{q="Wo befindet sich das Auktionshaus in Darnassus?",a="Das Auktionshaus von Darnassus befindet sich genau hier auf der Terrasse der Händler. Es bietet Reisenden, Händlern und Einheimischen Zugang zum stadtweiten und allianzweiten Handel.",al={"darnassus auktionshaus","ah standort darnassus","wo ist das ah"}},{q="Wie erreiche ich von hier aus die anderen Viertel?",a="Pfade von der Terrasse der Händler führen nach Norden auf die Terrasse der Krieger und nach Westen in Richtung der Tempelgärten und des emporragenden Tempel des Mondes.",al={"ausgänge von der terrasse der händler","wohin führt diese terrasse","terrasse der händler verlassen"}},{q="Welche Arten von Händlern gibt es in diesem Viertel?",a="Die Terrasse beherbergt eine breite Vielfalt an Gemischtwarenhändlern, Handwerkswarenverkäufern und Handwerkern, die den täglichen Bedarf decken, Reparaturen anbieten und in ganz Teldrassil hergestellte Waren verkaufen.",al={"händler terrasse der händler","was kann man hier kaufen","händlerläden"}}},fx={f0c60839={q="Ist Die Terrasse der Händler gefährlich?",a="Überhaupt nicht. Die Terrasse der Händler ist einer der sichersten und am dichtesten besiedelten Sektoren in Darnassus. Als das geschäftige kommerzielle Herz der Hauptstadt der Nachtelfen wird sie ständig von Stadtwachen patrouilliert und ist voller Händler, Handwerker und anderer Reisender der Allianz, die friedlich ihren Geschäften nachgehen.",al={"ist die terrasse der händler sicher","gefahr auf der terrasse der händler","terrasse der händler sicher"}},a7d49f79={q="Warum heißt sie Die Terrasse der Händler?",a="Der Distrikt hat seinen Namen direkt von seiner Rolle als Darnassus zentraler Knotenpunkt für Handel und Handwerk. Er dient als die designierte kommerzielle Terrasse der Hauptstadt und beherbergt die Gildenhandwerker, Ladenbesitzer, allgemeinen Lieferanten und das zentrale Auktionshaus der Stadt.",al={"warum terrasse der händler","name terrasse der händler","warum heißt sie terrasse der händler"}}},fp="19,370,31.671.0,20.467.0,28.216.0,40.158.0,45.140.0,49.169.0"}
P.entries["subzone:train-depot"] = {n="Train Depot",s="Das Train Depot ist ein unterirdischer Verkehrsknotenpunkt direkt unterhalb der oberirdischen Eingänge von Gnomeregan in Dun Morogh. Einst ein geschäftiges Zentrum gnomischer Fortbewegung, wimmelt es hier heute von feindseligen Lepragnomen und eindringenden Troggs.",h="Das Train Depot ist ein unterirdischer Verkehrsknotenpunkt direkt unterhalb der oberirdischen Eingänge von...",kw={"clockwerk run","dun morogh","gnomeregan","lepragnom","loading room","namdo bizzfizzle","train depot","trogg"},ang={["profession:Engineering"]="Ingenieure, die nach seltenen Bauplänen suchen, kundschaften oft die unteren Bahnsteige des Depots aus, wo überlebende Gnom-Händler wie Namdo Bizzfizzle inmitten der Trümmer noch immer ihren Handel treiben.",["race:Gnome"]="Für verbannte Gnome ist das verlassene Depot ein tragischer Anblick, der den Ruin der fortschrittlichen Fortbewegungssysteme zeigt, die einst ihre unterirdische Metropole verbanden."},sec={{t="Ein zerstörter Verkehrsknotenpunkt",b="Am Fuße des großen Aufzugs gelegen, der von Dun Morogh hinabführt, diente das Train Depot einst als wichtigster Knotenpunkt für den Schienenverkehr des unterirdischen Wunders von Gnomeregan. Heute liegen die Bahnsteige und Gleisbetten in Trümmern. Der radioaktive Niederschlag, der die Stadt verstrahlte, verwandelte die verbliebenen Arbeiter in wahnsinnige Lepragnome, während unterirdische Troggs die Gleise überrannt haben. Forscher, die in die zerstörte Stadt hinabsteigen, müssen dieses Aufmarschgebiet durchqueren, um tiefere Sektoren wie den Clockwerk Run, den Loading Room und die inneren Ingenieursanlagen zu erreichen."}},faq={{q="Wo befindet sich das Train Depot?",a="Das Train Depot liegt direkt unterhalb des Eingangsfahrstuhls an der Oberfläche in Dun Morogh und fungiert als einer der äußeren Schwellenbereiche, bevor man in das Herz von Gnomeregan vordringt.",al={"train depot ort","wie man zum train depot kommt","train depot eingang"}},{q="Welche Kreaturen bewohnen das Train Depot jetzt?",a="Das Depot wird von wilden Troggs überrannt, die sich aus den Tiefen der Erde heraufgegraben haben, sowie von elenden Lepragnomen, die während der radioaktiven Katastrophe ihren Verstand verloren haben.",al={"train depot gegner","mobs im train depot","wer ist im train depot"}},{q="Wohin führen die Wege vom Train Depot?",a="Passagen führen nach Westen in den Clockwerk Run und in Richtung des Loading Room, während ein nördlicher Werkstattbereich eine Hintertür hinab in die oberen Engineering Labs beherbergt.",al={"train depot ausgänge","wohin führt train depot","train depot verbindungen"}},{q="Wer versteckt sich im Train Depot?",a="Namdo Bizzfizzle, ein Ingenieursbedarfshändler, schafft es, versteckt unter der Nordseite des Hauptbahnsteigs auf der unteren Ebene des Depots zu überleben.",al={"namdo bizzfizzle","train depot nsc","train depot händler"}}},fx={["34ec9e38"]={q="Was ist mit dem Train Depot passiert?",a="Als die Invasion der Troggs und die darauffolgende Verstrahlung Gnomeregan überwältigten, wurden die Bahn- und Transitsysteme der Stadt vollständig unterbrochen. Das Depot wurde schnell von den gesunden Gnomen aufgegeben und blieb, genau wie der Rest der zerstörten unterirdischen Metropole, dem Verfall überlassen.",al={"geschichte train depot","was ist im train depot passiert","fall des train depot"}},b2726984={q="Warum ist das Train Depot ruiniert?",a="Die katastrophale Freisetzung radioaktiven Fallouts in ganz Gnomeregan brachte den normalen Betrieb zum Erliegen. Die Infrastruktur brach zusammen, als sich überlebende Arbeiter in geistlose Schrottgnome verwandelten oder flohen, wodurch die Maschinen und Korridore des Depots vernachlässigt wurden und mit feindseligen Bedrohungen überwucherten.",al={"warum ist das train depot verlassen","warum ist das train depot zerstört","train depot ruine"}},ab6b6be9={q="Wie gefährlich ist das Train Depot?",a="Das Gebiet ist für unvorbereitete Reisende außergewöhnlich gefährlich. Wilde unterirdische Troggs und verstrahlte, feindselige Schrottgnome durchstreifen die Bahnsteige und Korridore und greifen jeden an, der ohne Zögern aus Dun Morogh hinabsteigt.",al={"ist das train depot gefährlich","bedrohungen im train depot","gefahr im train depot"}},["9f84ab0b"]={q="Warum heißt es Train Depot?",a="Es verdankt seinen Namen seiner ursprünglichen Bestimmung als zentraler Bahnhof und Verladeterminal für die komplexen mechanischen Zugnetzwerke, die einst Fracht und Passagiere durch ganz Gnomeregan transportierten.",al={"warum train depot","bedeutung des namens train depot","gibt es hier einen zug"}},["08edd791"]={q="Was ist das Train Depot?",a="Das Train Depot ist ein weitläufiger Transitsektor, der sich direkt unter den Eingangsaufzügen von Gnomeregan befindet. Vor dem Fall der Stadt diente er als geschäftiger Verkehrsknotenpunkt, der die oberen Ebenen mit den tieferen Werkstätten und zentralen Einrichtungen verband.",al={"was ist das train depot","train depot in gnomeregan","über das train depot"}}},fp="11,222,20.566.0,33.171.0,43.153.0,45.154.0,33.145.0"}
P.entries["subzone:tranquil-gardens-cemetery"] = {fx={["86a6efa8"]={q="Was ist der Friedhof \"Stille Gärten\"?",a="Der Friedhof \"Stille Gärten\" ist eine alte Begräbnisstätte, die direkt südöstlich von Dunkelhain im Dämmerwald liegt. Einst ein friedlicher Ruheort, hat der dunkle Fluch, der die Region überkommen hat, die Toten aus ihren Gräbern gerissen. Der Friedhof zeichnet sich durch verwilderte Grabstellen und eine verfallene Kapelle aus, die nun von wandernden Skeletten und Ghulen überrannt wird.",al={"was sind die stillen gärten","lore friedhof stille gärten","erzähle mir von den stillen gärten"}},["77d44972"]={q="Warum ist der Friedhof \"Stille Gärten\" verfallen?",a="Wie ein Großteil des Dämmerwalds verfiel auch der Friedhof \"Stille Gärten\", als Dunkelheit und unnatürliche Plagen das Gebiet verschlangen. Die Kirche des Friedhofs verfiel und die Toten gruben sich aus der geweihten Erde, was die lebenden Wärter zwang, das Gelände vollständig aufzugeben.",al={"warum sind die stillen gärten ruiniert","friedhof stille gärten ruiniert","warum ist die kapelle ruiniert"}}}}
P.entries["subzone:tundrid-hills"] = {n="Die Tundrid-Hügel",s="Die Tundrid-Hügel sind ein schroffes, schneebedecktes Hochland im südlichen Zentrum von Dun Morogh, direkt westlich des Gol'bolar Steinbruchs gelegen. Von gefährlicher Bergwelt bewohnt, werden die felsigen Pässe von einfachen Reisenden nur selten durchquert.",h="Die Tundrid-Hügel sind ein schroffes, schneebedecktes Hochland im südlichen Zentrum von Dun Morogh, direkt...",kw={"das coldridgetal","dun morogh","frostmane","der steinbruch gol'bolar","eisenschmiede","kharanos","die tundrid-hügel"},ang={["class:Hunter"]="Die windgepeitschten Klippen bieten raues Fährtengelände voller widerstandsfähiger Bestien, die an die unbarmherzige Bergkälte von Dun Morogh angepasst sind.",["race:Dwarf"]="Für die Bergsteiger von Eisenschmiede dienen diese Höhen als allgegenwärtige Erinnerung daran, dass die Wildnis und die feindseligen Frostmane-Trolle dicht an das Kernland von Dun Morogh heranreichen."},sec={{t="Eine tückische Wildnis",b="Zwischen dem Coldridgetal und dem Tiefland des östlichen Dun Morogh erstrecken sich die Tundrid-Hügel und bieten eine unwegsame Querfeldein-Route für jene, die die Hauptstraßen durch Kharanos umgehen möchten. Dieser Komfort hat jedoch einen hohen Preis. Auf den zerklüfteten Schneehängen lauern wilde Raubtiere, was das Gebiet für unvorsichtige Reisende gefährlich macht, die sich ohne gezogene Waffe abseits der ausgetretenen Pfade wagen."}},faq={{q="Wo befinden sich die Tundrid-Hügel?",a="Die Tundrid-Hügel erstrecken sich über den südlich-zentralen Teil von Dun Morogh, liegen westlich des Gol'bolar Steinbruchs und bilden eine natürliche, erhabene Grenze südlich der Hauptstraße, die Kharanos mit den östlichen Ländern verbindet.",al={"lage der tundrid-hügel","wo liegen die tundrid-hügel","karte der tundrid-hügel"}},{q="Warum sollte jemand durch die Tundrid-Hügel reisen?",a="Abenteurer nutzen diese rauen Bergrücken bisweilen als Überlandabkürzung zwischen dem Coldridgetal und dem östlichen Dun Morogh, um die Routen der etablierten Siedlungen zu umgehen, auch wenn dies weitaus gefährlicher ist, als auf den patrouillierten Straßen zu bleiben.",al={"warum zu den tundrid-hügeln reisen","tundrid-hügel abkürzung"}},{q="Welche Gefahren lauern in den Tundrid-Hügeln?",a="Die Hügel beherbergen eine wilde einheimische Tierwelt, die an die eisigen Höhen gewöhnt ist, und nur wenige reisen hierher, ohne eine Waffe griffbereit zu haben.",al={"was lebt hier","feinde in den tundrid-hügeln","monster in den tundrid-hügeln"}}},fx={["6d54f98b"]={q="Ist das Reisen durch die Tundrid-Hügel gefährlich?",a="Ja, das Durchqueren dieser verschneiten Hügel ist erheblich gefährlicher, als auf den patrouillierten Wegen zu bleiben. Die Höhen werden von wilden, räuberischen Tieren bevölkert und bieten keine organisierten Zwergenpatrouillen oder Schutz. Obwohl sie eine direkte Abkürzung zwischen dem Coldridgetal und dem östlichen Dun Morogh bieten, wagen sich nur wenige Reisende ohne eine bereite Waffe und ein wachsames Auge abseits der ausgetretenen Pfade.",al={"sind die tundrid-hügel gefährlich","gefahr tundrid-hügel","ist es sicher in den tundrid-hügeln"}}},fp="13,232,24.401.0,36.205.0,50.237.0,47.126.0"}
P.entries["subzone:twilight-base-camp"] = {n="Basislager der Twilight",s="Das Basislager der Twilight ist ein befestigter Außenposten des Schattenhammerkults in den kargen Weiten von Silithus. Es dient als aktiver Ritualort, an dem Kultisten zusammenkommen, um mit Elementarkräften zu kommunizieren und ihre apokalyptischen Pläne voranzutreiben. Das Lager zeichnet sich durch seltsame Windsteine und schwer bewaffnete Kulteiferer aus.",h="Das Basislager der Twilight ist ein befestigter Außenposten des Schattenhammerkults in den kargen Weiten von...",kw={"silithus","twilight avenger","basislager der twilight","twilight geolord","twilight keeper havunth","twilight lord everun","schattenhammer","windsteine"},ang={["class:Paladin"]="Die finsteren, apokalyptischen Rituale der Kultisten stellen eine direkte Bedrohung für den Frieden dar und verlangen nach dem rechtschaffenen Urteil des Heiligen Lichts.",["class:Shaman"]="Die unverhohlene Pervertierung und Unterjochung von Elementargeistern an den Windsteinen des Lagers ist ein Affront gegen jeden Schamanen, der sich der Wahrung der spirituellen Harmonie verschrieben hat."},sec={{t="Eine Bastion des Verderbens",b="Inmitten der trostlosen Wüstensande von Silithus gelegen, ist das Basislager der Twilight eine von mehreren Enklaven, die der Schattenhammerkult errichtet hat. Der Außenposten wimmelt von Eiferern, Geomanten und Steinrufern, die sich der Beschwörung verheerender Elementarkräfte verschrieben haben. Umgeben von schartigen Ritualsteinen fungiert das Lager als Aufmarschgebiet, in dem Anführer wie Twilight Keeper Havunth und Twilight Lord Everun die Bemühungen leiten, Azeroths Ende zu beschleunigen – in offenem Trotz gegen die Streitkräfte von Burg Cenarius, die versuchen, das Gleichgewicht in der Region wiederherzustellen."},{t="Die Windsteine",b="Über den gesamten Außenposten verstreut stehen geheimnisvolle Monumente, die als Windsteine bekannt sind und in ihrer Macht von geringeren Kanälen bis hin zu größeren Monolithen reichen. Durch kryptische Beschwörungen und kultische Insignien nutzt der Schattenhammer diese Fokuspunkte, um chaotische Elementargeister direkt in das Reich der Sterblichen zu ziehen. Die Störung dieser Rituale hat für Reisende und Kundschafter, die eine Ausbreitung des Kulteinflusses über Kalimdor verhindern wollen, höchste Priorität."}},faq={{q="Was ist das Basislager der Twilight?",a="Es ist ein bewaffneter Außenposten, der vom apokalyptischen Schattenhammerkult in den Wüsten von Silithus errichtet wurde und der Durchführung dunkler Rituale sowie der Beschwörung mächtiger Elementarwesen dient.",al={"twilight lager silithus","was ist das basislager der twilight","silithus kultistenlager"}},{q="Wer kontrolliert dieses Lager?",a="Der Außenposten wird von Eiferern des Schattenhammers unter der Führung von Aufsehern wie Twilight Keeper Havunth und dem seltenen Anführer Twilight Lord Everun bemannt.",al={"wer leitet das basislager der twilight","basislager der twilight anführer","wer hat das kommando"}},{q="Was sind die seltsamen Steine im Lager?",a="Bei diesen Konstrukten handelt es sich um Windsteine – mystische Fokussierungskanäle unterschiedlicher Größe, mit denen die Kultisten Dimensionsbarrieren durchbrechen und Elementarwesen an ihren Dienst binden.",al={"windsteine","geringerer windstein","großer windstein silithus"}},{q="Warum ist der Schattenhammer in Silithus?",a="Der Kult wird von den uralten, chaotischen Energien angezogen, die unter dem Sand von Silithus lauern, und versucht, dunkle Mächte zu erwecken sowie Elementare zu beschwören, um den Untergang der Welt herbeizuführen.",al={"warum schattenhammer silithus","twilight kult silithus ziel"}}},fp="18,330,17.529.0,15.444.0,31.173.0,23.164.0,40.165.0,42.188.0"}
P.entries["subzone:twilight-grove"] = {n="Der Zwielichtshain",s="Verborgen im Zentrum des Dämmerwalds ist der Zwielichtshain eine atemberaubende Enklave üppiger Flora aus Kalimdor, die einen Kontrast zum düsteren, verheerten Wald ringsum bildet. Unter seinem riesigen großen Baum und der alten Architektur der Nachtelfen befinden sich ein Mondbrunnen und ein massives smaragdgrünes Portal, das direkt mit dem Smaragdgrünen Traum verbunden ist.",h="Verborgen im Zentrum des Dämmerwalds ist der Zwielichtshain eine atemberaubende Enklave üppiger Flora aus...",kw={"dämmerwald","smaragdgrüner traum","großer baum","grüner drachenschwarm","mondbrunnen","portal","der zwielichtshain"},ang={["class:Druid"]="Für Druiden, die die Östlichen Königreiche erkunden, ist der Hain eine seltene Oase der Heimat, die einen aktiven Mondbrunnen und eine direkte Verbindung zu den uralten Traumwegen beherbergt.",["race:NightElf"]="Einen abgelegenen Mondbrunnen und traditionelle Pavillons so weit entfernt von Kalimdor zu finden, ist eine ergreifende Erinnerung an die uralte Pflicht Eures Volkes, die Wunden von Azeroth zu heilen."},sec={{t="Ein grünes Heiligtum",b="Versteckt hinter steilen Kraterkämmen im Herzen des Dämmerwalds wirkt der Zwielichtshain für die Östlichen Königreiche völlig fremdartig. Antike Nachtelfenpavillons, leuchtend grüne Wiesen und ein friedlicher Mondbrunnen umrahmen einen unbenannten großen Baum, der das düstere Blätterdach überragt. Der Baum fungiert als Kanal der Natur, der die rohe Lebenskraft des Smaragdgrünen Traums in die Welt der Wachsenden filtert und es diesem Krater ermöglicht, selbst unter der ewigen Finsternis des Dämmerwalds zu gedeihen."},{t="Das Smaragdgrüne Portal",b="Am Fuß des großen Baums ragt ein massives Steinportal auf, eines von vier bekannten Toren in ganz Azeroth, das das physische Reich direkt mit dem Smaragdgrünen Traum verbindet. Obwohl es traditionell vom grünen Drachenschwarm unter Ysera bewacht wird, besagen dunkle Gerüchte, dass bösartige Mächte begonnen haben, das friedliche Reich dahinter zu verzerren. Das Portal bleibt vorerst weitgehend stumm, doch sein smaragdgrünes Leuchten dient als düstere Erinnerung daran, dass kosmische Verderbnis aus Pfaden, die weit tiefer liegen als die Geißel oder die örtlichen Worgen, in den Dämmerwald gelangen kann."}},faq={{q="Warum gibt es Nachtelfen-Architektur im Dämmerwald?",a="Die Pavillons und der Mondbrunnen sind nachtelfischen Ursprungs und wurden um den großen Baum des Hains und sein Portal zum Smaragdgrünen Traum errichtet. Wann und wie sie so weit entfernt von Kalimdor entstanden sind, ist nicht allgemein bekannt.",al={"elfenruinen dämmerwald","warum nachtelfengebäude hier","mondbrunnen im dämmerwald"}},{q="Was ist das riesige leuchtend grüne Portal?",a="Es ist ein Portal eines Großen Baums, das direkt in den Smaragdgrünen Traum führt, den urzeitlichen Bauplan von Azeroth, der vom grünen Drachenschwarm überwacht wird. Drei ähnliche Portale existieren im Eschental, in Feralas und im Hinterland.",al={"grünes portal dämmerwald","portal zum smaragdgrünen traum dämmerwald","steinbogen im zwielichtshain"}},{q="Wer bewacht heute den Hain?",a="Historisch gesehen bewachten Offiziere des grünen Drachenschwarms von Ysera dieses Heiligtum. Obwohl es für durchreisende Wanderer oft leer erscheint, drohen zunehmende Störungen im Smaragdgrünen Traum, verderbte Wächter durch das Portal in die Welt der Sterblichen zu bringen.",al={"wer bewacht den zwielichtshain","grüne drachen zwielichtshain"}},{q="Warum wirkt der Zwielichtshain nicht so tot wie der Rest des Dämmerwalds?",a="Der große Baum fungiert als Kanal zum Smaragdgrünen Traum und strahlt reine, ungezähmte Lebensenergie aus. Dieser stetige Zustrom natürlicher Vitalität schützt das innere Becken vor dem übernatürlichen Fluch und der Verderbnis, die die umliegenden Wälder ersticken.",al={"warum ist der zwielichtshain grün","warum belebt im dämmerwald"}}},fx={a63f3ab3={q="Was ist der Zwielichtshain?",a="Der Zwielichtshain ist ein abgelegenes, üppiges Becken, versteckt im Zentrum des Dämmerwalds. Er ist um einen unbenannten Großen Baum, einen friedlichen Mondbrunnen und elfische Architektur angeordnet und verbindet Azeroth durch ein massives, wirbelndes Portal direkt mit dem Smaragdgrünen Traum. Im Gegensatz zum Rest des dunklen und heimgesuchten Waldes ist die Natur hier noch lebendig und pulsierend.",al={"was ist der zwielichtshain","zwielichtshain dämmerwald","zwielichtshain lore"}},["4ad09d10"]={q="Was ist im Zwielichtshain passiert?",a="Es ist nur wenig über die Ursprünge des Hains aufgezeichnet. Sein großer Baum dient als Kanal zum Smaragdgrünen Traum, und die Pavillons der Nachtelfen sowie der Mondbrunnen in der Umgebung zeigen, dass einst Kaldorei ihn pflegten. Heute bedroht die wachsende Verderbnis innerhalb des Traums die grünen Drachen, die das Portal bewachen.",al={"zwielichtshain geschichte","geschichte des zwielichtshains","wie wurde der zwielichtshain erschaffen"}},["69043853"]={q="Ist der Zwielichtshain gefährlich?",a="Obwohl der Hain im Vergleich zu den untoten Schrecken, die durch den Dämmerwald streifen, friedlich erscheint, führt sein Portal in den Smaragdgrünen Traum, der unter einer wachsenden Alptraumverderbnis leidet. Die grünen Drachen, die mit der Bewachung dieser Äste beauftragt sind, riskieren, dem Wahnsinn zu verfallen, was die friedliche Senke zu einem Ort immenser, schlummernder Gefahr macht.",al={"ist der zwielichtshain sicher","gefahr zwielichtshain","gefahren des zwielichtshains"}}},fp="14,305,19.445.0,19.517.0,48.198.0,39.210.0,33.253.0,67.227.0"}
P.entries["subzone:twilight-outpost"] = {n="Twilight-Außenposten",s="Der Twilight-Außenposten ist ein befestigtes Lager des Schattenhammerkults im südwestlichen Sand von Silithus. Er liegt direkt nordwestlich des uralten Skarabäuswalls und dient als Aufmarschgebiet, in dem Kultisten finstere Rituale abhalten, um mit elementaren Schrecken zu kommunizieren und sie zu beschwören.",h="Der Twilight-Außenposten ist ein befestigtes Lager des Schattenhammerkults im südwestlichen Sand von Silithus.",kw={"bronzebeards lager","der skarabäuswall","silithus","twilight keeper exeter","twilight lord everun","twilight-außenposten","schattenhammer","windstein"},ang={["class:Paladin"]="Der nihilistische Fanatismus des Schattenhammers stellt einen Affront gegen das Licht dar und verlangt nach heiligem Zorn, um ihre finsteren Beschwörungen aus der Wüste zu tilgen.",["class:Shaman"]="Der Schattenhammer verdirbt und befehligt Elementargeister über seine Wind Stones und widersetzt sich damit dem natürlichen Gleichgewicht der Elemente, dessen Bewahrung Schamanen anstreben."},sec={{t="Eine Bastion des Flüsterns",b="Verborgen in den südwestlichen Weiten von Silithus dient der Twilight-Außenposten als eine von mehreren bedeutenden Hochburgen der Kultisten, die die Wüstenöde übersäen. Im Schatten des kolossalen Skarabäuswalls und westlich von Bronzebeards Lager gelegen, wimmelt es im Außenposten von fanatischen Twilight Avengers, Geolords und Stonecallers. Unter dem Befehl von Anführern wie Twilight Keeper Exeter und dem seltenen Twilight Lord Everun schuften diese Eiferer unermüdlich im Dienst ihrer den Verstand raubenden, apokalyptischen Herren."},{t="Die Windsteine",b="Über das gesamte Lager verstreut finden sich geheimnisvolle Wind Stones, deren Größe von geringeren bis hin zu größeren Leitern reicht. Durch den Einsatz verzauberter Kultistengewänder und finsterer Beschwörungsformeln nutzt der Kult diese Monolithen, um die Elementarebenen aufzureißen und Abyssische Kommandanten sowie Elementarlords hervorzuzerren. Für Abenteurer, die mutig genug sind, ihre Reihen zu infiltrieren, bleibt das Stören dieser Beschwörungen eines der wichtigsten Mittel, um gegen den Einfluss des Kults in der Wüste zurückzuschlagen."}},faq={{q="Wo befindet sich der Twilight-Außenposten?",a="Der Twilight-Außenposten liegt in der äußersten südwestlichen Ecke von Silithus. Er befindet sich nordwestlich des uralten Skarabäuswalls und direkt westlich des Zwergenstützpunkts Bronzebeards Lager.",al={"twilight-außenposten standort","wo ist twilight-außenposten","twilight-außenposten finden"}},{q="Wer besetzt den Twilight-Außenposten?",a="Das Lager wird vom Schattenhammerkult besetzt. In seinen Reihen finden sich verschiedene sterbliche Eiferer wie Twilight Avengers, Geolords, Stonecallers und Twilight Masters, die von Anführern wie Twilight Keeper Exeter und Twilight Lord Everun beaufsichtigt werden.",al={"wer ist im twilight-außenposten","twilight-außenposten gegner","kultisten in silithus"}},{q="Was sind die im Lager gefundenen Wind Stones?",a="Die Wind Stones – von geringeren bis hin zu größeren – sind mystische Foki, die der Kult verwendet, um Breschen in die Elementarebenen zu schlagen. Kultisten leiten dunkle Energien durch diese Steine, um mächtige Elementarlords und Abyssische Kommandanten nach Azeroth zu beschwören.",al={"was sind windsteine","großer windstein silithus","geringerer windstein silithus"}},{q="Warum versammelt sich der Schattenhammer nahe dem Skarabäuswall?",a="Der Kult wird von den mächtigen und uralten dunklen Energien angezogen, die unter Silithus schlummern. Die Errichtung von Lagern nahe dem Skarabäuswall ermöglicht es ihnen, Elementarbeschwörungen durchzuführen und die chaotischen Mächte nutzbar zu machen, die sich hinter den versiegelten Toren regen.",al={"warum sind kultisten in silithus","schattenhammer zweck silithus"}}},fp="16,286,21.497.0,15.480.0,38.178.0,34.248.0,43.239.0,59.241.0"}
P.entries["subzone:twilight-post"] = {n="Twilight-Posten",s="Der Twilight-Posten ist ein befestigtes Lager, das vom Schattenhammerklan im nordwestlichen Silithus errichtet wurde. Weit westlich von Burg Cenarius und nordwestlich des Basislagers der Twilight gelegen, dient er als entscheidender Ort für die elementaren Beschwörungsrituale der Kultisten. Abenteurer, die sich hierher wagen, sehen sich fanatischen Kultisten und den Windsteinen gegenüber, mit denen diese jenseitige Mächte kontaktieren.",h="Der Twilight-Posten ist ein befestigtes Lager, das vom Schattenhammerklan im nordwestlichen Silithus...",kw={"geolord","silithus","stonecaller","twilight keeper mayna","twilight lord everun","twilight-posten","schattenhammerklan","windstein"},ang={["class:Druid"]="Der Zirkel des Cenarius beobachtet das Aufkommen der Außenposten des Kults genau, da die finsteren Elementarrituale der Kultisten das zerbrechliche, gezeichnete Gleichgewicht von Silithus weiter zu zerstören drohen.",["class:Shaman"]="Der Schattenhammerklan pervertiert die heilige Zwiesprache der Elemente, indem er Geister gewaltsam über die Windsteine beschwört und bindet, die an Außenposten wie diesem zu finden sind."},sec={{t="Eine Bastion des elementaren Fanatismus",b="Verborgen im Wüstensand des nordwestlichen Silithus dient der Twilight-Posten als Außenposten des Schattenhammerklans. Das Lager wird von schwer bewaffneten Verteidigern und Ritualisten bevölkert, darunter Twilight Avengers, Geolords und Stonecallers unter der Führung von Twilight Keeper Mayna und dem seltenen Fanatiker Twilight Lord Everun. Wie andere in den Ödlanden verstreute Lager dreht sich auch dieser Posten um uralte Beschwörungsleitungen – Geringe, gewöhnliche und Größere Windsteine. Durch finstere Riten und elementare Zwiesprache nutzen die Kultisten diese Steine, um elementare Schrecken aus jenseitigen Reichen anzurufen und zu binden, wodurch sie den zerbrechlichen Frieden bedrohen, den der Zirkel des Cenarius in der Region aufrechterhält."}},faq={{q="Wo befindet sich der Twilight-Posten?",a="Der Twilight-Posten befindet sich im äußersten Nordwesten von Silithus, weit westlich von Burg Cenarius und nordwestlich des größeren Basislagers der Twilight.",al={"standort twilight-posten","wo ist der twilight-posten","twilight-posten silithus karte"}},{q="Wer besetzt den Twilight-Posten?",a="Der Posten wird vom Schattenhammerklan gehalten. Zu den bemerkenswerten Persönlichkeiten, die hier stationiert sind, gehören Twilight Keeper Mayna und Twilight Lord Everun, beschützt von den Rängen der Twilight Avengers, Geolords und Stonecallers.",al={"wer ist am twilight-posten","twilight-posten mobs","gegner am twilight-posten"}},{q="Was sind die Windsteine im Lager?",a="Die Windsteine – von Geringen Windsteinen über gewöhnliche bis hin zu Größeren Windsteinen – sind arkane Leitungen, die vom Schattenhammerklan genutzt werden, um Elementarkreaturen zu beschwören und an ihren Dienst zu binden.",al={"was sind windsteine","windsteine silithus","geringer windstein twilight-posten"}},{q="Warum operiert der Schattenhammerklan in Silithus?",a="Der Schattenhammerklan ist in die Wüsteneinöde von Silithus geströmt, um uralte, finstere Mächte zu erwecken und mit ihnen zu kommunizieren, die unter dem Sand schlummern, und um seine Ränge durch Elementarbeschwörungen zu verstärken.",al={"warum sind kultisten in silithus","schattenhammerklan silithus ziel"}}},fp="13,369,31.701.0,31.167.0,31.203.0,43.193.0,51.197.0"}
P.entries["subzone:twilight-s-run"] = {n="Kavernen des Schattenhammers",s="Die Kavernen des Schattenhammers sind eine abgelegene unterirdische Höhle, die in die nördlichen Berge von Silithus unterhalb von Staghelms Stätte gegraben wurde. Besetzt vom fanatischen Schattenhammer-Kult dient sie als abgeschiedene Zuflucht und ritueller Rückzugsort abseits der rauen Wüstenwinde.",h="Die Kavernen des Schattenhammers sind eine abgelegene unterirdische Höhle, die in die nördlichen Berge von...",kw={"silithus","staghelms stätte","schattenhammer kult","schattenhammer","kavernen des schattenhammers","vyral the vile"},ang={["class:Paladin"]="Die abgeschiedenen Tiefen der Kavernen des Schattenhammers beherbergen eifernde Nihilisten, deren Unterwerfung unter dunkle Mächte einen Frevel an den heiligen Lehren des Lichts darstellt."},sec={{t="Ein unterirdischer Rückzugsort",b="Verborgen in der nördlichen Felswand unterhalb von Staghelms Stätte bieten die Kavernen des Schattenhammers den Schattenhammer-Kultisten eine natürliche Bastion inmitten der stürmischen Gefahren von Silithus. Anstatt den Sandstürmen zu trotzen oder sich direkt mit den umherstreifenden Silithidenschwärmen auf den Dünen der Oberfläche anzulegen, ziehen sich die Kultisten in diese schattigen Tunnel zurück, um mit dunklen Mächten zu kommunizieren, rituelle Materialien zu bewachen und ihre Streitkräfte zu sammeln. Unter der Führung von Aufsehern wie Vyral the Vile halten die Kultmitglieder in der Höhle eine wachsame, feindselige Präsenz aufrecht, bereit, jeden neugierigen Reisenden oder Späher niederzustrecken, der ihrem unterirdischen Lager zu nahe kommt."}},faq={{q="Wo befinden sich die Kavernen des Schattenhammers?",a="Die Kavernen des Schattenhammers sind eine Höhle in den nördlichen Bergen von Silithus, direkt am felsigen Fuß unterhalb von Staghelms Stätte.",al={"wo liegen die kavernen der twilight","kavernen der twilight aufenthaltsort","kavernen der twilight finden"}},{q="Wer hält die Kavernen des Schattenhammers besetzt?",a="Die Höhle wird vollständig von Mitgliedern des Schattenhammer-Kults kontrolliert, darunter Gestalten wie Vyral the Vile, Twilight Overlords und Twilight Flamereavers.",al={"wer ist in den kavernen der twilight","kavernen der twilight mobs","wer lebt in den kavernen der twilight"}},{q="Was tut der Kult im Inneren der Höhle?",a="Der Kult nutzt die Höhle als geschützten Rückzugsort und vorgeschobenen Stützpunkt in Silithus, um den Elementen der Wüste zu entgehen und gleichzeitig sein apokalyptisches Werk voranzutreiben.",al={"schattenhammer zweck silithus höhle","warum sind kultisten in den kavernen der twilight"}}},fp="14,256,22.649.0,32.120.0,28.159.0,41.158.0"}
P.entries["subzone:twilight-shore-darkshore"] = {n="Zwielichtufer (Dunkelküste)",s="Das Zwielichtufer ist ein zerklüfteter Küstenabschnitt im Süden der Dunkelküste, der sich vom langen Strand nach Süden bis an die Grenze von Eschental erstreckt. Seine düsteren, nebelverhangenen Strände werden von aufragenden Klippen, vorgelagerten Inselchen und einer tückischen Brandung unterbrochen. Das Gebiet wird von aggressiven Murloc-Stämmen und gefräßigen Wasserraubtieren wie Threshadons heimgesucht.",h="Das Zwielichtufer ist ein zerklüfteter Küstenabschnitt im Süden der Dunkelküste, der sich vom langen Strand...",kw={"eschental","küste","dunkelküste","der lange strand","murlocs","threshadons","zwielichtufer"},ang={["race:NightElf"]="Das Zwielichtufer markiert die einsame, nebelverhangene Schwelle zwischen den heimgesuchten Ruinen der Dunkelküste und den heiligen uralten Wäldern von Eschental."},sec={{t="Eine tückische Küstenlinie",b="Südlich des langen Strands an den Ruinen von Ameth'Aran vorbei in Richtung Eschental gelegen, gehört das Zwielichtufer zu den zerklüftetsten und unwirtlichsten Teilen der Küste der Dunkelküste. Grauer Sand weicht scharfen, von Wellen gepeitschten Klippen und verstreuten Felseninseln. Die Gewässer hier sind berüchtigt feindselig; wer vor der Küste schwimmt, zieht Angriffe territorialer Threshadons und Meereskriecher auf sich, während die Strände selbst von florierenden Lagern aggressiver Murlocs beherrscht werden."}},faq={{q="Wo befindet sich das Zwielichtufer?",a="Es umfasst den südlichsten Küstenstreifen der Dunkelküste, der südlich des langen Strands (ungefähr westlich der uralten Ruinen von Ameth'Aran) beginnt und sich nach Süden fortsetzt, bis er die felsigen Grenzen von Eschental erreicht.",al={"zwielichtufer lage","wo liegt das zwielichtufer","zwielichtufer karte"}},{q="Welche Bedrohungen lauern am Zwielichtufer?",a="Die Küste ist dicht von aggressiven Murloc-Stämmen besiedelt, während die umliegende kalte Brandung die Heimat territorialer Threshadons, Lauerer und Riesenkrabben ist, die unvorsichtigen Reisenden nachstellen.",al={"zwielichtufer mobs","gefahren am zwielichtufer","was gibt es am zwielichtufer"}},{q="Warum ist das Terrain hier so zerklüftet?",a="Im Gegensatz zu den flacheren, weitläufigen Stränden weiter nördlich ist das Zwielichtufer von schroffen Meeresklippen, felsigen Untiefen und kleinen vorgelagerten Inseln durchsetzt, die durch das unerbittliche Tosen des Veiled Sea geformt wurden.",al={"warum gibt es dort klippen","zwielichtufer geografie"}}},fx={["4cda5a2c"]={q="Was ist das Zwielichtufer?",a="Das Zwielichtufer ist ein rauer Küstenabschnitt entlang der südlichen Dunkelküste, der vom Rand des langen Strandes bis hin zur Grenze des Eschentals verläuft. Im Gegensatz zu den flacheren sandigen Abschnitten weiter nördlich ist diese Küste zerklüftet und unerbittlich, gekennzeichnet durch herausragende Meeresklippen, felsige Inselchen und neblige graue Strände, die von kaltem Ozeanwasser gepeitscht werden.",al={"zwielichtufer lore","was ist das zwielichtufer","über das zwielichtufer"}},["2a509b88"]={q="Ist das Zwielichtufer gefährlich?",a="Ja, es ist einer der gefährlichsten Küstenabschnitte in der Region. Schwärme aggressiver Murlocs beanspruchen die felsigen Ufer und Felsvorsprünge für sich, während die Brandung von hungrigen Dreschadon durchstreift wird, die nur darauf warten, nach Schwimmern zu schnappen. Wenn Ihr in der Nähe der aufgewühlten Brandung reist oder entlang der isolierten Klippen klettert, seid Ihr anfällig für Hinterhalte von Land und Meer.",al={"ist das zwielichtufer sicher","wie gefährlich ist das zwielichtufer","gefahren am zwielichtufer"}}},fp="26,345,23.464.0,36.214.0,51.187.0,34.200.0"}
P.entries["subzone:twilight-vale"] = {n="Das Zwielichttal",s="Das Zwielichttal umfasst die dichten, schattigen südlichen Wälder von Dunkelküste, die sich bis zur Grenze von Eschental erstrecken. In seiner Düsternis streifen verderbte Furbolgs, tolle Bären und bösartige Nachtsäbler durch das Unterholz, was das Verlassen der Straßen lebensgefährlich macht. Es dient als düstere Schwelle zwischen der verdorbenen Küste von Dunkelküste und den heiligen Baumkronen im Süden.",h="Das Zwielichttal umfasst die dichten, schattigen südlichen Wälder von Dunkelküste, die sich bis zur Grenze...",kw={"ameth'aran","eschental","dunkelküste","furbolgs","nachtsäbler","tolle bären","das zwielichttal"},ang={["class:Druid"]="Druiden, die zwischen Dunkelküste und Eschental reisen, werden aus erster Hand Zeugen der Krankheit, die die Kreaturen des Tals befällt, was die dringende Notwendigkeit unterstreicht, das Land zu reinigen.",["race:NightElf"]="Der Verfall der südlichen Wälder lastet schwer auf den Nachtelfen, die die Verderbnis der einheimischen Bestien und den Fall ihrer Furbolgnachbarn so nah an der Schwelle von Eschental betrauern."},sec={{t="Eine gefährliche Schwelle",b="Das Zwielichttal erstreckt sich vom Süden der uralten Ruinen von Ameth'Aran bis hin zur Grenze von Eschental und hüllt die südlichen Gefilde von Dunkelküste in ein ewiges Zwielicht. Die um sich greifende Verderbnis, die das nördliche Kalimdor heimsucht, hat sich tief in die hiesige Tierwelt hineingefressen. Tolle Bären streifen an der Seite wilder Nachtsäbler umher, und feindselige Furbolgstämme lauern im dunklen Wald. Schildwachen wie Reisende raten gleichermaßen dazu, strikt auf der Hauptstraße zu bleiben, da schon wenige Schritte abseits der Pfade unter den Bäumen zu schnellen und tödlichen Hinterhalten führen können."}},faq={{q="Wo liegt das Zwielichttal?",a="Das Zwielichttal bildet den südlichen Teil von Dunkelküste. Es beginnt südlich der Hochgeborenenruinen von Ameth'Aran und reicht bis zum Grenzpass, der nach Eschental führt.",al={"zwielichttal lage","wo ist das zwielichttal","zwielichttal karte"}},{q="Welche Bedrohungen durchstreifen diesen Wald?",a="Das Tal wird von verfluchter Tierwelt und feindseligen Stämmen heimgesucht. Reisende treffen auf tolle Bären, aggressive Nachtsäbler und verderbte Furbolgs, die jeden angreifen, der in ihr Territorium eindringt.",al={"zwielichttal monster","was gibt es im zwielichttal","gefahr zwielichttal"}},{q="Ist es sicher, durch das Tal zu reisen?",a="Keine Wildnis in Dunkelküste ist vollkommen sicher, doch wer entschieden auf dem befestigten Feldweg bleibt, reist weitaus sicherer als beim Durchqueren des Unterholzes. Das Verlassen der ausgetretenen Pfade führt Euch geradewegs in den Weg wilder Bestien.",al={"ist das zwielichttal sicher","sicherer weg von dunkelküste nach eschental"}},{q="Warum ist die Tierwelt im Tal verderbt?",a="Dunkelküste hat seit dem Dritten Krieg und durch die im nördlichen Kalimdor verbliebene zerstörerische Magie schwer gelitten. Verdorbenes Wasser und dunkle magische Rückstände haben die heimische Tierwelt in den Wahnsinn getrieben und einst friedliche Furbolgs gewalttätig werden lassen.",al={"warum sind bären in dunkelküste tollwütig","furbolg-verderbnis zwielichttal"}}},fp="13,357,20.517.0,35.178.0,32.199.0,38.220.0,42.220.0"}
P.entries["subzone:twin-colossals"] = {n="Die Zwillingskolosse",s="Die Zwillingskolosse sind ein Paar aufragender, steil abfallender Tafelberge, die den nordwestlichen Horizont von Feralas beherrschen. Sie ragen hoch über das Blätterdach hinaus, und der schmale Durchgang zwischen ihren steilen Klippen bildet die wichtigste Überlandroute, die Feralas mit den trockenen Einöden von Desolace im Norden verbindet.",h="Die Zwillingskolosse sind ein Paar aufragender, steil abfallender Tafelberge, die den nordwestlichen Horizont...",kw={"desolace","diamond head","feralas","kalin windflight","makrura","marli wishrunner","die zwillingskolosse","zwillingskolosse"},ang={["race:NightElf"]="Die schwindelerregenden Höhen und die nahegelegenen verderbten Mondbrunnen des Teilgebiets dienen als eindringliche Mahnung an die uralte Geschichte von Feralas und die verweilenden Schatten, die sich in die Wildnis schleichen."},sec={{t="Säulen des Regenwaldes",b="Die Zwillingskolosse überragen die westlichen Gefilde von Feralas und stellen die höchsten Landformationen der Region dar. Ihre senkrechten Felswände zeichnen eine markante Silhouette am Himmel ab und dienen Reisenden, die sich von Desolace nach Süden wagen, als unverkennbare Wegmarken. Während die unteren Hänge in den dichten Dschungel und die Ländereien übergehen, die sich zur vergessenen Küste hin erstrecken, sind die Gipfel isolierte Plateaus weit über dem Waldboden."},{t="Den Gipfel erreichen",b="Das Erklimmen der senkrechten Klippen zu Fuß ist unmöglich, doch die Gipfel sind keineswegs völlig verlassen. Eine unerschrockene Nachtelfe namens Marli Wishrunner hilft Reisenden, die eine Passage zum östlichen Gipfel suchen. Diejenigen, die hinaufsteigen, finden einen friedlichen Teich oben auf dem steinernen Tafelberg vor – der allerdings von einem ungewöhnlich großen Makrura namens Diamond Head bewohnt wird. Um Abenteurern bei der Rückkehr zur Erde zu helfen, bietet Kalin Windflight robuste Fallschirme an, um wieder in das Blätterdach des Dschungels hinabzuschweben."}},faq={{q="Wo befinden sich die Zwillingskolosse?",a="Die Zwillingskolosse stehen im Nordwesten von Feralas und rahmen die Hauptstraße ein, die nach Norden nach Desolace führt. Das umliegende Teilgebiet erstreckt sich westlich in Richtung Die vergessene Küste.",al={"zwillingskolosse ort","wo sind die zwillingskolosse","zwillingskolosse karte"}},{q="Wie gelangt man auf die Zwillingskolosse?",a="Die steilen Felsklippen können nicht auf normalem Wege erklommen werden. Reisende verlassen sich auf die Nachtelfe Marli Wishrunner, die magische Beförderung zum östlichen Gipfel anbietet.",al={"zwillingskolosse erklimmen","auf zwillingskolosse gelangen","nach ganz oben quest"}},{q="Wer lebt auf dem östlichen Gipfel?",a="Auf der Spitze des östlichen Gipfels findet Ihr Kalin Windflight, der Fallschirme für einen sicheren Abstieg verkauft, sowie einen tiefen Teich, der von einem gewaltigen Makrura namens Diamond Head bewohnt wird.",al={"nsc auf zwillingskolossen","wer ist auf dem tafelberg","diamond head feralas"}},{q="Wie kommt man sicher vom Gipfel herunter?",a="Kalin Windflight verkauft auf dem östlichen Gipfel spezielle Kolossale Fallschirme, mit denen Reisende von den Klippen springen und unversehrt in den Dschungel von Feralas hinabgleiten können.",al={"zwillingskolosse verlassen","von zwillingskolossen springen","kolossaler fallschirm"}}},fp="14,286,25.426.0,20.464.0,37.172.0,47.153.0,32.181.0,40.173.0"}
P.entries["subzone:tyr-s-hand"] = {n="Tyrs Hand",s="Tyrs Hand ist eine schwer befestigte menschliche Festung in den südöstlichen Hügeln der Östlichen Pestländer. Lange als alte heilige Stätte der Kirche des Heiligen Lichts verehrt, dient die Stadt heute als wichtigste regionale Bastion und Versorgungszentrum für den eifernden Scharlachroten Kreuzzug.",h="Tyrs Hand ist eine schwer befestigte menschliche Festung in den südöstlichen Hügeln der Östlichen Pestländer.",kw={"abbendis","demetria","eastweald","heiliges licht","die scharlachrote basilika","scharlachroter kreuzzug","tyrs hand","valdelmar"},ang={["class:Paladin"]="Für heilige Krieger dient es als ernste Warnung, wie Glaube aussieht, wenn er nicht durch Mitgefühl gemildert wird, wenn sie sehen, wie diese alte Wiege der Silbernen Hand in eine Bastion wahnsinnigen, unnachgiebigen scharlachroten Eifers verdreht wurde.",["class:Priest"]="Die Abtei und die Scharlachrote Basilika stehen als prächtige architektonische Wunderwerke der frühen Kirche des Heiligen Lichts, auch wenn der Klerus darin pastorale Heilung gegen blinden Kreuzzug eingetauscht hat."},sec={{t="Eine Stadt der Kirchen",b="Tyrs Hand liegt strategisch günstig in dem, was einst Lordaerons grünes Eastweald war, und ist eine der ältesten heiligen Stätten der Menschheit. Die Siedlung wurde als 'Stadt der Kirchen' bekannt, da auf ihrem Gelände Schreine und heilige Bauwerke errichtet wurden. Im Gegensatz zu den vom Befall verrotteten Ruinen, die den Rest der Pestländer bedecken, ist Tyrs Hand hinter massivem Mauerwerk, dicken Wällen und der hoch aufragenden Silhouette der Scharlachroten Basilika bemerkenswert gut erhalten."},{t="Festung des Scharlachroten Kreuzzugs",b="Als die Geißel während des Dritten Kriegs durch Lordaeron fegte, hielt Lord Valdelmar die Stadt durch schiere militärische Wachsamkeit und Glauben standhaft. Nachdem sich die Ritter der Silbernen Hand in rivalisierende Fraktionen aufgespalten hatten, schloss sich Tyrs Hand fest der purpurnen Morgenröte des Scharlachroten Kreuzzugs an. Heute fungiert sie als undurchdringliche Operationsbasis unter der Führung von Hochgeneral Brigitte Abbendis und Valdelmar. Elitekreuzfahrer trainieren in ihrer Abtei, schwer bewachte Kuriere halten die Verbindung zu den scharlachroten Streitkräften in Stratholme aufrecht und die Stadt weist rücksichtslos alle Außenstehenden ab, die sich ihren Toren nähern."}},faq={{q="Warum heißt die Stadt Tyrs Hand?",a="Der Name ist uralt und die überlieferten Aufzeichnungen von Lordaeron sagen wenig darüber aus, wer Tyr war. Die Stadt selbst ist als eine der ältesten und am meisten verehrten heiligen Stätten der Kirche des Heiligen Lichts im alten Eastweald bekannt.",al={"wer ist tyr","bedeutung des namens tyrs hand","ursprung von tyrs hand"}},{q="Warum wurde Tyrs Hand nicht von der Geißel überrannt?",a="Tyrs Hand nimmt einen natürlichen gebirgigen Engpass ein und ist durch beeindruckende Steinbefestigungen, Kasernen und eine Abtei geschützt. Neben der defensiven Geografie unterhält der Scharlachrote Kreuzzug eine elitäre, schwer bewaffnete Garnison, deren kriegerischer Eifer und strahlende heilige Magie unerbittliche Angriffe der Geißel erfolgreich abgewehrt haben.",al={"warum hat tyrs hand überlebt","wie ist tyrs hand nicht untot","wie hält sich tyrs hand"}},{q="Sind Reisende und Abenteurer in Tyrs Hand willkommen?",a="Nein. Der Scharlachrote Kreuzzug ist in xenophobe Paranoia verfallen und betrachtet jeden außerhalb ihrer Reihen als potenziellen Träger der untoten Seuche oder als Geheimagenten der Geißel. Außenstehende sowohl der Allianz als auch der Horde werden bei Sichtkontakt angegriffen.",al={"kann ich tyrs hand besuchen","ist tyrs hand freundlich gesinnt","sind scharlachrote kreuzzügler hier freundlich"}},{q="Welche Rolle spielte die Stadt während des Zweiten Kriegs?",a="Während des Zweiten Kriegs schürten Provokateure aus Alterac heimlich einen Bauernaufstand in Tyrs Hand, um einen orkischen Bergbauaußenposten in der Nähe zu tarnen. Nachdem die Allianz und die Silberne Hand den Aufstand niedergeschlagen hatten, bombardierten Oger-Magier der Horde die Stadt schwer und plünderten die benachbarte Bucht, um die Versorgungswege nach Quel'Thalas abzuschneiden.",al={"tyrs hand zweiter krieg","bauernaufstand tyrs hand"}}},fp="10,284,18.444.0,31.592.0,34.209.0,42.334.0,52.244.0,50.301.0"}
P.entries["subzone:uldum"] = {n="Uldum",s="Uldum ist eine massive, versiegelte Forschungsanlage der Titanen, die hinter kolossalen Steintoren in den südlichsten Klippen von Tanaris verborgen liegt. Lange hinter uralten Schutzzaubern und vergessener Maschinerie verborgen, bleibt es für moderne Entdecker unzugänglich.",h="Uldum ist eine massive, versiegelte Forschungsanlage der Titanen, die hinter kolossalen Steintoren in den...",kw={"forscherliga","tore von uldum","platten von uldum","tanaris","titanen","uldum"},ang={["faction:Alliance"]="Gelehrte der Allianz hoffen, jeder rivalisierenden Macht zuvorzukommen, um die Titanengeheimnisse zu bergen, die in den südlichen Bergen verborgen liegen.",["race:Dwarf"]="Für Zwerge, die durch die Forscherliga ihr Titanenerbe verfolgen, stellen die kolossalen Tore von Uldum eines der größten ungelösten Rätsel auf dem Kontinent Kalimdor dar."},sec={{t="Die Tore der Schöpfer",b="In die zerklüftete südliche Bergkette eingemeißelt, die an die Wüste von Tanaris grenzt, steht das monumentale Tor nach Uldum stumm und unpassierbar. Erbaut während der Ordnung des alten Kalimdor, diente das Gelände als fortschrittliche Titanenanlage, die mit ihren geheimnisvollen Bemühungen verbunden war, die Biosphäre des Planeten zu formen und zu überwachen. Titanenwächter und Verteidigungskonstrukte bewachten einst den Umfang und hinterließen modernen Sterblichen nur monumentale, in Stein gehauene Bögen und begrabene Geheimnisse, die allen weltlichen Versuchen des Eindringens getrotzt haben."},{t="Die versiegelten Geheimnisse",b="Die unverkennbare Titanen-Handwerkskunst des Ortes weckt die Neugier von zwergischen Gelehrten, doch es wurde kein Mechanismus oder Schlüssel gefunden, der den uralten Komplex öffnen könnte. Legenden besagen, dass wahrer Einblick in die darin verschlossenen Geheimnisse die verlorenen Platten von Uldum erfordert, was die zwergischen Gelehrten dazu verdammt, durch das Schlüsselloch eines Imperiums zu spähen, das sie noch nicht betreten können."}},faq={{q="Könnt Ihr die Tore nach Uldum öffnen?",a="Nein. Die massiven Steintore, die in den Gebirgspass führen, sind vollständig versiegelt und fest gegen jedes Eindringen Sterblicher verschlossen. Es existiert kein Mechanismus oder Schlüssel in der umliegenden Wüste, um sie zu entriegeln.",al={"wie kommt man nach uldum","uldum-tor öffnen","uldum betreten"}},{q="Was befindet sich in Uldum?",a="Alten Aufzeichnungen und der Titanen-Überlieferung zufolge ist Uldum eine riesige Forschungseinrichtung, die von den Titanen errichtet wurde, um die Biosphäre von Azeroth zu untersuchen und zu verbessern. Genaue Details bleiben jedoch hinter den Sicherheitsmaßnahmen der Titanen verborgen.",al={"was ist uldum","zweck von uldum","im inneren von uldum"}},{q="Was sind die Platten von Uldum?",a="Die Platten von Uldum sind uralte Datenscheiben, die von den Titanen erschaffen wurden. Den Überlieferungen der alten Steinbewahrer zufolge kann spezifisches Wissen über die Arbeit und die Einrichtungen in Uldum nur durch diese heiligen Platten erschlossen werden.",al={"platten von uldum","scheiben von uldum","uldum-tafeln"}}},fp="5,236,23.511.0,18.354.0,32.193.0,21.225.0,29.235.0"}
P.entries["subzone:undercity"] = {fx={f1849a51={q="Was ist die Unterstadt?",a="Die Unterstadt ist die unterirdische Hauptstadt der Verlassenen, die sich direkt unter den zertrümmerten Ruinen von Lordaerons Hauptstadt erstreckt. Ursprünglich aus alten königlichen Krypten, Kerkern und Abwasserkanälen bestehend, wurde der riesige Komplex zu einer labyrinthartigen Festung ausgebaut. Heute dient sie als das Herz des Reiches von Königin Sylvanas Windläufer und fungiert als befestigter Zufluchtsort, politisches Zentrum und Forschungsbastion für die Untoten der Horde mit freiem Willen.",al={"was ist die unterstadt","unterstadt übersicht","unterstadt lore"}},["88d828cf"]={q="Was ist in der Unterstadt passiert?",a="Nach dem Fall von Lordaeron begann Prinz Arthas, unter der Hauptstadt eine Festung zu errichten, um der Geißel zu dienen. Als die Macht des Lichkönigs schwächte und Arthas nach Nordend floh, führte Sylvanas Windläufer eine Rebellion befreiter Untoter an. Während des Bürgerkriegs in den Pestländern besiegten ihre Streitkräfte rivalisierende Schreckenslords und Überreste der Allianz, um das unterirdische Netzwerk einzunehmen und es als Bastion der neu gegründeten Verlassenen zu beanspruchen.",al={"geschichte der unterstadt","unterstadt geschichte","was ist hier passiert"}},["9e3a5d6b"]={q="Wer lebt in der Unterstadt?",a="Die Stadt wird hauptsächlich von den Verlassenen bevölkert – Untote, die sich aus dem eisernen Griff des Lichkönigs befreit haben. In ihren Vierteln werdet Ihr auf die Königliche Apothekervereinigung treffen, die tödliche Gebräue herstellt, auf schattenhafte Schurken, dunkle Zauberwirker und Todeswachen, die den Umkreis bewachen. Besucheregesandte und Krieger der Nationen der Orcs, Tauren und Dunkelspeer-Trolle der Horde durchqueren ebenfalls die Korridore, wenn auch selten bequem.",al={"wer lebt in der unterstadt","unterstadt bewohner","unterstadt bevölkerung"}},a78ac513={q="Ist die Unterstadt gefährlich?",a="Sie ist für Außenstehende und unvorsichtige Besucher äußerst gefährlich. Für Eindringlinge der Allianz ist der Tod durch die wachsamen Todeswachen schnell und gewiss. Selbst für geschworene Verbündete der Horde birgt die Stadt Gefahren: riesige offene Schächte, Bottiche mit toxischem alchemistischen Schlamm, brütende Nekromanten und intrigante Apotheker führen Experimente durch, bei denen ein einziger Fehltritt tödlich enden kann.",al={"ist die unterstadt gefährlich","wie gefährlich ist die unterstadt","gefahren der unterstadt"}}}}
P.entries["subzone:undercroft"] = {n="Das Tiefgewölbe",s="Das Tiefgewölbe ist eine uralte Begräbnisgruft, die in den südwestlichen Hügeln der Östlichen Pestländer liegt. Einst ein würdiges Grabmal Lordaerons, wurde es von einer Schar untoter Trolle unter dem Befehl von Zaeldarr the Outcast entweiht. Inmitten der geschändeten Katakomben liegt ein Scheingrab, das vor langer Zeit ausgehoben wurde, um den Tod des verbannten Paladins Tirion Fordring vorzutäuschen.",h="Das Tiefgewölbe ist eine uralte Begräbnisgruft, die in den südwestlichen Hügeln der Östlichen Pestländer...",kw={"gruft","dire troll","östliche pestländer","grab","kapelle des hoffnungsvollen lichts","the outcast","tirion fordring","das tiefgewölbe","zaeldarr"},ang={["class:Paladin"]="Für heilige Krieger bedeutet das Betreten des Tiefgewölbes, sowohl das tragische Scheingrab des verbannten Helden Tirion Fordring als auch die schändliche Entweihung heiliger Grüfte durch Zaeldarrs abscheuliche Brut mitzuerleben.",["race:Troll"]="Trollische Reisende werden Zaeldarr the Outcast und seine untote Sippe als einen düsteren, pervertierten Hohn auf die Traditionen der Trolle und die den verstorbenen Ahnen gebührenden heiligen Riten ansehen."},sec={{t="Eine entweihte Grabstätte",b="In die schroffen Klippen südwestlich von Corins Kreuzung gehauen, wurde das Tiefgewölbe ursprünglich als letzte Ruhestätte für die geehrten Toten von Lordaeron erbaut. Der Untergang des Königreichs raubte ihm seine Unantastbarkeit, und das Grabmal wird nun von einer Schar wilder untoter Trolle heimgesucht. Angeführt von der hünenhaften Monstrosität Zaeldarr the Outcast nutzen diese grässlichen Marodeure die unterirdischen Hallen als Zuflucht, von der aus sie die Pestländer durchstreifen und sogar wagen, die Grabgruben der Kapelle des hoffnungsvollen Lichts zu überfallen, um frische Leichen für ihre finsteren Bräuche zu beschaffen."},{t="Das Grab eines Prätendenten",b="Über seinen monströsen Besetzer hinaus birgt das Tiefgewölbe ein ergreifendes Geheimnis aus der Ära des Zweiten Krieges: ein Scheingrab, das den Namen von Tirion Fordring trägt. Nach seinem Prozess wegen Hochverrats und der darauffolgenden Verbannung inszenierten Fordrings Verbündete hier sein symbolisches Begräbnis, damit seine Familie ihr Ansehen wahren konnte, während der gefallene Paladin im Verborgenen untertauchte. In dieser irdischen Täuschung ruht ein persönliches Andenken aus Tirions Vergangenheit, verborgen an einem Ort, an dem nur jene zu suchen wagen, die die Wahrheit kennen."}},faq={{q="Was ist das Tiefgewölbe?",a="Das Tiefgewölbe ist eine Begräbnisgruft im südwestlichen Teil der Östlichen Pestländer. Ursprünglich erbaut, um den lokalen Adel und gefallene Soldaten Lordaerons beizusetzen, ist es verfallen und wird nun von untoten Schrecken bewohnt.",al={"wo ist das tiefgewölbe","was ist diese gruft","tiefgewölbe östliche pestländer"}},{q="Wer besetzt die Gruft heute?",a="Die Gruft wird von einer Schar untoter Trolle heimgesucht, angeführt von einem massiven untoten Dire Troll namens Zaeldarr the Outcast. Sie nutzen die Tunnel als Unterschlupf zwischen ihren Beutezügen durch die Region.",al={"wer ist im tiefgewölbe","tiefgewölbe gegner","trolle im tiefgewölbe"}},{q="Warum gibt es untote Trolle in den Östlichen Pestländern?",a="Während die Geißel im nördlichen Lordaeron vor allem Menschen und Elfen auferstehen ließ, hausen in der Nähe Trollstämme wie die Mossflayer und Witherbark. Untote Trolle wie Zaeldarr und seine wiedererweckten Gefolgsleute streifen durch die Klippen, plündern Grabstätten und lauern unvorsichtigen Reisenden auf.",al={"warum trolle hier","zaeldarr geschichte","untote trolle östliche pestländer"}},{q="Warum steht der Name von Tirion Fordring auf einem Grab hier?",a="Das Grab ist eine gefälschte Ruhestätte, ein Scheingrab. Nachdem Tirion seines Ranges enthoben und von der Allianz von Lordaeron verbannt worden war, wurde im Tiefgewölbe eine Scheinbeerdigung arrangiert, damit seine Familie ihre Ehre bewahren und seinen Tod vortäuschen konnte, während er heimlich im Verborgenen lebte.",al={"tirion grab","ist tirion tot","fordring grabmal"}},{q="Warum überfallen die Trolle des Tiefgewölbes die Kapelle des hoffnungsvollen Lichts?",a="Zaeldarr the Outcast führt gelegentlich nächtliche Überfälle auf die Grabgruben vor der Kapelle des hoffnungsvollen Lichts an. Sein Ziel ist es, frisch begrabene Leichen auszugraben und zu stehlen, um seine eigene Schar zu verstärken oder ihren morbiden Hunger zu stillen.",al={"zaeldarr überfälle","grabgrubenüberfall","trolle kapelle des hoffnungsvollen lichts"}}},fp="10,351,22.536.0,18.491.1,23.240.0,27.189.0,55.269.0,46.268.0,54.222.0"}
P.entries["subzone:uplands"] = {n="Das Oberland",s="Das Oberland ist ein hügeliges, hochgelegenes Gebiet im nordöstlichen Alteracgebirge, das einst als landwirtschaftliches Kernland des gefallenen Königreichs Alterac diente. Nach dem Zusammenbruch des Königreichs gerieten die fruchtbaren Hügel vollständig unter die Herrschaft des Syndikats. Heute unterhält die kriminelle Organisation hier ihre stärkste Machtbasis und befestigt mehrere Lager auf den Hängen.",h="Das Oberland ist ein hügeliges, hochgelegenes Gebiet im nordöstlichen Alteracgebirge, das einst als...",kw={"alterac","baron vardus","kornkammer","dandreds senke","berge","syndikat","das oberland"},ang={["class:Rogue"]="Das Oberland dient als primärer Machtsitz für das Syndikat, was es zu einem entscheidenden Anschauungsbeispiel dafür macht, wie vertriebener Adel ein ganzes regionales Netzwerk von Banditen in ein organisiertes, tödliches Kartell verwandelte.",["race:Human"]="Diese Hügel sind eine düstere Erinnerung an Alteracs Fall; was einst eine blühende landwirtschaftliche Kornkammer für die Menschheit war, ist nun von Halsabschneidern und ruinierten Ambitionen erstickt."},sec={{t="Von der Kornkammer zur Banditenhochburg",b="Bevor der Zweite Krieg Alterac zerriss, wurden die Hügel des Oberlands als die Kornkammer des Königreichs gefeiert, die Getreide und Vieh zur Versorgung seiner Bergfestungen lieferte. Als das Herz des Reiches in Ruinen und Schande versank, wurden die landwirtschaftlichen Güter von den ehrlichen Leuten verlassen. An ihre Stelle trat das Syndikat, angeführt von enteigneten Alterac-Adligen und Halsabschneidern, die entschlossen waren, ihr gestohlenes Erbe mit Gewalt zurückzufordern. Das Oberland stellt heute das am stärksten konzentrierte Gebiet des Syndikats in der Region dar, übersät mit Lagern, Patrouillen und Außenposten wie Dandreds Senke entlang seiner westlichen Grenzen."},{t="Ein Sitz der Schatten",b="Da das Syndikat diese Hügel mit geballter Kraft beherrscht, überwachen hochrangige Verschwörer oft von dem Oberland aus die Operationen. Gestalten wie Baron Vardus, die mit der schattenhaften Führung verbündet sind, welche die Überreste von Alteracs Adel lenkt, koordinieren Brigantenbewegungen, Überfälle auf benachbarte Täler und den Widerstand gegen Allianz und Horde gleichermaßen. Reisende, die die nordöstlichen Bergrücken überqueren, sehen sich sofortiger Feindseligkeit von verschanzten Wegelagerern ausgesetzt, die das gesamte Gebirge als ihr souveränes Staatsgebiet betrachten."}},faq={{q="Wofür wurde das Oberland ursprünglich genutzt?",a="Das Oberland war historisch gesehen die wichtigste landwirtschaftliche Region des Königreichs Alterac. Seine sanften Hügel dienten als Kornkammer des Königreichs, bevor Krieg und Verrat den Untergang der Nation herbeiführten.",al={"geschichte des oberlands","was früher hier war","zweck des oberlands"}},{q="Wer kontrolliert das Oberland jetzt?",a="Das Oberland wird vom Syndikat gehalten. Alteracs ehemaliger Adel und sein Netzwerk von Banditen haben in diesen Hügeln mehrere Lager errichtet, was es zu dem Gebiet macht, in dem ihre Präsenz am stärksten ist.",al={"wer im oberland lebt","wer das oberland hält","fraktionen im oberland"}},{q="Wo befindet sich das Oberland?",a="Das Oberland erstreckt sich über das nordöstliche Hochland des Alteracgebirges und grenzt an seinem westlichen Rand an Dandreds Senke.",al={"lage des oberlands","wo ist das oberland","oberland finden"}},{q="Wer ist Baron Vardus?",a="Baron Vardus ist ein einflussreicher Adliger und Anführer innerhalb des Syndikats, der die Operationen im Oberland beaufsichtigt und die Banditen und Verschwörer anleitet, die Alterac zurückfordern wollen.",al={"baron vardus lore","wer ist vardus","baron des oberlands"}}},fx={["35db727f"]={q="Warum ist das Oberland ruiniert und verlassen?",a="Das Oberland florierte einst als Kornkammer des Königreichs Alterac, gefüllt mit fruchtbaren Feldern und Gehöften. Als das Königreich nach seinem Verrat während des Zweiten Krieges zusammenbrach, wurde sein Kernland zerschmettert. Ohne den Schutz des Königreichs verdorrte das landwirtschaftliche Herz der Region und wurde von Kriminellen überrannt, was Ruinen wie Dandreds Senke zur Folge hatte.",al={"warum ist das oberland ruiniert","was ist mit den farmen im oberland passiert","warum ist das oberland verlassen"}},["4211f63f"]={q="Ist das Oberland gefährlich?",a="Es ist außergewöhnlich gefährlich. Das Oberland dient als wichtigste Hochburg des Syndikats und beherbergt dort ihre größte Ansammlung an Kämpfern in den gesamten Bergen. Wandernde Banditen, Gesetzlose und abtrünnige Adlige patrouillieren durch die Hügel und bewachen ihre Lager erbittert gegen alle Außenstehenden, die in ihr Territorium eindringen.",al={"ist das oberland gefährlich","oberland gefahr","wie gefährlich ist das oberland"}}},fp="7,390,32.608.0,17.495.0,41.202.0,29.202.0,29.119.0,20.175.0"}
P.entries["subzone:ursolan"] = {n="Ursolan",s="Ursolan ist eine weitläufige Siedlung der Furbolgs der Holzschlundfeste im westlichen Azshara, direkt östlich der Holzschlundfeste. Das von einer tiefen Schlucht durchzogene Lager ehrt den Bären-Urahnen Ursol und dient unberührten Furbolgs als unverzichtbare Festung, um ihr Territorium gegen Eindringlinge von außerhalb zu verteidigen.",h="Ursolan ist eine weitläufige Siedlung der Furbolgs der Holzschlundfeste im westlichen Azshara, direkt östlich...",kw={"azshara","furbolg","schlucht","talrendis","holzschlund","ursol","ursolan"},ang={["class:Druid"]="Druiden hegen tiefen Respekt vor den Schutzpatronen von Ursolan, da die Zwillings-Bärenurahnen Ursol und Ursoc zentrale Gestalten der Naturverehrung und der Beherrschung der Bärengestalt sind.",["race:NightElf"]="Obwohl Nachtelfen die Bären-Urahnen verehren, herrschen vor Ort Spannungen, was sich an den Forschern aus Talrendis zeigt, die die Schlucht unter den argwöhnischen Blicken der Furbolgs untersuchen."},sec={{t="Bastion des Bären",b="Auf den zerklüfteten Klippen des westlichen Azshara gelegen, bildet Ursolan den östlichen Zweig des Gebiets des Holzschlundstamms, der direkt durch die Holzschlundfeste mit dem Bärenkopf im Süden verbunden ist. Benannt nach dem verehrten Bären-Urahnen Ursol, stellt dieses Lager einen seltenen Zufluchtsort des Geistes unter den Furbolgvölkern Kalimdors dar, die größtenteils der dämonischen Verderbnis anheimgefallen sind. Das Dorf erstreckt sich über beide Ränder einer dramatischen Erdkluft, wo die Holzschlundfurbolgs wachsam ihre Grenzen gegen vordringende Eindringlinge verteidigen – darunter aufdringliche Forscher aus dem Nachtelfenlager von Talrendis."}},faq={{q="Wer lebt in Ursolan?",a="Ursolan wird von den Furbolgs der Holzschlundfeste bewohnt, einem der letzten verbliebenen Furbolgstämme, dem es gelungen ist, der dämonischen Verderbnis zu widerstehen, die Kalimdor heimsucht.",al={"wer ist in ursolan","ursolan bewohner","ursolan furbolgs"}},{q="Warum heißt dieses Gebiet Ursolan?",a="Die Siedlung ist zu Ehren von Ursol benannt, einem der Zwillings-Bärengötter, die vom Volk der Furbolgs zutiefst verehrt werden.",al={"ursolan namensursprung","nach wem ist ursolan benannt","bedeutung von ursolan"}},{q="Was ist die tiefe Schlucht, die durch das Lager verläuft?",a="Ursolan wird durch eine tiefe Erdspalte geteilt. Unten in dieser Schlucht können oft Biologen von Talrendis aus dem nahe gelegenen Nachtelfenlager angetroffen werden, die dort Feldstudien durchführen.",al={"canyon in ursolan","schlucht in ursolan","abgrund ursolan"}},{q="Wie ist Ursolan mit dem Rest des Holzschlundgebiets verbunden?",a="Ursolan liegt direkt östlich des Azshara-Eingangs zur Holzschlundfeste und verbindet deren nördliche Präsenz durch die Bergtunnel hinab zum Bärenkopf im Süden.",al={"ursolan verbindung","weg zur holzschlundfeste von ursolan"}}},fp="7,290,19.587.0,21.161.0,32.110.0,48.175.0,64.164.0"}
P.entries["subzone:uther-s-tomb"] = {n="Uthers Grabmal",s="Uthers Grabmal ist die heilige Ruhestätte von Uther dem Lichtbringer, gelegen auf dem Trauerhügel in den Westliche Pestländer. Dieses Denkmal wurde von seinen überlebenden Anhängern nach seinem Fall im nahegelegenen Andorhal errichtet und ist eines der wenigen verbliebenen Bollwerke des das Heilige Licht inmitten einer verseuchten und von Untoten heimgesuchten Region.",h="Uthers Grabmal ist die heilige Ruhestätte von Uther dem Lichtbringer, gelegen auf dem Trauerhügel in den...",kw={"andorhal","arthas","lichtbringer","silberne hand","trauerhügel","theldanis","uther"},ang={["class:Paladin"]="Vor Uthers Statue zu stehen, ist für jeden Paladin eine tiefgreifende Pilgerreise, bei der der Vater ihres Ordens geehrt wird, dessen Opfer die Tugenden der Silbernen Hand verkörpert.",["faction:Alliance"]="Das Grabmal dient als bleibendes Zeugnis für Lordaerons gefallenes Erbe und als Ort der stillen Einkehr für Reisende der Allianz, die den Schrecken der Pestländer trotzen."},sec={{t="Ein Bollwerk in der Verseuchung",b="Südlich der Ruinen von Andorhal auf dem Trauerhügel gelegen, markiert Uthers Grabmal die letzte Ruhestätte des legendären Paladins, der die Ritter der Silbernen Hand gründete. Nach dem Fall von Lordaeron leistete Uther in Andorhal seinen letzten Widerstand, als er die königliche Urne mit der Asche von König Terenas Menethil II. gegen Prinz Arthas Menethil und die Geißel verteidigte. Arthas schlug seinen einstigen Mentor nieder und entweihte die Urne, um die Überreste von Kel'Thuzad zu transportieren. Überlebende Soldaten bargen Uthers Leichnam und betteten ihn in einem steinernen Heiligtum zur Ruhe. Trotz der unerbittlichen Verderbnis, die das umliegende Land verschlingt, bleibt das Grabmal auf wundersame Weise von Verfall verschont und steht unter der standhaften Wache von Hohepriester Thel'danis."},{t="Das Vermächtnis des Lichtbringers",b="Man erreicht das Denkmal über den Pfad von Uther. Es wird von einem großen steinernen Abbild dominiert, das den Paladin mit einem Folianten des das Heilige Licht in der einen und seinem Kriegshammer in der anderen Hand darstellt. Pilger, die diese tückischen Straßen bereisen, suchen das Grabmal häufig auf, um Tribut zu zollen, zu beten oder über die Hingabe nachzudenken, die die ersten Paladine auszeichnete."}},faq={{q="Wer ist in diesem Grabmal beigesetzt?",a="Uther der Lichtbringer ist hier beigesetzt. Er war der Oberkommandierende und Gründer der Ritter der Silbernen Hand, dem ersten Paladinorden in der menschlichen Geschichte, und diente als Mentor von Prinz Arthas Menethil, bevor Lordaeron an die Geißel fiel.",al={"wer ist uther","wer ist hier begraben","uther der lichtbringer"}},{q="Wie starb Uther?",a="Uther wurde in Andorhal von seinem ehemaligen Schüler Arthas Menethil erschlagen, der als Todesritter aus Nordend zurückgekehrt war. Uther fiel, während er erbittert die Urne verteidigte, die die Asche von Arthas' Vater, König Terenas Menethil II., enthielt.",al={"wer tötete uther","wie starb uther","arthas tötet uther"}},{q="Wer ist Hohepriester Thel'danis?",a="Hohepriester Thel'danis ist der hingebungsvolle Wächter des Denkmals. Er hält eine stille, heilige Wache über Uthers Ruhestätte und trotzt den umliegenden Untoten, um sicherzustellen, dass der Schrein ein Zufluchtsort des das Licht bleibt.",al={"theldanis","priester an uthers grabmal","wer beschützt das grabmal"}},{q="Warum ist das Grabmal nicht von der Pest verseucht?",a="Die beständige Heiligkeit von Uthers Andenken und die fortdauernde Macht des das Heilige Licht weihen das Gelände. Während die umliegenden Wälder des Trauerhügel verdorrt sind und der Fäulnis anheimfielen, bleibt der Schrein selbst ein unversehrter Zufluchtsort gegen die Verseuchung.",al={"warum ist uthers grabmal sauber","warum keine pest am grabmal"}}},fp="12,311,23.713.0,25.330.0,27.242.0,18.229.0,30.213.0,43.252.0"}
P.entries["subzone:valgan-s-field"] = {fx={["5ca486da"]={q="Was ist Valgans Feld?",a="Valgans Feld ist ein trostloses, verlassenes Weizenfeld im nördlichen Silberwald, das westlich des leuchtenden Strandes und östlich der Hauptstraße liegt. Bevor die Pest durch Lordaeron wütete, war es ein friedliches Gehöft mit Blick auf den Lordameresee. Heute, wie ein Großteil des Waldes, liegt es überwuchert, ungepflegt und wird von tödlichen Raubtieren heimgesucht.",al={"was ist valgans feld","valgan farm","valgans feld silberwald"}},["1c9d9eee"]={q="Was geschah bei Valgans Feld?",a="Vor dem Dritter Krieg verbrachte der Erzmagier Arugal Zeit hier und hinterließ Überreste seiner arkanen Forschung. Als die Geißel durch den Silberwald fegte, verfiel das Gehöft, da sein Besitzer vertrieben oder niedergemetzelt wurde. Später, als Arugal von Burg Shadowfang aus die Worgen auf die Region losließ, überrannten wilde Mondzornworgen die Felder und beanspruchten die kaputte Farm als ihr Territorium.",al={"geschichte von valgans feld","was geschah mit der valgan farm"}},d73dae69={q="Warum ist Valgans Feld zerstört?",a="Die Farm wurde verlassen, als die Geißel durch das nördliche Lordaeron marschierte und die ländlichen Siedlungen verwüstete. Jegliche Hoffnung, das Land zurückzugewinnen, schwand, als Arugal die jenseitigen Worgen herbeirief, deren Mondzornrudel die Felder befiel und eine menschliche Besiedlung unmöglich machte.",al={"warum ist valgans feld verlassen","warum ist die valgan farm ruiniert","ruinen von valgans feld"}}}}
P.entries["subzone:valley-of-bones"] = {n="Tal der Knochen",s="Das Tal der Knochen ist eine trostlose Schlucht entlang der Klippen von Shen'dralas, erstickt von Staub, uralten Überresten und ruhelosen Untoten. Heimgesucht von den verweilenden Geistern des Magram-Zentaurenklans und patrouilliert von dunklen Totenbeschwörern, wird es von den kolossalen Brustkörben mysteriöser, uralter Bestien dominiert, die als die Toten Goliathe bekannt sind.",h="Das Tal der Knochen ist eine trostlose Schlucht entlang der Klippen von Shen'dralas, erstickt von Staub...",kw={"zentauren","tote goliathe","magram","totenbeschwörer","shen'dralas","skelette","tal der knochen"},ang={["class:Priest"]="Die Schändung der Geister im Tal ist verheerend, da dunkle Praktizierende den natürlichen Übergang des Todes pervertieren, indem sie Magram-Seelen binden und verkrüppelte Skelettdiener erwecken."},sec={{t="Eine Schlucht der ruhelosen Toten",b="Verborgen in den südlichen Gefilden der Region macht das Tal der Knochen seinem düsteren Namen alle Ehre. Skelettartige Schrecken durchwandern die staubigen Schluchten, erweckt und gebunden von Zentauren-Totenbeschwörern, die sich dunkler Zauberkräfte bedienen. Die Geister verstorbener Magram-Zentauren wandern an ihrer Seite durch die Einöde, noch lange nach ihrem gewaltsamen Tod an diese karge Erde gebunden. Die bedrohliche Natur des Canyons wird noch verstärkt durch die Toten Goliathe – zwei gewaltige Skelette, die an die felsigen Klippen gelehnt sind und deren wahrer Ursprung Gelehrten wie Wanderern gleichermaßen ein vollkommenes Rätsel bleibt."}},faq={{q="Was sind die Toten Goliathe?",a="Die Toten Goliathe sind die kolossalen Überreste zweier riesiger, unidentifizierter Kreaturen, die an den Wänden der Schlucht ruhen. Es ist wenig darüber bekannt, welcher Spezies sie angehörten oder wann sie starben, doch ihr schieres Ausmaß deutet auf Bestien aus einer uralten, vergessenen Ära hin.",al={"riesige knochen","riesige skelette desolace","tote goliathe lore"}},{q="Warum gibt es hier Zentaurengeister?",a="Die Geister gehören zum Klan der Magram, einem der gewalttätigen Zentaurenstämme, die in diesen kargen Ebenen heimisch sind. Wegen der endlosen Kriege zwischen den Klans und der Anwesenheit von Zentauren-Totenbeschwörern, die sich an den Toten vergehen, wurde ihren Seelen die Ruhe verwehrt, sodass sie die Schlucht als wandelnde Erscheinungen heimsuchen.",al={"magram geister","warum zentaurengeister","untote zentauren"}},{q="Wer kontrolliert die Skelette im Tal?",a="Zentauren-Totenbeschwörer praktizieren dunkle Riten in der Schlucht, erwecken und befehligen skelettierte Diener, um die Klippen zu bewachen und ihren Einflussbereich unter den Toten aufrechtzuerhalten.",al={"wer befehligt skelette","totenbeschwörer tal der knochen"}}},fp="15,323,29.534.0,27.259.0,34.289.0,41.162.0"}
P.entries["subzone:valley-of-fangs"] = {n="Fangzahntal",s="Das Fangzahntal ist ein zerklüfteter, enger Pass, der zwischen hoch aufragenden Felssäulen im Zentrum des Ödlands verläuft. Bekannt für die bösartigen Raubtiere, die seinen staubigen Grund durchstreifen, beherbergt es zudem ein kleines, abgelegenes Lager wandernder Tüftler und Verbannter.",h="Das Fangzahntal ist ein zerklüfteter, enger Pass, der zwischen hoch aufragenden Felssäulen im Zentrum des...",kw={"ödland","pumas","jazzrik","martek the exiled","rigglefuzz","fangzahntal","wölfe"},ang={["class:Hunter"]="Die dichte Population zäher Pumas und Wölfe macht das Tal zu einem erstklassigen Jagdrevier, um Beute aufzuspüren und widerstandsfähige Bestien des Ödlands zu zähmen.",["profession:Engineering"]="Die im Fangzahntal lagernden Goblin-Tüftler ziehen neugierige Ingenieure an, die mitten in den trockenen Weiten nach unkonventionellem Fachwissen suchen."},sec={{t="Ein tückischer Pass",b="Eingebettet zwischen zwei imposanten Felsformationen im Herzen des Ödlands verdankt das Fangzahntal seinen Namen sowohl den scharfen Silhouetten der umliegenden Klippen als auch den gefährlichen Bestien, die seinen Grund durchstreifen. Wilde Felskojoten, schleichende Pumas und bösartige Wölfe lauern in dem staubigen Korridor, was die Durchquerung für einsame Reisende gefährlich macht. Trotz der feindseligen Tierwelt hat hier eine Handvoll eigenwilliger Gestalten – darunter der verbannte Orc Martek the Exiled und seine Goblin-Gefährten Rigglefuzz und Jazzrik – ein provisorisches Lager aufgeschlagen, wo sie fernab der regionalen Außenposten in Abgeschiedenheit tüfteln."}},faq={{q="Wo befindet sich das Fangzahntal?",a="Das Fangzahntal liegt im Zentrum des Ödlands, eingebettet zwischen zwei gewaltigen natürlichen Felsformationen südlich des nördlichen Hauptkamms.",al={"fangzahntal standort","wo ist das fangzahntal","fangzahntal karte"}},{q="Wer lebt im Fangzahntal?",a="Hier befindet sich ein kleines Lager am Wegesrand, die Heimat des einsamen Orcs Martek the Exiled und seiner tüftelnden Goblin-Gefährten Rigglefuzz und Jazzrik.",al={"wer ist im fangzahntal","fangzahntal lager","fangzahntal nscs"}},{q="Warum ist die Reise durch das Tal gefährlich?",a="Der Talboden ist dicht von aggressiver, im Ödland heimischer Tierwelt bevölkert, insbesondere von räuberischen Pumas, Wölfen und Kojoten, die Wanderern in dem engen Gelände auflauern.",al={"fangzahntal gefahr","fangzahntal mobs","was greift im fangzahntal an"}},{q="Warum haben sich Martek und die Goblins hier niedergelassen?",a="Ausgestoßen und durch die Einöde wandernd, fand Martek the Exiled zwischen den Felswänden eine ruhige, gut zu verteidigende Nische, zusammen mit Goblin-Gefährten, die bereit waren, fernab der neugierigen Blicke großer Fraktionen zu handeln und zu tüfteln.",al={"warum ist martek hier","warum ein lager im fangzahntal","martek the exiled"}}},fp="15,247,18.594.0,37.138.0,33.139.0,46.176.0,43.208.0"}
P.entries["subzone:valley-of-heroes"] = {n="Das Tal der Helden",s="Das Tal der Helden bildet den monumentalen südlichen Eingang nach Sturmwind und führt Reisende über eine Steinbrücke, die den Burggraben überspannt. Flankiert von gewaltigen Statuen zu Ehren der Anführer der Expedition der Allianz nach Draenor, dient es sowohl als ehrfurchtgebietender Empfang als auch als schwer befestigter Kontrollpunkt.",h="Das Tal der Helden bildet den monumentalen südlichen Eingang nach Sturmwind und führt Reisende über eine...",kw={"alleria","danath","khadgar","kurdran","marcus jonathan","tor von sturmwind","turalyon","das tal der helden"},ang={["class:Paladin"]="Die Statue von General Turalyon dient Paladinen als tiefgreifende Inspiration und verewigt einen der ersten Champions der Ritter der Silbernen Hand.",["faction:Alliance"]="Jeder Bürger der Großen Allianz verehrt das Tal als feierliches Zeugnis der Zusammenarbeit zwischen den Völkern, das menschliche, hochelfische und zwergische Märtyrer Seite an Seite ehrt."},sec={{t="Ein Monument für die Verlorenen",b="Errichtet während des großen Wiederaufbaus von Sturmwind nach dem Zweiten Krieg, gedenken die Statuen entlang des Damms der Kommandanten der Expedition der Allianz. Diese Champions marschierten durch das Dunkle Portal in die orkische Heimatwelt Draenor, um den Riss für immer zu versiegeln, und gaben ihr Leben, damit Azeroth überleben konnte. Besucher, die nach Norden in Richtung Der Handelsdistrikt weiterziehen, passieren die Bildnisse von Erzmagier Khadgar, Kurdran Wildhammer, Waldläuferhauptmann Alleria Windläufer, Truppenkommandant Danath Trollbann und Hochgeneral Turalyon."},{t="Die Bastion der Stadt",b="Über seine zeremonielle Rolle hinaus ist das Tal der wichtigste defensive Engpass, der Sturmwind vor einer Invasion über Land schützt. Die Zugänge werden von General Marcus Jonathan überwacht, dem Kommandanten der Stadtwache, der hoch zu Ross jeglichen Verkehr kontrolliert, der die großen Tore passiert. Flankierende Befehlshaber, darunter Major Mattingly und Feldmarschall Steinsteg, halten an der Seite von Reihen erfahrener Wachen Wachsamkeit und stellen sicher, dass die Hauptstadt vor äußeren Bedrohungen geschützt bleibt."}},faq={{q="Wer sind die Statuen entlang des Pfades?",a="Die fünf kolossalen Monumente stellen die legendären Kommandanten der Söhne Lothars dar, welche die Expedition der Allianz nach Draenor anführten: Hochgeneral Turalyon, Waldläuferhauptmann Alleria Windläufer, Erzmagier Khadgar, Kurdran Wildhammer und Truppenkommandant Danath Trollbann.",al={"statuen in sturmwind","wer sind die helden","tal der helden statuen","namen auf den statuen"}},{q="Warum wurden diese Monumente am Stadttor aufgestellt?",a="Die während des Wiederaufbaus der Stadt nach dem Zweiten Krieg errichteten Statuen dienen als dauerhafter Tribut an die Helden, die man bei der Zerstörung von Draenor für verloren hielt. Sie erinnern jeden Eintretenden an den hohen Preis, der für die Sicherheit des Königreichs gezahlt wurde.",al={"warum statuen hier gebaut","zweck des tals der helden"}},{q="Wer befehligt die am Eingang stationierten Wachen?",a="General Marcus Jonathan, der oberste Befehlshaber der Stadtwache von Sturmwind, überwacht die Sicherheit des Tals direkt von vorderster Front aus, unterstützt von Offizieren wie Major Mattingly und Feldmarschall Steinsteg.",al={"wachhauptmann","wer ist der mann auf dem pferd","wer leitet die verteidigung von sturmwind"}},{q="Wohin führt das Tal der Helden?",a="Richtung Norden über die Brücke gelangen Reisende direkt in den geschäftigen Handelsdistrikt von Sturmwind, während der Weg nach Süden durch die Tore in die idyllischen Wälder von Elwynn führt.",al={"wohin führt die brücke","wegbeschreibung tor von sturmwind"}}},fx={f5acfed9={q="Was ist Das Tal der Helden?",a="Das Tal der Helden ist der große, üppige Eingangsbereich, der vor den Haupttoren von Sturmwind liegt. Eine breite Steinbrücke überspannt den Wassergraben zwischen dem Wald von Elwynn und den Toren der Stadt, flankiert von hoch aufragenden Monumenten, die legendäre Champions ehren. Für jeden, der zu Fuß aus dem Süden ankommt, dient es als die große Schwelle zur Hauptstadt des Menschenkönigreichs.",al={"was ist das tal der helden","tal der helden sturmwind","über das tal der helden"}},["5176beb8"]={q="Was geschah im Das Tal der Helden?",a="Nach dem Zweiter Krieg und während des Wiederaufbaus von Sturmwind wurde dieses Tal zu einem dauerhaften Denkmal umgestaltet. Fünf monumentale Statuen wurden errichtet, um die Expedition der Allianz zu ehren, die durch Das Dunkle Portal in die zertrümmerte Welt Draenor marschierte, um den Dimensionsriss zu versiegeln. Da man glaubte, sie seien auf der anderen Seite für immer verloren, wurden diese fünf Kommandanten als ewiger Tribut für ihr Opfer in Stein verewigt.",al={"geschichte des tal der helden","lore des tal der helden","was geschah hier"}},["7507c845"]={q="Ist Das Tal der Helden gefährlich?",a="Nein. Das Tal der Helden ist stark befestigt und dient als Haupteingang zur Hauptstadt der Allianz. Es wird von hochrangigen Offizieren wie General Marcus Jonathan bewacht und ständig von der Stadtwache patrolliert, was es zu einem der sichersten Orte in ganz Azeroth für Reisende der Allianz macht.",al={"ist das tal der helden sicher","ist das tal der helden gefährlich","gefahr im tal der helden"}},["6b62f2c8"]={q="Warum heißt es Das Tal der Helden?",a="Das Tal hat seinen Namen von den kolossalen Steinstatuen, die entlang seines Zugangs stehen. Jede stellt einen prominenten Anführer der Expedition der Allianz nach Draenor dar – Turalyon, Alleria Windläufer, Khadgar, Danath Trollbann und Kurdran Wildhammer –, die alles opferten, um Azeroth vor der dämonischen Bedrohung jenseits Das Dunkle Portal zu schützen.",al={"warum heißt es das tal der helden","ursprung des namens tal der helden","warum tal der helden"}}},fp="16,306,22.531.0,16.488.0,36.259.0,49.242.0,50.219.0,37.175.0"}
P.entries["subzone:valley-of-honor"] = {fx={cbe73428={q="Was ist das Tal der Ehre?",a="Das Tal der Ehre dient als stolzes militärisches Herz von Orgrimmar. Eingebettet in die nordöstlichen Schluchten der Stadt, ist dieser raue Distrikt der militärischen Disziplin gewidmet und beherbergt die Kasernen der Stadt, die Hall of the Brave sowie Die Jägerhalle. Hier verfeinern Krieger und Jäger ihr tödliches Handwerk, während Kampfmeister Champions versammeln, um sich auf weit entfernten Schlachtfeldern in ganz Azeroth zu messen.",al={"tal der ehre","was ist das tal der ehre","tal der ehre orgrimmar"}},["167ed7f9"]={q="Wer lebt im Tal der Ehre?",a="Das Tal ist in erster Linie die Heimat der militärischen Streitkräfte der Horde und der Handwerker, die diese ausrüsten. Veteranen, Rekruten der Grunts, Jäger und Tierbändiger versammeln sich in den Hallen und Kasernen. An ihrer Seite arbeiten Schmiede, Bergleute und Ingenieure, die die Kriegsmaschinerie der Horde mit scharfen Klingen, stabiler Plattenrüstung und Munition versorgen.",al={"wer lebt im tal der ehre","bewohner tal der ehre","wer führt das tal der ehre"}},["6cb8ac9d"]={q="Ist das Tal der Ehre gefährlich?",a="Für loyale Mitglieder der Horde ist das Tal der Ehre eine sichere Bastion, die von einigen der mächtigsten Champions und Soldaten der Stadt bewacht wird. In den Trainingshallen finden zwar erbitterte, adrenalingeladene Kämpfe statt, doch die Gewalt beschränkt sich strikt auf das Training und regulierte militärische Prüfungen. Für jeden eindringenden Feind des Kriegshäuptlings ist es jedoch einer der tödlichsten Orte in Durotar.",al={"ist das tal der ehre gefährlich","gefahr im tal der ehre","gefahren im tal der ehre"}}}}
P.entries["subzone:valley-of-kings"] = {fx={["7c2b9610"]={q="Was ist das Tal der Könige?",a="Das Tal der Könige ist ein üppiger Gebirgspass, der in der südwestlichen Ecke von Loch Modan liegt, westlich des Splittersteintals. Er dient als wichtiger Kreuzungspunkt für Reisende zwischen Dun Morogh über den Südtorpass und den gefährlichen, vulkanischen Ländern der Sengende Schlucht im Süden.",al={"tal der könige loch modan","was ist das tal der könige","informationen zum tal der könige"}},["0960ad5d"]={q="Was geschah im Tal der Könige?",a="Nach dem verheerenden Krieg der drei Hämmer und dem tragischen Tod von Großkönig Madoran Bronzebart und König Khardros Wildhammer gaben ihre Söhne gemeinsam die beiden kolossalen Monumente des Tals in Auftrag. Die Statuen, die in die Klippen mit Blick auf den südlichen Pass gemeißelt wurden, stehen als ewiges Denkmal für ihren gemeinsamen Sieg über den Zauberfürst Thaurissan und das verbrannte Ödland, das er hinterließ.",al={"geschichte des tal der könige","warum sind hier statuen","lore des tal der könige"}},f059810f={q="Wer kontrolliert das Tal der Könige?",a="Das Tal untersteht der souveränen Autorität von Eisenschmiede und wird von Zwergen-Bergsoldaten patrolliert. Am südlichen Tor, das hinunter zur Sengende Schlucht führt, hält Bergsoldat Pebblebitty Wache und stellt sicher, dass nur erfahrene Abenteurer, die ihr Können unter Beweis gestellt haben, die schweren Tore öffnen und sich in Richtung der versengten Ödlande wagen können.",al={"wer kontrolliert das tal der könige","wer verwaltet das tal der könige","eisenschmiede wachen tal der könige"}},["960bcb2e"]={q="Ist das Tal der Könige gefährlich?",a="Obwohl das Tal selbst relativ sicher ist und von Bergsoldaten aus Eisenschmiede patrolliert wird, grenzt es an extreme Gefahren. Direkt im Osten liegt das troggverseuchte Splittersteintal, und direkt im Süden, versiegelt hinter verschlossenen Toren, wartet das sengende, feindselige Gelände der Sengende Schlucht und Der Schwarzfels.",al={"gefahr im tal der könige","ist es hier sicher","bedrohungen im tal der könige"}},["04615939"]={q="Warum heißt es das Tal der Könige?",a="Das Tal verdankt seinen Namen den zwei kolossalen Statuen, die in die Berghänge gemeißelt wurden und Großkönig Madoran Bronzebart von Eisenschmiede sowie König Khardros Wildhammer von Grim Batol darstellen. Ihre Söhne ließen diese hoch aufragenden Bildnisse gemeinsam errichten, um die Führung ihrer Väter im Krieg der drei Hämmer zu ehren.",al={"warum heißt es das tal der könige","ursprung des namens tal der könige","wer benannte das tal der könige"}}}}
P.entries["subzone:valley-of-spears"] = {n="Das Tal der Speere",s="Das Tal der Speere ist ein rauer Canyon im westlichen Desolace und dient als Festung des Maraudine-Zentaurenklans. Von steilen Klippen und bewachten Pässen umschlossen, führt das Tal direkt nach Maraudon, der heiligen, uralten Grabstätte aller Zentauren.",h="Das Tal der Speere ist ein rauer Canyon im westlichen Desolace und dient als Festung des...",kw={"zentauren","desolace","maraudine","maraudon","melizza brimbuzzle","das tal der speere"},ang={["faction:Alliance"]="Die Allianz behält die Region vorsichtig im Auge, besonders nachdem erkundungsfreudige Reisende wie die Gnom-Dame Melizza Brimbuzzle vom feindseligen Maraudine-Klan gefangen genommen wurden.",["race:Tauren"]="Die Grausamkeit der Zentauren plagt die Stämme von Kalimdor seit Generationen; wer diese Festung durchquert, sieht sich als Taure mit dem Kern dieser uralten Feindschaft konfrontiert."},sec={{t="Festung der Maraudine",b="Das in die rauen Höhen des westlichen Desolace gehauene Tal der Speere ist eine Festung des Maraudine-Klans. Da es zu Fuß nur über schmale, leicht zu verteidigende Bergpässe aus dem Süden und Osten zugänglich ist, bietet dieses umschlossene Tal den Zentauren eine natürliche Bastion. Reisende, die sich an den felsigen Engpässen vorbei wagen, treffen auf dichte Lager feindseliger Nomaden, die den Zugang zu ihrer am meisten verehrten heiligen Stätte bewachen."},{t="Die Schwelle zu Maraudon",b="Versteckt am südwestlichen Ende des Tals liegt der Eingang zu Maraudon, der heiligen Höhle, in der sich das Grab von Zaetar, dem Vater der Zentauren, befindet und wo Prinzessin Theradras haust. Aufgrund dieser Nähe verteidigen die Maraudine den Canyon mit fanatischer Wut gegen rivalisierende Klans sowie fremde Eindringlinge. Jeder, der töricht genug ist, unvorbereitet in das Tal zu stolpern – wie etwa unvorsichtige Gnom-Kartografen oder Kundschafter –, wird häufig gefangen genommen oder getötet."}},faq={{q="Wer kontrolliert das Tal der Speere?",a="Das Tal ist das Hauptterritorium des Maraudine-Klans, einer der kriegerischen Zentaurenfraktionen, die in Desolace um die Vorherrschaft kämpfen.",al={"wer lebt hier","zentaurenklan im tal der speere","maraudine-basis"}},{q="Wohin führt das Tal der Speere?",a="An der südwestlichen Spitze des Tals befindet sich der Eingang zu Maraudon, der heiligen, uralten Höhle und Grabstätte der Zentaurenrasse.",al={"wie kommt man nach maraudon","eingang zu maraudon","was befindet sich am ende des tals der speere"}},{q="Wie betritt man das Tal?",a="Das Tal ist von steilen Gebirgskämmen umgeben und kann nur zu Fuß durch schmale Gebirgspässe im Osten und Süden betreten werden.",al={"eingang zum tal der speere","wie kommt man hinein","pässe ins tal der speere"}},{q="Ist jemand im Tal gefangen?",a="Ja, eine unglückliche Gnom-Dame namens Melizza Brimbuzzle wurde von den Maraudine-Zentauren gefangen genommen und wird in ihren Lagern festgehalten.",al={"melizza brimbuzzle","gefangener im tal der speere","gnom-gefangene"}}},fp="16,264,27.419.0,25.457.0,34.130.0,37.139.0,28.136.0,32.131.0"}
P.entries["subzone:valley-of-spirits"] = {n="Tal der Geister",s="Eingebettet an den westlichen Klippen von Orgrimmar dient das Tal der Geister als traditionsreicher Sitz des Stammes der Dunkelspeer innerhalb der Hauptstadt der Horde. Gesäumt von strohgedeckten Hütten, Tikipfählen und ruhigen Gewässern bildet es einen scharfen Kontrast zum umgebenden roten Gestein und der eisernen orkischen Architektur.",h="Eingebettet an den westlichen Klippen von Orgrimmar dient das Tal der Geister als traditionsreicher Sitz des...",kw={"darkbriar lodge","dunkelspeer","orgrimmar","spirit lodge","talon gate","trolle","tal der geister"},ang={["profession:Herbalism"]="Die ruhigen Wasserwege und spezialisierten Hütten im Tal machen es zu einem zentralen Ort der Stadt, um das Wissen einheimischer Kräuterkundemeister zu erlangen.",["race:Troll"]="Für den Stamm der Dunkelspeer bietet diese friedliche Enklave ein unverzichtbares Stück Heimat und kulturelle Identität innerhalb der aufragenden roten Canyons der orkischen Hauptstadt."},sec={{t="Eine Heimat für die Dunkelspeer",b="Westlich des geschäftigen Tals der Stärke abzweigend, ist das Tal der Geister eine üppige und ruhige Enklave, die den Dunkelspeertrollen gewidmet ist. Als sich der Stamm an der Seite von Thralls Orks in Durotar niederließ, wurde dieser friedliche Winkel inmitten der Felsen zu ihrem städtischen Versammlungsort. Handwerker, Spiritualisten und Praktizierende der Trolle versammeln sich um die Holzbrücken und gewundenen Gewässer, um ihren Künsten fernab der trockenen Hitze der Hauptverkehrswege nachzugehen."},{t="Hüter des Handwerks",b="Jenseits seiner Behausungen und ruhigen Teiche beherbergt das Tal Ausübende der Magie und des wilden Handwerks. Hexendoktoren, Kräuterkundige und Zauberwirker versammeln sich in Bauten wie der Spirit Lodge und der Darkbriar Lodge. Weiter hinten liegt das Talon Gate, das sich direkt zu den weiten Ebenen des Brachlands hin öffnet und Wanderern, Jägern sowie Reisenden jenseits der Canyonwände einen schnellen Durchgang bietet."}},faq={{q="Wer lebt im Tal der Geister?",a="Das Tal ist vor allem die Heimat der Dunkelspeertrolle, die sich an der Seite der Orks in Durotar niedergelassen haben. Ihr werdet hier ihre Handwerker, spirituellen Anführer, Kräuterkundigen und Jäger finden, die inmitten typischer Trollhütten und geschnitzter Tikitotems leben.",al={"wer lebt hier","tal der geister bewohner","trolle in orgrimmar"}},{q="Wohin führt das Talon Gate?",a="Das Talon Gate befindet sich im hinteren Teil des Tal der Geister und fungiert als westlicher Ausgang von Orgrimmar. Wenn Ihr es durchquert, gelangt Ihr direkt in das Becken des Südstroms und auf die Ebenen des Brachlands.",al={"talon gate ausgang","hintertor orgrimmar","tal der geister tor"}},{q="Welche Dienste und Lehrer sind hier zu finden?",a="Das Tal der Geister bietet Lehrer und Händler für Kräuterkunde, Kochkunst sowie verschiedene Disziplinen der Wildnis und Magie, die in bedeutenden Gebäuden wie der Spirit Lodge und der Darkbriar Lodge untergebracht sind.",al={"lehrer im tal der geister","was gibt es im tal der geister"}}},fx={cef16464={q="Was ist das Tal der Geister?",a="Das Tal der Geister ist ein langes, schmales Viertel innerhalb von Orgrimmar, das sich vom zentralen Tal der Stärke bis zum hinteren Krallentor der Stadt erstreckt. Geprägt von seiner tropischen Architektur, Totems und flachen Wasserwegen, dient es als kulturelles Zentrum und Wohnhafen für die Dunkelspeere neben ihren Verbündeten, den Orcs, innerhalb der Hauptstadt der Horde.",al={"was ist das tal der geister","tal der geister orgrimmar","trollviertel"}},["8d1b898f"]={q="Was ist die Geschichte des Tal der Geister?",a="Gegründet während der Gründung von Orgrimmar nach dem Dritter Krieg, wurde das Tal als Heimat für den Stamm der Dunkelspeere beiseitegelegt, als sie sich Thralls neuer Horde anschlossen. Seit dem Bau der Hauptstadt dient es als Zentrum für Troll-Schamanismus, Voodoo-Praktiken und das tägliche Gemeinschaftsleben, geschützt hinter den roten Felswänden der Stadt.",al={"geschichte des tal der geister","was geschah im tal der geister","lore des tal der geister"}},["210fd1e6"]={q="Ist das Tal der Geister gefährlich?",a="Nein, es ist für Mitglieder der Horde und neutrale Besucher vollkommen sicher. Bewacht von den Wachen Orgrimmars und Kriegern der Dunkelspeer, ist das Tal eine häusliche Siedlung, die eher Schutz, Handel und spirituelle Führung bietet als physische Bedrohungen.",al={"ist das tal der geister sicher","gefahr im tal der geister","feinde im tal der geister"}}},fp="17,303,24.453.0,20.401.0,35.238.0,31.199.0,42.204.0"}
P.entries["subzone:valley-of-strength"] = {n="Tal der Stärke",s="Das Tal der Stärke ist der geschäftige zentrale Treffpunkt von Orgrimmar, der jeden begrüßt, der durch die gewaltigen Vordertore der Stadt zieht. Mit der Stadtbank, dem zentralen Auktionshaus und dem Gasthaus Zum Holzfällerbeil dient es als schlagendes kommerzielles und administratives Herz der Hauptstadt der Horde.",h="Das Tal der Stärke ist der geschäftige zentrale Treffpunkt von Orgrimmar, der jeden begrüßt, der durch die...",kw={"auktionshaus","bank","zum holzfällerbeil","durotar","grommash hold","horde","orgrimmar","thrall","tal der stärke"},ang={["faction:Horde"]="Als zentraler Platz hinter den Toren von Orgrimmar ist das Tal der Stärke der erste Ort, an dem sich Reisende der Horde treffen, um zu handeln und für Expeditionen zu rekrutieren."},sec={{t="Die Tore der Stadt",b="Schreitet durch die befestigten Holztore von Orgrimmar und Ihr betretet das Tal der Stärke. Tief in den roten Canyonfelsen von Durotar gehauen, dient dieses Tal als Vorplatz der Horde. Abenteurer, Händler und Krieger aus allen verbündeten Völkern mischen sich auf den staubigen Plätzen, tauschen Kriegsgeschichten bei Krügen aus dem Gasthaus Zum Holzfällerbeil aus oder erledigen wichtige Geschäfte an der zentralen Bank und im Auktionshaus. Es ist ein geschäftiges Zeugnis der Stärke und Einheit, die die Orcs in ihrer neuen Heimat zu etablieren kämpften."},{t="Zentrum für Handel und Befehl",b="Jenseits seiner defensiven Bedeutung fungiert das Tal als wichtigster Marktplatz der Hauptstadt. Läden wie Soran's Leather and Steel Armory verkaufen Rüstungen, während verschiedene Händler Proviant für lange Reisen durch das Brachland bereitstellen. Grunzer halten an jeder Ecke wachsam Wache, weisen Neuankömmlinge ein und sorgen für Ordnung unter den verschiedenen Völkern, die unter Thralls Banner Zuflucht gefunden haben."}},faq={{q="Was ist das Tal der Stärke?",a="Es ist der Haupteingangsbereich und das zentrale Tal von Orgrimmar, das sich direkt hinter den Haupttoren der Stadt befindet. Es beherbergt wichtige städtische Dienste wie die Bank, das Auktionshaus, Händler für allgemeine Waren und das Gasthaus Zum Holzfällerbeil.",al={"übersicht tal der stärke","was ist dieser ort","eingangsbereich orgrimmar"}},{q="Wo befindet sich Grommash Hold im Verhältnis zu diesem Tal?",a="Grommash Hold befindet sich nicht im Tal der Stärke; es liegt im Norden im Valley of Wisdom und dient als Sitz von Kriegshäuptling Thrall und dem Oberkommando der Horde.",al={"wo ist thrall","standort grommash hold","sitz des kriegshäuptlings"}},{q="Welche Dienste finde ich hier?",a="Das Tal beherbergt die primäre Stadtbank, das Auktionshaus, Handelsbedarf, Rüstungshändler bei Soran's Leather and Steel Armory, Unterkunft im Zum Holzfällerbeil und allgemeine Handelswaren.",al={"annehmlichkeiten tal der stärke","händler tal der stärke","was gibt es hier"}},{q="Wer bewacht das Tal der Stärke?",a="Das Tal wird schwer von Orgrimmar-Grunzern patrouilliert, erfahrenen Orc-Kriegern, die den Frieden wahren, ankommende Karawanen schützen und Reisende durch die labyrinthartige Canyonstadt leiten.",al={"orgrimmar grunzer","wachen im tal der stärke","stadtverteidigung"}}},fx={da94a7d4={q="Ist das Tal der Stärke gefährlich?",a="Nicht für Mitglieder der Horde. Als geschäftiges Eingangstor und kommerzielles Herz von Orgrimmar wird es rund um die Uhr von Grunzer und Stadtverteidigern stark bewacht. Die einzige wirkliche Gefahr hier wäre ein direkter Überfall der Allianz, der die Haupttore durchbricht, oder heimliche Infiltratoren, die versuchen, die Führung der Horde zu ermorden.",al={"ist das tal der stärke gefährlich","gefahr im tal der stärke","sicher im tal der stärke"}},["007f5841"]={q="Wer lebt im und leitet das Tal der Stärke?",a="Das Tal dient als öffentliches Zentrum von Orgrimmar und arbeitet unter der Autorität von Kriegshäuptling Thrall und seinen Wachen. Reisende, Bankiers und Händler tummeln sich auf seinen offenen Straßen, während Thrall von Grommash Hold im Tal der Weisheit aus regiert.",al={"wer verwaltet das tal der stärke","bewohner des tal der stärke","wer kontrolliert das tal der stärke"}}},fp="18,289,21.508.0,24.385.0,31.222.0,55.164.0,30.183.0,34.180.0"}
P.entries["subzone:valley-of-the-watchers"] = {n="Tal der Behüter",s="Versteckt in den fernsten südlichen Weiten der Wüste von Tanaris liegt das Tal der Behüter, ein sonnenverbrannter Canyon, der von monumentalen Steinmetzarbeiten geprägt ist. An seinem Ende steht ein kolossales, versiegeltes Steintor, das in den geheimnisvollen Komplex von Uldum führt, bewacht von schwerfälligen Riesen und uralten Steinschildwachen.",h="Versteckt in den fernsten südlichen Weiten der Wüste von Tanaris liegt das Tal der Behüter, ein...",kw={"dünenzertrümmerer","kalimdor","tanaris","titanentor","titanen","uldum","tal der behüter"},ang={["race:Dwarf"]="Für Zwergenforscher und Mitglieder der Forscherliga stellt das massive Steintor ein weiteres verlockendes Puzzlestück bei der Suche nach ihren Schöpfern, den Titanen, dar."},sec={{t="Die versiegelte Schwelle",b="Das Tal der Behüter markiert die südliche Grenze, an der der wandernde Sand von Tanaris auf den gebirgigen Rand des Kontinents trifft. Beherrscht wird die Schlucht von einem massiven Tor aus uraltem Stein, das fest vor der Außenwelt verschlossen ist. Dieses versiegelte Portal soll den Eingang nach Uldum bewachen, einer unterirdischen Anlage der rätselhaften Titanen. Gewaltige Dünenzertrümmerer-Berggiganten durchstreifen den staubigen Zugang und sorgen dafür, dass die Geheimnisse, die unter dem Sand begraben liegen, von Reisenden, Grabräubern und Gelehrten gleichermaßen ungestört bleiben."}},faq={{q="Was befindet sich hinter dem riesigen Steintor hier?",a="Die monumentalen Tore sind der Eingang nach Uldum, einer uralten unterirdischen Anlage, die lange vor den ersten sterblichen Geschichtsschreibungen von den Titanen errichtet wurde. Bislang bleiben die Mechanismen vollständig versiegelt, wodurch ihr wahrer Inhalt und Zweck ein absolutes Rätsel bleiben.",al={"tor von uldum","was ist uldum","was ist hinter der tür"}},{q="Kann das Tor nach Uldum geöffnet werden?",a="Nein. Die massiven Steintore sind vollkommen unpassierbar. Kein sterblicher Schlüssel, Zauber oder keine bekannte Macht auf Kalimdor kann derzeit die Schutzvorkehrungen der Titanen umgehen, die den Komplex verschlossen halten.",al={"kann man das uldum-tor öffnen","tür nach uldum öffnen","wie man nach uldum gelangt"}},{q="Warum wandern Riesen durch das Tal?",a="Kolossale Berggiganten, bekannt als Dünenzertrümmerer, streifen über den Schluchtboden. Angezogen von der mächtigen Erdenergie des Gebiets bewachen sie den Zugang erbittert und zermalmen alle Abenteurer, die sich zu nah an die südlichen Klippen heranwagen.",al={"warum gibt es dünenzertrümmerer","talriesen","berggiganten tanaris"}},{q="Wo in Tanaris liegt dieses Tal?",a="Das Tal liegt am äußersten südlichen Rand von Tanaris, südlich vom Disteltal und den klaffenden Klüften des Südmeers, direkt in die hoch aufragende südliche Gebirgswand gehauen.",al={"tal der behüter lage","wie man das tal der behüter findet","wo ist das tor"}}},fp="22,298,20.543.0,40.246.0,32.171.0,42.217.0,40.191.0"}
P.entries["subzone:valley-of-trials"] = {n="Das Tal der Prüfungen",s="Versteckt hinter den zerklüfteten roten Klippen des südlichen Durotar dient das Tal der Prüfungen als Übungsgelände für neue Rekruten der Horde. Junge Orcs und ihre Verbündeten von den Dunkelspeeren kommen hierher, um ihre Stärke zu beweisen und sich ihren Platz unter den Kriegern von Kalimdor zu verdienen. Diejenigen, die die raue Tierwelt und die verborgenen Gefahren des Tals überleben, brechen auf, bereit, ihre junge Nation zu verteidigen.",h="Versteckt hinter den zerklüfteten roten Klippen des südlichen Durotar dient das Tal der Prüfungen als...",kw={"koven der brennenden klinge","durotar","gornek","orcs","peons","sarkoth","der bau","das tal der prüfungen"},ang={["race:Orc"]="Das Tal stellt für jeden jungen Orc, der nach Ehre strebt, ein Initiationsritual dar, das die Kriegertraditionen von Draenor in einer neu geschmiedeten Heimat widerspiegelt.",["race:Troll"]="Nachdem sie ihre Heimat auf den Echoinseln an Zalazane verloren haben, trainieren die Dunkelspeere an der Seite ihrer orcischen Verbündeten in dieser Schlucht, um sich ihren Platz in der Horde zu verdienen."},sec={{t="Ein Schmelztiegel aus Sand und Stein",b="Das Tal der Prüfungen ist darauf ausgelegt, die Schwachen auszusortieren, bevor sie jemals einen Fuß in die weiteren Weiten von Durotar setzen. Beaufsichtigt von Häuptlingen und Ausbildern, die in der in den Fels gehauenen Zuflucht namens Der Bau stationiert sind, werden junge Kämpfer in die sonnenverbrannte Schlucht geschickt, um Skorpiden zu jagen, aggressive Eber zu dezimieren und faule Peons beim Holzsammeln zur Disziplin anzuhalten. Die Prüfung ist kompromisslos: Wer seinen Mut beweist, verdient sich das Recht, als wahrer Soldat der Horde weiterzuziehen, während die Gescheiterten unter der Wüstensonne verbleichen."},{t="Der Schatten im Norden",b="Was einst ein abgeschiedener Trainingsort war, hat vor Kurzem eine weitaus finsterere Note erhalten. In den natürlichen Höhlen entlang der nördlichen Klippen haben sich Kultisten der Burning Blade eingenistet, die niedere dämonische Vertraute in das Tal beschwören. Während die Ausbilder diese Eindringlinge als lebende Zielübungen für frische Rekruten nutzen, nährt die Anwesenheit von Teufelsmagie so nah an Orgrimmars Schwelle düstere Gerüchte, dass der Schattenrat aktiv versucht, seine Klauen erneut in das Volk der Orcs zu schlagen."}},faq={{q="Was ist der Zweck des Tals der Prüfungen?",a="Es ist das traditionelle Prüfungsfeld für Rekruten der Horde, vor allem junge Orcs und Dunkelspeere. In seinen geschützten Schluchten bewältigen neue Abenteurer anspruchsvolle Aufgaben, um ihr kriegerisches Können, ihren Überlebensinstinkt und ihre Loyalität zu beweisen, bevor ihnen erlaubt wird, in das restliche Durotar aufzubrechen.",al={"warum orcs hier sind","was dieser ort ist","zweck tal der prüfungen"}},{q="Was ist Der Bau?",a="Der Bau ist eine in die Klippen gehauene Höhle, etwa in der Mitte des Tals gelegen. Er beherbergt Klassenlehrer, Händler und Aufseher wie Gornek, die neue Rekruten anleiten, ausrüsten und ihren Fortschritt während der anfänglichen Prüfungen überwachen.",al={"der bau","höhle im tal der prüfungen","wer im höhlenbau ist"}},{q="Warum gibt es Dämonen in einem Anfänger-Trainingsgebiet?",a="Kultisten der Burning Blade haben in den nördlichen Höhlen einen geheimen Zirkel errichtet. Obwohl Ausbilder deren schwache Vertraute nutzen, um Rekruten zu prüfen, deutet die Anwesenheit des Kults darauf hin, dass finstere Mächte wie der Schattenrat direkt vor den Toren von Durotar Fuß fassen wollen.",al={"warum dämonen im tal der prüfungen","burning blade in durotar","dämonen nordhöhle"}},{q="Wer ist Sarkoth?",a="Sarkoth ist ein ungewöhnlich großer, giftiger Skorpid, der in den felsigen Höhen des Tals haust. Wegen seiner Aggressivität und Tödlichkeit tragen Ausbilder vielversprechenden Rekruten auf, ihn zur Strecke zu bringen, um ihren Mut auf die Probe zu stellen und seine verstümmelte Klaue als Beweis zurückzubringen.",al={"sarkoth geschichte","riesenskorpid","sarkoth quest"}}},fx={["9914b36c"]={q="Wer hat hier das Sagen?",a="Die Prüfungen und das Training im Tal werden vor Ort von Veteranen der Horde und Klassenlehrern verwaltet. Aufgabenmeister Gornek leitet die Neuankömmlinge an und bewertet ihre Fortschritte. Er stellt sicher, dass jeder Novize der New Horde seinen Wert beweist, bevor er sich in die weiteren Gebiete von Durotar begeben darf.",al={"wer führt das tal der prüfungen","wer leitet das tal der prüfungen","wer ist der boss hier"}},aa4d1f31={q="Wer ist Gornek?",a="Gornek ist ein Orc-Aufgabenmeister, der direkt vor The Den im Das Tal der Prüfungen stationiert ist. Er überwacht Rekruten ab dem Moment ihrer Meldung zum Dienst. Er stellt grundlegende Prüfungen, um Euren Mut zu testen, lässt wilde Bestien erlegen und schickt bewährte Krieger und Zauberwirker zu ihren jeweiligen Ausbildern.",al={"gornek","wer ist gornek","was macht gornek"}},["4fde55c9"]={q="Was ist die New Horde?",a="Die New Horde ist ein Bündnis unterschiedlicher Kulturen, das von Kriegshäuptling Thrall auf den Prinzipien des Überlebens, der Ehre und der Freiheit gegründet wurde. Verbunden durch ein Bündnis gegenseitigen Schutzes in einer feindseligen Welt, ist sie auf die Orcs zentriert, denen sich Verbündete wie die Dunkelspeertrolle und die Tauren angeschlossen haben. Sie ist dem Ziel gewidmet, eine Zukunft frei von dämonischer Verderbnis aufzubauen.",al={"new horde","was ist die horde","thralls horde"}},["3a67b133"]={q="Warum leben Orcs jetzt in einer Wüste?",a="Nachdem Thrall der menschlichen Gefangenschaft in den Östliche Königreiche entkommen war und Das große Meer überquert hatte, brachte er die Orcs nach Kalimdor, um ein eigenes Land zu beanspruchen. Durotars rissiger, roter Boden, die zerklüfteten Schluchten und die trockene Hitze erinnern die Orcs an ihre alte Heimatwelt Draenor und bieten eine raue Schönheit, in der ihre Stärke fortdauern kann.",al={"warum durotar","warum sind orcs in der wüste","warum ließen sich orcs in durotar nieder"}},e4c91867={q="Warum fängt mein Troll in einem Orc-Lager an?",a="Der Stamm der Dunkelspeere verdankt sein Überleben Thrall, der half, sie zu retten, als ihre Heimatinsel während des Exodus nach Kalimdor verloren ging. Verbunden durch Dankbarkeit und Freundschaft, trainieren junge Dunkelspeertrolle Seite an Seite mit Orc-Rekruten im Das Tal der Prüfungen, um ihre gemeinsame Loyalität zur Horde zu beweisen.",al={"warum starten trolle im tal der prüfungen","startgebiet der trolle","warum sind trolle bei den orcs"}},["3629ab9f"]={q="Was ist mit dem Stamm der Dunkelspeere passiert?",a="Nachdem sie nach Kämpfen gegen Murlocs und eine Seehexe von ihren angestammten Inseln im Das große Meer vertrieben wurden, folgten die Dunkelspeere Thrall nach Kalimdor und besiedelten die Die Echoinseln vor der Küste von Durotar. Die Treulosigkeit des Hexendoktors Zalazane und Angriffe menschlicher Truppen vertrieben sie jedoch von den Inseln und zwangen sie auf das Festland von Durotar zum Sen'jin.",al={"darkspear geschichte","was ist mit den darkspear passiert","darkspear echoinseln"}},["9ca718af"]={q="Wer ist die Burning Blade?",a="Die Burning Blade ist ein dunkler Kult, der mit dämonischer Verderbnis und den Einflüsterungen des tückischen Schattenrats in Verbindung gebracht wird. Anstatt unter Thralls Horde nach Ehre zu streben, handeln ihre Hexenmeister und Anhänger mit Teufelsmächten und hegen finstere Pläne gegen die Sicherheit von Durotar.",al={"burning blade","wer ist die burning blade","kult der burning blade"}},d2b83034={q="Warum ist die Burning Blade im Tal?",a="Mitglieder des Kults haben sich heimlich in das natürliche Höhlensystem entlang der nördlichen Klippen des Tals zurückgezogen, das nun als Koven der Brennenden Klinge bekannt ist. Unter der Führung des Hexenmeister Yarrog Baneshadow sorgt ihre Anwesenheit dafür, dass dämonische Wichtel in das Trainingsgelände eindringen und die Rekruten auf die Probe stellen, die die Verderbnis ausmerzen müssen, bevor sie abreisen.",al={"warum ist die burning blade hier","burning blade im tal der prüfungen","warum sind sie im koven"}},["3ff6b15f"]={q="Was ist Sen'jin und warum werde ich dorthin geschickt?",a="Sen'jin ist eine Siedlung der Dunkelspeertrolle, die entlang der Südküste von Durotar am Strand der Dunkelspeere errichtet wurde. Gegründet von Vol'jin, nachdem Zalazane die Die Echoinseln besetzt hatte, dient sie als Stützpunkt des Stammes und als Euer natürliches Ziel, sobald Ihr Euch als würdig erwiesen habt, das Das Tal der Prüfungen zu verlassen.",al={"sen'jin","warum zum sen'jin","was ist senjin"}},b9026890={q="Wie bin ich im Das Tal der Prüfungen gelandet?",a="Ihr seid hier angekommen, um Euch selbst zu prüfen. Versteckt in den südlichen Felsen von Durotar dient das Das Tal der Prüfungen als Übungsgelände für neue Rekruten der Horde. Ob aus Pflichtgefühl, Stammes-Tradition oder dem rohen Drang, für Euer Volk zu kämpfen – alle, die Thralls Reich dienen wollen, müssen zuerst diese trockene Schlucht durchqueren. Ihr seid zu Fuß gekommen und habt Euch bei den Anwerbern und Aufgabenmeistern von The Den gemeldet, um Eure Initiation zu beginnen.",al={"wie bin ich hierher gekommen","wie bin ich hier gelandet","warum bin ich hier aufgewacht"}},f72f3f76={q="Was soll ich im Das Tal der Prüfungen tun?",a="Ihr seid hier, um Eure Stärke zu beweisen und Euren Platz in der Horde zu verdienen. Unter der sengenden Sonne verlangen Aufgabenmeister Gornek und die Mentoren des Tals, dass Ihr Euch abhärtet, indem Ihr einheimische Bestien erschlagt, wichtige Vorräte sammelt und Euer Kampfgeschick schärft. Als letzte Herausforderung müsst Ihr Euch der wachsenden Verderbnis stellen, die in den nördlichen Höhlen braut. Sobald Eure Ausbilder Euch für fähig halten, die Gefahren von Durotar zu überleben, dürft Ihr das nördliche Tor passieren und tiefer in die wilden Länder jenseits reisen.",al={"was soll ich hier tun","was mache ich hier","warum bin ich hier"}},["5263efa6"]={q="Warum fängt ein neuer Orc hier, im Das Tal der Prüfungen, an?",a="Für einen Orc ist das Kommen in das Das Tal der Prüfungen ein wesentlicher Initiationsritus. In dieser neuen Heimat, die Thrall aus dem Staub schuf und nach seinem Vater, Durotan, benannte, leben alte Traditionen in neuer Form weiter. Jeder aufstrebende Orc muss diese Prüfungen durchlaufen, um Ehre, Disziplin und Kampfbereitschaft zu zeigen, bevor er sich den Grunzern anschließen kann, die Orgrimmar bewachen, oder die Grenzen durchstreifen darf. Ihr wurdet hierher geschickt, um zu beweisen, dass Ihr den Geist besitzt, der zur Verteidigung der New Horde erforderlich ist.",al={"warum starten orcs hier","warum sind orcs im tal","warum starte ich als orc im tal der prüfungen"}},["576a24aa"]={q="Warum fängt ein neuer Troll hier, im Das Tal der Prüfungen, an?",a="Euer Volk, der Stamm der Dunkelspeere, hat kürzlich einen bitteren Verrat erlebt. Von Eurer Heimat auf den Die Echoinseln durch den Verräter Zalazane und seine verfluchten Schergen vertrieben, versammelten sich die Überlebenden entlang der Küste bei Sen'jin. Da Ihr keine eigenen Übungsgelände habt, verlässt sich Euer Häuptling Vol'jin auf sein Bündnis mit Thrall und schickt eifrige Dunkelspeerjugendliche zusammen mit den Orcs hierher in Durotars Tal. Indem Ihr Eure Stärke in dieser rauen Schlucht beweist, bereitet Ihr Euch darauf vor, der Horde zu dienen und schließlich zu helfen, Eure Heimat zurückzuerobern.",al={"warum starten trolle hier","warum ist ein troll in einem orc-lager","warum bin ich als troll hier"}},["7f52c0d9"]={q="Was ist Das Tal der Prüfungen?",a="Das Tal der Prüfungen ist ein raues, von Schluchten geschütztes Übungsgelände im südlichen Durotar. Umgeben von hoch aufragenden roten Klippen dient es als unverzichtbarer Prüfstein für junge Orcs und Dunkelspeere, die ihren Platz in der Horde finden wollen. Hier ertragen Rekruten Prüfungen des Kampfes, des Überlebens und der Disziplin unter der harten Sonne und den schroffen Felsen, bevor sie über die Talwände hinaus in die weite Welt treten.",al={"wo bin ich","was ist das für ein ort","lore des tal der prüfungen"}},["341e719f"]={q="Warum heißt es Das Tal der Prüfungen?",a="Es hat seinen Namen von den strengen Initiationsriten, die innerhalb seiner Wände abgehalten werden. Jeder aufstrebende Rekrut muss seine Stärke, Entschlossenheit und Loyalität gegenüber der Horde beweisen, indem er gefährliche Prüfungen gegen die Bestien und Bedrohungen des Landes besteht. Diejenigen, die sich als würdig erweisen, erhalten die Erlaubnis, nach Durotar hinauszuziehen; diejenigen, die scheitern und bei dem Versuch fallen, bleiben in der sengenden Wüstensonne liegen.",al={"warum tal der prüfungen","bedeutung des namens tal der prüfungen","warum heißt es tal der prüfungen"}},["5bae7ae4"]={q="Ist Das Tal der Prüfungen Teil von Durotar?",a="Ja, es liegt in den südlichen Ausläufern von Durotar. Durotar selbst ist ein trockenes, felsiges Reich an der Ostküste von Kalimdor, das von Thrall zum Gedenken an seinen Vater Durotan gegründet und benannt wurde. Das Tal der Prüfungen ist das geschützte Bereitstellungsgelände, auf dem sich Rekruten vorbereiten, bevor sie die raueren Wildnisse des weiteren Gebiets betreten.",al={"ist das in durotar","ist das tal der prüfungen teil von durotar","tal der prüfungen durotar"}}},fp="16,385,28.558.0,23.490.1,44.300.0,16.231.0,53.276.0,15.251.0"}
P.entries["subzone:valor-s-rest"] = {n="Heldenwacht",s="Heldenwacht ist ein kleiner Außenposten und Friedhof an der östlichen Schwelle von Silithus. Bewacht von Mitgliedern des Zirkels des Cenarius, ist es der erste Zufluchtsort für Reisende, die aus dem Krater von Un'Goro in die windgepeitschte Einöde treten.",h="Heldenwacht ist ein kleiner Außenposten und Friedhof an der östlichen Schwelle von Silithus.",kw={"lager","zirkel des cenarius","friedhof","silithus","krater von un'goro","heldenwacht"},ang={["class:Druid"]="Als Außenposten, der vom Zirkel des Cenarius unterhalten wird, verkörpert Heldenwacht die aufmerksame Wacht Eures Ordens über die unheilvollen Regungen in der südlichen Wüste.",["faction:Alliance"]="Obwohl klein und unter cenarischer Neutralität mit der Horde geteilt, bietet Heldenwacht eine willkommene erste Zuflucht, sobald Ihr aus der Wildnis von Un'Goro heraustretet."},sec={{t="Tor zu den Dünen",b="Gelegen an der östlichen Grenze von Silithus entlang der Rampe, die vom Krater von Un'Goro herabführt, dient Heldenwacht als Schwelle zu dieser trostlosen Grenzregion. Als neutraler Stützpunkt vom Zirkel des Cenarius unterhalten, beherbergt das Lager Mitglieder sowohl der Allianz als auch der Horde, die es wagen, den trockenen Weiten zu trotzen. Sein markanter Friedhof dient als düstere Erinnerung an die Gefahren, die in der gesamten Wüste lauern, wo insektoide Schrecken und uralte Bedrohungen selbst die abgehärtetsten Expeditionen auf die Probe stellen."}},faq={{q="Wo befindet sich Heldenwacht?",a="Heldenwacht befindet sich am östlichen Eingang von Silithus. Es ist die allererste Siedlung, auf die man stößt, wenn man dem Pfad folgt, der aus der nordwestlichen Ecke des Un'Goro-Kraters hinauf in die Wüste führt.",al={"heldenwacht standort","heldenwacht finden","wo ist heldenwacht"}},{q="Wer kontrolliert Heldenwacht?",a="Der Außenposten wird vom Zirkel des Cenarius unterhalten. Als neutrale Hüter, die die Region erforschen und bewachen, gestatten sie sowohl Reisenden der Allianz als auch der Horde, das Lager zu nutzen.",al={"wer leitet heldenwacht","heldenwacht fraktion","zirkel des cenarius lager silithus"}},{q="Was ist das bemerkenswerte Merkmal dieses Lagers?",a="Das auffälligste Merkmal von Heldenwacht ist sein Friedhof, der die Gräber jener markiert, die von der unbarmherzigen Wüste und ihren vordringenden insektoiden Bewohnern dahingerafft wurden.",al={"heldenwacht friedhof","was gibt es in heldenwacht"}},{q="Ist Heldenwacht vor der umliegenden Tierwelt sicher?",a="Obwohl es als Außenposten fungiert, leidet die unmittelbare Umgebung des Lagers unter bekannten Insektenplagen, was als frühe Vorwarnung vor dem Schwarm dient, der tiefer in Silithus lauert.",al={"heldenwacht sicher","wird heldenwacht angegriffen"}}},fp="12,240,20.489.0,30.203.0,26.171.0,41.165.0,51.188.0"}
P.entries["subzone:valormok"] = {n="Valormok",s="Valormok ist ein abgelegener Außenposten der Horde, der in den zerklüfteten nordwestlichen Weiten von Azshara errichtet wurde. Nördlich des Lagers der Haldarr gelegen, dient diese windgepeitschte Siedlung als Aufmarschgebiet für Kundschafter und Abenteurer, die den verfluchten, uralten Ruinen der Küste trotzen.",h="Valormok ist ein abgelegener Außenposten der Horde, der in den zerklüfteten nordwestlichen Weiten von Azshara...",kw={"ag'tor bloodfist","azshara","belgrom rockmaul","flugmeister","jediga","magus rimtori","valormok"},ang={["faction:Horde"]="Valormok ist die wichtigste Zuflucht für Horde-Abenteurer, die Azsharas tückische Ruinen erkunden, und bietet Flugmeister sowie Rachemissionen.",["race:Orc"]="Der Außenposten stellt einen harten Test der Ausdauer für Orcs dar, die weit entfernt von Orgrimmar stationiert und durch Ehre gebunden sind, ihre verratenen Brüder zu rächen."},sec={{t="Ein unsicherer Vorposten",b="Inmitten der herbstlich gefärbten Bäume von Azshara gelegen, verkörpert Valormok das vorsichtige Interesse der Horde an einem feindseligen und weitgehend verlassenen Territorium. Das Leben hier ist karg und voller Gefahren; das Lager ist nur leicht befestigt und ständig den nahen Satyren, Nagas und umherstreifenden Bestien ausgesetzt. Trotz dieser Entbehrungen halten die dort stationierten Krieger die Stellung und fungieren als entscheidender Flugknotenpunkt und vorgeschobenes Bollwerk, das Orgrimmar mit den wilderen Gebieten des nördlichen Kalimdor verbindet."},{t="Verrat und Vergeltung",b="Das Lager wurde kürzlich von einem verheerenden Verrat erschüttert. Belgrom Rockmaul entsandte ursprünglich Krieger der Horde an der Seite einer Blutelfe namens Magus Rimtori, um in den Ruinen alte Schätze und mächtige Relikte zu bergen. Rimtori wandte sich jedoch gegen ihre Eskorte und schlachtete die Krieger ab, um die Artefakte für sich selbst zu beanspruchen. Unter der Führung von Ag'tor Bloodfist schmieden die Überlebenden in Valormok nun Rachepläne gegen Rimtori und ihre Gefolgschaft, die sich im nahe gelegenen Thalassischen Stützpunkt verschanzt haben."}},faq={{q="Was ist Valormok?",a="Valormok ist eine isolierte Siedlung der Horde im Nordwesten von Azshara. Sie bietet eine lebenswichtige Flugmeisterverbindung und dient Reisenden der Horde als Operationsbasis bei der Erkundung der uralten Wildnis an der Küste.",al={"valormok azshara","was ist dieses lager","horde-basis in azshara"}},{q="Wer leitet das Lager?",a="Der Außenposten wird von Ag'tor Bloodfist beaufsichtigt, einem Orc-Krieger, der damit betraut ist, den Stützpunkt der Horde zu halten und Rache für seine gefallenen Kameraden zu üben.",al={"wer hat das kommando","anführer von valormok","agtor bloodfist"}},{q="Warum wurden hier so viele Krieger der Horde getötet?",a="Belgrom Rockmaul hatte Krieger entsandt, um die Blutelfe Magus Rimtori bei der Suche nach Relikten zu eskortieren. Rimtori verriet und massakrierte ihre Eskorte, um die Macht und den Reichtum von Azshara für sich allein zu horten, was die Garnison schwer dezimiert zurückließ.",al={"was geschah mit den wachen","massaker von valormok","rimtoris verrat"}},{q="Wohin führt die Verbindung des Flugmeisters?",a="Valormoks Windreitermeister bietet direkte Flugverbindungen durch ganz Kalimdor, darunter Routen nach Orgrimmar, Donnerfels, Das Wegekreuz, zum Splitterholzposten, zum Blutgiftposten und nach Ewige Warte.",al={"flugpunkte valormok","wohin fliegen ab valormok"}}},fp="8,262,21.473.0,25.457.1,17.213.0,25.151.0,44.241.0,40.190.0"}
P.entries["subzone:vault-of-ironforge"] = {n="Tresor von Eisenschmiede",s="Der Tresor von Eisenschmiede ist das wichtigste Bankhaus und Schatzlager der Zwergenhauptstadt. Gelegen im geschäftigen Commons direkt gegenüber dem Auktionshaus, dient er als zentraler Knotenpunkt, an dem Bürger und Reisende aus der gesamten Allianz ihren Wohlstand sicher aufbewahren. Der Betrieb des Tresors wird von Dinita und der angesehenen Familie Stonemantle beaufsichtigt.",h="Der Tresor von Eisenschmiede ist das wichtigste Bankhaus und Schatzlager der Zwergenhauptstadt.",kw={"dinita","eisenschmiede","bank von eisenschmiede","stonemantle","die commons","tresor von eisenschmiede"},ang={["faction:Alliance"]="Direkt gegenüber dem Auktionshaus der Stadt gelegen, dient der Tresor als Eckpfeiler des Allianzhandels und sorgt dafür, dass Abenteurer gut finanziert und versorgt bleiben.",["race:Dwarf"]="Für Zwerge ist der Tresor eine Angelegenheit des Bergstolzes und steht für unerschütterliche Sicherheit sowie einen dauerhaften Ruf bei der Wahrung zwergischen Reichtums."},sec={{t="Herz des Zwergenhandels",b="Tief in den Fels der Commons gehauen, steht der Tresor von Eisenschmiede als Symbol für zwergische finanzielle Sicherheit und Handwerkskunst. Da der Handel der Stadt floriert, versammeln sich hier täglich Reisende, Soldaten und Händler, um unter den wachsamen Augen der Stadtwachen und Kassierer Münzen, Relikte und Vorräte zu hinterlegen. Beaufsichtigt von Dinita und der vertrauenswürdigen Familie Stonemantle bietet die Institution Besuchern der Allianz absolute Seelenruhe."}},faq={{q="Wofür wird der Tresor von Eisenschmiede genutzt?",a="Der Tresor dient als Zentralbank und Schließfachlager für die Stadt Eisenschmiede. Bürger und Reisende der Allianz verlassen sich auf ihn, um ihr Gold, ihre Ausrüstung und ihre geschätzten Besitztümer innerhalb der schweren Steinmauern des Berges sicher aufzubewahren.",al={"zweck des tresors","bank von eisenschmiede","was ist dieser ort"}},{q="Wer betreibt die Bank?",a="Die Einrichtung wird von Dinita zusammen mit Mitgliedern der Familie Stonemantle geführt, welche Einzahlungen, Transaktionen und die Lagerung für Besucher verwalten.",al={"bankiers","wer leitet den tresor","familie stonemantle"}},{q="Wo befindet sich der Tresor?",a="Ihr könnt ihn direkt im Viertel the Commons von Eisenschmiede finden, direkt gegenüber dem Platz vom geschäftigen Auktionshaus der Stadt.",al={"standort des tresors","wo ist die bank von eisenschmiede","wie man den tresor findet"}}},fx={["84f84a05"]={q="Was ist der Tresor von Eisenschmiede?",a="Der Tresor von Eisenschmiede dient als zentrale Bank und primäres Schatzhaus für die Hauptstadt der Zwerge. Direkt gegenüber dem belebten Auktionshaus in den Commons gelegen, bietet es sichere Lagerung für Reisende, Händler und Champions der Allianz, die einen vertrauenswürdigen Zufluchtsort für ihre hart verdienten Wertsachen suchen.",al={"was ist der tresor von eisenschmiede","lore der bank von eisenschmiede","tresor von eisenschmiede"}},["45fc2a88"]={q="Ist der Tresor von Eisenschmiede gefährlich?",a="Für Reisende der Allianz überhaupt nicht. Der Tresor liegt sicher im Herzen des Stadtviertels Commons, ist schwer bewacht und wird von der vollen Macht der Stadtwache von Eisenschmiede geschützt. Sofern es feindlichen Kräften der Horde nicht gelingt, einen dreisten Überfall direkt in den Berg selbst durchzuführen, bleibt er eine der sichersten Einrichtungen im Reich.",al={"ist der tresor von eisenschmiede sicher","gefahr bank von eisenschmiede","tresor sicher"}},ef86fb6b={q="Warum heißt es Tresor von Eisenschmiede?",a="Er hat seinen Namen von seiner Funktion und seiner festungsartigen Bauweise. Als große Schatzkammer der Stadt erbaut, ist diese höhlenartige Halle verstärkt, um Reichtümer und Relikte unter dem massiven Gestein des Berges zu sichern, was ihn zum definitiven Tresor der Zwergennation macht.",al={"warum heißt es tresor","namensherkunft tresor von eisenschmiede","name tresor von eisenschmiede"}}},fp="18,358,25.425.0,40.231.0,22.142.0,27.130.0"}
P.entries["subzone:venomweb-vale"] = {fx={c3248b05={q="Was ist das Giftwebertal?",a="Das Giftwebertal ist ein weites, verheertes Tal in den östlichen Tirisfal, das südlich von Das Scharlachrote Kloster liegt. Einst ein üppiger Wald voller Rehe und Kaninchen, ist es zu einer trüben, vergifteten Senke verfallen, die von aggressiven Spinnentieren und streunenden Bestien überlaufen ist, flankiert von wachsamen Patrouillen der The Scarlet Crusade.",al={"was ist das giftwebertal","info zum giftwebertal","erzähl mir vom giftwebertal"}},["266d3ee0"]={q="Wer lebt im Giftwebertal?",a="Keine zivilisierten Völker wohnen im Herzen des Tals. Es wird vollständig von giftigen Spinnen unter der Brutmutter Sri'skulk sowie umherstreifenden dunklen Hunden beherrscht. Gegen den nördlichen Rand des Tals unterhält die The Scarlet Crusade einen bewaffneten Außenposten unter Leutnant Sanders, der als Scharlachrotes Lager bekannt ist.",al={"wer lebt im giftwebertal","bewohner des giftwebertals","wer kontrolliert das giftwebertal"}},f71a1b3a={q="Ist das Giftwebertal gefährlich?",a="Ja, es ist außergewöhnlich gefährlich für unachtsame Reisende. Tödliche, giftige Spinnen nisten in den verdorbenen Bäumen des Tals und lauern ihrer Beute im Schatten von Sri'skulk auf. Außerdem streifen aggressive Dunkelhunde am nördlichen Rand umher, wo Eiferer der The Scarlet Crusade jeden gewaltsam angreifen, der sich ihrem Lager nähert.",al={"ist das giftwebertal gefährlich","gefahren im giftwebertal","bedrohungen im giftwebertal"}},["7b7f7008"]={q="Warum heißt es Giftwebertal?",a="Das Tal erhielt seinen düsteren Namen aufgrund der dichten, giftigen Netze, die die riesigen Spinnen, welche die Senke befallen, in die Bäume spannen. Einst ein unbenannter Zufluchtsort im Wald, begannen Reisende und Einheimische es Giftwebertal zu nennen, nachdem die tödlichen Spinnentiere das gesamte Becken für sich beansprucht hatten.",al={"warum heißt es giftwebertal","bedeutung des namens giftwebertal","wie kam das giftwebertal zu seinem namen"}}}}
P.entries["subzone:venture-co-base-camp"] = {n="Stützpunkt der Venture Co.",s="Versteckt in den dichten Dschungeln des nördlichen Schlingendorntals dient der Stützpunkt der Venture Co. als Vorposten für das berüchtigt gierige Goblinsyndikat. Hier beuten angeheuerte Vorarbeiter und Tagelöhner die üppige Wildnis aus, wobei sie ihre Bemühungen auf das Holzschlagen, das Jagen der heimischen Tierwelt und das Fördern wertvoller getrommelter Kristalle aus den nahegelegenen Wasserläufen konzentrieren.",h="Versteckt in den dichten Dschungeln des nördlichen Schlingendorntals dient der Stützpunkt der Venture Co.",kw={"goblinholz","operations center","schlingendorntal","getrommelte kristalle","venture co base camp","venture company"},ang={["class:Druid"]="Die Venture Company verkörpert hemmungslose industrielle Zerstörung, indem sie unberührte Dschungelhabitate verwüstet und das örtliche Gleichgewicht der Natur für plumpe mechanische Machenschaften stört.",["profession:Mining"]="Das Lager dient als industrieller Knotenpunkt für die Erkundung des Dschungels, an dem Goldsucher des Unternehmens nach Rohstoffen und seltenen getrommelten Kristallen suchen."},sec={{t="Industrielle Übergriffe",b="Die Venture Company ist in ganz Azeroth für ihre rücksichtslose Profitgier und ihre völlige Missachtung der Natur berüchtigt. In diesem Dschungel-Basislager fressen sich dampfbetriebene Gerätschaften und provisorische Goblinhütten in das uralte Blätterdach. Bewacht von bewaffneten Söldnern, Vorarbeitern und Feldarbeitern koordiniert das Lager den Ressourcenabbau in den umliegenden Tälern, wobei ein besonderes Augenmerk auf die wertvollen, in der Nähe gefundenen getrommelten Kristalle gelegt wird, während jeglicher Dschungel gerodet wird, der ihnen im Weg steht."}},faq={{q="Was tut die Venture Company im Schlingendorntal?",a="Die Venture Company agiert als opportunistisches Syndikat für Bergbau, Holzfällerei und Ingenieurskunst. Im nördlichen Schlingendorntal haben sie ihr Lager aufgeschlagen, um den dichten Dschungel abzuholzen, schwere Förderanlagen zu errichten und wertvolle Mineralvorkommen abzubauen – allen voran die getrommelten Kristalle, die an den örtlichen Wasserläufen vorkommen.",al={"warum sind hier goblins","venture co zweck","venture company schlingendorntal"}},{q="Gehören die hiesigen Goblins zum Steamwheedle-Kartell in Beutebucht?",a="Nein. Die Venture Company ist ein eigenständiges, räuberisches Unternehmen, das vollkommen getrennt von Baron Revilgaz und dem Steamwheedle-Kartell agiert. Anders als die Handelsprinzen von Beutebucht, die lukrative Handelsbeziehungen pflegen, setzt die Venture Company auf schonungslose Ausbeutung und verhält sich nahezu jedem gegenüber feindselig, der ihrem Profit in die Quere kommt.",al={"gehört venture co zu beutebucht","sind sie beutebucht freundlich gesinnt","venture co steamwheedle"}},{q="Was liegt jenseits des Basislagers?",a="Neben dem Basislager liegt die Arbeitszentrale der Venture Co., ein tiefer befestigter Außenposten, der schwere Holzfällerapparaturen, Holzvorräte und höherrangige Unternehmensleiter beherbergt, welche die regionalen Kahlschlagarbeiten leiten.",al={"wohin führt dieses lager","was liegt neben dem basislager","venture co operations center"}}},fp="21,365,23.487.0,56.301.0,74.338.0,31.230.0"}
P.entries["subzone:venture-co-mine"] = {n="Die Mine der Venture Co.",s="Eingebettet in die östlichen Klippen von Mulgore ist die Mine der Venture Co. eine unbefugte industrielle Ausgrabungsstätte, die von gierigen Goblin-Opportunisten betrieben wird. Obwohl die Tauren ihnen die Schürfrechte verweigerten, grub sich die Venture Company dennoch in die Hügel und bedroht damit das natürliche Gleichgewicht der Ebenen.",h="Eingebettet in die östlichen Klippen von Mulgore ist die Mine der Venture Co.",kw={"fizsprocket","goblins","mulgore","überfallene karawane","razdunk","schredder","stonebullsee","mine der venture co."},ang={["profession:Engineering"]="Hinter den Minentunneln und jenseits der höher gelegenen Holzfällerlichtung lauert Twizwick Sprocketgrind, ein Tüftler, der bereit ist, mechanische Betriebsgeheimnisse fernab neugieriger Firmenaugen zu teilen.",["race:Tauren"]="Die Mine ist eine schwere Beleidigung für die Erdenmutter, da sie Ruß, Lärm und rücksichtslose Narben in die uralten Täler bringt, zu deren Schutz sich die Stämme verpflichtet haben."},sec={{t="Unerwünschte Industrie",b="Als die Venture Company Rechte erwerben wollte, um Mulgores Bodenschätze abzubauen, lehnten die Tauren dies entschieden ab. Das Unternehmenskartell ignorierte sie jedoch und grub sich unter der Leitung von Vorsteher Zischelspross tief in die östliche Bergwand. Ihr weitläufiger Komplex verfügt über drei Eingänge – einen ebenerdigen Tunnel, der von angeheuerten Schlägern bewacht wird, einen steilen Klippenausguck und einen oberen Durchgang, der zu einem kleinen Holzfällerlager führt. Die vordringenden Maschinen, der Rauch und die Schlackenhaufen stellen eine eklatante Entweihung des heiligen Landes dar."},{t="Wachsende Ambitionen",b="Der Bergbau war für das Kartell nur der Anfang. Interne Dokumente belegen, dass Mogul Razdunk und der Vorstand der Venture Company Fizsprocket ermutigten, das Geschäft auf großflächigen Holzeinschlag auszuweiten, und ihm dafür fortschrittliche Goblin-Schredder versprachen, um die sanften Hügel kahlzuschlagen. Obwohl Vorpostenläufer der Tauren nahe dem Stonebullsee eine Versorgungskarawane des Konzerns angriffen und niederbrannten, um deren Expansion aufzuhalten, wurden umgehend Berger entsandt, um die Fracht zu bergen. Um die Zerstörung zu stoppen, haben die Stämme nun zu direkten Vergeltungsmaßnahmen gegen die Aufseher der Mine gegriffen."}},faq={{q="Warum schürfen Goblins in Mulgore?",a="Die Venture Company ersuchte um die Erlaubnis, in Mulgore Mineralien abzubauen, doch die Tauren lehnten ihr Gesuch ab. Da das Kartell weder die Gebietsansprüche der Einheimischen noch das ökologische Gleichgewicht respektieren wollte, schmuggelte es Arbeiter und Maschinen in die östlichen Klippen, um die Hügel unbefugt zu plündern.",al={"warum sind hier goblins","venture co mulgore grund","wer leitet die mine"}},{q="Wer hat die Leitung über diese Abbaustätte?",a="Vorsteher Zischelspross überwacht von seinem Posten im Haupteingang aus alle Operationen der Venture Company in Mulgore. Er empfängt seine Befehle direkt vom Vorstand des Unternehmens und Mogul Razdunk.",al={"minenboss","wer führt die mine","vorsteher zischelspross"}},{q="Was geschah mit der Versorgungskarawane am See?",a="Vorpostenläufer der Tauren lauerten einer Versorgungskarawane der Venture Company nahe dem Nordufer des Stonebullsees auf und steckten sie in Brand, um zu verhindern, dass Maschinen die Mine erreichen. Die Goblins entsandten rasch Bergungsteams, um die verkohlten Trümmer zu durchsuchen und ihre Waren zu retten.",al={"überfallene karawane geschichte","stonebullsee karawane","wer verbrannte die karawane"}},{q="Was planen die Goblins hier sonst noch zu bauen?",a="Über das Aushöhlen der Klippen nach Erz hinaus enthüllen interne Mitteilungen Pläne zur Errichtung eines Sägewerks und zum Einsatz von Schreddern, um Mulgores Bäume für zusätzlichen Unternehmensgewinn kahlzuschlagen.",al={"venture co pläne","goblin-schredder mulgore","holzfällerlager pläne"}}},fx={["082f8142"]={q="Was ist die Mine der Venture Company?",a="Dies ist eine riesige Ausgrabung, die tief in die östlichen Klippen von Mulgore gegraben wurde. Ohne Genehmigung von der Venture Company errichtet, dient sie als illegaler industrieller Stützpunkt im Heimatland der Tauren. Das Gelände verfügt über einen Haupteingang, der von Goblin-Aufsehern überwacht wird, hohe Klippenpfade und eine obere Öffnung, die zu einem kleinen Holzfällerbetrieb führt.",al={"mine der venture company","was ist die mine der venture company","mine in mulgore"}},["55edfc51"]={q="Was geschah in der Mine der Venture Company?",a="Nachdem die Tauren der Venture Company die Abbaurechte in Mulgore rundherum verweigert hatten, ignorierte das Kartell sie und begann trotzdem zu graben. Die Späher der Tauren schlugen zurück, indem sie eine große Versorgungskarawane am Stonebullsee überfielen und in Brand steckten. Aufgebracht über die Entweihung ihrer heiligen Ahnenländer, haben die Ältesten des Dorfes der Bluthufe Überfälle auf die Mine organisiert, um die Eindringlinge zu vertreiben.",al={"geschichte der mine der venture company","was ist hier passiert","hintergrundgeschichte zur mine der venture company"}},a93a58cf={q="Ist die Mine der Venture Company gefährlich?",a="Ja. Die Tunnel wimmeln von schwer bewaffneten Goblin-Vollstreckern, Arbeitern und Ingenieuren, die ihren illegalen Anspruch erbittert verteidigen. Die Wachen der Venture Company zögern nicht, Eindringlinge bei Sichtkontakt zu erschießen, und das Navigieren durch die verschlungenen, mehrstöckigen Schächte bringt Euch direkt in das Visier ihrer skrupellosen Belegschaft.",al={"ist die mine der venture company gefährlich","gefahren in der mine der venture company","risiken durch die venture company"}},caf6f18d={q="Warum heißt sie Mine der Venture Company?",a="Sie hat ihren Namen direkt von dem berüchtigten Goblin-Syndikat, das sie betreibt: der Venture Company. Geführt unter der fernen Leitung von Mogul Razdunk, kümmert sich dieses skrupellose Unternehmen nicht um lokale Souveränität oder den Schutz der Umwelt und brandmarkt seine illegale Ausgrabung mit dem Namen der Firma.",al={"warum mine der venture company","bedeutung des namens mine der venture company","name venture company"}}},fp="16,280,17.506.0,19.546.1,34.290.0,37.192.0,48.266.0,44.184.0"}
P.entries["subzone:vice"] = {n="Das Laster",s="Das Laster ist eine zerklüftete, trostlose Weite im Gebirgspass der Totenwinde, gelegen an der Straße, die nach Karazhan führt. Es dient als Territorium der Oger der Totenwinde, die der düsteren Isolation des Landes zum Trotz grobe Hügel und verstreute Lager unterhalten. Reisende, die dieses Gebiet durchqueren, müssen sich sowohl gegen ihre rohe Brutalität als auch gegen ihre überraschend versierten Wirker dunkler Magie behaupten.",h="Das Laster ist eine zerklüftete, trostlose Weite im Gebirgspass der Totenwinde, gelegen an der Straße, die...",kw={"oger der totenwinde","gebirgspass der totenwinde","hexenmeister der totenwinde","karazhan","ogerhügel","das laster"},ang={["class:Mage"]="Die Anwesenheit der Oger direkt auf dem Weg nach Karazhan wirft für die Kirin Tor Fragen darüber auf, ob Restenergien aus Medivhs Turm die örtlichen Bestien und Clans beeinflussen.",["class:Warlock"]="Die Oger der Totenwinde, die das Laster bewohnen, zeigen eine unerwartete Beherrschung dunkler Magie, was darauf hindeutet, dass selbst isolierte, rohe Clans auf verderbliche Teufelsenergien zugreifen können."},sec={{t="Eine trostlose Festung",b="Das Laster erstreckt sich über die südlichen Bereiche des Gebirgspasses der Totenwinde und ist von karger Erde, schroffen Felswänden sowie groben Erdhügeln geprägt, die vom Ogerclan der Totenwinde errichtet wurden. Während die umliegende Schlucht größtenteils rachsüchtigen Geistern und Aasgeiern überlassen ist, haben sich diese Oger direkt neben dem Hauptweg nach Karazhan eine hartnäckige Enklave geschaffen. Warum sie ein derart trostloses und magisch gezeichnetes Ödland wählten, bleibt ein beständiges Rätsel, doch jeder Reisende zwischen dem Dämmerwald und den Sümpfen des Elends stellt rasch fest, dass sie ihre Lager mit unerbittlicher territorialer Gewalt verteidigen."},{t="Rohe Gewalt und dunkle Künste",b="Anders als gewöhnliche Wegelagerer verfügen die im Laster hausenden Oger sowohl über gewaltige körperliche Stärke als auch über gefährliches arkanes Talent. Neben wuchtigen Schlägern praktizieren die Hexenmeister der Totenwinde zwischen den Erdhügeln grobe, doch tödliche Teufelszauber. Ihre Präsenz so nahe dem verlassenen Sitz von Medivh deutet auf einen Hunger nach restlicher magischer Macht hin, was die Schlucht gleichermaßen für umherstreifende Gelehrte wie für einsame Späher zu einem tödlichen Spießrutenlauf macht."}},faq={{q="Was ist das Laster?",a="Das Laster ist ein zerklüftetes Teilgebiet im südlichen Gebirgspass der Totenwinde, geprägt von Erdhügeln, verstreuten Lagerfeuern und felsigen Schluchten, die vollständig von den Ogern der Totenwinde kontrolliert werden.",al={"das laster totenwinde","was ist das laster","das laster gebirgspass der totenwinde"}},{q="Warum leben die Oger hier?",a="Niemand weiß mit Gewissheit, warum die Oger beschlossen haben, sich in einer derart unwirtlichen, heimgesuchten Schlucht niederzulassen. Möglicherweise zieht der verbleibende arkane Niederschlag aus dem nahen Karazhan ihre Hexenmeister an, oder sie nutzen schlicht die abgelegene Bergstraße, um Reisenden aufzulauern.",al={"warum oger in totenwinden","oger totenwinde motiv","warum sind oger im laster"}},{q="Wohin führt die Straße durch das Laster?",a="Der Pfad, der das Laster durchquert, windet sich tiefer in die Klüfte des südlichen Gebirgspasses der Totenwinde und führt geradewegs auf die unheilvollen Tore von Karazhan zu, dem verlassenen Turm des Wächters Medivh.",al={"ziel straße durch das laster","wohin führt der weg","pfad durch das laster"}},{q="Welche Gefahren erwarten Reisende im Laster?",a="Reisende treffen auf aggressive Oger der Totenwinde, die die Straße patrouillieren und ihre Erdhügel verteidigen. Neben körperlich imposanten Raufbolden umfasst der Clan gefährliche Hexenmeister, die Flüche und Schattenmagie wirken.",al={"gefahren im laster","gegner im laster","was greift im laster an"}}},fp="4,362,21.584.0,25.419.0,17.170.0,30.270.0,42.183.0,49.215.0"}
P.entries["subzone:vile-reef"] = {n="Das finstere Riff",s="Das finstere Riff ist eine untergetauchte, farbenfrohe Korallenbank vor der Westküste des Schlingendorntals nahe dem Basislager von Grom'gol. Unter seiner Wasseroberfläche haben aggressive Murlocs inmitten uralter, versunkener Trollruinen, Riesenmuscheln und küstennaher Schiffswracks ihre Heimat gefunden.",h="Das finstere Riff ist eine untergetauchte, farbenfrohe Korallenbank vor der Westküste des Schlingendorntals...",kw={"altar of the tides","blaue perlen","riesenmuscheln","grom'gol","murloc","schlingendorntal","das finstere riff"},ang={["faction:Horde"]="Direkt vor der Küste des Basislagers von Grom'gol gelegen, stellt das Riff eine ständige maritime Bedrohung für die Versorgungsschiffe und Küstenpatrouillen der Horde im Schlingendorntal dar.",["race:Troll"]="Das versunkene Mauerwerk und der uralte Altar of the Tides dienen als düstere Erinnerung an das längst verlorene Küstengebiet, das einst von den Dschungeltrollen beherrscht wurde."},sec={{t="Versunkene Steine und Korallenbänke",b="Unter den Wellen des großen Meeres, direkt vor der Küste des Basislagers von Grom'gol gelegen, ist das finstere Riff für seine farbenprächtige Meeresflora und seine gefährlichen Bewohner bekannt. Der Meeresboden ist übersät mit den verwitterten Steinbauten versunkener Trollruinen sowie dem rätselhaften Altar of the Tides. Schwärme territorialer Murlocs lauern zwischen den Korallenbänken und den zerschellten Holzüberresten vorüberfahrender Schiffe; sie verteidigen die seichten Gewässer erbittert und lauern jedem Taucher auf, der sich auf der Suche nach Riesenmuscheln und seltenen blauen Perlen in die Tiefe wagt."}},faq={{q="Wo befindet sich das finstere Riff?",a="Das finstere Riff liegt im großen Meer vor der Westküste des Schlingendorntals, direkt nordwestlich des Basislagers von Grom'gol.",al={"das finstere riff lage","wo ist das finstere riff","das finstere riff finden"}},{q="Welche Kreaturen bewohnen das finstere Riff?",a="Das Riff wird stark von feindseligen Murlocs heimgesucht, die zwischen den Korallen und versunkenen Strukturen schwimmen, während auf dem Meeresgrund Riesenmuscheln liegen.",al={"das finstere riff mobs","das finstere riff monster","wer lebt im finsteren riff"}},{q="Welche Ruinen befinden sich hier unter Wasser?",a="Auf dem Meeresboden befinden sich die Überreste uralter Trollruinen sowie der Altar of the Tides – Relikte der Trollzivilisation, die vor langer Zeit vom Ozean verschlungen wurden.",al={"das finstere riff ruinen","versunkene ruinen schlingendorntal","altar of the tides ort"}},{q="Warum tauchen Abenteurer in das finstere Riff hinab?",a="Taucher wagen sich in die von Murlocs verseuchten Gewässer, um küstennahe Schiffswracks zu erkunden, den Altar of the Tides zu untersuchen und Riesenmuscheln zu sammeln, die bisweilen wertvolle blaue Perlen bergen.",al={"warum zum finsteren riff reisen","das finstere riff schätze","blaue perlen schlingendorntal"}}},fp="9,250,28.513.0,31.132.0,37.150.0,37.158.0,43.178.0"}
P.entries["subzone:vul-gol-ogre-mound"] = {fx={["40dc9221"]={q="Was ist der Ogerhort Vul'Gol?",a="Der Ogerhort Vul'Gol ist ein tieferliegendes Becken im südlichen Dämmerwald, südwestlich der Gabelung, an der die Straße Richtung Schlingendorntal abbiegt. Einst die Heimat menschlicher Farmer, wurde die Senke besetzt und in eine grobe Festung für die brutalen Oger des Splitterfaustclans verwandelt, komplett mit schlammigen Erdhügeln und einer Höhle voller ihrer grausamen Beute.",al={"was ist der ogerhort vul'gol","informationen zum ogerhort vul'gol","was ist das für ein ort"}},["7dda38fd"]={q="Was geschah mit den Gehöften bei Vul'Gol?",a="Menschliche Siedler bewirtschafteten einst dieses fruchtbare Becken, bevor der Dämmerwald in Schatten fiel und bösartige Bestien eindrangen. Als die Oger des Splitterfaustclans das Gebiet überfielen, wurden die Siedler getötet oder vertrieben und ihre Bauernhäuser blieben als Ruinen zurück. Heute ist das Becken vollständig zu einem Oger-Außenposten korrumpiert, übersät mit Bärenkadavern und Knochen anstatt mit Feldfrüchten.",al={"geschichte von vul'gol","was geschah bei vul'gol","vergangenheit des ogerhorts vul'gol"}},["60de4358"]={q="Ist der Ogerhort Vul'Gol gefährlich?",a="Er ist außergewöhnlich gefährlich. Die Senke wimmelt von aggressiven Ogern des Splitterfaustclans und ihren Vollstreckern, die Reisende bei Sichtkontakt angreifen und umherstreifende Wanderer ausrauben. Zudem haust tief in ihrem Höhlenversteck ihr gerissener Anführer, Zzarc'Vul. Die The Night Watch hält eine Säuberung des Beckens für ihre dünnen Reihen für viel zu kostspielig und verlässt sich stattdessen auf erfahrene Mercenaries, um die Bedrohung zu verringern.",al={"wie gefährlich ist vul'gol","ist vul'gol gefährlich","gefahrenstufe im ogerhort vul'gol"}}}}
P.entries["subzone:wailing-caverns"] = {n="Die Höhlen des Wehklagens",s="Eingebettet in die Klippen über der Blühenden Oase im Brachland sind die Höhlen des Wehklagens ein weit verzweigtes Netz aus unterirdischen Quellen und Höhlen. Ursprünglich vom Nachtelfendruiden Naralex erforscht, um den trockenen Ebenen wieder üppige Vitalität zu verleihen, ist der Komplex stattdessen zu einem verzerrten Hort von Albträumen, mutierten Wildtieren und verderbten Druiden geworden.",h="Eingebettet in die Klippen über der Blühenden Oase im Brachland sind die Höhlen des Wehklagens ein weit...",kw={"brachland","cavern of mists","mutiert","druiden des giftzahns","smaragdgrüner alptraum","die blühende oase","naralex","die höhlen des wehklagens"},ang={["class:Druid"]="Für Druiden sind die Höhlen eine tragische Mahnung an gute Absichten, die durch den Smaragdgrünen Alptraum verdorben wurden, und erfordern, dass Naralex entweder geweckt oder seinen fehlgeleiteten Jüngern Einhalt geboten wird.",["faction:Horde"]="Die verdorbenen Wasser bedrohen die empfindlichen Oasen, die das Leben und Reisen im gesamten Brachland ermöglichen, was die Säuberung der Höhlen zu einer dringenden Angelegenheit für die Sicherheit der nahegelegenen Siedlungen macht."},sec={{t="Der geronnene Traum",b="Die Höhlen verdanken ihren Namen den unheimlichen, klagenden Schreien, die aus Felsspalten dringen, wenn natürliche unterirdische Geysire zu Dampf aufsteigen. Der Nachtelfendruide Naralex wagte sich mit seinen treuen Anhängern in diese tiefen Wasserwege, in der Hoffnung, das unterirdische Netzwerk anzuzapfen und den Smaragdgrünen Traum zu kanalisieren, um die kargen Savannen erblühen zu lassen. Stattdessen wurde Naralex' Bewusstsein im Smaragdgrünen Alptraum gefangen. Die schwärende Verderbnis strömt durch den schlummernden Druiden nach außen, verzerrt die Quellen und verwandelt die einheimischen Bestien in unnatürliche mutierte Schrecken."},{t="Die Druiden des Giftzahns",b="Als Naralex' Schlummer in den Wahnsinn abdriftete, wurden seine engsten Jünger durch den eindringenden Alptraum um den Verstand gebracht. Sie sagten sich von ihren uralten Traditionen los und gründeten unter Anführern wie Lady Anakondra die Druiden des Giftzahns, nahmen giftige Schlangenaspekte an und verteidigten ihren schlafenden Meister vor jedem, der die Trance brechen wollte. Die unterirdischen Wasserwege drohen nun die Oasen im gesamten Brachland zu vergiften, was sowohl besorgte Verbündete des Zirkels des Cenarius in Donnerfels als auch opportunistische Goblins in Ratschet auf den Plan ruft."}},faq={{q="Warum heißen sie die Höhlen des Wehklagens?",a="Die Höhlen sind nach den eindringlichen, klagenden Schreien benannt, die entstehen, wenn unterirdische Dampföffnungen durch enge Risse in der Felsdecke brechen und wie Schmerzensschreie durch die gewaltigen Steinkammern hallen.",al={"warum wehklagen","bedeutung höhlen des wehklagens","warum klagt es"}},{q="Wer ist Naralex und warum schläft er hier?",a="Naralex ist ein Nachtelfendruide, der das Brachland in üppiges Waldland verwandeln wollte, indem er unterirdische Quellen an den Smaragdgrünen Traum anschloss. In seiner Trance wurde er jedoch vom Smaragdgrünen Alptraum überwältigt und wurde zu einem unfreiwilligen Kanal für die Verderbnis.",al={"wer ist naralex","schlafender druide","warum schläft naralex"}},{q="Was sind die Druiden des Giftzahns?",a="Sie sind Naralex' ehemalige Jünger, die durch den Smaragdgrünen Alptraum in den Wahnsinn getrieben wurden, während ihr Meister schlief. Sie nahmen die Aspekte von Schlangen an, verteidigen die verderbte Höhle aktiv und versuchen, ihre verzerrte Vision der Natur über das Land zu verbreiten.",al={"druiden des giftzahns lore","wer sind die giftzahndruiden","schlangendruiden"}},{q="Warum werden die Bestien im Inneren als 'mutiert' bezeichnet?",a="Die Alptraumenergie, die aus Naralex entweicht, hat die Quellen verseucht und gewöhnliche Raptoren, Krokilisken und Vipern in abnorme mutierte Formen verwandelt, die sich durch seltsame Färbungen, gesteigerte Aggression und veränderte Schuppen und Häute auszeichnen.",al={"mutierte bestien","was ist mutiert","warum mutiert"}}},fx={["0897dbe4"]={q="Was sind Die Höhlen des Wehklagens?",a="Die Höhlen des Wehklagens sind ein unterirdisches Netzwerk aus Wasserwegen und Grotten, das sich in der Die blühende Oase im Brachland befindet. Ihre unterirdischen Flüsse speisen die Oasen, die die trockenen Ebenen darüber überziehen. Einst ein Naturwunder aus Nebel und rauschenden unterirdischen Strömungen, sind sie zu einem Epizentrum grassierender Verderbnis geworden, die sich durch das Herz der Savanne ausbreitet.",al={"was sind die höhlen des wehklagens","übersicht zu den höhlen des wehklagens","über die höhlen des wehklagens"}},["2a1640a8"]={q="Was geschah in Die Höhlen des Wehklagens?",a="Der Nachtelf-Druide Naralex brachte seine Anhänger mit einem großen Ziel in diese Höhlen: die unterirdischen Wasser anzuzapfen und den Der Smaragdgrüne Traum zu kanalisieren, um dem Brachland üppige Fruchtbarkeit zurückzugeben. Stattdessen wurde sein Schlummer vom Der Smaragdgrüne Albtraum gefangen. Die dunkle Verderbnis sickerte aus seinem träumenden Geist in die unterirdischen Quellen, veränderte die heimische Tierwelt und trieb seine Akolythen in den Wahnsinn.",al={"geschichte der höhlen des wehklagens","was geschah in den höhlen des wehklagens","hintergrundgeschichte der höhlen des wehklagens"}},fdd3771a={q="Sind Die Höhlen des Wehklagens gefährlich?",a="Sie sind außergewöhnlich gefährlich. Die Gewässer im Inneren sind von mutierten, aggressiven Bestien verseucht, darunter giftige Deviatschlangen, mutierte Raptoren und gefräßige Krokolisken. Jenseits der Bestien lauern die Druiden des Fangzahn-Ordens, die jeden Eindringling bei Sichtkontakt angreifen und albtraumhafte Energien kanalisieren, um den gefangenen, schlummernden Meister zu beschützen, dessen Träume die Verderbnis nähren.",al={"wie gefährlich sind die höhlen des wehklagens","sind die höhlen des wehklagens sicher","bedrohungen in den höhlen des wehklagens"}}},fp="15,337,17.558.0,22.526.1,37.203.0,43.254.0,32.256.0,43.234.0"}
P.entries["subzone:war-quarter"] = {n="Kriegsviertel",s="Das Kriegsviertel ist das nordwestliche Viertel von Unterstadt und dient den Verlassenen als Kommandoposten sowie militärischer Übungsplatz. In seinen widerhallenden Steinkammern schärfen die Soldaten, Priester und Handwerker von Lordaeron ihre Waffen und Schattenmagie zur Verteidigung ihres jungen Königreichs. Es beherbergt Ausbildungshallen für Krieger und Priester sowie Waffenmeister und die Schwerindustrie.",h="Das Kriegsviertel ist das nordwestliche Viertel von Unterstadt und dient den Verlassenen als Kommandoposten...",kw={"altar der dunkelheit","kaserne","schmiedekunst","verlassene","priesterlehrer","unterstadt","kriegsviertel","kriegerlehrer"},ang={["class:Warrior"]="Das Kriegsviertel ist Eure wichtigste Zuflucht in Unterstadt und bietet Waffenmeister, erfahrene Kampfausbilder sowie schwere Rüstkammern, um Euch auf die erbarmungslosen Frontschlachten von Lordaeron vorzubereiten.",["profession:Blacksmithing"]="Mit seinen Ausbildungsmeistern und glühenden Ambossen ist das Kriegsviertel der zentrale Knotenpunkt für Schmiede, die Munition und Plattenrüstungen für die Kriegsanstrengungen der Verlassenen fertigen."},sec={{t="Die Garnison der Verlassenen",b="Im nordwestlichen Sektor der unterirdischen Metropole gelegen, bildet das Kriegsviertel die Bastion der militärischen Stärke der Verlassenen. Unter seinen düsteren Steinbögen versammeln sich einfache Wachen und Elite-Champions, um den bewaffneten Kampf zu trainieren. Anders als traditionelle Kasernen lebender Königreiche verbindet dieses Militärzentrum schonungslose eiserne Kriegsführung mit den schauderhaften Riten des Schattens und birgt einen unheilvollen Altar der Dunkelheit, an dem geistliche Disziplin mit militärischem Ehrgeiz verschmilzt."},{t="Schmiede und Stahl",b="Neben den Gilden der Krieger und Priester fungiert das Viertel als das Herzstück der Kriegsproduktion von Unterstadt. Das Klirren von Klingen und Rüstungen hallt unablässig vom Stein wider, getragen von den Schmieden, Schmelzern und Waffenmeistern des Viertels. Hier wird tief in der Erde geschmiedetes Eisen geformt, um die Streitkräfte auszurüsten, die die Ruinen von Lordaeron vor der Geißel und dem Scharlachroten Kreuzzug verteidigen."}},faq={{q="Welchem Zweck dient das Kriegsviertel?",a="Das Kriegsviertel dient als militärisches Hauptquartier von Unterstadt. Es beherbergt kriegerische Übungsplätze für Krieger und Priester sowie wichtige Handwerksstätten für Schmiedekunst und Bergbau, um die Armee der Verlassenen bewaffnet und gerüstet zu halten.",al={"was ist das kriegsviertel","kriegsviertel zweck","warum das kriegsviertel besuchen"}},{q="Warum befinden sich die Priester im Kriegsviertel?",a="Die Priester der Verlassenen konzentrieren sich größtenteils auf die Disziplin des Schattens und nutzen diesen an der Seite ihrer Krieger als mächtige Waffe, anstatt seelsorgerische Zufluchtsorte zu unterhalten. Ihre Anwesenheit nahe den Streitkräften und dem Altar der Dunkelheit spiegelt wider, wie tief Glaube und Kriegsführung bei der Verteidigung der Verlassenen miteinander verflochten sind.",al={"untoter priester standort","warum sind priester im kriegsviertel","priesterlehrer unterstadt"}},{q="Was ist der Altar der Dunkelheit?",a="Der Altar der Dunkelheit ist ein Brennpunkt dunkler spiritueller Macht im Kriegsviertel. Er ist eng mit den finsteren Riten und der Ausbildung der Verlassenen verbunden und verankert die Schattenmagie, die von ihren Priestern und Champions gewirkt wird.",al={"altar der dunkelheit unterstadt","altar im kriegsviertel"}},{q="Wo befindet sich das Kriegsviertel in Unterstadt?",a="Das Kriegsviertel nimmt den nordwestlichen Quadranten des kreisförmigen Grundrisses von Unterstadt ein, nordwestlich des zentralen Handwerksviertel, zwischen dem Magieviertel im Osten und dem Apothekarium im Süden.",al={"wo ist das kriegsviertel","kriegsviertel standort","wegbeschreibung kriegsviertel"}}},fx={e554fcad={q="Warum heißt es Kriegsviertel?",a="Es erhielt seinen Namen, weil es als das kriegerische Herz von Lady Sylvanas' Herrschaftsbereich dient. Hier organisieren die Verlassenen ihr stehendes Heer, drillen Soldaten, schärfen Klingen und bereiten die Taktiken vor, die notwendig sind, um Krieg gegen die Geißel, The Scarlet Crusade und jede andere Bedrohung ihrer Souveränität zu führen.",al={"warum heißt es kriegsviertel","name kriegsviertel","warum kriegsviertel"}},d58a257c={q="Ist das Kriegsviertel gefährlich?",a="Für Helden der Horde ist das Viertel sicher und wird schwer bewacht von Eliteeinheiten der Verlassenen und Wachen der Todeswache. Für Außenstehende, die Allianz oder Agenten der Geißel bedeutet das Betreten des Kriegsviertels jedoch, einer bewaffneten Garnison gegenüberzustehen, die bereit ist, Eindringlinge ohne Zögern niederzuschlagen.",al={"ist das kriegsviertel gefährlich","gefahr kriegsviertel","ist das kriegsviertel sicher"}}},fp="11,390,21.477.0,15.390.0,39.237.0,43.313.0,30.216.0,50.196.0"}
P.entries["subzone:war-room"] = {fx={bec1bb93={q="Was ist der War Room?",a="Der War Room ist eine strategische Militärkammer in der Burg Sturmwind, direkt neben der Haupthalle des Thronsaals. Er dient als Oberkommando, in dem sich Befehlshaber, Taktiker und Anführer der Allianz versammeln, um laufende Militärkampagnen zu beaufsichtigen. Gefüllt mit Karten, Waffen, Strategiebüchern und Kanonen, ist der Raum vollständig der Verteidigung und strategischen Mobilisierung von Sturmwind und seinen Verbündeten gewidmet.",al={"was ist der war room","über den war room","war room in sturmwind"}},["2eaea60b"]={q="Wer beaufsichtigt den War Room?",a="Der Raum ist mit hochrangigen Militärstrategen, Generälen und Zauberwirkern der Allianz besetzt, die die Operationen im Einsatzgebiet koordinieren. Magier und Kampfoffiziere halten ständig Wache über regionale Konflikte, entwerfen Taktiken und leiten Verstärkungen über die Grenzen des Königreichs.",al={"wer ist im war room","wer leitet den war room","befehlshaber im war room"}},["3751c6cd"]={q="Ist der War Room gefährlich?",a="Nicht für Mitglieder der Allianz. Er liegt tief in der Burg Sturmwind, umgeben von der königlichen Elitegarde und dem militärischen Führungspersonal. Für Eindringlinge oder Agenten der Horde würde das Infiltrieren dieses befestigten strategischen Zufluchtsortes jedoch den sicheren Tod bedeuten.",al={"war room sicherheit","ist der war room sicher","bedrohungen im war room"}},["6b32db00"]={q="Warum heißt er War Room?",a="Der Raum verdient seinen Namen durch seinen speziellen Zweck: Er ist das Nervenzentrum, in dem die militärischen Aktionen des Königreichs orchestriert werden. Ausgestattet mit Donnerbüchsen, Schwertern, Kanonen und taktischen Karten existiert jedes Merkmal in der Kammer, um die Kampagnen der Allianz zu planen und zu führen.",al={"bedeutung des namens war room","warum heißt er war room"}}}}
P.entries["subzone:warpwood-quarter"] = {n="Warpwood Quarter",s="Das Warpwood Quarter umfasst das östliche Viertel der zerstörten Hochgeborenenstadt Eldre'Thalas, die heute als Düsterbruch bekannt ist. Einst ein Zentrum elfischer Naturkultivierung und üppiger Gärten, hat es sich zu einer verzerrten, dämonisch verdorbenen Ruine gewandelt, die von rasender Flora und verderbten Satyren überrannt wird.",h="Das Warpwood Quarter umfasst das östliche Viertel der zerstörten Hochgeborenenstadt Eldre'Thalas, die heute...",kw={"alzzin the wildshaper","düsterbruch ost","eldre'thalas","felvine","fruit of fertility","larisspavillon","pusillin","warpwood quarter"},ang={["class:Druid"]="Das tragische Schicksal der Urtume des Warpwood Quarters und die Verderbnis der Fruit of Fertility zu übler Felvine sind ein trauriger Frevel an den Lehren des Cenarius, was Druiden aus Mondlichtung dazu veranlasst, die Reinigung des Viertels anzustreben.",["race:NightElf"]="Zu sehen, wie die majestätischen Gewächshäuser von Eldre'Thalas zu einer Satyrbrutstätte pervertiert wurden, dient als düstere Erinnerung an die Verderbnis, die das uralte Reich der Hochgeborenen zu Fall brachte."},sec={{t="Ein verderbter Garten",b="Einst bekannt für seine großartigen botanischen Wunder, ist das Warpwood Quarter zu einem erstickenden Wald aus verdrehten Urtumen und tödlichen Peitschern geworden. Der Bezirk geriet unter den Einfluss von Alzzin the Wildshaper, einem Satyr, der seine dunkle Magie darauf ausrichtete, die uralte Fruit of Fertility zu entweihen. Unter seinem bösartigen Einfluss wuchs die Pflanzenwelt grotesk und raubtierhaft heran, tränkte die Hallen mit abscheulichen Felvine-Scherben und lockte Dämonen, rebellische Wichtel sowie dämonische Knechte in die verfallenen Säle."},{t="Pfade durch das Dickicht",b="Während Entdecker den Bezirk für gewöhnlich über die zentralen Broken Commons von Düsterbruch betreten, liegt im Osten unter dem Larisspavillon ein überwucherter unterirdischer Hintereingang verborgen. Um sich im Viertel zurechtzufinden, gilt es nicht nur, Alzzins verdrehte Wächter zu überwinden, sondern auch flüchtige Bewohner wie den schelmischen Wichtel Pusillin, dessen Diebstahl Verfolger auf gefährliche Hetzjagden in die abgelegenen Bereiche der Ruinen führt."}},faq={{q="Was ist das Warpwood Quarter?",a="Das Warpwood Quarter ist der Ostflügel von Düsterbruch, der uralten Hochgeborenenstadt Eldre'Thalas. Ursprünglich um prachtvolle Gewächshäuser herum erbaut, wurde es von dämonischen Energien überwuchert und mutiert.",al={"was ist das warpwood quarter","warpwood quarter","düsterbruch ost lore"}},{q="Wer herrscht über diesen Bezirk?",a="Der Satyr Alzzin the Wildshaper hat die Herrschaft über das Viertel inne. Er nutzte finstere Energien, um die einheimische Vegetation und die legendäre Fruit of Fertility zu verderben, wodurch die pflanzlichen Wächter des Bezirks zu bösartigen, verdrehten Urtumen wurden.",al={"wer kontrolliert warpwood","alzzin the wildshaper","warpwood boss"}},{q="Wie betritt man das Warpwood Quarter?",a="Der Haupteingang befindet sich abseits der Broken Commons im Inneren von Düsterbruch. Ein zweiter, abgeschiedener Hintereingang führt als Tunnel unter dem Larisspavillon im östlichen Feralas heraus, für dessen Öffnung ein Mondsichelschlüssel erforderlich ist.",al={"warpwood eingang","wie man nach düsterbruch ost kommt","lariss' pavillon eingang"}},{q="Warum rennt der Wichtel Pusillin durch die Ruinen?",a="Pusillin ist ein diebischer Wichtel, der nahe dem Eingang des Viertels lauert. Wenn er von Eindringlingen gestellt wird, verhöhnt er sie und flieht tiefer durch die Ruinen, wobei er Abenteurer den ganzen Weg bis hin zum Hidden Reach verspottet.",al={"pusillin","wer ist pusillin","wichtel rennt düsterbruch"}}},fp="16,281,18.474.0,31.427.0,29.199.0,24.234.0,38.206.0,50.210.0"}
P.entries["subzone:warrior-s-terrace"] = {n="Die Terrasse der Krieger",s="Die Terrasse der Krieger ist das östliche Viertel von Darnassus und fungiert sowohl als Zentrum für die militärische Ausbildung als auch als befestigtes Tor der Hauptstadt. Mit Blick auf die Straße ins weitere Teldrassil beherbergt sie die Kampfmeister der Stadt, Kriegerlehrer und Patrouillen der Schildwachen.",h="Die Terrasse der Krieger ist das östliche Viertel von Darnassus und fungiert sowohl als Zentrum für die...",kw={"kampfmeister","darnassus","duellplätze","osttor","halle der gerechtigkeit","schildwachen","teldrassil","die terrasse der krieger"},ang={["class:Warrior"]="Für Krieger, die in der Hauptstadt der Nachtelfen trainieren, ist dieses Viertel Eure Operationsbasis, die Zugang zu Kampfausbildern, Duellbereichen und Kampfmeistern bietet.",["profession:Blacksmithing"]="Auf der Terrasse befinden sich die Schmiedekunstlehrer und Schmiedeeinrichtungen der Stadt, die neben der Garnison für Rüstungs- und Waffenherstellung sorgen."},sec={{t="Schild von Darnassus",b="An der östlichen Schwelle von Darnassus gelegen, bildet die Terrasse der Krieger – manchmal auch als Halle der Gerechtigkeit bezeichnet – das wichtigste Verteidigungsbollwerk gegen Einfälle aus der Wildnis von Teldrassil. Schwer bewaffnete Schildwachen auf Nachtsäblern bewachen die hohen Bogentore und halten wachsam Ausschau nach ankommenden Reisenden. Auf den offenen Plätzen trainieren angehende Kämpfer an der Seite erfahrener Veteranen auf weitläufigen Duellplätzen und Schießständen. Der Bezirk dient auch praktischen militärischen Erfordernissen und beherbergt Waffenschmiede, Rüstungsschmiede sowie die Kampfmeister, welche die Streitkräfte der Nachtelfen in der weiteren Welt koordinieren."}},faq={{q="Was ist der Zweck der Terrasse der Krieger?",a="Die Terrasse der Krieger fungiert als das militärische Herz von Darnassus und sein wichtigstes Verteidigungstor. Sie beherbergt die Kampfausbilder der Stadt, Kampfmeister, Duellplätze und Schießstände, während stationierte Schildwachen das Osttor bewachen, das in die weiteren Äste von Teldrassil führt.",al={"was ist die terrasse der krieger","zweck terrasse der krieger","warum terrasse der krieger"}},{q="Wohin führt die Straße durch das Osttor?",a="Die großen Tore am östlichen Rand der Terrasse führen direkt aus Darnassus hinaus auf die Waldpfade des weiteren Teldrassil und verbinden die abgelegene Hauptstadt mit Siedlungszentren wie Dolanaar und Rut'theran darunter.",al={"wohin führt das tor","tor terrasse der krieger","osttor darnassus"}},{q="Wer bewacht das Viertel?",a="Das Viertel und seine Außentore werden vor allem von den Schildwachen bewacht, dem stehenden Eliteheer der Nachtelfen. Viele von ihnen patrouillieren auf gepanzerten Nachtsäblern über die Terrassen und Tore.",al={"wer beschützt terrasse der krieger","schildwachen terrasse der krieger","darnassus wachen"}},{q="Welche anderen Viertel sind mit der Terrasse der Krieger verbunden?",a="Brücken und Gehwege verbinden die Terrasse der Krieger direkt mit der Terrasse der Handwerker im Norden, der Terrasse der Händler im Süden und den üppigen Tempelgärten im Zentrum der Stadt im Westen.",al={"verbindungen terrasse der krieger","weg zur terrasse der krieger","was verbindet terrasse der krieger"}}},fx={["162de6c0"]={q="Was ist Die Terrasse der Krieger?",a="Die Terrasse der Krieger ist der östlichste Bezirk von Darnassus und bewacht die großen Tore, die hinaus in die Wildnis von Teldrassil führen. Als primärer militärischer Knotenpunkt der Hauptstadt der Nachtelfen beherbergt sie Duellplätze, Schießstände und Kasernen, in denen sich Wächterinnen, Kriegerausbilder und Kampfmeister versammeln, um zu üben und das Reich zu verteidigen.",al={"was ist die terrasse der krieger","informationen zur terrasse der krieger","über die terrasse der krieger"}},["4e3ffca6"]={q="Warum heißt sie Die Terrasse der Krieger?",a="Die Terrasse erhielt ihren Namen als das kriegerische Herz von Darnassus. Sie ist der dedizierte Bereitstellungs- und Ausbildungsbereich für Krieger, Wächterinnen und Kampfmeister der Nachtelfen, die ihre Kampffertigkeiten verfeinern, und dient gleichzeitig als erste Verteidigungslinie der Stadt gegen jeden Angriff auf ihre Tore.",al={"warum heißt sie terrasse der krieger","bedeutung des namens terrasse der krieger","warum terrasse der krieger"}},d3913307={q="Ist Die Terrasse der Krieger gefährlich?",a="Für Besucher der Allianz ist die Terrasse völlig sicher. Sie dient als die am stärksten bewachte Festung von Darnassus, die Tag und Nacht von wachsamen Wächterinnen auf Nachtsäblern geschützt wird. Es sei denn, Ihr provoziert einen Übungskampf auf den Duellplätzen oder wagt es, als Feind der Kaldorei in die Stadt zu kommen, droht Euch hier keine Gefahr.",al={"ist die terrasse der krieger gefährlich","sicherheit auf der terrasse der krieger","bedrohungen auf der terrasse der krieger"}}},fp="17,256,19.626.0,45.284.0,50.225.0,24.191.0,55.206.0"}
P.entries["subzone:warsong-labor-camp"] = {n="Lager des Kriegshymnenklans",s="Das Lager des Kriegshymnenklans ist ein abgelegener Holzfäller-Außenposten der Horde, der im südöstlichen Eschental verborgen liegt. Betrieben von Holzfällern des Kriegshymnenklans und verteidigt von orkischen Wachposten, schlägt das Arbeitslager Holz für das Wachstum von Durotar, während es den feindseligen Gefahren des umliegenden Waldes trotzt.",h="Das Lager des Kriegshymnenklans ist ein abgelegener Holzfäller-Außenposten der Horde, der im südöstlichen...",kw={"eschental","dor'danil","fallenskysee","arbeitslager","holzfäller","holz","bauholz","warsong"},ang={["faction:Horde"]="Das von diesen Holzfällern geschlagene Holz ist für den Aufbau und Erhalt von Orgrimmar unverzichtbar, was diesen abgelegenen Arbeitsplatz zu einer lebenswichtigen wirtschaftlichen Lebensader in umkämpftem Gebiet macht.",["race:NightElf"]="Das Lager stellt eine anhaltende Wunde in den lebendigen Wäldern von Eschental dar, indem es uralte Haine abholzt, um die Kriegsmaschinerie von Durotar anzutreiben."},sec={{t="Bauholz für die Horde",b="Östlich des Himmelssturzsees und südwestlich des Dor'danil-Grabhügels gelegen, dient das Lager des Kriegshymnenklans einem einzigen, lebenswichtigen Zweck: der Abholzung des dichten Baumbestands von Eschental. Die trockenen Ebenen von Durotar bieten kaum nutzbares Bauholz für den Bau von Städten wie Orgrimmar, was den Kriegshymnenklan dazu zwingt, tief in die umkämpften Wälder vorzudringen. Besetzt mit abgehärteten Holzfällern und orkischen Wachen, arbeitet die Holzfällerstätte in relativer Isolation und fällt uralte Bäume trotz der allgegenwärtigen Bedrohung durch Späher der Nachtelfen und vorbeiziehende Kriegstrupps der Allianz."},{t="Ein verwundbarer Außenposten",b="Aufgrund seiner abgeschiedenen Lage fernab der Hauptstraße und befestigter Stützpunkte wie dem Splitterholzposten ist das Lager außerordentlich verwundbar. Angreifer der Allianz überfallen oft die arbeitenden Peons und Wächter, da sie wissen, dass Verstärkung nicht schnell eintreffen wird. Für die Nachtelfen ist jeder gefällte Baum ein Sakrileg, was dieses gewöhnliche Holzfällerlager zu einem ständigen Brennpunkt im regionalen Krieg macht."}},faq={{q="Wo befindet sich das Lager des Kriegshymnenklans?",a="Das Arbeitslager liegt im südöstlichen Eschental, östlich des Himmelssturzsees und südwestlich des Dor'danil-Grabhügels.",al={"lager der warsongarbeiter ort","wo liegt das lager der warsongarbeiter","lager der arbeiter finden"}},{q="Was ist der Zweck dieses Lagers?",a="Der Außenposten dient als Holzfällerbetrieb. Orkische Holzfäller fällen und verarbeiten das uralte Holz von Eschental, um Baumaterial für Orgrimmar und andere Siedlungen in Durotar zu beschaffen.",al={"warum sind orcs hier","was tun sie hier","warsong holzfällerlager zweck"}},{q="Warum wird das Lager häufig angegriffen?",a="Das Lager liegt isoliert und fernab größerer Befestigungen der Horde. Die Nachtelfen verabscheuen das Abholzen ihrer heiligen Wälder zutiefst, und Recken der Allianz überfallen den Außenposten häufig, da seine abgelegene Lage verhindert, dass nahegelegene Wachen schnell Beistand leisten können.",al={"allianz greift arbeitslager an","warum wird es angegriffen","ist das lager sicher"}},{q="Wurde dieses Lager von Grommash Hellscream gegründet?",a="Kriegshäuptling Thrall schickte Grommash Hellscream und den Kriegshymnenklan während des Dritten Krieges ursprünglich nach Eschental, um gezielt Holz zu schlagen. Das Lager des Kriegshymnenklans ist die aktive Fortsetzung dieser ursprünglichen Holzfällerbemühungen.",al={"hat grom dies erbaut","grom hellscream arbeitslager","geschichte des lagers"}}},fx={f9ba0d17={q="Was ist das Lager des Kriegshymnenklans?",a="Das Lager des Kriegshymnenklans ist ein aktiver Außenposten der Horde zur Holzfällerei im südöstlichen Eschental, östlich des Himmelssturzsees und südwestlich des Dor'danil-Grabhügels gelegen. Es dient als Frontbetrieb, in dem Arbeiter und mechanisierte Erntemaschinen die uralten Bäume des Waldes fällen, um die Expansion der Horde voranzutreiben, während das Lager kontinuierlich gegen lokale Bedrohungen verteidigt wird.",al={"was ist das lager des kriegshymnenklans","informationen zum lager des kriegshymnenklans","erzähl mir etwas über das lager des kriegshymnenklans"}},b37a2225={q="Wer lebt im Lager des Kriegshymnenklans und betreibt es?",a="Das Lager wird von Mitgliedern des Kriegshymnenklans betrieben, die hauptsächlich aus orkischen Holzfällern, Mannschaften für die von Goblins gebauten Schredder und Erntemaschinen sowie standhaften Wachen bestehen, die den Umkreis bewachen und die Holzernte verteidigen.",al={"wer betreibt das lager des kriegshymnenklans","bewohner des lager des kriegshymnenklans","wer ist im lager des kriegshymnenklans"}},f04818dc={q="Ist das Lager des Kriegshymnenklans gefährlich?",a="Es ist ziemlich gefährlich. Da das Lager relativ isoliert tief im Eschental liegt, ist es anfällig für Überraschungsangriffe der Streitkräfte der Allianz und lokaler Wächter, die versuchen, die Holzfällertrupps auszulöschen, bevor Verstärkung von größeren Stützpunkten der Horde eintreffen kann.",al={"ist das lager des kriegshymnenklans gefährlich","gefahr im lager des kriegshymnenklans","wie gefährlich ist das lager des kriegshymnenklans"}},["1e0e0990"]={q="Warum heißt es Lager des Kriegshymnenklans?",a="Der Außenposten hat seinen Namen vom Kriegshymnenklan, dem wilden orkischen Klan, der von Kriegshäuptling Thrall damit beauftragt wurde, Holz im gesamten Eschental zu ernten. Da es sich eher um eine spezialisierte Holzfällerstätte als um eine große Festung handelt, wird es einfach als ihr Arbeitslager bezeichnet.",al={"warum heißt es lager des kriegshymnenklans","bedeutung des namens lager des kriegshymnenklans","warum lager des kriegshymnenklans"}}},fp="18,280,20.518.0,20.390.0,40.113.0,33.189.0,36.258.0,40.223.0"}
P.entries["subzone:warsong-lumber-camp"] = {n="Holzfällerlager des Kriegshymnenklans",s="Das Holzfällerlager des Kriegshymnenklans ist ein befestigter Holzfällerbetrieb der Orcs tief in Eschental, der vom Kriegshymnenklan betrieben wird, um Bauholz für die Horde zu schlagen. Verankert durch die befestigte Burg Kargathia dient es sowohl als wirtschaftliche Lebensader für nahegelegene Hordensiedlungen als auch als unerbittliche Provokation für die Nachtelfen. Das ständige Geräusch von Goblinschreddern, die sich durch uralte Äste fressen, macht diese Lichtung zu einem zentralen Brennpunkt des Waldkriegs.",h="Das Holzfällerlager des Kriegshymnenklans ist ein befestigter Holzfällerbetrieb der Orcs tief in Eschental...",kw={"eschental","burg kargathia","schredder","splintertreeposten","bauholz","warsongclan","holzfällerlager des kriegshymnenklans"},ang={["faction:Horde"]="Das hier geschlagene Holz liefert die Baumaterialien für den Splitterholzposten und die Befestigungen, die die Zukunft der Horde in Kalimdor sichern.",["race:NightElf"]="Die kreischenden Schredder und fallenden Bäume des Lagers stellen einen direkten, brutalen Angriff auf das heilige Gleichgewicht von Eschental dar, den die Schildwachen auszulöschen geschworen haben."},sec={{t="Herz der Ernte",b="Direkt aus dem dichten Blätterdach des östlichen Eschental geschlagen, ist das Holzfällerlager des Kriegshymnenklans der industrielle Motor, der die Expansion der Horde in Kalimdor antreibt. Orc-Knechte und angeheuerte Goblin-Ingenieure roden den Wald mit surrenden Schreddern und verarbeiten riesige Stämme zu Bauholz, um Außenpostenwände wie den nahegelegenen Splitterholzposten zu verstärken und die junge Nation Durotar aufzubauen. Das Lager ist stark gegen ständige Gegenangriffe der Nachtelfen befestigt und zentriert sich um die Palisaden von Burg Kargathia sowie einen aktiven Zwinger für die wilden Kriegswölfe des Clans. Für den Kriegshymnenklan bedeutet jeder gefällte Baum Überleben und Stärke; für die einheimischen Schildwachen ist jedes Sägeblatt ein Akt des Frevels."},{t="Ein Vermächtnis des Krieges",b="Die Präsenz des Kriegshymnenklans in diesen Wäldern reicht bis in den Dritten Krieg zurück, als Grom Hellscream seine Krieger zum ersten Mal in die heiligen Haine führte, um Holz für die Horde zu beanspruchen. Diese anfängliche Abholzung entfachte den Zorn des Halbgottes Cenarius und beschwor die uralte Wut der Nachtelfen herauf. Obwohl das heutige Lager unter den Bannern von Thralls Horde betrieben wird, brennen die alten Feindseligkeiten genauso heftig. Umgeben von ungezähmtem Holz, feindseligen Elfen und der anhaltenden dämonischen Verderbnis rund um den benachbarten Dämonenhügel bleiben die Verteidiger des Lagers rund um die Uhr bewaffnet – sie fällen Bäume mit der Axt in der Hand und sind jederzeit bereit, ihr Holz fallen zu lassen, um den nächsten Hinterhalt abzuwehren."}},faq={{q="Warum schlägt die Horde in Eschental Holz?",a="Die von der Horde besiedelten Gebiete – insbesondere Durotar und das Brachland – sind trocken und karg; es fehlt ihnen an dichtem Nutzholz, das für den Bau von Gebäuden, Palisaden und Kriegsmaschinerie benötigt wird. Eschental bietet einen gewaltigen, praktisch endlosen Vorrat an erstklassigem Holz, der für das Überleben und die Expansion von Orc-Außenposten wie dem Splitterholzposten und der Hauptstadt Orgrimmar unerlässlich ist.",al={"warum bäume fällen","warsong holzfäller gründe","warum braucht horde holz"}},{q="Was ist Burg Kargathia?",a="Burg Kargathia ist die befestigte Festung, die das Holzfällerlager des Kriegshymnenklans verankert. Sie bietet Kasernen, strategische Führung und eine verstärkte Bastion, in die sich Knechte und Aufseher zurückziehen können, um Nachtelfen-Hinterhalte abzuwehren, wenn Schildwachen oder die einheimische Tierwelt den Holzfällerperipherie angreifen.",al={"zweck burg kargathia","festung im holzfällerlager","warsong festung eschental"}},{q="Warum sind die Nachtelfen diesem Lager gegenüber so feindselig gesinnt?",a="Für die Nachtelfen ist Eschental eine heilige angestammte Heimat, die von Naturgeistern und Urtumen beschützt wird. Das Fällen uralter Bäume mit lautem, rauchspeiendem Goblin-Gerät gilt als mutwillige Zerstörung und offenkundige Schändung, was ständige Guerillaangriffe provoziert, um die Orcs des Kriegshymnenklans aus dem Wald zu vertreiben.",al={"reaktion der nachtelfen","warum elfen holzfällerlager angreifen","schildwachen angriffe"}},{q="Welche Rolle spielen Goblins im Lager?",a="Goblinsöldner und -techniker stellen die spezialisierte Technologie bereit, die den Holzfällerbetrieb antreibt, allen voran dampfbetriebene Schredder. Diese Maschinen ermöglichen es dem Kriegshymnenklan, massive uralte Bäume mit einer Geschwindigkeit zu fällen und zu entasten, die herkömmliche Handäxte niemals erreichen könnten.",al={"goblins im warsong lager","warum sind schredder hier","goblin maschinen eschental"}}},fx={["4dce9068"]={q="Was ist das Holzfällerlager des Kriegshymnenklans?",a="Das Holzfällerlager des Kriegshymnenklans ist ein riesiger, befestigter Holzfäller-Außenposten, der vom Kriegshymnenklan im zentralen Eschental errichtet wurde. Es wird durch die befestigte Burg Kargathia gehalten und verfügt über Wolfszwinger; es dient als Hauptbasis der Horde für die Holzproduktion im uralten Wald und schickt stetig Lieferungen von Holz und Vorräten durch Kalimdor, um junge orkische Siedlungen wie Orgrimmar zu unterstützen.",al={"das holzfällerlager der warsong","was ist dieser ort","über das holzfällerlager der warsong"}},ae82815c={q="Warum heißt es Holzfällerlager des Kriegshymnenklans?",a="Das Lager ist nach dem Kriegshymnenklan benannt, dem wilden orkischen Klan, der während des Dritten Krieges unter dem Häuptling Grom Hellscream als Erster in die uralten Wälder des Eschentals vordrang. Obwohl ihr Anführer starb, während er die Orks von dämonischer Verderbnis befreite, bleibt sein Klan hier dauerhaft verschanzt und treibt die Holzfällerbemühungen der Horde trotz heftigen Widerstands aus der Wildnis unnachgiebig voran.",al={"warum heißt es holzfällerlager der warsong","ursprung des namens holzfällerlager der warsong"}},["4eda0a15"]={q="Wer betreibt das Holzfällerlager des Kriegshymnenklans?",a="Das Lager wird von Orks des Kriegshymnenklans betrieben und besetzt, die mit von der Venture Company ausgebildeten Goblin-Söldnern, Ingenieuren und Maschinenführern zusammenarbeiten. Kriegshymnen-Grunzer und Zwingermeister sichern Burg Kargathia und bewachen den Umkreis, während Goblin-Aufseher die lauten, treibstofffressenden Schredder verwalten, die die uralten Bäume des Eschentals fällen.",al={"wer führt das holzfällerlager der warsong","wer hat hier das sagen","kommandant des holzfällerlagers der warsong"}},["7474287b"]={q="Ist das Holzfällerlager des Kriegshymnenklans gefährlich?",a="Es ist extrem gefährlich. Das unerbittliche Abholzen des Eschentals hat die Nachtelfen und die Geister des Waldes erzürnt. Wächter und rachsüchtige Bäume starten häufige Hinterhalte aus dem Blätterdach, um Schredder zu zertrümmern und heilige Haine zurückzuerobern. Darüber hinaus werden Reisende der Allianz, die sich in die Nähe des Umkreises wagen, feststellen, dass Burg Kargathia voller aggressiver Verteidiger des Kriegshymnenklans ist, die bereit sind, jeden Eindringling niederzustrecken.",al={"ist das holzfällerlager der warsong gefährlich","wie gefährlich ist das holzfällerlager"}}},fp="19,433,20.678.0,15.661.0,38.357.0,23.276.0,48.307.0,38.272.0"}
P.entries["subzone:waterspring-field"] = {n="Wasserfeld",s="Das Wasserfeld ist eine lebenswichtige Wasserpumpanlage im nördlichen Tanaris, die von den Goblins aus Gadgetzan errichtet wurde, um unterirdische Grundwasserleiter zu erschließen. Anstatt die Boomtown zu versorgen, wurde das Feld von den skrupellosen Wastewander-Banditen überrannt, die nun die wertvollste Ressource der Wüste horten.",h="Das Wasserfeld ist eine lebenswichtige Wasserpumpanlage im nördlichen Tanaris, die von den Goblins aus...",kw={"gadgetzan","pumpen","tanaris","wastewander","wasserschläuche","wassertürme","wasserfeld"},ang={["profession:Engineering"]="Die von Goblins erbauten mechanischen Pumpentürme stellen eine beeindruckende Wüstenhydraulik dar.",["race:Human"]="Die Wastewander-Banditen, die die Türme besetzt halten, sind überwiegend menschliche Gesetzlose, die den Königreichen des Nordens den Rücken gekehrt haben, um in der Wüstensonne ein brutales Dasein zu fristen."},sec={{t="Eine gestohlene Oase",b="In den sengenden Ödlanden von Tanaris ist nichts wertvoller als frisches Wasser. Um ihr expandierendes Handelszentrum zu unterstützen, errichteten die Goblins des Steamwheedle-Kartells aus Gadgetzan eine Reihe industrieller Pumpentürme im Wasserfeld, um aus unterirdischen Reserven zu schöpfen. Ihre Pläne scheiterten, als die Wastewander – eine weitverzweigte Bande menschlicher Gesetzloser und Wüstenplünderer – das gesamte Feld besetzten. Die Banditen bewachen die entwendeten Pumpen nun mit ihrem Leben, was Gadgetzan dazu zwingt, nach angeheuerten Klingen zu suchen, die bereit sind, das Nass zurückzuerobern."}},faq={{q="Wer hat die Wassertürme hier gebaut?",a="Die Türme wurden von den Goblins aus Gadgetzan gebaut. Sie beabsichtigten, frisches Wasser aus tiefen unterirdischen Reserven zu pumpen, um ihre Wüstensiedlung und ihren Industriebetrieb aufrechtzuerhalten.",al={"wer hat das erbaut","goblin-pumpen","waterspring-feld türme"}},{q="Warum besetzen Banditen das Wasserfeld?",a="Die Nomaden der Wastewander fielen in das Feld ein und bemächtigten sich der Maschinen. Die Kontrolle über die Hauptquelle von frischem Wasser im nördlichen Tanaris gibt ihnen die totale Kontrolle über umherziehende Reisende und Händler.",al={"wer sind die banditen","wastewander waterspring","warum sind die wastewander hier"}},{q="Warum holt sich Gadgetzan das Feld nicht direkt zurück?",a="Gadgetzan heuert Abenteurer an, um die Wastewander-Banditen zurückzudrängen und ihre Wasserschläuche zurückzuholen. Der Grund, warum ihre Schläger nicht in das Feld geschickt werden, ist unbekannt.",al={"warum kämpft gadgetzan nicht","goblin-wachen waterspring"}}},fp="17,294,14.538.0,32.178.0,53.215.0,51.162.0"}
P.entries["subzone:wavestrider-beach"] = {n="Wellenschreiterstrand",s="Der Wellenschreiterstrand ist der sonnenverbrannte Küstenstreifen am östlichen Rand von Tanaris. Er erstreckt sich zwischen dem Dampfdruckpier und der Piratenhochburg an der Mast- und Schotbucht. Seine Sandflächen werden von aggressiven Krebstieren bewohnt und bieten einen Ausblick auf ferne Seegefechte draußen auf dem Meer.",h="Der Wellenschreiterstrand ist der sonnenverbrannte Küstenstreifen am östlichen Rand von Tanaris.",kw={"küste","wüstenkriecher","mast- und schotbucht","südmeer","steamwheedle","stahlkieferschnapper","tanaris","wellenschreiterstrand"},sec={{t="Eine tückische Küstenlinie",b="Entlang der Meeresgrenze des östlichen Tanaris verbindet der Wellenschreiterstrand die Goblinsiedlung Dampfdruckpier im Norden mit den Klippen, die die Mast- und Schotbucht im Süden abschirmen. Statt eines friedlichen Erholungsortes wird das Ufer von bösartigen Stahlkieferschnappern und Wüstenkriechern heimgesucht, die über den glühend heißen Sand huschen. Draußen im tiefen Wasser, unweit der Küste, liefern sich brennende Schiffe ein unablässiges Seegefecht – eine düstere Warnung vor der Piratengewalt, die diese Küstengewässer beherrscht."}},faq={{q="Wo befindet sich der Wellenschreiterstrand?",a="Der Wellenschreiterstrand liegt an der Ostküste von Tanaris und erstreckt sich direkt zwischen den Docks vom Dampfdruckpier im Norden und dem Eingang zur Mast- und Schotbucht im Süden.",al={"wellenschreiterstrand lage","wo liegt der wellenschreiterstrand","wellenschreiterstrand tanaris"}},{q="Welche Kreaturen durchstreifen hier den Sand?",a="Der Strand wird vor allem von aggressiven marinen Aasfressern überrannt, darunter einheimische Wüstenkriecher und schwer gepanzerte Stahlkieferschnapper, die in der Brandung lauern.",al={"wellenschreiterstrand mobs","krebse am wellenschreiterstrand"}},{q="Was hat es mit den vor der Küste sichtbaren brennenden Schiffen auf sich?",a="Blickt man vom Strand aus aufs Meer hinaus, kann man zwei lichterloh brennende Schiffe erkennen, die in ein Gefecht verwickelt sind. Sie zeugen von den unbändigen Piratenaktivitäten, die die Gewässer rund um die Schlupfwinkel der Südmeerfreibeuter plagen.",al={"brennende schiffe tanaris","brennende schiffe wellenschreiterstrand"}},{q="Ist der Wellenschreiterstrand sicher zu bereisen?",a="Er ist verhältnismäßig gefährlich. Zwischen den aggressiven Schnappkiefern und Krebsen am Wassersaum sowie der unmittelbaren Nähe zum Territorium der Südmeerpiraten können unvorsichtige Entdecker schnell überwältigt werden.",al={"ist der wellenschreiterstrand gefährlich","wellenschreiterstrand sicherheit"}}},fp="17,279,23.508.0,35.182.0,37.153.0,44.213.0,44.204.0"}
P.entries["subzone:weathered-nook"] = {n="Der Wetterwinkel",s="Versteckt an den nördlichen Klippen von Tausend Nadeln liegt Der Wetterwinkel, eine abgelegene Felsspalte und Zuflucht hoch über dem Grund des Canyons. Mit Blick auf das weite Meer aus Steinnadeln dient er als bescheidene Behausung und Rückzugsort für einsame Tauren, die fernab belebter Siedlungen stille Einkehr suchen.",h="Versteckt an den nördlichen Klippen von Tausend Nadeln liegt Der Wetterwinkel, eine abgelegene Felsspalte und...",kw={"höhle","klippe","dorn ebenenpirscher","freiwindposten","prate cloudseer","tausend nadeln","der wetterwinkel"},ang={["faction:Horde"]="Wanderer der Horde, welche die Höhen der Canyonwände erkunden, finden hier an den nördlichen Klippen freundliche Artgenossen, die Schutz suchen.",["race:Tauren"]="Für Tauren-Reisende verkörpert Der Wetterwinkel den stillen Geist der Selbstgenügsamkeit und bietet einen friedlichen Aussichtspunkt über den Canyon, um fernab der geschäftigen Brücken des Freiwindpostens Zwiesprache mit den Elementen zu halten."},sec={{t="Zuflucht an den Klippen",b="In die steile Sandsteinwand nördlich vom Freiwindposten gehauen, wird Der Wetterwinkel von Reisenden im darunter liegenden Canyonbecken leicht übersehen. Eine natürliche Rampe windet sich die Klippenwand hinauf und führt zu einem geschützten Felsvorsprung samt Höhle abseits der vorherrschenden Winde. Anstelle eines militärischen Außenpostens oder einer großen Siedlung dient der Winkel als bescheidenes Heim für einsame Wanderer wie Dorn Ebenenpirscher und Prate Cloudseer und bietet Sicherheit, Abgeschiedenheit sowie einen weiten Blick über die windgepeitschten Nadelplateaus."}},faq={{q="Wo befindet sich Der Wetterwinkel?",a="Der Winkel schmiegt sich an die nördliche Felswand von Tausend Nadeln. Reist vom Freiwindposten nach Norden, bis Ihr die hoch aufragende Felswand erreicht, und folgt den Klippen dann nach Osten, bis Ihr eine gewundene Rampe findet, die an der Wand des Tafelbergs hinaufsteigt.",al={"wie man den wetterwinkel findet","der wetterwinkel standort","wo ist der winkel"}},{q="Wer lebt im Wetterwinkel?",a="Die Zuflucht ist die Heimat von Dorn Ebenenpirscher und Prate Cloudseer, einsamen Tauren, die diesen abgelegenen Felsvorsprung über dem Canyon den überfüllten Türmen des Freiwindpostens vorgezogen haben.",al={"wer ist hier","der wetterwinkel bewohner","npcs im winkel"}},{q="Gehört Der Wetterwinkel zur Horde?",a="Obwohl die Bewohner Tauren sind und sich ganz natürlich ihren Artgenossen verbunden fühlen, ist der Winkel keine offizielle Garnison der Horde. Es handelt sich um ein bescheidenes persönliches Lager und eine Behausung, die ruhig in der Wildnis verborgen liegt.",al={"ist dies ein hordenlager","horde der wetterwinkel"}}},fx={["3c15de53"]={q="Was ist der Wetterwinkel?",a="Der Wetterwinkel ist ein kleiner, abgelegener Unterstand, der in die nördlichen Felswände mit Blick auf die Schluchten der Tausend Nadeln gehauen wurde. Weit entfernt von den geschäftigen Pfaden der Freiwindposten und der schimmernden Ebene dient diese ruhige Felsspalte als bescheidenes Lager für Reisende, die Zuflucht vor den rauen Elementen und umherstreifenden Bestien des Schluchtenbodens suchen.",al={"wetterwinkel was ist das","was ist der wetterwinkel","informationen zum wetterwinkel"}},["4c65fc70"]={q="Ist der Wetterwinkel gefährlich?",a="Der Winkel selbst ist im Vergleich zum umliegenden Schluchtenboden relativ ruhig und dient seinen Bewohnern als Zufluchtsort. Der Pfad entlang der hoch aufragenden Klippen kann jedoch tückisch sein, und aggressive Bestien wie umherstreifende Pumas, Wyvern und Zentaur-Plünderer durchstreifen die felsigen Höhen und Pässe in der Nähe.",al={"wetterwinkel gefährlich","ist der wetterwinkel sicher","bedrohungen im wetterwinkel"}}},fp="14,319,19.505.0,36.227.0,32.191.0,48.189.0"}
P.entries["subzone:weazel-s-crater"] = {n="Weazels Krater",s="Weazels Krater ist eine tiefe Einkerbung, die in das harte Salz der nördlichen Schimmernden Ebene geschlagen wurde. Seine Ursprünge sind rätselhaft, und Saltstone-Basilisken bewohnen die Senke.",h="Weazels Krater ist eine tiefe Einkerbung, die in das harte Salz der nördlichen Schimmernden Ebene geschlagen...",kw={"gnomingenieurskunst","goblin-rennstrecke","saltstone-basilisken","die schimmernde ebene","tausend nadeln","weazels krater"},ang={["profession:Engineering"]="Die tiefe Senke liegt inmitten der experimentellen Rennmaschinen und Trümmer der Schimmernden Ebene. Ingenieure, die die Rennstrecke besuchen, haben guten Grund, das gefährliche Terrain zu untersuchen."},sec={{t="Ein volatiles Vermächtnis",b="Über die blendend weiße Weite der Schimmernden Ebene hinweg verschieben experimentelle Raketenwagen der Goblins und Gnome ständig die Grenzen des mechanischen Verstands. Trümmer, verbrannte Erde und Einschlagsmulden übersäen die Ebenen, doch Weazels Krater sticht durch seine schiere Größe und Tiefe hervor. Die Ursprünge des Kraters sind unbekannt. Heute haben sich die mechanischen Wrackteile weitgehend gesetzt, und die Senke wurde von aggressiven Saltstone-Basilisken als Sonnenplatz beansprucht."}},faq={{q="Was hat Weazels Krater verursacht?",a="Die Ursprünge des Kraters sind unbekannt. Es ist keine Ursache erwiesen.",al={"wie ist weazels krater entstanden","ursprung von weazels krater","warum gibt es hier einen krater"}},{q="Was lebt jetzt im Krater?",a="Die Senke wird derzeit von gefährlichen Saltstone-Basilisken bewohnt, die an den felsigen Rändern und am Grund der Grube lauern.",al={"weazels krater mobs","was befindet sich im krater"}}},fx={["76b07605"]={q="Was ist Weazels Krater?",a="Weazels Krater ist eine große, tiefe Vertiefung, die in die nördliche Weite der schimmernden Ebene in den Tausend Nadeln gegraben wurde. Obwohl er wie eine Einschlagstelle aussieht, liegt er direkt an den Pfaden, auf denen Goblins und Gnome ihre flüchtigen, raketenbetriebenen Rennmaschinen testen, was ihn zu einem markanten und gefährlichen Wahrzeichen inmitten der Salzwüste macht.",al={"weazels krater","was ist dieser krater","weazels krater schimmernde ebene"}},["4a4cb038"]={q="Ist Weazels Krater gefährlich?",a="Ja. Jenseits des Risikos durch rücksichtslose Raketenrennfahrer, die über die Ebene rasen, ist der Krater selbst zu einem verseuchten Bau für aggressive Salzsteinbasilisken geworden. Jeder, der in die Senke hinabsteigt, riskiert, zu Stein erstarrt oder von den darin lauernden, territorialen Bestien zerfleischt zu werden.",al={"ist weazels krater gefährlich","weazels krater bedrohungen","gefahr weazels krater"}}},fp="15,163,17.446.0,28.58.0,29.127.0"}
P.entries["subzone:webwinder-path"] = {n="Weberpass",s="Der Weberpass ist eine gewundene Bergstraße im Steinkrallengebirge, die den Trollaußenposten Malaka'jin mit dem Mirkfallonsee verbindet. Er durchschneidet schroffe Felsen und dichte Hochlandwälder, die von aggressiven Spinnentieren und einheimischen Bestien bewohnt werden.",h="Der Weberpass ist eine gewundene Bergstraße im Steinkrallengebirge, die den Trollaußenposten Malaka'jin mit...",kw={"malaka'jin","mirkfallonsee","straße","spinnen","steinkrallengebirge","weberpass"},ang={["class:Hunter"]="Der Pfad beherbergt kräftige Donnerechsen, robuste Bergwidder und giftige Netzweber, was ihn zu einer hervorragenden Route zum Aufspüren und Zähmen von Steinkrallenbestien macht.",["faction:Horde"]="Der Pfad ist eine entscheidende Überlandader direkt vor den Toren von Malaka'jin und verbindet Eure Späher mit den tiefer gelegenen Tälern des Steinkrallengebirges."},sec={{t="Eine tückische Durchgangsstraße",b="Von der Hordensiedlung Malaka'jin in Richtung Mirkfallonsee verlaufend, dient der Weberpass als eine der Hauptverkehrsadern, die sich durch das untere Steinkrallengebirge schneiden. Seinem Namen getreu ist der Weg berüchtigt für die dichten Spinnweben, die hoch zwischen den Baumkronen und zerklüfteten Felswänden gespannt sind. Reisende auf dieser gewundenen Strecke müssen stets auf ihre Schritte achten, da sie sich den ausgetretenen Pfad mit herumstreifenden Bergspinnen, aggressiven Donnerechsen und territorialen Widdern teilen."}},faq={{q="Wohin führt der Weberpass?",a="Der Weberpass erstreckt sich zwischen dem Dunkelspeertroll-Außenposten Malaka'jin im Süden und dem weiter bergauf im Norden gelegenen Mirkfallonsee.",al={"weberpass lage","wo ist der weberpass","was verbindet der weberpass"}},{q="Warum heißt er Weberpass?",a="Die Straße verdankt ihren Namen der schieren Fülle an Spinnentieren, die diese Region bewohnen. Spinnen weben weite Labyrinthe aus glitzernder Seide hoch in den Bäumen und entlang der Felsvorsprünge, die den Weg säumen.",al={"warum weberpass","warum heißt es weberpass"}},{q="Welche Kreaturen streifen auf dem Pfad umher?",a="Abgesehen von den giftigen Spinnen, die ihre Netze über der Straße weben, begegnen Reisende häufig umherstreifenden Donnerechsen, Hochlandwiddern und gewöhnlichem Bergkleingetier.",al={"was lebt hier","weberpass bestien","mobs auf dem weberpass"}},{q="Ist der Weberpass sicher zu bereisen?",a="Er ist alles andere als sicher. Die einheimischen Raubtiere sind wild und territorial, und die Straße führt direkt am Hordelager Malaka'jin vorbei, was sie für Reisende der Allianz, die aus dem Brachland hinaufziehen, gefährlich macht.",al={"ist der weberpass gefährlich","kann allianz den weberpass nutzen"}}},fx={["4490b183"]={q="Was ist der Weberpass?",a="Der Weberpass ist eine gewundene Bergstraße im Steinkrallengebirge, die eine kritische Route vom Troll-Außenposten Malaka'jin in Richtung Mirkfallonsee darstellt. Er führt durch schroffe Gipfel und von Netzen bedeckte Baumkronen und dient als lebenswichtige Durchgangsstraße für Reisende, die tiefer in das Gebirge vordringen, flankiert von rauer Wildnis und aggressiven einheimischen Bestien.",al={"was ist der weberpass","hintergrund zum weberpass","weberpass steinkrallengebirge"}}},fp="14,242,26.465.0,31.145.0,32.195.0,31.166.0,33.205.0"}
P.entries["subzone:weeping-cave"] = {n="Die weinende Höhle",s="Die weinende Höhle ist eine widerwärtige, unterirdische Kaverne, die in den Hügeln der nordöstlichen Westlichen Pestländer liegt, direkt westlich des Thondroril. Einst ein natürliches Höhlensystem, sickert nun giftige Seuche durch das Gestein und es wimmelt von grotesken Pilzbestien und Schlämmen.",h="Die weinende Höhle ist eine widerwärtige, unterirdische Kaverne, die in den Hügeln der nordöstlichen...",kw={"faulender schrecken","schlamm","verfallenes ungetüm","the husk","thondroril","die weinende höhle","westliche pestländer"},ang={["class:Druid"]="Die weinende Höhle stellt eine groteske Perversion der natürlichen Welt dar, in der die unterirdische Flora und elementare Energien durch die Seuche des Untods vollkommen zu gewalttätigen Monstrositäten verdorben wurden."},sec={{t="Eine Höhle der Fäulnis",b="In die zerklüfteten Klippen oberhalb des Thondroril gehauen, verdankt Die weinende Höhle ihren Namen dem stetigen Tropfen von Feuchtigkeit durch ihre felsige Decke – Wasser, das längst faulig und verdorben ist. Die Seuche der Geißel hat das darüberliegende Erdreich vollkommen durchdrungen und lässt giftigen Unrat in die Finsternis hinabfließen. Im Inneren streifen faulende Schrecken, verfallende Ungetüme und ätzende Schlämme durch die feuchten Tunnel, begleitet von einem rätselhaften, verderbten Elementarwesen, das schlicht als The Husk bekannt ist."}},faq={{q="Wo befindet sich Die weinende Höhle?",a="Die weinende Höhle liegt im nordöstlichen Winkel der Westlichen Pestländer, eingebettet in die felsigen Hänge direkt westlich des Thondroril nahe der Grenze zu den Östlichen Pestländern.",al={"die weinende höhle ort","wo ist die weinende höhle","die weinende höhle finden"}},{q="Welche Kreaturen hausen in der Höhle?",a="Die Höhle wird von schlurfenden, pflanzenartigen Abscheulichkeiten heimgesucht – wie etwa verfallenden Ungetümen und faulenden Schrecken – sowie von giftigen, kriechenden Schlämmen und dem seltenen, gepeinigten Elementar namens The Husk.",al={"die weinende höhle monster","was ist in der weinenden höhle","die weinende höhle mobs"}},{q="Warum heißt sie Die weinende Höhle?",a="Von der Decke der Höhle tropft unaufhörlich Feuchtigkeit herab, was ihr das Aussehen von weinendem Stein verleiht. Durch die Nachwirkungen der Seuche hat sich das herabsickernde Wasser jedoch in eine ranzige, eitrige Flüssigkeit verwandelt, die ein virulentes Pilzwachstum nährt.",al={"warum heißt es die weinende höhle","die weinende höhle namensbedeutung"}},{q="Wer ist The Husk?",a="The Husk ist ein seltener, verderbter Elementar tief im Inneren der weinenden Höhle, verzerrt und verdreht durch die anhaltende alchemistische Seuche, die die umliegende Erde und das Wasser infiziert hat.",al={"the husk","the husk die weinende höhle","the husk rar"}}},fp="12,256,12.485.0,34.189.0,37.198.0,34.226.0,16.188.0"}
P.entries["subzone:wellspring-lake"] = {n="Quellsee",s="Der Quellsee ist ein ruhiges Süßwassergewässer hoch in den Ästen von Teldrassil, nordöstlich von Darnassus gelegen. Gespeist von natürlichen Quellen, die tief aus dem Inneren des Weltenbaums entspringen, nährt sein Wasser den sich dahinschlängelnden Quellfluss. Einst ein friedlicher Rückzugsort für nachtelfische Fischer, sind die Ufer des Sees der wachsenden Verderbnis anheimgefallen, die Teldrassils Tierwelt aufwühlt.",h="Der Quellsee ist ein ruhiges Süßwassergewässer hoch in den Ästen von Teldrassil, nordöstlich von Darnassus...",kw={"darnassus","kaldorei","nachtsäbler","die lichtung des orakels","teldrassil","holzkolosse","wellspringsee","quellfluss"},ang={["class:Druid"]="Druiden erforschen die aufgebrachten Holzkolosse und Bestien nahe dem Quellsee, um den Ursprung der unnatürlichen Krankheit zu ergründen, die sich durch Teldrassils Gewässer und Erdreich ausbreitet.",["race:NightElf"]="Für die Kaldorei ist der Verfall friedlicher Haine wie des Quellsees zu gefährlichen Monsterhöhlen eine schmerzhafte Mahnung daran, dass mit ihrem jungen Weltenbaum etwas zutiefst im Argen liegt."},sec={{t="Eine verdorbene Zuflucht",b="Unter dem Blätterdach zwischen Darnassus und der Lichtung des Orakels gelegen, wurde der Quellsee von den Kaldorei lange Zeit als ruhige Oase zum Angeln und Nachdenken geschätzt. Sein klares Wasser stammt aus unterirdischen Quellen, die durch die kolossalen Äste des Weltenbaums fließen, und fließt dann nach Norden durch den Quellfluss ab. In jüngster Zeit hat jedoch eine heimtückische Fäulnis begonnen, die umliegende Wildnis zu befallen. Aggressive Spinnen, herumstreifende Nachtsäbler und aufgebrachte Holzkolosse streifen nun an den Ufern umher, was den einst idyllischen Teich zu einem gefährlichen Ort für unvorsichtige Reisende macht."}},faq={{q="Wo befindet sich der Quellsee?",a="Der Quellsee liegt im Norden von Teldrassil, nordöstlich der Hauptstadt Darnassus und direkt südöstlich der Lichtung des Orakels.",al={"wo ist der wellspringsee","wellspringsee ort","weg zum wellspringsee"}},{q="Woher kommt das Wasser des Sees und wohin fließt es?",a="Der See wird von natürlichen Quellen gespeist, die tief aus den Wurzeln und dem Holz von Teldrassil selbst aufsteigen. Das überschüssige Wasser fließt in den Quellfluss ab, der nach Norden an den Rand des Baumes fließt.",al={"wohin fließt der wellspringsee ab","quelle des wellspring","wasserquelle des wellspringsees"}},{q="Warum ist das Gebiet um den Quellsee gefährlich?",a="Obwohl es früher ein ruhiger, von Anglern der Kaldorei geschätzter Ort war, hat die sich über den Weltenbaum ausbreitende Verderbnis die dortigen Bestien in den Wahnsinn getrieben. Herumstreifende Nachtsäbler, riesige Webwaldspinnen und verdorbene Rindenborken-Holzkolosse lauern nun am Ufer.",al={"was lebt am wellspringsee","wellspringsee gegner","warum ist der wellspringsee feindselig"}},{q="Wer versammelte sich früher am Quellsee?",a="Einheimische Nachtelfenfischer suchten den See oft zur stillen Einkehr und zum Angeln auf, bevor die jüngste Fäulnis die Tierwelt aufbrachte und die Ufer gefährlich machte.",al={"geschichte des wellspringsees","see der nachtelfen-fischer"}}},fx={f7f79729={q="Was ist der Quellsee?",a="Der Quellsee ist ein kleiner See, eingebettet in die Zweige von Teldrassil, nordöstlich von Darnassus und südöstlich der Lichtung des Orakels. Gespeist von einer natürlichen Quelle, die tief im Weltenbaum selbst verborgen liegt, fließen seine frischen Wasser in den Quellfluss und nähren das umliegende Waldgebiet.",al={"was ist der quellsee","quellsee teldrassil","über den quellsee"}},ce819020={q="Warum wurde der Quellsee verlassen?",a="Nachtelfische Fischer bevorzugten einst die friedlichen Ufer des Sees, aber die zunehmende Verderbnis im gesamten Weltenbaum vertrieb sie. Verderbte Holzlinge leben nun im Wasser, und aggressive Nachtsäbler und Spinnen durchstreifen die umliegende Wildnis, was friedliche Besuche unmöglich macht.",al={"warum wurde der quellsee verlassen","quellsee fischer","warum verließen fischer den quellsee"}},["0645470a"]={q="Ist der Quellsee gefährlich?",a="Ja. Obwohl er einst ein friedlicher Angelrückzugsort war, wurde der See von feindseligen, verderbten Holzlingen in Anspruch genommen. Das umliegende Gelände bietet ebenfalls keine Sicherheit, da es von räuberischen Nachtsäblern und Webholzspinnen befallen ist, die im Unterholz umherstreifen.",al={"ist der quellsee gefährlich","quellsee sicher","gefahren am quellsee"}},["4ed9a160"]={q="Warum heißt er Quellsee?",a="Der See hat seinen Namen von seiner Quelle: einem natürlichen Quellwasser, das tief aus den Wurzeln und der Erde von Teldrassil gespeist wird. Er dient wiederum als Quellgebiet des Quellflusses und belebt die zentralen Wasserwege der Zweige.",al={"warum heißt er quellsee","ursprung des namens quellsee","bedeutung des namens quellsee"}}},fp="15,384,16.584.0,33.127.0,45.193.0,49.252.0,38.161.0"}
P.entries["subzone:wellspring-river"] = {n="Quellfluss",s="Der Quellfluss entspringt einer natürlichen Quelle in Teldrassil und fließt aus dem Quellsee nach Norden, bis er in einem gewaltigen Wasserfall von den Ästen tief hinab in das Meer stürzt. Einst eine friedliche Süßwasserquelle für das Ökosystem des Weltenbaums, sind seine Ufer aufgrund aufgewühlter einheimischer Wildtiere gefährlich geworden.",h="Der Quellfluss entspringt einer natürlichen Quelle in Teldrassil und fließt aus dem Quellsee nach Norden, bis...",kw={"kaldorei","teldrassil","timberlinge","wasserfall","wellspringsee","quellfluss"},ang={["class:Druid"]="Der verdorbene und wahnsinnige Zustand der heimischen Timberlinge des Flusses ist ein beunruhigendes Zeichen für die wachsende Fäulnis, die sich durch Teldrassils Ökosystem schleicht.",["race:NightElf"]="Die Süßwasserläufe, die aus dem Herzen von Teldrassil fließen, stehen für die Lebenskraft der neuen Heimat der Kaldorei, weshalb die Unruhe an ihren Ufern zutiefst besorgniserregend ist."},sec={{t="Wasser des Weltenbaums",b="Genährt von den tiefen natürlichen Quellen inmitten der Äste von Teldrassil, führt der Quellfluss Wasser aus dem Quellsee nach Norden über den üppigen Waldboden, ehe er spektakulär über den Rand des großen Baumes in das Meer hinabfällt. Trotz der ruhigen Umgebung werden die Flussufer zunehmend unsicher. Die Timberlinge, die am Wasser hausen, sind wahnsinnig und feindselig geworden und greifen Reisende sowie Druiden heftig an, die versuchen, sich dem Flussufer zu nähern."}},faq={{q="Wohin führt der Quellfluss?",a="Der Quellfluss fließt aus dem Quellsee nach Norden. Schließlich erreicht er den Rand von Teldrassils Krone und stürzt über den Rand in einem enormen Wasserfall hinab, der bis in den umgebenden Ozean fällt.",al={"wohin fließt der fluss","der wellspring ziel","wohin führt der wellspring"}},{q="Warum greifen die Timberlinge am Fluss die Leute an?",a="Die Timberlinge entlang des Quellflusses sind unberechenbar und rasend geworden und wenden sich gegen jeden, der in ihre Nähe wandert. Diese Aggression ist Teil einer größeren Störung, die sich durch Teldrassils Tier- und Pflanzenwelt ausbreitet und die einheimischen Druiden der Nachtelfen beunruhigt.",al={"warum sind timberlinge aggressiv","rasende timberlinge wellspring","warum timberlinge feindselig"}},{q="Woher stammt das Wasser im Fluss?",a="Der Fluss wird direkt aus dem Quellsee gespeist, der wiederum von einer natürlichen Süßwasserquelle versorgt wird, die tief aus dem lebendigen Stamm und den Ästen des Weltenbaums entspringt.",al={"wellspring wasserquelle","woher kommt das wasser des wellsprings"}}},fx={cd3e3593={q="Was ist der Quellfluss?",a="Der Quellfluss ist ein lebenswichtiger Süßwasserstrom, der durch Teldrassil fließt. Er entspringt einer natürlichen Quelle tief in den Zweigen des Weltenbaums, fließt nach Norden aus dem Quellsee ab und trägt sein Wasser in Richtung der nördlichen Klippen, wo es schließlich über den massiven Rand der Baumkrone in einem atemberaubenden Wasserfall in die darunter liegende See stürzt.",al={"was ist der quellfluss","erzähl mir etwas über den quellfluss","hintergrund zum quellfluss"}},fd48f2c1={q="Warum heißt er Quellfluss?",a="Der Fluss hat seinen Namen von seinem Ursprung: einer natürlichen Quelle und einem tiefen Quellwasser, das hoch in der Krone von Teldrassil liegt. Die klaren Wasser fließen direkt aus dem Quellsee und dienen als eine der primären Arterien, die den umliegenden Wald mit Feuchtigkeit versorgen, bevor sie über den Rand des großen Baumes stürzen.",al={"warum heißt er quellfluss","bedeutung des namens quellfluss","ursprung des namens quell"}}},fp="16,318,24.486.0,37.221.0,57.249.0,44.173.0"}
P.entries["subzone:westbrook-garrison"] = {n="Weststromgarnison",s="Die Weststromgarnison ist ein Außenposten der Wache von Sturmwind am westlichen Rand des Walds von Elwynn nahe der Grenze zu Westfall. Besetzt von einer überarbeiteten, unterversorgten Notbesatzung unter Stellvertreter Rainer, dient sie als erste Verteidigungslinie des Reichs gegen die vordringenden Flusstatzengnolle und Gesetzlose.",h="Die Weststromgarnison ist ein Außenposten der Wache von Sturmwind am westlichen Rand des Walds von Elwynn...",kw={"stellvertreter rainer","wald von elwynn","der waldrand","hogger","marschall dughan","flusstatzen","weststromgarnison","westfall"},ang={["class:Warrior"]="Die bedrängten Wachen an der Weststromgarnison stehen stellvertretend für ein überdehntes Königreich, das die Raubtiere der Wildnis mit schierem Mut in Schach hält, und bieten reichlich geradlinige, harte Arbeit beim Vernichten der Gnoll-Kriegstrupps.",["faction:Alliance"]="Für Champions der Allianz, die aus Elwynn nach Westfall aufbrechen, ist das Sichern des Umkreises von Weststrom und das Einfordern des Kopfgelds auf Hogger unerlässlich, um die Westgrenzen des Kernlands zu schützen."},sec={{t="Ein bedrängter Grenzposten",b="Dort gelegen, wo sich der Wald von Elwynn in Richtung Westfall lichtet, ist die Weststromgarnison ein wichtiger, aber schwer kämpfender Wachposten. Da ein Großteil der Armee von Sturmwind in Übersee gebunden oder durch die politische Trägheit in der Hauptstadt blockiert ist, leidet der Außenposten unter akutem Personalmangel. Stellvertreter Rainer und seine Handvoll Wachen müssen die westlichen Straßen patrouillieren und sich gleichzeitig gegen dreiste Diebe sowie die bösartigen Flusstatzengnolle zur Wehr setzen, die die südlichen Wälder überrannt haben. Da er von Marschall Dughan in Goldhain keine formellen Verstärkungen erhält, verlässt sich der Posten fast ausschließlich auf reisende Abenteurer, um die Hauptstraße zu sichern."},{t="Die Bedrohung vom Waldrand",b="Die größte Bedrohung für die Weststromgarnison geht von der wachsenden Gnollpräsenz südlich vom Waldrand aus. Die Rudel sind inzwischen dreist genug geworden, unter Führung des gefürchteten Gnoll-Häuptlings Hogger direkte Überfälle auf Versorgungslinien und Höfe zu verüben. In Unterzahl und von der schieren Stärke von Hoggers Streitkräften überwältigt, hat die Garnison auf ihrem Gelände ein hohes Kopfgeld ausgeschrieben, in der verzweifelten Suche nach fähigen Kämpfern, die bereit sind, in die Hügel vorzudringen und die Bestie zu erledigen, bevor sie weiter nach Osten vordringt."}},faq={{q="Warum ist die Weststromgarnison so unterbesetzt?",a="Der Großteil der Armee von Sturmwind ist im Ausland stationiert, und politische Unentschlossenheit im Adelshaus der Hauptstadt hat die regionalen Garnisonen um frische Truppen und Nachschub gebracht. Die Befehlshaber der Weststromgarnison müssen sich stark auf wandernde Abenteurer verlassen, um das Defizit auszugleichen.",al={"warum so wenige wachen","weststrom verstärkung","stellvertreter rainer truppenmangel"}},{q="Wer hat das Kommando in der Garnison?",a="Stellvertreter Rainer leitet die Operationen in der Weststromgarnison. Er untersteht direkt Marschall Dughan in Goldhain, auch wenn seine Bitten um zusätzliche Soldaten größtenteils unbeantwortet blieben.",al={"wer befehligt die weststromgarnison","stellvertreter rainer rolle","weststrom kommandant"}},{q="Welchen Bedrohungen sieht sich die Garnison gegenüber?",a="Die Garnison hat es mit herumstreifenden Banditen zu tun, die aus Westfall herüberschwappen, sowie mit den wilden Flusstatzengnollen, die in den umliegenden Wäldern lagern und von ihrem gefährlichen Häuptling Hogger angeführt werden.",al={"bedrohungen weststrom","gnolle weststrom","wer greift weststromgarnison an"}},{q="In welcher Beziehung stehen Weststrom und Westfall zueinander?",a="Die Weststromgarnison ist der letzte Außenposten im Wald von Elwynn an der westlichen Straße vor der Brücke nach Westfall und schützt die Grenze vor der Gesetzlosigkeit, die aus dem Westen aufkeimt.",al={"liegt weststrom in westfall","grenze nach westfall"}}},fx={["2e1647ed"]={q="Was ist die Weststromgarnison?",a="Die Weststromgarnison ist eine Kaserne der Wache von Sturmwind, die nahe dem Waldrand an der westlichen Grenze des Waldes von Elwynn steht. Direkt auf der anderen Seite des Flusses von Westfall gelegen, bewacht dieser militärische Außenposten die Hauptstraße, die das Kernland der Hauptstadt mit den westlichen Ebenen verbindet. Obwohl sie mit einem robusten Wachturm und einer Kaserne befestigt ist, dient sie derzeit als letzte, kämpfende Verteidigungslinie, um lokale Gehöfte vor Gesetzlosen und wilden Gnollen zu schützen.",al={"was ist die weststromgarnison","weststromgarnison wald von elwynn","über die weststromgarnison"}},["9e78a278"]={q="Ist die Weststromgarnison gefährlich?",a="Die Garnison selbst bleibt ein sicherer Zufluchtsort, der von der Wache von Sturmwind gehalten wird, aber die umliegende Wildnis ist gefährlich. Die Wälder direkt im Süden wimmeln nur so vor dem bösartigen Gnollrudel der Flusspfoten, angeführt von dem monströsen Häuptling Hogger. Zudem dringen Defias-Banditen aus Westfall über die Grenze, um Reisende zu überfallen, was jede unbegleitete Reise außerhalb des unmittelbaren Geländes der Garnison riskant macht.",al={"ist weststromgarnison gefährlich","gefahr bei weststromgarnison","ist weststromgarnison sicher"}}},fp="18,300,25.608.0,27.516.0,42.261.0,34.192.0,36.176.0,52.187.0"}
P.entries["subzone:westfall-lighthouse"] = {n="Der Leuchtturm von Westfall",s="Auf einer felsigen Insel vor der südwestlichen Küste von Westfall gelegen, warnte der Leuchtturm von Westfall einst Schiffe vor den gefährlichen Untiefen des großen Meeres. Heute gibt es keine lebenden Wärter mehr; sie wurden bei einem brutalen Angriff ausgelöscht, der von dem berüchtigten Murloc Trübauge der Alte angeführt wurde, sodass nur der Geist von Kapitän Grausohn zurückblieb, um über die Flamme zu wachen.",h="Auf einer felsigen Insel vor der südwestlichen Küste von Westfall gelegen, warnte der Leuchtturm von Westfall...",kw={"leuchtfeuer","kapitän grausohn","küste","flamme","leuchtturm","murloc","trübauge der alte","westfall"},ang={["faction:Alliance"]="Der Leuchtturm steht als deutliches Symbol für den schwindenden Einfluss von Sturmwind, wo isolierte Diener des Königreichs ohne militärische Unterstützung den wilden Küstenbestien überlassen wurden."},sec={{t="Ein Leuchtfeuer im Nebel",b="An den tückischen südwestlichen Klippen von Westfall erbaut, bot der Leuchtturm lange Zeit sicheres Geleit für Schiffe, die die Küste nahe Sturmwind befuhren. Als jedoch Recht und Ordnung in der gesamten Region zusammenbrachen und die königlichen Patrouillen schwanden, nahmen die Gefahren an der Küste ungehindert zu. Ursprünglich pflegte eine Familie von Wärtern das Leuchtfeuer, doch aggressive Murloc-Stämme vertrieben sie ins Landesinnere. Obwohl sie mutig zurückkehrten, um den Turm wieder zu entzünden, scharte der berüchtigte Murloc-Räuber Trübauge der Alte seine Artgenossen zu einem zweiten, erbarmungslosen Angriff um sich, bei dem die Familie niedergemetzelt und das Leuchtfeuer gelöscht wurde."},{t="Die geisterhafte Wacht",b="Nach der Tragödie blieb das Leuchtfeuer nicht gänzlich verlassen. Die Spukgestalt von Kapitän Grausohn verweilt nun auf der felsigen Erhebung, gebunden an den Ort, an dem er hilflos das Ende der Familie mitansehen musste. Unfähig zu ruhen, solange das Leuchtfeuer erloschen ist und die Küste von Monstern wimmelt, heuert Grayson vorbeikommende Abenteurer an, um Öl von den Erntegolems zu sammeln, damit die Flamme weiter brennt, und um Trübauge der Alte zur Strecke zu bringen, um die gefallenen Wärter zu rächen."}},faq={{q="Warum ist der Leuchtturm von Westfall verlassen?",a="Die Menschenfamilie, die den Leuchtturm betreute, wurde von einheimischen Murlocs vertrieben. Als sie zurückkehrten, um das Leuchtfeuer wieder zu entzünden, führte Trübauge der Alte einen zweiten Überfall an, bei dem die gesamte Familie vor den Augen von Kapitän Grausohn massakriert wurde.",al={"was geschah mit den wärtern","wer lebte am leuchtturm","warum liegt er in trümmern"}},{q="Wer ist Kapitän Grausohn?",a="Kapitän Grausohn ist ein Geist, der auf der Insel vor dem Leuchtturm spukt. Gebunden an Schuldgefühle und Pflichtbewusstsein, nachdem er den Tod der Wärter miterlebt hat, beauftragt er mutige Reisende damit, Öl zu beschaffen, um das Leuchtfeuer am Brennen zu halten, und die verantwortlichen Küstenmurlocs zu jagen.",al={"geist am leuchtturm","wer ist der geist","kapitän grausohn lore"}},{q="Wer ist Trübauge der Alte?",a="Trübauge der Alte ist ein ungewöhnlich gerissener und bösartiger Murloc-Häuptling, der die Küste von Westfall durchstreift. Er scharte die Küstenstämme um sich, um den Leuchtturm zu überrennen und die Wärter abzuschlachten.",al={"murk-eye","murloc-boss","wer tötete die wärter"}},{q="Funktioniert der Leuchtturm noch?",a="Die mechanische Laterne funktioniert immer noch und wirft nachts einen weithin sichtbaren Lichtstrahl über das Meer, während Kapitän Grausohn Reisende um das Öl bittet, das nötig ist, um das Feuer am Brennen zu halten.",al={"geht das licht an","leuchtfeuer funktionstüchtig"}}},fx={fe113f6d={q="Was ist der Leuchtturm von Westfall?",a="Der Leuchtturm von Westfall ist ein einsames Küstenfeuer, das auf einer felsigen Insel vor der südwestlichen Küste von Westfall steht. Er wurde erbaut, um Seeleute sicher an den tückischen Untiefen vom Das große Meer vorbeizuleiten, und steht nun weitgehend verlassen da, während er über eine Küste wacht, die von grausamen Küstenmurlocs überrannt wird.",al={"was ist der leuchtturm von westfall","der leuchtturm von westfall","über den leuchtturm von westfall"}},db6e5f33={q="Was ist am Leuchtturm von Westfall geschehen?",a="Der Leuchtturm wurde ursprünglich von einem menschlichen Wärter und seiner Familie betreut. Der berüchtigte Murloc Trübauge der Alte vertrieb sie, doch als sie mutig zurückkehrten, um das Leuchtfeuer wieder zu entzünden, führte Trübauge der Alte einen brutalen zweiten Angriff an. Die Familie wurde unter dem Blick des Geistes von Kapitän Grausohn hilflos abgeschlachtet, wodurch der Turm unbemannt blieb.",al={"geschichte vom leuchtturm von westfall","was ist hier geschehen","tragödie am leuchtturm"}},c45dc608={q="Ist der Leuchtturm von Westfall gefährlich?",a="Während die Leuchtturminsel selbst unter der geisterhaften Aufsicht von Kapitän Grausohn relativ ruhig ist, wimmelt es in den umliegenden Gewässern und an den Stränden von bösartigen Murlocs, darunter der berüchtigte Trübauge der Alte. Unvorsichtige Reisende können leicht von ihnen umschwärmt werden, wenn sie unbedacht hinüberwaten.",al={"ist der leuchtturm von westfall sicher","gefahr am leuchtturm von westfall","gibt es feinde am leuchtturm von westfall"}}},fp="19,333,20.561.0,17.438.1,41.213.0,23.244.0,20.183.0,35.184.0"}
P.entries["subzone:whelgar-s-excavation-site"] = {n="Whelgars Ausgrabungsstätte",s="Whelgars Ausgrabungsstätte ist eine archäologische Zwergenausgrabung in den westlichen Ausläufern des Sumpflands. Die Expedition sollte uralte Titanenrelikte und prähistorische Geheimnisse ans Tageslicht bringen, endete jedoch in einer Katastrophe, als bösartige gescheckte Raptoren den Steinbruch überrannten. Die überlebenden Ausgräber sitzen nun auf einem Felsvorsprung oberhalb der Ausgrabung fest, abgeschnitten von ihren Funden.",h="Whelgars Ausgrabungsstätte ist eine archäologische Zwergenausgrabung in den westlichen Ausläufern des...",kw={"ausgrabungsstätte","ausgrabung","fossilien","raptoren","sarltooth","sumpfland","whelgar"},ang={["profession:Mining"]="Die gewaltigen freiliegenden Steinbruchwände und das ausgegrabene Grundgestein bieten erstklassige Adern für Bergleute, die mutig genug sind, unter dem Knurren hungriger Raptoren zu arbeiten.",["race:Dwarf"]="Jede an wilde Bestien aufgegebene Ausgrabung ist eine Beleidigung für die Forscherliga. Die Forschungen von Whelgar zurückzuholen bedeutet, Euer Erbe zu verteidigen und gestohlene Titanengeheimnisse zurückzufordern."},sec={{t="Eine ruinierte Expedition",b="Angefeuert von Zwergenausgräbern auf der Suche nach uralten Fossilien und irdenen Geheimnissen schlug die Ausgrabung einen gewaltigen Steinbruch zwischen dem Hafen von Menethil und Dun Modr in den Fels. Das Ausgraben prähistorischer Überreste zog jedoch den Zorn einheimischer gescheckter Raptoren auf sich. Überrannt und schlecht ausgerüstet zogen sich die Archäologen auf einen Felsvorsprung oberhalb der Ausgrabungsstätte zurück und ließen ihre Zelte, Werkzeuge und ausgegrabenen Relikte verstreut zwischen den lauernden Raubtieren zurück."}},faq={{q="Warum wurde die Ausgrabungsstätte verlassen?",a="Die Zwergenausgräber störten versehentlich das Revier aggressiver gescheckter Raptoren. Von diesen wilden Kreaturen überrannt, suchte die überlebende Mannschaft Zuflucht auf einem Felsvorsprung oberhalb der Ausgrabungsstätte.",al={"warum ist sie verlassen","was geschah mit der ausgrabungsstätte","warum die ausgrabung verlassen wurde"}},{q="Wonach suchten die Zwerge hier?",a="Die Zwerge gruben nach prähistorischen Fossilien und unterirdischen Artefakten in der Hoffnung, uralte Hinweise auf ihr Titanenerbe und die ferne Vergangenheit der Welt aufzudecken.",al={"wonach graben sie","zweck der ausgrabung","ziel von whelgars ausgrabungsstätte"}},{q="Welche Bedrohungen durchstreifen die Ausgrabungsstätte jetzt?",a="Auf dem Boden des Steinbruchs und auf den umliegenden Felsvorsprüngen wimmelt es von gescheckten Raptoren, darunter auch der gefürchtete Raptor Sarltooth.",al={"was befindet sich in der ausgrabungsstätte","ausgrabungsstätte mobs","raptoren im sumpfland"}},{q="Wohin gingen die überlebenden Ausgräber?",a="Die überlebende Ausgrabungsmannschaft, darunter Ausgrabungsleiter Whelgar, sitzt auf einem Felsvorsprung oberhalb der Ausgrabungsstätte fest, wo sie nach tapferen Abenteurern sucht, um ihre verlorenen Forschungen zu bergen.",al={"wo ist whelgar","wo sind die zwerge","aufenthaltsort der überlebenden der ausgrabungsstätte"}}},fx={["4eb1142c"]={q="Was ist Whelgars Ausgrabungsstätte?",a="Whelgars Ausgrabungsstätte ist eine archäologische Grabungsstätte der Zwerge in den Ausläufern vom Sumpfland, östlich vom Hafen von Menethil. Sie wurde von zwergischen Entdeckern gegründet, die nach antiken Relikten und Fossilien suchten, doch leider ist die Stätte in schwere Zeiten geraten, nachdem aggressive einheimische Raubtiere die Arbeiter aus ihren eigenen Gräben vertrieben haben.",al={"whelgars ausgrabungsstätte","whelgar grabungsstätte","was ist whelgars ausgrabungsstätte"}},["65697e7b"]={q="Was ist bei Whelgars Ausgrabungsstätte geschehen?",a="Was als vielversprechendes archäologisches Unterfangen der Zwerge begann, nahm eine katastrophale Wendung, als die Grabungen die lokale Tierwelt aufschreckten. Bösartige gefleckte Raptoren drangen in den Steinbruch ein und überwältigten das Lager, was die überlebenden Ausgräber zwang, ihre Werkzeuge, Relikte und laufenden Forschungen zurückzulassen und sich auf sichereres Gelände zu flüchten.",al={"geschichte von whelgars ausgrabungsstätte","geschichte whelgars ausgrabungsstätte","was ist bei der grabungsstätte geschehen"}},["23dbaaa4"]={q="Warum heißt sie Whelgars Ausgrabungsstätte?",a="Die Grabungsstätte trägt den Namen von Ausgrabungsleiter Whelgar, dem Zwerg, der die Expedition leitet. Er und die überlebende Mannschaft haben auf einem Grat Zuflucht gesucht, der den raptorenverseuchten Steinbruch überblickt.",al={"wer ist whelgar","namensherkunft whelgar","warum whelgar grabungsstätte"}}},fp="25,349,19.434.0,38.196.0,39.169.0,34.113.0,38.170.0"}
P.entries["subzone:whispering-forest"] = {fx={d118db82={q="Was ist der Flüsternde Wald?",a="Der Flüsternde Wald ist ein abgeschiedenes, nebelverhangenes Waldgebiet, das hinter den steilen westlichen Bergen von Tirisfal liegt. Vom Rest der Region durch die Höhen des Northface Rock getrennt, ist er eine unheimliche, ungezähmte Wildnis, die kranke Wildtiere, geheimnisvolle Feenringe, vergessene Ruinen und abgelegene Bergseen beherbergt, die von gewöhnlichen Reisewegen abgeschnitten sind.",al={"was ist der flüsternde wald","überlieferung vom flüsternden wald","erzähl mir vom flüsternden wald"}},["4326a394"]={q="Ist der Flüsternde Wald gefährlich?",a="Ja, sehr sogar. Neben seinen kranken und verseuchten Wildtieren sind die Klippen und Gewässer von vertriebenen Vile Fin-Murlocs und dem monströsen untoten Threshadon Blightsculler verseucht. Weiter landeinwärts suchen gedankenlose Untote die Ruinen von Schattental um ein gefallenes nekromantisches Kristallfragment heim, während feindselige Tarnished-Kultisten in den verheerten Wäldern lauern.",al={"gefahr im flüsternden wald","ist der flüsternde wald sicher","bedrohungen im flüsternden wald"}}}}
P.entries["subzone:whispering-gardens"] = {n="Flüstergärten",s="Die Flüstergärten erstrecken sich über den terrassierten Hang direkt südlich des Scharlachroten Klosters im nordöstlichen Tirisfal. Einst ein Ort stiller Kontemplation, wurden sie zum Schauplatz eines erbitterten Zusammenstoßes zwischen frühen Verteidigern des Kreuzzugs und einem gewaltigen Heer der Geißel. Heute patrouillieren Kreuzzügler über die überwucherten Pfade, während die leisen Stimmen der Gefallenen noch immer in der Luft liegen.",h="Die Flüstergärten erstrecken sich über den terrassierten Hang direkt südlich des Scharlachroten Klosters im...",kw={"scharlachroter kreuzzug","das scharlachrote kloster","geißel","tirisfal","flüstergärten","geflüster"},ang={["class:Priest"]="Priester, die über die Terrassen wandeln, können die verbliebenen spirituellen Überreste der heiligen Verteidiger spüren, die im Kampf gegen die Geißel ein gewaltsames Ende fanden und deren Seelen für immer an die Winde gebunden sind.",["race:Undead"]="Für die Verlassenen stellen die Gärten ein aktives Nest fanatischen scharlachroten Widerstands direkt vor den Toren von Tirisfal dar, heimgesucht von genau jenem Krieg, der Lordaeron zum Verhängnis wurde."},sec={{t="Eine im Nebel nachhallende Schlacht",b="Bevor sich der Scharlachrote Kreuzzug vollständig hinter die Festungsmauern des Klosters zurückzog, entbrannte an diesen terrassierten Hängen eine heftige Schlacht gegen eine herandrängende Armee von Untoten. Der Zusammenstoß forderte auf beiden Seiten unzählige Leben. In der Dämmerung berichten Reisende, die die Gärten durchqueren, von seltsamem, leisem Murmeln im Wind – man hält es für die ruhelosen Echos der Soldaten und Priester, die bei der Verteidigung der heiligen Stätten fielen."},{t="Außenposten der Kreuzzügler",b="Trotz der spukhaften Präsenz hält der Scharlachrote Kreuzzug eine aktive Wache über die Gärten aufrecht. Scharlachrote Späher, Magier und Bewahrer sichern die Pfade, um alle Eindringlinge abzufangen, die sich aus den tiefer gelegenen Gefilden nähern. Für die Fanatiker im nahe gelegenen Kloster dienen diese überwucherten Stufen sowohl als Bollwerk zur Verteidigung als auch als feierliche Mahnung an den unaufhörlichen Krieg gegen die Untoten."}},faq={{q="Wo befinden sich die Flüstergärten?",a="Die Flüstergärten liegen im nordöstlichen Tirisfal und bedecken den Hang unmittelbar südlich des Eingangs zum Scharlachroten Kloster.",al={"flüstergärten standort","wo liegen die flüstergärten","weg zu den flüstergärten"}},{q="Warum heißen sie Flüstergärten?",a="Der Name rührt von dem schwachen, geisterhaften Murmeln her, das in der Abenddämmerung zu hören ist. Man sagt, es seien die verbliebenen Geister der Verteidiger und Untoten, die in einer blutigen Schlacht an diesen Hängen gefallen sind.",al={"warum heißen sie flüstergärten","was ist das flüstern","flüstergärten name"}},{q="Welche Schlacht fand hier statt?",a="Hier fand eine verzweifelte Schlacht zwischen den frühen Truppen, aus denen der Scharlachrote Kreuzzug hervorging, und einer Invasionsarmee der Geißel statt. Die Kämpfer starben in Scharen, bevor die Geißel vor dem Kloster aufgehalten werden konnte.",al={"schlacht der flüstergärten","was geschah in den flüstergärten"}},{q="Wer kontrolliert die Gärten heute?",a="Der Scharlachrote Kreuzzug kontrolliert das Gelände. Scharlachrote Späher, Bewahrer und Magier patrouillieren über die Terrassen, um den südlichen Zugang zu ihrer Festung zu sichern.",al={"wer lebt in den flüstergärten","monster in den flüstergärten"}}},fx={["3774f1a6"]={q="Was sind die Flüstergärten?",a="Die Flüstergärten sind eine düstere Hangterrasse im nordöstlichen Tirisfal, direkt südlich des Eingangs zum Das Scharlachrote Kloster. Einst ein friedliches Gelände, dient die Terrasse nun als äußerer Verteidigungsposten und Bereitstellungsraum für die fanatischen Streitkräfte von The Scarlet Crusade, von wo aus sie die umliegenden Lichtungen überblicken.",al={"was sind die flüstergärten","überlieferung zu den flüstergärten","was ist mit den flüstergärten"}},["7713d5ca"]={q="Wie gefährlich sind die Flüstergärten?",a="Sie sind für jeden Außenstehenden extrem gefährlich. The Scarlet Crusade unterhält auf der gesamten Terrasse eine aktive Wache und stationiert Magier, Bewahrer und Späher auf den Pfaden. Getrieben von fanatischer Paranoia hinrichten sie jeden, der nicht auf ihre Sache vereidigt ist, beim ersten Anblick, da sie alle Außenstehenden als Träger der untoten Verderbnis betrachten.",al={"sind die flüstergärten gefährlich","gefahr in den flüstergärten","bedrohungen in den flüstergärten"}}},fp="18,364,28.432.0,16.379.0,41.143.0,43.180.0,28.211.0,29.156.0"}
P.entries["subzone:whispering-shore"] = {n="Die Flüsternde Küste",s="Die Flüsternde Küste ist ein düsterer Küstenabschnitt im Westen von Tirisfal, der knapp nördlich von Sollidens Bauernhof liegt. Einst ein ruhiger und ertragreicher Zufluchtsort für Lordaerons Fischer, wurden ihre kalten Gewässer seither von einem gewalttätigen Stamm von Murlocs überrannt.",h="Die Flüsternde Küste ist ein düsterer Küstenabschnitt im Westen von Tirisfal, der knapp nördlich von...",kw={"küste","angeln","muad","murloc","sollidens bauernhof","tirisfal","die flüsternde küste"},ang={["race:Undead"]="Für die Verlassenen, die das westliche Tirisfal sichern, stellt die Murloc-Plage an der Flüsternden Küste eine widerspenstige Bedrohung direkt an den Grenzen ihrer Besitztümer dar."},sec={{t="Ein zerstörter Zufluchtsort",b="Bevor der Dritte Krieg über das nördliche Lordaeron hereinbrach, war die Flüsternde Küste unter den Einheimischen als beliebter Fischerhafen bekannt, geschätzt für ihre ruhigen Gewässer und ihren reichen Fang. Heute brandet die eisige Gischt des großen Meeres an eine verlassene Küste, die ihrer friedvollen Vergangenheit beraubt wurde. Die Gewässer sind kalt und finster geworden, bar ihrer einstigen Fülle, und jeder unglückselige Reisende, der von den Hügeln hinabsteigt, riskiert, von revierbezogenen Küstenbewohnern überfallen zu werden."},{t="Die Murlocbedrohung",b="Der Strand wird nun unerbittlich von einer Gruppe feindseliger Murlocs beansprucht, die jeden rücksichtslos angreifen, der sich der Brandung nähert. Angeführt von einem wilden Häuptling namens Muad bewachen diese aquatischen Aasfresser das Seichtwasser und die Wattflächen aggressiv und stellen eine ständige Gefahr für die nahegelegenen Straßen und das nahe Sollidens Bauernhof dar."}},faq={{q="Wo befindet sich die Flüsternde Küste?",a="Die Flüsternde Küste liegt an der Westküste von Tirisfal, direkt nördlich von Sollidens Bauernhof.",al={"die stille küste standort","wo ist die stille küste","die stille küste karte"}},{q="Was befand sich vor der Geißel an der Flüsternden Küste?",a="In den Tagen des Königreichs Lordaeron war die Küste ein beliebter und friedvoller Ort für einheimische Fischer, angelockt von ihren fischreichen Küstengewässern.",al={"die stille küste geschichte","wofür wurde die stille küste genutzt","die stille küste vergangenheit"}},{q="Wer beherrscht die Flüsternde Küste jetzt?",a="Ein Stamm aggressiver Murlocs hat den Küstenabschnitt übernommen. Sie werden von einem besonders bösartigen Murloc-Häuptling namens Muad angeführt und greifen jeden an, der sich ans Wasser verirrt.",al={"wer lebt an der stillen küste","die stille küste feinde","die stille küste mobs"}},{q="Kann man an der Flüsternden Küste noch friedlich angeln?",a="Die Küste ist nicht länger der friedliche Zufluchtsort, der sie einst war. Ihre Gewässer sind kalt und dunkel, haben viel von ihrer einstigen Fülle verloren, und feindselige Murlocs bewachen die Uferlinie aggressiv.",al={"angeln an der stillen küste","die stille küste fische"}}},fx={a19e4211={q="Was ist die Flüsternde Küste?",a="Die Flüsternde Küste ist ein kalter, dunkler Küstenabschnitt entlang der westlichen Ausläufer von Tirisfal, gelegen direkt nördlich von Sollidens Bauernhof. Einst als ruhiger und ergiebiger Rückzugsort für lokale Fischer bekannt, ist die verheerte Küste seitdem dem Ruin und Chaos anheimgefallen und lässt wenig von den friedlichen Gewässern zurück, die das einfache Volk einst genoss.",al={"überlieferung zur flüsternden küste","was ist die flüsternde küste","erzähl mir von der flüsternden küste"}},["84b8417d"]={q="Ist die Flüsternde Küste gefährlich?",a="Ja, sie ist extrem gefährlich für unvorsichtige Reisende. Die Küste wird derzeit von einer feindseligen Bande gefräßiger Murlocs überrannt, die von dem bösartigen Muad angeführt wird. Diese Kreaturen greifen aggressiv jeden an, der zu nah an die Brandung herankommt, was die Küste für lebende Siedler unbewohnbar und für jeden, der entlang des westlichen Tirisfal reist, zu einer Gefahr macht.",al={"ist die flüsternde küste sicher","bedrohungen an der flüsternden küste","gefahr an der flüsternden küste"}},bea21c89={q="Warum wurde die Flüsternde Küste aufgegeben?",a="Nach dem Fall von Lordaeron an die Geißel und der Verderbnis von Tirisfal wurden die einst ergiebigen Fischgründe kalt, dunkel und unfruchtbar. Ohne friedliche Siedler, die die Küste instand hielten, zogen räuberische Murlocs ein und besetzten den Küstenstreifen, wodurch jeder vertrieben wurde, der gehofft hatte, zurückzukehren.",al={"warum ist die flüsternde küste ruiniert","was hat die flüsternde küste zerstört","warum wurde die flüsternde küste verlassen"}}},fp="16,263,14.468.0,17.299.0,38.111.0,59.136.0,38.171.0,54.183.0"}
P.entries["subzone:whitereach-post"] = {n="Weißgipfelposten",s="Der Weißgipfelposten ist ein kleines Lager der Horde, das am staubigen Schluchtpfad in Tausend Nadeln liegt. Als kleiner Stützpunkt in der Nähe von Camp E'thok bietet er Rast und wachsame Augen über die raue Wüstenstraße. Reisenden, die zwischen Feralas und den Salzebenen unterwegs sind, dient er als sicherer Außenposten der Horde unter den aufragenden Sandsteinsäulen.",h="Der Weißgipfelposten ist ein kleines Lager der Horde, das am staubigen Schluchtpfad in Tausend Nadeln liegt.",kw={"camp e'thok","horde-außenposten","kanati grauwolke","tauren","tausend nadeln","weißgipfelposten"},ang={["faction:Horde"]="Der Weißgipfelposten stellt einen wichtigen Rastplatz und Spähposten für Reisende der Horde dar, die die gefährlichen Schluchten von Tausend Nadeln durchqueren.",["race:Tauren"]="Taurenspäher helfen dabei, dieses Lager am Wegesrand zu sichern, und gewährleisten, dass Stammesmitglieder, die zwischen Mulgore, Feralas und Die schimmernde Ebene unterwegs sind, einen sicheren Ort zum Rasten haben."},sec={{t="Ein Stützpunkt in den Schluchten",b="Am ausgetretenen Pfad gelegen, der sich durch die Tiefen von Tausend Nadeln schlängelt, ist der Weißgipfelposten einer von mehreren bescheidenen Stützpunkten der Horde, die der rauen Landschaft abgerungen wurden. In unmittelbarer Nähe zu Camp E'thok gelegen, trägt der Posten dazu bei, eine verlässliche Präsenz am Schluchtboden aufrechtzuerhalten und das Reisen zwischen den windgepeitschten Mesas zu überwachen. Obwohl er nicht so befestigt ist wie Der große Aufzug oder größere Stammessiedlungen, dient er Kurieren, Spähern und Abenteurern, die das umkämpfte Ödland durchqueren, als unverzichtbare Zwischenstation."}},faq={{q="Was ist der Weißgipfelposten?",a="Der Weißgipfelposten ist ein kleiner Außenposten der Horde am Hauptpfad der Schlucht in Tausend Nadeln, unweit von Camp E'thok gelegen.",al={"weißgipfel","weißgipfellager","wo liegt der weißgipfelposten"}},{q="Welche Fraktion kontrolliert den Weißgipfelposten?",a="Er wird von der Horde kontrolliert und hauptsächlich von Taurenspähern unterhalten, die die Pfade der Schlucht im Auge behalten.",al={"gehört weißgipfel zur horde","fraktion des weißgipfelpostens"}},{q="Wer ist hier stationiert?",a="Der Posten wird von örtlichen Spähern und Wanderern der Horde besetzt, darunter der Taure Kanati Grauwolke, der über den Schluchtpass wacht.",al={"weißgipfel npcs","wer lebt am weißgipfelposten"}}},fp="15,351,27.506.0,24.134.0,39.105.0,32.131.0"}
P.entries["subzone:wild-shore"] = {n="Die wilden Ufer",s="Die wilden Ufer bilden die südlichste Küste des Schlingendorntals, an der der Dschungel auf die Wellen der Südlichen Meere trifft. Sie dienen den Blutsegelbukanieren als Aufmarschgebiet und Ankerplatz, deren Schiffe entlang der Untiefen vertäut liegen.",h="Die wilden Ufer bilden die südlichste Küste des Schlingendorntals, an der der Dschungel auf die Wellen der...",kw={"blutsegelbukaniere","beutebucht","gorlash","die insel jaguero","piraten","die südlichen meere","schlingendorntal","die wilden ufer"},ang={["class:Rogue"]="Die Lager und geankerten Schiffe der Blutsegel bieten Gelegenheiten zum Taschendiebstahl und die Chance, rivalisierende Haudegen zu beobachten, die sich außerhalb der Gesetze des Steamwheedle-Kartells bewegen."},sec={{t="Am Rande der Südlichen Meere",b="Entlang der Südspitze des Kontinents erstrecken sich Die wilden Ufer und markieren die Grenze, an der das Schlingendorntal in die südlichen Meere abfällt. Im Nordwesten liegt die befestigte Bucht von Beutebucht, während eine seichte Meeresstraße den Strand des Festlands von der Insel Jaguero im Osten trennt. Der Strand setzt sich nach Nordosten in Richtung des Kristallufers fort. Wegen ihrer abgeschiedenen Lage abseits der direkten Kanonen der Blackwater Raiders hat sich die Küste zu einer Hochburg piratischer Umtriebe und wilder Gefahren entwickelt."},{t="Piraten und Riesen",b="Die Küste wird stark von den Blutsegelbukanieren beansprucht, die ihre Holzschiffe in der Brandung ankern und am Strand Lager aufschlagen. Diese Haudegen nutzen die Strände, um Operationen vorzubereiten, Schmuggelgut zu lagern und Angriffe gegen ihre goblinischen Rivalen zu planen. Reisende müssen sich zudem mit den natürlichen Gefahren der Küste auseinandersetzen, darunter lauernde Bestien und Gorlash, ein kolossaler Meeresriese, der durch die Brandung stapft und jeden zerschmettert, der zu lange an der Flutlinie verweilt."}},faq={{q="Wo befinden sich Die wilden Ufer?",a="Die wilden Ufer bilden die südlichste Küstenlinie des Schlingendorntals in den Östlichen Königreichen. Sie liegen südlich von Beutebucht und blicken über die südlichen Meere hinüber zur Insel Jaguero.",al={"die wilden ufer ort","wo sind die wilden ufer","die wilden ufer karte"}},{q="Wer beherrscht Die wilden Ufer?",a="Die Blutsegelbukaniere beherrschen die Küstenlinie. Sie ankern mehrere ihrer Schiffe in den seichten Gewässern und unterhalten Lager entlang der Sandstrände.",al={"wer lebt an den wilden ufern","die wilden ufer fraktionen","die wilden ufer piraten"}},{q="Wer ist Gorlash?",a="Gorlash ist ein gewaltiger Meeresriese, der die Untiefen entlang der wilden Ufer durchstreift und sowohl unvorsichtige Seefahrer als auch am Strand umhergehende Piraten bedroht.",al={"gorlash riese","wer ist der riese am strand","gorlash die wilden ufer"}},{q="In welcher Beziehung stehen Die wilden Ufer zu Beutebucht?",a="Eine felsige Landzunge trennt Beutebucht von den wilden Ufern. Beutebucht dient als Festung der Blackwater Raiders und des Steamwheedle-Kartells, was Die wilden Ufer in der Nähe zu einem natürlichen Aufmarschgebiet für ihre geschworenen Feinde, die Blutsegelbukaniere, macht.",al={"beutebucht verbindung","die wilden ufer beutebucht"}}},fp="10,236,22.488.0,18.462.0,32.178.0,28.153.0,15.141.0,44.249.0"}
P.entries["subzone:wildbend-river"] = {n="Der Wildbend",s="Der Wildbend ist ein verderbtes Gewässer, das sich durch die südlichen Wälder der Dunkelküste nahe dem Hain der Uralten schlängelt. Er entspringt direkt den korrumpierten Höhen des Teufelswalds und trägt dämonisches Gift ins Meer, wodurch die umliegende Wildnis bedroht wird.",h="Der Wildbend ist ein verderbtes Gewässer, das sich durch die südlichen Wälder der Dunkelküste nahe dem Hain...",kw={"blutgiftbach","dunkelküste","teufelswald","der hain der uralten","verdorbenes wasser","der wildbend"},ang={["class:Druid"]="Druiden, die die ökologischen Folgen des Dritten Krieges erforschen, behalten den Fluss wachsam im Auge und beobachten, wie tief die Verderbnis des Teufelswalds in die flussabwärts gelegene Flora und Fauna vordringt.",["race:NightElf"]="Das aus dem Teufelswald herabstürzende, verschmutzte Wasser bedroht die uralten Wurzeln der Dunkelküste, weshalb die Flussufer den Hütern der Nachtelfen ständige Sorge bereiten."},sec={{t="Ein giftiger Gebirgsbach",b="Der Wildbend durchquert die südlichen Gefilde der Dunkelküste und fließt westwärts am heiligen Hain der Uralten vorbei, ehe er ins Meer mündet. Statt dem Wald saubere Nahrung zu spenden, bringt er Verderbnis aus den Bergen herab. Der Fluss ist die direkte Fortsetzung des Blutgiftbachs aus dem Teufelswald, stürzt über felsige Kämme und spült üble, korrumpierte Abflüsse in das Ökosystem der Dunkelküste. Die Nachtelfen überwachen seine Ufer aufmerksam und achten auf entstellte Wildtiere sowie das schleichende Vordringen der dämonischen Fäulnis."}},faq={{q="Warum ist der Wildbend verdorben?",a="Der Fluss entspringt hoch in den Bergen des Teufelswalds, wo er als Blutgiftbach bekannt ist. Der Teufelswald wurde während des Dritten Krieges völlig von dämonischer Magie durchtränkt, und dieses faulige Schmutzwasser ergießt sich über die Klippen als der Wildbend in die Dunkelküste.",al={"warum ist wasser verdorben","wildbend gift","dunkelküste schmutziges wasser"}},{q="Wohin fließt der Fluss?",a="Er stürzt über die östlichen Bergkämme herab, die den Teufelswald von der Dunkelküste trennen, schlängelt sich durch die südliche Dunkelküste nahe dem Hain der Uralten und mündet schließlich ins Verhüllte Meer.",al={"wo ist der wildbend","wildbend verlauf","wildbend lage"}},{q="Beeinträchtigt der Fluss den Hain der Uralten?",a="Der Fluss fließt nahe am Hain der Uralten vorbei und stellt eine ständige Umweltbedrohung für die dort verwurzelten uralten Beschützer dar. Die Nachtelfen arbeiten unermüdlich daran, die Verderbnis einzudämmen und zu verhindern, dass das vergiftete Wasser die heiligen Haine verfaulen lässt.",al={"hain der uralten wasser","ist hain der uralten verdorben"}}},fx={["842d63ec"]={q="Was ist der Wildbend?",a="Der Wildbend ist ein verseuchter Wasserweg, der sich durch den südlichen Teil von Dunkelküste schlängelt, in der Nähe von Grove of the Ancients. Er entspringt hoch in den verseuchten Hochländern von Teufelswald und stürzt als Fortsetzung vom Blutgiftbach die Berge hinab, bevor er seinen Weg zum Meer bahnt.",al={"was ist der wildbend","der wildbend","über den wildbend"}},["96fc4b9b"]={q="Ist der Wildbend gefährlich?",a="Ja, sein Wasser ist zutiefst faulig und tückisch. Da der Fluss die flussabwärts gelegene Fortsetzung vom Blutgiftbach in Teufelswald ist, kaskadiert dämonische Verderbnis direkt aus den verseuchten Hochländern in die Dunkelküste, verschmutzt die umliegende Landschaft und bedroht die heiligen Haine in der Nähe.",al={"ist der wildbend gefährlich","gefahren des wildbend","ist der wildbend sicher"}}},fp="14,267,23.531.0,36.253.0,26.186.0,48.248.0"}
P.entries["subzone:wildmane-water-well"] = {n="Brunnen der Wildmähnen",s="Der Brunnen der Wildmähnen ist der nördlichste der heiligen Wasserbrunnen, die über ganz Mulgore verstreut liegen, und befindet sich direkt nördlich der Mesas von Donnerfels. Von lebenswichtiger Bedeutung für die Ebenen und ihre Herden, ist er zu einem umkämpften Brennpunkt geworden, der ins Visier von Goblin-Opportunisten geraten ist, die den Tauren die Lebensader abschnüren wollen.",h="Der Brunnen der Wildmähnen ist der nördlichste der heiligen Wasserbrunnen, die über ganz Mulgore verstreut...",kw={"mulgore","heiliger brunnen","donnerfels","venture company","wasserbrunnen","wildmane"},ang={["class:Druid"]="Die Versuche der Goblins, das frische Wasser von Mulgore zu verderben, bedrohen das empfindliche Gleichgewicht der Ebenen und erfordern druidische Wachsamkeit, um das Land zu reinigen und zu heilen.",["race:Tauren"]="Die heiligen Brunnen von Mulgore sind ein Geschenk der Erdenmutter. Den Brunnen von Wildmane vor Entweihung und Gift zu schützen, ist eine heilige Pflicht für jeden jungen Krieger."},sec={{t="Eine belagerte Lebensader",b="Seit Generationen verlassen sich die nomadischen Tauren auf heilige Wasserbrunnen, die in den goldenen Ebenen von Mulgore gegraben wurden, um ihr Volk und ihre umherziehenden Kodoherden zu versorgen. Der Brunnen von Wildmane behütet die nördlichen Weiten gleich hinter dem Schatten von Donnerfels. Seine entscheidende Bedeutung macht ihn zu einem unwiderstehlichen Ziel für Feinde der Stämme. Die Goblins der Venture Company haben ihn mit ihren Giften verunreinigt, um die regionale Wasserversorgung unter ihre Kontrolle zu bringen, und nur ein Reinigungsritual mit einem von den Tauren gefertigten Totem kann sein Wasser wieder reinigen."}},faq={{q="Wo befindet sich der Brunnen der Wildmähnen?",a="Der Brunnen der Wildmähnen liegt in den Ebenen von Mulgore, direkt nördlich der hoch aufragenden Mesas von Donnerfels. Er ist der nördlichste der heiligen Brunnen, die die Region versorgen.",al={"wasserbrunnen von wildmane standort","wo ist der wasserbrunnen von wildmane","wasserbrunnen von wildmane karte"}},{q="Warum ist der Brunnen für die Tauren wichtig?",a="Frisches Wasser bedeutet Leben in den Ebenen. Die Tauren betrachten die Brunnen des Landes als heilig, da sie lebenswichtige Adern für ihre Siedlungen, reisenden Jäger und die großen Kodoherden sind, die die Ebenen von Mulgore durchstreifen.",al={"warum ist den tauren der brunnen wichtig","wasserbrunnen von wildmane heilig"}},{q="Wer hat versucht, den Brunnen zu sabotieren oder zu kontrollieren?",a="Die Goblins der Venture Company haben den Brunnen vergiftet, um die Wasserversorgung von Mulgore unter ihre Kontrolle zu bringen, und die Tauren müssen ihn mit einem heiligen Totem reinigen.",al={"wer griff den brunnen an","wasserbrunnen von wildmane feinde","wer vergiftete den brunnen von wildmane"}}},fx={["6d5f57b0"]={q="Was ist der Brunnen der Wildmähnen?",a="Der Brunnen der Wildmähnen ist der nördlichste der heiligen Wasserbrunnen, die die Tauren von Mulgore versorgen, und befindet sich direkt nördlich der Klippen unterhalb von Donnerfels. Er liefert sauberes, lebenswichtiges Wasser für die Ebenen und Herden, was ihn zu einer unverzichtbaren Lebensader und einem heiligen Ort für die Stämme macht, die in diesen angestammten Ländern ihre Heimat gefunden haben.",al={"was ist der brunnen der wildmähnen","infos zum brunnen der wildmähnen","brunnen der wildmähnen mulgore"}},["92d8374e"]={q="Was ist am Brunnen der Wildmähnen geschehen?",a="Der Brunnen wurde von den Goblins der Venture Company beschlagnahmt, die sein Wasser mit ihren Giften verseuchten, um die Wasserversorgung von Mulgore zu kontrollieren. Die Tauren haben sie vertrieben und müssen den Brunnen nun mit einem heiligen Totem reinigen, damit wieder sauberes Wasser fließen kann.",al={"geschichte vom brunnen der wildmähnen","was ist am brunnen der wildmähnen geschehen"}},d4e90335={q="Ist der Brunnen der Wildmähnen gefährlich?",a="Ja. Während der Brunnen selbst ein friedlicher Ort der Tauren ist, wurde sein Wasser durch die Gifte der Venture Company verseucht, und Präriewölfe sowie andere Raubtiere durchstreifen die Ebenen in seiner Umgebung. Jeder, der sich nähert, sollte wachsam bleiben und es vermeiden, das verseuchte Wasser zu trinken, bis der Brunnen gereinigt ist.",al={"ist der brunnen der wildmähnen gefährlich","gefahr am brunnen der wildmähnen","bedrohungen am brunnen der wildmähnen"}}},fp="19,292,23.543.0,41.184.0,40.191.0,46.157.0"}
P.entries["subzone:windbreak-canyon"] = {n="Schlucht der heulenden Winde",s="Die Schlucht der heulenden Winde ist eine gewundene Schlucht an der Nordseite von Tausend Nadeln, gelegen zwischen dem Freiwindposten und der Schimmernden Ebene. Berühmt für ihre rauen Luftzüge und den zerklüfteten Fels, ist sie stark von nistenden Windnattern befallen. Reisende, die die Hauptstraße passieren, müssen in der Nähe ihres Eingangs vorsichtig sein, um nicht von oben gejagt zu werden.",h="Die Schlucht der heulenden Winde ist eine gewundene Schlucht an der Nordseite von Tausend Nadeln, gelegen...",kw={"freiwindposten","tausend nadeln","der wetterwinkel","windnattern","schlucht der heulenden winde"},ang={["class:Hunter"]="Die in der gesamten Schlucht nistenden Windnattern bieten Wildnisjägern eine ideale Gelegenheit, agile, blitzspuckende Bestien zu studieren und zu zähmen."},sec={{t="Ein Natternest in den Nadeln",b="In die steilen Nordwände des Schluchtbodens gehauen, erstreckt sich die Schlucht der heulenden Winde über ein großes Gebiet östlich des Freiwindpostens. Anstatt Schutz zu bieten, leitet die Schlucht pfeifende Winde zwischen den Felsnadeln hindurch und schafft ideale Sitzplätze für wilde Windnattern. Die Raubtiere legen ihre Gelege entlang der Felsvorsprünge ab und schlagen auf unvorsichtige Reisende herab, die von der Hauptstraße abkommen. Diejenigen, die sich in das Innere der Schlucht wagen, finden zudem die gewundenen Pfade, die hinauf zum Wetterwinkel führen."}},faq={{q="Wo liegt die Schlucht der heulenden Winde?",a="Die Schlucht der heulenden Winde liegt an der Nordseite von Tausend Nadeln, etwa zwischen dem Freiwindposten und dem östlichen Zugang zur Schimmernden Ebene.",al={"schlucht der heulenden winde ort","wo liegt die schlucht der heulenden winde","karte der schlucht der heulenden winde"}},{q="Welche Kreaturen leben in der Schlucht der heulenden Winde?",a="Die Schlucht wird von aggressiven wilden Windnattern beherrscht, die in den Felsen nisten und ihre Gelege vor Eindringlingen verteidigen.",al={"monster in der schlucht der heulenden winde","was gibt es in der schlucht der heulenden winde","mobs in der schlucht der heulenden winde"}},{q="Wohin führt der Pfad in der Schlucht?",a="Folgt man den ansteigenden Pfaden im Inneren der Schlucht, gelangt man zum Wetterwinkel, der in den Klippen darüber liegt.",al={"pfad der schlucht der heulenden winde","weg in der schlucht der heulenden winde","wohin führt die schlucht der heulenden winde"}}},fx={["4bddac98"]={q="Ist die Schlucht der heulenden Winde gefährlich?",a="Ja. Die Schlucht wimmelt von wilden Windschlangen, die ihre Nester entlang des felsigen Bodens und der Schluchtwände bewachen. Jeder, der die Schlucht in Richtung des Der Wetterwinkel durchquert, muss wachsam bleiben, da diese territorialen Bestien schnell zuschlagen, sobald Eindringlinge ihrer Brut zu nahe kommen.",al={"ist die schlucht der heulenden winde gefährlich","gefahren der schlucht der heulenden winde","bedrohungen schlucht der heulenden winde"}},["7c7f9a22"]={q="Was ist die Schlucht der heulenden Winde?",a="Die Schlucht der heulenden Winde ist eine weitläufige, raue Schlucht in Tausend Nadeln. Sie erstreckt sich über einen Großteil der nördlichen Ausdehnung zwischen Freiwindposten und Die schimmernde Ebene und ist vor allem für ihre dichte Population nistender Windschlangen und den gewundenen Pfad bekannt, der zum Der Wetterwinkel führt.",al={"was ist die schlucht der heulenden winde","übersicht zur schlucht der heulenden winde","erzähl mir von der schlucht der heulenden winde"}}},fp="16,342,29.499.0,26.143.0,40.124.0,44.116.0"}
P.entries["subzone:windfury-ridge"] = {n="Windfurienkamm",s="Der Windfurienkamm ist ein schroffes Hochlandgebiet, das die Weiden von Mulgore säumt. Er ist berüchtigt dafür, boshafte Harpyien neben räuberischen Wölfen und Berglöwen zu beherbergen, und stellt eine ständige Gefahr für Reisende dar, während er Tauren-Handwerkern geschätzte Federn bietet.",h="Der Windfurienkamm ist ein schroffes Hochlandgebiet, das die Weiden von Mulgore säumt.",kw={"berglöwen","federn","harpyien","mulgore","donnerfels","windfurien","windfurienkamm"},ang={["class:Hunter"]="Die steilen Hänge und gerissenen Raubtiere bieten ein hervorragendes frühes Übungsgelände für das Fährtenlesen, das Zähmen von Tieren und den Fernkampf.",["race:Tauren"]="Der Kamm ist sowohl ein wiederkehrendes Ärgernis für junge Jäger als auch eine Quelle lebenswichtiger zeremonieller Ornamente, die zur Ehrung von Hochzeiten und jahreszeitlichen Zusammenkünften verwendet werden."},sec={{t="Ein gefährlicher Hochsitz",b="Der Windfurienkamm erhebt sich steil über die ruhigen Ebenen von Mulgore und dient den Windfurienharpyien als Jagdrevier. Diese bösartigen geflügelten Kreaturen nisten hoch an den Klippen und stürzen sich bereitwillig auf jeden unvorsichtigen Wanderer, der die Hügel streift. Das felsige Gelände wird zudem von umherstreifenden Präriewölfen und wilden Berglöwen bevölkert, was den Kamm zu einer der tückischeren Grenzen des Kernlandes der Tauren macht. Trotz der Gefahr werden die Harpyien häufig von tapferen Tauren-Kriegern gejagt; ihr leuchtendes, schillerndes Gefieder ist in ganz Donnerfels heiß begehrt, um zeremonielle Gewänder für üppige Feste und Hochzeitsfeiern zu schmücken."}},faq={{q="Was macht den Windfurienkamm gefährlich?",a="Auf dem Kamm wimmelt es von räuberischen Berglöwen und Präriewölfen, doch seine beständigste Bedrohung ist die Schar aggressiver Harpyien, die an den Höhen nistet. Sie stürzen sich aktiv von den Klippen herab, um Eindringlinge zu fangen oder abzuschlachten, die sich ihren Nistplätzen zu sehr nähern.",al={"warum ist der windfurienkamm gefährlich","gefahren des windfurienkamms","windfurienkamm monster"}},{q="Warum jagen die Tauren die Harpyien auf dem Windfurienkamm?",a="Neben der Sicherung der Grenzen vor ihren Übergriffen jagen die Tauren die Windfurienharpyien wegen ihrer prächtigen Federn. Diese farbenfrohen Schmuckfedern werden traditionell gesammelt und in zeremonielle Kopfbedeckungen und Verzierungen eingewoben, die bei Festen und Hochzeiten verwendet werden.",al={"warum windfurienharpyien töten","harpyienfedern mulgore","harpyien jagen"}},{q="Wo befindet sich der Windfurienkamm?",a="Der Windfurienkamm liegt entlang der erhöhten Klippen in der ländlichen Region von Mulgore, weit im Norden von Mulgore, jenseits von Donnerfels.",al={"windfurienkamm standort","wo ist der windfurienkamm","windfurienkamm karte"}}},fx={d25e422a={q="Was ist der Windfurienkamm?",a="Der Windfurienkamm ist ein zerklüftetes Hochland, das in den Hügeln von Mulgore liegt. Er ist vor allem als Nistplatz wilder Harpyien bekannt und ist ein gefährlicher, hochgelegener Landstrich, der von tödlichen Raubtieren heimgesucht und von vorsichtigen Reisenden gemieden wird.",al={"was ist der windfurienkamm","infos zum windfurienkamm","über den windfurienkamm"}},["52a38b39"]={q="Wer lebt im Windfurienkamm?",a="Der Kamm wird von den Windfurien-Harpyien beansprucht und erbittert verteidigt, die ihre Nester zwischen den Felsen bauen. Abgesehen von diesen geflügelten Aasfressern lauern Pumas und wilde Wölfe an den Hängen und jagen alles, was sich den Hügeln zu nahe wagt.",al={"wer lebt am windfurienkamm","bewohner des windfurienkamms","kreaturen am windfurienkamm"}}},fp="14,245,16.644.0,36.267.0,53.250.0,32.131.0"}
P.entries["subzone:windshear-crag"] = {n="Die Scherwindklippe",s="Die Scherwindklippe ist ein schwer geplündertes Tal im zentralen Steinkrallengebirge, dessen uralter Baumbestand von der Venture Company abgeholzt wurde. Einst ein üppiger Wald, ist die Region nun ein industrielles Ödland, das von surrenden Holzfällern, trüben Abwässern und aggressiven Holzfällertrupps beherrscht wird. Im Schatten der Maschinen schürfen einheimische Kobolde nach Erz, während Gebirgspässe die vernarbte Landschaft mit Eschental verbinden.",h="Die Scherwindklippe ist ein schwer geplündertes Tal im zentralen Steinkrallengebirge, dessen uralter...",kw={"braug dimspirit","felskesselsee","gerenzo pfeifzang","superschnitter 6000","der steinkrallenpfad","venture company","die scherwindklippe","scherwindmine","ziz fizziks"},ang={["faction:Horde"]="Horde-Reisende auf dem Weg nach Eschental begegnen Braug Dimspirit nahe dem Steinkrallenpfad, wo er ihr Wissen über die Geschichte von Kalimdor prüft.",["profession:Engineering"]="Die Industrieanlagen auf der Klippe zeugen von rücksichtslosen Goblin-Handelsgeheimnissen und Gerenzo Pfeifzangs tödlichen Superschnitter-Entwürfen."},sec={{t="Industrielle Verwüstung",b="Vor nicht allzu langer Zeit war die Scherwindklippe ein dichter Urwald an den Hängen des Steinkrallengebirges. Diese friedliche Wildnis verschwand, als die Venture Company auf der Suche nach Profit eintraf. Heute ist das Becken voller abgeholzter Baumstümpfe, beißendem Smog und klappernden Maschinen. Das gesamte Holzfällerunternehmen wird von Gerenzo Pfeifzang beaufsichtigt, einem Lepragnom, dessen Ingenieurskunst den Superschnitter 6000 hervorbrachte – ein mechanisches Monstrum, das riesige Stämme in Sekundenschnelle zu Kleinholz verarbeiten kann. Von einer erhöhten Plattform über dem verschmutzten Felskesselsee leitet Gerenzo eine ungebremste Operation, die den Berg kahl schlägt und ihm die Feindschaft rivalisierender Ingenieure wie auch einheimischer Bewohner einbringt."},{t="Minen und Gebirgspässe",b="Jenseits der aktiven Holzplätze birgt die Scherwindklippe weitere Gefahren und Wegkreuzungen. Im Südosten liegt die Scherwindmine, in der territoriale Kobolde das Gestein nach Rauchigen Eisenbarren durchgraben und jeden erbittert angreifen, der sich ihrer Beute nähert. In den nordöstlichen Ausläufern der Klippe finden Reisende den Steinkrallenpfad, einen unterirdischen Höhlentunnel, der direkt unter den Kämmen hindurch nach Eschental führt. Nahe diesem schattigen Portal steht der Tauren-Älteste Braug Dimspirit, der das historische Wissen und die Entschlossenheit von Horde-Reisenden auf die Probe stellt, die die umkämpften Gipfel durchqueren."}},faq={{q="Wer leitet hier die Holzfälleroperation?",a="Das Holzfällerunternehmen wird vor Ort von Gerenzo Pfeifzang befehligt, einem brillanten, aber verseuchten Lepragnom-Ingenieur. Unter Vertrag bei der Venture Company wacht er von einer Holzplattform aus über die Klippe, die direkt über dem Felskesselsee errichtet wurde.",al={"wer leitet die venture company hier","wer ist der boss der scherwindklippe","gerenzo pfeifzang geschichte"}},{q="Was ist der Superschnitter 6000?",a="Der Superschnitter 6000 ist ein fortschrittlicher mechanischer Holzfäller-Prototyp, der von Gerenzo Pfeifzang konstruiert wurde. Entwickelt, um Holz mit beispielloser Geschwindigkeit zu fällen, kann er uralte Gebirgsbäume in Sekundenschnelle zu Sägemehl zermahlen und so den Kahlschlag des Unternehmens beschleunigen.",al={"superschnitter 6000","was ist der große schnitter","superschnitter der venture company"}},{q="Warum hat die Tüftlerunion von Lorenhall es auf Gerenzo abgesehen?",a="Direktor Riddlevox von der Tüftlerunion in Lorenhall will Gerenzo tot sehen, und der Goblin Ziz Fizziks, der bereits beim Diebstahl der Superschnitter-6000-Blaupause half, erteilt den Auftrag. Die Handelsprinzen von Lorenhall missbilligen es, dass die Venture Company mit dem Gnom verkehrt.",al={"warum gerenzo töten","motive von ziz fizziks","fehde der tüftlerunion"}},{q="Wohin führt die Höhle im Nordosten?",a="Die Höhle in der Nordostecke ist der Steinkrallenpfad. Er durchschneidet die unterirdischen Wurzeln der Berge und bietet einen Fußweg zwischen der Scherwindklippe und den dichten Wäldern von Eschental.",al={"ziel des steinkrallenpfads","ausgang der scherwindhöhle","tunnel in der scherwindklippe"}},{q="Wer sind die Kobolde, die im Südosten graben?",a="Die Scherwindkobolde haben die hiesige Mine in der südöstlichen Ecke der Klippe überrannt. Sie verteidigen ihren unterirdischen Anspruch energisch und bauen Vorkommen Rauchiger Eisenbarren ab, die von Schmieden der Region genutzt werden.",al={"scherwindmine kobolde","warum sind kobolde hier","rauchige eisenbarren"}}},fx={c9b71aef={q="Was ist die Scherwindklippe?",a="Die Scherwindklippe ist ein tiefes Tal im Steinkrallengebirge, das einst für seinen hoch aufragenden, uralten Wald berühmt war. Heute hat rücksichtslose Abholzung das grüne Waldland in eine vernarbte Landschaft aus gezackten Baumstümpfen, aufgewühltem Schlamm und giftigen Abwässern verwandelt.",al={"was ist das für ein ort","scherwindklippe lore","scherwindklippe steinkrallengebirge"}},f4630a37={q="Was ist mit der Scherwindklippe passiert?",a="In den Jahren nach dem Dritter Krieg drang die Venture Company mit schwerem Industriegerät in das Tal ein. Unter der Führung des aussätzigen Gnom Gerenzo Wrenchwhistle haben ihre destruktiven Abholzungsarbeiten und riesigen Schredder das Altholz praktisch ausgelöscht, die lokalen Gewässer verseucht und die Klippe für Holz und Profit kahlgeschlagen.",al={"geschichte der scherwindklippe","warum ist die scherwindklippe abgeholzt","was ist hier passiert"}},bab211f4={q="Ist die Scherwindklippe gefährlich?",a="Sehr gefährlich. Die Venture Company beschäftigt aggressive Holzfäller, Mechaniker und erbarmungslose Schredder, die jeden angreifen, der in ihr Gebiet eindringt. Im Südosten verteidigen feindselige Kobolde die Scherwindmine, was das gesamte Becken zu einem gefährlichen Ort für wandernde Reisende macht.",al={"ist die scherwindklippe sicher","bedrohungen in der scherwindklippe","gefahren der scherwindklippe"}}},fp="14,403,22.687.0,25.571.0,42.252.0,30.259.0,54.272.0,42.194.0,45.204.0"}
P.entries["subzone:winterfall-village"] = {n="Lager der Winterfelle",s="Das Lager der Winterfelle ist ein weitläufiges Furbolglager, eingebettet in die Schneewehen des östlichen Winterquell, direkt östlich von Ewige Warte. Einst friedliche Verwandte der anderen Bärenstämme Kalimdors, sind die hier lebenden Furbolgs der Winterfelle unter der Herrschaft von High Chief Winterfall dem Wahnsinn und einer gewalttätigen Verderbnis anheimgefallen.",h="Das Lager der Winterfelle ist ein weitläufiges Furbolglager, eingebettet in die Schneewehen des östlichen...",kw={"ewige warte","furbolg","high chief winterfall","winterfelle","lager der winterfelle","winterquell"},ang={["class:Druid"]="Die tiefe Verderbnis des Stammes der Winterfelle mitanzusehen, ist eine bittere Tragödie, da die Furbolgs uralte Verbündete der Nachtelfen und des Zirkels des Cenarius waren, bevor der dämonische Wahnsinn sie ergriff.",["race:NightElf"]="Der Fall des Stammes der Winterfelle markiert einen weiteren schmerzhaften Bruch in den uralten Banden zwischen den Nachtelfen und den Völkern Kalimdors."},sec={{t="Ein verzehrter Stamm",b="Ausgebreitet über die terrassierten Schneewehen östlich des Goblin-Handelspostens Ewige Warte dient das Lager der Winterfelle als wichtigste Bastion der Furbolgs der Winterfelle in Winterquell. Wie ihre über das nördliche Kalimdor verstreuten Vettern wurden auch diese Bärenmenschen durch die anhaltende Fäulnis der Invasion der Brennenden Legion verzerrt und in den Wahnsinn getrieben. Angeführt von High Chief Winterfall aus einer abgelegenen Höhle auf der höchsten Ebene der Siedlung, hat der Stamm seine überlieferten Bräuche aufgegeben. Anstatt friedlich mit den wilden Geistern des Schnees zu kommunizieren, greifen die erbosten Furbolgs nun Reisende aggressiv an, durchkämmen die Gebirgspässe und bedrohen jeden, der sich ihrer frostigen Heimat nähert."}},faq={{q="Was ist das Lager der Winterfelle?",a="Es ist die zentrale Siedlung der Furbolgs der Winterfelle, gelegen an den verschneiten Hängen direkt östlich des Goblin-Außenpostens Ewige Warte in Winterquell.",al={"lager der winterfelle info","was ist dieser ort","furbolg stadt winterquell"}},{q="Warum sind die Furbolgs hier feindselig?",a="Die Furbolgs der Winterfelle erlagen nach dem Dritten Krieg der Verderbnis. Das von der Brennenden Legion hinterlassene dämonische Verderben verzerrte ihren Geist, beraubte sie ihrer friedlichen Bräuche und machte sie allen Außenstehenden gegenüber gewaltsam feindselig.",al={"warum furbolgs wahnsinnig","verderbte furbolgs","warum angreifen"}},{q="Wer führt das Dorf an?",a="Der Stamm wird von High Chief Winterfall beherrscht, der von einer kleinen Höhle ganz oben auf dem Gipfel der Siedlung aus über seine Anhänger wacht.",al={"wer ist der boss","anführer der winterfelle","häuptling"}},{q="Warum kümmert sich Ewige Warte um dieses Dorf?",a="Das Dorf liegt unangenehm nah an Ewige Warte. Die wahnsinnigen Furbolgs überfallen ständig vorbeiziehende Karawanen, stören die lokalen Handelswege und bedrohen die Bergbau- und Handelsinteressen der Goblins im gesamten östlichen Winterquell.",al={"ewige warte goblins","warum winterfelle bekämpfen"}}},fp="18,312,16.671.0,27.142.0,34.235.0,22.141.0,42.222.0"}
P.entries["subzone:winterhoof-water-well"] = {n="Brunnen der Winterhufe",s="Der Brunnen der Winterhufe ist eine lebenswichtige Frischwasserquelle am Rande der Wogenden Ebenen im südlichen Mulgore. Der Brunnen, der für die einheimische Tierwelt und die nomadischen Taurenstämme von entscheidender Bedeutung ist, wurde vor Kurzem von der ausbeuterischen Venture Company bedroht, die versucht, die Wasserversorgung der Region zu vergiften und unter ihre Kontrolle zu bringen.",h="Der Brunnen der Winterhufe ist eine lebenswichtige Frischwasserquelle am Rande der Wogenden Ebenen im...",kw={"reinigung","mulgore","mull donnerhorn","die wogenden ebenen","totem","venture company","wasserbrunnen","winterhoof"},ang={["class:Shaman"]="Die Reinigung des Brunnens erfordert elementare Harmonie und dient als praktische Demonstration des Einsatzes von Totems zur Heilung verwundeter Wassergeister.",["race:Tauren"]="Die Verteidigung und Reinigung der uralten Wasserbrunnen ist eine der ersten Prüfungen, denen sich junge Krieger stellen müssen, um das Land vor äußerer Ausbeutung zu schützen."},sec={{t="Eine bedrohte Lebensader",b="In den trockenen Weiten von Zentralkalimdor bedeutet Wasser Leben, und Mulgores unterirdische Brunnen versorgen sowohl die Herden der Ebenen als auch die Lager der Tauren. Der Brunnen der Winterhufe, benannt nach einem der angesehenen Stämme der Ebenen, zapft die tiefen Grundwasserleiter unter den Wogenden Ebenen an. Unglücklicherweise hat seine strategische Bedeutung die Habgier der Venture Company geweckt. Anstatt das Land gemeinsam zu nutzen oder zu verhandeln, hat das rücksichtslose Goblinsyndikat versucht, die Wasserversorgung zu vergiften, um Druck auf das umliegende Territorium auszuüben."},{t="Reinigung und Verteidigung",b="Um der industriellen Sabotage der Venture Company entgegenzuwirken, haben die Ältesten und Schamanen der Tauren junge Krieger in ganz Mulgore mobilisiert. Mull Donnerhorn hat heilige Totems gefertigt, die den industriellen Giftstoffen entgegenwirken und das spirituelle wie physische Gleichgewicht des Brunnens wiederherstellen sollen. Den Brunnen zu reinigen, ist für die Tauren nicht bloß ein Akt des Überlebens, sondern eine spirituelle Pflicht, um sicherzustellen, dass die Erde und ihre Gewässer von fremder Gier unberührt bleiben."}},faq={{q="Wo befindet sich der Brunnen der Winterhufe?",a="Der Brunnen befindet sich im südlichen Mulgore, direkt am Rand der Wogenden Ebenen südlich des Dorfes der Bluthufe.",al={"wasserbrunnen von winterhoof standort","wo ist der winterhoof-brunnen","wasserbrunnen von winterhoof finden"}},{q="Wer hat den Brunnen der Winterhufe vergiftet?",a="Die Venture Company hat den Brunnen vergiftet. Die skrupellose Handelsorganisation der Goblins versuchte, die Wasserversorgung zu verseuchen, um die Kontrolle über die lokalen Ressourcen zu erlangen und die einheimischen Tauren zu schwächen.",al={"wer hat den winterhoof-brunnen vergiftet","warum ist der brunnen vergiftet","wer hat das wasser ruiniert"}},{q="Wie kann der vergiftete Brunnen gereinigt werden?",a="Der Brunnen wird durch ein Ritual mit einem verzauberten Totem gereinigt, das von Mull Donnerhorn gefertigt wurde und Ur-Magie nutzt, um die fauligen Gifte der Venture Company aus dem Wasser zu entfernen.",al={"winterhoof-brunnen reinigen","den brunnen reparieren","winterhufsäuberung"}},{q="Warum sind Wasserbrunnen für die Tauren so heilig?",a="Wasserquellen in Mulgore dienen nicht nur der notwendigen Versorgung der Stämme und umherziehenden Herden, sondern werden als Gaben der Erdenmutter betrachtet. Ihre Verunreinigung gilt sowohl als direkte physische Bedrohung als auch als schwerer spiritueller Frevel.",al={"warum sind brunnen den tauren wichtig","lore zu den taurenbrunnen"}}},fx={["8e6c4fef"]={q="Was ist der Brunnen der Winterhufe?",a="Der Brunnen der Winterhufe ist eine von mehreren lebenswichtigen Süßwasserquellen, die in die Erde von Mulgore gegraben wurden und am Rande der südlichen Die wogenden Ebenen liegen. Für die nomadischen Tauren und die lokale Tierwelt spenden diese Brunnen das Leben im ariden Grasland. Doch seine stille Präsenz hat kürzlich die unerwünschte Aufmerksamkeit skrupelloser Ausbeuter auf sich gezogen, die die natürlichen Ressourcen des Landes zu Geld machen wollen.",al={"wasserbrunnen von winterhoof übersicht","was ist der wasserbrunnen von winterhoof","über den wasserbrunnen von winterhoof"}},a848edd2={q="Was ist am Brunnen der Winterhufe passiert?",a="Gierige Agenten der Venture Company besetzten den Brunnen in einem hinterhältigen Versuch, die Kontrolle über die lokale Wasserversorgung zu erlangen. Dabei verschmutzten und vergifteten sie die Tiefen, was die Gesundheit der Ebenen und der Herden, die von ihm abhängen, bedroht. Taurenälteste und Schamanen haben seitdem tapfere Wanderer dazu aufgerufen, die Schänder zu vertreiben und die natürliche Reinheit des Wassers mit geweihten Totems wiederherzustellen.",al={"geschichte des wasserbrunnens von winterhoof","was ist am wasserbrunnen von winterhoof passiert","ereignisse am wasserbrunnen von winterhoof"}},["897a0f7c"]={q="Ist der Brunnen der Winterhufe gefährlich?",a="Ja. Jenseits der giftigen Verunreinigung, die in das Grundwasser sickert, ist der Brunnenstandort von bewaffneten Söldnern der Venture Company überrannt. Diese rücksichtslosen Eindringlinge verteidigen ihren Anteil an dem Land erbittert und werden jeden Tauren oder Reisenden der Horde gewaltsam angreifen, der sich nähert, um den Ort zu untersuchen oder zu reinigen.",al={"gefahren am wasserbrunnen von winterhoof","ist der wasserbrunnen von winterhoof sicher","bedrohungen am wasserbrunnen von winterhoof"}}},fp="21,315,21.547.0,24.439.1,43.111.0,39.188.0,38.178.0,44.226.0"}
P.entries["subzone:witch-hill"] = {n="Hexenhügel",s="Der Hexenhügel ist eine trostlose, nebelverhangene Anhöhe im Herzen der Düstermarschen entlang des Pfades nach Theramore. Er ist vor allem für das abgelegene Swamplight-Anwesen, verstreute Lager feindseliger Mirefin-Murlocs und finstere Gerüchte über dunkle Spukgestalten bekannt.",h="Der Hexenhügel ist eine trostlose, nebelverhangene Anhöhe im Herzen der Düstermarschen entlang des Pfades...",kw={"düstermarschen","mirefin","sumpfauge jarl","swamplight-anwesen","hexenhügel"},ang={["class:Warlock"]="Hexenmeister, die auf der Straße nach Theramore reisen, spüren womöglich die dunklen Gerüchte über Spukerscheinungen, die der trostlosen Kuppe anhaften.",["faction:Alliance"]="Der Hexenhügel grenzt an den primären Überlandweg zur Insel Theramore, weshalb seine Murlocstämme und dunklen Wesenheiten ein ständiges Ärgernis für Reisende und Kuriere darstellen."},sec={{t="Eine verheerte Anhöhe",b="Aus den stehenden Gewässern der Düstermarschen ragend, liegt der Hexenhügel etwa auf einem Drittel des Weges entlang der Halbinsel, die nach Südosten zur Insel Theramore führt. Der erhöhte Grund bietet jedoch wenig Zuflucht vor den Gefahren des Sumpfes, da aggressive Mirefin-Murlocs die umliegenden Gewässer beanspruchen. In seinem Zentrum steht das Swamplight-Anwesen, die einsame und beunruhigende Residenz des Einsiedlers, der als „Sumpfauge“ Jarl bekannt ist. Reisende, die das Gebiet durchqueren, berichten häufig von unheimlichen Phänomenen und verweilenden dunklen Präsenzen auf der Kuppe."},{t="Der Spuk auf dem Hügel",b="Hinter seinem stillen, düsteren Äußeren ist der Hexenhügel von finsteren Gerüchten umrankt. Geschichten über Spukgestalten haften dem trostlosen Boden an und verstärken das örtliche Misstrauen. Diejenigen, die sich auf den Hügel wagen, müssen sich nicht nur mit der primitiven Wildheit der Mirefin auseinandersetzen, sondern auch mit okkulten Bedrohungen, die selbst erfahrene Patrouillen aus Theramore beunruhigen."}},faq={{q="Wo befindet sich der Hexenhügel?",a="Der Hexenhügel liegt in den Düstermarschen, etwa auf einem Drittel des Weges entlang der Halbinsel, die den westlichen Sumpf mit der Insel Theramore verbindet.",al={"hexenhügel standort","wo liegt der hexenhügel","hexenhügel finden"}},{q="Wer lebt auf dem Hexenhügel?",a="Der prominenteste Bewohner ist „Sumpfauge“ Jarl, ein exzentrischer Einsiedler, der im Swamplight-Anwesen nahe dem Zentrum des Hügels lebt. Die umliegenden Niederungen werden zudem von Lagern der Mirefin-Murlocs heimgesucht.",al={"wer lebt hier","hexenhügel bewohner","swamplight-anwesen bewohner"}},{q="Warum heißt das Gebiet Hexenhügel?",a="Die Kuppe hat seit langem einen unheilvollen Ruf wegen dunkler Magie, seltsamer Lichter und übernatürlicher Gefahren, verstärkt durch die unheimliche Einsamkeit des Swamplight-Anwesens.",al={"warum hexenhügel","gibt es hier eine hexe","hexenhügel geschichte"}},{q="Vor welchen Gefahren sollten sich Reisende auf dem Hexenhügel in Acht nehmen?",a="Reisende müssen sich vor umherstreifenden Mirefin-Murlocs in Acht nehmen, die Lager um den Hügel herum errichten, sowie vor den beunruhigenden Gerüchten über Spukerscheinungen, die dem Hügel anhaften.",al={"hexenhügel gefahren","hexenhügel gegner","kreaturen auf dem hexenhügel"}}},fp="10,243,15.515.0,24.315.1,28.146.0,24.195.0,34.151.1,57.154.0"}
P.entries["subzone:witherbark-village"] = {n="Witherbark",s="Witherbark ist eine Waldtrollsiedlung, die an einem abgelegenen See in den südöstlichen Hügeln des Arathihochlands liegt. Sie wird vom feindseligen Stamm der Witherbark bewohnt und dient als Aufmarschgebiet für trollische Plünderer, die sowohl den verbliebenen Allianzstreitkräften von Stromgarde als auch dem Außenposten der Horde bei Hammerfall trotzen.",h="Witherbark ist eine Waldtrollsiedlung, die an einem abgelegenen See in den südöstlichen Hügeln des...",kw={"arathihochland","waldtrolle","nimar the slayer","witherbark","zalas witherbark"},ang={["faction:Horde"]="Die Witherbark zeigen keinen Respekt vor der neuen Horde; sie geraten regelmäßig mit Spähern aus Hammerfall aneinander und bedrohen den Verkehr durch die östlichen Pässe.",["race:Troll"]="Dunkelspeere werden hier keine Verbundenheit finden; die Waldtrolle der Witherbark begegnen Dschungeltrollen und der Horde mit tief verwurzelter Feindseligkeit."},sec={{t="Feste der Waldtrolle",b="Erbaut an den Ufern eines ruhigen Bergsees, beherbergt Witherbark die wilden Waldtrolle des Witherbarkstammes. Während Fischer, Axtwerfer und Hexendoktoren die von Hütten gesäumte Uferpromenade bevölkern, leiten Stammesführer wie Zalas Witherbark und tödliche Schattenjäger die Operationen aus einer gewaltigen Höhle hinter der Siedlung. Die Witherbark unterhalten ein opportunistisches Bündnis mit den Boulderfist-Ogern von Arathi und arbeiten mit ihnen zusammen, um sich Territorien im gesamten Hochland zu sichern – wobei sie sogar in den Ruinen von Burg Stromgarde festen Fuß gefasst haben. Grimmig territorial veranlagt, greifen sie jeden Außenstehenden an, der sich in ihre Ecke des Beckens wagt."}},faq={{q="Wer lebt in Witherbark?",a="Die Siedlung wird vom Stamm der Witherbark gehalten, einer in der Region einheimischen Fraktion von Waldtrollen. Sie stellen Kopfjäger, Axtwerfer, Fischer und Hexendoktoren, die den See und die umliegenden Pfade verteidigen.",al={"wer sind die witherbark","witherbark trolle","wer kontrolliert witherbark"}},{q="Was befindet sich in der großen Höhle hinter dem Dorf?",a="Die Höhle dient als Sitz der Stammesführung. Häuptling Zalas Witherbark und gefährliche Schattenjäger koordinieren die Raubzüge und die Verteidigung des Stammes tief aus dem Inneren ihrer Tunnel.",al={"witherbark höhle","höhle hinter witherbark","zalas witherbark aufenthaltsort"}},{q="Warum arbeiten die Witherbark-Trolle mit Ogern zusammen?",a="Die Witherbark haben ein loses Zweckbündnis mit den einheimischen Boulderfist-Ogern geschlossen. Die Bündelung ihrer Kräfte erlaubt es ihnen, gegen die geschwächten menschlichen Verteidiger von Stromgarde vorzugehen und regionale Rivalen wie die Horde in Hammerfall zu bedrohen.",al={"witherbark oger bündnis","trolle und boulderfist","warum sind trolle mit ogern verbündet"}},{q="Sind die Witherbark der Horde freundlich gesinnt?",a="Nein. Wie die meisten von den Amani abstammenden Waldtrolle hegen die Witherbark tiefen Groll gegen die moderne Horde und ihre Dunkelspeere, und sie bekämpfen die Horde bei Hammerfall. Sie greifen Reisende der Horde auf Sicht an.",al={"gehören witherbark zur horde","kann horde mit witherbark sprechen","witherbark ruf"}}},fp="18,309,31.664.0,32.208.0,49.179.0,49.248.0,41.217.0"}
P.entries["subzone:woodpaw-hills"] = {n="Waldpfotenhügel",s="Die Waldpfotenhügel sind ein zerklüfteter, bewaldeter Landstrich im Südosten von Feralas, der von den Waldpfotengnollen beansprucht wird. Einst ein vorherrschendes Stammesgebiet, sind die Hügel zu einer umkämpften Front geworden, da sich insektoide Schrecken von unten heraufgraben und uralte Steinriesen durch das Blätterdach streifen.",h="Die Waldpfotenhügel sind ein zerklüfteter, bewaldeter Landstrich im Südosten von Feralas, der von den...",kw={"feralas","gnolle","bergriesen","waldpfoten","waldpfotenbau","waldpfotenhügel","die verwundene tiefe"},ang={["faction:Horde"]="Im Gegensatz zu den neutralen Klippenriesen, die nahe der Westküste weilen, hegen die Bergriesen, die in den Waldpfotenhügeln patrouillieren, eine ausgeprägte Feindseligkeit gegenüber Mitgliedern der Horde, die sich ins Landesinnere wagen."},sec={{t="Eine belagerte Festung",b="Die dichten Wälder der Waldpfotenhügel dienen dem Gnollclan der Waldpfoten als historisches Territorium. Während das Hyänenvolk einst unangefochten über diese Hänge streifte, ist seine Vorherrschaft unter dem Druck mehrerer Fronten zerbröckelt. Südöstlich von ihnen haben alptraumhafte Silithidenschwärmer bei der verwundenen Tiefe die Erde durchbrochen, was die Gnolle zurückdrängt und ihre Häuptlinge dazu zwingt, sich tiefer in den Waldpfotenbau zurückzuziehen. Hinzu kommt die Gefahr durch uralte Bergriesen – Relikte, die während des Dritten Krieges herbeigerufen wurden, um die Brennende Legion abzuwehren –, die nun durch die Wälder der Hänge wandern und alle Reisenden oder Eindringlinge der Horde zerschmettern, die ihren Weg kreuzen."}},faq={{q="Wer lebt in den Waldpfotenhügeln?",a="Die Hügel werden hauptsächlich vom Gnollclan der Waldpfoten bewohnt, der in den gesamten Wäldern Verteidigungslager unterhält. Uralte Bergriesen patrouillieren ebenfalls an den Hängen, während invasive Silithideninsekten von den südöstlichen Grenzen her vordringen.",al={"wer bewohnt die waldpfotenhügel","gegner in den waldpfotenhügeln","gnolle in feralas"}},{q="Warum laufen Bergriesen in diesem Wald umher?",a="Die Bergriesen stiegen ursprünglich von den Gipfeln herab, um den Nachtelfen während des Dritten Krieges beizustehen, als die Brennende Legion in Kalimdor einmarschierte. Obwohl die dämonische Invasion abgewehrt wurde, verweilen diese massigen Wächter weiterhin in den Wäldern und verteidigen die wilden Lande erbittert gegen jedes Eindringen.",al={"riesen in den waldpfotenhügeln","warum gibt es hier riesen","bergriesen geschichte feralas"}},{q="Was bedroht die Gnolle hier?",a="Der Waldpfotenclan wird durch einen plötzlichen Ausbruch insektoider Silithiden vertrieben, die in der verwundenen Tiefe Schwarmbauten anlegen. Die vordringenden Schwärme haben die Gnolle aus mehreren Lagern vertrieben und ihre stärksten Alphatiere dazu gezwungen, ihre Stellung im Waldpfotenbau zu befestigen.",al={"gegen was kämpfen die gnolle","probleme der waldpfoten","insekten greifen gnolle an feralas"}},{q="Wo sind die Anführer des Waldpfotenclans?",a="Aufgrund der vordringenden Silithidenschwärme in den Hügeln hat die Stammesführung die offenen Lager aufgegeben. Die Waldpfotenalphas haben sich in die geschützten unterirdischen Höhlen des Waldpfotenbaus zurückgezogen.",al={"aufenthaltsort der waldpfotenalphas","gnollbosse feralas","waldpfotenanführer finden"}}},fp="13,267,24.645.0,31.233.0,51.279.0,36.267.0,35.199.0"}
P.entries["subzone:workshop-entrance"] = {n="Workshop Entrance",s="Der Workshop Entrance, gemeinhin als Hintertür nach Gnomeregan bekannt, ist ein Zugangsportal direkt hinter dem Train Depot. Er bietet erfahrenen Abenteurern und Ingenieuren eine alternative Route in die Tiefen der verstrahlten Stadt, indem er die Vordertore umgeht und nahe den Engineering Labs herauskommt.",h="Der Workshop Entrance, gemeinhin als Hintertür nach Gnomeregan bekannt, ist ein Zugangsportal direkt hinter...",kw={"hintertür","engineering labs","gnomeregan","loading room","train depot","workshop entrance"},ang={["profession:Engineering"]="Dieser Korridor führt direkt auf die Engineering Labs zu, was ihn zu einer verlockenden Infiltrationsroute für Tüftler macht, die nach bahnbrechenden Bauplänen suchen.",["race:Gnome"]="Jeder geheime Durchgang nach Gnomeregan ist eine potenzielle Einbruchstelle, um verlorene Werkstätten zurückzuerobern und Prototypmaschinen von den Streitkräften von Mekgineer Thermaplugg zu bergen."},sec={{t="Die Hintertür zur Stadt",b="Gegenüber der weitläufigen Werkstattebene direkt hinter dem Train Depot gelegen, bietet der Workshop Entrance einen direkten Zugang in das industrielle Herz von Gnomeregan. Flankiert auf einer Seite vom Durchgang zum Loading Room, führt dieser Pfad geradewegs zu den Engineering Labs und umgeht die befestigten Eingangstore, die Lepragnome und Troggs nahe der Oberfläche umkämpfen. Für Einsatztrupps, die versuchen, die unterirdische Hauptstadt zurückzuerobern, kann die Umgehung der äußeren Verteidigungslinien durch diese Seitentür von entscheidender Bedeutung sein."}},faq={{q="Wo befindet sich der Workshop Entrance?",a="Der Workshop Entrance befindet sich am hinteren Ende der Werkstattebene, hinter dem Train Depot in den äußeren Korridoren von Gnomeregan. Von diesem Standpunkt aus liegt das Portal zum Loading Room zu Eurer Linken.",al={"workshop entrance standort","wo ist die hintertür","gnomeregan hintertür koord"}},{q="Warum wird dieser Bereich Hintertür genannt?",a="Er dient als alternativer Zugang zur inneren Instanz von Gnomeregan, der den Hauptspießrutenlauf am Vordereingang überspringt und Eindringlinge direkt in Richtung der Engineering Labs führt.",al={"warum hintertür","gnomeregan hintertür","hintereingang"}},{q="Wohin führt dieser Durchgang im Inneren der Stadt?",a="Wenn Ihr durch dieses Portal tretet, gelangt Ihr über einen Gang direkt in den Sektor der Engineering Labs tief im Inneren von Gnomeregan.",al={"wohin führt es","weg durch die hintertür","was liegt hinter dem eingang"}}},fx={bbef9a7d={q="Was ist der Workshop Entrance?",a="Der Workshop Entrance ist ein Dienstzugang, der sich auf der anderen Seite der äußeren Werkstatt hinter dem Train Depot befindet. Umgangssprachlich als Hintertür nach Gnomeregan bekannt, ermöglicht dieser befestigte Zugang den direkten Weg in die Engineering Labs und umgeht die zeremoniellen Tore der Oberstadt.",al={"was ist der workshop entrance","workshop entrance gnomeregan","über den workshop entrance"}},["6fa860f5"]={q="Was ist am Workshop Entrance passiert?",a="Während des Falls von Gnomeregan wurden die sekundären Zugangstunnel und Frachtverkehrslinien der Stadt zum Schlachtfeld, als Troggs in den unteren Ebenen ausbrachen. Um zu verhindern, dass sich der Befall und der toxische Niederschlag unkontrolliert in die äußeren Gebirgskorridore ausbreiten, wurden schwere Sicherheitsprotokolle und Schlösser an Durchgangstüren wie dieser versiegelt.",al={"geschichte des workshop entrance","was ist hier passiert","geschichte der hintertür"}},["8f5e07c5"]={q="Warum ist der Workshop Entrance ruiniert und verlassen?",a="Als Hochtüftler Mekkatorque den Abzug von radioaktivem Gas anordnete, um die einfallenden Trogg-Horden zu vertreiben, schlug der Plan katastrophal fehl. Der tödliche Niederschlag hüllte die industrielle Infrastruktur ein, machte die überlebenden Verteidiger krank und verwandelte viele in wilde Aussätzige. Der Eingang ist nun verwaist und mit Trümmern, Maschinen und umherstreifenden Schrecken verstopft.",al={"warum ist er verlassen","warum ist der workshop entrance ruiniert","workshop entrance überrannt"}},e5f19575={q="Ist der Workshop Entrance gefährlich?",a="Er ist extrem gefährlich. Jenseits der Strahlung, die an den unteren Werken haftet, schleichen schurkische Verteidigungsautomaten, wahnsinnige aussätzige Gnome und blutrünstige Troggs durch die Gänge. Wer durch diese Tür tritt, befindet sich direkt in der Nähe der instabilen Engineering Labs der Stadt, wo keine vernünftige Verteidigungstruppe mehr Stellung hält.",al={"ist der workshop entrance sicher","gefahren des workshop entrance","wie gefährlich ist die hintertür"}}},fp="17,299,24.500.0,39.193.0,37.176.0,45.115.0"}
P.entries["subzone:writhing-deep"] = {n="Die verwundene Tiefe",s="Die verwundene Tiefe ist ein gewaltiger, insektenartiger Baukomplex im Südosten von Feralas. Dieser unterirdische Bau wird von den Silithiden der Zukk'ash bewohnt und stellt eine wachsende Gefahr dar, die sowohl die nahegelegene Tierwelt als auch die umliegenden Lager bedroht. Die unerbittliche Ausbreitung dieser unterirdischen Raubtiere hat das regionale Gleichgewicht des üppigen Waldes gestört.",h="Die verwundene Tiefe ist ein gewaltiger, insektenartiger Baukomplex im Südosten von Feralas.",kw={"camp mojache","feralas","bau","qirot","silithid","stinglasher","die verwundene tiefe","zukk'ash"},ang={["faction:Horde"]="Die Ausbreitung der Silithiden aus der verwundenen Tiefe bedroht Camp Mojache direkt, indem sie rasende Gnolle und umherstreifende Insektenspäher geradewegs in Eure Nachschublinien treibt."},sec={{t="Der Schwarm der Zukk'ash",b="Versteckt in den feuchten Tieflanden des südöstlichen Feralas dient die verwundene Tiefe als Hauptkolonie der Zukk'ash-Silithiden. Anders als die typischen Waldtiere des Tals graben diese zirpenden Insekten labyrinthartige Tunnel und bewachen Gelege aus harzigen Eiern aufs Schärfste. Die aggressiven Übergriffe des Baus auf die nahen Territorien haben die wilde Fauna destabilisiert und einheimische Gnollrudel aufgescheucht, was vertriebene und rasende Raubtiere bedrohlich nahe an Pfade der Horde und unberührte Zufluchtsorte treibt."}},faq={{q="Welche Kreaturen bewohnen die verwundene Tiefe?",a="Die Schlucht wird von den Zukk'ash-Silithiden heimgesucht, einer aggressiven Brut riesiger Insekten, die aus Arbeitern, Tunnelgräbern, Stachlern und Wespen besteht und von gefährlichen Brutchampions wie Stinglasher und Qirot angeführt wird.",al={"mobs in der verwundenen tiefe","was lebt in der verwundenen tiefe","silithiden in feralas"}},{q="Warum ist die verwundene Tiefe eine Bedrohung für Camp Mojache?",a="Während der Zukk'ash-Schwarm weiter nach außen vordringt, greift er auf die umliegenden Jagdgründe der Gnolle über. Die aufgescheuchten Gnolle werden direkt nach Norden in Richtung Camp Mojache getrieben, was für den Außenposten der Horde eine eskalierende Sicherheitskrise bedeutet.",al={"camp mojache verwundene tiefe","warum angriff horde","gnolle feralas"}},{q="Wo befindet sich die verwundene Tiefe?",a="Die verwundene Tiefe befindet sich im südöstlichen Teil von Feralas, südlich der Hauptstraße und östlich der aufragenden Waldhügel.",al={"ort der verwundenen tiefe","wo ist die verwundene tiefe","standort bau feralas"}}},fp="13,343,18.510.0,41.199.0,50.221.0,35.131.0"}
P.entries["subzone:wyrmbog"] = {n="Der Drachensumpf",s="Der Drachensumpf ist das gefährliche südliche Gebiet der Düstermarschen und liegt direkt südlich des Drachendüsters. Beherrscht von fauligem Morast und zerklüfteten Felsspitzen dient er dem Schwarzen Drachenschwarm als Aufmarschgebiet und territoriales Bollwerk. Die Höhlen uralter Wyrms, darunter die Brutwurm-Königin Onyxia und der Älteste Emberstrife, sind direkt in die umliegenden Bergkämme geschlagen.",h="Der Drachensumpf ist das gefährliche südliche Gebiet der Düstermarschen und liegt direkt südlich des...",kw={"schwarzer drachenschwarm","das drachendüster","drachen","dustwallow","emberstrife","sumpf","onyxia","der drachensumpf"},ang={["faction:Alliance"]="Für Champions der Allianz, die Jagd auf den Schwarzen Drachenschwarm machen, ist der Drachensumpf das letzte, tückische Aufmarschgebiet vor der Schwelle zu Onyxia.",["faction:Horde"]="Kriegshäuptling Thralls Späher behalten den Drachensumpf wachsam im Auge, wohl wissend, dass die schwarzen Drachen, die so nahe am Brachland und an Theramore nisten, eine Bedrohung für das fragile Gleichgewicht in Kalimdor darstellen."},sec={{t="Das Herz der Brut",b="Der Drachensumpf stellt das am stärksten von schwarzen Drachen verseuchte Territorium im südlichen Kalimdor dar. Wo die offenen Gewässer von Dustwallow verbranntem Morast und emporragenden Knochen weichen, durchstreifen Welpen und ausgewachsene Drachen die faulige Luft. Der Sumpf ist von giftigen Dämpfen und raubtierartigen Bestien erfüllt, die durch die Gegenwart der Drachen wild geworden sind. Reisende, die töricht genug sind, sich in diese Weiten vorzuwagen, finden sich unmittelbar im Schatten von Onyxias Hort und Emberstrifes höhlenartigem Bau wieder."}},faq={{q="Was ist der Drachensumpf?",a="Der Drachensumpf ist die tückische südliche Region der Düstermarschen, südlich des Drachendüsters gelegen. Er ist stark von Mitgliedern des Schwarzen Drachenschwarms verseucht.",al={"der drachensumpf","was ist der drachensumpf","wo liegt der drachensumpf"}},{q="Welche Drachen hausen im Drachensumpf?",a="Der Schwarze Drachenschwarm beherrscht das Gebiet. Zahlreiche schwarze Drachenbruten, Drachen und Welpen patrouillieren durch den Sumpf, während uralte Wyrms wie Emberstrife und die Brutwurm-Königin Onyxia ihre Horte entlang der südlichen Grenze haben.",al={"wer lebt im drachensumpf","drachen im drachensumpf","welche drachen sind hier"}},{q="Wo befindet sich Onyxias Hort im Verhältnis zum Drachensumpf?",a="Der Eingang zu Onyxias Hort liegt eingebettet in den Felsnadeln und Höhlenöffnungen entlang des südlichen Randes des Drachensumpfs.",al={"lage von onyxias hort","wo ist onyxia","eingang zu onyxia"}},{q="Wer ist Emberstrife?",a="Emberstrife ist ein uralter schwarzer Drache, der in einer Höhle in den Felsformationen des Drachensumpfs haust und als mächtiger Wächter im Territorium der Brutwurm-Königin dient.",al={"emberstrife","wer ist emberstrife","emberstrifes bau"}}},fp="7,368,18.455.0,16.160.0,31.218.0,54.122.0,19.174.0"}
P.entries["subzone:xavian"] = {n="Xavian",s="Xavian ist eine uralte verfallene Tempelanlage der Nachtelfen im nordöstlichen Eschental, die nun von den Satyrn überrannt und beansprucht wurde. Als Hauptsitz des Einflusses der Satyrn im Wald ist die Ruine von dämonischer Verderbnis und dunklen Riten gegen das Waldland erfüllt.",h="Xavian ist eine uralte verfallene Tempelanlage der Nachtelfen im nordöstlichen Eschental, die nun von den...",kw={"anilia","eschental","zweig des cenarius","geltharis","raze","satyr","xavian","xavius"},ang={["class:Druid"]="Die Satyrn hier haben den Zweig des Cenarius gestohlen und nutzen Teufelsriten, um das Land zu verderben; Druiden sind dazu aufgerufen, das Artefakt zurückzuholen und die seelischen Wunden des Hains zu heilen.",["race:NightElf"]="Die entweihten Hallen eines uralten Tempels zu erblicken, geschändet von den verdrehten Nachfahren der Hochgeborenen, ist für jeden Nachtelfen ein bitterer Frevel, der nach rascher Vergeltung verlangt."},sec={{t="Ein Sitz des Schattens",b="Verborgen in den nordöstlichen Hügeln von Eschental, westlich von Forest Song und nördlich von Satyrnaar, ragt Xavian als wichtigste Bastion der Satyrmacht in der Region empor. Einst ein heiliger Elfantempel, wurden seine Steinbögen und Terrassen von Anhängern der Brennenden Legion entweiht. Anführer der Satyrn, darunter Prince Raze und Geltharis, befehligen ihre Sippe von diesen Ruinen aus. Sie führen auf dem gesamten Gelände schändliche Rituale durch und nutzen sogar gestohlenes Öl des Kriegshymnenklans, um das heilige Waldland weiter zu verheeren. Das Gebiet verdankt seinen Namen Xavius, dem Ratsherrn der Hochgeborenen, der während des Krieges der Ahnen zum ersten Satyr wurde, nachdem er bei Sargeras in Ungnade gefallen war."},{t="Die gefallene Vorhut",b="Die von Xavian ausgehende Verderbnis blieb nicht unangefochten, doch der Kampf gegen die Satyrn fordert einen bitteren Preis. Schildwachen und Hüter des Waldes haben Ein wachsames Auge auf die Festung, wohl wissend, dass ihre strategische Bosheit nahe Enklaven wie Nachtflucht in den Schatten stellt. Kürzlich versuchten Dryadenverteidigerinnen, die Ruinen zu infiltrieren, um den heiligen Zweig des Cenarius zurückzuholen, erlitten dabei jedoch schwere Verluste. Abenteurer, welche die äußeren Terrassen erstürmen, treffen auf die sterbende Dryade Anilia, die niedergestreckt wurde, als sie die Schänder daran hindern wollte, heilige Relikte für ihre dunklen Beschwörungen zu missbrauchen."}},faq={{q="Warum heißt dieser Ort Xavian?",a="Die Festung ist nach Lord Xavius benannt, dem Höfling von Königin Azshara aus den Reihen der Hochgeborenen, der während des Krieges der Ahnen dazu beitrug, die Brennende Legion nach Azeroth zu führen. Nachdem er Sargeras enttäuscht hatte, wurde Xavius in den allerersten Satyr verwandelt – ein dämonischer Fluch, der sich auf weitere Angehörige seines Volkes übertrug.",al={"ursprung von xavian","nach wem xavian benannt ist","xavius xavian"}},{q="Was tun die Satyrn hier?",a="Die Satyrn nutzen Xavian als ihr primäres Command Center in Eschental. Sie führen dunkle Rituale durch, um dämonische Verderbnis im uralten Wald zu verbreiten, und verwenden dabei geschändete heilige Relikte wie den gestohlenen Zweig des Cenarius sowie von den Kriegshymnenorks entwendetes Maschinenöl.",al={"was tun sie in xavian","xavian satyrrituale"}},{q="Wer ist die sterbende Dryade, die am Boden liegt?",a="Ihr Name ist Anilia. Sie gehörte zu einer Gruppe von Dryaden, die den gestohlenen Zweig des Cenarius von den Satyrn zurückholen wollten. Im Gefecht wurde sie tödlich verwundet und liegt nun in den Ruinen, flehend darum, dass jemand den heiligen Zweig zurückerlangt, bevor er vollends verdorben wird.",al={"verletzte dryade xavian","wer ist anilia","dryade in xavian"}},{q="Wie unterscheidet sich Xavian von Satyrnaar oder Nachtflucht?",a="Während Satyrnaar und Nachtflucht beachtliche Satyrniederlassungen in Eschental darstellen, fungiert Xavian als das politische und rituelle Herz ihrer Streitkräfte im Wald. Ranghohe Satyranführer wie Geltharis und Prince Raze haben ihr Lager hier in den Ruinen aufgeschlagen.",al={"satyrnaar vs xavian","andere satyrlager","warum xavian wichtig ist"}}},fx={a8b6505e={q="Was ist Xavian?",a="Xavian ist ein alter Nachtelfentempelkomplex im nordöstlichen Eschental, der heute von Satyrn überrannt und besetzt ist. Er liegt nördlich von Satyrnaar und westlich von Forest Song und ist der primäre Sitz der politischen und dunklen rituellen Macht der Satyrn im gesamten Wald.",al={"was ist xavian","xavian lore","über xavian"}},cfe8a8e5={q="Was ist in Xavian passiert?",a="Einst ein friedliches Heiligtum der alten Nachtelfen, verfiel Xavian nach dem Krieg der Ahnen in Ruinen und Verderbnis.",al={"geschichte von xavian","was ist in xavian passiert","schlacht in xavian"}},e57f7c80={q="Wer regiert Xavian?",a="Die Festung ist die Heimat einer Kabale bösartiger Satyrn und dient als regionales Machtzentrum. Einflussreiche Anführer wie Prinz Raze und Geltharis residieren hier, beaufsichtigen korrumpierende Riten und lenken die Aktivitäten ihrer abscheulichen Brüder im gesamten Eschental.",al={"wer führt xavian an","wer lebt in xavian","xavian anführer"}},["73205fc1"]={q="Warum liegt Xavian in Ruinen?",a="Wie viele alte Bauwerke in Kalimdor wurde dieser heilige Nachtelfentempel vor zehntausend Jahren während des Großen Bruchs und des Krieges der Ahnen zertrümmert. Anstatt ihn wieder aufzubauen, ließen sich die korrupten Satyrn im zerbrochenen Stein nieder und verwandelten die Überreste in eine Bastion für dunkle Zauberei.",al={"warum ist xavian ruiniert","wer zerstörte xavian","xavian ruinen"}},bc87c8f6={q="Ist Xavian gefährlich?",a="Es ist außerordentlich gefährlich. Xavian wird schwer von aggressiven Satyrkultisten bewacht, die dunkle Rituale mit gestohlenem Öl des Kriegshymnenklans durchführen und Artefakte wie The Branch of Cenarius schänden. Sogar Waldschützer wie Dryaden wurden bei dem Versuch, das Gelände zu stürmen, in Hinterhalte gelockt und tödlich verwundet.",al={"ist xavian gefährlich","bedrohung in xavian","wie gefährlich ist xavian"}}},fp="6,267,16.643.0,19.565.1,31.293.0,31.277.0,43.264.0,51.247.0"}
P.entries["subzone:yojamba-isle"] = {n="Die Insel Yojamba",s="Die Insel Yojamba ist eine Ansammlung kleiner tropischer Inselchen vor der Nordwestküste des Schlingendorntals, nahe den Gewässern, die nach Westfall führen. Sie dient als vorgelagertes Lager für den gelehrten Stamm der Zandalar, der hier Fuß gefasst hat, um die wachsende Krise im Dschungel zu beobachten. Von diesen Gestaden aus suchen die Zandalari nach willigen Champions von Horde und Allianz, um sich den uralten Schrecken zu stellen, die in Zul'Gurub erwachen.",h="Die Insel Yojamba ist eine Ansammlung kleiner tropischer Inselchen vor der Nordwestküste des...",kw={"blutgott","hakkar","schlingendorntal","das finstere riff","insel yojamba","die insel yojamba","zandalar","zandalari","zul'gurub"},ang={["faction:Alliance"]="Abenteurer der Allianz mögen überrascht sein, so nah an Westfall ein friedliches Trolllager vorzufinden, doch angesichts der verheerenden Bedrohung durch den Seelenschinder stellen die Zandalari jegliche Politik hintenan.",["race:Troll"]="Für die Dunkelspeere ist die Begegnung mit den Zandalari ein Zusammentreffen mit den uralten Wurzeln der Trollzivilisation, deren Traditionen, Ansehen und Forderungen tiefe kulturelle Ehrfurcht gebieten."},sec={{t="Die Abgesandten von Zandalar",b="Während die meisten Trolle im Schlingendorntal Fremden gegenüber feindselig gesinnt sind, wahrt der Stamm der Zandalar auf der Insel Yojamba eine angespannte Neutralität. Als uralte Priester und Bewahrer des Wissens der Trollzivilisation haben die Zandalari mit wachsendem Entsetzen beobachtet, wie sich die Gurubashitrolle in Zul'Gurub Hakkar dem Seelenschinder zuwandten. Wohl wissend, welche weltenzerstörende Gefahr von einem vollständig herbeigerufenen Blutgott ausgeht, sind die Zandalari weit aus ihrer angestammten Heimat gereist, um diesen Stützpunkt zu errichten, und rufen jeden fähigen Abenteurer an – ungeachtet der Fraktion –, um bei der Eindämmung der Bedrohung zu helfen."},{t="Bewachte Gewässer",b="Die Insel liegt friedlich an der Küste nordwestlich des finsteren Riffs und der Ruinen, die die Strände des Festlands heimsuchen. Im Norden liegt das gewaltige, verborgene Seetor der Eisernen Bucht, während die umliegenden Untiefen von umherstreifenden Meeresbestien aufgesucht werden. Trotz ihrer heiklen Lage fungiert das Lager der Zandalari als ruhige Zuflucht, in der exotische Rituale, heilige Altäre und uraltes Wissen Trost und Kraft für jene spenden, die sich darauf vorbereiten, tief in die finstersten Ruinen des Dschungels vorzudringen."}},faq={{q="Warum sind die Trolle auf der Insel Yojamba friedlich?",a="Diese Trolle gehören zum Stamm der Zandalar, der verehrten Kaste von Priestern und Historikern des Trollvolkes. Anders als die territorialen Stämme der Bloodscalp oder Schädelspalter im Landesinneren sind die Zandalari auf einer dringenden Mission hier, um Hakkar den Seelenschinder in Zul'Gurub aufzuhalten, und sie erkennen, dass sie die Hilfe außenstehender Champions von Horde und Allianz benötigen, um dies zu erreichen.",al={"friedliche trolle yojamba","warum greifen yojamba trolle nicht an","zandalar friedlich"}},{q="Wo befindet sich die Insel Yojamba?",a="Die Insel Yojamba liegt im äußersten Nordwesten des Meeres vor dem Schlingendorntal. Sie liegt unmittelbar vor der Küste nordwestlich des finsteren Riffs, nahe der Seegrenze, an der das südliche Meer an Westfall grenzt.",al={"insel yojamba ort","weg nach yojamba","wo ist yojamba"}},{q="Was macht der Stamm der Zandalar hier draußen?",a="Sie haben ein Vorhutlager errichtet, um das gefährliche Wiedererstarken von Hakkar dem Seelenschinder in Zul'Gurub zu überwachen. Von der Insel Yojamba aus rekrutieren, versorgen und belohnen ihre Abgesandten mächtige Abenteurer, die bereit sind, die uralte Trollstadt zu betreten und die korrumpierte Priesterschaft zu besiegen, bevor Hakkars volle Macht auf Azeroth entfesselt wird.",al={"ziel der zandalar","was wollen zandalari","warum sind zandalar hier"}}},fp="12,441,26.594.0,14.489.0,44.376.0,30.198.0,42.338.0"}
P.entries["subzone:yorgen-farmstead"] = {n="Yorgens Bauernhof",s="Yorgens Bauernhof ist ein verfallener Hof im südlichen Dämmerwald, der zusammen mit dem Rest der heimgesuchten Region dem Ruin anheimgefallen ist. Einst im Besitz des Bauern Sven Yorgen, wurde das Anwesen von Wegelagerern der Bruderschaft der Defias eingenommen und besetzt.",h="Yorgens Bauernhof ist ein verfallener Hof im südlichen Dämmerwald, der zusammen mit dem Rest der...",kw={"das dunkle ufer","defias","bruderschaft der defias","dämmerwald","bauernhof","sven yorgen","yorgens bauernhof"},ang={["class:Rogue"]="Die verborgenen Assassinen der Defias, die das Gehöft durchstreifen, machen das Gebiet tückisch und verdeutlichen, wie bereitwillig abtrünnige Handlanger verwilderte Wildnisanwesen in getarnte Verstecke verwandeln.",["faction:Alliance"]="Der Verlust von Svens Bauernhof an die Bruderschaft der Defias zeigt, wie tief die Syndikate der Gesetzlosen in den Dämmerwald eingedrungen sind, während die Nachtwache darum kämpft, die Ordnung in Dunkelhain aufrechtzuerhalten."},sec={{t="Ein zerstörter Hof",b="Inmitten der düsteren Wälder des südlichen Dämmerwalds gelegen, war Yorgens Bauernhof einst ein funktionierendes Anwesen im Besitz von Sven Yorgen. Wie viele abgelegene Höfe in der Region konnte auch dieser den vordringenden Gefahren des Landes nicht standhalten. Sven war gezwungen, seine Ländereien aufzugeben, und zog sich nach Norden in ein behelfsmäßiges Lager am Dunklen Ufer zurück. In seiner Abwesenheit nahmen Gesetzlose das verlassene Gelände in Besitz, um fernab der Blicke von Sturmwinds Obrigkeit Fuß zu fassen."},{t="Infiltration der Defias",b="Anstatt leer zu stehen, wurde das Gehöft von der Bruderschaft der Defias zu einem Sammelpunkt umfunktioniert. Maskierte Straßenräuber und heimtückische Halsabschneider lauern zwischen den verfallenden Zäunen und verwitterten Nebengebäuden und nutzen das dichte Blätterdach, um ihre Anwesenheit zu verschleiern. Reisende, die sich dem Gehöft nähern, müssen vorsichtig vorgehen, da Assassinen der Defias die Umgebung patrouillieren und jeden auflauern, der ihr neu besetztes Refugium betritt."}},faq={{q="Wem gehört Yorgens Bauernhof?",a="Das Gehöft wurde ursprünglich von Sven Yorgen erbaut und bewirtschaftet. Nachdem eine Tragödie sein Heim heimgesucht hatte und er von den wachsenden Gefahren vertrieben wurde, floh Sven in ein einsames Lager weiter nördlich am Dunklen Ufer.",al={"wer lebte hier","wem gehört yorgens bauernhof","sven yorgen bauernhof"}},{q="Wer besetzt das Gehöft jetzt?",a="Die Bruderschaft der Defias hat das verlassene Anwesen an sich gerissen. Beutelschneider, Banditen und getarnte Assassinen streifen durch die überwucherten Höfe und Scheunenanlagen, was einen Besuch des Bauernhofs äußerst gefährlich macht.",al={"wer ist bei yorgens bauernhof","welche feinde sind hier","wer lebt jetzt hier"}},{q="Wohin ist Sven Yorgen gegangen?",a="Sven gab die Farm auf und hält sich nun in einem bescheidenen Lager am Dunklen Ufer auf, das im Norden an dem Fluss liegt, der den Dämmerwald und den Wald von Elwynn trennt.",al={"wo ist sven","sven yorgen aufenthaltsort","sven yorgen finden"}},{q="Warum ist die Bruderschaft der Defias im Dämmerwald?",a="Die Bruderschaft der Defias hat ihre Operationen weit über Westfall hinaus ausgeweitet. Unorganisierte ländliche Siedlungen und geschwächte regionale Verteidigungsanlagen ermöglichen es ihren Agenten, geheime Lager und Stützpunkte außerhalb der Reichweite von Sturmwinds Marschällen zu errichten.",al={"defias im dämmerwald","warum sind banditen hier","bruderschaft der defias bauernhof"}}},fx={["70ba336a"]={q="Was ist Yorgens Bauernhof?",a="Yorgens Bauernhof ist ein verlassener Bauernhof im südlichen Dämmerwald. Einst ein friedliches Gehöft, das Sven Yorgen gehörte und bewirtschaftet wurde, ist es zusammen mit einem Großteil der schattigen Region verfallen. Heute wurde der Hof von Briganten der The Defias Brotherhood besetzt und eingenommen.",al={"was ist yorgens bauernhof","infos zu yorgens bauernhof","erzähle mir von yorgens bauernhof"}},["7755c939"]={q="Ist Yorgens Bauernhof gefährlich?",a="Ja, sich dem Bauernhof zu nähern ist außerordentlich gefährlich. Das Gelände ist von Mitgliedern der The Defias Brotherhood verseucht, darunter verstohlene Attentäter, die unsichtbar zwischen den ruinierten Gebäuden und den überwucherten Feldern patrouillieren, bereit jeden in einen Hinterhalt zu locken, der sich zu nahe heranwagt.",al={"ist yorgens bauernhof gefährlich","gefahr yorgens bauernhof","bedrohungen yorgens bauernhof"}}},fp="16,252,18.482.0,19.423.0,30.205.0,31.192.0,25.172.0,42.229.0"}
P.entries["subzone:zalashji-s-den"] = {n="Zalashjis Bau",s="Zalashjis Bau ist eine abgelegene Höhle an der Ostküste von Tanaris. Sie dient als einsamer Unterschlupf von Zalashji, einem rätselhaften Naga, der weit entfernt von den üblichen Sammelplätzen seiner schlangenartigen Artgenossen weilt.",h="Zalashjis Bau ist eine abgelegene Höhle an der Ostküste von Tanaris.",kw={"höhle","küste","naga","tanaris","zalashji","zalashjis bau"},ang={["race:NightElf"]="Für die Nachtelfen ist jede Präsenz der verfluchten, mutierten Naga an den Gestaden Kalimdors eine düstere Erinnerung an die uralten Hochgeborenen und die Zerschlagung."},sec={{t="Ein einsamer Unterschlupf",b="Eingebettet in die schroffen Klippen entlang der östlichen Küstenlinie von Tanaris bietet diese Höhle an der Küste einer einzigen Kreatur Zuflucht: Zalashji. In ganz Kalimdor ist bekannt, dass sich Naga in disziplinierten Kriegstrupps oder Küstenaußenposten zusammenschließen, doch Zalashji haust hier vollkommen allein. Über die Gründe, warum er diese isolierte Höhle fernab der Hauptsiedlungen und Wüstenruinen der Region zu seinem Refugium auserkoren hat, ist wenig bekannt, doch Reisende, die sich entlang der Brandung wagen, sollten sich dem Höhleneingang mit Vorsicht nähern."}},faq={{q="Wo befindet sich Zalashjis Bau?",a="Die Höhle befindet sich an der Ostküste von Tanaris, eingelassen in die felsigen Klippen, die an die Meeresfluten grenzen.",al={"zalashji aufenthaltsort","wo ist zalashjis bau","zalashji höhle"}},{q="Wer ist Zalashji?",a="Zalashji ist ein einzelner Naga, der diese isolierte Höhle an der Küste zu seiner Heimat gemacht hat und sich fernab größerer Naga-Streitkräfte an der Wüstenküste aufhält.",al={"wer ist zalashji","zalashji lore","was ist zalashji"}},{q="Gibt es Quests, die mit dieser Höhle verbunden sind?",a="Es gibt keine bekannten Quests, die Abenteurer zu Zalashjis Bau führen. Er bleibt ein merkwürdiger Orientierungspunkt für Küstenforscher, die den östlichen Rand von Tanaris bereisen.",al={"zalashjis bau quests","gibt es hier eine quest","zalashji quest"}},{q="Warum lebt ein Naga allein in Tanaris?",a="Seine wahren Beweggründe bleiben unbekannt. Während sich Naga für gewöhnlich in der Nähe versunkener Ruinen oder organisierter Lager sammeln, bleibt Zalashji in diesem einsamen Unterschlupf am Meer für sich.",al={"warum ist zalashji allein","naga in tanaris","warum ist zalashji hier"}}},fp="14,211,15.496.0,32.117.0,16.142.0,47.162.0,38.165.0"}
P.entries["subzone:zoram-gar-outpost"] = {n="Außenposten von Zoram'gar",s="Außenposten von Zoram'gar ist ein befestigter Brückenkopf der Horde, der am westlichen Rand von Eschental entlang des Zoramstrandes liegt. Als entscheidendes Küstenlager dient es der Horde als Zugang zum Verschleierten Meer und überwacht regionale Bedrohungen wie die eindringenden Naga und die finsteren Tiefen in der Nähe.",h="Außenposten von Zoram'gar ist ein befestigter Brückenkopf der Horde, der am westlichen Rand von Eschental...",kw={"eschental","tiefschwarze grotte","horde","naga","außenposten","zoram gar","der zoramstrand","zoram'gar"},ang={["faction:Alliance"]="Als fest etablierte Präsenz der Horde an der Küste von Eschental repräsentiert Zoram'gar einen gefährlichen Versorgungsstützpunkt in der Nähe der angestammten Länder der Nachtelfen.",["faction:Horde"]="Der Außenposten dient Euch als primäre Zuflucht im Nordwesten von Eschental und bietet Schutz, Ruhe und Windreiter-Transport inmitten der gefährlichen Wildnis."},sec={{t="Eine Bastion am Strand",b="Gelegen am nordwestlichen Rand von Eschental, wo der uralte Wald ins Meer abfällt, dient Außenposten von Zoram'gar der Horde als isolierter Stützpunkt an der Küste am Zoramstrand. Eingekeilt zwischen dem Gebiet der Nachtelfen im Landesinneren und maritimen Gefahren auf See, fungiert das Lager als Ausgangspunkt für Kundschafter, Jäger und Schamanen, die mit der Beobachtung lokaler Gefahren betraut sind. Das Leben am Außenposten ist eine endlose Wache: Naga durchstreifen regelmäßig das seichte Wasser, während lauernde Kultisten und urzeitliche Schrecken aus dem unterirdischen Höhlensystem, das als Tiefschwarze Grotte bekannt ist, direkt die Küste entlang pulsieren."},{t="Strategische Bedeutung",b="Aufgrund seiner peripheren Lage unterhält Zoram'gar Flugverbindungen mit anderen kritischen Stützpunkten der Horde wie Splitterholzposten, Das Wegekreuz und Donnerfels. Obwohl er flächenmäßig klein ist, bildet der Außenposten den Ankerpunkt für die Versorgungslinien der Horde an der Westküste."}},faq={{q="Warum hat die Horde Außenposten von Zoram'gar errichtet?",a="Die Horde errichtete das Lager, um einen Stützpunkt an der Westküste von Eschental zu sichern. Es ermöglicht die maritime Überwachung entlang des Zoramstrandes und bietet eine verteidigbare Station, um den aggressiven Naga entgegenzutreten, die die Küste heimsuchen.",al={"warum gibt es zoram'gar","zweck von zoram gar","warum baute die horde zoram gar"}},{q="Welchen Bedrohungen sieht sich der Außenposten gegenüber?",a="Die unmittelbare Bedrohung geht von den Wrathtail-Naga aus, die über den Zoramstrand kriechen. Zusätzlich stellen die Kultisten des Schattenhammers und tierische Schrecken, die in den nahegelegenen Tempelruinen der Tiefschwarzen Grotte hausen, eine ständig lauernde Gefahr dar.",al={"bedrohungen für zoram gar","feinde bei zoram gar"}},{q="Wohin verbindet der Flugmeister den Außenposten?",a="Außenposten von Zoram'gar verbindet Windreiter über ganz Kalimdor und verknüpft Reisende mit Splitterholzposten, Sonnenfels, Das Wegekreuz und der Hauptstadt der Tauren, Donnerfels.",al={"flugrouten zoram gar","wohin kann ich von zoram gar fliegen"}},{q="Welche Beziehung besteht zwischen dem Außenposten und der Tiefschwarzen Grotte?",a="Die Tiefschwarze Grotte liegt nördlich des Außenpostens entlang der Küstenruinen. Die in Zoram'gar stationierten Streitkräfte der Horde überwachen die Verderbnis, die aus dem überfluteten Tempel sickert, und entsenden Abenteurer hinein, um den Kultisten und ihrem Biest, Aku'mai, entgegenzuwirken.",al={"blackfathom-tiefe in der nähe von zoram","ist bfd nahe zoram gar"}}},fx={bbfe9eaf={q="Was ist der Außenposten von Zoram'gar?",a="Der Außenposten von Zoram'gar ist ein befestigter Brückenkopf der Horde am Der Zoramstrand, der im nordwestlichen Eschental entlang der Verschleierten See liegt. Er bietet der Horde einen lebenswichtigen Zugang zur Westküste und fungiert als Küstenlager und militärischer Bereitstellungsort, isoliert inmitten von feindlichem Gebiet.",al={"was ist der außenposten von zoram'gar","außenposten von zoram'gar im überblick","über den außenposten am der zoramstrand"}},["53f73dc3"]={q="Ist der Außenposten von Zoram'gar gefährlich?",a="Der Außenposten selbst bietet Sicherheit, Verteidigung und Zuflucht für Reisende der Horde, doch der umliegende Der Zoramstrand ist gefährlich. Aggressive Naga patrouillieren an der Brandung und in den nahegelegenen Ruinen, während Truppen der Allianz und uralte Schrecken, die in der Tiefschwarze Grotte lauern, jeden bedrohen, der sich vom Schutz des Lagerfeuers entfernt.",al={"wie gefährlich ist zoram'gar","gefahren am außenposten von zoram'gar","ist der der zoramstrand sicher"}}},fp="17,302,23.568.0,20.255.0,46.229.0,35.235.0,49.185.0,63.250.0"}
P.entries["subzone:zoram-strand"] = {n="Der Zoramstrand",s="Der Zoramstrand ist ein windgepeitschter Küstenstreifen am nordwestlichen Rand von Eschental entlang des Veiled Sea. Einst die Stätte einer uralten nachtelfischen Stadt, die von der Großen Zerschlagung verschlungen wurde, wird das Ufer heute von Wrathtail-Naga, Schiffswracks und gestrandeten Leviathanen heimgesucht. Hier befindet sich auch der Eingang zur versunkenen Tempelanlage der Tiefschwarzen Grotte.",h="Der Zoramstrand ist ein windgepeitschter Küstenstreifen am nordwestlichen Rand von Eschental entlang des...",kw={"eschental","tiefschwarze grotte","naga","ruuzel","veiled sea","wrathtail","zoram","der zoramstrand"},ang={["faction:Horde"]="Die Verteidigung der Zugänge zum Außenposten von Zoram'gar ist von entscheidender Bedeutung, um eine nördliche Flotten- und Küstenpräsenz in Eschental gegen die unerbittliche Wrathtail-Brut aufrechtzuerhalten.",["race:NightElf"]="Der Strand ist eine ernüchternde Erinnerung an die durch die Zerschlagung verlorene alte Welt, in der heilige Relikte und versunkene Tempel der Elune nun unter den Tritten der Naga leiden."},sec={{t="Ruinen der zerschlagenen Küste",b="Vor zehntausend Jahren zierte die erhabene Nachtelfenstadt Zoram diese Gestade, bevor die Große Zerschlagung Kalimdor entzweiriss und die Siedlung in die Tiefen des Ozeans stürzte. Heute spült die Flut unaufhörlich uralte Relikte, Überreste zerschellter Schiffe und die Kadaver gewaltiger Meeresbestien an. Die Wrathtail-Naga haben die Strände und Gezeitentümpel überrannt und verteidigen die überfluteten Ruinen sowie uralte Artefakte erbittert gegen jeden, der sich heranzuwagen droht."},{t="Eine umkämpfte Küstenlinie",b="Trotz der Bedrohung durch die Naga zieht es Reisende vom Festland wie auch Küstenwanderer an den Strand. Im Süden liegt das befestigte Horde-Lager Außenposten von Zoram'gar, dessen Krieger einen ständigen Kampf um die Sicherung der Küste führen. Tief in den nahegelegenen Höhlen befindet sich die Tiefschwarze Grotte, ein uralter Tempel von Elune, der in dunkle Hände gefallen ist, was den Strand zu einem Sammelplatz für Kundschafter, Gelehrte und Schatzsucher macht, die der Brandung trotzen."}},faq={{q="Was war Zoram, bevor es zerstört wurde?",a="Vor der Großen Zerschlagung vor zehntausend Jahren war Zoram eine majestätische Nachtelfenstadt. Der Kataklysmus zerschmetterte die Küste, stieß die Stadt in das Veiled Sea hinab und hinterließ lediglich zerklüftete Ruinen sowie angeschwemmte Statuetten entlang des Ufers.",al={"geschichte von zoram","antikes zoram","was war zoram"}},{q="Wer kontrolliert heute den Zoramstrand?",a="Die Küstenlinie selbst ist weitgehend von den Wrathtail-Naga überrannt, die das Flachwasser und die uralten Ruinen erbittert verteidigen. Die Horde hält an den südlichen Klippen im Außenposten von Zoram'gar einen befestigten Stützpunkt, während gefährliche Wildtiere wie Hydren und Krabben den Sand durchstreifen.",al={"wer lebt am zoramstrand","zoramstrand feinde","wer kontrolliert den zoramstrand"}},{q="Wo befindet sich der Eingang zur Tiefschwarzen Grotte?",a="Der Eingang zur Tiefschwarzen Grotte befindet sich in den überfluteten Höhlen am Zoramstrand. Reisende wagen sich in die Küstenhöhlen am Rande des Wassers, um den Abstieg in den versunkenen Tempel zu erreichen.",al={"blackfathom-tiefe standort","wie man bfd findet","bfd eingang zoram"}},{q="Warum gibt es hier so viele gestrandete Meereskreaturen?",a="Die ungestümen Gezeiten und dunklen Strömungen des Veiled Sea spülen häufig gewaltige Meereskreaturen an Land. Forscher und Naturkundler beider Fraktionen suchen diese Überreste oft auf, um zu untersuchen, was die Ozean-Giganten dazu treibt, an den Felsen zu verenden.",al={"gestrandete meereskreatur quest","tote wale zoramstrand","gestrandete kreaturen"}}},fx={["449b54c1"]={q="Was ist der Der Zoramstrand?",a="Der Der Zoramstrand ist ein zerklüfteter Küstenstreifen im nordwestlichen Eschental, der an die Verschleierte See grenzt. Einst Teil einer uralten Nachtelfenstadt vor dem Großen Auseinanderbrechen, ist der Strand heute ein umkämpftes Ufer, übersät mit Schiffswracks, gestrandeten Leviathans und Ruinen. Er dient sowohl als Standort für den befestigten Außenposten von Zoram'gar der Horde als auch als Zugang zur Oberfläche, der in das unterirdische Labyrinth der Tiefschwarze Grotte führt.",al={"was ist der der zoramstrand","informationen zum der zoramstrand","über den der zoramstrand"}},["7861a3b9"]={q="Warum ist der Der Zoramstrand zerstört?",a="Vor zehntausend Jahren, während des Großen Auseinanderbrechens, wurde die uralte Nachtelfensiedlung Zoram zertrümmert und größtenteils unter den steigenden Wassern der Verschleierten See ertränkt. Was heute an der Küste übrig ist, ist nur der zerstörte Rand dieser gefallenen Stadt, der lange dem Verfall preisgegeben war, bis die schlangenartigen Naga aus den Tiefen des Ozeans auftauchten, um das Ufer und seine versunkenen Tempel für sich zu beanspruchen.",al={"warum ist zoram zerstört","was geschah mit zoram","zerstörung des der zoramstrand"}},["3de65288"]={q="Ist der Der Zoramstrand gefährlich?",a="Sehr. Die Küstenlinie wird von den aggressiven Wrathtail-Naga überrannt, die die Ruinen erbittert verteidigen und Reisende am Wasserrand angreifen. Feindselige Krabben und bösartige Hydren lauern in den Wellen und zwischen gestrandeten Kadavern. Jenseits der Bedrohungen der Wildnis verstecken sich dunkle Kultisten und finstere Schrecken unter der Oberfläche in den Gängen der Tiefschwarze Grotte, was diesen nebelverhangenen Strand für Unvorsichtige unsicher macht.",al={"wie gefährlich ist der der zoramstrand","bedrohungen am der zoramstrand","bedrohungen entlang des der zoramstrand"}},["8dedb8fb"]={q="Warum wird er Der Zoramstrand genannt?",a="Die Küste hat ihren Namen von Zoram, der uralten Nachtelfenstadt, die vor dem Großen Auseinanderbrechen entlang dieser Küste stand. Obwohl die ursprüngliche Stadt zertrümmert und vom Ozean verschluckt wurde, tragen der überlebende Strand und die umliegenden Ruinen seitdem ihren Namen.",al={"woher hat zoram seinen namen","warum der zoramstrand","bedeutung von der zoramstrand"}}},fp="12,345,27.453.0,21.453.0,39.239.0,36.269.0,43.202.0,49.251.0"}
P.entries["subzone:zul-gurub"] = {n="Zul'Gurub",s="Zul'Gurub ist eine uralte Tempelstadt tief in den Dschungeln des nordöstlichen Schlingendorntals. Einst das ruhmreiche Herz des weitläufigen Gurubashi-Imperiums, steht sie heute als gefährliche Festung da, in der Dschungeltrolle finstere Pläne schmieden, um ein uraltes, schreckliches Wesen in die Welt zu beschwören.",h="Zul'Gurub ist eine uralte Tempelstadt tief in den Dschungeln des nordöstlichen Schlingendorntals.",kw={"atal'ai","gurubashi","hakkar","jin'do","seelenschinder","schlingendorntal","trollhauptstadt","zul'gurub"},ang={["faction:Horde"]="Die Horde hat ein wachsames Auge auf die dunklen Rituale in Zul'Gurub, wohl wissend, dass die Rückkehr des Blutgottes eine existenzielle Bedrohung für die Sicherheit der nahegelegenen Siedlungen und Stämme im gesamten Schlingendorntal darstellt.",["race:Troll"]="Für den Stamm der Dunkelspeer stellt Zul'Gurub sowohl ein tragisches Denkmal an die gefallene Größe ihrer Ahnen als auch eine furchterregende Warnung vor dem verheerenden Preis dar, den der Dienst an Hakkar fordert."},sec={{t="Das Herz des gefallenen Imperiums",b="Vor Tausenden von Jahren herrschte Zul'Gurub als pulsierende Hauptstadt des gesamten Gurubashi-Imperiums und vereinte die Stämme der Dschungeltrolle unter seinen gewaltigen steinernen Zikkurats. Dieses goldene Zeitalter endete vor rund fünfzehnhundert Jahren vor der Öffnung des Dunklen Portals, als ein erbitterter Bürgerkrieg das Reich zerriss. Eine radikale Priestersekte, die Atal'ai, trachtete danach, Hakkar den Seelenschinder – einen blutrünstigen alten Gott – herbeizurufen, um die absolute Macht an sich zu reißen. Obwohl loyale Stämme sich verbündeten, um die Atal'ai zu besiegen und nach Norden in die Sümpfe des Elends zu verbannen, brach diese Verheerung dem Imperium das Rückgrat und ließ Zul'Gurub als gewaltsamen Schatten seiner einstigen Größe zurück."},{t="Der drohende Schatten des Seelenschinders",b="Obwohl verbannt, gaben die fanatischen Anhänger von Hakkar ihre finstere Hingabe nie auf. Schließlich erkannten sie, dass der physische Avatar ihrer Schreckensgottheit nur am uralten Ritualsitz Zul'Gurub selbst hervorgebracht werden konnte. Im Inneren der Stadt trachteten dunkle Hexenmeister wie Jin'do the Hexxer danach, Hohepriester der Gurubashi zu unterwerfen, um in Hakkars Namen Blutrituale zu vollziehen. Der die Ruinen umgebende Dschungel wimmelt von äußerst aggressiven Gurubashi-Trollen, die in mörderische Raserei verfallen sind, was die Tempelstadt zu einem Epizentrum des Grauens für jeden macht, der mutig oder töricht genug ist, sich ihren Grenzen zu nähern."}},faq={{q="Was ist Zul'Gurub?",a="Zul'Gurub ist eine uralte Tempelstadt im nordöstlichen Schlingendorntal. Sie diente vor Tausenden von Jahren als Hauptstadt des großen Gurubashi-Imperiums, doch heute ist sie eine gefährliche, verfallene Festung, die vom feindseligen Stamm der Gurubashi bewohnt wird.",al={"zg geschichte","was ist zg","über zulgurub"}},{q="Wer ist Hakkar the Soulflayer?",a="Hakkar the Soulflayer ist ein uralter und schrecklicher Blutgott. Er wird von der fanatischen Trollsekte der Atal'ai verehrt, verlangt unablässig nach Blut und Opfern, und seine Kultisten schmieden seit langem Pläne, um seinen physischen Avatar durch finstere Rituale in Zul'Gurub nach Azeroth zu bringen.",al={"hakkar","blutgott","wer ist der seelenschinder"}},{q="Warum brach das Gurubashi-Imperium zusammen?",a="Rund fünfzehnhundert Jahre vor der Öffnung des Dunklen Portals wurde das Imperium durch einen verheerenden Bürgerkrieg zerrissen. Die radikalen Atal'ai-Priester versuchten, Hakkar zu beschwören, und obwohl die anderen Trolle sie erfolgreich ins Exil trieben, hinterließ der Konflikt das Imperium dauerhaft zerrüttet.",al={"warum gurubashi fiel","gurubashi bürgerkrieg","fall von zul'gurub"}},{q="Können Abenteurer die Ruinen gefahrlos erkunden?",a="Nein. Zul'Gurub ist außerordentlich gefährlich. Die Gurubashi-Trolle, welche die Ruinen bewohnen, sind gewalttätig, aggressiv und von blutiger Inbrunst getrieben. Schatzjäger und Sucher nach Artefakten verschwinden regelmäßig innerhalb der Steinmauern, und nur die wenigsten kehren je zurück.",al={"ist zg sicher","zg schätze","zg erkunden"}}},fp="9,278,26.656.0,36.594.1,18.239.0,29.263.0,38.281.0,41.249.0"}
P.entries["subzone:zul-mashar"] = {n="Zul'Mashar",s="Zul'Mashar ist eine uralte Waldtrollsiedlung, die im nordöstlichsten Winkel der Östlichen Pestländer liegt. Einst die stolze Hauptstadt des Stammes der Mossflayer, ist sie nach andauernden Kriegen mit den Menschenreichen und den Verheerungen durch die Seuche des Untods zu einer trostlosen Ruine verfallen. Heute stehen ihre verbliebenen Verteidiger vor einem schleichenden Untergang, während die Geißel sie von innen heraus zersetzt, um sie in untote Knechte zu verwandeln.",h="Zul'Mashar ist eine uralte Waldtrollsiedlung, die im nordöstlichsten Winkel der Östlichen Pestländer liegt.",kw={"östliche pestländer","waldtroll","hameya","mazra'alor","mossflayer","thresh'jin","warpbranch","zul'mashar"},ang={["race:Troll"]="Für die Dunkelspeere ist das Schicksal der Mossflayer in Zul'Mashar eine düstere Mahnung an das Schicksal isolierter Stämme, die an uraltem Hass festhalten, anstatt in einer sich wandelnden Welt Verbündete zu suchen.",["race:Undead"]="Die Verlassenen betrachten Zul'Mashar mit wachsamem Pragmatismus und beobachten genau, ob der zerfallende Mossflayer-Stamm Widerstand leistet oder unweigerlich die Reihen der Geißel mit neuen, zombifizierten Waldtrollen verstärken wird."},sec={{t="Eine fallende Festung",b="Lange bevor die Geißel über das nördliche Lordaeron hereinbrach, diente Zul'Mashar den Mossflayer-Waldtrollen als Machtsitz. Ständige Grenzscharmützel gegen die Menschen von Lordaeron schwächten nach und nach ihre Vorherrschaft und hinterließen ein zersplittertes Herrschaftsgebiet. Als die Seuche des Untods die Region heimsuchte, traf sie die Mossflayer ebenso erbarmungslos wie ihre Todfeinde. Zwar steht die große Stufen-Zikkurat Mazra'Alor noch immer, doch ist Zul'Mashar nur noch eine hohle Hülle seines einstigen Glanzes. Unter dem Befehl von Warlord Thresh'jin und Zul'Brin Warpbranch klammern sich die verbliebenen Trolle verbissen an ihre uralte Heimat – weitgehend blind für die Tatsache, dass der Einfluss der Geißel bereits ihre Reihen unterwandert und ihre Stammesbrüder unbemerkt in verrottende Monstrositäten verwandelt."},{t="Infiltration aus den Schatten",b="Die wahre Gefahr für Zul'Mashar ist kein direkter Angriff der Geißel, sondern eine schleichende Fäulnis von innen heraus. Selbst während die Mossflayer versuchen, ihre Zikkurat zu verteidigen und ihre Unabhängigkeit im verwüsteten Norden zu wahren, breiten sich Spione und heimliche Seuchen in ihrer Bevölkerung aus. Da Kundschafter wie Infiltrator Hameya in den Ruinen operieren und die lebenden Krieger nach und nach dem Untod anheimfallen, steht die einst stolze Festung kurz davor, gänzlich unter die Herrschaft des Lichkönigs zu geraten, ohne dass es je zu einer großen Schlacht kam."}},faq={{q="Wer kontrolliert Zul'Mashar?",a="Zul'Mashar wird vom Waldtrollstamm der Mossflayer beherrscht, angeführt von Warlord Thresh'jin und Zul'Brin Warpbranch. Ihr Einfluss schwindet jedoch zusehends, da die Seuche des Untods ihre Gemeinschaft unterwandert.",al={"wer lebt in zulmashar","zul mashar herrscher","mossflayer anführer"}},{q="Was ist Mazra'Alor?",a="Mazra'Alor ist die markante Stufen-Zikkurat der Trolle in Zul'Mashar. Sie bildet das architektonische Herz und das spirituelle Zentrum der angestammten Hauptstadt der Mossflayer.",al={"mazraalor","zul mashar pyramide","troll zikkurat östliche pestländer"}},{q="Warum liegt Zul'Mashar in Ruinen?",a="Zul'Mashar wurde durch lange, zermürbende Konflikte gegen das Menschenreich Lordaeron geschwächt, bevor es von der Seuche des Untods heimgesucht wurde. Die Seuche verwüstete das umliegende Land und hinterließ die Mossflayer isoliert und entkräftet.",al={"warum ist zulmashar zerstört","was geschah mit zul mashar"}},{q="Sind die Trolle hier mit der Geißel verbündet?",a="Nein, die lebenden Mossflayer sind Fremden gegenüber feindselig gesinnt und kämpfen für den Schutz ihrer angestammten Ländereien. Die Geißel infiziert und verwandelt ihre Stammesangehörigen jedoch heimlich in Untote, wodurch der Stamm von innen heraus systematisch ausgehöhlt wird.",al={"sind mossflayer geißel","trolle verbündet mit geißel"}}},fp="10,422,20.765.0,29.512.1,24.206.0,19.182.0,27.225.0,44.225.0"}
P.entries["topic:alliance"] = {n="Allianz",s="Die Allianz ist eine große Koalition sterblicher Völker, die durch geteilte Ideale von Ehre, Pflicht und der Verteidigung der Ordnung in ganz Azeroth verbunden sind. Geboren aus der Asche des nördlichen Königreichs Lordaeron, schlägt ihr Herz heute in Sturmwind, vereint an der Seite der Zwerge von Eisenschmiede, der exilierten Gnome und der Nachtelfen von Kalimdor.",h="Die Allianz ist eine große Koalition sterblicher Völker, die durch geteilte Ideale von Ehre, Pflicht und der...",kw={"allianz","allianz von lordaeron","anduin wrynn","bolvar fordragon","darnassus","gnomeregan","große allianz","eisenschmiede","magni bronzebart","mekkadrill","sturmwind"},ang={["faction:Alliance"]="Eure geschworene Fraktion kämpft auf zwei Kontinenten, um Gesetz, Tradition und die Souveränität der Sterblichen gegen die Geißel, wilde Bestien und die vordringende Horde zu wahren.",["faction:Horde"]="Die Horde betrachtet die Allianz als eine festgefahrene, expansionistische Macht, deren selbstgerechte Ideale die Souveränität und das territoriale Überleben ihrer Mitglieder bedrohen.",["race:Dwarf"]="Die Zwerge von Eisenschmiede sind die unerschütterlichsten und treuesten Verbündeten der Menschheit und stellen ihr formidables Eisen, ihre Gebirgsinfanterie und ihre tiefe Freundschaft in den Dienst der Sache der Allianz.",["race:Gnome"]="Als Flüchtlinge in Eisenschmiede lenken die Gnome ihren wissenschaftlichen Erfindungsreichtum in die Flotten der Allianz, im Vertrauen darauf, dass gegenseitige Loyalität letztendlich die Kräfte hervorbringen wird, die zur Befreiung von Gnomeregan erforderlich sind.",["race:Human"]="Als die Hauptarchitekten der Erholung der Fraktion betrachten die Menschen die Allianz als den rechtmäßigen Verteidiger der Zivilisation und das Heilige Licht gegen wilde und dämonische Kräfte.",["race:NightElf"]="Nachdem sie durch den Dritten Krieg aus ihrer Isolation getrieben wurden, navigieren die Nachtelfen durch eine seltsame, notwendige Verwandtschaft mit den jüngeren Völkern, um die territoriale Aggression der Horde im Eschental in Schach zu halten."},sec={{t="Von Lordaeron nach Sturmwind",b="Die moderne Allianz stammt von der ursprünglichen Allianz von Lordaeron ab, die gegründet wurde, als Sir Anduin Lothar während des Zweiten Krieges Flüchtlinge aus Sturmwind in den Norden führte, um die Sieben Königreiche, Zwerge und Hochelfen gegen die alte Horde zu vereinen. Während die Geißel und der Dritte Krieg den Norden dezimierten – was Lordaeron in Ruinen hinterließ und die Überlebenden in einen zersplitterten Widerstand trieb – erhob sich das wiederhergestellte Königreich Sturmwind, um die Lücke zu füllen. Heute steht Sturmwind als der herausragende Sitz der menschlichen Führung und trägt die Banner von Ehre und Glauben in eine zerbrochene Welt."},{t="Eine Koalition aus Notwendigkeit und Verwandtschaft",b="Das Rückgrat der Fraktion in den Östlichen Königreichen beruht auf dem unerschütterlichen Band zwischen den Menschen und den Zwergen von Eisenschmiede unter König Magni Bronzebart. Neben den Zwergen leben die Gnome, die durch einen verheerenden Trogg-Aufstand aus Gnomeregan vertrieben wurden. Unter der Führung von Hochtüftler Gelbin Mekkadrill stellen die exilierten Gnome ihr brillantes Ingenieurswesen in den Dienst der Kriegsanstrengungen der Allianz, in der Überzeugung, dass das Überleben der Koalition von größter Bedeutung ist, um jemals ihre verstrahlte Heimat zurückzuerobern."},{t="Die Front in Kalimdor",b="Jenseits des großen Meeres gaben die zurückgezogen lebenden Nachtelfen nach der Schlacht um den Hyjal ihre jahrtausendelange Isolation auf. Gezeichnet vom Verlust ihrer Unsterblichkeit und verstrickt in erbitterte territoriale Zusammenstöße mit der Horde wegen Holzfällerarbeiten im Eschental, verbündeten sich die Kaldorei mit ihren neu gefundenen sterblichen Gefährten. Obwohl kulturelle Spannungen bestehen bleiben – und einige Traditionalisten die Anwesenheit von Menschen und Zwergen in uralten Wäldern verurteilen – bietet die Allianz lebenswichtige militärische und diplomatische Zusammenarbeit, um Kalimdor gegen dämonische Überreste und die Expansion der Horde zu sichern."},{t="Ungewisse Schatten",b="Trotz ihrer äußeren Stärke wird die Allianz von internen Spannungen geplagt. König Varian Wrynn verschwand unter mysteriösen Umständen auf dem Weg zu einem diplomatischen Gipfeltreffen, wodurch sein junger Sohn Anduin unter der Regentschaft von Hochlord Bolvar Fordragon auf dem Thron zurückblieb. Die Beziehungen zu ehemaligen menschlichen Verbündeten sind zerrüttet: Das maritime Königreich Kul Tiras hält sich fern, während die untoten Verlassenen von Sylvanas Windläufer nun die Ruinen von Lordaeron halten."}},faq={{q="Welche Völker bilden die Allianz?",a="Die Kern-Allianz besteht aus vier Völkern: den Menschen von Sturmwind, den Bergzwergen von Eisenschmiede, den exilierten Gnomen von Gnomeregan und den Nachtelfen von Kalimdor.",al={"völker der allianz","wer gehört zur allianz","spielbare völker der allianz"}},{q="Wer führt die Allianz derzeit an?",a="Es gibt keinen einzigen absoluten Monarchen über die gesamte Allianz. In den menschlichen Landen wird Sturmwind nach dem Verschwinden von König Varian Wrynn von dem Jungenkönig Anduin Wrynn und seinem Regenten Hochlord Bolvar Fordragon regiert. Die anderen Mitgliedsnationen werden von König Magni Bronzebart von Eisenschmiede, Hochtüftler Gelbin Mekkadrill von den Gnomen und der Führung der Nachtelfen in Kalimdor angeführt.",al={"anführer der allianz","wer ist hochkönig","wer regiert sturmwind"}},{q="Wie wurde aus der Allianz von Lordaeron die moderne Allianz?",a="Die ursprüngliche Allianz wurde von König Terenas Menethil II. und Anduin Lothar gegründet, um die alte Horde während des Zweiten Krieges zurückzuschlagen. Nachdem Lordaeron im Dritten Krieg von der Geißel zerstört wurde, verlagerte sich die Führung nach Süden in das wiederaufgebaute Königreich Sturmwind, welches neue Bündnisse mit den Zwergen, Gnomen und Nachtelfen schloss.",al={"allianz von lordaeron vs allianz","was passierte mit lordaeron","ursprung der allianz"}},{q="Warum traten die Nachtelfen der Allianz bei?",a="Nach dem Dritten Krieg und der Schlacht um den Hyjal verloren die Nachtelfen ihre Unsterblichkeit und konnten nicht länger abgeschottet bleiben. Da die Orc-Horde in der Kriegshymnenschlucht im Eschental aktiv Wälder abholzte, schlossen die Kaldorei einen Militärpakt mit den Menschen und Zwergen, um ihre angestammten Länder zu verteidigen.",al={"warum sind nachtelfen in der allianz","geschichte der nachtelfen in der allianz","allianz der kaldorei"}},{q="Warum ist Kul Tiras derzeit kein Teil der Allianz?",a="Kul Tiras war eine Säule der alten Allianz von Lordaeron, blieb aber seit der Zersplitterung dieser Allianz für sich. Sein Großadmiral Daelin Prachtmeer fiel bei einer Invasion von Durotar durch die Horde, und das Inselkönigreich hat sich der neuen Allianz, die von Sturmwind aus geführt wird, nicht angeschlossen.",al={"wo liegt kul tiras","gehört kul tiras zur allianz","daelin prachtmeer kul tiras"}},{q="Warum haben die Gnome während des Dritten Krieges nicht geholfen?",a="Während des Dritten Krieges kam es zu einer unterirdischen Trogg-Invasion in Gnomeregan. Im Glauben, dass die Bedrohung durch die Geißel an der Oberfläche größer sei, verbargen die Gnome ihre Krise vor ihren Verbündeten und kämpften allein. Die Stadt fiel Strahlung und Invasion zum Opfer, was die Überlebenden zwang, nach Eisenschmiede zu fliehen.",al={"wo waren die gnome in warcraft 3","gnome dritter krieg","fall von gnomeregan"}},{q="Wie steht die Allianz zu den Verlassenen?",a="Viele in der Allianz betrachten die Untoten als Abscheulichkeiten und Werkzeuge der Geißel, die Lordaeron zerstörte, und die Allianz hegt offene Feindseligkeit gegenüber den Untoten, die das nördliche Königreich zurückerobern.",al={"sicht der allianz auf die verlassenen","warum hass auf untote","beziehungen zwischen verlassenen und allianz"}}},fx={["90827062"]={q="Was ist die Allianz?",a="Die Allianz ist ein großes Bündnis sterblicher Völker, das sich dem Adel, der Ehre, der Gerechtigkeit und der Bewahrung der Ordnung auf Azeroth verschrieben hat. Entstanden aus den Überresten der gefallenen Allianz von Lordaeron, vereint sie Menschen, Zwerge der Eisenschmiede, Gnome und Nachtelfen unter einem gemeinsamen Ziel. Anstatt rein durch Verzweiflung gebunden zu sein, sind ihre Mitglieder durch gemeinsame Traditionen, Glauben und einen beständigen Abscheu gegen dämonische Verderbnis verbunden. Gemeinsam bündeln sie ihre militärische Macht, ihre technische Fertigkeit und ihr altes Wissen, um ihr Volk zu schützen und das Licht in eine vom Krieg zerrissene Welt zu bringen.",al={"was ist die allianz","wer ist die allianz","große allianz"}},["76fd3754"]={q="Warum bekämpft die Allianz die Horde?",a="Der Konflikt sitzt tief und ist aus Generationen von Blutvergießen geboren. Die Allianz erinnert sich an die Brutalität des Ersten und Zweiten Krieges, als die ursprüngliche Horde das Königreich Sturmwind zerstörte und die Östlichen Königreiche verwüstete. Selbst nachdem man sich vorübergehend am Hyjal vereinte, bleibt der Friede zerbrechlich und bitter. Laufende Scharmützel um Ressourcen, wie die fortdauernden Rodungen des Kriegshymnenclans in den angestammten Wäldern des Eschental, lassen die Feindseligkeit hochkochen. Für viele in der Allianz stellt die Horde eine ungezähmte und gefährliche Bedrohung dar, vor der man sich ständig in Acht nehmen muss.",al={"warum gegen die horde kämpfen","warum die horde hassen","allianz-horde-konflikt","warum krieg mit der horde"}},["760e04fc"]={q="Was bedeutet es, der Allianz zu dienen?",a="Die Allianz zu verfechten bedeutet, als Bollwerk für Pflicht, Gerechtigkeit und Ordnung gegen die eindringende Dunkelheit einzustehen. Ob Ihr aus den Hallen der Eisenschmiede, den Türmen von Sturmwind, den Flüchtlingswerkstätten der Tüftlerstadt oder den heiligen Ästen von Teldrassil stammt, Ihr seid geschworen, verbündete Ländereien vor Monstern, Eindringlingen und dem wilden Zugriff der Feinde zu schützen. Zu dienen bedeutet, das höhere Wohl und noble Ideale über den individuellen Gewinn zu stellen, heilige Traditionen aufrechtzuerhalten und das Überleben freier Völker auf Azeroth zu sichern.",al={"der allianz dienen","pflichten bei der allianz","was erwartet die allianz"}}},fp="8,327,27.555.0,36.457.0,18.556.0,14.429.0,32.167.0,33.376.0,61.330.0,42.298.0,52.271.0,48.266.0,50.198.0"}
P.entries["topic:alliance-of-lordaeron"] = {fx={dd426ccb={q="Wer war Teil der Allianz von Lordaeron?",a="Das Bündnis vereinte alle sieben Menschenkönigreiche: Lordaeron, Sturmwind, Stromgarde, Kul Tiras, Dalaran, Gilneas und Alterac. Während der Zweite Krieg eskalierte, schlossen sich ihnen die Bronzebartzwerge aus Eisenschmiede, die Wildhammerzwerge vom Nistgipfel, die Gnome von Gnomeregan und die Hochelfen von Quel'Thalas an, neben den Paladinen der Silbernen Hand und der Kirche des Heiligen Lichts.",al={"mitglieder der allianz von lordaeron","wer trat der allianz von lordaeron bei","nationen der allianz von lordaeron"}},["913db280"]={q="Warum wurde sie Allianz von Lordaeron genannt?",a="Sie verdiente sich den Namen, weil das nördliche Königreich Lordaeron als das Herz und der Sammelpunkt der Vereinigung diente. König Terenas Menethil II. von Lordaeron rief die Sieben Königreiche in der Hauptstadt zusammen, um auf den Fall von Sturmwind zu reagieren, und Lordaeron fungierte als politischer Anker und primärer militärischer Versorger während des Zweiten Krieges.",al={"warum allianz von lordaeron","bedeutung des namens allianz von lordaeron","warum nennt man sie allianz von lordaeron"}}}}
P.entries["topic:alterac-kingdom"] = {fx={a8320e62={q="Was war das Königreich Alterac?",a="Alterac war eine der sieben historischen Menschennationen, angesiedelt in den hohen, zerklüfteten Gipfeln des Alteracgebirges. Ursprünglich als befestigter Stadtstaat des alten Imperiums von Arathor gegründet, wuchs es zu einem unabhängigen Königreich heran, das strategische Gebirgspässe und Handelsrouten kontrollierte. Obwohl kleiner und militärisch schwächer als Nachbarn wie Lordaeron und Stromgarde, hielt Alterac lebenswichtiges Territorium zwischen den nördlichen Königreichen, bis sein katastrophaler Verrat während des Zweiten Krieges seinen Status für immer erschütterte.",al={"was ist alterac","das königreich alterac im überblick","wer sind die leute von alterac"}},["6b4d83cf"]={q="Wer führt das Volk von Alterac jetzt?",a="Das Königreich selbst hat nach der Inhaftierung und dem Tod von König Aiden Perenolde keinen anerkannten Herrscher oder eine geeinte Regierung mehr. Seine Überreste sind zersplittert: Viele enteignete Adlige und Bürger sammeln sich unter Aidens Sohn, Lord Aliden Perenolde, der das Syndikat in einem gesetzlosen Feldzug anführt, um ihre angestammten Ländereien zurückzuerobern. Unterdessen bleibt ihre zerstörte Hauptstadt von wilden Bestien und rivalisierenden Fraktionen umkämpft.",al={"wer führt alterac an","der könig von alterac","anführer von alterac"}},["080e3676"]={q="Mit wem ist Alterac verbündet?",a="Als anerkannte Nation hat Alterac keine Verbündeten mehr. Es brach seinen ursprünglichen Pakt mit der Allianz von Lordaeron während des Zweiten Krieges, um Orgrim Schicksalshammars Horde zu unterstützen, was ihm die bleibende Feindschaft der anderen Menschenreiche einbrachte. Heute agieren seine adligen Überreste innerhalb des Syndikats als Gesetzlose, die mit angeheuerten Halsabschneidern und Schurken zusammenarbeiten, während sie sowohl gegen die Allianz als auch gegen die neue Horde ums Überleben kämpfen.",al={"verbündete von alterac","für wen kämpft alterac","wer unterstützt alterac"}}}}
P.entries["topic:anduin-lothar"] = {n="Anduin Lothar",s="Sir Anduin Lothar, bekannt als der Löwe von Sturmwind, war der letzte Nachfahre der uralten Arathi-Blutlinie und der Oberkommandierende der Allianz von Lordaeron. Als Jugendfreund von König Llane Wrynn und dem Wächter Medivh führte Lothar die Menschheit durch die Schrecken des Ersten Krieges und versammelte die nördlichen Nationen während des Zweiten Krieges, bevor er am Schwarzfels fiel.",h="Sir Anduin Lothar, bekannt als der Löwe von Sturmwind, war der letzte Nachfahre der uralten Arathi-Blutlinie...",kw={"anduin lothar","arathi","der schwarzfels","bruderschaft des pferds","löwe von sturmwind","llane wrynn","lothar","oberkommandierender"},ang={["class:Paladin"]="Lothar unterstützte die neu entstehenden Ritter der Silbernen Hand während des Zweiten Krieges und setzte sein Vertrauen in Paladine wie Turalyon, der nach seinem Fall Lothars zerbrochenes Schwert aufhob, um die Allianz zum Sieg zu führen.",["class:Warrior"]="Angesehen als einer der besten Wappenrockträger und Schlachtfeldkommandanten, die je gelebt haben, dienen Lothars Beherrschung berittener Taktiken und seine schiere militärische Entschlossenheit als Inspiration für Krieger in ganz Azeroth.",["faction:Alliance"]="Lothar war der grundlegende Architekt und erste Oberkommandierende der Allianz, der Elfen, Zwerge und Menschen vereinte, um die Horde aus den Östlichen Königreichen zu drängen.",["race:Human"]="Für die Menschheit ist Lothar das ultimative Vorbild für Opferbereitschaft und Ehre. Sein Arathi-Blut brachte die verschiedenen menschlichen Königreiche zusammen, und sein tragischer Tod am Schwarzfels besiegelte die Befreiung des Königreichs."},sec={{t="Die Jugend des Löwen",b="Als Träger der uralten Blutlinie der Arathi-Könige wuchs Lothar am königlichen Hof von Sturmwind an der Seite von Prinz Llane Wrynn und Medivh auf. Das Trio unternahm waghalsige Ausflüge in die Wildnis und scharmützelte mit Gurubashi-Trollen im Schlingendorntal. Lothar stieg schnell in den militärischen Rängen von Sturmwind auf, trat der Ehrengarde des Königs bei und erlangte Ruhm als Wappenrockträger der Bruderschaft des Pferds."},{t="Der Fall von Sturmwind",b="Als geheimnisvolle, grüne Eindringlinge aus dem Sümpfen des Elends strömten, ernannte König Llane Lothar zum Champion des Königs, um die Verteidigung des Königreichs zu organisieren. Lothar leistete Pionierarbeit bei verheerenden Hinterhalten gegen orcische Plündertrupps in Westfall, dem Rotkammgebirge und dem Wald von Elwynn, manövrierte Kriegshäuptling Schwarzfaust aus und brach die erste Belagerung von Sturmwind. Doch Verrat besiegelte das Schicksal des Königreichs von innen heraus: Medivh wurde als der Architekt entlarvt, der das Dunkle Portal geöffnet hatte, was Lothar und den Lehrling Khadgar dazu zwang, Karazhan zu stürmen und den korrumpierten Wächter hinzurichten. Als er zurückkehrte und König Llane ermordet sowie Sturmwind in Flammen vorfand, sammelte Lothar die Überlebenden – darunter den jungen Prinzen Varian – und evakuierte sie nach Norden über das große Meer."},{t="Oberkommandierender und der Schwarzfels",b="Nach seiner Ankunft an den Küsten von Lordaeron schilderte Lothar König Terenas Menethil II. die grausame Realität der Horde. Indem er sich auf seine arathische Abstammung und sein diplomatisches Gewicht berief, vereinte er die menschlichen Reiche, die Zwerge der Eisenschmiede und die Hochelfen zur Großen Allianz von Lordaeron. Zum Oberkommandierenden der vereinten Streitkräfte ernannt, führte Lothar den Feldzug an, der die Horde zurück in den Süden bis zum Fuße des Schwarzfels drängte. Dort, in einem schicksalhaften Gefecht gegen Ende des Zweiten Krieges, wurde Lothar von Kriegshäuptling Orgrim Schicksalshammer erschlagen. Sein Tod erschütterte die Allianz jedoch nicht; stattdessen spornte er seinen Leutnant Turalyon dazu an, den Angriff anzuführen, der die Horde für immer zerschlug."}},faq={{q="Wer war Anduin Lothar?",a="Sir Anduin Lothar war ein Ritter von Sturmwind und der letzte Nachfahre der Arathi-Blutlinie. Er diente während des Ersten Krieges als Champion des Königs und wurde später während des Zweiten Krieges zum Oberkommandierenden der Allianz von Lordaeron. Er ist als einer der größten Helden und Taktiker in der Geschichte der Menschheit in Erinnerung geblieben.",al={"wer ist lothar","wer war lothar","löwe von sturmwind hintergrund"}},{q="Wie starb Lothar?",a="Lothar wurde während des Höhepunkts des Zweiten Krieges am Fuße des Schwarzfels erschlagen. Er kämpfte im Zweikampf gegen Kriegshäuptling Orgrim Schicksalshammer und fiel kurz bevor die Streitkräfte der Allianz unter Turalyon die Horde in die Flucht schlugen und sie bis zum Dunklen Portal verfolgten.",al={"lothars tod","wie starb lothar","wer tötete lothar"}},{q="Warum heißt der aktuelle Prinz Anduin?",a="König Varian Wrynn benannte seinen jungen Sohn, Prinz Anduin Wrynn, zu Ehren von Sir Anduin Lothar. Lothar rettete Varian als Kind aus den Ruinen von Sturmwind, beschützte ihn im Exil und eroberte ihre Heimat durch sein Opfer im Zweiten Krieg zurück.",al={"warum heißt anduin anduin","anduin wrynn namensherkunft"}},{q="Was war Lothars Verbindung zu Medivh und König Llane?",a="Lothar, Prinz Llane Wrynn und der junge Magier Medivh waren unzertrennliche Jugendfreunde am königlichen Hof von Sturmwind. Sie erkundeten gemeinsam Azeroth in ihrer Jugend und kämpften gegen Trolle und Bestien. Tragischerweise war Lothar später gezwungen, den Angriff auf Medivh in Karazhan anzuführen, nachdem er entdeckt hatte, dass sein Freund das Reich verraten und die Horde beschworen hatte.",al={"lothar medivh llane","lothars jugendfreunde"}},{q="Warum wird Lothar der 'Letzte der Arathi' genannt?",a="Lothar war der letzte direkte Spross der uralten Arathi-Linie, der Dynastie, die ursprünglich die Menschheit vereinte und das Imperium von Arathor vor Jahrtausenden gründete. Dieses prestigeträchtige Erbe verlieh ihm immenses diplomatisches Ansehen, als er die zerstrittenen nördlichen Könige unter dem Banner der Allianz in Lordaeron vereinte.",al={"lothar arathi blutlinie","arathi nachfahre"}},{q="Welche Rolle spielte Lothar in der Bruderschaft des Pferds?",a="Lothar wurde früh in seiner Karriere zum Ritter geschlagen und stieg in die Position eines Wappenrockträgers innerhalb der Bruderschaft des Pferds auf, Sturmwinds Eliteorden der berittenen Ritter. Er nutzte deren disziplinierte Kavallerieangriffe, um während des gesamten Ersten Krieges wiederholt die Hordenformationen zu flankieren und zu zerschlagen.",al={"bruderschaft des pferds lothar","ritter von sturmwind lothar"}}},fp="13,379,16.409.0,21.740.1,40.666.0,22.313.0,19.247.0,39.246.0,54.354.0,46.300.0,55.280.0"}
P.entries["topic:argent-dawn"] = {fx={a2a95d31={q="Was ist die Argentumdämmerung?",a="Die Argentumdämmerung ist ein neutraler Ritterorden, der sich dem Schutz Azeroths vor zerstörerischen Übeln verschrieben hat, allen voran der Geißel und der Brennenden Legion. Anders als politische Fraktionen oder isolierte Sekten heißt die Dämmerung Mitglieder und Recken jedes Volkes ohne Unterschied willkommen, einzig vereint durch ihre Hingabe an das Licht und ihre Weigerung, die Welt der Dunkelheit anheimfallen zu lassen.",al={"wer ist die argentumdämmerung","der orden der argentumdämmerung","was tut die argentumdämmerung"}},fb8338d1={q="Wer führt die Argentumdämmerung?",a="Lord Maxwell Tyrosus führt die Argentumdämmerung und leitet ihren Kreuzzug gegen die Untoten von ihrem primären Zufluchtsort in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern aus.",al={"anführer der argentumdämmerung","wer leitet die argentumdämmerung","lord tyrosus und die argentumdämmerung"}},["7fcb74f5"]={q="Mit wem ist die Argentumdämmerung verbündet?",a="Die Argentumdämmerung bewahrt strikte politische Neutralität und zählt sowohl die Allianz als auch die Horde zu ihren Verbündeten im größeren Kampf gegen das Böse. Ihre Offiziere rekrutieren Helden sowohl aus Sturmwind als auch aus Orgrimmar. Während sie mit der The Scarlet Crusade gemeinsame untote Feinde haben und gelegentlich einen unbehaglichen Waffenstillstand durch die Bruderschaft des Lichts halten, betrachten sie den eifrigen Fanatismus der Kreuzzügler als gefährliche Ketzerei.",al={"verbündete der argentumdämmerung","arbeitet die argentumdämmerung mit der horde zusammen","wer arbeitet mit der argentumdämmerung"}},["7042b727"]={q="Wie wurde die Argentumdämmerung gegründet?",a="Nach dem Fall von Lordaeron und dem Mord an Hochlord Alexandros Mograine zersplitterten die Überreste der Silbernen Hand. Während viele Ritter zealotischer Paranoia erlagen und die The Scarlet Crusade bildeten, spalteten sich diejenigen ab, die von diesem aufkeimenden Extremismus angewidert waren. Entschlossen, die wahren Lehren des Lichts ohne Vorurteile zu wahren, gründeten sie die Argentumdämmerung, um die Geißel ehrenhaft zu bekämpfen.",al={"geschichte der argentumdämmerung","ursprung der argentumdämmerung","wie entstand die argentumdämmerung"}}}}
P.entries["topic:arthas-menethil"] = {fx={b80d5fb0={q="Wer führt Arthas Menethil an?",a="Arthas dient dem Lichkönig, dem obersten Meister der untoten Geißel. Ursprünglich aus Rache nach Nordend gezogen, nahm Arthas die verfluchte Runenklinge Frostgram an sich und opferte seine eigene Seele ihren dunklen Flüstern. Er gab seinen Willen vollständig auf, um Ner'zhuls größter Todesritter und Champion zu werden, befehligte Armeen im Namen seines Meisters, bevor er zum Frostthron zurückkehrte, um direkt mit dem Lichkönig selbst zu verschmelzen.",al={"wem dient arthas","arthas anführer","wer kontrolliert arthas"}},["8c3ad81e"]={q="Mit wem ist Arthas Menethil verbündet?",a="Arthas befehligt die Geißel, eine monströse Legion aus gedankenlosen Untoten, Nekromanten und Schrecken, die durch die Seuche des Untodes erschaffen wurden. Zu seinen wichtigsten Leutnants gehört der wiederbelebte Erzlich Kel'Thuzad, den Arthas einst zu Lebzeiten erschlug, aber später wiederbelebte, um die Ruinen von Lordaeron zu überwachen. Arthas arbeitet ausschließlich im Auftrag der Geißel und des Lichkönigs und steht in bitterer Feindschaft zu allen lebenden sterblichen Nationen auf Azeroth.",al={"arthas verbündete","mit wem arbeitet arthas zusammen","arthas fraktion"}}}}
P.entries["topic:black-dragonflight"] = {n="Schwarzer Drachenschwarm",s="Einst die unerschütterlichen Erdwächter, von den Titanen damit beauftragt, Azeroths tiefe unterirdische Reiche zu beschützen, verfiel der Schwarze Drachenschwarm dem Wahnsinn und Verrat. Verderbt durch das heimtückische Flüstern der gefangenen Alten Götter, wurde ihr Anführer Neltharion zu Deathwing und machte seine Brut zu einer der zerstörerischsten und meistgehassten Mächte der Welt. Heute spinnen ihre überlebenden Nachkommen Intrigen aus den Schatten und führen verdeckte Kriege gegen die sterblichen Königreiche.",h="Einst die unerschütterlichen Erdwächter, von den Titanen damit beauftragt, Azeroths tiefe unterirdische...",kw={"schwarze drachenbrut","schwarze drachen","deathwing","drachenschwarm","erdwächter","khaz'goroth","nefarian","neltharion","onyxia"},ang={["class:Shaman"]="Schamanen blicken mit tiefer Trauer und Abscheu auf die schwarzen Drachen, wohl wissend, dass sie die heilige Elementarmacht der Erde nicht nutzen, um Harmonie zu wahren, sondern um Stein und Magma zu Instrumenten der Qual zu verzerren.",["faction:Alliance"]="Die Allianz muss stets wachsam gegen politische Subversion bleiben, da der Schwarze Drachenschwarm wiederholt versucht hat, den menschlichen Adel zu verderben und aristokratische Ambitionen an den Höfen der Menschen auszunutzen.",["faction:Horde"]="Die Horde hegt einen dauerhaften Groll gegen die Machenschaften des Schwarms, da sie während früherer Kriege unter deren manipulativen Einmischungen litt und sich in den Klüften von Kalimdor und den Östlichen Königreichen ihren unterirdischen Bruten gegenübersieht."},sec={{t="Die gefallenen Beschützer",b="Vor langer Zeit verlieh der Titan Khaz'goroth Neltharion seinen Segen und schuf den Schwarzen Drachenschwarm, um über die Erde zu wachen, Berge aufzutürmen und Azeroths tiefe Höhlen zu behüten. Äonenlang standen sie an der Seite der anderen Schwärme als geduldige, standhafte Wächter. Doch ihre innige Verbindung zu den unterirdischen Fundamenten der Welt besiegelte ihren Untergang. Indem sie in den tiefsten Höhlen hausten, lagen sie gefährlich nah an den versunkenen Gefängnissen der Alten Götter. Über Jahrhunderte hinweg zersetzte dunkles Flüstern den Verstand des edlen Erdwächters, trieb ihn in den Wahnsinn und machte seine gesamte Brut zu bösartigen Werkzeugen des Ruins."},{t="Verrat und Feuer",b="Während des uralten Krieges der Ahnen zerbrach Neltharion die Einheit der Drachen und wandte sich als Deathwing der Zerstörer gegen seine Artgenossen. Seither führt der schwarze Schwarm einen unerbittlichen, hasserfüllten Krieg gegen den roten, blauen, grünen und bronzenen Schwarm, die seine Grausamkeit als absolute Entweihung des Lebens betrachten. Statt den Boden zu pflegen, nutzen schwarze Drachen nun geschmolzenes Magma, schwarze Magie und sengenden Schwefel, um die Ländereien zu verbrennen, die sie einst nährten, und weiden sich daran, Zwietracht, Elend und endlose Konflikte über die Reiche der Sterblichen zu bringen."},{t="Menschliche Gestalten und sterbliche Intrigen",b="Anders als viele Bestien, die sich rein auf Klauen und Flammen verlassen, sind die schwarzen Drachen Meister der Manipulation. Oft nehmen sie humanoide Gestalten an – zumeist kultivierte, dunkelhaarige Menschen mit durchdringenden Augen –, um königliche Höfe und Ratskammern zu infiltrieren. Indem sie Herrscher in die Arroganz treiben, Zwietracht zwischen Adelshäusern säen und verletzlichen Ohren giftigen Rat einflüstern, orchestriert der Schwarm den Niedergang sterblicher Zivilisationen von innen heraus. Sie ziehen es vor, dass Königreiche sich selbst zerfleischen, ehe ihre Drakes eintreffen, um die Überreste niederzubrennen."}},faq={{q="Warum sind schwarze Drachen böse?",a="Ihre uralte Pflicht band sie eng an die unterirdischen Tiefen von Azeroth, genau dorthin, wo die Alten Götter eingekerkert lagen. Über Jahrtausende hinweg sickerte das wahnsinnig machende Flüstern dieser Wesenheiten in Neltharions Verstand und verwandelte seine schützenden Instinkte in Paranoia und Bosheit, bis ihm schließlich seine gesamte Brut in die Verderbnis folgte.",al={"warum schwarze drachen böse wurden","wer verdarb deathwing","wahnsinn des schwarzen drachenschwarms"}},{q="Welche Kräfte besitzen schwarze Drachen?",a="Vom Titanen Khaz'goroth mit der Vorherrschaft über die Erde betraut, befehligen sie Stein, Magma und tiefe unterirdische Mächte. In ihrem verderbten Zustand wirken sie unbeständige Erdelementargewalten, bekannt als schwarze Magie, speien sengendes Feuer sowie geschmolzenes Gestein, während ihre schweren Schuppen unaufhörlich intensive Hitze ausstrahlen.",al={"schwarze drachenmagie","fähigkeiten des schwarzen drachenschwarms","was können schwarze drachen"}},{q="Nutzen schwarze Drachen Tarnungen?",a="Ja. Schwarze Drachen sind herausragend in Infiltration und politischer Manipulation. Ihre bevorzugte humanoide Gestalt ist typischerweise ein attraktiver, adliger Mensch mit dunklem Haar und dunklen Augen, was es ihnen ermöglicht, sich frei an Höfen zu bewegen, Monarchen zu manipulieren und Bürgerkriege zu entfachen, ohne ihre wahre drakonische Natur zu offenbaren.",al={"nehmen drachen menschliche gestalt an","sterbliche gestalten schwarzer drachen","schwarze drachen als menschen getarnt"}},{q="Woran erkennt man den Namen eines schwarzen Drachen?",a="Mitglieder des schwarzen Schwarms folgen üblicherweise bestimmten Namenskonventionen: Männliche Namen enden häufig auf die Nachsilbe „-ion“ (wie etwa Neltharion), während weibliche Namen typischerweise auf „-ia“ enden (wie etwa Onyxia). Viele wählen zudem Namen, die Asche, Schatten, Stein oder Ruin heraufbeschwören.",al={"namensgebung schwarzer drachen","namen schwarzer drachen","wie schwarze drachen benannt werden"}},{q="Warum hassen die anderen Drachenschwärme sie?",a="Während des Krieges der Ahnen verriet der Erdwächter die anderen Schwärme und schlachtete Tausende seiner Brüder und Schwestern ab. Insbesondere der Rote Drachenschwarm verabscheut sie zutiefst und sieht in ihrer feurigen Bosheit und ihrem verderbenden Einfluss einen widernatürlichen Frevel gegen das Leben selbst.",al={"roter drachenschwarm gegen schwarzer drachenschwarm","warum drachen einander bekämpfen","bürgerkrieg der drachenschwärme"}},{q="Wer führt den Schwarzen Drachenschwarm heute an?",a="Ihr uralter Aspekt, Deathwing, ist nach vergangenen Niederlagen aus dem Blickfeld der Öffentlichkeit verschwunden und hat seine gefährliche Brut in zersplitterten Zirkeln zurückgelassen. Heute verfolgen prominente Nachkommen – wie Nefarian und Onyxia – ihre eigenen rücksichtslosen Bestrebungen, Rivalen zu versklaven, Königreiche zu unterwandern und finstere Schöpfungen heranzuzüchten.",al={"wer ist der anführer der schwarzen drachen","wo ist deathwing","wer beherrscht die schwarzen drachen"}}},fx={["0af770e1"]={q="Was ist der Schwarze Drachenschwarm?",a="Der Schwarze Drachenschwarm ist eine Brut von Drachen, Drakoniden und Drachkin, die ursprünglich vom Titanen Khaz'goroth gesegnet wurden, um als standhafte Wächter der Erde zu dienen. Einst als edle Verteidiger von Azeroths tiefsten Reichen, Bergen und unterirdischen Höhlen verehrt, verfiel der gesamte Drachenschwarm in den Wahnsinn, als ihr uralter Anführer den dunklen Flüstern der Alten Götter erlag.",al={"wer sind die schwarzen drachen","was sind schwarze drachen","was ist der schwarze drachenschwarm"}},["146344cc"]={q="Woher stammt der Schwarze Drachenschwarm?",a="Vor unzähligen Jahrtausenden verliehen die Titanen dem Großen Aspekt Neltharion dem Erdwächter und seiner schwarzen Brut die Herrschaft über Stein und Magma. Über Zeitalter hinweg formten sie Berge und Täler im Einklang mit den anderen Drachenschwärmen. Ihre enge Bindung zu den tiefen Orten der Erde machte sie jedoch anfällig für die Flüstern der gefangenen Alten Götter. Völlig dem Wahnsinn verfallen, verrieten Neltharion und seine Kinder ihre heilige Pflicht und wandten ihre elementare Macht Zerstörung und Schrecken zu.",al={"geschichte des schwarzen drachenschwarms","ursprung der schwarzen drachen","geschichte der schwarzen drachen"}}},fp="18,450,21.607.0,17.534.0,33.551.1,27.329.0,35.302.0,31.302.0,39.259.0,41.265.0,37.306.0"}
P.entries["topic:blackrock-clan"] = {fx={["2b76c337"]={q="Was ist der Schwarzfelsklan?",a="Der Schwarzfelsklan ist einer der berühmtesten und militärisch diszipliniertesten Orc-Clans aus Draenor. Bekannt für ihre meisterhafte Schmiedekunst und ihren eisernen Willen, bildeten sie das zentrale Rückgrat der Alten Horde während des Ersten und Zweiten Krieges unter den Kriegshäuptlingen Schwarzfaust und Orgrim Schicksalshammer. Während einige Mitglieder schließlich Thrall in seine neue Horde folgten, bleibt der Großteil abtrünnige Traditionalisten, die sich im Schwarzfels verschanzt haben.",al={"wer sind blackrock orcs","blackrock clan hintergrundgeschichte","was ist der blackrock clan"}},["77427c0a"]={q="Warum sind die Orcs des Schwarzfelsklans Reisenden gegenüber feindselig?",a="Die freien Orcs des Schwarzfelsklans halten noch immer an den blutigen Eroberungen der Alten Horde fest und lehnen Thralls friedliche Ideale ab. Angetrieben von kriegerischem Stolz und tiefem Hass sowohl auf die Allianz als auch auf Thralls Horde, behandeln sie jeden Eindringling in ihre Ländereien – insbesondere rund um Der Schwarzfels und Rotkammgebirge – als Invasoren, die abgeschlachtet oder versklavt werden müssen.",al={"warum greifen blackrock orcs an","blackrock clan feindselig","warum sind blackrocks böse"}},["2a83fd4b"]={q="Mit wem ist der Schwarzfelsklan verbündet?",a="Die Mitglieder des Schwarzfelsklans, die Rend Blackhand folgen, führen die Dunkle Horde von der Schwarzfelsspitze aus an. Um ihre Reihen gegen die Dunkeleisenzwerge und die Allianz zu stärken, haben sie sich mit Überresten des Dragonmaw clan, lokalen Waldtrollen, Ogern und dem Schwarzer Drachenschwarm verbündet.",al={"blackrock clan verbündete","mit wem arbeiten blackrock orcs zusammen","verbündete der dunklen horde"}}}}
P.entries["topic:bronzebeard-clan"] = {fx={["177e0e99"]={q="Wer sind die Verbündeten des Bronzebeard-Clans?",a="Die Bronzebeards sind treue, tragende Säulen der Großen Allianz. Ihre engste Bindung besteht zur Menschheit und reicht etwa achtzehn Jahrhunderte zurück, als menschliche Entdecker aus Arathor erstmals nach Süden in Khaz Modan reisten und Eisenschmiede entdeckten. Die beiden Völker schmiedeten eine dauerhafte Partnerschaft durch gemeinsame Schmiedekunst, Ingenieurwesen und Geschichtenerzählung. Sie pflegen auch enge Beziehungen zu den Gnomen aus dem nahegelegenen Gnomeregan und haben längst freundschaftliche Beziehungen zu ihren Wildhammer-Vettern im Nistgipfel wiederaufgenommen, ungeachtet vergangener Bürgerkriege.",al={"verbündete der bronzebeards","mit wem sind die bronzebeards verbündet","verbündete von eisenschmiede"}}}}
P.entries["topic:brotherhood-of-northshire"] = {n="Bruderschaft von Nordhain",s="Die Bruderschaft von Nordhain ist ein heiliger klerikaler Menschenorden, der der Kirche des Heiligen Lichts geweiht ist und seinen Sitz in der Abtei von Nordhain im Wald von Elwynn hat. Ursprünglich als die Kleriker von Nordhain bekannt, erlitt der Orden während des Ersten Krieges verheerende Verluste, bevor er unter Erzbischof Alonsus Faol reformiert wurde. Heute dient die Bruderschaft sowohl als spirituelle Zuflucht als auch als primäres Ausbildungsgelände für angehende Verteidiger der Allianz.",h="Die Bruderschaft von Nordhain ist ein heiliger klerikaler Menschenorden, der der Kirche des Heiligen Lichts...",kw={"alonsus faol","bruder paxton","bruderschaft von nordhain","kirche des heiligen lichts","kleriker von nordhain","wald von elwynn","abtei von nordhain","priesterin anetta"},ang={["class:Paladin"]="Das tragische Gemetzel an den ungerüsteten Klerikern von Nordhain während des Ersten Krieges war der direkte Anstoß für Erzbischof Faol, die Ritter der Silbernen Hand zu gründen.",["class:Priest"]="Die Abtei von Nordhain ist die Wiege der Klerikertradition von Sturmwind, wo uralte Disziplinen des Heilens, der Beichte und des Heiligen Lichts lange vor dem Ersten Krieg gepflegt wurden.",["race:Human"]="Für Generationen von Bürgern Sturmwinds hat die Bruderschaft in Notzeiten seelischen Trost gespendet, und ihre Abtei dient den größten Champions des Königreichs als bescheidener Anfang."},sec={{t="Die Kleriker des Ersten Krieges",b="Vor Jahrhunderten reisten fromme Missionare von Lordaeron nach Süden in das Königreich Sturmwind und errichteten die Abtei von Nordhain, um den Menschen beizustehen und das Reich durch das Heilige Licht zu stärken. Ursprünglich als der Heilige Orden der Kleriker von Nordhain bekannt, war ihr Mitgefühl legendär – sie versorgten während früherer Grenzkriege sogar verwundete Gnolle und Dschungeltrolle. Als die Orcische Horde durch das Dunkle Portal strömte, zogen die Kleriker mutig ohne Rüstung oder Waffen an die Frontlinien, um gefallene Soldaten zu heilen. Da ihre Heilung die Armee von Sturmwind aufrechterhielt, wurden sie von den Orcs gnadenlos ins Visier genommen. Der Orden wurde dezimiert, die Abtei geplündert und niedergebrannt, und die überlebenden Kleriker waren gezwungen, gemeinsam mit Sir Anduin Lothar über das Meer nach Norden nach Süderstade zu fliehen."},{t="Der Funke der Paladine",b="Das Massaker an den Klerikern von Nordhain löste Schockwellen in den Reichen der Menschen aus. In dem Wissen, dass der Glaube allein ohne Rüstung und kriegerische Disziplin keiner Axt standhalten konnte, beschloss Erzbischof Alonsus Faol, Krieger zu erschaffen, die sowohl über die heiligen Mächte des Lichts als auch über das kriegerische Können eines Ritters verfügten. Faol griff auf die überlebenden Kleriker sowie auf fromme Ritter zurück und gründete die Ritter der Silbernen Hand, womit er die ersten Paladine der Menschheit ins Leben rief. Auf diese Weise wurde das Opfer der gefallenen Heiler von Nordhain zum eigentlichen Fundament für jene heiligen Krieger, die die Horde im Zweiten Krieg bezwangen."},{t="Wiederaufbau und gegenwärtige Pflicht",b="Nach der Rückeroberung von Sturmwind und der Zerstörung des Dunklen Portals leitete Erzbischof Faol den Wiederaufbau der Abtei von Nordhain und reorganisierte den Orden als die Bruderschaft von Nordhain. Heute, im Jahr 25 n. d. P., steht die Abtei von Nordhain als ruhiger, aber lebenswichtiger Mittelpunkt, an dem sich neue Rekruten versammeln, um ihren Dienst für das Reich zu beginnen. Unter Persönlichkeiten wie Priesterin Anetta, Bruder Sammuel und Bruder Paxton kümmert sich die Bruderschaft um das seelische Wohl des Tals, bewahrt alte Texte in ihrer Bibliothek auf und bildet die nächste Generation von Verteidigern aus, um sich Briganten, Wölfen und den sich zusammenziehenden Schatten im gesamten Wald von Elwynn zu stellen."}},faq={{q="Was ist die Bruderschaft von Nordhain?",a="Sie sind ein monastischer Orden innerhalb der Kirche des Heiligen Lichts mit Sitz in der Abtei von Nordhain im Wald von Elwynn. Früher als die Kleriker von Nordhain bekannt, spenden sie spirituellen Beistand, heilen die Verwundeten und bilden neue Abenteurer der Allianz aus, die ihre Reise beginnen.",al={"wer ist die bruderschaft von nordhain","geschichte der bruderschaft von nordhain","kleriker von nordhain"}},{q="Was geschah mit den ursprünglichen Klerikern während des Ersten Krieges?",a="Die Kleriker zogen als ungerüstete Heiler auf dem Schlachtfeld in den Ersten Krieg. Da die Orcs erkannten, dass menschliche Soldaten kaum zu besiegen waren, solange sie durch heilige Magie gestärkt wurden, machten sie die Niedermetzelung der Kleriker zur Priorität. Die Abtei wurde überrannt und zerstört, und nur ein Rest entkam über das große Meer nach Lordaeron.",al={"kleriker von nordhain erster krieg","was geschah mit der abtei","zerstörung der abtei von nordhain"}},{q="Wie inspirierten die Kleriker von Nordhain die Paladine?",a="Als Erzbischof Alonsus Faol miterlebte, wie leicht die ungerüsteten Kleriker von der Horde getötet wurden, erkannte er, dass die Allianz heilige Krieger benötigte, die brutalen Kämpfen trotzen konnten. Er vereinte die spirituelle Hingabe der Kleriker mit der kriegerischen Macht der Ritter und formte so die Ritter der Silbernen Hand.",al={"erschaffung der paladine","ursprung der silbernen hand","alonsus faol paladine"}},{q="Wer führt oder bildet heute Leute in der Abtei von Nordhain aus?",a="Die Abtei beherbergt mehrere bemerkenswerte Gestalten der Bruderschaft, darunter Bruder Paxton, der Vorräte verwaltet und Texte für die Bibliothek kopiert, Priesterin Anetta, die angehende Priester unterweist, und Bruder Sammuel, der Novizen der Paladine anleitet.",al={"wer ist in der abtei von nordhain","abtei von nordhain lehrer","bruder paxton"}},{q="Was war die Expedition in die Todesminen während des Ersten Krieges?",a="Ein Ogerhäuptling namens Turok stahl den heiligen Folianten der Offenbarung aus Nordhain. Sir Anduin Lothar führte eine Expedition in die Todesminen von Westfall an, um ihn zurückzuholen, saß jedoch in der Falle, bis Truppen aus Sturmwind ihn retteten und das Buch zurück in die Abtei brachten.",al={"foliant der offenbarung todesminen","anduin lothar todesminen","turok todesminen"}},{q="Besteht eine Verbindung zur Bruderschaft der Defias?",a="Nein, sie stehen in völligem Gegensatz zueinander. Obwohl beide das Wort 'Bruderschaft' teilen, ist die Bruderschaft von Nordhain ein heiliger religiöser Orden, der Sturmwind treu ergeben ist, während die Bruderschaft der Defias ein kriminelles Syndikat aus Geächteten und Banditen ist, das das Umland heimsucht.",al={"bruderschaft von nordhain defias","sind sie defias","nordhain defias"}}},fx={["5eaf3832"]={q="Warum hat die Bruderschaft ihren Sitz im Nordhaintal?",a="Vor Jahrhunderten reisten Kleriker der Kirche des Heiligen Lichts aus Lordaeron nach Süden und errichteten die Abtei von Nordhain als ihr spirituelles Zuhause in Sturmwind. Obwohl die ursprüngliche Abtei während des Ersten Krieges von der Orcischen Horde niedergebrannt wurde, beaufsichtigte Erzbischof Alonsus Faol ihren Wiederaufbau nach Kriegsende. Das Tal bleibt ihr angestammtes Heiligtum und dient nun als Ausbildungs- und Rekrutierungsgelände, um neue Verteidiger für das Königreich vorzubereiten.",al={"warum sind sie im nordhain","warum im nordhaintal","standort der bruderschaft von nordhain"}},["24abd8af"]={q="Mit wem ist die Bruderschaft von Nordhain verbündet?",a="Die Bruderschaft von Nordhain ist ein Orden innerhalb der Kirche des Heiligen Lichts und operiert direkt im Dienst des Königreichs Sturmwind und der Großen Allianz. Historisch gesehen kümmerten sich ihre Kleriker während großer Konflikte wie dem Gnollkrieg und dem Gurubashikrieg um Sturmwinds Armeen, und ihr wiederhergestellter Orden rekrutiert und trainiert nun direkt junge Champions, um das Reich zu schützen.",al={"verbündete der bruderschaft von nordhain","für wen arbeitet die bruderschaft","loyalität der bruderschaft"}}},fp="25,437,28.769.0,25.601.0,27.628.0,38.260.0,59.298.0,52.294.0,53.246.0,62.254.0,45.251.0"}
P.entries["topic:burning-blade-clan"] = {fx={["59650569"]={q="Warum sind die Burning Blade gegenüber Reisenden feindselig?",a="Die Burning Blade dienen dem dämonischen Willen der Brennenden Legion und des Schattenrats. Seit ihr Clan während der frühen Kriege von dämonischem Blutdurst verzehrt wurde, haben sie jede wahre Loyalität oder Ehre aufgegeben. Heute als geheimer apokalyptischer Kult neu organisiert, betrachten sie Außenstehende, loyale Untertanen der Horde und neugierige Reisende als direkte Bedrohungen für ihre Zirkel oder als Brennstoff für dämonische Blutopfer.",al={"warum greifen die burning blade an","feindseligkeit der burning blade","warum kämpfen die burning blade"}},d02d80de={q="Mit wem sind die Burning Blade verbündet?",a="Der Kult agiert als direkter Arm des finsteren Schattenrats und führt dessen dunkle Pläne in ganz Kalimdor aus. Sie kooperieren häufig mit verbündeten dämonenanbetenden Splitterfraktionen wie die Searing Blade, die sich unter Orgrimmar verstecken, und die Argus Wake in den Östlichen Königreichen. Vor allem aber sind sie der Brennenden Legion in Dienstbarkeit geschworen; sie beschwören Dämonen und sammeln korrupte Artefakte, um die Pläne ihrer Meister zu beschleunigen.",al={"verbündete der burning blade","für wen arbeiten die burning blade","burning blade und schattenrat"}},["7b15f473"]={q="Woher stammen die Burning Blade?",a="Ursprünglich ein uralter orkischer Clan aus Draenor, bekannt für seine furchterregenden Klingenmeister, schlossen sich die Burning Blade der Alten Horde an und überquerten während des Ersten Krieges die Schwelle nach Azeroth. Dämonische Verderbnis zersetzte ihren Verstand, bis sie während des Zweiten Krieges zu einer rücksichtslosen, wahnsinnigen Raserei wurden und schließlich völlig zerfielen. Während ehrenhafte Klingenmeister später Thralls Neuer Horde die Treue schworen, verwandelten sich die verbliebenen Reste in den schattenhaften dämonischen Kult, der heute Kalimdor bedroht.",al={"ursprung der burning blade","burning blade hintergrund","geschichte des burning blade clans"}}}}
P.entries["topic:burning-legion"] = {n="Brennende Legion",s="Die Brennende Legion ist eine unendliche, apokalyptische Armee aus Dämonen, angeführt vom gefallenen Titanen Sargeras, deren Ziel es ist, alles Leben aus der Schöpfung zu tilgen. Nachdem sie bereits vor zehntausend Jahren das alte Kalimdor in Trümmer legten, bleiben die Dämonen Azeroths unerbittlichster Erzfeind, die für die Verderbnis der Orcs und die Schrecken des Dritter Krieg verantwortlich sind.",h="Die Brennende Legion ist eine unendliche, apokalyptische Armee aus Dämonen, angeführt vom gefallenen Titanen...",kw={"archimonde","brennende legion","dämonen","eredar","teufelsenergie","hyjal","kil'jaeden","mannoroth","sargeras","auseinanderbrechen","wirbelnder nether","brunnen der ewigkeit"},ang={["class:Paladin"]="Paladine betrachten die Brennende Legion als den Antagonisten von das Heilige Licht und widmen ihre kriegerischen Gelübde und ihre rechtschaffene Macht der Säuberung dämonischen Abschaums, wo immer er auch schwärt.",["class:Warlock"]="Hexenmeister wandeln auf Messers Schneide, indem sie die rohe Teufelsmagie und die unterwürfigen Dämonen der Legion ihrem eigenen sterblichen Willen unterwerfen, ungeachtet ständigen Misstrauens und der allgegenwärtigen Gefahr der Verderbnis.",["race:NightElf"]="Die Nachtelfen tragen die tiefsten Narben der Invasionen der Legion; ihr altes Imperium wurde beim Auseinanderbrechen zerschmettert und das jüngste Opfer ihres Weltenbaums am Hyjal kostete sie ihre Unsterblichkeit.",["race:Orc"]="Orcs tragen ein bitteres Vermächtnis mit der Legion, da sie durch den dämonischen Blutpakt von Mannoroth versklavt wurden, bevor Grom Hellscream sich selbst opferte, um den Fluch ein für alle Mal zu brechen."},sec={{t="Genesis der Armee",b="Vor langer Zeit war Sargeras der Streiter der Titanen, beauftragt damit, die Dämonen aufzuspüren und einzukerkern, die den Kosmos plagten. Über unzählige Zeitalter des Kampfes gegen ihr Böses hinweg wurde er desillusioniert und kam zu dem Schluss, dass die Schöpfung selbst grundlegend fehlerhaft sei und in Flammen aufgelöst werden müsse. Um seinen Kreuzzug zu verwirklichen, befreite er die Dämonen, die er einst eingekerkert hatte, und zwang sie durch Teufelsmagie unter seinen Willen. Er verstärkte ihr Chaos mit dem Intellekt der korrumpierten Eredar – wobei er Archimonde und Kil'jaeden zu seinen Hauptleutnanten erhob – und schmiedete eine unaufhaltsame Maschinerie der kosmischen Vernichtung."},{t="Der Krieg der Ahnen",b="Vor zehntausend Jahren zogen die rücksichtslosen Zaubereien der Hochgeborenen den Blick der Legion auf Azeroth. Durch das Flüstern aus dem Brunnen der Ewigkeit verführte Sargeras Königin Azshara und ihren Berater Xavius mit dem Versprechen, die Welt in ein Paradies zu verwandeln. Stattdessen entfesselte das Portal Befehlshaber wie Mannoroth und Archimonde sowie Schwärme von Doomguards, Teufelshunden und flammenden Infernals. Der darauf folgende Krieg stürzte die Zivilisation von Kalimdor ins Verderben, bevor ein Bündnis aus Nachtelfen, Drachenschwärmen und Halbgöttern den Durchgang kollabieren ließ. Die katastrophale Implosion zerriss den Superkontinent im Großen Auseinanderbrechen und schleuderte die verwüsteten Lande über riesige neue Meere."},{t="Schatten über Azeroth",b="Obwohl sie zurück in den Wirbelnden Nether verbannt wurde, gab die Legion Azeroth nie auf. Da Kil'jaeden entschied, dass eine direkte Invasion nur zum Scheitern verurteilt war, inszenierte er aus der Ferne stellvertretende Kataklysmen. Der Betrüger band die Orcs von Draenor durch dämonische Blutpakte und ließ die Horde durch Das Dunkle Portal stürmen, um die Verteidigung der Sterblichen zu schwächen. Als das fehlschlug, schmiedete die Legion den Lichkönig und entfesselte die untote Geißel über Lordaeron, was den Weg für Archimondes Rückkehr im Dritter Krieg ebnete. Selbst nachdem Archimonde am Hyjal fiel, verweilen Überreste der Legion im Teufelswald, den Verwüstete Lande und in versteckten Kulten auf der ganzen Welt."}},faq={{q="Was ist die Brennende Legion?",a="Die Brennende Legion ist eine unendliche Armee aus Dämonen, korrumpierten Völkern und zerstörerischen Schrecken, geschmiedet vom gefallenen Titanen Sargeras. Ihr einziges Ziel ist der Brennende Kreuzzug: alles Leben und jegliche geordnete Existenz aus dem Kosmos zu tilgen.",al={"wer ist die legion","was ist die brennende legion","dämonen der legion","was sind dämonen"}},{q="Wer führt die Brennende Legion an?",a="Der oberste Meister der Legion ist der gefallene Titan Sargeras. Unter ihm dienen die Dämonenfürsten der Eredar, allen voran Archimonde der Entweiher, der bis zu seinem Untergang am Hyjal militärische Angriffe anführte, und Kil'jaeden der Betrüger, der in allen Welten heimtückische Pläne schmiedet.",al={"wer regiert die legion","anführer der legion","wer ist der dämonenkönig","boss archimonde"}},{q="Warum will die Legion Azeroth zerstören?",a="Azeroth hat der Legion wiederholt getrotzt und gilt als die einzige bekannte Welt, die ihre Angriffe zurückgeschlagen hat.",al={"warum greifen dämonen an","ziel der legion","warum azeroth invadieren","ziel von sargeras"}},{q="Wie kamen die Dämonen zum ersten Mal nach Azeroth?",a="Vor zehntausend Jahren kanalisierten Königin Azshara und ihre Hochgeborenen die gewaltigen Energien des Brunnens der Ewigkeit und zogen dabei versehentlich Sargeras an. Getäuscht durch Versprechen von grenzenloser Macht öffneten die Hochgeborenen ein gewaltiges Portal unter dem Palast, das es der Legion ermöglichte, in Kalimdor einzufallen.",al={"erste dämoneninvasion","wie kam die legion hierher","portal brunnen der ewigkeit","dämonen von königin azshara"}},{q="Was geschah mit der Legion während des Dritter Krieg?",a="Nachdem er mithilfe des Buchs von Medivh zurück nach Azeroth beschworen wurde, marschierte Archimonde durch Lordaeron und segelte gen Westen, um den Weltenbaum Nordrassil zu verschlingen. Am Hyjal erkauften sich die sterblichen Völker Zeit für Malfurion Sturmgrimm, um die Geister der Ahnen zu rufen, was die Macht des Baumes zur Explosion brachte und Archimonde vernichtete.",al={"dämonen im dritten krieg","invasion am hyjal","hat die legion den dritten krieg verloren","was geschah mit archimonde"}},{q="Sind Dämonen derzeit immer noch eine Bedrohung?",a="Ja. Obwohl ihr Hauptheer nach Archimondes Fall zersplitterte, bleiben gefährliche Überreste in ganz Azeroth verschanzt. Schreckenslords, Infernals und verbliebene Unholde besetzen korrumpierte Gebiete wie den Teufelswald und die Verwüstete Lande, während sterbliche Kultisten wie der Schattenrat im Geheimen agieren.",al={"gibt es noch dämonen","überreste der legion","dämonen in classic","wo sind die dämonen jetzt"}}},fx={["5561206b"]={q="Warum ist die Brennende Legion gegenüber jedem feindselig?",a="Der ultimative Zweck der Brennenden Legion ist nichts Geringeres als die absolute Vernichtung allen sterblichen Lebens und aller Schöpfung im Kosmos. Unter dem Kommando des gefallenen Titanen Sargeras suchen Dämonen nicht nach Eroberung, Koexistenz oder Kapitulation; sie betrachten sterbliche Welten als fehlerhafte Überreste, die im Teufelsfeuer ausgelöscht werden müssen. Jeder Reisende oder jede Seele, der/die ihnen auf Azeroth begegnet, ist lediglich Brennstoff für ihre Magie oder Beute, die ausgelöscht werden muss.",al={"warum ist die legion feindselig","warum greift die brennende legion an","gründe für die feindseligkeit der brennenden legion"}},c3b2191d={q="Wer dient an der Seite der Brennenden Legion oder arbeitet für sie?",a="Die Legion verlässt sich auf eine endlose Flut dämonischer Rassen, darunter monströse Grubenlords, gerissene Schreckenslords, gefräßige Teufelshunde und turmhohe Infernals. Über reine Dämonen hinaus korrumpieren sie sterbliche Rassen, damit diese als Bauernopfer und Vorhut agieren. In der Vergangenheit beeinflussten sie die Hochgeborenen-Zauberer von Königin Azshara, korrumpierten die Orcs von Draenor durch dämonisches Blut und schmiedeten die Geißel, um den sterblichen Widerstand vor Invasionen aufzuweichen.",al={"verbündete der brennenden legion","wer arbeitet für die legion","wer dient der brennenden legion"}},["9252264e"]={q="Warum findet man immer noch dämonische Überreste auf ganz Azeroth?",a="Nach Archimondes Niederlage in der Schlacht am Hyjal zersplitterte der zentralisierte dämonische Angriff, was die überlebenden Unholde in den Untergrund trieb. Heute lauern verbliebene Dämonen und abtrünnige Schreckenslords in öden Gegenden wie Desolace, Teufelswald und den Verwüsteten Landen. Zusätzlich beschwören korrupte sterbliche Kabalen, wie die Hexenmeister des Schattenrats, heimlich frische Verstärkungen durch versteckte dunkle Portale, um die Arbeit der Legion fortzusetzen.",al={"warum sind noch dämonen auf azeroth","warum sind legion-dämonen hier","orte der brennenden legion auf azeroth"}}},fp="14,335,19.576.0,23.648.0,20.628.0,27.231.0,29.286.0,44.107.0,43.282.0,49.298.0,36.283.0"}
P.entries["topic:cenarion-circle"] = {fx={["93dd49b8"]={q="Warum wird er Zirkel des Cenarius genannt?",a="Der Orden wurde nach Cenarius benannt, dem Halbgott und Herrn des Waldes, und von ihm gesegnet. Cenarius war der Schutzpatron der Wildnis, der ursprünglich Malfurion Sturmgrimm, den ersten sterblichen Druiden Azeroths, unterrichtete. Als Malfurion und seine Mitpraktizierenden zusammenkamen, um ihre Traditionen zu organisieren und das Gleichgewicht der Natur zu wahren, nahmen sie den Namen des Halbgottes an, um ihren göttlichen Lehrer zu ehren.",al={"namensursprung des zirkels des cenarius","warum cenarius","nach wem ist der zirkel des cenarius benannt"}},["975f0135"]={q="Woher stammt der Zirkel des Cenarius?",a="Der Zirkel wurde in der Mondlichtung von Malfurion Sturmgrimm nach dem Großen Auseinanderbrechen gegründet, als er die frühen Nachtelfendruiden zusammenbrachte, um ihre Richtlinien und Traditionen zu etablieren. Während der Jahrtausende der langen Wache bewahrte der Zirkel das Gleichgewicht und heilte dämonische Narben auf ganz Azeroth, während er an der Seite des grünen Drachenschwarms durch den Smaragdgrünen Traum wandelte.",al={"geschichte des zirkels des cenarius","ursprung des zirkels des cenarius","wie wurde der zirkel des cenarius gegründet"}}}}
P.entries["topic:cenarius"] = {fx={["19f1e731"]={q="Woher stammt Cenarius?",a="Cenarius wurde aus der Verbindung von Elune, der Mondgöttin, und dem weißen Hirsch-Halbgott Malorne geboren. Da er mehr dem sterblichen Bereich als dem Himmel angehörte, überließ Elune seine Erziehung Malorne und Ysera der Träumerin. Ysera zog Cenarius im Smaragdgrünen Traum auf und unterrichtete ihn in dessen tiefen Mysterien. Über Jahrtausende hinweg wanderte der Herr des Waldes durch die Wildnis Azeroths, lehrte uralte Völker die natürlichen Wege und stand sterblichen Verteidigern durch katastrophale Konflikte wie den Krieg der Ahnen zur Seite.",al={"ursprung von cenarius","geschichte von cenarius","geburt von cenarius"}}}}
P.entries["topic:centaur"] = {fx={["9cda8173"]={q="Wer führt die Zentauren an?",a="Die Zentauren haben keinen einzelnen Herrscher. Stattdessen sind sie in unabhängige, sich bekriegende Clans unterteilt – wie etwa die Kolkar, Gelkis, Magram, Maraudine und Galak –, von denen jeder von seinem eigenen Khan regiert wird. Diese Khane herrschen durch rücksichtslose körperliche Dominanz und Gerissenheit, und die Clans investieren fast genauso viel Mühe in blutige Gebietskriege gegeneinander wie in Überfälle auf ausländische Feinde.",al={"zentaurenanführer","wer regiert die zentauren","zentaurenkhan"}},f5a4aa83={q="Was sind Zentauren?",a="Zentauren sind ein kriegerisches, primitives Volk, das den Oberkörper und die Arme eines Menschen besitzt, die mit dem Unterkörper und den vier Beinen eines Pferdes verbunden sind. Von Natur aus wild und nomadisch, durchstreifen sie die trockenen Ebenen und Täler im zentralen Kalimdor. Sie sind in erbittert territorialen Clans organisiert, die rohe Gewalt schätzen, benachbarte Siedlungen überfallen und alle Außenstehenden vertreiben, die sich ihren Jagdgründen und Wasserlöchern nähern.",al={"was sind zentauren","wer sind die zentauren","zentaurenvolk"}},["5b0a3e11"]={q="Warum sind Zentauren so feindselig gegenüber Reisenden?",a="Feindseligkeit ist tief in der Natur der Zentauren verwoben. Verflucht geboren und erfüllt von Selbsthass und Wut, ermordeten sie kurz nach ihrer Erschaffung ihren eigenen Vater. Seitdem betrachten sie die Welt durch Gewalt und Eroberung. Sie sehen das zentrale Kalimdor als ihr rechtmäßiges Territorium an und behandeln jede vorbeiziehende Karawane, jeden Reisenden oder jede Siedlung als Eindringlinge, die geschlachtet, versklavt oder vertrieben werden müssen.",al={"warum greifen zentauren an","warum sind zentauren aggressiv","zentauren feindseligkeit"}}}}
P.entries["topic:church-of-the-holy-light"] = {n="Kirche des Heiligen Lichts",s="Die Kirche des Heiligen Lichts ist die dominierende religiöse Institution der Menschheit, die sterbliche Seelen durch die Tugenden von Mitgefühl, Gerechtigkeit und Hingabe leitet. Ursprünglich im verlorenen nördlichen Königreich Lordaeron beheimatet, residiert ihre Führung nach der Verwüstung durch die Geißel nun in der prachtvollen Kathedrale des Lichts in Sturmwind.",h="Die Kirche des Heiligen Lichts ist die dominierende religiöse Institution der Menschheit, die sterbliche...",kw={"alonsus faol","benedictus","kathedrale des lichts","kirche","heiliges licht","lordaeron","nordhain","paladin","priester","silberne hand","sturmwind"},ang={["class:Paladin"]="Eure heiligen Gelübde stammen aus dem Bund von Erzbischof Faol während des Zweiten Krieges, der ritterliche Tugendhaftigkeit mit der wiederherstellenden und vergeltenen Gnade des Lichts vereinte.",["class:Priest"]="Ob Ihr nun den Verwundeten Trost spendet oder das schwierige Gleichgewicht zwischen Lumineszenz und Schatten studiert, Eure Berufung gehört zu einem Vermächtnis, das Jahrtausende menschlicher Hingabe umspannt.",["faction:Alliance"]="Die Kirche des Heiligen Lichts bietet der Allianz moralische Einheit und Hospizpflege auf dem Schlachtfeld und steht als dauerhaftes Symbol der Hoffnung gegen die Dunkelheit.",["race:Dwarf"]="Lange mit den Menschenreichen verbündet, finden viele Zwerge aus Eisenschmiede Gemeinsamkeiten und geteilte Tugend in den Predigten und geheiligten Hallen des Heiligen Lichts.",["race:Human"]="Seit Generationen segnet die Kirche die Menschenkönigreiche durch Krisen und Seuchen hindurch, und ihre Präsenz in Sturmwind bleibt das spirituelle Rückgrat Eurer Zivilisation."},sec={{t="Ursprünge und das Glaubensbekenntnis des Lichts",b="Die Ursprünge der Kirche reichen über ein Jahrtausend zurück zum Glauben an das Heilige Licht, der unter den Menschen von Arathor Wurzeln schlug und sie lehrte, heilige Macht zu kanalisieren, um Verletzungen zu heilen und Leiden zu tilgen. Angetrieben von den Grundsätzen der Nächstenliebe, Rechtschaffenheit und dem grundlegenden Glauben, dass das Licht in allen denkenden Wesen wohnt, verschmolzen diese Lehren schließlich zu einem organisierten Glauben. Das Königreich Lordaeron wurde zum religiösen Kernland dieser Doktrin und errichtete verehrte Heiligtümer im ganzen Norden, darunter Stratholme, Andorhal, Tyrs Hand und die Kapelle des Hoffnungsvollen Lichts."},{t="Ein Schild in den Großen Kriegen",b="Im Ersten Krieg folgte die Bruderschaft von Nordhain dem Ruf zu den Waffen, um gefallene Verteidiger gegen die einfallende orcische Horde zu heilen. Da ihnen Waffen oder schwere Rüstungen fehlten, erlitten diese Kleriker an der Front entsetzliche Verluste durch die Orcs. Da Erzbischof Alonsus Faol die Notwendigkeit für heilige Krieger erkannte, die sowohl heiligen Zorn kanalisieren als auch physischen Kampf überleben konnten, berief er während des Zweiten Krieges eine Versammlung mit Oberkommandant Anduin Lothar ein, um die Ritter der Silbernen Hand zu gründen. Paladine und Priester gleichermaßen wurden zum moralischen und militärischen Bollwerk der Allianz von Lordaeron und bewahrten die Menschheit vor der totalen Vernichtung."},{t="Der Fall des Nordens und der südliche Zufluchtsort",b="Der Dritte Krieg brachte großes Leid über die Gläubigen. Als die Seuche des Untodes über Lordaeron hinwegzog, arbeitete die Kirche unermüdlich daran, die Kranken zu lindern und die Kontamination einzudämmen, nur um überwältigt zu werden, als das Königreich von innen heraus zusammenbrach. Da sich Lordaeron in eine von der Geißel heimgesuchte Wildnis verwandelt hatte, wurde der Sitz der Kirche nach Süden verlegt. Unter der Obhut von Erzbischof Benedictus baute der Klerus seine Hierarchie innerhalb der neu errichteten Kathedrale des Lichts in Sturmwind wieder auf und bot den geschlagenen Überlebenden der Allianz Trost, spirituelle Führung und militärischen Zweck."}},faq={{q="Was ist die Kernphilosophie der Kirche des Heiligen Lichts?",a="Die Kirche lehrt, dass eine vereinende heilige Energie alle lebenden Dinge verbindet. Praktizierende kultivieren persönliche Rechtschaffenheit, Altruismus und Mitgefühl und streben danach, sowohl sich selbst als auch die Welt um sie herum zu verbessern. Anhänger glauben, dass das Handeln mit Tugend, Gerechtigkeit und Selbstaufopferung es einem erlaubt, die reinste Essenz des Lichts widerzuspiegeln.",al={"glauben des heiligen lichts","was glaubt die kirche","grundsätze des lichts","philosophie der kirche"}},{q="Wer führt die Kirche heute an?",a="Erzbischof Benedictus dient als geistiges Oberhaupt der Kirche des Heiligen Lichts. Nach dem Ableben von Erzbischof Alonsus Faol und dem Fall des nördlichen Königreichs Lordaeron organisierte Benedictus das Priestertum von der prachtvollen Kathedrale des Lichts aus, die sich im Herzen von Sturmwind befindet.",al={"kirchenoberhaupt","wer ist der erzbischof","oberhaupt der kirche"}},{q="Wie wurde der Orden der Paladine gegründet?",a="Während des Ersten Krieges wurden ungepanzerte Kleriker aus Nordhain gezielt von der Horde ins Visier genommen und massakriert. Um sicherzustellen, dass heilige Zauberwirker den Krieg an der Front überleben konnten, gründete Erzbischof Alonsus Faol vor dem Zweiten Krieg die Ritter der Silbernen Hand und verlieh ritterlichen Kampfstreitern göttliche Zauberfähigkeiten.",al={"ursprung der paladine","wie wurden paladine erschaffen","alonsus faol paladine","gründung der silbernen hand"}},{q="Wo befinden sich die heiligsten Orte der Kirche?",a="Historisch gesehen lagen die ältesten heiligen Stätten der Kirche im Ostweald von Lordaeron, darunter Andorhal, Stratholme, Tyrs Hand und die Kapelle des Hoffnungsvollen Lichts. Nach der Zerstörung des Nordens durch die Geißel wurde Sturmwinds Kathedrale des Lichts zum bedeutendsten Heiligtum und Machtzentrum des Glaubens.",al={"heilige stätten","heilige orte","wichtige schreine"}},{q="Welche Rolle spielte die Kirche gegen die Seuche des Untodes?",a="Während des Dritten Krieges stürzten sich Priester und Kleriker in Feldlazarette in ganz Lordaeron, in dem Versuch, die Befallenen zu reinigen und die Ausbreitung der Seuche zu stoppen. Tragischerweise erwies sich heilige Magie als unfähig, die übernatürliche Verderbnis vollständig umzukehren, und viele Geistliche fielen, als ihre Patienten erlagen und als Monstrositäten der Geißel auferstanden.",al={"rolle der kirche bei der seuche","heiliges licht seuchenheilung","geißel und kirche"}},{q="Folgen auch andere Völker als Menschen der Kirche?",a="Ja. Zwerge aus Eisenschmiede haben sich die Lehren der Kirche vor Jahrhunderten zu eigen gemacht und ihre eigenen frommen Orden von Priestern und Paladinen gegründet. Die Hochelfen von Quel'Thalas haben die Philosophie ebenfalls übernommen und restaurative Heilmagie gemeistert, die sie später mit menschlichen Klerikern teilten.",al={"nichtmenschliche anhänger des lichts","folgen zwerge dem licht","hochelfenpriester"}}},fx={["1109d54d"]={q="Was ist die Kirche des Heiligen Lichts?",a="Die Kirche des Heiligen Lichts ist die zentrale religiöse Institution der Menschheit. Ihre Geistlichkeit predigt, dass ein wohlwollendes Heiliges Licht in allen Lebewesen wohnt, und drängt die Anhänger dazu, Mitgefühl, Ehre und Gerechtigkeit zu praktizieren, um das Beste in sich selbst und der Welt hervorzubringen. Durch ihre Hingabe heilen ihre Priester die Kranken und Verwundeten, während die Paladine der Silbernen Hand als militärischer Arm der Kirche dienen, um die Schwachen zu beschützen und das Böse zu vernichten.",al={"was ist die kirche des lichts","wer ist die kirche des heiligen lichts","kirche des heiligen lichts"}},e7672a04={q="Woher stammt die Kirche des Heiligen Lichts?",a="Die Kirche hat ihre Wurzeln im Glauben an das Heilige Licht, der sich unter den Menschen von Arathor verbreitete. Jahrhunderte später gründeten Migranten das Königreich Lordaeron, das zum Kernland für heilige Asketen und Pilger wurde. Die Anführer von Lordaeron organisierten diese Überzeugungen schließlich in einer einheitlichen kirchlichen Hierarchie und errichteten Schreine, Klöster und Kapellen in den Menschenkönigreichen.",al={"ursprünge der kirche des lichts","geschichte der kirche des heiligen lichts","wie wurde die kirche gegründet"}},["12379874"]={q="Mit wem ist die Kirche des Heiligen Lichts verbündet?",a="Die Kirche ist tief mit der Großen Allianz verwoben. Während des Zweiten Krieges sicherte Erzbischof Alonsus Faol der Kirche die spirituelle und militärische Unterstützung zu, um die Horde zurückzuschlagen, und gründete die Ritter der Silbernen Hand, um an der Front zu kämpfen. Nach dem Fall von Lordaeron baute die Kirche ihren Sitz in der Kathedrale des Lichts von Sturmwind wieder auf und arbeitet direkt mit dem Königreich Sturmwind und seinen Verbündeten zusammen.",al={"fraktion kirche des lichts","wen unterstützt die kirche des lichts","kirche des lichts allianz"}}},fp="24,352,29.583.0,26.638.0,40.606.0,60.331.0,27.296.0,37.332.0,42.295.0,60.336.0,45.274.0"}
P.entries["topic:cult-of-the-damned"] = {n="Kult der Verdammten",s="Der Kult der Verdammten ist eine geheimnisvolle Verschwörung sterblicher Fanatiker, Nekromanten und Aristokraten, die sich dem Lichkönig verschrieben haben. Seine Mitglieder, die sich vor dem Dritten Krieg im nördlichen Lordaeron formierten, vergifteten die Getreidevorräte, die die Geißel hervorbrachten, und leiteten den Untergang des größten Königreichs der Menschheit in die Wege. Heute verwalten die überlebenden Kultisten die Seuchenkessel und nekromantischen Akademien in den Pestländern, während sie zugleich aktiv die Städte der Lebenden infiltrieren.",h="Der Kult der Verdammten ist eine geheimnisvolle Verschwörung sterblicher Fanatiker, Nekromanten und...",kw={"andorhal","darrowehr","kesselmeister","kult der verdammten","kel'thuzad","lichkönig","seuche des untodes","pestländer","scholomance","geißel"},ang={["class:Mage"]="Der Kult ist ein schmerzhafter Fleck auf der Ehre der Kirin Tor, da er von einem von Dalarans eigenen geschätzten Erzmagiern, Kel'Thuzad, gegründet wurde.",["class:Paladin"]="Der Kult der Verdammten stellt den ultimativen Frevel gegen das Heilige Licht dar, indem er finstere Nekromantie einsetzt, um die Lebenden zu verderben und die ewige Ruhe der Toten zu stören.",["faction:Alliance"]="Späher und Soldaten der Allianz müssen stets wachsam bleiben, da Infiltratoren des Kults noch immer versuchen, Seuche und Chaos in den Städten der Lebenden wie Sturmwind zu säen.",["race:Human"]="Jeder Mensch erinnert sich an den Fall von Lordaeron; der Kult der Verdammten dient als bittere Mahnung daran, dass die Menschheit nicht allein von Dämonen bezwungen wurde, sondern von Verrätern aus ihren eigenen Städten und Anwesen.",["race:Undead"]="Für die Verlassenen sind die Kultisten erbärmliche Schoßhunde, die bereitwillig ihre Freiheit für den Meister opfern, dessen geistige Ketten die Verlassenen unter so großen Mühen sprengten."},sec={{t="Eine Krankheit der Seele",b="Der Kult der Verdammten wurde vom verbannten Erzmagier Kel'Thuzad ins Leben gerufen, nachdem dieser den telepathischen Einflüsterungen des Lichkönigs gefolgt war, die vom Frostthron ausgingen. Ausgestattet mit unermesslichem Reichtum und verbotenen dunklen Künsten kehrte Kel'Thuzad nach Lordaeron zurück und verkündete zwei trügerische Heilsversprechen: Den verzweifelten, verarmten Unterschichten versprach er gesellschaftliche Gleichheit und Erlösung aus ihrem Elend; den wohlhabenden Grundbesitzern wie dem adligen Hause Barov versprach er ewiges Leben und unerschütterliche Macht über ihre Besitztümer. In Wahrheit waren sowohl die Mittellosen als auch die Vermögenden lediglich Schlachtvieh, gebunden an einen Todeskult, der ihre Heimat von innen heraus verraten sollte."},{t="Die vergiftete Ernte",b="In völliger Verborgenheit verfeinerten die Kultisten in den Verliesen unter Darrowehr ihr nekrotisches Handwerk, schufen gewaltige Monstrositäten und perfektionierten die Seuche des Untodes, die aus Nordend nach Süden gebracht worden war. Sie schlugen in Lordaerons Kornkammer zu und verseuchten die Getreidespeicher von Andorhal. Als das verdorbene Mehl über gewöhnliche Handelswege die Herde im gesamten Eastweald erreichte, erkrankten die einfachen Leute und starben binnen weniger Tage, nur um als schlurfende Knechte unter der telepathischen Peitsche des Lichkönigs wieder aufzuerstehen. Als Prinz Arthas Kel'Thuzad in Andorhal erschlug, war das Netzwerk der Kultisten bereits so tief verwurzelt, dass das Schicksal des Königreichs besiegelt war."},{t="Die gegenwärtige Bedrohung",b="Obgleich Arthas nach Nordend segelte und den Frostthron bestieg, bleibt der Kult der Verdammten im nördlichen Lordaeron unter dem Befehl des wiederauferstandenen Erzlichs Kel'Thuzad voll einsatzfähig. Aus den Schatten von Stratholme und den Hallen von Scholomance vollführen lebende Kultisten dunkle Riten, warten die giftigen Seuchenkessel auf den zerstörten Gehöften und trachten danach, Scharlachrote Kreuzfahrer wie auch Verlassene gleichermaßen zu ermorden. Da sie noch atmen, können sich diese Akolythen unbemerkt durch Siedlungen der Lebenden bewegen, Brunnen vergiften, Nachschublinien sabotieren und neue Rekruten anwerben, um die Kriegsmaschinerie der Geißel zu füttern."}},faq={{q="Warum sollten sich lebende Sterbliche einem Kult anschließen, der Menschen in Untote verwandelt?",a="Kel'Thuzad nutzte die Schwächen der Sterblichen aus. Den verarmten Unterschichten bot er eine neue Ordnung vollkommener Gleichheit und Befreiung von ihren Entbehrungen, während er wohlhabenden Adligen wie Baron Totenschwur und der Familie Barov Unsterblichkeit und ewige Macht versprach. Die meisten Novizen wurden über die wahre, schreckliche Natur der Seuche im Unklaren gelassen, bis es für eine Umkehr zu spät war.",al={"warum dem kult der verdammten beitreten","motive der kultisten","warum der geißel dienen"}},{q="Warum dürfen Kultisten am Leben bleiben, anstatt getötet und wiedererweckt zu werden?",a="Lebende Agenten besitzen für den Lichkönig einen enormen praktischen Wert. Sie können sich unerkannt durch menschliche Siedlungen bewegen, auf regulären Handelsrouten reisen, Vorräte erwerben und Königreiche von innen heraus untergraben. In der Lehre des Kults gilt der Untod zudem als ruhmreiche Belohnung, die man sich durch hingebungsvollen Dienst verdienen muss.",al={"warum sind kultisten menschen","warum sind sie nicht untot","lebende kultisten"}},{q="Wo hat der Kult der Verdammten seinen Stützpunkt?",a="Ihre wichtigste akademische und geistliche Festung ist Scholomance, gelegen in den Katakomben unter Darrowehr. Abseits dieser Akademie operieren große Ansammlungen von Kultisten in den Ruinen von Stratholme, rund um die Seuchenkessel der Westlichen und Östlichen Pestländer sowie in geheimen Zellen, die in Siedlungen der Lebenden verborgen liegen.",al={"hauptquartier des kults","wo ist der kult","hauptbasis des kults"}},{q="Wer gründete den Kult der Verdammten?",a="Erzmagier Kel'Thuzad, ein ehemaliges hochrangiges Mitglied der Kirin Tor von Dalaran. Nachdem er wegen seiner verbotenen nekromantischen Studien gemaßregelt worden war, reiste er nach Norden, um mit dem Lichkönig in Kontakt zu treten, der ihm gewaltige Macht verlieh und ihn nach Lordaeron zurücksandte, um die sterbliche Vorhut der Geißel aufzubauen.",al={"wer schuf den kult der verdammten","gründer des kults","kel'thuzad kult"}},{q="Wie verbreitet der Kult der Verdammten die Seuche heute?",a="Während sie die Seuche anfangs über verseuchte Getreidelieferungen aus Andorhal verbreiteten, stützen sie sich heute vor allem auf gewaltige Seuchenkessel, die auf den Höfen der Pestländer verteilt sind. Kesselmeister des Kults brauen widerwärtige Reagenzien, um fortwährend giftige Schwaden der Seuche freizusetzen, die das Land ersticken und gefallene Leichen auferstehen lassen.",al={"wie sich die seuche verbreitet","seuchenkessel","wie greift der kult an"}},{q="In welchem Verhältnis steht der Kult zu den Verlassenen?",a="Sie sind erbitterte Feinde. Die Verlassenen rissen sich von der telepathischen Kontrolle des Lichkönigs los und streben nach Rache an der Geißel. Die Kultisten betrachten die Verlassenen als gestohlenes Eigentum sowie Ketzer und versuchen unentwegt, sie zu vernichten oder die Ruinen von Lordaeron für den Frostthron zurückzuerobern.",al={"kult gegen verlassene","verlassene kult der verdammten"}}},fx={["13254224"]={q="Was ist der Kult der Verdammten?",a="Der Kult der Verdammten ist ein geheimes Netzwerk aus lebenden Sterblichen, die dem Lichkönig dienen und das sterbliche Fundament der Geißel bilden. Er besteht hauptsächlich aus fanatischen Menschen sowie Mitgliedern anderer Völker; sie infiltrieren Siedlungen, studieren dunkle Nekromantie und arbeiten unermüdlich daran, den lebenden Königreichen Tod und Seuche zu bringen, im Austausch für das Versprechen auf Unsterblichkeit und Macht.",al={"was ist der kult der verdammten","wer ist der kult der verdammten","identität kult der verdammten"}},["3f52b63c"]={q="Wer führt den Kult der Verdammten an?",a="Der Kult wird auf Azeroth vom Erzlich Kel'Thuzad befehligt, dem ehemaligen Erzmagier von Dalaran, der den Orden gründete. Über ihm herrscht der Lichkönig selbst, der an den Frostthron in Nordend gebunden ist und den alle Kultisten als ihren dunklen Herrn und Gott verehren.",al={"wer führt den kult der verdammten","anführer kult der verdammten","wer ist der anführer des kults"}},["3a452ce2"]={q="Mit wem ist der Kult der Verdammten verbündet?",a="Der Kult arbeitet direkt für den Lichkönig und dient an der Seite der Legionen der untoten Geißel. Obwohl sie einst die Ankunft der Brennenden Legion während des Dritten Krieges erleichterten, gilt ihre absolute Hingabe dem Thron von Nordend und seinem Lich-Kommandanten Kel'Thuzad.",al={"verbündete kult der verdammten","für wen arbeitet der kult","mit wem ist der kult der verdammten verbündet"}},["3250aa21"]={q="Woher stammt der Kult der Verdammten?",a="Jahre vor dem Dritten Krieg erreichte der Lichkönig telepathisch von Nordend aus den Erzmagier Kel'Thuzad und lockte ihn mit nekromantischer Macht. Kel'Thuzad kehrte nach Lordaeron zurück und nutzte sein Vermögen und seine Demagogie, um sowohl desillusionierte Bürgerliche als auch machtgierige Adlige zu rekrutieren. Im Geheimen operierend aus den Katakomben von Darrowehr, entwickelte der Kult die Seuche des Untodes, verteilte verseuchtes Getreide in ganz Andorhal und im nördlichen Lordaeron und ebnete den Weg für den katastrophalen Untergang des Königreichs.",al={"geschichte kult der verdammten","geschichte des kults der verdammten","wie fing der kult an"}},af150ded={q="Warum ist der Kult der Verdammten Reisenden gegenüber feindselig?",a="Die Kultisten betrachten alle lebenden Menschen außerhalb ihrer Reihen als Rohmaterial für ihre nekromantischen Experimente oder als zukünftige Soldaten für die Geißel. Sie greifen Außenstehende sofort an, um ihre geheimen Labore zu bewachen, ihre Seuchenkessel zu schützen und jeden auszuschalten, der ihre dunklen Rituale stören könnte.",al={"warum sind kultisten feindselig","warum greift der kult an","kult der verdammten feindselig"}}},fp="18,457,22.652.0,20.632.0,18.609.0,62.368.0,74.313.0,38.324.0,35.291.0,56.309.0,48.283.0"}
P.entries["topic:dark-iron-clan"] = {fx={["2c9aae62"]={q="Was ist der Dunkeleisenclan?",a="Der Dunkeleisenclan ist neben den Bronzebarts und Wildhämmern eine der drei Hauptfraktionen der Zwerge. Bekannt für ihre Zauberei, ihren rücksichtslosen Ehrgeiz und ihre meisterhafte Steinmetzkunst, leben sie tief im Schwarzfels unter ihrer Hauptstadt Schattenhammer. In Knechtschaft an den Feuerfürsten Ragnaros gebunden, führen sie Krieg gegen sowohl die Allianz als auch die Horde.",al={"wer sind die dunkeleisenzwerge","dunkeleisenzwerge","was sind dunkeleisenzwerge"}},afe1d736={q="Warum sind Dunkeleisenzwerge Reisenden gegenüber feindselig?",a="Angetrieben von jahrhundertelangem bitterem Hass auf Eisenschmiede und gefangen in der feurigen Tyrannei von Ragnaros, sehen die Dunkeleisenzwerge alle Außenstehenden als Feinde oder Werkzeuge. Unter den Befehlen des Feuerfürsten bereitet Kaiser Dagran Thaurissan seine Armeen auf die totale Eroberung vor, startet aggressive Überfälle in benachbarte Länder und schlachtet jeden ab, der ihr Gebiet betritt.",al={"warum greifen dunkeleisenzwerge an","feindseligkeit dunkeleisenzwerge","sind dunkeleisenzwerge böse"}},["627d3f57"]={q="Mit wem ist der Dunkeleisenclan verbündet?",a="Der Dunkeleisenclan dient Ragnaros dem Feuerfürsten und seinen Elementararmeen, in harte Knechtschaft gebunden, seit ihre Hexenmeister ihn versehentlich beschworen haben. Während sie eine tückische Rivalität mit den Schwarzfelsorks pflegen, die die obere Spitze besetzt halten, sind ihre Streitkräfte auch im gefallenen Gnomeregan präsent, obwohl ihre genaue Rolle dort unklar ist.",al={"verbündete dunkeleisenzwerge","für wen arbeiten dunkeleisenzwerge","meister der dunkeleisenzwerge"}}}}
P.entries["topic:dark-iron-dwarf"] = {n="Dunkeleisenzwerg",s="Dunkeleisenzwerge sind ein eigenständiges Zwergen-Untervolk, das sich durch aschgraue Haut, lodernde rote Augen und eine angeborene Affinität zum Feuer auszeichnet. Nach dem Bürgerkrieg der Drei Hämmer aus Eisenschmiede verbannt, hausen sie tief im Inneren des Schwarzfels, wo ihre Gesellschaft unter die tyrannische Herrschaft des Feuerfürsten Ragnaros gefallen ist.",h="Dunkeleisenzwerge sind ein eigenständiges Zwergen-Untervolk, das sich durch aschgraue Haut, lodernde rote...",kw={"blackrocktiefen","dunkeleisen","zwerg","ironfoe","ragnaros","shadowforge","thaurissan","thoriumbruderschaft"},ang={["faction:Alliance"]="Späher der Allianz beobachten die Dunkeleisenzwerge mit Argusaugen, da sie deren imperiale Armeen als aggressive, expansionistische Bedrohung wahrnehmen, die direkt an die südlichen Tore des Territoriums von Eisenschmiede drängt.",["faction:Horde"]="Die Horde betrachtet die Dunkeleisenzwerge als gefährliche Fanatiker, die den Schwarzfels besetzen und die Nachschubwege der Horde durch das Ödland und die angrenzenden Pässe unmittelbar gefährden.",["profession:Blacksmithing"]="Dunkeleisen-Kunsthandwerker sind legendäre Schmiede, die als Einzige die Kunst beherrschen, Dunkeleisenerz zu verarbeiten, wofür die sengende Hitze der Schwarzen Schmiede im Schwarzfels benötigt wird, um es zu schmelzen und zu formen.",["race:Dwarf"]="Für die Bronzebartzwerge von Eisenschmiede stellen die Dunkeleisenzwerge eine andauernde Familienfehde dar, die sich zu einer existentiellen Bedrohung entwickelt hat und auf ihre blutige Rebellion während des Krieges der Drei Hämmer zurückgeht."},sec={{t="Feuriges Erbe und Exil",b="Anders als ihre Vettern von den Bronzebärten und Wildhämmern besitzen Dunkeleisenzwerge dunkelgraue oder rußschwarze Haut und Augen, die wie glühende Kohlen brennen. Ihre Geschichte spaltete sich während des Krieges der Drei Hämmer, als ihr Zauberkönig Thaurissan versuchte, Eisenschmiede zu erobern. Geschlagen und nach Süden in das Rotkammgebirge vertrieben, versuchte Thaurissan, dunkle Mächte zu beschwören, um seine Niederlagen zu rächen, und entfesselte dabei unabsichtlich Ragnaros den Feuerfürsten aus den Elementarebenen. Die katastrophale Beschwörung zerschmetterte die umliegenden Gipfel in die vulkanische Ödnis des Schwarzfels und kettete das Volk der Dunkeleisenzwerge in feurige Knechtschaft."},{t="Im Schatten des Feuerfürsten",b="Das Leben in der tief gelegenen unterirdischen Stadt Shadowforge ist brutal und unbarmherzig. Während die Dunkeleisenzwerge einst lediglich ehrgeizig und gerissen waren, haben Generationen unter dem Schwarzfels unter der erdrückenden Aura von Ragnaros einen Großteil ihrer Kultur zu Grausamkeit, Paranoia und Tyrannei verkommen lassen. Das Recht der Dunkeleisenzwerge kennt für Vergehen nur ein einziges Urteil: den Kampf im brutalen Ring of the Law. Giftmorde und politische Intrigen sind so alltäglich, dass Reisende der Dunkeleisenzwerge gewohnheitsmäßig ihre eigenen Rationen einpacken, anstatt Nahrung von Fremden zu trauen."},{t="Abtrünnige und Ausgestoßene",b="Nicht alle Dunkeleisenzwerge dienen Imperator Dagran Thaurissan und dem Kult von Ragnaros. Abtrünnige Fraktionen haben sich losgesagt, um ihre eigenen Ziele zu verfolgen. Die bedeutendste unter ihnen ist die Thoriumbruderschaft, eine Gilde von Meisterschmieden mit Sitz an der Thoriumspitze in der Sengenden Schlucht, die sich vom Hauptclan abgewandt hat, um externe Abenteurer gegen ihre früheren Herren anzuheuern. Andere arbeiten als Söldner, Spione oder Handwerksingenieure an der Seite neutraler Organisationen wie der Venture Company."}},faq={{q="Warum haben Dunkeleisenzwerge graue Haut und rote Augen?",a="Ihre dunkelgraue Haut und die feurigen, glühend roten Augen sind natürliche Merkmale, die sie von Berg- und Hügelzwergen unterscheiden. Ihre tief unterirdische Lebensweise und Jahrhunderte in unmittelbarer Nähe zu den elementaren Feuern von Ragnaros haben ihre vulkanische Natur weiter verstärkt.",al={"aussehen der dunkeleisenzwerge","warum dunkeleisenzwerge so aussehen","rote augen dunkeleisenzwerg"}},{q="Sind alle Dunkeleisenzwerge böse?",a="Nicht zwangsläufig. Obwohl die imperiale Dunkeleisengesellschaft tückisch ist und vom Willen von Ragnaros beherrscht wird, zeugen historische Gestalten wie der legendäre Baumeister Franclorn Forgewright und Gruppen wie die rebellische Thoriumbruderschaft von Ehre, Tapferkeit und einem eigenständigen Willen abseits der Verderbnis des Feuerfürsten.",al={"sind alle dunkeleisenzwerge böse","gute dunkeleisenzwerge","können dunkeleisenzwerge gut sein"}},{q="Wo liegt die Hauptstadt der Dunkeleisenzwerge?",a="Das Zentrum ihrer Zivilisation ist Shadowforge City, tief in den unterirdischen Höhlen der Schwarzfelstiefen im Schwarzfels. Von dort aus überwacht Imperator Dagran Thaurissan sein Reich unter dem Schatten des Geschmolzenen Kerns.",al={"hauptstadt der dunkeleisenzwerge","wo leben dunkeleisenzwerge","dunkeleisenzwerg stadt"}},{q="Was ist der Ring of the Law?",a="Der Ring of the Law ist die Arena, in der die Justiz der Dunkeleisenzwerge vollstreckt wird. In der Gesellschaft der Dunkeleisenzwerge steht auf Verbrechen gegen den Clan der Tod. Angeklagte werden gezwungen, den Blutzoll zu zahlen, indem sie gegen Wellen bösartiger Bestien und Gladiatoren kämpfen – eine Prüfung, die praktisch kein Gefangener je überlebt.",al={"ring of the law","dunkeleisenzwerg arena","shadowforge prozess"}},{q="Was ist die Thoriumbruderschaft?",a="Die Thoriumbruderschaft ist eine abtrünnige Fraktion von Dunkeleisenhandwerkern, die sich aus dem Dienst von Ragnaros losgesagt hat. Ihr Lager befindet sich an der Thoriumspitze in der Sengenden Schlucht, wo sie ihr unvergleichliches Wissen über feurige Metallurgie und die Schmiedegeheimnisse der Dunkeleisenzwerge mit Abenteurern teilen, die bereit sind, den imperialen Clan zu schwächen.",al={"thoriumbruderschaft geschichte","wer ist die thoriumbruderschaft","thoriumspitze zwerge"}}},fx={["95842395"]={q="Was sind Dunkeleisenzwerge?",a="Die Dunkeleisenzwerge sind eine eigenständige Zwergenart, die vorwiegend aus dem Dunkeleisenclan stammt. Bekannt für ihre aschfahle Haut, ihre feurig roten Augen und ihre Meisterschaft in Zauberei und Handwerk, besitzen sie eine wilde Entschlossenheit und ein berüchtigtes Temperament. Während die meisten in ihrem unterirdischen Herrschaftsbereich unter dem Schwarzfels leben, gehören einige unabhängigen Fraktionen wie der Thoriumbruderschaft oder Söldnergruppen an.",al={"wer sind die dunkeleisenzwerge","dunkeleisenzwerge","was ist ein dunkeleisenzwerg"}},["25c6bc58"]={q="Warum sind Dunkeleisenzwerge Reisenden gegenüber feindselig?",a="Jahrhunderte der Isolation, des internen Verrats und die korrumpierende Präsenz des Feuerfürsten Ragnaros haben den Dunkeleisenclan manipulativ, grausam und zutiefst misstrauisch gegenüber Außenstehenden gemacht. Sie betrachten Vergehen gegen ihren Clan mit äußerster Strenge und bestrafen Eindringlinge und Kriminelle mit dem Tod oder blutigen Kämpfen in der Arena des Gesetzes.",al={"warum greifen dunkeleisenzwerge an","dunkeleisenzwerge aggressiv","warum sind dunkeleisenzwerge feindselig"}},d8b686f4={q="Mit wem sind die Dunkeleisenzwerge verbündet oder wem dienen sie?",a="Der Großteil des Dunkeleisenclans ist in Knechtschaft an den elementaren Feuerfürsten Ragnaros gebunden, dessen feuriger Einfluss ihre Gesellschaft durchdringt. Viele arbeiten auch an der Seite von Elementarstreitkräften und dunklen Kulten, während unabhängige Splittergruppen wie die Thoriumbruderschaft gegen die Führung des Clans arbeiten.",al={"für wen arbeiten dunkeleisenzwerge","verbündete dunkeleisenzwerge","dunkeleisenzwerge ragnaros"}},["7edffefb"]={q="Woher stammen die Dunkeleisenzwerge?",a="Die Dunkeleisenzwerge waren einst einer der drei herrschenden Zwergenclans von Eisenschmiede. Nach dem Krieg der drei Hämmer floh ihr Hexenmeister-Than Thaurissan in den Süden und beschwor versehentlich Ragnaros den Feuerfürsten nach Azeroth. Die Katastrophe erschütterte das Rotkammgebirge, erschuf den Schwarzfels und kettete den Dunkeleisenclan an den Willen des Feuerfürsten.",al={"ursprung dunkeleisenzwerge","geschichte der dunkeleisenzwerge","krieg der drei hämmer"}}},fp="15,328,24.618.0,27.536.0,22.482.0,53.271.0,31.303.0,46.226.0,28.293.0,32.295.0"}
P.entries["topic:dark-riders"] = {n="Dunkle Reiter",s="Die Dunklen Reiter sind eine Bande mysteriöser, vermummter Reiter, die den Dämmerwald terrorisieren. Als gnadenlose Jäger magischer Relikte schlagen sie aus dem Verborgenen zu und hinterlassen nichts als ein Blutbad.",h="Die Dunklen Reiter sind eine Bande mysteriöser, vermummter Reiter, die den Dämmerwald terrorisieren.",kw={"ariden","schwarze reiter","dunkle reiter","gebirgspass der totenwinde","dämmerwald","bibbers","the scythe of elune","sven yorgen"},ang={["class:Druid"]="Die rücksichtslose Jagd der Dunklen Reiter nach The Scythe of Elune stellt eine ernste Bedrohung für das Gleichgewicht dar, da die wilden Energien der Waffe im gesamten Dämmerwald verheerenden Schaden anrichten können.",["class:Mage"]="Als unerbittliche Jäger magischer Relikte sind die Reiter eine lebendige Warnung dafür, wie viel Blut das Streben nach arkaner Macht kosten kann.",["faction:Alliance"]="Die Reiter schlagen direkt hinter den Grenzen von Sturmwind zu und schlachten unschuldige Siedler wie Sven Yorgens Familie ab, was beweist, wie weit die Grenze des Königreichs seiner Kontrolle entglitten ist."},sec={{t="Jäger in der Dunkelheit",b="Über die Ursprünge der Dunklen Reiter ist nur wenig bekannt. Zeugen beschreiben vermummte Reiter, die mit rauen und schrillen Stimmen sprechen, und einer wurde dabei beobachtet, wie er einen kleinen Edelstein benutzte, um Befehle von einem Meister entgegenzunehmen, den er nur seinen ‚Herrn‘ nannte. Sie jagen Objekte von magischer Macht durch das gesamte Königreich und metzeln jeden nieder, der sich ihnen und ihrer Beute in den Weg stellt."},{t="Gemetzel auf Yorgens Bauernhof",b="Die Reiter drangen kürzlich in den Dämmerwald vor, angezogen von raumverzerrenden Erschütterungen, die von The Scythe of Elune ausgingen. Ohne ihr Wissen hatte der Bergarbeiter Bibbers den uralten Stab in Rolands Verdammnis freigelegt und sofort wieder verloren. Indem sie die magische Signatur bis zum nahegelegenen Yorgens Bauernhof zurückverfolgten, forderten die Reiter das Artefakt von Sven Yorgens Familie. Als die verängstigten Siedler keine Antworten geben konnten, schlachteten die Reiter Svens Frau und Kinder kaltblütig ab, was Sven in einen rachsüchtigen Wahnsinn trieb."},{t="Schatten über dem Dämmerwald",b="Flüstern im Dämmerwald bringt die finsteren Jagden der Reiter mit dem abtrünnigen Nekromanten Morbent Fel in Verbindung, obwohl niemand weiß, was die beiden miteinander verbindet oder wer der ‚Herr‘ sein mag, dem die Reiter dienen."}},faq={{q="Wer sind die Dunklen Reiter?",a="Sie sind eine Bande vermummter Reiter, die nach Objekten magischer Macht jagen und jeden niedermetzeln, der sich ihnen in den Weg stellt. Ihre Ursprünge und die Identität des Meisters, dem sie dienen, bleiben ein Geheimnis.",al={"schwarze reiter","was sind die dunklen reiter","wer sind die reiter im dämmerwald"}},{q="Was haben sie Sven Yorgens Familie angetan?",a="Sie jagten nach The Scythe of Elune, die in der Nähe ausgegraben worden war. Als sie Sven Yorgens Frau und Kinder verhörten und feststellten, dass diese nichts über das Artefakt wussten, ermordeten die Reiter sie gnadenlos.",al={"gemetzel auf svens bauernhof","was geschah auf yorgens bauernhof","warum töteten die reiter svens familie"}},{q="Warum sind die Dunklen Reiter im Dämmerwald?",a="Sie wurden von den zeitlichen und magischen Störungen, die durch The Scythe of Elune, ein in Rolands Verdammnis ausgegrabenes uraltes Artefakt, verursacht wurden, in den dunklen Wald gezogen.",al={"warum sind dunkle reiter im dämmerwald","dunkle reiter the scythe of elune","was jagen sie"}},{q="Sind die Dunklen Reiter Untote?",a="Niemand weiß es. Sie sprechen mit rauen, schrillen Stimmen und schlagen aus dem Verborgenen zu, doch was sich unter ihren vermummten Umhängen verbirgt, bleibt ein Geheimnis.",al={"sind dunkle reiter geister","sind die dunklen reiter untote","was sind die dunklen reiter"}},{q="Arbeiten sie mit Morbent Fel zusammen?",a="The Night Watch hat verdächtige Geschäfte zwischen den Dunklen Reitern und dem Nekromanten Morbent Fel im Dämmerwald bemerkt, doch die genauen Bedingungen ihrer Allianz bleiben unbekannt.",al={"morbent fel und dunkle reiter","morbent fel allianz"}}},fx={c7ab6d4f={q="Was ist die Geschichte der Dunklen Reiter?",a="Über ihre Geschichte ist nur wenig bekannt. Sie tauchten im Dämmerwald auf, auf der Jagd nach The Scythe of Elune, und ermordeten die Familie von Sven Yorgen, als die Bauern nicht sagen konnten, wo sie war; die Nachtwache verbindet sie mit dem Nekromanten Morbent Fel. Einer von ihnen wurde dabei gesehen, wie er über einen kleinen Edelstein Befehle von einem Meister entgegennahm, den er seinen 'Herrn' nannte.",al={"ursprung dunkle reiter","woher kommen die dunklen reiter","wie wurden die dunklen reiter erschaffen"}}},fp="11,182,19.329.0,26.494.1,21.186.1,24.190.0,41.214.1,36.154.0,27.133.1,34.171.0"}
P.entries["topic:darkspear-tribe"] = {fx={f751a05c={q="Was ist der Stamm der Dunkelspeere?",a="Die Dunkelspeere sind ein Stamm von Dschungeltrollen, die als Kernmitglieder von Thralls Horde gelten. Einst aus ihren uralten Ländereien im Schlingendorntal vertrieben, überlebten sie das Exil, eine gefährliche Seereise und Verrat in der Heimat. Bekannt für ihre Anpassungsfähigkeit und Gerissenheit, haben sie den Ehrenkodex der Horde angenommen und bewahren gleichzeitig ihre Traditionen der Shadow Magic, des Voodoo und der Loa-Verehrung.",al={"wer sind die darkspear trolle","was ist der darkspear tribe","darkspear tribe"}}}}
P.entries["topic:defias-brotherhood"] = {n="Bruderschaft der Defias",s="Die Bruderschaft der Defias ist ein weitreichendes kriminelles Netzwerk aus Banditen, Räubern und Meuchelmördern, das einen Untergrundaufstand gegen das Königreich Sturmwind führt. Ursprünglich von den Handwerkern der Stonemasons Guild gegründet, die um ihren Lohn für den Wiederaufbau der Hauptstadt betrogen wurden, haben sie sich zu gewalttätigen Gesetzlosen entwickelt, die das südliche Ackerland terrorisieren. Aus ihrer verborgenen Zuflucht tief unter Westfall versuchen sie, das korrupte House of Nobles zu stürzen und das Königreich zu verwüsten.",h="Die Bruderschaft der Defias ist ein weitreichendes kriminelles Netzwerk aus Banditen, Räubern und...",kw={"bandanas","bruderschaft","die todesminen","defias","elwynn","juggernaught","mondbruch","steinmetze","van cleef","westfall"},ang={["class:Paladin"]="Die Ritter der Silbernen Hand und Kirchenoberhäupter wie Duthorian Rall rufen Paladine dazu auf, wehrlose Siedler wie Daphne Stillbrunn vor rücksichtslosen Defias-Räubern in Westfall zu verteidigen.",["class:Rogue"]="Meister Mathias Shaw und SI:7 haben ein wachsames Auge auf die Defias, da van Cleefs Agenten den königlichen Kundschaftern im Schlösserknacken, in der Tarnung und bei tödlichen unterirdischen Hinterhalten in nichts nachstehen.",["faction:Alliance"]="Der Aufstand bedroht die Stabilität des gesamten Königreichs, indem er die Getreidelieferungen aus Westfall abwürgt, Goldminen destabilisiert und das Vertrauen der Öffentlichkeit in die Führung von Sturmwind erschüttert.",["race:Human"]="Für die Menschen des Königreichs sind die Defias eine bittere Mahnung an die innere Fäulnis Sturmwinds – eine Tragödie, in der ehrliche Erbauer der Stadt durch die Gier des Adels zu Halsabschneidern wurden."},sec={{t="Von Steinmetzen zu Marodeuren",b="Nach dem Zweiten Krieg wurde die Stonemasons Guild angeheuert, um Sturmwind aus rauchenden Ruinen zu einer prächtigen steinernen Hauptstadt wiederaufzubauen. Als ihr Meisterwerk vollendet war, weigerte sich das House of Nobles unter Berufung auf erdrückende Kriegsschulden, die versprochene Bezahlung zu leisten. Gildenmeister Edwin van Cleef sprach sich im Namen seiner Arbeiter für eine gerechte Entschädigung aus, doch die Adligen reagierten darauf, indem sie die Auflösung der Stonemasons Guild anordneten. Die darauffolgenden Unruhen in den Straßen der Stadt endeten damit, dass die Arbeiter aus Sturmwind ins Exil getrieben wurden. Ihrer Existenzgrundlage beraubt und für vogelfrei erklärt, schlossen sich van Cleef und die verzweifelten Arbeiter zusammen, verhüllten ihre Gesichter in roter Seide, um das Blut derer darzustellen, denen Unrecht getan wurde, und verlegten sich auf Straßenraub, um einzufordern, was ihnen ihrer Ansicht nach zusteht."},{t="Der Schatten über Westfall",b="Da die königliche Armee überdehnt war, machte van Cleef das vernachlässigte Ackerland von Westfall zur Operationsbasis der Bruderschaft. Die Banditen überrannten den Weiler Mondbruch und beschlagnahmten die verlassenen unterirdischen Tunnel der Todesminen. Agenten der Defias brachten örtliche Minen unter ihre Kontrolle, vertrieben Bauern mit umprogrammierten Erntegolems von ihren Höfen und streuten Salz auf die Erde, um die Region auszuhungern. Da die Krone nicht in der Lage oder nicht willens war, Soldaten zum Schutz der ländlichen Bürger zu entsenden, gründeten die einheimischen Bauern von Späherkuppe aus die Volksmiliz, um einen verzweifelten Abnutzungskrieg gegen einen Feind zu führen, der ihnen inzwischen zahlen- und waffenmäßig überlegen ist."},{t="Ein Netz aus Verschwörungen",b="Die Bruderschaft ist längst über eine einfache Bande vertriebener Arbeiter hinausgewachsen. Van Cleef heuerte Söldnergoblins an, um die Bewaffnung zu beaufsichtigen, schloss Bündnisse mit Riverpaw-Gnollen und Elwynn-Kobolden und trieb Handel mit skrupellosen Piraten wie den Blutsegelbukanieren. Wegelagerer der Defias überfallen Goldtransporte im gesamten Wald von Elwynn, und ihre Agenten fassten sogar im Dämmerwald Fuß, bevor sie in Rolands Verdammnis ein verfluchtes Artefakt ausgruben. Weitaus schlimmer ist, dass der Einfluss der Bruderschaft bis in das Herz der Hauptstadt reicht, wo sie verdeckte Unterstützung von verräterischen Aristokraten innerhalb des House of Nobles genießt, während sie Entführungen inszeniert, die die höchsten Ämter der Allianz treffen."},{t="Der Juggernaught in den Todesminen",b="Unter Mondbruch liegt die Eiserne Bucht, wo van Cleefs Gobliningenieure heimlich ein gewaltiges eisenbeschlagenes Kriegsschiff zusammenbauen, das als Defias Juggernaught bekannt ist. Der Gildenmeister beabsichtigt, diese schwimmende Festung durch die unterirdischen Küstengewässer hinauszusegeln und Sturmwind vom Meer aus zu bombardieren, um seine eigene großartige Architektur in Schutt und Asche zu legen. Die Verschwörung reicht bis in den königlichen Hof selbst: Korrupte Adlige wie Lord Gregor Lescovar dienen als Augen und Ohren für den Aufstand, während die höfischen Machenschaften von Lady Katrana Prestor das Königreich bewusst gespalten und blind für die entstehende Flotte unter Westfall halten."}},faq={{q="Warum tragen die Defias rote Bandanas?",a="Das rote Seidenbandana wurde von Edwin van Cleef und den verbannten Steinmetzen als Symbol des Widerstands angenommen. Es steht für das vergossene Blut der unterdrückten Arbeiterklasse, die Sturmwind wiederaufbaute und vom Adel mit gebrochenen Versprechen, Gewalt und Verbannung abgespeist wurde.",al={"bedeutung der defias-maske","warum rote seide","bedeutung roter bandanas"}},{q="Warum greift die Bruderschaft unschuldige Bauern anstelle von Adligen an?",a="Obwohl die Bruderschaft aufgrund berechtigter Missstände gegen den Adel gegründet wurde, verwandelten Jahre des gesetzlosen Exils sie in ein brutales kriminelles Imperium. Verzweiflung, Gier und die Rekrutierung skrupelloser Halsabschneider und Goblins brachten sie dazu, örtliche Gehöfte zu plündern, Ernten niederzubrennen und Minen zu beschlagnahmen, um ihre Kriegsmaschinerie zu finanzieren.",al={"warum defias bauern angreifen","warum westfall schaden","motiv der defias"}},{q="Wer ist Edwin van Cleef?",a="Edwin van Cleef war der brillante Gildenmeister der Stonemasons Guild, der den Wiederaufbau von Sturmwind nach dem Zweiten Krieg beaufsichtigte. Ausgebildet in Tarnung und Täuschung gründete er die Bruderschaft der Defias, nachdem sich das House of Nobles geweigert hatte, die Arbeiter zu bezahlen. Heute leitet er ihre Operationen tief aus den Todesminen.",al={"wer ist van cleef","hintergrund zu edwin van cleef","anführer der defias"}},{q="Warum schickt Sturmwind nicht die Armee, um sich um die Defias zu kümmern?",a="Die Finanzen des Königreichs sind stark erschöpft, und die Armee von Sturmwind ist überdehnt, da sie Außenposten in fernen Gebieten wie dem Schlingendorntal besetzt halten muss. Der politische Stillstand innerhalb des House of Nobles lähmt den Thron zusätzlich, sodass sich das ländliche Westfall und der Dämmerwald mit freiwilligen Milizen selbst verteidigen müssen.",al={"wo ist die armee von sturmwind","warum keine wachen in westfall","warum volksmiliz"}},{q="Was ist die Volksmiliz?",a="Die Volksmiliz ist eine freiwillige Verteidigungstruppe, die von Gryan Starkmantel und den bedrängten Bauern von Späherkuppe organisiert wurde. Da Sturmwind so gut wie keine Soldaten bereitgestellt hat, um die Defias aus Westfall zu vertreiben, griffen die einheimischen Bürger zu den Waffen, um ihr eigenes Land zu verteidigen.",al={"volksmiliz westfall","gryan starkmantel miliz","armee der späherkuppe"}},{q="Was bauen die Defias in den Todesminen?",a="Verborgen in der unterirdischen Höhle, die als Eiserne Bucht bekannt ist, bauen Gobliningenieure und abtrünnige Handwerker den Defias Juggernaught, eine gewaltige eisenbeschlagene Kriegsgaleere. Van Cleef beabsichtigt, mit dem Kriegsschiff in den Hafen von Sturmwind einzulaufen und die Hauptstadt zu vernichten.",al={"schiff in den todesminen","was bauen sie in den todesminen","defias juggernaught"}},{q="Hatten die Defias etwas mit dem Verschwinden des Königs zu tun?",a="Was aus König Varian Wrynn wurde, bleibt ein Rätsel. Er verschwand auf der Reise zu einem Friedensgipfel in Theramore und hinterließ das Kind Anduin unter der Herrschaft eines Regenten auf dem Thron.",al={"haben die defias varian entführt","verschwundener könig defias","verschwundener diplomat defias"}}},fx={d3e0b685={q="Was ist die Bruderschaft der Defias?",a="Die Bruderschaft der Defias ist ein weitverzweigtes kriminelles Syndikat und ein Rebellenzirkel, der sich aus ehemaligen Steinmetzen, Dieben, Wegelagerern und Söldnern zusammensetzt. Ursprünglich aus einem bitteren Streit zwischen den Handwerkern, die Sturmwind wiederaufbauten, und dem korrupten Adel entstanden, der sie nicht bezahlen wollte, hat sich die Gruppe zu einer gewalttätigen Untergrundarmee entwickelt, die entschlossen ist, das Königreich Sturmwind zu stürzen.",al={"was ist die bruderschaft der defias","wer sind die defias","übersicht bruderschaft der defias"}},a3005855={q="Warum operiert die Bruderschaft der Defias in Westfall und Elwynn?",a="Die Defias haben ihre Basis unter der Stadt Mondbruch in den Todesminen von Westfall, einer verarmten Region, die vom Militär Sturmwinds vernachlässigt wird. Von dort aus breiten sie sich über Westfall, den Wald von Elwynn und den Dämmerwald aus, um wertvolle Minen zu besetzen, Nachschublinien zu überfallen und die überlasteten Verteidigungslinien Sturmwinds abzulenken, während sie insgeheim einen katastrophalen Schlag gegen die Hauptstadt vorbereiten.",al={"warum sind defias in westfall","warum sind defias in elwynn","wo befinden sich die defias"}},["5e60415a"]={q="Wie bildete sich die Bruderschaft der Defias?",a="Nach dem Zweiten Krieg baute die Stonemasons Guild Sturmwind aus Ruinen wieder auf. Als das Werk vollendet war, weigerte sich das von militärischen Schulden belastete House of Nobles, sie zu bezahlen. Der Gildenmeister, Edwin van Cleef, führte aus Protest Aufstände an, und die Steinmetze wurden ins Exil getrieben. Sie suchten Zuflucht in Westfall und wandten sich dem Banditentum zu, um ihren versprochenen Lohn einzufordern, wobei sie ihre Reihen stetig mit Kriminellen und Ausgestoßenen vergrößerten.",al={"ursprung der defias","geschichte der defias","wie begannen die defias","steinmetzgilde defias"}},b1c3d7cc={q="Mit wem ist die Bruderschaft der Defias verbündet?",a="Die Bruderschaft hat Bande in den gesamten südlichen Ländern geknüpft. Im Wald von Elwynn heuern sie Kobolde an, um eroberte Minen zu sichern, während sie sich in Westfall mit den Gnollen der Flusspratzen koordinieren. Sie haben Goblin-Ingenieure engagiert, um tödliche Erntegolems zu bauen, mit den Blutsegelbukanieren wegen maritimer Expertise verhandelt und verdeckt mit verräterischen Gestalten innerhalb der Hauptstadt zusammengearbeitet.",al={"verbündete der defias","wer arbeitet mit den defias zusammen","partner der bruderschaft der defias"}}},fp="18,480,24.754.0,24.622.0,21.670.1,33.630.2,36.256.0,68.328.0,22.332.0,60.306.2,29.267.0,50.264.1,66.169.2"}
P.entries["topic:dragonmaw-clan"] = {fx={["27e0e992"]={q="Was ist der Drachenmalclan?",a="Der Drachenmalclan ist ein Orcclan aus Draenor. Sie erlangten während des Zweiten Krieges Berühmtheit, nachdem sie die Dämonenseele benutzt hatten, um die Drachenkönigin Alexstrasza zu versklaven und den roten Drachenschwarm zu zwingen, für die alte Horde zu kämpfen. Nachdem sie bei Grim Batol die Kontrolle über ihre Drachen verloren hatten, sind sie ein gefährlicher, abtrünniger Überrest in den östlichen Landen.",al={"wer sind die drachenmal","infos zum drachenmalclan","was sind drachenmal"}},ef3e041c={q="Warum sind die Drachenmal den Reisenden gegenüber feindselig?",a="Die Drachenmal sind unbelehrbare Überbleibsel der alten Horde, die Thralls friedlichen neuen Weg ablehnen. Verbittert durch den Verlust ihrer versklavten Drachen und aus Grim Batol vertrieben, überleben sie durch gewalttätige Raubzüge und geraten in heftige Konflikte mit den örtlichen Wildhammerzwergen, Reisenden der Allianz und jedem anderen, der sich in die Nähe ihrer befestigten Lager in den Marschen wagt.",al={"warum greifen drachenmal an","sind drachenmal böse","warum sind drachenmal feindselig"}},["2417d206"]={q="Mit wem ist der Drachenmalclan verbündet?",a="Die Überreste der Drachenmal im Sumpfland operieren außerhalb von Thralls neuer Horde. Unter Nek'rosh Totenschädel verteidigen sie ihre Lager gegen nahegelegene Feinde und suchen Rache an den Drachen, die ihre Macht bei Grim Batol zerstört haben.",al={"verbündete der drachenmal","für wen arbeiten drachenmal","drachenmal fraktion"}}}}
P.entries["topic:druids-of-the-fang"] = {fx={d5ccf0b1={q="Warum werden sie Druiden des Fangs genannt?",a="Anstatt traditionelle druidische Formen wie Bären oder Katzen anzunehmen, machten sich diese gefallenen Druiden den Aspekt der Schlange zu eigen. Unter der Führung von Lord Serpentis und ihren schlangenartigen Anführern verwandeln sie sich in Vipern, setzen tödliches Gift ein und halten tödliche Reptilien als Begleiter, wobei sie die traditionellen Pfade des Zirkels des Cenarius aufgeben, um den giftigen Fangzahn zu verkörpern.",al={"warum druiden des fangs","bedeutung des namens druiden des fangs","warum der name fang"}},f17ecb7b={q="Warum sind die Druids of the Fang feindselig?",a="Als Naralex den Smaragdgrünen Traum anzapfte, um das Brachland zu heilen, verfiel seine Vision in einen um sich greifenden Albtraum. Dieser Albtraum verzerrte den Verstand und den Geist seiner Jünger und trieb sie in den Wahnsinn. Nun zu den Druids of the Fang verzerrt, greifen sie jeden Eindringling gewaltsam an, um ihr verderbtes Reich zu schützen und die umliegende Welt dazu zu zwingen, ihre albtraumhaften Visionen widerzuspiegeln.",al={"warum greifen druiden des rudels an","warum sind druiden des rudels aggressiv","feinde der druiden des rudels"}},["1c4e8a0d"]={q="Wie entstanden die Druids of the Fang?",a="Sie waren ursprünglich ein edler Orden von Nachtelfen-Druiden, die Naralex in die unterirdischen Quellen der Höhlen des Wehklagens folgten. Ihre Mission war wohlwollend: den Smaragdgrünen Traum zu kanalisieren, um dem trockenen Brachland üppiges Leben zurückzugeben. Allerdings verzerrte sich der Traum um Naralex in den Wahnsinn, verdarb seine Anhänger und wandte seinen fähigsten Schüler, Lord Serpentis, einer finsteren, fanatischen Ergebenheit zu.",al={"ursprung der druiden des rudels","wie entstanden die druiden des rudels","geschichte der druiden des rudels"}}}}
P.entries["topic:earth-mother"] = {n="Erdmutter",s="Die Erdmutter ist die höchste, gütige Schöpfergottheit, die von den Tauren verehrt wird. Sie gilt als die lebendige Verkörperung und Architektin des Landes und der Elemente Azeroths. In den Mythen der Tauren formte sie die Berge, Ebenen und Jahreszeiten und setzte Sonne und Mond als ihre wachsamen Augen an den Himmel. Ihre Präsenz durchdringt den Alltag der Taurenkultur und leitet ihre Ehrfurcht vor der Natur, ihre Pflicht gegenüber den Elementen und ihre Hoffnung auf das Leben nach dem Tod.",h="Die Erdmutter ist die höchste, gütige Schöpfergottheit, die von den Tauren verehrt wird.",kw={"an'she","schöpfung","erdmutter","mu'sha","mulgore","shu'halo","tauren"},ang={["class:Druid"]="Die Druiden der Tauren betrachten ihr heiliges Band mit der Natur als eine direkte Gemeinschaft mit dem lebendigen Körper der Erdmutter und folgen ihrem uralten Ruf, das Gleichgewicht des Landes zu bewahren.",["class:Shaman"]="Die Schamanen der Tauren ehren die Erdmutter an der Seite der Elementargeister, eingedenk dessen, dass Wind, Wasser, Feuer und Stein ihre ersten Gefährten waren.",["faction:Horde"]="Durch ihr Bündnis mit Mulgore sind Orcs und Dschungeltrolle mit der Ehrfurcht der Tauren vor der Erdmutter vertraut geworden und rufen ihren Namen oft als respektvollen Segen an.",["race:Tauren"]="Jeder Aspekt der Shu'halo-Gesellschaft – vom Respekt des Nomaden vor der Beute bis hin zum Rat der Häuptlinge – ist im Gesetz, der Aufopferung und der beständigen Liebe der Erdmutter verwurzelt."},sec={{t="Die Morgendämmerung der Schöpfung",b="Die Schöpfungsmythen der Tauren besagen, dass die Erdmutter, noch bevor es Tag und Nacht gab, damit begann, Azeroth als Zufluchtsort für ihre kommenden Kinder zu gestalten. Als sie ihre Nägel über die gerade erst emporgehobenen Berge kratzte, entstanden die ersten Feuer der Welt, während ihre Hände Flüsse und Ozeanbetten formten. Ihr Lachen hauchte dem Wind Leben ein, und indem sie den ursprünglichen Nebel in den Himmel hob, brachte sie den ersten Regen, der Gras, Wälder und Getreide aus dem Boden lockte."},{t="Sonne, Mond und die Shu'halo",b="Unterstützt von den freundlichen Elementen brachte die Erdmutter Zwillinge hervor: An'she, die Sonne, und Mu'sha, den Mond. Um zu ruhen und sie gleichzeitig zu beschützen, legte sie die strahlenden Zwillinge in ihre Augen. So schuf sie Tag, Nacht und den Zyklus der Jahreszeiten, indem sie ihre Lider öffnete und schloss. Später drückte sie ihr Herz gegen die fruchtbare Erde und hauchte dem Land das Lied des Lebens ein, um die Shu'halo, die ersten Tauren, zu erschaffen. Sie beauftragte die Zwillinge und die Elemente damit, den jungen Sterblichen beizubringen, wie man jagt, baut, tanzt und in Harmonie mit der Wildnis lebt."},{t="Augen an den Himmeln",b="Mit der Zeit setzte die Erdmutter An'she und Mu'sha an den Himmel, wo Sonne und Mond bei Tag und bei Nacht über das Land wachen. Die Tauren sagen, dass ihr Geist nun in den Flüssen, Bäumen, Ebenen und Bergen der Welt wohnt und dass jeder geringere Naturgeist aus ihr entspringt und am Ende zu ihr zurückkehrt."},{t="Lebendiges Vermächtnis",b="Die Tauren glauben, dass ihr Geist Azeroth immer noch behütet. Ihr Ohr ist auf den Wind abgestimmt und vernimmt die Gebete ihrer Kinder, und ihr Herz schlägt im tiefen Gestein. Jäger, Schamanen und Druiden der Tauren richten ihren Dank für jede Jagd und jede Ernte an sie, da sie glauben, dass alles Leben aus ihrer Umarmung stammt und der Geist eines jeden Tauren nach dem Tod in ihre Erde zurückkehrt."}},faq={{q="Wer ist die Erdmutter?",a="Die Erdmutter ist die gütige Schöpfergottheit im Zentrum des Taurenglaubens. Ihren Mythen zufolge erschuf sie die physische Landschaft Azeroths, gebar Sonne und Mond und formte das Volk der Tauren aus der Erde.",al={"was ist die erdmutter","erdmutter hintergrundwissen","taurengott"}},{q="Was sind ihre Augen am Himmel?",a="Ihr rechtes Auge ist An'she, die Sonne, die Licht und Wärme in die Welt bringt. Ihr linkes Auge ist Mu'sha, der Mond Weiße Dame, der Frieden und Schlummer schenkt. Die Mythologie der Tauren besagt, dass sie sie an den Himmel setzte, um über das Land zu wachen.",al={"anshe und musha","sonne und mond der tauren","augen der erdmutter"}},{q="Ist die Erdmutter ein wirklich lebendes Wesen?",a="Für die Tauren ist sie eine aktive, liebende spirituelle Realität, deren Essenz die natürliche Welt, das Gestein und die Winde durchdringt. Schamanen und Druiden leiten Natur- und Elementargeister durch ihre Segnungen, doch ob sie eine uralte Riesin, eine Weltseele oder eine Allegorie ist, bleibt eine Glaubensfrage.",al={"ist die erdmutter real","existiert die erdmutter","wer ist die erdmutter"}},{q="Verehren auch andere Völker die Erdmutter?",a="Obwohl die Tauren ihre primären Verehrer sind, erkennen andere Völker, die mit dem Land verbunden sind, sie an. Einige Schamanen der Orc und Zentauren rufen ihren Namen respektvoll an, und ihre Segnungen werden in der gesamten Horde häufig ausgetauscht.",al={"erdmutter der orcs","wer verehrt die erdmutter","glauben trolle an die erdmutter"}},{q="Was glauben die Tauren, was nach dem Tod geschieht?",a="Die Tauren glauben, dass, da alle Lebewesen aus der liebevollen Berührung der Erdmutter geboren wurden, jede Seele nach dem Tod zu ihr zurückkehrt. Traditionelle Riten geben den Verstorbenen an das Land zurück, im Vertrauen darauf, dass ihre Geister friedlich in ihrer ewigen Umarmung ruhen.",al={"leben nach dem tod der tauren","bestattungsglaube der tauren","rückkehr zur erdmutter"}}},fx={dbad9a55={q="Wie erschuf die Erdenmutter die Welt und die Tauren?",a="Den Schöpfungsmythen der Tauren zufolge formte die Erdenmutter die Berge, Meere und den Himmel vor Anbeginn der Erinnerung. Nachdem sie ihre Zwillingskinder, An'she und Mu'sha, die Sonne und den Mond, zur Welt gebracht hatte, schenkte sie den Ebenen Leben und erschuf die ersten Tauren, die sie innig liebte. Die Tauren glauben, dass ihr Geist noch immer in jedem Fluss, jedem Baum, jeder Ebene und jedem Berg der Welt wohnt.",al={"schöpfungsgeschichte der erdenmutter","wie erschuf die erdenmutter die welt","geschichte der erdenmutter"}}},fp="12,417,20.438.0,27.543.0,19.308.0,13.367.0,24.227.0,29.224.0,44.296.0,40.226.0,43.253.0"}
P.entries["topic:elemental-plane"] = {fx={["4757a26f"]={q="Wer regiert die Elementarebene?",a="Die Ebene hat keinen einzigen Herrscher, da ihre vier Domänen unabhängig von den vier mächtigen Elementarfürsten regiert werden: Ragnaros der Feuerfürst befiehlt über die Feuerlande, Therazane die Steinmutter regiert Tiefenheim, Al'Akir der Windfürst hält den Himmelswall und Neptulon der Gezeitenjäger überwacht den Abyssalen Schlund. Anstatt zusammenzuarbeiten, haben diese Wesen und ihre Armeen jahrtausendelang in endlosem Krieg gegeneinander über die Grenzen ihrer jeweiligen Reiche hinweg gekämpft.",al={"anführer der elementarebene","wer führt die elementarebene","elementarfürsten"}},a219565c={q="Mit wem sind die Elementare verbündet?",a="In urzeitlichen Zeiten wurden die Elementare von den Alten Göttern in den Dienst gezwungen und führten im Namen ihrer Meister Krieg gegen die Titanen und deren geschmiedete Armeen. Im aktuellen Zeitalter kämpfen die meisten Elementare jedoch strikt für ihre jeweiligen Elementarfürsten. Sie bleiben fast allen Sterblichen gegenüber äußerst feindselig, obwohl bestimmte Fraktionen oder Beschwörer – wie die Dunkeleisenzwerge, die sich versehentlich an Ragnaros banden – ihnen gelegentlich dienen oder mit ihnen handeln.",al={"verbündete der elementare","wem dienen elementare","elementare loyalitäten"}}}}
P.entries["topic:elune"] = {n="Elune",s="Elune ist die verehrte Mondgöttin von Azeroth, die hauptsächlich von den Nachtelfen als ihre gütige Beschützerin und Mutter des Waldhalbgottes Cenarius angebetet wird. Sie wird mit dem größeren Mond, der Weißen Dame, in Verbindung gebracht und herrscht über Frieden, Heilung und Mondzorn auf der ganzen Welt. Im Mythos der Tauren wird sie als Mu'sha, dem sanften linken Auge der Erdenmutter, geehrt.",h="Elune ist die verehrte Mondgöttin von Azeroth, die hauptsächlich von den Nachtelfen als ihre gütige...",kw={"cenarius","elune","mondmutter","mu'sha","nachtkriegerin","schwesternschaft von elune","tyrande","weiße dame"},ang={["class:Druid"]="Als göttliche Mutter von Lord Cenarius ist Elunes himmlischer Einfluss direkt in Eure astralen Kräfte und Eure uralte Verwandtschaft mit der lebendigen Wildnis eingewoben.",["class:Priest"]="Priester der Nachtelfen beziehen ihre göttlichen Zauber und ihren himmlischen Zorn direkt aus Elunes Führung und nutzen strahlendes Mondlicht anstelle des Heiligen Lichts, das in den Östliche Königreiche verehrt wird.",["race:NightElf"]="Jeder Aspekt der Zivilisation der Kaldorei – von der herrschenden Schwesternschaft bis hin zum Mondlicht, das Eure Waldsiedlungen badet – fließt aus Eurer ewigen Hingabe an die Mondmutter.",["race:Tauren"]="Der Mond am Nachthimmel ist Mu'sha, das linke Auge der Erdenmutter, das in Euren angestammten Mythen dafür gepriesen wird, über die Stämme und die Kreaturen der Dunkelheit zu wachen."},sec={{t="Die Weiße Dame",b="Elune ist eine der wenigen wahren Gottheiten, die auf ganz Azeroth anerkannt sind und unzertrennlich mit dem Nachthimmel und dem größeren der beiden Monde der Welt, der Weißen Dame, verbunden sind. Obwohl sie niemals in körperlicher Form in der Welt erscheint, stellen Nachtelfen-Handwerker sie als eine Kaldorei von transzendenter Anmut dar, gebadet in Lumineszenz mit alabasterfarbener Haut, silbernem Haar und Augen aus reinem Mondlicht. Uralte Legenden unter den Kaldorei besagen, dass sie einst während der Tagesstunden in den Tiefen des Brunnens der Ewigkeit ruhte und den frühen Nachtelfen Weisheit zuflüsterte."},{t="Die Schwesternschaft und der Wald",b="Das spirituelle und zivile Leben der Nachtelfen ist in der Hingabe an Elune durch die Schwesternschaft von Elune verankert, eine uralte matriarchalische Priesterschaft, die von der Hohepriesterin Tyrande Wisperwind geleitet wird. Die Schwestern rufen Elune's Grace an, um tödliche Wunden zu heilen, aber sie können auch ihren strahlenden Zorn kanalisieren, um sengendes Sternenlicht auf ihre Feinde herabzurufen. Ihre göttliche Vereinigung mit dem Großen Weißen Hirsch, Malorne, brachte Cenarius hervor und verband Elunes himmlische Mysterien direkt mit den druidischen Traditionen, die die Wildnis von Kalimdor pflegen."},{t="Aspekte und Namen",b="Obwohl Elune für Frieden, Harmonie und friedliche Wiederherstellung bekannt ist, ist sie keine sanfte Pazifistin. Als Nachtkriegerin agiert sie als wilde Schutzherrin der Schlacht, die die Geister gefallener Helden vom Schlachtfeld sammelt und sie an den Himmel versetzt, damit sie als Sterne durch die Nacht reiten. Jenseits der Kaldorei kennen sie die nomadischen Tauren als Mu'sha, das strahlende linke Auge der Erdenmutter, das die Nacht erhellt und wandernde Jäger an der Seite ihres feurigen Zwillingsbruders, An'she der Sonne, leitet."}},faq={{q="Wer ist Elune?",a="Elune ist die primäre Gottheit der Nachtelfen, eine Mondgöttin, die mit Heilung, Natur, Frieden und der Weißen Dame – dem größeren Mond von Azeroth – in Verbindung gebracht wird. Sie wird weithin als eines der wenigen wahren göttlichen Wesen der Welt verehrt.",al={"was ist elune","elune lore","wer ist die mondgöttin"}},{q="Ist Elune jemals persönlich erschienen?",a="Elune wurde auf Azeroth noch nie in physischer Form beobachtet. Kaldorei-Handwerker stellen sie als strahlende, platinbekrönte Nachtelfenjungfrau mit langem silbernem Haar und leuchtenden Mondlichtaugen dar, obwohl ihre wahre kosmische Gestalt ein Rätsel bleibt.",al={"hat elune eine körperliche form angenommen","wie sieht elune aus"}},{q="Was ist die Nachtkriegerin?",a="Die Nachtkriegerin ist Elunes wildester Aspekt. Anstatt sanften Frieden und Heilung zu bieten, repräsentiert diese Manifestation ihren rechtschaffenen Zorn im Kampf und hebt die Geister mutiger, gefallener Krieger in den Nachthimmel, damit sie unter den Sternen reiten.",al={"elune nachtkriegerin","zorn von elune"}},{q="In welcher Beziehung steht Elune zu Cenarius?",a="Elune empfing Cenarius mit dem wilden Hirschhalbgott Malorne. Durch diese Verbindung erbte Cenarius sowohl die tiefe Liebe seiner Mutter zu den Lebewesen von Azeroth als auch die tiefe Verbindung seines Vaters zur natürlichen Wildnis und dem Smaragdgrünen Traum.",al={"ist elune die mutter von cenarius","eltern von cenarius"}},{q="Verehren die Tauren Elune?",a="Ja, wenn auch unter einem anderen Namen. Der Mythos der Tauren bezeichnet sie als Mu'sha, das sanfte linke Auge der Erdenmutter, das nachts an der Seite ihres solaren Bruders An'she über die Welt wacht.",al={"musha","tauren mondgöttin","wer ist musha"}},{q="Wer leitet die Verehrung von Elune in Kalimdor?",a="Die Schwesternschaft von Elune wird von der Hohepriesterin Tyrande Wisperwind vom Tempel des Mondes in Darnassus aus geleitet. Die Schwesternschaft dient als die primäre spirituelle und zivile Autorität unter den Nachtelfen.",al={"anführerin der priesterinnen von elune","schwesternschaft von elune"}}},fx={["33d35cb4"]={q="Woher stammt Elune?",a="Elunes wahre Ursprünge bleiben im Mythos verborgen, da sie eine der wenigen wahren Gottheiten ist, die in ganz Azeroth verehrt werden. Nach dem Glauben der Nachtelfen spürten die frühen Kaldorei ihre Anwesenheit zuerst, nachdem sie durch den Brunnen der Ewigkeit verwandelt wurden, wo sie glaubten, dass sie während des Tages ruhte. Uralte Legenden erzählen davon, wie sie den Großen Weißen Hirsch, Malorne, als ihren Gefährten nahm, um Cenarius hervorzubringen.",al={"ursprung von elune","woher stammt elune","geschichte von elune"}}},fp="5,351,14.533.0,26.509.0,17.482.0,13.218.0,34.233.0,26.247.0,33.238.0,28.183.0,43.200.0"}
P.entries["topic:emerald-dream"] = {n="Smaragdgrüner Traum",s="Der Smaragdgrüne Traum ist ein riesiges, sich ständig veränderndes Geisterreich, das Azeroth in seinem urzeitlichen Zustand darstellt, völlig unberührt von der Zivilisation. Bewacht vom Drachenaspekt Ysera und ihrem grünen Schwarm dient er als spirituelle Blaupause der Natur und als heilige Domäne, in der Druiden mit dem Kreislauf des Lebens Zwiesprache halten.",h="Der Smaragdgrüne Traum ist ein riesiges, sich ständig veränderndes Geisterreich, das Azeroth in seinem...",kw={"cenarius","träumen","druidenschlummer","smaragdgrüner traum","grüner drachenschwarm","wilde götter","ysera"},ang={["class:Druid"]="Der Smaragdgrüne Traum ist die heilige Quelle Eurer Macht, wo Euer Orden mit den Wilden Göttern Zwiesprache hält und das empfindliche Gleichgewicht des Großen Kreislaufs studiert.",["race:NightElf"]="Zehntausend Jahre lang schliefen Eure männlichen Druiden in heiligen Hügelgräbern, um an der Seite Yseras durch den Traum zu wandeln, während sie die Schildwachen und Priesterinnen zurückließen, um die wachende Welt zu bewachen.",["race:Tauren"]="Eure Druiden wandeln durch das Land der Träume, um mit den Geistern der Erde Zwiesprache zu halten, und sehen es als die ungezähmte Wiege der Schöpfung der Erdenmutter an."},sec={{t="Ein Spiegel des urzeitlichen Azeroths",b="Außerhalb der physischen Ebene existierend und dennoch an ihren Herzschlag gebunden, spiegelt der Smaragdgrüne Traum wider, wie Azeroth aussehen würde, hätten intelligente Wesen niemals seine Wälder gerodet oder Städte auf seinem Stein errichtet. Geformt während der uralten Ordnung der Welt, ist er eine sich stetig verändernde Wildnis aus unberührten Wäldern, grenzenlosen Ebenen und urzeitlichen Flüssen. Zeit und Entfernung haben im Traum kaum eine Bedeutung; Tage in der physischen Welt können sich im Geist wie Jahrzehnte anfühlen, und Orientierungspunkte verändern ihre Gestalt wie Mist vor den Augen der Sterblichen."},{t="Das Reich der Träumerin",b="Nach der Ordnung der Welt vertrauten die Titanen diese grüne Ebene Ysera der Träumerin an, dem großen Aspekt des grünen Drachenschwarms. Mit der Aufgabe betraut, die Entwicklung und den natürlichen Rhythmus von Azeroth zu leiten, verweilt Ysera in einer endlosen Trance und blickt durch eine verzauberte Traumsicht, die sowohl die wachende Welt als auch ihre gespiegelte Geisterebene wahrnimmt. Die grünen Drachen bewachen die seltenen, natürlichen Portale, die die physische Ebene mit dem Traum verbinden, und wahren ewige Wachsamkeit über die Grenze zwischen Schlaf und Erwachen."},{t="Druiden und das Träumen",b="Für sterbliche Druiden ist der Smaragdgrüne Traum der Quell ihres Handwerks. Durch das Kanalisieren von Naturmagie können Druiden ihren Geist in den Traum projizieren, während ihre körperlichen Leiber jahrelang oder gar jahrhundertelang sicher in Hügelgräbern ruhen. In diesem ungezähmten Reich halten sie Zwiesprache mit uralten Naturgeistern und den Wilden Göttern und erlangen tiefen Einblick in den Großen Kreislauf von Leben und Tod. Geübte Traumwandler lernen, physische Gesetze zu überwinden, während sie sich in ihrer Traumgestalt befinden, und durchqueren nach Belieben gewaltige Entfernungen oder gleiten durch feste Barrieren."}},faq={{q="Was ist der Smaragdgrüne Traum?",a="Der Smaragdgrüne Traum ist ein ätherisches, spirituelles Abbild von Azeroth. Er bewahrt eine unberührte, ungezähmte Blaupause der Welt, wie sie existierte, bevor zivilisierte Völker die Landschaft veränderten, und dient als Zufluchtsort für Naturgeister und den grünen Drachenschwarm.",al={"was ist der smaragdgrüne traum","lore des smaragdgrünen traums","der traum erklärt"}},{q="Wer herrscht über den Smaragdgrünen Traum?",a="Der Drachenaspekt Ysera wacht an der Seite des grünen Drachenschwarms über den Traum. Sie beherrscht ihn jedoch nicht vollkommen. Die wilde, zugrunde liegende Struktur des Traums folgt ihrem eigenen uralten Rhythmus und leitet eher Yseras Obhut, anstatt sich ihrem Willen zu beugen.",al={"wer kontrolliert den smaragdgrünen traum","herrscher des smaragdgrünen traums","ysera traum"}},{q="Wie betreten Sterbliche den Smaragdgrünen Traum?",a="Die meisten Sterblichen betreten ihn durch tiefen, druidischen Schlummer, indem sie ihren Geist in eine Traumgestalt projizieren, während ihre physischen Körper geschützt in Hügelgräbern ruhen. Es existieren überall auf Azeroth auch seltene, physische Portale, die vom grünen Drachenschwarm bewacht werden, wenngleich das Durchschreiten gefährlich ist.",al={"den smaragdgrünen traum besuchen","wie man den traum betritt","traumgestalt"}},{q="Kann man Dinge im Traum verändern?",a="Träumer können die örtliche Umgebung mit ihren Gedanken und ihrer Magie vorübergehend formen und verändern, doch diese Veränderungen sind nie von Dauer. Die urzeitliche Blaupause des Traums setzt sich unweigerlich wieder durch und tilgt jede dauerhafte Spur von Sterblichen.",al={"den smaragdgrünen traum verändern","kann man den traum verändern"}},{q="Warum schlafen Druiden jahrhundertelang?",a="Druiden begeben sich in einen langwierigen Winterschlaf, um durch den Smaragdgrünen Traum zu wandeln, mit Naturgeistern Zwiesprache zu halten, von den Wilden Göttern zu lernen und dem grünen Drachenschwarm dabei zu helfen, das Gleichgewicht der natürlichen Kreisläufe Azeroths über Generationen hinweg zu bewahren.",al={"warum druiden winterschlaf halten","druidenschlummer","in hügelgräbern schlafen"}},{q="Wohin gehen Tiergeister, wenn sie sterben?",a="Niemand kann dies mit Gewissheit sagen. Druiden ehren die Geister der Bestien als Teil des natürlichen Kreislaufs von Leben und Tod, doch was nach dem Tod aus jenen Geistern wird, bleibt ein Geheimnis.",al={"jenseits der tiere","geister der wilden götter","tiergeister"}}},fx={["8b438d74"]={q="Woher stammt der Smaragdgrüne Traum?",a="Seine Ursprünge sind geheimnisumwittert. Es heißt, der Traum wurde während der Ordnung Azeroths durch die Titanen als lebendiger Entwurf der natürlichen Welt geformt und Ysera und ihrem grünen Drachenschwarm anvertraut, damit sie über ihn wachen.",al={"ursprung des smaragdgrünen traums","wer erschuf den smaragdgrünen traum","wie wurde der smaragdgrüne traum erschaffen"}},["68609b47"]={q="Warum heißt er Smaragdgrüner Traum?",a="Er ist nach seinem üppigen, unberührten Grün und seiner spirituellen Natur benannt. Dieses grüne Reich, das Ysera und dem grünen Drachenschwarm anvertraut wurde, spiegelt ein unberührtes, blühendes Azeroth wider, das Sterbliche oft durch Träume und in Geistform betreten, obwohl auch physische Portale existieren.",al={"warum smaragdgrüner traum","bedeutung des namens smaragdgrüner traum"}}},fp="13,315,30.527.0,24.513.0,23.543.0,26.252.0,28.262.0,39.274.0,39.223.0,34.227.0,41.175.0"}
P.entries["topic:explorers-league"] = {fx={f9af476b={q="Warum findet Ihr überall auf der Welt Lager der Forscherliga?",a="König Magni richtete die zwergische Industrie auf Archäologie aus, nachdem er uralte Ruinen entdeckt hatte, die mit ihrem Erbe in Verbindung standen. Seitdem hat die Liga Kundschafter und Ausgräber überall dorthin entsandt, wo uralte Relikte der Titanen, geheimnisvolle Ruinen oder historische Geheimnisse vergraben liegen könnten. Ihr werdet ihre Ausgrabungsstätten verstreut in ganz Khaz Modan finden, tief in der Wildnis Kalimdors wie Dunkelküste und dem Brachland sowie in uralten unterirdischen Komplexen wie Uldaman.",al={"warum ist die forscherliga überall","standorte der ausgrabungsstätten der forscherliga","warum ist die liga in kalimdor"}}}}
P.entries["topic:first-war"] = {n="Erster Krieg",s="Der Erste Krieg war der verheerende fünfjährige Konflikt, in dem die Orc-Horde durch das Dunkle Portal hervorbrach und das menschliche Königreich von Sturmwind vollständig zerstörte. Hinter den Kulissen vom dämonisch besessenen Wächter Medivh und dem Hexenmeister Gul'dan inszeniert, endete er mit der Ermordung von König Llane Wrynn I. und der Flucht der menschlichen Überlebenden nach Norden gen Lordaeron.",h="Der Erste Krieg war der verheerende fünfjährige Konflikt, in dem die Orc-Horde durch das Dunkle Portal...",kw={"anduin lothar","black morass","blackhand","das dunkle portal","erster krieg","gul'dan","llane wrynn","medivh","abtei von nordhain","orgrim schicksalshammer"},ang={["class:Paladin"]="Das Abschlachten der Kleriker der Abtei von Nordhain während dieses Konflikts bewies, dass heiliger Glaube allein nicht ausreichte, um brutale Nahkämpfe zu überleben, was direkt die Gründung der Ritter der Silbernen Hand inspirierte.",["class:Warlock"]="Gul'dan und sein Schattenrat lenkten die Eroberungen der Horde durch Teufelszauberei und demonstrierten die immense, weltenerschütternde Zerstörung, die dämonische Pakte entfesseln können.",["faction:Alliance"]="Die völlige Vernichtung von Sturmwind diente als düstere Warnung, die die nördlichen Nationen davon überzeugte, ihre Isolation aufzugeben und sich in der Allianz von Lordaeron zu vereinen.",["race:Human"]="Der Erste Krieg stellt die dunkelste Stunde in der Geschichte von Sturmwind dar, als das Königreich fiel, sein König ermordet wurde und seine Überlebenden als mittellose Flüchtlinge über das Meer flohen.",["race:Orc"]="Für die Orcs markierte der Erste Krieg ihre erste blutige Eroberung auf Azeroth, gezeichnet vom Blutfluch von Mannoroth und den verborgenen Machenschaften von Gul'dans Schattenrat."},sec={{t="Öffnung des Portals",b="Vor dem Krieg genoss das Königreich Sturmwind nach dem Gnollkrieg lange Jahre des Friedens, beschützt von seinen Rittern und den Klerikern der Abtei von Nordhain. Diese Stabilität zerbrach, als der Wächter Medivh, der heimlich vom Dämonenfürsten Sargeras besessen war, den Orchexenmeister Gul'dan auf Draenor kontaktierte. Gemeinsam schufen sie das Dunkle Portal im sumpfigen Black Morass. Getrieben von Dämonenblut und dem langsamen Sterben ihrer Heimatwelt überquerte die Orc-Horde Azeroth in großer Zahl. Frühe Gerüchte taten die Invasoren als rachsüchtige Geister oder seltsame Ausläufer der Trolle ab, doch die Spähpatrouillen von Sir Anduin Lothar bestätigten schnell die Ankunft einer disziplinierten, blutrünstigen Armee."},{t="Der Krieg um Sturmwind",b="Offen angeführt von Kriegshäuptling Schwarzfaust und aus den Schatten von Gul'dans Schattenrat manipuliert, überrannte die Horde die südlichen Gefilde des Königreichs. Während ein Versuch der Orcs scheiterte, gegen die Gurubashi-Trolle ins Schlingendorntal vorzustoßen, erwies sich ihr Feldzug durch das Territorium der Menschen als katastrophal. Die Horde eroberte immer weitere Gebiete, bis nur noch der Wald von Elwynn unter menschlicher Kontrolle verblieb. Schwarzfaust unternahm einen ersten direkten Angriff auf Sturmwind, doch Sir Anduin Lothar schlug die Invasion mit einem brillanten, überraschenden Flankenkonter über das Meer zurück und bewahrte die Hauptstadt vorübergehend vor der Vernichtung."},{t="Verrat und der Fall",b="Der Krieg wendete sich, als Lothar und der junge Magier Khadgar Medivhs Verrat aufdeckten, Karazhan stürmten und den Wächter erschlugen. Medivhs Tod versetzte Gul'dan in ein Koma, was Orgrim Schicksalshammer die Gelegenheit bot, Schwarzfaust zu einem Mak'gora-Duell herauszufordern und zu töten. Indem er das absolute Kommando übernahm, zerschlug Doomhammer den Schattenrat und marschierte für eine zweite Belagerung auf Sturmwind. Während des Sturms ermordete die Halborc-Attentäterin Garona König Llane Wrynn I. in seiner eigenen Festung. Sturmwind wurde geplündert und zu Asche verbrannt, was Lothar dazu zwang, die überlebende Bevölkerung zu sammeln und nach Norden über das große Meer nach Lordaeron zu fliehen."}},faq={{q="Wie gelangten die Orcs überhaupt erst nach Azeroth?",a="Der Hexenmeister Gul'dan auf Draenor und der Wächter Medivh auf Azeroth arbeiteten mithilfe dunkler Teufelsmagie zusammen, um das dimensionale Gefüge zwischen den Welten zu durchbrechen, und errichteten das Dunkle Portal im Black Morass.",al={"wie orcs herkamen","ursprung dunkles portal","beginn erster krieg"}},{q="Warum halfen die anderen Menschenkönigreiche Sturmwind nicht?",a="Sturmwind stand allein da, weil die fernen nördlichen Königreiche die Gerüchte über grünhäutige Invasoren für weit hergeholte Übertreibungen oder lokale Streitigkeiten hielten. Erst als Sturmwind fiel und Lothar mit Booten voller Flüchtlinge in Lordaeron eintraf, schlossen sich die Könige des Nordens zusammen.",al={"warum keine allianz","half lordaeron","verstärkung für sturmwind"}},{q="Wer tötete König Llane?",a="König Llane Wrynn I. wurde in seiner eigenen Festung von Garona Halforcen ermordet – einer Gesandten, der der König vertraut hatte –, was der Moral der Menschen während der letzten Belagerung einen tödlichen Schlag versetzte.",al={"wer llane ermordete","tod könig llane","garona tötete könig"}},{q="Kämpften die Orcs im Ersten Krieg noch gegen andere Völker außer den Menschen?",a="Ja. Zu Beginn des Konflikts stieß die Horde nach Süden ins Schlingendorntal vor, wurde jedoch in einem heftigen Gefecht mit den Dschungeltrollen der Gurubashi zurückgeschlagen.",al={"kämpften orcs gegen trolle","gurubashi im ersten krieg","andere völker erster krieg"}},{q="Wer gewann den Ersten Krieg?",a="Die Orc-Horde errang einen vollständigen Sieg. Das Königreich Sturmwind wurde dem Erdboden gleichgemacht, König Llane wurde getötet und die überlebende Menschenbevölkerung war zu einer massiven Evakuierung über das Meer nach Norden gen Lordaeron gezwungen.",al={"sieger erster krieg","wer gewann wc1","ausgang erster krieg"}},{q="Was geschah mit Kriegshäuptling Schwarzfaust?",a="Als Gul'dan nach Medivhs Tod handlungsunfähig war, forderte Orgrim Schicksalshammer Schwarzfaust zum Mak'gora – einem Ehrenduell – heraus, erschlug ihn und riss die Führung der Horde an sich.",al={"wie blackhand starb","orgrim schicksalshammer herausforderung","kriegshäuptling getötet"}}},fx={a8364e3f={q="Was war der Erste Krieg?",a="Der Erste Krieg, auch bekannt als der erste Große Krieg, war der verheerende fünfjährige Konflikt zwischen der orcischen Horde und dem Menschenkönigreich Sturmwind. Geheim orchestriert von dem Hexenmeister Gul'dan und dem korrumpierten Wächter Medivh, überschritten die Orcs von ihrer sterbenden Heimatwelt Draenor durch das Dunkle Portal das Schwarzmoor. Was als verstreute Grenzscharmützel begann, eskalierte zu einer umfassenden Invasion, die die Städte des Königreichs zerstörte, in der Ermordung von König Llane Wrynn gipfelte und mit der totalen Plünderung von Sturmwind endete.",al={"was ist der erste krieg","zusammenfassung des ersten krieges","der erste große krieg"}},bf3015cc={q="Warum wird er Erster Krieg genannt?",a="Er wird Erster Krieg genannt, weil er den allerersten Zusammenstoß zwischen der Menschheit und der orcischen Horde auf Azeroth markierte. Vor der Öffnung des Dunklen Portals hatten Menschen noch nie Orcs gesehen und genossen nach dem Gnollkrieg Generationen relativen Friedens. Der Konflikt erschütterte diese Isolation, und da kurz darauf eine zweite große Konfrontation folgte, als die Horde in die nördlichen Menschenkönigreiche einfiel, bezeichnen Historiker und Überlebende diesen anfänglichen Kampf um Sturmwind als Erster Krieg.",al={"warum erster krieg","bedeutung des namens erster krieg","warum wird er erster krieg genannt"}}},fp="9,374,21.668.0,21.602.0,22.608.1,51.194.0,51.273.0,22.177.0,58.154.0,22.191.0,36.173.0"}
P.entries["topic:frostmane-tribe"] = {fx={a2fffb42={q="Warum sind die Frostmane-Trolle in Dun Morogh?",a="Die Frostmane betrachten die schneebedeckten Gipfel von Dun Morogh als ihre angestammte Heimat. Lange bevor Eisenschmiede an die Macht kam, herrschten ihre Vorfahren über diese Berge, bis zwergische Armeen ihr Imperium zerschlugen und sie in die frostigen Hügel drängten. Heute dienen verstreute Lager wie Frostmane Hovel und Schimmergrat als Stützpunkte für ihren andauernden Guerillakrieg, um ihr verlorenes Territorium von den Zwergen zurückzuerobern.",al={"warum sind frostmane in dun morogh","warum sind trolle in dun morogh","frostmane dun morogh grund"}}}}
P.entries["topic:furbolg"] = {n="Furbolg",s="Furbolgs sind ein wuchtiges, zurückgezogen lebendes Volk von Bärenmenschen, das im nördlichen Kalimdor beheimatet ist und über Jahrtausende im Einklang mit der Natur und den Nachtelfen lebte. Seit dem Dritten Krieg haben dämonische Verderbnis und die Reste von Teufelsmagie fast jeden Stamm in einen rasenden Wahnsinn getrieben. Heute sind aus einstigen Freunden bösartige, territoriale Raubtiere geworden, und nur eine winzige Handvoll Stämme bewahrt noch ihren Verstand.",h="Furbolgs sind ein wuchtiges, zurückgezogen lebendes Volk von Bärenmenschen, das im nördlichen Kalimdor...",kw={"eschental","verderbnis","deadwood","foulweald","furbolg","gnarlpine","thistlefur","timbermaw","ursoc","winterfall"},ang={["class:Druid"]="Druiden betrauern die Bärenmenschen als geistesverwandte Anhänger Ursocs, deren Verbindung zur Natur durch die Teufelsverderbnis als Waffe missbraucht wurde, was die Unruhen der Stämme zu einem direkten Symptom für das allgemeine Siechtum des Landes macht.",["faction:Horde"]="Die Horde betrachtet die feindseligen Stämme des Eschentals als territoriale Hindernisse und räumt aggressive Gruppen wie die Foulweald und Thistlefur aus dem Weg, um Versorgungsrouten und Außenposten am Rande des Waldes zu sichern.",["race:NightElf"]="Für die Nachtelfen ist der Untergang der Furbolgs eine herzzerreißende Tragödie. Stämme, die zehntausend Jahre lang treue Verbündete des Waldes waren, sind zu wilden Raubtieren geworden, die Astranaar und die heiligen Grabhügel von Teldrassil bedrohen."},sec={{t="Alte Verbundenheit",b="Furbolgs sind ein altes Volk aus Kalimdor, das seit Langem den Wildgott Ursoc verehrt. Während des Krieges der Ahnen vor zehntausend Jahren vereinigten sich die Stämme unter Häuptling Unng Ak, um an der Seite der Nachtelfen und Tauren gegen die erste dämonische Invasion zu kämpfen. Nach der Großen Zerschlagung wählten sie die Abgeschiedenheit tief in den nördlichen Wäldern und pflegten friedliche Beziehungen zu den Druiden der Nachtelfen und den Waldwächtern, während sie in einfacher Harmonie mit der Wildnis lebten."},{t="Die Geißel des Wahnsinns",b="Der Dritte Krieg erschütterte das friedliche Dasein der Furbolgs. Der Durchzug der Brennenden Legion durch Kalimdor hinterließ bleibende Spuren von Teufelsverderbnis im Boden und im Blätterdach des Eschentals und des Teufelswaldes. Als einfältiges und tief mit dem Land verbundenes Volk nahmen die Bärenmenschen diese Verderbnis direkt auf. Ihre weisen Schamanen wurden gestürzt oder zum Schweigen gebracht durch blutrünstige Brandstifter, die Teufelsmoos, dunkle Talismane und verderbte Alchemie nutzten und so friedliche Sammler in tollwütige Plünderer verwandelten, die nun Reisende und Siedlungen der Nachtelfen bei Sichtkontakt angreifen."},{t="Die ungebrochene Linie",b="Im gesamten nördlichen Kalimdor ist fast jeder größere Stamm erlegen: die Gnarlpine auf Teldrassil, die Blackwood der Dunkelküste, die Thistlefur und Foulweald im Eschental sowie die Deadwood und Winterfall im nördlichen Hochland. Doch einige halten die Stellung. Tief in den befestigten Tunneln, die den Teufelswald, Winterquell und die Mondlichtung verbinden, bewahrt der Stamm der Timbermaw verbissen seinen Verstand. Misstrauisch und isoliert verteidigen die Timbermaw ihre Feste gegen ihre wahnsinnigen nördlichen Artgenossen, in der verzweifelten Hoffnung, das zu bewahren, was von ihrer unverdorbenen Kultur übrig ist."}},faq={{q="Warum greifen die Furbolgs jeden an?",a="Die Nachwirkungen des Dritten Krieges hinterließen in den nördlichen Wäldern Kalimdors bleibende dämonische Verderbnis. Da Furbolgs tief mit der Natur verbunden sind, sickerte dieser Makel in ihre Gedanken ein, trieb ihre Stämme in einen paranoiden, gewalttätigen Wahnsinn und ersetzte ihre friedlichen Ältesten durch aggressive Häuptlinge.",al={"warum sind furbolgs feindselig","furbolg wahnsinn","warum wurden furbolgs wahnsinnig"}},{q="Waren Furbolgs schon immer Feinde der Nachtelfen?",a="Nein. Über Tausende von Jahren waren Furbolgs und Nachtelfen friedliche Nachbarn und enge Verbündete. Sie kämpften während des Krieges der Ahnen Schulter an Schulter gegen die Brennende Legion, und die Druiden der Nachtelfen pflegten freundschaftliche Beziehungen zu den Stammessiedlungen, bis die jüngste Welle des Wahnsinns überhandnahm.",al={"geschichte von furbolgs und nachtelfen","mochten furbolgs die nachtelfen"}},{q="Gibt es noch Furbolgs, die freundlich sind?",a="Ja. Der Stamm der Timbermaw unterhält eine unverdorbene Enklave innerhalb der Holzschlundfeste, dem Tunnelsystem an der Wegkreuzung zwischen dem Teufelswald, der Mondlichtung und Winterquell. Obwohl sie gegenüber Außenstehenden zutiefst misstrauisch sind, tolerieren sie Reisende, die ihre Feindseligkeit gegenüber den verderbten Deadwood- und Winterfall-Stämmen unter Beweis stellen.",al={"freundliche furbolgs","guter furbolgstamm","unverdorbene furbolgs"}},{q="Was stimmt mit den Furbolgs auf Teldrassil nicht?",a="Der Stamm der Gnarlpine auf Teldrassil ist dem Einfluss von Teufelsmoos erlegen, einer heimtückischen Verderbnis, die sich durch die Äste des Weltenbaums ausbreitet. Unter Häuptling Ursal the Mauler gaben die verderbten Gnarlpine ihre traditionellen Dörfer auf und überrannten heilige Stätten wie den Grabhügel von Ban'ethil und Sternenhauch.",al={"furbolgs auf teldrassil","gnarlpine corruption"}},{q="Wer steckt hinter der Verderbnis der Winterfall in Winterquell?",a="Die Winterfall werden insgeheim von einem Satyr namens Xandivious manipuliert, der sich in der Höhle ihres Häuptlings versteckt hält. Der Wahnsinn des Stammes wird durch Feuerwasser der Winterfelle genährt, das aus verderbten Materialien im Deadwood-Kessel des Teufelswaldes gebraut und durch die Gebirgspässe nach Norden transportiert wird.",al={"hintergrund der winterfall","wer verdarb die winterfall","ursprung von feuerwasser der winterfelle"}},{q="Können verderbte Furbolgs jemals geheilt werden?",a="Die Wächterinnen und Druiden der Nachtelfen haben versucht, einzelne Stämme mithilfe von Mondbrunnenwasser und heiligen Relikten zu reinigen, aber eine flächendeckende Heilung hat sich als nahezu unmöglich erwiesen. Da Satyrn und dunkle Relikte die Verderbnis aktiv vorantreiben, bleibt den Verteidigern oft keine andere Wahl, als feindselige Gruppen auszuschalten, um Siedlungen zu schützen.",al={"furbolgs heilen","können furbolgs gerettet werden"}}},fx={ec2e8979={q="Was sind Furbolgs?",a="Furbolgs sind ein Volk wuchtiger, bärenähnlicher Humanoide, die in den uralten Wäldern des nördlichen Kalimdor beheimatet sind. Traditionell einfach gestrickt, tief spirituell und zurückgezogen lebend, existierten sie Jahrtausende lang friedlich im Einklang mit der Natur. Obwohl sie von kräftiger Statur und zu heftigen Kämpfen fähig waren, besaßen sie keinen natürlichen Hang zu Krieg oder Grausamkeit, bis kürzliche Tragödien ihren Verstand vernebelten.",al={"was ist ein furbolg","wer sind furbolgs","furbolg-volk"}},["195c4c39"]={q="Woher stammen die Furbolgs?",a="Furbolgs sind ein uraltes Volk aus Kalimdor. Während des Krieges der Ahnen vor zehntausend Jahren standen Furbolg-Rudel unter der Führung von Unng Ak Seite an Seite mit Nachtelfen, Tauren und Irdenen gegen die Brennende Legion, was ein Bündnis festigte, das über Generationen friedlich Bestand hatte.",al={"ursprung der furbolgs","geschichte der furbolgs","woher stammen furbolgs"}},["11e5052c"]={q="Wer führt die Furbolgs an?",a="Furbolgs haben keinen einzigen übergeordneten Anführer oder Herrscher. Stattdessen sind sie in unabhängige Stämme unterteilt, die jeweils von ihren eigenen Häuptlingen, Schamanen und Ältesten angeführt werden. In jüngster Zeit wurden viele der weisen Ältesten dieser Stämme gestürzt, getötet oder durch aggressive Brandstifter und korrupte Häuptlinge ersetzt, die ihre verrückten Artgenossen in die Gewalt führen.",al={"anführer der furbolgs","wer herrscht über die furbolgs","furbolg-könig"}}},fp="7,401,15.458.0,22.530.0,17.535.0,40.302.0,48.303.0,46.297.0,46.313.0,63.277.1,37.313.0"}
P.entries["topic:gnoll"] = {n="Gnoll",s="Gnolle sind ein wildes, hyänenartiges Volk humanoider Plünderer und Räuber, die über die gesamten Östlichen Königreiche und Kalimdor verstreut sind. Bekannt für ihre bösartigen internen Kämpfe, ihre brutale Stärke und ihre tierische Gerissenheit, überleben sie durch das Plündern von Siedlungen, das Schlachten von Wildtieren und Hinterhalte gegen unvorsichtige Reisende. Wenn sie nicht aufgehalten werden, stellen ihre weitläufigen Rudel und Kriegsherren eine ständige Bedrohung für Grenzortschaften und Handelsstraßen gleichermaßen dar.",h="Gnolle sind ein wildes, hyänenartiges Volk humanoider Plünderer und Räuber, die über die gesamten Östlichen...",kw={"gnoll","hogger","mosshide","mudsnout","palemane","riverpaw","rot hide","shadowhide","woodpaw"},ang={["faction:Alliance"]="Marschälle der Allianz in ganz Elwynn, Westfall, dem Rotkammgebirge und dem Sumpfland verlassen sich stark auf freiberufliche Helden, um die vordringenden Gnollpopulationen auszudünnen.",["race:Human"]="Für die Menschen von Sturmwind sind Gnolle ein uralter Feind, der einst das Kernland des Königreichs niederbrannte; heute bedrohen Rudel wie die Riverpaw und Shadowhide die verwundbaren Grenzstraßen des Königreichs.",["race:Tauren"]="Der Palemane-Stamm in Mulgore behandelt das Land mit rücksichtsloser Grausamkeit, was junge Tauren-Krieger dazu zwingt, sie zurückzudrängen, um das Gleichgewicht der Ebenen zu bewahren.",["race:Undead"]="Die Verlassenen betrachten Gnolle entweder als Ärgernis oder als Ressource: Die Mudsnout kultivieren in Hillsbrad wiederherstellende Pilze, während Sylvanas zuvor nördliche Rudel durch Banshee-Besessenheit versklavte."},sec={{t="Hyänen der Wildnis",b="Gnolle sind etwas kleiner als der durchschnittliche Mensch, besitzen aber explosive physische Kraft. Sie sind zweibeinige Hyänenwesen, die für ihre spitzen Zähne, ihr dickes Fell und ihr markantes bellendes Lachen bekannt sind. Obwohl sie durchaus aufrecht gehen können, fallen sie oft auf alle Viere, um schnell durch das Unterholz zu laufen oder Beute anhand ihres Geruchs aufzuspüren. Die Gnollkultur schätzt rohe körperliche Dominanz über alles. Sie organisieren sich in zerstrittenen Rudeln, die von dem stärksten und grausamsten Alpha angeführt werden, und geben sich erst geschlagen, wenn sie von einer überlegenen Macht zur Unterwerfung gezwungen werden."},{t="Der Gnollkrieg",b="Obwohl sie normalerweise durch kleinliche Streitigkeiten gespalten sind, führten vereinte Gnolle einst einen offenen Krieg gegen das Königreich Sturmwind. Sturmwinds Armeen siegten in diesem Gnollkrieg, und das Königreich genoss danach einen dauerhaften Frieden, bis die Orcs durch Das Dunkle Portal kamen."},{t="Plünderer der südlichen Königreiche",b="Im Süden wüten Gnollrudel, da Sturmwinds volle militärische Macht fehlt. Im Wald von Elwynn und Westfall überfällt das Rudel der Flusspfoten – angeführt von dem berüchtigten Hogger – Gehöfte und zwingt unterworfene Kobolde dazu, nach Gold zu graben, während sie heimlich mit der Bruderschaft der Defias zusammenarbeiten. Weiter östlich im Rotkammgebirge stiehlt das Rudel der Rotkammgnolle Pferde vor Seenhain und sabotiert Brückenreparaturen, während der Schattenfellklan im Galardelltal dem dunklen Willen des abtrünnigen Zauberers Morganth dient."},{t="Seuche und Territorium",b="Die Gnollbedrohung ist nicht auf den menschlichen Süden beschränkt. Im nördlichen Lordaeron lässt der Nekromant der Geißel, Thule Ravenclaw, untote Rot Hide-Gnolle auferstehen, um in Tirisfal und im Silberwald Leichen auszugraben. In der Nähe von Hillsbrad ernten die Mudsnout üble, giftige Blüten zwischen zerstörten Gehöften. Jenseits Das große Meer in Kalimdor schlachtet das Palemane-Rudel Wild in ganz Mulgore ab, trotz der Bemühungen der Tauren, Frieden zu schließen, während die Woodpaw von Feralas einen verzweifelten, rasenden Krieg gegen vordringende Silithidenschwärme führen."}},faq={{q="Was genau ist ein Gnoll?",a="Gnolle sind hyänenartige humanoide Fleischfresser, die für ihre gewalttätige Natur, ihre körperliche Ausdauer und ihre geringe Gerissenheit bekannt sind. Sie leben in nomadischen oder halbpermanenten Lagern und überleben hauptsächlich durch Plünderung, Jagd und Aas.",al={"was sind gnolle","gnollvolk","sind gnolle hyänen"}},{q="Warum bilden Gnolle kein richtiges Königreich?",a="Gnolle sind extrem streitlustig und von unmittelbarer Hierarchie getrieben. Ohne einen außergewöhnlichen und tyrannischen Kriegsherren, der sie diszipliniert, zerfallen die Rudel unweigerlich in blutige territoriale Fehden, was langfristige Organisation oder zivilen Fortschritt verhindert.",al={"warum sind gnolle verstreut","gnollreich","gnolleinigkeit"}},{q="Was war der Gnollkrieg?",a="Lange vor dem Erster Krieg führten vereinte Gnollrudel Krieg gegen das Königreich Sturmwind. Die Armeen des Königreichs siegten, und Sturmwind genoss danach einen dauerhaften Frieden, bis die Orcs durch Das Dunkle Portal kamen.",al={"gnollkrieg sturmwind"}},{q="Warum arbeiten Gnolle mit der Bruderschaft der Defias zusammen?",a="Das Riverpaw-Rudel in Westfall und im Wald von Elwynn arbeitet mit der Bruderschaft der Defias im Austausch für Waffen, Koordination und geteilte Beute zusammen. Die Banditen nutzen die Gnolle als rohe Muskelkraft, um Ackerland zu überrennen und Sturmwinds schwindende Garnisonen abzulenken.",al={"gnollallianz defias","riverpaw defias","hogger defias"}},{q="Sind die Rot Hide-Gnolle am Leben?",a="Nein. Die Rot Hide-Gnolle, die in Tirisfal und im Silberwald umherstreifen, sind untote Sklaven. Sie gehorchen Thule Ravenclaw, einem verbannten menschlichen Nekromanten, der die Insel Fenris als Stützpunkt nutzt, um Leichen für die Geißel zu sammeln.",al={"rot hide untote","gnolle silberwald","gnolle insel fenris"}},{q="Warum bekämpfen Tauren die Palemane-Gnolle?",a="Als die Tauren sich in Mulgore ansiedelten, versuchten sie, mit dem dort heimischen Palemane-Rudel zu koexistieren und zu kommunizieren. Die Gnolle wiesen alle friedlichen Gesten zurück, schlachteten die Wildtiere der Ebenen ohne Zurückhaltung ab und bedrohten die Dörfer der Tauren.",al={"palemane mulgore","tauren und gnolle","warum palemane töten"}}},fx={["06f85769"]={q="Warum sind Gnolle Reisenden gegenüber feindselig?",a="Gnolle sind brutale, räuberische Aasfresser, die andere Völker hauptsächlich als Beute, Eindringlinge oder Quellen der Plünderung betrachten. Kriegerisch und von simpler tierischer List getrieben, schätzen sie körperliche Stärke über alles andere und respektieren kaum etwas anderes. Da sie stark auf Überfälle, Entführungen und den Diebstahl von Vieh aus nahegelegenen Siedlungen angewiesen sind, greifen Gnollrudel reflexartig jeden an, der in ihr Territorium wandert oder ihre Jagdgründe durchquert.",al={"warum greifen gnolle an","sind gnolle feindselig","gnolle greifen bei sichtkontakt an"}},["15503234"]={q="Wer führt die Gnolle an?",a="Gnolle haben keinen vereinten Anführer oder zentralen König. Stattdessen sind sie in verstreute, sich zankende Rudel und Stämme auf beiden Kontinenten zersplittert. In jedem Clan fällt die Führung dem Alpha oder Rudelführer zu – dem größten, brutalsten Tier, das in der Lage ist, Rivalen zur Unterwerfung zu prügeln. Zu den bekannten Kriegsherren zählen Hogger von den Strompfoten im Wald von Elwynn, Rudelführer Jault im Rotkammgebirge und Leutnant Fangore bei den Schattenhäuten.",al={"wer ist anführer der gnolle","gnoll-könig","gnoll-rudelführer"}},["1c9639a8"]={q="Woher stammen Gnolle?",a="Gnolle sind ein uraltes Volk hyänenartiger Humanoide, deren Ursprünge in der Geschichte verloren sind. Sie bewohnen seit Jahrtausenden sowohl Kalimdor als auch die Östlichen Königreiche, lange vor dem Aufstieg moderner Nationen. Frühe menschliche Siedler trafen vor Tausenden von Jahren in Tirisfal auf bösartige Gnollrudel, und Trollstämme bekämpften sie in den südlichen Wäldern. Wo immer wilde Landstriche existieren, haben sich Gnolle eine wilde Existenz erkämpft.",al={"ursprung der gnolle","woher stammen gnolle","geschichte der gnolle"}}},fp="5,419,19.509.0,13.250.0,32.506.1,24.489.0,24.207.0,39.246.0,23.209.0,51.246.1,30.216.0,40.236.0"}
P.entries["topic:goblin"] = {n="Goblin",s="Goblins sind kleine, gerissene Humanoide, die von der Insel Kezan stammen und in ganz Azeroth für ihr unermüdliches Streben nach Profit, explosive Ingenieurskunst und aggressive Handelskartelle bekannt sind. Während die meisten eine strikte Neutralität wahren, um den Handel zwischen der Allianz und der Horde zu maximieren, hinterlassen Söldner- und Halsabschneidergruppen wie die Venture Company und das Steamwheedle Cartel einen bleibenden Eindruck in jedem Winkel der Welt.",h="Goblins sind kleine, gerissene Humanoide, die von der Insel Kezan stammen und in ganz Azeroth für ihr...",kw={"beutebucht","kartell","die todesminen","ingenieurskunst","gadgetzan","goblin","kezan","steamwheedle","venture company"},ang={["faction:Alliance"]="Die Behörden der Allianz stehen der Neutralität der Goblins zutiefst misstrauisch gegenüber, da sie sich gut an deren Söldnerdienste erinnern, die der alten Horde während des Zweiten Krieges Kriegsschiffe und Pioniere lieferten.",["faction:Horde"]="Während Thralls Horde Goblin-Mechaniker einsetzt und mit neutralen Knotenpunkten handelt, bleibt die Erinnerung an die Söldnerverträge zwischen Orgrim Schicksalshammer und Handelsprinz Steamwheedle frisch.",["profession:Engineering"]="Die Ingenieurskunst der Goblins priorisiert extreme Sprengkraft, offensive Gadgets und risikoreiche mechanische Apparaturen, was in starkem Kontrast zu den präzisen, defensiven Entwürfen der Gnome steht.",["profession:Mining"]="Bergbau befeuert die Industrie und den Handel der Goblinkartelle, und sie bleiben erbitterte Verteidiger wertvoller Mineralienvorkommen in ganz Kalimdor und den Östlichen Königreichen."},sec={{t="Kartelle von Kezan",b="Goblins stammen von der Insel Kezan in den südlichen Meeren, wo sich ihre Gesellschaft vor langer Zeit in konkurrierende Wirtschaftssyndikate aufteilte, die als Kartelle bekannt sind. Anstatt eigene Königreiche oder Armeen aufzubauen, kanalisierten Goblinausführer ihre Ambitionen in halsabschneiderischen Merkantilismus, flüchtige Ingenieurskunst und industrielle Unternehmungen, die heute jeden Winkel der Welt erreichen."},{t="Söldner und Merkantilismus",b="Während des Zweiten Krieges verbündete sich Handelsprinz Steamwheedle mit der Horde von Orgrim Schicksalshammer und lieferte Karten, Belagerungstechnik und Flottenbau-Expertise im Austausch für die erbeuteten Schätze von Sturmwind. Nach der letztendlichen Niederlage der Horde lernten die Kartelle, dass offene Bündnisse sie lukrative Märkte kosteten. In der modernen Ära beanspruchen die großen Kartelle offizielle Neutralität und unterhalten geschäftige Handelshäfen wie Beutebucht im Schlingendorntal und Gadgetzan in der Wüste Tanaris. Hier kreuzen sich die Wege von Reisenden der Allianz und der Horde, ohne dass die Klingen gezogen werden – solange die Hafenwachen für Frieden sorgen."},{t="Angeheuerte Kräfte und Industrie",b="Die primäre Loyalität eines Goblins gehört dem Gold, und viele agieren außerhalb der neutralen Kartelle als angeheuerte Spezialisten oder rücksichtslose Unternehmensbarone. Die Venture Company betreibt hemmungslose Abholzung und Ressourcenausbeutung auf allen Kontinenten, ohne Rücksicht auf die lokale Bevölkerung. Andernorts verkaufen geschickte Konstrukteure ihre Talente direkt an kriminelle Organisationen: Tief in den Todesminen beaufsichtigen Gobliningenieure wie Sneed, Gilnid und Kapitän Grünhaut Schmelzöfen und Schiffbauer, die ein massives, gepanzertes Schlachtschiff für die Bruderschaft der Defias konstruieren."}},faq={{q="Sind Goblins der Allianz oder der Horde zugehörig?",a="Weder noch. Die primären Handelssyndikate, einschließlich des Steamwheedle Cartel, halten an strikter Neutralität fest, um frei mit beiden Seiten handeln zu können. Einzelne Goblins und Privatunternehmen vermieten ihre Dienste gerne an die Horde, die Allianz oder Dritte wie die Bruderschaft der Defias, wenn der Preis stimmt.",al={"gehören goblins zur horde","goblin fraktion","für wen kämpfen goblins"}},{q="Warum neigen Goblin-Erfindungen so sehr dazu, zu explodieren?",a="Die Ingenieurskunst der Goblins schätzt rohe Kraft, Eile, günstige Produktion und hohe Sprengkraft mehr als strukturelle Sicherheit, daher liefern ihre Geräte spektakuläre Ergebnisse und spektakuläre Explosionen zu annähernd gleichen Teilen.",al={"goblin ingenieurswesen gefährlich","warum explodieren goblin maschinen","goblin vs gnom technik"}},{q="Was ist das Steamwheedle Cartel?",a="Das Steamwheedle Cartel ist das einflussreichste merkantile Kartell, das auf dem Festland operiert. Sie verwalten wichtige neutrale Handelshäfen und kontinentübergreifende Verkehrsknotenpunkte, darunter Beutebucht im südlichen Schlingendorntal und Gadgetzan in der Wüste Tanaris.",al={"steamwheedle cartel","wer regiert beutebucht","goblin häfen"}},{q="Was ist die Venture Company?",a="Die Venture Company ist ein rücksichtsloser, von Goblins geführter Industriekonzern, der für aggressive Abholzung, Tagebau und Ölgewinnung berüchtigt ist. Im Gegensatz zum Steamwheedle Cartel operieren sie ohne Rücksicht auf lokale Gesetze oder das ökologische Gleichgewicht und geraten oft gewaltsam mit der einheimischen Bevölkerung aneinander.",al={"venture company","wer ist die venture company","was ist die venture company"}},{q="Warum arbeiten Goblins in den Todesminen mit den Defias zusammen?",a="Die Bruderschaft der Defias verfügte über reichlich geplündertes Gold und Roherz aus den Minen von Mondbruch, was es ihnen ermöglichte, hochkarätige Goblinspezialisten anzuheuern. Handwerker wie Sneed, Gilnid und Kapitän Grünhaut wurden unter Vertrag genommen, um das schwere Schmelzen zu beaufsichtigen und das gepanzerte Schlachtschiff für Edwin van Cleef zu bauen.",al={"todesminen goblins","warum sind goblins in den todesminen","gilnid sneed todesminen"}},{q="Wo ist die Heimat der Goblins?",a="Goblins stammen von der tropischen Insel Kezan in den südlichen Meeren. Dort entstanden ihre großen Handelskartelle, die ein Imperium des Handels und des Industriesmogs aufbauten.",al={"woher kommen goblins","goblin heimatinsel","kezan"}}},fx={d8aa07c2={q="Was sind Goblins?",a="Goblins sind kleine, grünhäutige Humanoide, die überall in Azeroth für ihre ausgeprägte kaufmännische Schlitzohrigkeit, ihre Meisterschaft in volatiler Technologie und ihre Vorliebe für Sprengstoffe bekannt sind. Angetrieben von einem unersättlichen Profitgier betrachten sie fast jedes Unterfangen durch die Brille von Handel, Bergbau und Industrie. Obwohl sie körperlich klein sind, machen sie ihre Genialität und ihre Bereitschaft, rohe Ingenieurskunst zu bewaffnen, sowohl zu gefürchteten als auch unberechenbaren Gegnern.",al={"was ist ein goblin","wer sind goblins","goblin-volk"}},d5109913={q="Wer führt die Goblins an?",a="Goblins haben keinen einzelnen Herrscher. Stattdessen ist ihre Gesellschaft in konkurrierende Handelskartelle und Syndikate unterteilt, von denen jedes von einem wohlhabenden Handelsprinzen oder einem exekutiven Mogul befehligt wird. Prominente Persönlichkeiten wie Handelsprinz Steamwheedle führen riesige Handelssyndikate, während lokale Barone und Aufseher – wie Baron Revilgaz in Beutebucht – den Betrieb leiten und in den einzelnen Häfen und Siedlungen für Ordnung sorgen.",al={"goblin-anführer","wer hat bei goblins das sagen","goblin-herrscher"}},["68045a57"]={q="Warum sind manche Goblins Reisenden gegenüber feindselig?",a="Während große Häfen wie Beutebucht und Gadgetzan eine strikte bewaffnete Neutralität aufrechterhalten, um den Handel zu schützen, gehören viele Goblins zu skrupellosen Organisationen, die Reisende als Hindernisse oder Konkurrenten betrachten. Unternehmen wie die Venture Company verteidigen ihre illegalen Holzfällerei- und Bergbauansprüche aggressiv mit roher Gewalt, während sich andere Goblins bereitwillig als Mercenaries, Techniker oder Piraten an kriminelle Fraktionen verdingen.",al={"feindselige goblins","warum greifen goblins an","sind goblins feinde"}},a6996125={q="Woher stammen die Goblins und was ist ihre Geschichte?",a="Goblins stammen von der Insel Kezan in den südlichen Meeren, wo sich ihre Gesellschaft in rivalisierende Handelskartelle aufspaltete. Anstatt eigene Königreiche oder Armeen aufzubauen, richteten die Kartelle ihre Energie auf Wirtschaftskriege, Handel und weltweite technologische Unternehmen.",al={"goblin-geschichte","ursprung der goblins","woher kommen goblins"}}},fp="6,432,16.356.0,28.594.0,24.537.1,51.303.0,48.209.0,32.251.0,28.296.0,63.282.1,29.173.0"}
P.entries["topic:grimtotem-tribe"] = {n="Stamm der Grimmtotem",s="Der Stamm der Grimmtotem ist ein aggressiver, erbittert traditionalistischer Taurenklan, der sich weigert, Thralls Horde formell die Treue zu schwören. Sie sind an ihren dunklen Fellen und ihrer grimmigen Kriegsbemalung zu erkennen und streben danach, Kalimdor von fremden Rassen zu säubern und sich ihre angestammten Länder mit allen notwendigen Mitteln zurückzuholen. Während ihre Matriarchin, die Ältestengreisin Magatha Grimmtotem, auf dem Donnerfels residiert und regionale Politik betreibt, überfallen ihre Sippenmitglieder aktiv Siedlungen in ganz Kalimdor.",h="Der Stamm der Grimmtotem ist ein aggressiver, erbittert traditionalistischer Taurenklan, der sich weigert...",kw={"düsterwolkengipfel","ältestengreisin","freiwindposten","grimtotem","magatha","taurenstamm","donnerfels"},ang={["faction:Alliance"]="Die Grimmtotem verachten jeden, der nach Kalimdor kommt, und greifen Händler der Allianz sowie Enklaven der Nachtelfen wahllos an.",["faction:Horde"]="Verwechselt ihre schwarzen Felle nicht mit Verbündeten: Draußen im Brachland, in den Bergen und Sümpfen von Kalimdor werden Grimmtotem-Krieger Späher der Horde bei Sichtkontakt aus dem Hinterhalt angreifen.",["race:Tauren"]="Die Grimmtotem sind eine offene Schande für die Bluthufe und andere Stämme; obwohl Cairne ihnen im Namen der Einheit der Tauren Unterschlupf in Donnerfels gewährt, droht ihre Kriegstreiberei genau diese Einheit zu zerreißen.",["race:Undead"]="Magatha Grimmtotem ist eine der wenigen Anführer der Tauren in Donnerfels, die offen mit den Verlassenen paktiert und gemeinsam mit Spezialisten der Königlichen Apothekervereinigung Forschung an exotischen Seuchen vermittelt."},sec={{t="Ein Volk für sich",b="Im Gegensatz zu ihren friedlichen Vettern, die die Erdenmutter durch Verehrung ehren, glauben die Grimmtotem, dass Kalimdor ausschließlich den Tauren gehört. Von Jugend an werden sie nicht in der geduldigen Harmonie der Großen Jagd ausgebildet, sondern in Rücksichtslosigkeit, Heimlichkeit und tödlichem Kampf. Sie hegen immense Verachtung für die anderen Rassen, die sich auf ihren alten Böden niedergelassen haben. Obwohl Cairne Bluthuf sie in Donnerfels willkommen geheißen hat, um alle Tauren zu vereinen, ist der Klan der Grimmtotem der einzige bedeutende Stamm, der sich niemals formell Thralls Horde angeschlossen hat, und verfolgt seine eigene isolierte und gewalttätige Agenda."},{t="Aggressoren der Wildnis",b="In der Wildnis, weit entfernt von den wachsamen Augen von Donnerfels, bricht die Feindseligkeit der Grimmtotem offen in Gewalt aus. Im Steinkrallengebirge massakrieren sie lokale Siedlungen und bedrohen Versorgungsposten der Horde. Über die hoch aufragenden Mesas von Tausend Nadeln hinweg, mit dem Zentrum am Düsterwolkengipfel, bedrohen sie ständig den Freiwindposten und schmieden Pläne, die Schlucht einzunehmen. Begegnungen in Feralas erweisen sich als ebenso gefährlich: Die Grimmtotem greifen Reisende der Horde, Karawanen der Allianz und andere Tauren ohne Zögern an. Die Garnisonen der Horde in Sonnenfels und Camp Mojache setzen regelmäßig Kopfgelder aus und entsenden Krieger, um diese gewalttätigen Ausgestoßenen niederzustrecken."},{t="Schatten und Apotheker",b="Unter Magathas Fassade als spirituelle Beraterin verbirgt sich ein kompliziertes Netz aus Intrigen. Die Ältestengreisin ist eine leidenschaftliche Befürworterin der umstrittenen Beziehungen der Tauren zu den Verlassenen und behauptet öffentlich, sie wolle die Untoten heilen, während sie heimlich nach toxischen Seuchen und Artefakten der Hochelfen sucht. In Tausend Nadeln fangen Späher des Freiwindpostens bewachte Korrespondenzen zwischen vermummten Boten und Grimmtotem-Häuptlingen am Düsterwolkengipfel ab."}},faq={{q="Warum sind die Grimmtotem feindselig, wenn ihre Anführerin in Donnerfels lebt?",a="Der Stamm der Grimmtotem ist der Horde nie formell beigetreten. Während Cairne Bluthuf Magatha Grimmtotem auf den hohen Mesas von Donnerfels in der Hoffnung duldet, den Frieden unter allen Tauren zu wahren, lehnen die umherstreifenden Krieger des Stammes Diplomatie von außen ab. Im Steinkrallengebirge, in Tausend Nadeln und in Feralas greifen sie jeden an, der ihr angestammtes Territorium betritt, einschließlich anderer Tauren.",al={"warum grimtotem rot","warum greifen grimtotem die horde an","sind grimtotem freundlich"}},{q="Woran könnt Ihr einen Grimmtotem von anderen Tauren unterscheiden?",a="Grimtotem-Tauren besitzen fast ausnahmslos pechschwarzes Fell. Sie sind außerdem dafür bekannt, ihre Körper und Gesichter mit markanter, scharfer Kriegsbemalung in strahlendem Weiß, tiefem Rot oder Blau zu bemalen.",al={"aussehen der grimtotem","fellfarbe der grimtotem"}},{q="Wer führt die Grimmtotem an?",a="Sie werden von der Ältestengreisin Magatha Grimmtotem regiert, einer mächtigen Schamanin, die auf der Anhöhe der Ältesten in Donnerfels residiert. Sie erlangte die Herrschaft, nachdem sie den vorherigen Häuptling geheiratet hatte, der kurz darauf bei einem ungeklärten Kletterunfall ums Leben kam.",al={"anführer der grimtotem","ältestengreisin"}},{q="Was ist das Ziel der Grimmtotem?",a="Die Grimmtotem streben danach, Kalimdor von dem zu säubern, was sie als niedere fremde Rassen betrachten – einschließlich Orcs, Menschen und Nachtelfen – und alle angestammten Territorien der Tauren zurückzufordern. Im Gegensatz zu Cairnes Volk glauben sie, dass dieses Land rein durch Gewalt, Täuschung und elementare Herrschaft eingenommen werden sollte.",al={"was wollen die grimtotem","motive der grimtotem"}},{q="Warum arbeitet Magatha Grimmtotem mit den Verlassenen zusammen?",a="Öffentlich behauptet Magatha, sie setze sich für die Verlassenen ein, weil der Schamanismus und die Erdenweisheit der Tauren helfen könnten, ihr Leiden zu heilen und ihre Menschlichkeit zurückzugeben. Insgeheim sucht sie jedoch nach deren Fachwissen über virulente Gifte, Fäulnis und dunkle Magie, um ihre Feinde zu eliminieren und ihre Macht in ganz Kalimdor zu festigen.",al={"magatha und untote","grimtotem und verlassene"}}},fx={["855936f4"]={q="Was ist der Grimtotemklan?",a="Die Grimtotem sind einer der mächtigsten und aggressivsten Taurenklane in Kalimdor. Im Gegensatz zu den allgemein friedlichen und spirituellen Klanen, die unter Hochhäuptling Cairne Bluthuf vereint sind, sind die Grimtotem militante Extremisten. Von Kindesbeinen an werden ihre Krieger in rücksichtslosem Kampf ausgebildet und meiden traditionelle ehrenhafte Jagdriten zugunsten des Lernens, mit jeder verfügbaren Waffe schnell zu töten.",al={"wer sind die grimtotem","grimtotem-klan","was ist grimtotem"}},["04251e4b"]={q="Warum findet man die Grimtotem überall in Kalimdor?",a="Ihr werdet Außenposten und Kriegstrupps der Grimtotem im Steinkrallengebirge, im Tausend Nadeln und in Feralas antreffen. Sie haben in diesen Regionen befestigte Stellungen errichtet, um ihre Herrschaft über angestammte Ländereien zu behaupten, und überfallen aktiv rivalisierende Siedlungen, während sie in die Gebiete der Horde und der Allianz eindringen.",al={"wo findet man grimtotem","warum sind grimtotem im steinkrallengebirge","grimtotem-standorte"}}},fp="15,454,13.612.0,19.624.0,24.439.1,69.362.0,53.184.0,24.239.0,27.288.0,50.293.1"}
P.entries["topic:grommash-hellscream"] = {fx={["04922c2d"]={q="Was ist die Geschichte von Grommash Höllschrei?",a="Grommash stieg auf, um den Kriegshymnenklan auf Draenor zu führen, und wurde der erste Häuptling, der das Blut des Dämons Mannoroth trank und die Orcs an die Brennende Legion band. Während des Zweiten Krieges auf Draenor festgehalten, führte er seinen Klan später durch Das Dunkle Portal und überlebte fünfzehn Jahre im Versteck in den Wildnissen von Lordaeron, während er gegen die dämonische Lethargie kämpfte, die sein Volk ergriffen hatte. Als er Thrall traf, half Grom, den Aufstand zu entfachen, der die gefangenen Orcs aus den Internierungslagern der Menschen befreite, und segelte schließlich mit Thrall nach Westen nach Kalimdor.",al={"grom höllschrei hintergrundgeschichte","grom-geschichte","woher stammt grom"}},["7ca9af40"]={q="Wer war mit Grommash Höllschrei verbündet?",a="Grom war der ergebene Häuptling des Kriegshymnenklans und der größte Leutnant sowie enger Waffenbruder von Kriegshäuptling Thrall. Zusammen mit Orgrim Schicksalshammer und Thralls Frostwolfklan verbündete Grom seine Krieger, um die Internierungslager der Orcs in Lordaeron zu befreien und die neue Horde zu schmieden. Er kämpfte an der Seite von Thrall während der Überfahrt nach Kalimdor und der Gründung ihrer neuen Heimat bis zu seinem ultimativen Opfer gegen Mannoroth.",al={"groms verbündete","für wen kämpfte grom","mit wem war grom höllschrei verbündet"}}}}
P.entries["topic:harpy"] = {fx={fb0f8e51={q="Was sind Harpyien?",a="Harpyien sind bösartige, intelligente vogelartige Kreaturen, die einer Mischung aus einer weiblichen Nachtelf und einem Raubvogel ähneln und anmutige Flügel als Arme sowie grausame Krallen als Füße besitzen. Anstatt mit der Wildnis zu harmonieren, verwüsten sie aktiv ihre Umgebung, schlachten die lokale Tierwelt ab und bauen üble, giftige Nester. Sie beherrschen urzeitliche Sturmmagie neben ihren Krallen und primitiven Waffen und verursachen Leid, wo auch immer sie sich niederlassen.",al={"was ist eine harpyie","wer sind harpyien","harpyien-kunde"}},["6541e8e0"]={q="Warum sind Harpyien Reisenden gegenüber feindselig?",a="Harpyien greifen bei Sichtkontakt an, weil sie territorial und räuberisch sind und davon leben, Chaos und Kummer zu verursachen. Sie breiten sich aggressiv von ihren Nestern aus, überfallen Reisende, plündern Versorgungskarawanen und töten fast jede Kreatur, die in ihre Ländereien wandert, um ihre Nester mit den grausamen Überresten ihrer Opfer zu übersäen.",al={"warum greifen harpyien an","sind harpyien freundlich","warum sind harpyien aggressiv"}},b7cf3fa6={q="Haben Harpyien irgendwelche Verbündeten?",a="Harpyien tolerieren selten Außenstehende, sind aber dafür bekannt, lockere Verbindungen zu Kobolden zu unterhalten. Da Harpyien gierig auf glänzende Edelsteine und Erze sind, handeln Kobolde mit diesen gesammelten Schätzen im Austausch gegen Dinge wie Harpyien-Ohrenschmalz, und in einigen Regionen zollen Kobolde den Harpyien Tribut im Austausch für Schutz.",al={"mit wem arbeiten harpyien zusammen","harpyien-verbündete","wer verbündet sich mit harpyien"}},["518dbd10"]={q="Warum findet man Harpyien überall in Kalimdor?",a="Harpyien waren einst auf ihre angestammten Nistplätze in den Felsen des Steinkrallengebirges beschränkt. Im Laufe der Zeit trieben ihre wachsende Anzahl und ihre aggressive Natur die Brutstätten dazu, nach außen über den Kontinent zu migrieren. Ihr könnt jetzt auf ihre üblen Nistplätze überall treffen, von den Wäldern von Teldrassil bis zu den Mesas von Mulgore, Durotar und dem Brachland.",al={"wo leben harpyien","warum sind harpyien in kalimdor","harpyien-gebiet"}}}}
P.entries["topic:highborne"] = {n="Hochgeborene",s="Die Hochgeborenen, oder Quel'dorei, waren die aristokratische Zaubererkaste des alten Kaldoreireichs, die Königin Azshara dienten. Ihre rücksichtslose Manipulation des Brunnens der Ewigkeit brachte die Brennende Legion nach Azeroth und führte zum verheerenden Krieg der Ahnen sowie der Großen Zerschlagung.",h="Die Hochgeborenen, oder Quel'dorei, waren die aristokratische Zaubererkaste des alten Kaldoreireichs, die...",kw={"azshara","dath'remar","düsterbruch","eldre'thalas","hochgeborene","quel'dorei","sargeras","shen'dralar","brunnen der ewigkeit","zin-azshari"},ang={["class:Druid"]="Der Druidismus entstand als die Naturphilosophie, die der rücksichtslosen Ausbeutung des Brunnens der Ewigkeit durch die Hochgeborenen entgegentrat, und bildete das Fundament für die Heilung von Kalimdor nach dem Fall des Reiches.",["class:Mage"]="Die Hochgeborenen waren die ersten sterblichen Anwender sterblicher Arkanmagie auf Azeroth, deren atemberaubende Errungenschaften und verheerende Fehler die gefährlichen Regeln des modernen Zauberwirkens begründeten.",["class:Warlock"]="Die Hochgeborenen waren die ersten Sterblichen auf Azeroth, die mit der Brennenden Legion verhandelten, und tauschten kosmische Geheimnisse sowie Dämonenpakte aus, die den Weg für moderne Teufelsstudien ebneten.",["race:NightElf"]="Die Erinnerung an die Kaste der Hochgeborenen bleibt eine tiefe Narbe in der Kultur der Nachtelfen und dient als einziger Grund dafür, dass Arkanmagie überall in Kalimdor unter Androhung von Verbannung oder Tod verboten ist."},sec={{t="Aristokraten des Brunnens",b="Vor der Zerschlagung stiegen die Hochgeborenen als die bevorzugte Oberschicht um Königin Azshara auf. Sie beanspruchten Überlegenheit gegenüber einfachen Kaldorei durch erlesene Blutlinien, Intelligenz und opulente Privilegien und kontrollierten streng den Zugang zum Brunnen der Ewigkeit. Sie entdeckten, wie man dessen urzeitliche arkane Energien anzapfen und formen konnte, und errichteten prächtige Städte im gesamten alten Kalimdor. Ihr unstillbarer Durst nach größerer Zauberkraft trieb sie dazu, tiefer aus dem Brunnen zu schöpfen, was dessen ruhige Wasser unruhig und finster werden ließ."},{t="Der Verrat und die Zerschlagung",b="Die Wogen arkaner Macht, die durch die Zauberkunst der Hochgeborenen erzeugt wurden, erregten die Aufmerksamkeit des Dunklen Titanen Sargeras und der Brennenden Legion. Von Azshara und ihrem Berater Xavius überzeugt, dass die Dämonen die Welt in ein unbeflecktes Paradies verwandeln würden, öffneten die Hochgeborenen ein gewaltiges Tor im Brunnen selbst. Dies entfesselte den katastrophalen Krieg der Ahnen. Während dämonische Horden die Bevölkerung abschlachteten, kämpften von Malfurion Sturmgrimm gesammelte Rebellenstreitkräfte darum, das Portal zu schließen, was den Brunnen der Ewigkeit implodieren ließ und den Urkontinent zerriss."},{t="Verstreute Erben und Überbleibsel",b="Das Schicksal der Hochgeborenen zersplitterte nach der Zerschlagung. Jene, die an der Seite von Azshara unter die Wellen gerissen wurden, verwandelten sich in schlangenartige Naga, während andere dämonischen Flüchen erlagen und zu Satyren wurden. Eine Fraktion unter Dath'Remar Sunstrider half dem Widerstand, weigerte sich jedoch, der Arkanmagie abzuschwören, und erlitt schließlich die Verbannung über das Meer, um das Hochelfenkönigreich Quel'Thalas zu gründen. Heute verbleiben isolierte Enklaven wie die Shen'dralar abgeschottet in Eldre'Thalas, gemiedene Relikte eines Reiches, das Azeroth beinahe vernichtet hätte."}},faq={{q="Was bedeutet „Hochgeborene“?",a="Auf Darnassisch sind sie als Quel'dorei bekannt, was direkt mit „Kinder edler Geburt“ übersetzt wird. Sie wählten diesen Namen, um ihre aristokratischen Blutlinien und ihre magische Begabung vom Rest der Kaldoreigesellschaft abzugrenzen.",al={"queldorei bedeutung","was bedeutet queldorei","hochgeborene übersetzung"}},{q="Sind die modernen Nachtelfen mit den Hochgeborenen verwandt?",a="Ja. Die Hochgeborenen waren lediglich die adelige, Magie wirkende Herrscherkaste der alten Nachtelfen. Abgesehen davon, dass sie etwas blasser waren und zu extravaganter Kleidung neigten, gehörten sie physisch demselben Volk an. Nach der Zerschlagung verbot die moderne Nachtelfengesellschaft die Arkanmagie und schaffte die Kaste vollständig ab.",al={"sind nachtelfen hochgeborene","unterschied nachtelfen und hochgeborene","hochgeborene nachtelfen verbindung"}},{q="Wie haben die Hochgeborenen den Krieg der Ahnen verursacht?",a="Ihre maßlose und unkontrollierte Nutzung des Brunnens der Ewigkeit sandte magische Wogen durch den Kosmos und lockte die Brennende Legion an. Verlockt von Sargeras' Versprechungen unübertroffener Macht und einer idealisierten Welt kanalisierten Azshara und ihre Adligen den Brunnen, um ein Portal zu erschaffen, das die Dämonenarmee direkt nach Kalimdor einlud.",al={"warum kam die brennende legion","wie beschworen hochgeborene dämonen","hochgeborene krieg der ahnen rolle"}},{q="Stellten sich alle Hochgeborenen auf die Seite von Königin Azshara?",a="Nein. Mehrere Gruppierungen sagten sich los, als sie die dämonische Verwüstung sahen. Zauberer unter der Führung von Dath'Remar Sunstrider liefen über, um sich Malfurions Kaldorei-Widerstand anzuschließen, während Gruppen wie die Shen'dralar in Eldre'Thalas sich darauf konzentrierten, zu überleben und ihre eigenen regionalen Besitztümer zu verteidigen.",al={"gute hochgeborene","kämpften hochgeborene gegen azshara","hochgeborene widerstand"}},{q="Was geschah nach dem Krieg mit den überlebenden Hochgeborenen?",a="Ihre Linie verteilte sich auf unterschiedliche Schicksale. Viele, die mit Zin-Azshari versanken, wurden zu Naga, andere wurden zu Satyren entstellt, und jene, die Dath'Remar folgten, wurden in die Östlichen Königreiche verbannt und entwickelten sich zu Hochelfen. Einige wenige, wie die Shen'dralar im Düsterbruch, blieben in uralten Ruinen abgeschottet.",al={"was wurde aus den hochgeborenen","wo sind die hochgeborenen jetzt","nachfahren der hochgeborenen"}},{q="Wer sind die Shen'dralar?",a="Die Shen'dralar sind eine uralte Sekte von Hochgeborenen-Gelehrten und Arkanisten, die während der Großen Zerschlagung die südliche Stadt Eldre'Thalas erfolgreich verteidigten. Abgeschnitten von Königin Azshara und der restlichen Kaldoreigesellschaft zogen sie sich in die Stadt – heute Düsterbruch genannt – zurück und verließen sich auf dunkle Zaubereien, um ihre Unsterblichkeit zu bewahren.",al={"düsterbruch hochgeborene","eldre thalas elfen","wer lebt in düsterbruch"}}},fx={["798aa346"]={q="Wer waren die Hochgeborenen?",a="Die Hochgeborenen – oder Quel'dorei – waren die wohlhabende aristokratische Kaste des alten Nachtelfenreichs und dienten als bevorzugte Höflinge und Zauberer der Königin Azshara. Indem sie sich durch erbliches Privileg und unermüdliches Studium arkaner Magie aus dem Brunnen der Ewigkeit auszeichneten, wurden sie arrogant und entfremdeten sich von den gewöhnlichen Kaldorei. Ihre rücksichtslosen magischen Experimente und ihr Pakt mit Sargeras führten vor zehntausend Jahren zur ersten Invasion der Brennenden Legion.",al={"was sind hochgeborene","wer sind die hochgeborenen","quel'dorei nachtelfen"}},de607c9c={q="Wer führt die Hochgeborenen an?",a="In alten Zeiten antworteten die Hochgeborenen direkt an Königin Azshara, ihre geliebte und tyrannische Monarchin. Nach der Großen Zerstörung und dem Zusammenbruch des Kaldorei-Reiches zersplitterte die Kaste in verstreute Überreste. Überlebende Enklaven wie die Shen'dralar in Düsterbruch folgen ihren eigenen lokalen Herrschern, während die Hochgeborenen, die über das Meer flohen, neue Abstammungslinien bildeten, sodass heute kein einzelner Anführer mehr über die alte Kaste herrscht.",al={"hochgeborenen-anführer","wer regiert die hochgeborenen","königin azshara hochgeborene"}}},fp="9,286,23.503.0,30.551.0,28.516.0,27.225.0,48.296.0,52.312.0,42.273.0,55.307.0,24.330.0"}
P.entries["topic:horde"] = {fx={["34e0453c"]={q="Was ist die Horde?",a="Die Horde ist ein Bündnis aus vier unterschiedlichen Völkern – Orcs, Tauren, Dunkelspeere und die Verlassenen –, die sich zum gegenseitigen Überleben in einer unversöhnlichen Welt zusammengeschlossen haben, die sie sonst vernichtet sähe. Unter Kriegshäuptling Thrall wiedergeboren, nachdem sie sich von der dämonischen Verderbnis befreit haben, schätzt diese neue Horde Stärke, Ehre und Freiheit. Anstatt zu erobern, stehen diese Ausgestoßenen und spirituellen Verbündeten vereint, um ihre neu gefundene Heimat in Kalimdor und Lordaeron vor Feinden von allen Seiten zu schützen.",al={"was ist die horde","wer sind die horde","horde-fraktion erklärt"}},b47060cc={q="Warum bekämpft die Horde die Allianz?",a="Tiefsitzendes Misstrauen und eine schmerzhafte Geschichte halten beide Seiten in einem angespannten Kalten Krieg gefangen. Die Allianz erinnert sich an die Brutalität der dämonischen alten Horde und fällt es schwer zu glauben, dass die Orcs sich wirklich geändert haben, während sie gleichzeitig die untoten Verlassenen als monströse Abscheulichkeiten betrachtet. Territoriale Scharmützel, knappe Ressourcen und alte Feindseligkeiten flackern ständig auf der ganzen Welt auf. Auch wenn Anführer wie Thrall Frieden und Distanz zur Vergangenheit suchen, macht das anhaltende Misstrauen der Allianz einen offenen Konflikt zu einer allgegenwärtigen Realität.",al={"warum die allianz hassen","grund für den krieg zwischen horde und allianz","warum die allianz bekämpfen"}},["93715b4a"]={q="Was bedeutet es, der Horde zu dienen?",a="Der Horde zu dienen bedeutet, für das Überleben, die Freiheit und die Ehre von Völkern zu kämpfen, die vom Rest Azeroths beiseitegeschoben wurden. Es wird von Euch erwartet, Euren Kameraden als Familie zur Seite zu stehen und Bedrohungen mit Taten und Stärke statt mit leerer Diplomatie zu beantworten. Egal, ob Ihr wichtiges Holz in umkämpften Wäldern sichert, an der Seite von Tauren-Tapferen jagt oder neue Siedlungen vor feindlichen Nachbarn verteidigt, Eure Klinge schützt ein Bündnis von Ausgestoßenen, die danach streben, sich einen dauerhaften Platz in der Welt zu erkämpfen.",al={"der horde dienen","pflicht der horde","was erwartet die horde"}}}}
P.entries["topic:house-of-nobles"] = {fx={f6b9ddca={q="Wer führt das Haus der Adligen an?",a="Das Haus der Adligen hat keinen einzelnen vorsitzenden Herrscher; es ist ein erblicher Rat mächtiger Aristokraten, der den Thron berät. Da König Varian vermisst wird, halten der Jungenkönig Anduin Wrynn und Hochlord Bolvar Fordragon die formelle exekutive Autorität, aber die Hofberaterin Lady Katrana Prestor übt enormen Einfluss auf den Adel aus. Ihr Flüstern lenkt einen Großteil ihrer Politik und hält die Versammlung gespalten, ängstlich und zögerlich, königliche Truppen an die abgelegenen Grenzen zu entsenden.",al={"anführer des hauses der adligen","wer kontrolliert das haus der adligen","wer hat das sagen beim adel"}},["7a9e9579"]={q="Was ist die Geschichte des House of Nobles?",a="Das House of Nobles reicht bis vor den Ersten Krieg zurück und vertrat die wohlhabendsten aristokratischen Grundbesitzer des Königreichs. Die meisten seiner Blutlinien wurden beinahe ausgelöscht, als die alte Horde Sturmwind plünderte. Nach dem Zweiten Krieg stellte Prinz Varian Wrynn die Versammlung mit Ministern und Beratern wieder her, um den Wiederaufbau im Inneren zu leiten. Das Haus beaufsichtigte den Wiederaufbau von Sturmwind, indem es die Stonemasons' Guild anheuerte, häufte jedoch durch militärische Unternehmungen schwere Schulden an, was bittere Streitigkeiten, Aufstände und Jahre politischer Lähmung auslöste.",al={"geschichte des hauses der adligen","ursprünge des hauses der adligen","woher kamen die adligen"}}}}
P.entries["topic:human"] = {n="Mensch",s="Menschen sind ein anpassungsfähiges und widerstandsfähiges sterbliches Volk, das einen Großteil der Geschichte der Östlichen Königreiche geprägt hat. Einst unter dem uralten Imperium von Arathor vereint, zerfiel ihre Zivilisation in die Sieben Königreiche, wobei Sturmwind heute als wichtigste überlebende Bastion der Menschheit innerhalb der Allianz dasteht.",h="Menschen sind ein anpassungsfähiges und widerstandsfähiges sterbliches Volk, das einen Großteil der...",kw={"allianz","arathor","mensch","lordaeron","menschheit","sturmwind","thoradin","trollkriege","wrynn"},ang={["class:Mage"]="Die Zauberkunst der Menschen reicht bis in die Trollkriege zurück, als die Hochelfen die ersten Einhundert menschlichen Magier unterrichteten, was schließlich zur Gründung von Dalaran führte.",["class:Paladin"]="Die Ritter der Silbernen Hand wurden von menschlichen Geistlichen und Rittern in Lordaeron gegründet, um die Schrecken des Zweiten Krieges zu bekämpfen.",["faction:Alliance"]="Menschliche Diplomatie und Entschlossenheit schmiedeten die Allianz von Lordaeron, und Sturmwind bleibt das politische und militärische Herz der Fraktion.",["faction:Horde"]="Die Menschen waren die ersten Feinde, auf die die Orks trafen, als sie das Dunkle Portal durchquerten, was drei brutale Kriege ums Überleben auf Azeroth auslöste.",["race:Human"]="Als Mensch tretet Ihr das Erbe des gefallenen Arathor und des zerstörten Lordaeron an; die Verteidigung und das Überleben der sterblichen Reiche ruht ganz auf den Schultern von Sturmwind."},sec={{t="Das Imperium von Arathor",b="Vor Jahrtausenden lebten die frühen Menschen als verstreute, nomadische Stämme, die ständig von den Amani-Waldtrollen bedroht wurden. In der Erkenntnis, dass Uneinigkeit den Untergang bedeuten würde, vereinte Kriegsfürst Thoradin vom Stamm der Arathi die ungleichen Clans durch Diplomatie und Eroberung und gründete das Imperium von Arathor mit seiner Festungshauptstadt Strom. Während der Trollkriege verbündeten sich die bedrängten Hochelfen von Quel'Thalas mit Arathor und lehrten einhundert Menschen die Künste der arkanen Magie. Gemeinsam zerschlugen sie die Armeen der Trolle, sicherten die Vorherrschaft der Menschheit über die zentralen Kontinente und legten den Grundstein für künftige sterbliche Allianzen."},{t="Zerfall in die Sieben Königreiche",b="Als Arathor sicherer und wohlhabender wurde, entwickelten sich seine abgelegenen Siedlungen zu mächtigen, autarken Stadtstaaten. Im Laufe der Zeit zersplitterte das zentralisierte Imperium in sieben verschiedene Reiche: Gilneas, Alterac, Dalaran, Lordaeron, Kul Tiras, Sturmwind und Stromgarde (die ursprüngliche Heimat von Strom). Während diese Nationen regen Handel mit Zwergen, Gnomen und Elfen trieben, war der Frieden brüchig. Gebietsstreitigkeiten, Grenzscharmützel – wie die ständigen Fehden in den Bergen zwischen Alterac und Stromgarde – und höfische Intrigen zehrten an den Königreichen und schufen tiefe Rivalitäten, die fortbestanden, bis äußere Katastrophen sie zum Handeln zwangen."},{t="Invasion und Ruin",b="Die Ankunft der orkischen Horde durch das Dunkle Portal setzte den internen Streitigkeiten der Menschheit ein Ende. Sturmwind wurde während des Ersten Krieges dem Erdboden gleichgemacht, und seine Flüchtlinge flohen nach Norden, um die anderen Reiche zu warnen. Als Reaktion darauf half König Terenas Menethil II. dabei, die Allianz von Lordaeron zu schmieden, welche die Stärke der Menschen, Zwerge, Gnome und Hochelfen bündelte, um die Horde im Zweiten Krieg zu besiegen. Obwohl Sturmwind mühsam wiederaufgebaut wurde, schlug die Tragödie erneut zu, als die Seuche der Geißel Lordaeron verwüstete und Dalaran während des Dritten Krieges fiel, wodurch die nördlichen Menschenreiche als rauchende Trümmer zurückblieben."},{t="Eine prekäre Gegenwart",b="Heute ist Sturmwind das stärkste verbliebene Menschenkönigreich und der Dreh- und Angelpunkt der Großen Allianz. Doch der Frieden bleibt trügerisch. König Varian Wrynn ist auf dem Weg zu einem diplomatischen Gipfeltreffen auf mysteriöse Weise verschwunden, sodass sein zehnjähriger Sohn Anduin Wrynn zum König gekrönt wurde, während Hochlord Bolvar Fordragon als Regent fungiert. Im Norden sind die Überlebenden von Lordaeron verstreut oder tot, während Gilneas sich hinter seinem kolossalen Greymane-Wall versteckt, sodass Sturmwind die Last der Verteidigung der Menschheit tragen muss."}},faq={{q="Was waren die Sieben Königreiche der Menschheit?",a="Die Sieben Königreiche entstanden, als das uralte Imperium von Arathor in unabhängige Stadtstaaten zerfiel: Lordaeron, Sturmwind, Stromgarde, Dalaran, Kul Tiras, Gilneas und Alterac. Jedes entwickelte seine eigene Kultur, von den Seefahrerflotten von Kul Tiras bis zu den arkanen Akademien von Dalaran.",al={"sieben menschenkönigreiche","menschennationen","königreiche von arathor"}},{q="Woher kamen die Menschen ursprünglich?",a="Die Menschen entstanden vor Jahrtausenden als nomadische Stämme, die durch die Wälder und das Hochland der nördlichen Östlichen Königreiche streiften, insbesondere rund um Tirisfal, bevor sie sich unter Kriegsfürst Thoradin zur ersten Menschennation vereinten.",al={"ursprung der menschen","frühe menschen","vorfahren der menschen"}},{q="Was geschah mit dem Königreich Lordaeron?",a="Lordaeron wurde während des Dritten Krieges durch die Seuche des Untods der Geißel verwüstet und von seinem eigenen Prinzen Arthas Menethil verraten. Heute sind die zerstörte Hauptstadt und die umliegenden Ländereien zwischen den untoten Verlassenen, der Geißel und Überresten wie dem Scharlachroten Kreuzzug umkämpft.",al={"warum ist lordaeron zerstört","fall von lordaeron","schicksal von lordaeron"}},{q="Wer regiert derzeit die Menschheit und Sturmwind?",a="Da König Varian Wrynn unter verdächtigen Umständen verschwunden ist, sitzt sein junger Sohn Anduin Wrynn als Galionsfigur auf dem Thron, während Hochlord Bolvar Fordragon an der Seite der königlichen Beraterin Lady Katrana Prestor als Regent herrscht.",al={"wer regiert sturmwind","könig von sturmwind","herrscher von sturmwind"}},{q="Warum lehrten die Hochelfen die Menschen Magie?",a="Während der uralten Trollkriege standen die Hochelfen von Quel'Thalas vor der Vernichtung durch die Amani-Trolle. Verzweifelt auf der Suche nach militärischer Verstärkung schlossen sie einen Vertrag mit Thoradin, dem Herrscher von Arathor, und willigten ein, einhundert Menschen im Arkanen zu unterweisen, im Austausch für menschliche Armeen.",al={"elfen lehrten menschen magie","erste menschliche magier","magie der trollkriege"}},{q="Welche Rolle spielten die Menschen bei der Bildung der Allianz?",a="Nachdem Sturmwind im Ersten Krieg an die Orks gefallen war, sammelten menschliche Flüchtlinge die nördlichen Königreiche. Unter König Terenas von Lordaeron und Lord Lothar von Sturmwind vereinten sich die Menschenreiche mit den Zwergen aus Eisenschmiede, Gnomen und Hochelfen, um die Allianz von Lordaeron zu gründen.",al={"gründung der allianz","ursprung der allianz von lordaeron","wie entstand die allianz"}},{q="Welche Klassen können Menschen sein?",a="Menschen werden als Krieger, Paladine, Jäger, Schurken, Priester, Magier und Hexenmeister ausgebildet.",al={"menschenklassen","welche klassen können menschen sein","können menschen jäger sein"}}},fp="5,297,21.619.0,28.619.0,17.572.0,20.504.0,41.281.0,38.227.0,42.272.0,43.221.0,42.269.0,50.266.0,28.81.0"}
P.entries["topic:hunter"] = {n="Jäger",s="Als Meister des Überlebens in der Wildnis und der tödlichen Treffsicherheit durchstreifen Jäger die ungezähmten Weiten von Azeroth an der Seite wilder tierischer Begleiter. Bewaffnet mit Bögen, Gewehren oder Armbrüsten verstehen sie es meisterhaft, Feinde aus der Ferne zu bedrängen, während sie sich auf geschickte Fallen und urtümliche Aspekte verlassen, um das Kampfgeschehen zu kontrollieren. Ob sie nun schwer fassbare Beute über schneebedeckte Gipfel verfolgen oder ihr durch dichte Wälder nachstellen – sie leben von ihrem Scharfsinn und ihrer Verbundenheit zur Natur.",h="Als Meister des Überlebens in der Wildnis und der tödlichen Treffsicherheit durchstreifen Jäger die...",kw={"bogenschießen","aspekte","wildtiere","jäger","treffsicherheit","begleiter","gewehr","überleben","spurenlesen","fallen"},ang={["class:Hunter"]="Eure Stärke liegt in Eurer Verbindung zur Wildnis und Eurem tierischen Begleiter. Meistert Euer Fernkampfarsenal, haltet Abstand und lasst Euren Begleiter die Aufmerksamkeit des Feindes binden.",["race:Dwarf"]="Scharfschützen der Zwerge sind berühmt für ihre Treffsicherheit mit schweren Gewehren und trotzen an der Seite wilder Eisbären den tückischen Gebirgspässen von Khaz Modan.",["race:Human"]="Menschliche Jäger erlernen ihr Handwerk im Wald von Elwynn von erfahrenen Fährtensuchern wie dem Zwerg Tordrin Sternblade im Nordhaintal und Josephine Carson in Goldhain.",["race:NightElf"]="Seit Jahrtausenden patrouillieren Kaldorei-Schildwachen mit Bögen und treuen Säbeln durch uralte Wälder und verteidigen heilige Haine gegen Verderbnis von außen.",["race:Orc"]="Bestienmeister der Orcs ehren uralte Überlebensraditionen, die auf rauen Welten geschmiedet wurden, und gehen unzerbrechliche Kampfbünde mit loyalen Wölfen und Ebern ein.",["race:Skyborne"]="Jäger der Skyborne lernen, die Bestien der Insel Zephras aufzuspüren und zu zähmen, einem schwebenden Land, das im Himmelswall treibt.",["race:Tauren"]="Für die Tauren ist die Jagd eine heilige spirituelle Prüfung der Ausdauer und Ehrfurcht, die die Erdenmutter ehrt, indem sie jedes Tier respektiert, das den Stamm ernährt und kleidet."},sec={{t="Verbundenheit mit der Wildnis",b="Im Herzen jedes Jägers liegt ein instinktives Mitgefühl für die urtümliche Welt. Anders als jene, die die Natur ausbeuten oder sich in steinernen Bastionen isolieren, tauchen Jäger vollkommen in ungezähmte Lande ein. Sie studieren die Gewohnheiten, Bewegungen und Stärken räuberischer Bestien und verdienen sich deren Respekt, anstatt ihren Geist zu brechen. Durch geduldigen Beziehungsaufbau zähmt ein Jäger gefährliche Kreaturen – wie etwa wilde herumstreifende Katzen, starrsinnige Gebirgsbären und scharfäugige Raptoren – und verwandelt wilde Tiere in standhafte Verbündete, die ihn bis zum Tod verteidigen."},{t="Meisterschützen und Fährtensucher",b="Auf dem Schlachtfeld diktieren Jäger die Bedingungen des Gefechts aus sicherer Entfernung. Ausgerüstet mit Bögen, schweren Armbrüsten oder kalibrierten Gewehren entfesseln sie tödliche Salven, die schwere Rüstungen durchdringen, noch bevor ein Angreifer überhaupt herankommen kann. Ihre fein geschärften Sinne machen sie zu unvergleichlichen Fährtensuchern, die selbst den schwächsten Fußspuren, Fährten und von Beute hinterlassenen Störungen zu folgen vermögen. Wenn Feinde versuchen, die Distanz zu verringern, setzen Jäger Frost- und Feuerfallen, verwirrende Hinterhalte oder agile Ausweichmanöver ein, um Widersacher genau dort zu halten, wo sie sie haben wollen."},{t="Traditionen der verschiedenen Kulturen",b="Der Pfad des Jägers manifestiert sich in den verschiedenen Kulturen von Azeroth auf unterschiedliche Weise. Schildwachen der Nachtelfen verkörpern uralte Treffsicherheit und Heimlichkeit unter dem Blätterdach von Eschental, wobei sie Bögen und Schattenkunst in ruhiger Harmonie mit der Wildnis nutzen. Gewehrschützen der Zwerge trotzen an der Seite zäher Bären den eisigen Felsen von Dun Morogh und meistern die Ingenieurskunst des Schießpulvers. In ganz Kalimdor ehren Fährtensucher der Tauren und Orcs uralte nomadische Bräuche, indem sie ihre Beute mit heiligem Respekt zur Strecke bringen und bestialische Geister anrufen, um ihre Schüsse zu leiten. Im Wald von Elwynn erlernen junge Menschen das Handwerk von erfahrenen Fährtensuchern wie dem Zwerg Tordrin Sternblade im Nordhaintal und Josephine Carson in Goldhain, und die Skyborne lernen, die Bestien der Insel Zephras aufzuspüren und zu zähmen."}},faq={{q="Welche Waffen nutzen Jäger?",a="Jäger spezialisieren sich auf Fernkampfwaffen, darunter Bögen, Armbrüste und Gewehre. Auf kurze Distanz sind sie zudem im Führen von Nahkampfwaffen wie Stangenwaffen, Stäben, Äxten und Dolchen geschult, wobei sie oft den beidhändigen Kampf nutzen oder Fallen einsetzen, um Abstand zu gewinnen und das Feuer aus der Ferne wieder aufzunehmen.",al={"jägerwaffen","was jäger ausrüsten","jäger bögen gewehre"}},{q="Wie zähmen Jäger Bestien?",a="Jäger verlassen sich auf angeborenes Einfühlungsvermögen und ein tiefes Verständnis für wilde Kreaturen. Indem sie deren Verhalten beobachten, sich ohne böse Absicht nähern und Stärke sowie Respekt beweisen, können sie gefährliche Raubtiere beruhigen und ein lebenslanges Band als Begleiter knüpfen, um sie für den Kampf an ihrer Seite auszubilden.",al={"wie man begleiter zähmt","tierzähmung","tier zähmen"}},{q="Welche Rüstung tragen Jäger?",a="Jäger beginnen ihre Reisen im Tragen leichter, flexibler Lederrüstung, um ihre Beweglichkeit beim Durchqueren unwegsamen Geländes zu bewahren. Wenn sie an Erfahrung gewinnen und sich tödlicheren Bedrohungen stellen, lernen sie, strapazierfähige schwere Rüstung zu tragen, die größeren Schutz bietet, ohne ihre Bewegung gravierend zu behindern.",al={"jäger rüstungsart","können jäger schwere rüstung tragen","jägerausrüstung"}},{q="Was sind Jägeraspekte?",a="Aspekte sind urtümliche Techniken, bei denen ein Jäger seine Sinne und körperlichen Reflexe auf die angeborenen Stärken wilder Kreaturen einstimmt. Durch das Anrufen dieser Aspekte kann ein Jäger mit der Schnelligkeit eines Geparden laufen, sein Ziel wie ein Falke fokussieren oder die defensive Widerstandskraft eines Affen annehmen.",al={"jägeraspekte","aspekt des geparden","jäger tieraspekte"}},{q="Was geschieht, wenn ein Feind einem Jäger zu nahe kommt?",a="Jäger befinden sich auf kurze Distanz in einem deutlichen Nachteil, da das Abfeuern einer Fernkampfwaffe dort schwierig wird. Um zu überleben, verlassen sie sich auf Frost- und Feuerbrandfallen, erschütternde Hilfsmittel und Nahkampfangriffe, um Angreifer zu verlangsamen, zu verwunden oder zu verwirren, während sie selbst oder ihre Bestien sich lösen, um Distanz aufzubauen.",al={"tote zone des jägers","nahkampf jäger","jäger nahkampf"}},{q="Welche Völker praktizieren die Pfade des Jägers?",a="Die Jagd wird in fast allen Kulturen praktiziert, wenn auch in unterschiedlicher Form. In der Allianz ergreifen Nachtelfen, Zwerge und Menschen Bogen und Gewehr. In der Horde verehren Orcs, Tauren und Trolle das Fährtensuchen und die Tierherrschaft als überlieferte Traditionen des Überlebens. Die Skyborne bilden Jäger auf beiden Seiten aus, während Gnome und die Verlassenen nicht auf dem Pfad des Jägers wandeln.",al={"wer kann jäger werden","jägervölker","spielbare jägervölker","können menschen jäger werden","menschlicher jäger"}}},fx={b60a9390={q="Was ist ein Jäger in der Geschichte?",a="Jäger sind Meister der Wildnis, meisterhafte Schützen und abgehärtete Fährtenleser, die dem Ruf der Wildnis folgen. Da sie auf einzigartige Weise auf die Natur eingestimmt sind, überleben sie in unerforschten Gebieten dank ihres Verstandes und ihres Wissens über die Kreaturen, die sie verfolgen. Während ein Jäger mit Bögen, Armbrüsten, Gewehren und Fallen tödlich ist, zeichnet er sich durch tiefes Einfühlungsvermögen für Bestien aus und knüpft lebenslange Bindungen zu wilden Gefährten, die an seiner Seite gegen die vordringenden Bedrohungen der Welt kämpfen und Kundschaften.",al={"was ist ein jäger","jäger lore","jägerklassen lore"}},["49aa042d"]={q="Woher stammt die Kraft eines Jägers?",a="Die Stärke eines Jägers stammt aus einer innigen Verbindung zur natürlichen Welt, strengem Waffentraining und genauer Beobachtung des wilden Wildes. Anstatt auf arkanes Studium oder göttliche Verehrung zurückzugreifen, kanalisieren sie ihre Kraft, indem sie sich auf die urtümlichen Aspekte wilder Bestien einstimmen. In Kombination mit unübertroffener Treffsicherheit, pflanzlichen Giften und einer angeborenen Verwandtschaft, die den Gehorsam wilder Raubtiere erzwingt, liegt ihre Macht in völliger Harmonie mit der Wildnis.",al={"woher bekommen jäger ihre kraft","jäger kraftquelle","jäger magiequelle"}},fa19871b={q="Was bedeutet es für einen neuen Abenteurer, ein Jäger zu werden?",a="Als Jäger aufzubrechen bedeutet, einem inneren Ruf zu folgen, die Annehmlichkeiten der Zivilisation zugunsten der ungezähmten Wildnis hinter sich zu lassen. Ihr verlasst Euch ganz auf Eure List, Eure scharfen Sinne und Eure Fernkampfwaffen, um allein in feindseligen Landen zu überleben. Wenn Ihr lernt, Spuren zu lesen und Hinterhalte zu legen, werdet Ihr Euch den Respekt eines wilden Tieres verdienen und einen treuen Partner gewinnen, der Euch den Rücken freihält, während Ihr die Wildnis vor Verderbnis und Ausbeutung verteidigt.",al={"jäger werden","was bedeutet es, ein jäger zu sein","als jäger starten"}}},fp="6,447,21.552.0,28.548.0,26.764.0,28.286.0,27.282.0,27.289.0,24.283.0,52.290.0,44.366.0"}
P.entries["topic:juggernaught"] = {n="Juggernaught",s="Ein Juggernaught ist ein enormes, schwer gepanzertes Schlachtschiff, das vor schweren Schiffskanonen nur so strotzt. Ursprünglich von Ogern konstruiert, um während des Zweiten Krieges als eiserner Kern der Flotte der Alten Horde zu dienen, wurden diese schwimmenden Festungen gebaut, um Küstenfestungen und Handelsrouten zu pulverisieren. Ihre massive Eisenpanzerung und ihre Breitseiten von Belagerungsstärke machen sie zu legendären Instrumenten der Seekriegsführung.",h="Ein Juggernaught ist ein enormes, schwer gepanzertes Schlachtschiff, das vor schweren Schiffskanonen nur so...",kw={"schlachtschiff","die todesminen","defias","eiserne bucht","juggernaught","juggernaut","oger-juggernaught","schiff","sturmwind","vancleef"},ang={["class:Rogue"]="Der Juggernaught in den Todesminen stellt die äußerste Kühnheit von Edwin van Cleef dar – den Bau eines Großkampfschiffs direkt vor der Nase von SI:7 und der Wache von Sturmwind.",["faction:Alliance"]="Die Entdeckung eines im Bau befindlichen Juggernaughts unter Westfall offenbart eine ernste Bedrohung für die Sicherheit von Sturmwind und den Hof von König Anduin.",["faction:Horde"]="Juggernaughts stellen ein geschichtsträchtiges Kapitel des maritimen Erbes der Horde aus dem Zweiten Krieg dar und beweisen, dass rohe Ingenieurskunst der Wildheit die Vorherrschaft der Allianz auf den Meeren anfechten konnte.",["race:Human"]="Die Wiedererbauer von Sturmwind, die unter VanCleef verraten und zu Gesetzlosen wurden, setzten ihre feinsten architektonischen Fähigkeiten und Steinmetzkünste ein, um ein monströses Kriegsschiff zusammenzusetzen, das unter den Hügeln von Westfall verborgen liegt."},sec={{t="Schrecken des Zweiten Krieges",b="Orcs waren traditionell keine Seefahrerkultur. Als die Horde daher während des Zweiten Krieges eine Flotte benötigte, die in der Lage war, Das große Meer zu überqueren und die marine Überlegenheit der Allianz anzufechten, verließ sie sich stark auf den Einfallsreichtum der Oger. Das daraus resultierende Fahrzeug – der Oger-Juggernaught – wurde zum Rückgrat der Armada der Horde. Obwohl sie weitaus langsamer und weniger wendig als die schnellen Trollzerstörer waren, trugen diese Ungetüme eine immense Panzerung und verheerende Breitseitenbatterien, die die Rümpfe der Allianz zerschmettern und Küstenbefestigungen in Trümmer legen konnten."},{t="Eiserne Bucht",b="Verborgen unter den Hügeln von Westfall, tief in den unterirdischen Höhlen der Todesminen, liegt die Eiserne Bucht. Dort, abgeschieden von neugierigen Blicken und königlichen Inspektoren, arbeiteten Edwin van Cleefs Handwerker heimlich am Bau eines voll bewaffneten Juggernaughts. Indem sie ein schweres Kriegsschiff in einer unterirdischen Höhle zusammenbauten, die direkt mit dem offenen Meer verbunden ist, planten die Defias, Sturmwinds Überlandverteidigung zu umgehen und einen überraschenden Flottenangriff mitten in das Herz des Königreichs zu führen."}},faq={{q="Was ist ein Juggernaught?",a="Ein Juggernaught ist ein massives, schwer gepanzertes Schlachtschiff, das mit schweren Bombardierungskanonen bewaffnet ist. Ursprünglich von der Horde mit Hilfe von Ogern während des Zweiten Krieges entwickelt, fungiert es als schwimmende Festung, die gebaut wurde, um feindliche Flotten zu überwältigen und Küstenverteidigungen zu zerschmettern.",al={"juggernaut warcraft","orc-schlachtschiff","oger-juggernaut"}},{q="Warum befindet sich ein riesiges Schiff in den Todesminen?",a="Edwin van Cleef und die Bruderschaft der Defias nutzten die abgelegene Höhle der Eisernen Bucht in den Todesminen als versteckte Werft. Der Bau des Juggernaughts unter Tage schützte ihn vor Patrouillen der Allianz, während sie an dem Schiff arbeiteten.",al={"schiff in den todesminen","warum schiff in minen","todesminen schiff"}},{q="Was hatte Edwin van Cleef mit dem Schiff vor?",a="Das Schiff ist Teil von VanCleefs Aktivitäten unter Westfall. Nachforschungen über die Bruderschaft der Defias enthüllen, was er damit vorhatte.",al={"vancleef schiff plan","warum baute die defias ein schiff","zweck des defias-juggernaughts"}},{q="Wer erfand den Juggernaught ursprünglich?",a="Die Alte Horde baute Juggernaughts während des Zweiten Krieges mit der Hilfe von Ogern. Die Orcs hatten wenig Seefahrterfahrung, und diese massiven Kriegsschiffe wurden zur schweren Bewaffnung ihrer Flotte.",al={"wer baute juggernauts","oger-schiffe lore","ursprung der horde-flotte"}},{q="Wie gelangt das Schiff aus der Höhle der Todesminen hinaus?",a="Die Eiserne Bucht ist über einen verborgenen Küstenkanal entlang der felsigen Küste von Westfall mit den offenen Gewässern des Großen Meeres verbunden, was es dem Kriegsschiff ermöglicht, nach seiner Fertigstellung direkt auf den Ozean hinauszusegeln.",al={"wie verlässt das todesminen-schiff die höhle","ausgang der eisernen bucht","todesminen wasserausgang"}},{q="Nutzt die Horde noch immer Juggernaughts?",a="Orcische Schlachtschiffe waren während des Dritten Krieges noch immer als Juggernaughts bekannt. Ihre Rolle bestand darin, die schwere Feuerkraft der Horde-Flotte zu stellen; der gegenwärtige Einsatz solcher Schiffe ist ungewiss.",al={"moderne horde-juggernauts","horde-schlachtschiffe"}}},fx={f4436d36={q="Was ist die Geschichte des Juggernaughts?",a="Juggernaughts wurden erstmals während des Zweiten Krieges gebaut, um als eiserner Kern der Marineflotte der alten Horde zu dienen. Da die Orks wenig Marinetradition besaßen, verließen sie sich stark auf die Handwerkskunst und rohe Gewalt der Oger, um diese gigantischen schwimmenden Festungen zu erschaffen. Bestückt mit schweren Kanonen und dicker Panzerung terrorisierten sie die Meere von Azeroth und fügten der Flotte der Allianz verheerende Verluste zu. Obwohl viele nach der endgültigen Niederlage der Horde versenkt oder aufgegeben wurden, werden überlebende Schiffe und verwertbare Baupläne weiterhin von Gesetzlosen und Kriegsherren gleichermaßen geschätzt.",al={"juggernaught geschichte","woher kamen juggernaughts","juggernaughts zweiter krieg"}}},fp="12,390,24.532.0,13.479.1,23.268.0,46.236.1,51.129.1,41.190.0,50.205.1,39.193.0"}
P.entries["topic:knights-of-the-silver-hand"] = {fx={f98dc644={q="Was ist der Orden der Silbernen Hand?",a="Die Ritter der Silbernen Hand sind ein Orden heiliger Krieger, allgemein bekannt als Paladine. Als militärischer Arm der Kirche des Heiligen Lichts geformt, verbinden sie kriegerische Stärke mit göttlicher Kraft. Ausgerüstet mit schwerer Platte, Kriegshämmern und heiligen Beschwörungsformeln dienen sie als Vorbilder der Tugend, die sich dem Schutz der Unschuldigen, der Heilung der Verwundeten und dem Besiegen des Bösen widmen.",al={"was sind die ritter der silbernen hand","wer ist die silberne hand","paladine der silbernen hand"}},a6d23619={q="Was ist die Geschichte der Ritter der Silbernen Hand?",a="Erzbischof Alonsus Faol gründete den Orden während des Zweiten Krieges, nachdem die Geistlichkeit im Ersten Krieg schwere Verluste erlitten hatte. Er suchte Champions zu schaffen, die an der Front kämpfen konnten, während sie das Licht kanalisierten. Unter Uther der Lichtbringer wendeten die Paladine das Blatt gegen die Horde. Jahrzehntelang verteidigten sie Lordaeron, bis Prinz Arthas während des Dritten Krieges ihre Reihen zerschlug.",al={"geschichte der silbernen hand","wie begann die silberne hand","ursprung der silbernen hand"}},["1db4f553"]={q="Wer führt die Ritter der Silbernen Hand?",a="Dem Orden fehlt ein einzelner oberster Anführer. Lord Uther der Lichtbringer befehligte ursprünglich die Ritter, bis zu seinem tragischen Tod durch Arthas. Hochlord Alexandros Mograine sammelte kurzzeitig die Überlebenden in Lordaeron, bis zu seiner Ermordung. Heute sind die Überreste in Lordaeron zersplittert, während Paladinführer in Sturmwind und Eisenschmiede die Brüder leiten, die unter dem Banner der Allianz kämpfen.",al={"silberne hand anführer","wer befehligt die silberne hand","anführer der paladine"}},["0d7dcf69"]={q="Mit wem sind die Ritter der Silbernen Hand verbündet?",a="Die Silberne Hand wurde gegründet, um die Menschheit zu verteidigen und für die Große Allianz zu kämpfen. Während ihr ursprüngliches nördliches Kapitel während des Dritten Krieges in Ruinen fiel, bleiben aktive Kapitel in Sturmwind und Eisenschmiede standhafte Champions der Nachfolgenationen der Allianz von Lordaeron und kämpfen an der Seite von Menschen, Zwergen und Hochelfen gegen Bedrohungen in ganz Azeroth.",al={"für wen kämpft die silberne hand","silberne hand fraktionen","silberne hand allianz"}}}}
P.entries["topic:kobold"] = {fx={["31a27fce"]={q="Was sind Kobolde?",a="Kobolde sind winzige, rattenartige unterirdische Humanoide, die kaum einen Meter zwanzig groß sind. Berüchtigt für ihre Feigheit und ihren üblen Geruch, bauen sie ihre Häuser, indem sie sich durch Kavernen und verlassene Minen tunneln. Während sie einzeln schwach sind und Angst vor größeren Rassen haben, vermehren sie sich schnell und verlassen sich auf ihre zahlenmäßige Überlegenheit, wenn sie in einen Kampf gezwungen werden, indem sie Eindringlinge mit rohen Bergbauhacken umschwärmen.",al={"was ist ein kobold","wer sind die kobolde","kobold info"}},["427afc17"]={q="Warum findet man Kobolde in so vielen Minen?",a="Kobolde sind natürliche Gräber und Bergleute, die unterirdische Höhlen fernab besiedelter Oberflächen bevorzugen. Sie strömen ganz natürlich zu bereits existierenden Höhlen, Steinbrüchen und reichen Adern. Wenn humanoide Siedlungen Ausgrabungen unbeaufsichtigt oder leicht verteidigt lassen – wie etwa die Minen in Elwynn, Loch Modan und im Steinkrallengebirge –, graben sich opportunistische Kobolde schnell ein, erweitern die Tunnel und beanspruchen die Adern für sich.",al={"warum sind kobolde in minen","koboldminen warum","wo leben kobolde"}},["840836f4"]={q="Warum sind Kobolde feindselig gegenüber Reisenden?",a="Kobolde sind scheu, paranoid und misstrauisch gegenüber allem, was größer ist als sie selbst. Tief unter der Erde fürchten sie ständig Höhleneinstürze, Hunger und die absolute Dunkelheit. Wenn Fremde ihr Territorium betreten, sehen Kobolde sie als unmittelbare Bedrohung, die gekommen ist, um ihre Funde zu stehlen oder ihre kostbaren Kopfkerzen auszulöschen, was sie dazu treibt, in panischen, verzweifelten Mobs anzugreifen.",al={"warum greifen kobolde an","sind kobolde immer feindselig","warum kämpfen kobolde"}}}}
P.entries["topic:kolkar-clan"] = {fx={["0aa5759f"]={q="Woher kommt der Kolkar-Clan?",a="Die Kolkar sind einer der ursprünglichen Zentaurenclans, die in Desolace geboren wurden und ihre Blutlinie auf Khan Kolk zurückführen, den Sohn von Zaetar und Prinzessin Theradras. Lange vor dem Dritten Krieg drangen ihre umherziehenden Kriegstrupps nach Osten in das Brachland vor und vertrieben gewaltsam die nomadischen Tauren von ihren heiligen Jagdgründen. Als Thralls neu angekommene Orks sich mit Cairne Bluthuf verbündeten, zerschlug die vereinte Horde die Zentaurenarmee und ebnete den Weg für die Tauren, sich in Mulgore niederzulassen. Nun, zersplittert über Desolace, Durotar und das Brachland, hegen die Kolkar einen bitteren Groll und führen ständige Territorialkriege, um ihre verlorene Vorherrschaft zurückzugewinnen.",al={"kolkar geschichte","ursprung der kolkar","kolkar clan ursprung"}},a5b3ba08={q="Wie bekam der Kolkar-Clan seinen Namen?",a="Der Clan hat seinen Namen von seinem Gründervater, Khan Kolk. Als der legendäre älteste Sohn des Halbgottes Zaetar und der Erdelementar-Prinzessin Theradras stand Kolk als erster der großen Zentaurenkhans, die ihre brutalen Nachkommen aus Maraudon führten und die kargen Weiten von Zentralkalimdor beanspruchten.",al={"warum heißen sie kolkar","kolkar namensursprung","wer ist kolk"}}}}
P.entries["topic:kul-tiras"] = {n="Kul Tiras",s="Kul Tiras ist ein insulares menschliches Königreich, das auf einem Inselarchipel im Großen Meer liegt, westlich von Dun Morogh und der Baradinbucht. Bekannt dafür, die mächtigste Marine in Azeroth zu besitzen, diente es während des Zweiten Krieges unter Großadmiral Daelin Prachtmeer als ein Eckpfeiler der Allianz von Lordaeron. Nach dem Zerfall der alten Allianz und tragischen Verlusten in Kalimdor hat sich das Inselreich weitgehend in isolierte Gewässer zurückgezogen.",h="Kul Tiras ist ein insulares menschliches Königreich, das auf einem Inselarchipel im Großen Meer liegt...",kw={"allianz von lordaeron","daelin prachtmeer","großes meer","jaina prachtmeer","kul tiras","tiragarde"},ang={["faction:Alliance"]="Die Allianz von Lordaeron verdankte ihr Überleben zur See der Flotte von Kul Tiras, obwohl die Inselnation nach den Verlusten des Dritten Krieges derzeit distanziert und wachsam bleibt.",["faction:Horde"]="Kul Tiraner Seeleute unter Admiral Prachtmeer kämpften im Zweiten Krieg erbittert gegen die Horde und griffen später Thralls neue Heimat in Durotar an, was eine anhaltende Blutfehde vertiefte.",["profession:Mining"]="Die Werften von Kul Tiras verwandeln große Mengen an Metall in die gepanzerten Kriegsschiffe der mächtigsten Marine in Azeroth.",["race:Human"]="Die Kul Tiraner entwickelten eine ausgeprägte, widerstandsfähige Inselkultur, die für Schiffbau, Handel und Standhaftigkeit gegenüber dem offenen Ozean bekannt ist."},sec={{t="Eine Nation, die dem Meer entsprang",b="Kul Tiras blühte zu einer unerreichten Seemacht auf, gestützt durch eine fleißige Handelsmarine, reiche Fischgründe und eine Marineflotte, die in der menschlichen Geschichte ihresgleichen sucht."},{t="Der Zweite Krieg und die Isolation",b="Als die Orcische Horde durch die Östlichen Königreiche fegte, folgte Kul Tiras dem Ruf von König Terenas Menethil II. und unterstellte seine Flotte der Allianz von Lordaeron. Großadmiral Daelin Prachtmeer befehligte die Seestreitkräfte der Menschheit und führte blutige Kämpfe auf dem offenen Ozean, um die Seewege der Horde abzuschneiden und die Küsten zu schützen. Doch nach dem Ende des Krieges und der schließlich erfolgten Zersplitterung der nördlichen Königreiche zog Kul Tiras seine Flotten zurück und begab sich in eine Phase starker Küstenverteidigung und stiller Isolation."},{t="Schatten über den Prachtmeers",b="Kul Tiras hat den bitteren Stich ferner Kriege über das Meer hinweg gespürt. Als Lady Jaina Prachtmeer Flüchtlinge über den Ozean nach Kalimdor führte, um Theramore zu errichten, segelte ihr Vater, Großadmiral Daelin Prachtmeer, auf der Suche nach ihr nach Kalimdor und startete dann einen Feldzug gegen die Horde. Sein Kreuzzug brachte Verderben und endete mit seinem Tod in Theramore."}},faq={{q="Wo befindet sich Kul Tiras?",a="Kul Tiras ist ein Archipel, das weit draußen im Großen Meer liegt, westlich der Baradinbucht und der Küste von Dun Morogh. Es ist eine raue, kalte und gebirgige Inselgruppe, die durch massive Seemauern und starke Küstengarnisonen befestigt ist.",al={"wo liegt kul tiras","kul tiras karte","kul tiras standort"}},{q="Ist Kul Tiras immer noch Teil der Allianz?",a="Kul Tiras war eine der Gründungsnationen der ursprünglichen Allianz von Lordaeron. Da die alte Allianz jedoch zerbrach, hat sich das Inselkönigreich weitgehend aus kontinentalen Angelegenheiten zurückgezogen und bewahrt eine Haltung strenger Isolation.",al={"ist kul tiras bei der allianz","kul tiras mitglied der allianz"}},{q="Wer regiert Kul Tiras?",a="Großadmiral Daelin Prachtmeer führte die Nation jahrzehntelang, bis sein schicksalhafter Feldzug in Kalimdor mit seinem Tod in Theramore endete.",al={"anführer von kul tiras","wer führt kul tiras an","könig von kul tiras"}},{q="Warum ist Kul Tiras in ganz Azeroth berühmt?",a="Kul Tiras ist legendär für die größte maritime Flotte, Schiffsbauer und Seeleute in der bekannten Welt. Seine Kriegsschiffe und riesigen Handelskonvois beherrschen seit Jahrhunderten die Seewege, und seine Marine war entscheidend dafür, die Horde während des Zweiten Krieges aufzuhalten.",al={"wofür ist kul tiras bekannt","warum ist kul tiras berühmt"}},{q="Wie ist Kul Tiras mit Jaina Prachtmeer verbunden?",a="Lady Jaina Prachtmeer ist eine Tochter von Kul Tiras, da sie das Kind von Großadmiral Daelin Prachtmeer ist. Obwohl sie in die herrschende Familie ihrer Heimat geboren wurde, studierte sie in Dalaran und gründete später den unabhängigen Hafen Die Insel Theramore in Kalimdor, was sie von der Führung ihrer Heimat distanzierte.",al={"jaina kul tiras","stammt jaina aus kul tiras"}},{q="Welche Bedrohungen gibt es für Kul Tiras?",a="Jenseits ihrer tief verwurzelten Feindschaft gegenüber der Horde werden die Gewässer um Kul Tiras ständig von abtrünnigen Piratenmannschaften und feindseligen Küstenbestien geplagt, was ständige Wachsamkeit und befestigte Seeschleusen erfordert, um die Schifffahrtswege zu schützen.",al={"kul tiras feinde","bedrohungen für kul tiras"}}},fx={["31ee9d0a"]={q="Was ist Kul Tiras?",a="Kul Tiras ist eine Inselnation und ein Archipel im großen Meer westlich der Östlichen Königreiche. Bekannt für ihre beispiellose maritime Meisterschaft und Handelsschiffe, bauten die Menschen von Kul Tiras eines der sieben historischen menschlichen Königreiche auf. Sie befehligen die mächtigste Marineflotte der Welt, die auf einer langen Tradition des Schiffbaus, der Fischerei und der Erkundung des offenen Ozeans basiert.",al={"was ist kul tiras","kul tiras königreich","kul tiras nation"}},db90478b={q="Was ist die Geschichte von Kul Tiras?",a="Kul Tiras entwickelte sich zu einer mächtigen Seenation, deren Handelswege die ganze Welt erreichten. Sie stellte während des Zweiten Krieges unter Daelin Prachtmeer die zentrale Marinestärke der Allianz.",al={"geschichte von kul tiras","wie wurde kul tiras gegründet","kul tiras ursprung"}}},fp="9,441,24.171.0,28.532.0,28.347.1,27.223.0,40.239.0,20.132.0,39.265.0,47.292.0,28.231.0"}
P.entries["topic:leper-gnome"] = {fx={e1b9c7cf={q="Was sind Aussätzige Gnome?",a="Aussätzige Gnome sind Gnome, die durch die giftige Strahlung, die in Gnomeregan freigesetzt wurde, deformiert, krank und wahnsinnig geworden sind. Gekennzeichnet durch blasse, grünliche, mit Läsionen bedeckte Haut und gewalttätige Instabilität, sind die meisten zu geistesgestörten Elenden verkommen, die durch die ruinierten Hallen ihrer ehemaligen Hauptstadt wandern, völlig abgeschnitten von der zivilisierten Gnomengesellschaft.",al={"was ist ein aussätziger gnom","wer sind aussätzige gnome","aussätziger gnom info"}},["7550d48d"]={q="Warum werden sie Lepragnome genannt?",a="Ihren Namen verdanken sie ihrem kränklichen, verrottenden Erscheinungsbild. Schwere Strahlenbelastung durch radioaktive Abfälle hinterließ ihre Haut verfärbt, schälend und mit abscheulichen Wunden und Läsionen übersät, was an die Leiden der klassischen Lepra erinnert. In Verbindung mit ihrem langsamen körperlichen und geistigen Verfall spiegelt der Titel ihren tragisch erkrankten Zustand wider.",al={"warum lepragnome","bedeutung name lepragnome","warum heißen sie lepragnome"}}}}
P.entries["topic:lich-king"] = {n="Lichkönig",s="Der Lichkönig ist der Herr und geistige Gebieter der untoten Geißel, der vom Frostthron weit im Norden in Eiskrone herrscht. Ursprünglich wurde das Wesen vom Dämon Kil'jaeden aus dem Geist des Ork-Schamanen Ner'zhul geschmiedet. Später lockte es Prinz Arthas Menethil in die Verderbnis, was in ihrer schicksalhaften Vereinigung auf den eisigen Gipfeln von Nordend gipfelte.",h="Der Lichkönig ist der Herr und geistige Gebieter der untoten Geißel, der vom Frostthron weit im Norden in...",kw={"arthas","kult der verdammten","frostgram","frostthron","helm der herrschaft","eiskrone","kiljaeden","lichkönig","nerzhul","geißel"},ang={["class:Paladin"]="Der Orden der Silbernen Hand wurde durch die verderbende Macht des Lichkönigs zerschlagen, die ihren größten Champion in einen Todesritter verwandelte, der Uther den Lichtbringer niederstreckte.",["class:Priest"]="Die Geißel stellt eine düstere Perversion der Heiligkeit des Lichts dar und erinnert Anhänger des Lichts an den schrecklichen Preis, der in den gefallenen Pfarreien von Lordaeron gezahlt wurde.",["race:Human"]="Für Menschen stellt der Lichkönig die ultimative Tragödie dar: Prinz Arthas, Erbe des Throns von Lordaeron und Paladin der Silbernen Hand, ermordete seinen eigenen Vater und vernichtete sein Königreich im Namen dieses Wesens.",["race:Undead"]="Die Verlassenen existieren nur, weil der telepathische Griff des Lichkönigs nachließ, und Königin Sylvanas treibt ihr Volk mit brennendem Hass gegen ihren ehemaligen Meister im gefrorenen Norden an."},sec={{t="Geburt des Frostgottes",b="Als der Ork-Schamane Ner'zhul versuchte, von der sterbenden Welt Draenor zu fliehen, fiel er direkt in die Fänge von Kil'jaeden dem Betrüger. Der Dämonenfürst zerfetzte Ner'zhuls Körper, band aber seine gequälte Seele in einen Block aus diamanthartem Eis, der aus dem Wirbelnden Nether geschleudert wurde. Der Gletscher-Monolith schlug in Azeroth ein, in den nördlichen Einöden von Nordend, und bildete den Frostthron. Kil'jaeden wollte, dass der Lichkönig eine unaufhaltsame untote Vorhut schmiedet, die die sterblichen Königreiche zerschlagen würde, ohne den internen Kämpfen zu unterliegen, die die Orkische Horde ruiniert hatten. Stattdessen begann Ner'zhul, ausgerüstet mit immenser telepathischer Kraft, sofort, seinen eigenen Weg in die Freiheit zu planen."},{t="Der Fall von Lordaeron",b="Beobachtende Schreckenslords hielten das Wesen streng unter Bewachung, was Ner'zhul dazu zwang, im Geheimen zu handeln. Mit seinem Geist erreichte er den verbannten Erzmagier der Kirin Tor, Kel'Thuzad, der in Lordaeron den Kult der Verdammten gründete. Durch Kessel mit verseuchtem Getreide entfesselte die Geißel die Pest des Untodes über die nördlichen Königreiche. Die Krise zog Prinz Arthas Menethil mit hinein, dessen Verzweiflung, sein Volk zu retten, ihn zu rücksichtsloser Brutalität führte, die im berüchtigten Massaker von Stratholme gipfelte. Geblendet von Rachegelüsten gegen den Schreckenslord Mal'Ganis, verfolgte Arthas sein Ziel bis nach Nordend, wo die verfluchte Runenklinge Frostgram darauf wartete, seine Seele zu stehlen und ihn zum wichtigsten Todesritter der Geißel zu machen."},{t="Verrat und Aufstieg",b="Obwohl der Lichkönig gezwungen war, Archimonde herbeizurufen und das vorübergehende Kommando an die Brennende Legion abzugeben, sah er die Hybris der Dämonen voraus. Arthas manipulierte den Dämonenjäger Illidan Sturmgrimm dazu, den Schädel von Gul'dan an sich zu nehmen und Tichondrius zu erschlagen, was letztlich zu Archimondes Untergang am Hyjal beitrug. Im Nachhinein beauftragte ein verzweifelter Kil'jaeden Illidan damit, den Frostthron zu zerstören. Als Risse in der eisigen Turmspitze Ner'zhuls Macht schwächten – was es Sylvanas Windläufer und ihren Verlassenen ermöglichte, sich zu befreien – rief der Lichkönig seinen Champion heim. Arthas kehrte nach Nordend zurück, besiegte Illidan am Fuße von Eiskrone, bestieg die Spitze und zerschlug das Eis, um mit Ner'zhul zu einem einzigen schrecklichen Bewusstsein zu verschmelzen."}},faq={{q="Wer ist der Lichkönig momentan?",a="Der Lichkönig ist das verschmolzene Wesen aus Prinz Arthas Menethil und dem Ork-Schamanen Ner'zhul. Arthas zerschlug das eisige Gefängnis auf dem Frostthron in Eiskrone und setzte den Helm der Herrschaft auf, wodurch er seine sterbliche Hülle und seine dunkle Seele mit dem Geist von Ner'zhul zu einem einzigen absoluten Herrscher der Geißel vereinte.",al={"derzeitiger lichkönig","wer herrscht über die geißel","ist arthas der lichkönig"}},{q="Warum erschuf ihn die Brennende Legion?",a="Kil'jaeden erschuf den Lichkönig, um die Verteidiger von Azeroth vor einer vollständigen dämonischen Invasion zu schwächen. Die vorherige Invasion scheiterte aufgrund von internen Streitigkeiten innerhalb der sterblichen Orkischen Horde; eine telepathisch kontrollierte Armee der Toten versprach absoluten Gehorsam und die völlige Erschöpfung der sterblichen Armeen.",al={"warum wurde der lichkönig erschaffen","ziel von kiljaeden","ursprung der geißel und legion"}},{q="Wo befindet sich der Lichkönig?",a="Er sitzt auf dem Frostthron auf dem eisigen Gletscher von Eiskrone, tief im entlegenen und gefrorenen Kontinent Nordend, weit jenseits des Großen Meeres, nördlich von Lordaeron.",al={"wo ist der frostthron","standort des lichkönigs","wo lebt er"}},{q="Wie konnte sich Sylvanas aus seiner Kontrolle befreien?",a="Als Illidan Sturmgrimm den Frostthron mit mächtiger Magie angriff, zerbrach das magische Eis und die Macht des Lichkönigs begann zu entweichen. Als sein telepathischer Griff schwächer wurde, erlangte eine Fraktion der Untoten ihren freien Willen zurück, schloss sich unter Sylvanas Windläufer zusammen und gründete die Verlassenen.",al={"wie haben sich die verlassenen befreit","warum ist sylvanas frei","kontrollverlust der geißel"}},{q="Was ist Frostgram?",a="Frostgram ist die verfluchte, seelenfressende Runenklinge, die vom Frostthron ausgesandt wurde, um einen sterblichen Champion anzulocken. Sie lockte Prinz Arthas Menethil dazu, sie in Nordend an sich zu nehmen, verschlang die Seele des Prinzen und verwandelte ihn in den wichtigsten Todesritter der Geißel.",al={"welches schwert benutzte arthas","hintergrund zu frostgram","runenklinge"}},{q="Wer war Ner'zhul?",a="Ner'zhul war ein älterer Ork-Schamane von Draenor. Als er versuchte, durch Dimensionsrisse von seiner sterbenden Heimatwelt zu fliehen, wurde er vom Dämon Kil'jaeden gefangen genommen, der sein Fleisch von ihm riss und seinen Geist zu dem allsehenden Bewusstsein formte, das zum Lichkönig wurde.",al={"hintergrund zu nerzhul","wer war nerzhul","ursprünglicher lichkönig"}}},fx={["66564786"]={q="Warum sind der Lichkönig und seine Geißel allen lebenden Reisenden gegenüber feindselig?",a="Der Lichkönig strebt die völlige Auslöschung und Unterwerfung des sterblichen Lebens an. Jedes lebende Wesen, das durch seine Seuche oder seine unheiligen Legionen erschlagen wird, kann unter seinem absoluten geistigen Befehl wiederbelebt werden, was seine Macht exponentiell erweitert. Er sieht die sterblichen Völker nicht als Nachbarn, sondern als Rohmaterial, um seine ewige Geißel zu vergrößern.",al={"warum ist der lichkönig feindselig","feindseligkeit der geißel","warum greift der lichkönig die lebenden an"}},b2423b94={q="Wer ist mit dem Lichkönig verbündet?",a="Der Lichkönig arbeitet mit keinen lebenden Nationen zusammen. Er befehligt die untote Geißel direkt durch psychische Beherrschung, unterstützt von sterblichen Nekromanten und Fanatikern im Kult der Verdammten wie Kel'Thuzad. Obwohl er vom Dämonenfürsten Kil'jaeden erschaffen wurde, verriet er im Geheimen die Brennende Legion, um seine eigene absolute Herrschaft über Azeroth zu verfolgen.",al={"verbündete des lichkönigs","wer arbeitet für den lichkönig","wem dient der lichkönig"}}},fp="9,344,23.676.0,21.713.0,24.730.0,31.301.0,38.296.0,31.167.0,45.283.0,20.268.0,17.265.0"}
P.entries["topic:light"] = {n="Licht",s="Das Licht ist eine grenzenlose, urzeitliche kosmische Kraft, deren Energie alle Lebewesen in der gesamten Schöpfung miteinander verbindet und durchdringt. In der sterblichen Welt als Heiligmagie manifestiert, reagiert es auf Willenskraft, Meditation und unerschütterlichen Glauben, um Fleisch zu heilen, Verbündete zu beschützen und Dunkelheit zu läutern.",h="Das Licht ist eine grenzenlose, urzeitliche kosmische Kraft, deren Energie alle Lebewesen in der gesamten...",kw={"an'she","kirche","elune","glaube","heilung","heiliges licht","heiligmagie","licht","paladin","priester","geißel"},ang={["class:Paladin"]="Paladine wirken nicht bloß Zauber; sie erfüllen ihre kriegerische Disziplin und sterblichen Körper mit dem Licht und führen seinen glühenden Zorn gegen die Geißel und dämonisches Unheil.",["class:Priest"]="Priester dienen als spirituelle Hirten und Leitmedien, die tiefe Meditation und Gebete praktizieren, um Fleisch zu heilen, gebrochene Seelen aufzurichten und Verbündete zu beschützen.",["faction:Alliance"]="Die Kirche des Heiligen Lichts bildet das spirituelle Fundament von Sturmwind und Eisenschmiede und spendet Hoffnung in einer Ära, die durch den Fall von Lordaeron verdunkelt wurde.",["race:NightElf"]="Nachtelfen kanalisieren heilige Energie nicht durch kirchliche Doktrin, sondern durch die Verehrung der Mondgöttin Elune und ihres silbernen Lichts.",["race:Tauren"]="Tauren verehren An'she, das goldene rechte Auge der Erdenmutter, im Rahmen ihrer traditionellen Sonnenanbetung.",["race:Undead"]="Für die Verlassenen bringt das Kanalisieren des Lichts oder das Empfangen seiner Heilung heftige Schmerzen mit sich, selbst wenn der Zauber ihre Körper heilt."},sec={{t="Eine urzeitliche Kraft",b="Das Licht ist eine allgegenwärtige Kraft lebendiger Energie. Wenn es nach Azeroth gebracht wird, manifestiert es sich als Heiligmagie. Seine Macht strömt als verbindendes Band durch lebendige Seelen und eint sterbliche Herzen. Während Sterbliche es oft als bewussten Beschützer personifizieren, antwortet das Licht im Grunde der absoluten Überzeugung der Seele, die es anruft."},{t="Werkzeuge des Glaubens",b="Das Kanalisieren des Lichts erfordert intensive Selbstaufgabe, disziplinierte Meditation und unerschütterliche Willenskraft. Seine Ausüber – allen voran die Priester der Kirche des Heiligen Lichts und die heiligen Paladine – trainieren jahrelang, um zu klaren, leeren Gefäßen für seinen Glanz zu werden. Durch ihre Hingabe manifestiert sich das Licht als heilende Wärme, um sterbliche Wunden zu schließen, als strahlender Schutz, um die Unschuldigen zu behüten, oder als sengendes Feuer, um Dämonen und die auferstandenen Untoten niederzustrecken."},{t="Viele Gesichter des Glanzes",b="Während die Menschheit und die Zwerge das Licht durch formelle Schriften verehren, greifen andere Kulturen durch verschiedene spirituelle Traditionen auf seinen Glanz zu. Die Nachtelfen kanalisieren heiliges Mondlicht durch die Hingabe an die Göttin Elune und weben Heiligmagie, die reinigt und beschützt. Die Tauren ehren die Sonnengottheit An'she in ihren eigenen spirituellen Traditionen."}},faq={{q="Was ist das Licht?",a="Das Licht ist eine fundamentale kosmische Energie, die in der gesamten Schöpfung existiert. Es ist die urzeitliche Quelle von Leben und positiver Energie, die fühlende Seelen miteinander verbindet. Sterbliche rufen es an, um Heiligmagie zur Heilung, zum Schutz und für den Kampf hervorzubringen.",al={"wissen über das heilige licht","was ist das heilige licht","das licht erklärt"}},{q="Besitzt das Licht einen bewussten Willen oder Verstand?",a="Das Licht ist eher eine urzeitliche kosmische Kraft als ein Gott. Während Sterbliche häufig vom „Willen des Lichts“ sprechen und es als leitenden Schutzherrn betrachten, besitzt es keine sterbliche Moral. Es reagiert direkt auf die Gewissheit, Willenskraft und den Glauben des Zaubernden.",al={"lebt das licht","hat das licht ein bewusstsein","ist das licht ein gott"}},{q="Warum können böse Fanatiker das Licht dennoch nutzen?",a="Weil das Licht auf Überzeugung antwortet, nicht auf abstrakte Rechtschaffenheit. Wenn ein Zaubernder den absoluten Glauben daran besitzt, dass seine Sache gerecht ist, und sein Geist ungeteilt bleibt, wird das Licht durch ihn fließen – selbst wenn seine Taten rücksichtslos oder fehlgeleitet sind.",al={"warum hat der scharlachrote kreuzzug das licht","können bösewichte das licht nutzen","böse paladine licht"}},{q="Wie wirkt sich das Licht auf Untote aus?",a="Heiligmagie ist eine mächtige Waffe gegen die Geißel, kann aber auch untote Körper heilen. Das Kanalisieren des Lichts oder das Empfangen seiner Heilung fügt Untoten intensive Schmerzen zu; es verbrennt jedoch nicht automatisch ihr Fleisch.",al={"licht gegen untote","warum schmerzt das licht die geißel","können untote das licht nutzen"}},{q="Wie lernen Priester und Paladine, es zu führen?",a="Das Führen des Lichts erfordert strenge geistige Disziplin, emotionale Klarheit und jahrelange Meditation. Der Zaubernde muss sein persönliches Ego zum Schweigen bringen und seinen Geist vollkommen fokussieren, um als klares Leitmedium zu wirken, durch das sich die Heiligmagie in die Realität ergießen kann.",al={"wie man heiligmagie nutzt","magiequelle der paladine","priester lichtausbildung"}},{q="Ist Elunes Magie mit dem Licht verbunden?",a="Ja. Das von den Priesterinnen der Elune kanalisierte Mondlicht manifestiert sich als eine Form von Heiligmagie und teilt dieselben wiederherstellenden, schützenden und reinigenden Eigenschaften wie die von Paladinen und Kirchenpriestern gewirkten Zauber.",al={"ist elune heiligmagie","elune und das licht","mondlicht heiliges licht"}}},fx={["73e6193d"]={q="Woher kam das Licht?",a="Seine wahren Ursprünge sind unbekannt. Priester der Church of the Holy Light lehren, dass das Licht in allen Lebewesen weilt, doch woher das Licht selbst stammt, bleibt ein Geheimnis.",al={"ursprung des lichts","woher kam das licht","wie wurde das licht erschaffen","geschichte des heiligen lichts"}}},fp="5,269,14.343.0,20.457.0,22.350.0,18.240.0,45.257.0,41.245.0,37.211.0,46.251.0,40.214.0"}
P.entries["topic:lordaeron"] = {fx={ca72f255={q="Was ist die Geschichte von Lordaeron?",a="Ursprünglich von Menschenstämmen nach der Ära des Imperiums von Arathor besiedelt, wuchs Lordaeron zu einem der mächtigsten Königreiche der Menschheit heran und gab dem gesamten nördlichen Kontinent seinen Namen. Über Generationen hinweg umfasste sein Reich reiches Ackerland und starke Städte und diente während des Zweiten Krieges als das Bollwerk der Allianz. Dieser Ruhm zerfiel im Dritten Krieg, als die Geißel die Seuche des Untodes über seine Ländereien brachte, das Königreich zerriss und seine einst blühenden Gebiete zu den verheerten Pestländern und umkämpften Ruinen reduzierte, die Ihr heute seht.",al={"geschichte von lordaeron","lore von lordaeron","woher stammt lordaeron"}}}}
P.entries["topic:mage"] = {n="Magier",s="Magier sind gelehrte Zauberwirker, die das Gefüge der Realität durch arkane Studien beugen, zerstörerisches Feuer schleudern, Frost beherrschen und reine arkane Energie lenken. Obwohl sie körperlich zerbrechlich und nur in Stoff gehüllt sind, machen ihre Meisterschaft über Teleportation, Beschwörung und Massenkontrolle auf dem Schlachtfeld sie zu formidablen Verbündeten und furchterregenden Feinden. Ihre Disziplin erfordert immense geistige Hingabe und balanciert immenses zerstörerisches Potenzial gegen die verhängnisvolle Geschichte des arkanen Missbrauchs aus.",h="Magier sind gelehrte Zauberwirker, die das Gefüge der Realität durch arkane Studien beugen, zerstörerisches...",kw={"arkan","beschwörung","dalaran","feuer","frost","kirin tor","magier","magus","mana","zauberwirker","teleportieren","zauberer"},ang={["class:Mage"]="Euer Handwerk ist eines von akribischer intellektueller Disziplin, das Feuer, Frost und arkane Macht meistert, während Ihr das fragile Gleichgewicht der Realität bewahrt.",["class:Paladin"]="Während Ihr an der Seite von Magi auf dem Schlachtfeld kämpft, betrachten die Ritter der Silbernen Hand deren weltliche arkane Methoden seit Langem mit tiefer Vorsicht.",["class:Warlock"]="Viele Hexenmeister begannen ihre Reise als Magier, bevor sie akademische Zurückhaltung und strenge Erlasse von Dalaran auf der Suche nach dämonischer Macht aufgaben.",["race:Human"]="Das arkane Erbe der Menschheit geht auf die hundert ursprünglichen Magi zurück, die während der Trollkriege ausgebildet wurden und deren Nachkommen Dalaran zu einem großen Zentrum magischer Studien ausbauten.",["race:NightElf"]="Die kaldoreische Gesellschaft meidet arkane Magie strikt und erinnert sich nur zu gut daran, wie Königin Azshara und ihre hochgeborenen Magi das uralte Kalimdor ins Verderben stürzten.",["race:Orc"]="Orc-Magier beginnen ihre Studien unter der Dunkelspeermagierin Mai'ah im Tal der Prüfungen, die vor der Macht Geduld und sorgfältiges Urteilsvermögen lehrt.",["race:Skyborne"]="Skyborne-Magier des Hohen Ordens trachten danach, die hochgeborene Zauberkunst wiederzuerlangen, die ihre Vorfahren aus Eldre'Thalas mitbrachten, in der Hoffnung, dass sie ihre verfallende Insel retten kann."},sec={{t="Gelehrte des Arkanen",b="Der Pfad des Magiers verlangt Intellekt, Konzentration und jahrelanges unerbittliches Studium. Anstatt mit Geistern zu kommunizieren oder sich auf göttlichen Glauben zu verlassen, behandeln Magi die Magie als eine präzise kosmische Wissenschaft. Indem ein Ausübender arkane Energien anzapft, kann er rohe Zerstörungskraft weben, sengende Feuersbrünste herbeirufen oder die umgebende Luft zu festem Eis und heulenden Schneestürmen gefrieren lassen. Da schwere Rüstung die feinen somatischen Gesten und die geistige Konzentration stört, die für Beschwörungsformeln erforderlich sind, tragen Magier leichten Stoff und verlassen sich stattdessen auf Schutzbannzauber, Manabarrieren und Ausweichzauber, um sich zu schützen."},{t="Das Erbe von Dalaran und Arathor",b="Das magische Erbe der Menschen begann vor fast drei Jahrtausenden während der Trollkriege, als hochelfische Zauberer einhundert Menschen des Reiches von Arathor unterwiesen, um das Blatt gegen die Amani zu wenden. Als sich die Zahl der menschlichen Ausübenden vervielfachte, trieben ängstliche weltliche Bürger viele Magi dazu, die Magokratie Dalaran zu gründen. Unter der Führung der Kirin Tor wurde Dalaran zum zentralen Archiv magischer Studien für die nördlichen Königreiche und formalisierte die Traditionen der Kampfmagie, die später die Allianz von Lordaeron durch den Ersten und Zweiten Krieg hindurch unterstützten."},{t="Argwohn und Notwendigkeit",b="Arkane Ausübende genossen nie unkompliziertes Vertrauen. Von der uralten Katastrophe, die von den Hochgeborenen herbeigeführt wurde, bis zum katastrophalen Fall Dalarans während des Dritten Krieges weckt die volatile Natur der Magie weitverbreitetes Misstrauen. Die Kirche des Heiligen Lichts begegnete der Zauberei historisch mit Skepsis, und konservative Ritter betrachteten arkane Zauberkundige oft als verdammte Seelen oder als notwendiges Übel auf dem Schlachtfeld. Trotz dieses Argwohns erkennen zivile und militärische Führer an, dass ein fähiger Magus unschätzbare Überlegenheit auf dem Schlachtfeld, schnelle Massenbeförderung und unverzichtbare Gegenmaßnahmen gegen übernatürliche Bedrohungen bietet."},{t="Magier der Horde und des Hohen Ordens",b="Das Arkane gehört nicht der Allianz allein. Trolle und Magier der Verlassenen dienen der Horde, und Orcs, die sich der Kunst widmen, beginnen unter der Dunkelspeermagierin Mai'ah im Tal der Prüfungen, die lehrt, dass Geduld und sorgfältiges Urteilsvermögen wichtiger sind als rohe Macht. Unter den Skyborne stammt Der Hohe Orden von den Hochgeborenen aus Eldre'Thalas ab. Ihre Zeitalter im Himmelswall kosteten sie einen Großteil des arkanen Wissens ihrer Vorfahren, und da die Windgeister von der Insel Zephras verschwunden sind, trachten sie danach, es wiederzuerlangen. Magier der Skyborne kämpfen für die Allianz."}},faq={{q="Auf welche Magieschulen sind Magier spezialisiert?",a="Magier konzentrieren sich auf drei Kernschulen: Arkan, Feuer und Frost. Arkane Magie verändert Zeit, Raum und Realität und ermöglicht Verwandlung, Teleportation sowie konzentrierte Entladungen reiner Macht. Feuerzauber konzentrieren sich auf schnellen, überwältigenden Verbrennungsschaden, um Ziele einzuäschern. Frostmagie verlangsamt, fesselt und zerschmettert Feinde und bietet entscheidende Kontrolle auf dem Schlachtfeld, um Gegner daran zu hindern, in den Nahkampf überzugehen.",al={"magier-spezialisierungen","magier-magiearten","arkan feuer frost"}},{q="Warum tragen Magier nur Stoffrüstung?",a="Das Wirken komplexer Zauber erfordert ungehinderte körperliche Bewegung, präzise Handgesten und ununterbrochene geistige Konzentration. Schwere Materialien wie Leder, Kettenhemd oder Platte stören die somatischen Komponenten und die Lenkung magischer Energie eines Zauberwirkers. Um ihre körperliche Verwundbarkeit auszugleichen, setzen Magi magische Barrieren, Frostschilde und Zauber ein, die Feinde auf Distanz halten.",al={"warum stoff","magier rüstungsart","können magier leder tragen"}},{q="Wie lernten die Menschen erstmals, arkane Magie zu wirken?",a="Während der uralten Trollkriege vor etwa 2.800 Jahren verbündete sich das menschliche Reich von Arathor mit den Hochelfen von Quel'Thalas gegen die Amani-Trolle. Im Austausch für militärische Hilfe bildeten elfische Magi einhundert Menschen in den Grundlagen des Arkanen aus. Diese ursprünglichen hundert Pioniere erwiesen sich in der Schlacht als verheerend und begründeten die menschliche magische Linie, die schließlich Dalaran hervorbrachte.",al={"erste menschliche magier","trollkriege magier","ursprung der menschlichen magie"}},{q="Wie ist das Verhältnis zwischen Magiern und der Kirche des Heiligen Lichts?",a="Das Verhältnis ist angespannt. Jahrhundertelang betrachteten orthodoxe Mitglieder der Kirche des Heiligen Lichts arkane Studien und die Kirin Tor mit Argwohn und behandelten sie mitunter als ketzerisch. Paladine und fromme Priester halten Zauberei oft für eine unberechenbare, moralisch zweifelhafte Praxis, die jedoch aufgrund ihrer strategischen militärischen Macht aus Notwendigkeit akzeptiert wird.",al={"haltung der kirche zu magiern","paladine und magier","heiliges licht arkane häresie"}},{q="Gehören die Magier von Sturmwind zu Dalarans Kirin Tor?",a="Historisch gesehen hatte Sturmwind seine eigenen Traditionen, die ursprünglich von Hofbeschwörern angeführt wurden, welche weitgehend unabhängig von Dalaran agierten. Während Dalarans Kirin Tor das unbestrittene Zentrum magischer Gelehrsamkeit im Norden war, entwickelten die Zauberer des Südens ihre eigenen Enklaven und königlichen Beraterrollen, wenngleich Kommunikation und gemeinsame Bande über beide Reiche hinweg fortbestanden.",al={"sturmwinder magier dalaran","beschwörer von azeroth","sturmwinder zauberer"}},{q="Können Magier Nahrung erschaffen und Personen augenblicklich transportieren?",a="Ja. Neben zerstörerischen Zaubern verfügen Magier über umfangreiche Hilfsmagie. Sie können arkane Energie weben, um frische Nahrung und frisches Wasser aus dem Nichts herbeizuzaubern, den Intellekt von Verbündeten zu verzaubern und den Raum krümmen, um augenblicklich Portale zu öffnen, die bedeutende Städte auf der ganzen Welt miteinander verbinden.",al={"magier-nützlichkeit","magierportale","wasser und brot herbeizaubern"}},{q="Welche Völker können Magier sein?",a="Menschen, Gnome und die Skyborne bilden sich für die Allianz als Magier aus, und Trolle, die Verlassenen sowie Orcs tun dies für die Horde. Zwerge, Nachtelfen und Tauren tun dies nicht; die Nachtelfen meiden das Arkane nach dem Verderben, das Königin Azsharas Hochgeborene über das uralte Kalimdor brachten.",al={"wer kann magier werden","magiervölker","können orcs magier werden","orc-magier","himmelsgeborener magier"}}},fp="4,472,22.574.0,33.567.0,23.632.0,37.516.0,45.398.0,35.380.0,48.389.0,72.354.0,50.349.0,53.257.0,25.260.0"}
P.entries["topic:medivh"] = {n="Medivh",s="Medivh war der letzte Wächter von Tirisfal, ein uralter Orden, der damit betraut war, Azeroth vor dämonischer Verderbnis zu beschützen. Noch vor seiner Geburt durch den Geist des Dunklen Titanen Sargeras gebunden, öffnete er das Dunkle Portal und brachte die orkische Horde in die Welt, was jahrzehntelange verheerende Kriege auslöste.",h="Medivh war der letzte Wächter von Tirisfal, ein uralter Orden, der damit betraut war, Azeroth vor dämonischer...",kw={"aegwynn","atiesh","das dunkle portal","wächter","karazhan","khadgar","lothar","medivh","sargeras","tirisfal"},ang={["class:Mage"]="Medivh verkörpert sowohl den Zenit als auch die ultimative Gefahr arkaner Meisterschaft; jeder Gelehrte der Kirin Tor studiert seinen verheerenden Fall als mahnendes Beispiel ungezügelter Macht.",["class:Warlock"]="Medivhs Zwiesprache mit Gul'dan und seine Rolle als sterbliches Gefäß für Sargeras bleiben legendäre Demonstrationen von Teufelsbeschwörung und interplanarer Manipulation.",["faction:Alliance"]="Das Volk von Sturmwind blickt mit bitterer Trauer auf Medivh und erinnert sich an ihn als geliebten königlichen Gefährten, der letztlich die zerstörerische Horde in ihre Länder einlud.",["faction:Horde"]="Für Thralls Horde ist Medivh jener menschliche Zauberer, dessen Pakt mit Gul'dan das Dunkle Portal öffnete und die Orks einst in diese Welt brachte."},sec={{t="Ein verfluchtes Erbe",b="Medivh wurde als Sohn der mächtigen Wächterin Aegwynn und des Hofbeschwörers Nielas Aran geboren. Jahrhunderte zuvor hatte Aegwynn in Northrend gegen den gefallenen Titanen Sargeras gekämpft, ohne zu ahnen, dass seine dunkle Essenz in ihren Körper schlüpfte, um auf einen Erben zu warten. Als Medivh seinen vierzehnten Geburtstag erreichte, manifestierte sich das gewaltige magische Erbe seiner Mutter in einer furchterregenden Explosion von Macht, die den Jungen unter der Obhut der Kleriker in der Abtei von Nordhain in ein jahrzehntelanges Koma stürzte."},{t="Der Fall von Karazhan",b="Aus seinem Schlummer erwacht, ließ sich Medivh im abgelegenen Turm von Karazhan nieder und diente seinem Jugendfreund König Llane Wrynn von Sturmwind als Hofmagier. Doch der finstere Geist in seinem Inneren zersetzte langsam seinen Verstand. Im Bestreben, Verwüstung zu entfesseln, nahm Medivh über die Sterne hinweg Kontakt mit dem Hexenmeister Gul'dan und dem Schattenrat auf. Gemeinsam bündelten sie ungeheure Magie, um das Dunkle Portal aufzureißen, wodurch die Horde über die Östlichen Königreiche hereinbrach und der Erste Krieg entfesselt wurde. Schließlich wurde Medivh in seinem Turm von seinem engsten Freund Anduin Lothar und seinem Lehrling Khadgar erschlagen."},{t="Die Erlösung des Propheten",b="Durch seinen irdischen Tod von Sargeras befreit, kehrte Medivh von jenseits des Todes zurück, um seine Verbrechen zu sühnen. Während des Dritten Krieges gab er sich als rätselhafter, in einen Rabenmantel gehüllter Prophet aus und flüsterte König Terenas Menethil sowie Kriegshäuptling Thrall Warnungen vor der Rückkehr der Brennenden Legion zu. Obwohl Lordaeron seine Bitten ignorierte, führte er Thralls Horde und Jaina Prachtmeers Flüchtlinge über das große Meer nach Kalimdor und vereinte Orks, Menschen und Nachtelfen für den entscheidenden Kampf am Hyjal, ehe er zur Legende verblasste."}},faq={{q="Wer war Medivh?",a="Medivh war der letzte menschliche Wächter von Tirisfal, ausgestattet mit immenser arkaner Macht, um Azeroth zu beschützen. Er war der Sohn von Magna Aegwynn und der Drahtzieher hinter der Öffnung des Dunklen Portals.",al={"wer ist medivh","medivh geschichte","der letzte wächter"}},{q="Warum öffnete Medivh das Dunkle Portal?",a="Medivh war bereits vor seiner Geburt vom Geist des Dunklen Titanen Sargeras besessen. Unter diesem bösartigen Einfluss handelte er einen Pakt mit dem Hexenmeister Gul'dan aus: Er bot den Standort des Grabmals von Sargeras im Austausch dafür, dass die Horde in Azeroth einfiel, um den sterblichen Reichen den Untergang zu bringen.",al={"warum verriet medivh sturmwind","medivh dunkles portal","warum orks geholt"}},{q="Wer tötete Medivh?",a="Während des Ersten Krieges wurde Medivh in Karazhan von seinem engen Freund Anduin Lothar, seinem Lehrling Khadgar und der Halborc-Attentäterin Garona gestellt. Khadgar durchstieß Medivhs Herz und Lothar trennte seinen Kopf ab, was sein Leben beendete und den Geist von Sargeras zurück in den Nether verbannte.",al={"wie starb medivh","wer tötete den wächter","medivh tod"}},{q="Wie war Medivhs Beziehung zum Königshaus von Sturmwind?",a="Medivh wuchs an der Seite von Prinz Llane Wrynn und Anduin Lothar am königlichen Hof von Sturmwind auf. Das Trio kämpfte in seiner Jugend Seite an Seite gegen die Gurubashitrolle, und König Llane vertraute Medivh vollkommen, was seinen schließlichen Verrat für das Königreich umso verheerender machte.",al={"medivh und llane","war medivh mit lothar befreundet"}},{q="Lebt Medivh noch?",a="Nachdem er die sterblichen Völker in der Schlacht um den Hyjal zum Sieg über Archimonde geführt hatte, zog Medivh fort, um seinen Platz unter den Legenden der Vergangenheit einzunehmen. Sein Verbleib ist seither unbekannt.",al={"wo ist medivh jetzt","ist der prophet medivh","medivh status"}},{q="Was ist Karazhan?",a="Karazhan ist ein Turm, der auf einer mächtigen Kreuzung von Ley-Linien im Gebirgspass der Totenwinde errichtet wurde. Ursprünglich von Aegwynn erbaut und später von Medivh geerbt, wurde der Turm nach dem Fall des Wächters von arkanen und dämonischen Energien schwer verzerrt und bleibt eine heimgesuchte Ruine.",al={"medivh turm","was geschah mit karazhan"}}},fx={["2cdc20e2"]={q="Was bedeutet der Name Medivh?",a="Medivh bedeutet „Hüter der Geheimnisse“ in Thalassisch, der Sprache der Hochelfen. Der Name wurde ihm bei der Geburt von seiner Mutter Aegwynn gegeben und erwies sich als erschreckend passend für einen Wächter, der sowohl die grenzenlose Macht von Tirisfal als auch die heimtückische Verderbnis von Sargeras in seiner Seele verbarg.",al={"was bedeutet medivh","bedeutung des namens medivh","bedeutung von medivh"}}},fp="6,299,17.469.0,20.596.0,24.506.1,15.190.0,36.274.0,18.276.0,56.263.0,22.183.1,17.269.0"}
P.entries["topic:mor-ladim"] = {n="Mor'Ladim",s="Mor'Ladim ist ein gefährlicher, rachsüchtiger Skelettkrieger, der über das Gelände des Friedhofs von Rabenflucht im Dämmerwald streift. Einst der edle Ritter Morgan Ladimore, verfiel er tiefem Kummer und Wahnsinn, als er den Verlust seiner Familie entdeckte, und erhob sich im Untod, um jeden niederzumetzeln, der seinen Weg kreuzt.",h="Mor'Ladim ist ein gefährlicher, rachsüchtiger Skelettkrieger, der über das Gelände des Friedhofs von...",kw={"althea schwarzhaupt","archeus","dämmerwald","groß-burg","lys ladimore","mor'ladim","morgan ladimore","rabenflucht"},ang={["class:Paladin"]="Morgan Ladimore war einst ein ehrenhafter Krieger des Lichts, der an der Seite von Uther der Lichtbringer kämpfte. Sein Fall verdeutlicht die schreckliche Gefahr, wenn Kummer und Zorn heilige Schwüre überschatten.",["faction:Alliance"]="Der tragische Untergang von Morgan Ladimore dient als düstere Mahnung daran, wie tief der Dritte Krieg die südlichen Königreiche wie Sturmwind erschütterte und erfahrene Soldaten zu zerstörten Familien zurückkehren ließ."},sec={{t="Ein Ritter der Silbernen Hand",b="Bevor er zum Schrecken von Rabenflucht wurde, lebte Mor'Ladim als Morgan Ladimore, ein ergebener Ritter und Beschützer der Hilflosen aus Groß-Burg—dem Ort, der heute als Dunkelhain bekannt ist. Mit achtzehn Jahren heiratete er seine Frau Lys und zog mit ihr drei Kinder in Frieden groß, bis der Krieg ihn nach Norden rief. Morgan zog während des Dritten Krieges an der Seite von Uther der Lichtbringer nach Lordaeron und wurde Zeuge des Untergangs der Ritter der Silbernen Hand, der Ausbreitung von Kel'Thuzads Seuche und des tragischen Todes von Uther selbst."},{t="Der Fall von Morgan Ladimore",b="Als Morgan nach dem Krieg heimkehrte, fand er den Dämmerwald von Finsternis verzerrt und sein Gehöft zerstört vor. Zum Friedhof von Rabenflucht getrieben, suchte er zwischen den Grabsteinen, bis er die Gräber von Lys und zwei ihrer Kinder entdeckte. Von Trauer und Zorn überwältigt, schlug Morgan blindlings auf die Grabsteine ein. Als Friedhofswärter versuchten, ihn zu beruhigen, metzelte der Ritter sie in rasender Wut nieder. Als sein Verstand zurückkehrte und er über seine abscheuliche Tat entsetzt war, stieß sich Morgan die eigene Klinge ins Herz. Beschämt begruben die Dorfbewohner seinen Leichnam in einer unmarkierten, abgelegenen Ecke des Friedhofs."},{t="Die Geißel von Rabenflucht",b="Das Begräbnis brachte Morgan keinen Frieden. Gebunden an die schwere Schuld unschuldigen Blutes und erstickenden Kummer, erhoben sich seine verdorbenen Überreste als gewaltiger skelettartiger Wiedergänger aus der Erde. Reisende und Mitglieder der Nachtwache nannten ihn Mor'Ladim und lernten schnell, seinen Namen zu fürchten. Bewaffnet mit seiner uralten Klinge Archeus patrouilliert die geistlose Erscheinung zwischen den nebelverhangenen Gräbern und streckt sowohl Bestien als auch unachtsame Abenteurer nieder, die sich seiner Ruhestätte zu sehr nähern."}},faq={{q="Wer war Mor'Ladim zu Lebzeiten?",a="Mor'Ladim war ursprünglich Morgan Ladimore, ein ehrenhafter Paladin und Ritter aus Groß-Burg, der während des Dritten Krieges in Lordaeron an der Seite von Uther der Lichtbringer kämpfte.",al={"wer ist morladim","morladim hintergrundgeschichte","morgan ladimore geschichte","wer war morladim"}},{q="Warum ist Mor'Ladim feindselig?",a="Morgan verfiel dem Wahnsinn vor Schmerz, als er die Gräber seiner Familie entdeckte. Nachdem er unschuldige Friedhofswärter niedergemetzelt und sich selbst das Leben genommen hatte, wurde seine Seele von Schuld und Qual gefangen gehalten, was seinen Körper als mörderische untote Bestie wiedererweckte.",al={"warum greift morladim an","warum ist er wütend","morladim wahnsinn"}},{q="Wo streift Mor'Ladim umher?",a="Er patrouilliert auf den weitläufigen Wegen und Mausoleen des Friedhofs von Rabenflucht im westlichen Dämmerwald und überrascht Reisende aufgrund seiner weiten Patrouillenroute häufig unvorbereitet.",al={"morladim route","wo morladim finden","morladim aufenthaltsort"}},{q="Starb die gesamte Familie von Morgan Ladimore?",a="Nein. Während seine Frau Lys und zwei seiner Kinder umkamen, überlebte ein drittes Kind den Niedergang des Dämmerwalds—ein Umstand, den Morgan in seiner blinden Verzweiflung auf dem Friedhof völlig übersah.",al={"überlebte familie von morgan ladimore","morgan ladimore tochter","wer überlebte in familie ladimore"}},{q="Welche Waffe trägt Mor'Ladim?",a="Mor'Ladim führt Archeus, eine edle Klinge, die ihm zeit seines Lebens als Ritter treu diente, bevor sie im Untod zu einem Werkzeug des Schlachtens wurde.",al={"morladim schwert","archeus schwert","welches schwert nutzt morladim"}},{q="Wer will Mor'Ladim vernichten?",a="Kommandantin Althea Schwarzhaupt und Die Nachtwache von Dunkelhain streben aktiv seine Vernichtung an, um Patrouillen und Reisende vor seinen unerbittlichen Hinterhalten im westlichen Dämmerwald zu schützen.",al={"wer will morladim tot sehen","nachtwache morladim","althea schwarzhaupt morladim"}}},fx={fdd06828={q="Was ist die Geschichte von Mor'Ladim?",a="Mor'Ladim war einst Sir Morgan Ladimore, ein edler Ritter aus dem Dämmerwald, der unter Uther der Lichtbringer nach Norden marschierte, um gegen die Geißel in Lordaeron zu kämpfen. Als er Jahre später nach Hause zurückkehrte, fand er seine Heimat als Dämmerwald verderbt und sein Haus zerstört vor. Bei der Suche auf dem Friedhof von Rabenflucht entdeckte er die Gräber seiner Frau und zweier seiner Kinder. Überwältigt von Trauer und Wahnsinn, schlachtete er die Friedhofswärter ab, die versuchten, ihn zu beruhigen. Entsetzt über seine Taten, als er wieder zu Sinnen kam, nahm Morgan sich das Leben. Kurz nach seiner hastigen Bestattung erweckten ihn dunkle Energien als rastlose Monstrosität wieder.",al={"hintergrundgeschichte von mor'ladim","lore von morgan ladimore","wie starb mor'ladim"}},aff5d09b={q="Wie erhielt Mor'Ladim seinen Namen?",a="Sein monströser Beiname ist eine korrumpierte Ableitung seines lebendigen Namens, Morgan Ladimore. Als der Ritter aus seinem ungeweihten Grab als halbintelligentes untotes Grauen auferstand, wurde der gequälte Rest seiner Identität zu dem Schrecken verzerrt, den die Einheimischen heute als Mor'Ladim fürchten.",al={"warum wird er mor'ladim genannt","namensursprung von mor'ladim","bedeutung des namens mor'ladim"}}},fp="9,293,27.494.0,27.585.1,25.457.0,26.170.1,25.238.1,26.161.0,40.171.1,37.156.1,30.172.0"}
P.entries["topic:muradin-bronzebeard"] = {n="Muradin Bronzebeard",s="Muradin Bronzebeard war der Bruder von König Magni Bronzebart und Brann Bronzebeard sowie ein renommierter Krieger, Diplomat und Mitbegründer der Forscherliga. Er wurde in Khaz Modan und Lordaeron gleichermaßen verehrt und man glaubt, dass er in den gefrorenen Weiten von Nordend starb, als Prinz Arthas Menethil die verfluchte Runenklinge Frostgram an sich nahm.",h="Muradin Bronzebeard war der Bruder von König Magni Bronzebart und Brann Bronzebeard sowie ein renommierter...",kw={"arthas","bronzebart","forscherliga","frostgram","eisenschmiede","magni","muradin","nordend"},ang={["class:Warrior"]="Muradin galt als einer der herausragendsten Duellanten und Waffenmeister der Zwerge seiner Ära und hatte Prinz Arthas Menethil persönlich in der Kunst der Klinge unterwiesen.",["faction:Alliance"]="Muradin schmiedete die Bande der Kameradschaft zwischen Eisenschmiede und den nördlichen Menschenkönigreichen und zählte zu den grundlegenden Helden der Allianz.",["race:Dwarf"]="Die Zwerge von Eisenschmiede erinnern sich an Muradin als Vorbild ihres Volkes – tapfer, treu ergeben und getrieben von einer unstillbaren Neugier auf die Geschichte ihrer Schöpfer."},sec={{t="Ein Bruder und Botschafter",b="Muradin kämpfte während des Zweiten Krieges mit Auszeichnung und fungierte als wichtiges Bindeglied zwischen den Berghallen von Khaz Modan und der Allianz von Lordaeron. Er half dabei, Eisenschmiede während der Belagerung durch die Horde zu halten, und marschierte an der Seite der Streitkräfte der Allianz den gesamten Weg über die Schwarzfelsspitze bis zum Dunklen Portal. In den darauf folgenden friedlichen Jahren ließ sich Muradin als offizieller Botschafter von Eisenschmiede in der Hauptstadt nieder. Heiter und doch furchterregend wurde er zu einer festen Größe am Hof, freundete sich eng mit König Terenas Menethil an und machte es sich zur Aufgabe, den jungen Prinzen Arthas in der Schwertkunst und im Kampf zu unterweisen."},{t="Die Forscherliga und Nordend",b="Jenseits von Politik und Krieg besaß Muradin eine rastlose Neugier. Zusammen mit seinen Brüdern half er beim Aufbau der Zwergen-Forscherliga, die sich der Entdeckung verlorener Titanenrelikte und der Erforschung der entlegensten Winkel der Welt verschrieben hatte. Er verliebte sich in den öden, windgepeitschten Kontinent Nordend und unternahm häufige Reisen in den Norden, um antike Architektur zu skizzieren und seine wilden Bewohner zu dokumentieren. Es waren die rauen Geheimnisse Nordends, die ihn schließlich zu seiner letzten Expedition führten, um Wissen, Relikte und die geraunte Legende einer vergessenen Runenklinge aufzuspüren."},{t="Das Ergreifen von Frostgram",b="Als Prinz Arthas in Nordend eintraf, besessen davon, den Schreckenslord Mal'Ganis zur Strecke zu bringen, traf er wieder auf Muradin und heuerte dessen Zwergenexpedition an. Arthas suchte die Macht von Frostgram, um das Blatt zu wenden, und ignorierte Muradins wachsende Bestürzung, als der Prinz seine eigenen Mercenaries verriet und jede Ehre aufgab. Am Altar von Frostgram las Muradin die auf dem eisigen Sockel eingravierte Warnung und flehte seinen ehemaligen Schüler an umzukehren. Arthas weigerte sich. Als der Prinz die Runenklinge ergriff, streckte die Explosion unheiligen Eises Muradin nieder und ließ ihn scheinbar tot auf dem Höhlenboden zurück."}},faq={{q="Wer war Muradin Bronzebeard?",a="Muradin Bronzebeard war der mittlere Bruder von König Magni Bronzebart und dem Forscher Brann. Er war ein erfahrener Held des Zweiten Krieges, Eisenschmiedes Botschafter in Lordaeron und Gründungsmitglied der Forscherliga.",al={"wer ist muradin","muradin geschichte","magnis bruder muradin"}},{q="Was geschah mit Muradin in Nordend?",a="Muradin begleitete Prinz Arthas zu der Höhle, in der sich Frostgram befand. Als Arthas Muradins Warnungen ignorierte und das eisige Gefängnis der Runenklinge zerschmetterte, traf ein explodierender Splitter verzauberten Eises Muradin und tötete ihn scheinbar auf der Stelle. Arthas ließ seinen Leichnam zurück und nahm die Klinge an sich.",al={"wie starb muradin","muradins tod","tötete arthas muradin"}},{q="Was für eine Beziehung hatte Muradin zu Prinz Arthas?",a="Während er als Eisenschmiedes Botschafter in der Hauptstadt diente, nahm Muradin Arthas unter seine Fittiche. Er bildete den jungen Prinzen im Klingen- und Schwertkampf aus und erlebte viele Abenteuer mit ihm, wobei er Arthas fast wie einen Ziehsohn oder geliebten Neffen betrachtete, bis zu Arthas' finsterem Abstieg in Nordend.",al={"kannte muradin arthas","muradin lehrer von arthas","muradin und arthas"}},{q="Welche Rolle spielte Muradin im Zweiten Krieg?",a="Muradin diente als Verbindungsmann der Allianz zwischen Lordaeron und Khaz Modan. Er verteidigte Eisenschmiede während der Belagerung durch die Horde und zog dann mit der vereinten Streitmacht der Allianz nach Süden, um an der Schwarzfelsspitze und am Dunklen Portal zu kämpfen.",al={"muradin zweiter krieg","muradins schlachten","kämpfte muradin gegen die horde"}},{q="Warum ging Muradin überhaupt nach Nordend?",a="Als Gründer der Forscherliga war Muradin zutiefst fasziniert von der Archäologie und den uralten Ruinen Nordends. Er kehrte im Rahmen einer Expedition dorthin zurück, um vergessene Geschichte aufzudecken und nach Relikten zu suchen, was ihn letztlich auf die Spur von Frostgram führte.",al={"warum war muradin in nordend","muradin expedition","wonach suchte muradin"}},{q="Wie reagierte König Magni auf Muradins Tod?",a="König Magni und der gesamte Bronzebart-Klan waren durch Muradins Verlust am Boden zerstört. Muradins scheinbarer Tod zerschnitt das einst herzliche Band zwischen Eisenschmiede und Prinz Arthas und verwandelte die Trauer in bittere Wut gegen die Geißel.",al={"magni reaktion auf muradin","trauer um muradin in eisenschmiede"}}},fx={["3bcb591a"]={q="Mit wem war Muradin Bronzebeard verbündet?",a="Muradin war der Allianz von Lordaeron und seinem eigenen Volk von Khaz Modan gegenüber erbittert loyal. Als Prinz des Bronzebart-Clans unterstand er direkt seinem Bruder, König Magni Bronzebart, während er als offizieller Botschafter von Eisenschmiede am königlichen Hof von Lordaeron diente. Dort entwickelte er enge Beziehungen zu König Terenas Menethil II. und Prinz Arthas. Muradin half auch bei der Gründung der Forscherliga der Zwerge und führte unerschrockene Teams von zwergischen Archäologen und Abenteurern unter dem Banner von Eisenschmiede in die entlegensten Winkel der Welt.",al={"verbündete von muradin bronzebart","für wen arbeitete muradin","fraktionen von muradin"}}},fp="19,345,24.597.0,35.562.0,27.596.1,28.218.0,38.295.0,51.278.0,42.218.0,51.255.0,44.218.0"}
P.entries["topic:murloc"] = {n="Murloc",s="Murlocs sind amphibische, zweibeinige Humanoide, berühmt für ihre gurgelnden Kampfschreie, territorialen Küstendörfer und plötzlichen Schwarmtaktiken. Obwohl sie historisch in den Tiefen des Ozeans lebten, sind sie stetig entlang der Küsten, Seen und Flüsse von Azeroth landeinwärts gezogen und handeln mit weit größerer Koordination und Gerissenheit, als ihr primitives Aussehen vermuten lässt.",h="Murlocs sind amphibische, zweibeinige Humanoide, berühmt für ihre gurgelnden Kampfschreie, territorialen...",kw={"brann bronzebeard","küsten-","flosse","mur'gul","murloc","rwlrwlrwl","küstenlinie","kaulquappe"},ang={["class:Shaman"]="Murloc-Mystiker besitzen eine angeborene, wenn auch rohe Verbindung zu Wasser- und Erdelementaren und lenken die örtlichen Geister, um ihre Küstendörfer zu stärken.",["faction:Alliance"]="Siedler in ganz Westfall, Dunkelküste und Seenhain müssen häufig erleben, wie ihre Schifffahrt, Höfe und Docks von vordringenden Murloc-Stämmen belagert werden.",["race:Orc"]="Thralls Krieger kämpften gegen Murlocs, als sie die Dunkelspeer auf See retteten, und lernten früh, dass ihr albernes Auftreten wilde Brutalität verbirgt.",["race:Troll"]="Der Stamm der Dunkelspeere teilt eine bittere Geschichte mit Murlocs, da sie Gefangennahme und rituelle Opferung durch Küstenstämme erleiden mussten, bevor sie sich Kriegshäuptling Thrall anschlossen."},sec={{t="Kreaturen der Untiefen",b="Murlocs hausen in dicht besiedelten Siedlungen entlang von Küstenlinien, Flussufern und Süßwasserseen. Mit einer durchschnittlichen Größe von rund vier Fuß besitzen sie knollenförmige, schleimbedeckte Körper, breite Mäuler voller scharfer Fänge und eine scharfe Sehkraft, die pechschwarzes Wasser durchdringen kann. Während Individuen selten weit abseits ihrer Artgenossen umherwandern, bedeutet die Begegnung mit einem einzelnen Murloc unweigerlich, dass ein Dutzend weiterer knapp unter der Oberfläche lauert. Sie verlassen sich auf überwältigende Zahlen und scharfe, primitive Waffen."},{t="Der Vormarsch ins Landesinnere",b="Obwohl uralte Abstammungslinien darauf hindeuten, dass Murlocs bereits vor den ersten geschichtlichen Aufzeichnungen unter den Wellen existierten, ist ihr weit verbreitetes Vordringen auf die Landmassen von Lordaeron und Kalimdor relativ neu. Historiker bemerken, dass diese Binnenwanderung verdächtig mit dem Wiederauftauchen der schlangenartigen Naga aus den Meerestiefen zusammenfiel. Einige Stämme scheinen Tiefsee-Monstrositäten anzubeten, die in den ozeanischen Tiefen warten. Ob sie vor dunkleren Schrecken fliehen oder die Welt auf das Erwachen ihrer Herren vorbereiten – ihre koordinierte Bewegung in Süßgewässer stellt eine wachsende Bedrohung dar."},{t="Ein verborgener Intellekt",b="Da ihre verstümmelte Sprache für Außenstehende wie sinnloses Blubbern klingt, tun viele Murlocs als bloßes wildes Ungeziefer ab. Doch ihre koordinierten Hinterhalte, ihre Beherrschung von Erd- und Wassermagie und ihre gemeinschaftlichen Strukturen deuten auf einen schärferen Verstand hin. Der renommierte Forscher Brann Bronzebeard hat die Vermutung geäußert, dass Murlocs weitaus klüger sind, als die zivilisierten Völker ahnen, und ihre Gerissenheit absichtlich verbergen. Ihr Einfluss auf die Weltgeschichte ist unbestreitbar: Es war ein Murloc-Überfall auf den Stamm der Dunkelspeere, der Thrall zum Eingreifen bewegte und das Bündnis zwischen den Orcs und Trollen schmiedete, aus dem die moderne Horde hervorging."}},faq={{q="Warum greifen Murlocs alle auf einmal an?",a="Murlocs kämpfen selten allein. Sie leben in eng verbundenen, überfüllten Siedlungen und reagieren in Gruppen auf Eindringlinge, indem sie Feinde mit überwältigenden Zahlen überrennen.",al={"murloc-schwarmbildung","warum rotten sich murlocs zusammen","murloc-aggro"}},{q="Sind Murlocs tatsächlich intelligent?",a="Ja, weitaus mehr, als ihr komisches Aussehen vermuten lässt. Während ihr kehliger, gurgelnder Dialekt für die meisten unverständlich ist, fertigen Murlocs Waffen, organisieren strategische Hinterhalte und wirken elementare Wasser- und Erdmagie. Gelehrte wie Brann Bronzebeard glauben, dass Murlocs Außenstehende ihren Intellekt absichtlich unterschätzen lassen.",al={"sind murlocs klug","murloc-intelligenz","können murlocs denken"}},{q="Warum ziehen Murlocs vom Meer ins Landesinnere?",a="Ursprünglich Geschöpfe des Meeresbodens, sind Murlocs stetig in Süßwasserseen und Flussbetten vorgedrungen. Historiker vermuten, dass diese Wanderung durch das Wiedererstarken der Naga ausgelöst wurde oder durch im Abgrund schlummernde Tiefsee-Wesenheiten, deren Erwachen den Murlocs befiehlt, das Land zu sichern.",al={"warum sind murlocs an land","murloc-wanderung","warum gibt es überall murlocs"}},{q="Wie halfen Murlocs bei der Gründung der Horde?",a="Während des Dritten Krieges überfiel ein Stamm von Murlocs im Dienste der Meerhexe Zar'jira die Dunkelspeer auf ihrer Inselheimat. Kriegshäuptling Thrall und seine Orc-Krieger kämpften an der Seite von Sen'jin zur Verteidigung der Trolle. Diese Schlacht schmiedete das unzerbrechliche Band zwischen den Orcs und dem Stamm der Dunkelspeere und legte den Grundstein für die moderne Horde.",al={"murloc horde ursprung","murlocs und dunkelspeer","thrall murloc-insel"}},{q="Was sind Mur'gul?",a="Mur'gul sind Murlocs, denen man während des Dritten Krieges begegnete. Trotz ihres seltsamen Aussehens und Namens sind sie lebende Kreaturen.",al={"mur'gul","warcraft iii murlocs","murgul-identität"}},{q="Was ist das für ein ikonisches Geräusch, das Murlocs machen?",a="Wenn sie Beute angreifen oder Alarm schlagen, stoßen Murlocs ein lautes, feuchtes, oszillierendes Gurgeln aus (oft als „Aaaaaughibbrgubugbugrguburgle“ oder „RwlRwlRwlRwl“ wiedergegeben). Es dient sowohl als aggressive psychologische Waffe als auch als sofortiger Ruf an ihr Rudel, zusammenzuströmen.",al={"murloc-geräusch","murloc-kampfschrei","rwlrwlrwl"}}},fx={["87c77fd7"]={q="Was sind Murlocs?",a="Murlocs sind eine zweibeinige, amphibische Rasse, die man an Küsten, Seen und Flüssen überall auf Azeroth findet. Mit einer durchschnittlichen Körpergröße von etwa vier Fuß besitzen sie bauchige Körper, schleimige Haut, beklaute Finger und Münder, die mit messerscharfen Reißzähnen besetzt sind. Obwohl sie aufgrund ihrer gurgelnden Sprache oft als primitive Fischbestien abgetan werden, errichten sie gemeinschaftliche Siedlungen, führen handgefertigte Waffen und kanalisieren Erd- und Wassermagie.",al={"was ist ein murloc","murloc-rasse","wer sind die murlocs"}},["033f2da0"]={q="Warum sind Murlocs Reisenden gegenüber feindselig?",a="Murlocs sind zutiefst isolierte Kreaturen, die die Sterblichen des Festlandes meiden und fast keine Toleranz für andere Rassen zeigen. Sie verteidigen ihre Nistplätze, Eierverstecke und Nahrungsvorräte erbittert gegen Außenstehende. In Verbindung mit ihrer Angewohnheit, in dicht gedrängten Lagern zu leben, wird jeder Eindringling, der sich in die Nähe ihrer Küstensiedlungen wagt, schnell vom gesamten Stamm umschwärmt und vertrieben.",al={"warum greifen murlocs an","murloc-aggression","warum sind murlocs aggressiv"}},["630a3c8a"]={q="Woher stammen Murlocs?",a="Obwohl sie erst kürzlich in die Binnengewässer von Azeroth eingedrungen sind, sind Murlocs ein altes Volk. Ihre frühen Vorfahren bewohnten die abgründigen Tiefen der Weltmeere, lange bevor die Bewohner der Oberfläche überhaupt von ihnen wussten, und waren möglicherweise älter als sogar die Trolle. In den letzten Jahren sind sie stetig aus dem ozeanischen Abgrund ausgewandert und haben sich an Süßwasserläufe auf den Kontinenten angepasst.",al={"ursprung der murlocs","geschichte der murlocs","woher stammen murlocs"}},b6922777={q="Mit wem sind Murlocs verbündet?",a="Murlocs isolieren sich im Allgemeinen, aber Gelehrte vermuten, dass ihr Auftauchen mit dunkleren Mächten des Ozeans verbunden ist. Einige Stämme verehren Seehexen oder möglicherweise schlummernde Tiefsee-Monstrositäten, die in den ozeanischen Tiefen warten, und führen Rituale in ihrem Namen durch.",al={"für wen arbeiten murlocs","meister der murlocs","verbündete der murlocs"}}},fp="6,362,25.481.0,16.568.0,18.596.0,34.152.0,33.327.0,43.287.0,36.328.0,17.123.0,39.259.0"}
